import {
  defaultNetworkService,
  INetworkService,
  TR_CODES,
} from '@mfe/core';

export interface CustomerProfileDTO {
  cifNumber: string;
  nric: string;
  fullName: string;
  gender: 'M' | 'F';
  dateOfBirth: string;
  phoneNumber: string;
  cbsSyncStatus: 'SYNCED' | 'PENDING' | 'FAILED';
  address: {
    province: string;
    district: string;
    commune: string;
    village?: string;
  };
}

export interface ICustomerService {
  getCustomerByNric(nric: string, useMock?: boolean): Promise<CustomerProfileDTO | null>;
  registerCustomer(
    profile: Omit<CustomerProfileDTO, 'cifNumber' | 'cbsSyncStatus'>,
    useMock?: boolean
  ): Promise<CustomerProfileDTO>;
  syncWithCbs(cifNumber: string, useMock?: boolean): Promise<boolean>;
}

export class CustomerService implements ICustomerService {
  private static instance: CustomerService;
  private mockCifStore = new Map<string, CustomerProfileDTO>();
  private networkService: INetworkService;
  private useMock: boolean;

  constructor(
    networkService: INetworkService = defaultNetworkService,
    useMock: boolean = true
  ) {
    this.networkService = networkService;
    this.useMock = useMock;
    this.mockCifStore.set('012345678901', {
      cifNumber: 'CIF-982104',
      nric: '012345678901',
      fullName: 'Sokha Chan',
      gender: 'M',
      dateOfBirth: '1995-06-15',
      phoneNumber: '0912345678',
      cbsSyncStatus: 'SYNCED',
      address: {
        province: 'Phnom Penh',
        district: 'Chamkar Mon',
        commune: 'Tonle Bassac',
        village: 'Village 1',
      },
    });
  }

  public static getInstance(): CustomerService {
    if (!CustomerService.instance) {
      CustomerService.instance = new CustomerService();
    }
    return CustomerService.instance;
  }

  async getCustomerByNric(
    nric: string,
    useMock: boolean = this.useMock
  ): Promise<CustomerProfileDTO | null> {
    if (this.mockCifStore.has(nric)) {
      return this.mockCifStore.get(nric) || null;
    }

    const res = await this.networkService.request<{ items?: CustomerProfileDTO[] } | CustomerProfileDTO>({
      trCode: TR_CODES.CUSTOMER_INQUIRY,
      payload: { nric },
      useMock,
    });

    if (res.result && res.body) {
      const bodyAny = res.body as any;
      const items: CustomerProfileDTO[] = Array.isArray(bodyAny)
        ? bodyAny
        : bodyAny.items || (bodyAny.nric ? [bodyAny] : []);
      const match = items.find((c) => c.nric === nric);
      if (match) {
        this.mockCifStore.set(match.nric, match);
        return match;
      }
    }

    return null;
  }

  async registerCustomer(
    profile: Omit<CustomerProfileDTO, 'cifNumber' | 'cbsSyncStatus'>,
    useMock: boolean = this.useMock
  ): Promise<CustomerProfileDTO> {
    await this.networkService.request({
      trCode: TR_CODES.CUSTOMER_REGISTER,
      payload: profile,
      useMock,
    });

    const cif = `CIF-${Math.floor(100000 + Math.random() * 900000)}`;
    const fullProfile: CustomerProfileDTO = {
      ...profile,
      cifNumber: cif,
      cbsSyncStatus: 'SYNCED',
    };
    this.mockCifStore.set(profile.nric, fullProfile);
    return fullProfile;
  }

  async syncWithCbs(
    cifNumber: string,
    useMock: boolean = this.useMock
  ): Promise<boolean> {
    await this.networkService.request({
      trCode: TR_CODES.CUSTOMER_CBS_SYNC,
      payload: { cifNumber },
      useMock,
    });

    for (const customer of this.mockCifStore.values()) {
      if (customer.cifNumber === cifNumber) {
        customer.cbsSyncStatus = 'SYNCED';
        return true;
      }
    }
    return false;
  }
}
