import { useEffect } from 'react';
import {
  firebasePushNotificationService,
  DeviceLoginAttemptPayload,
} from '@mfe/core/services/FirebasePushNotificationService';
import { DialogUtil } from '@mfe/ui-components/modals/DialogUtil';
import { appLogger } from '@mfe/core/logger/AppLogger';

export interface UseDeviceLoginPushSecurityOptions {
  userId?: string;
  autoInitializePush?: boolean;
}

/**
 * Hook to initialize Firebase push notification listener and automatically
 * present the "Another device is trying to log in to your account" confirmation modal.
 */
export function useDeviceLoginPushSecurity({
  userId,
  autoInitializePush = true,
}: UseDeviceLoginPushSecurityOptions = {}) {
  useEffect(() => {
    if (autoInitializePush) {
      firebasePushNotificationService.initializePushToken(userId);
    }

    const unsubscribe = firebasePushNotificationService.onAnotherDeviceLoginAttempt(
      async (attempt: DeviceLoginAttemptPayload) => {
        appLogger.info('useDeviceLoginPushSecurity', 'Device login attempt prompt triggered', attempt);

        const isItMe = await DialogUtil.anotherDeviceLogin({
          deviceName: attempt.deviceName,
          location: attempt.location,
          timestamp: attempt.timestamp,
        });

        if (isItMe) {
          appLogger.info('useDeviceLoginPushSecurity', "User selected 'It's me'");
          await firebasePushNotificationService.submitDeviceLoginDecision(attempt.attemptId, 'APPROVED');
        } else {
          appLogger.warn('useDeviceLoginPushSecurity', "User selected 'It's not me'");
          await firebasePushNotificationService.submitDeviceLoginDecision(attempt.attemptId, 'REJECTED');
        }
      }
    );

    return () => {
      unsubscribe();
    };
  }, [userId, autoInitializePush]);
}
