import React from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
  StyleProp,
} from 'react-native';
import { SelectionItem } from './SelectionItem';

export interface SelectionOption<T = string> {
  label: string;
  value: T;
  subtitle?: string;
  badge?: string;
  disabled?: boolean;
}

export interface SelectionGroupProps<T = string> {
  /** Optional group heading */
  title?: string;
  /** Options list */
  options: SelectionOption<T>[];
  /** Currently selected value (if multiSelect is false) */
  selectedValue?: T;
  /** Currently selected values array (if multiSelect is true) */
  selectedValues?: T[];
  /** Whether multiple items can be selected */
  multiSelect?: boolean;
  /** Single selection callback */
  onSelect?: (value: T) => void;
  /** Multi selection callback */
  onChange?: (values: T[]) => void;
  /** UI presentation type: 'radio', 'checkbox', or 'pill' */
  type?: 'radio' | 'checkbox' | 'pill';
  /** Columns layout: 1 for stacked list, 2 for grid, 'wrap' for chips/pills */
  layout?: 'column' | 'grid-2' | 'wrap';
  /** Primary accent color */
  activeColor?: string;
  /** Filter icon prefix (funnel) */
  showFilterIcon?: boolean;
  /** Clear all callback */
  onClear?: () => void;
  /** Container custom style */
  style?: StyleProp<ViewStyle>;
  /** Optional testID */
  testID?: string;
}

export const SelectionGroup = <T extends string | number>({
  title,
  options,
  selectedValue,
  selectedValues = [],
  multiSelect = false,
  onSelect,
  onChange,
  type,
  layout = 'column',
  activeColor = '#2563EB',
  showFilterIcon = false,
  onClear,
  style,
  testID = 'selection-group',
}: SelectionGroupProps<T>) => {
  // Infer indicator type if not specified
  const effectiveType = type || (multiSelect ? 'checkbox' : 'radio');

  const handleItemPress = (value: T) => {
    if (multiSelect) {
      const isChecked = selectedValues.includes(value);
      const newValues = isChecked
        ? selectedValues.filter((v) => v !== value)
        : [...selectedValues, value];
      onChange?.(newValues);
    } else {
      onSelect?.(value);
    }
  };

  const isSelected = (value: T) => {
    if (multiSelect) {
      return selectedValues.includes(value);
    }
    return selectedValue === value;
  };

  return (
    <View testID={testID} style={[styles.container, style]}>
      {title ? (
        <View style={styles.headerRow}>
          <View style={styles.titleContainer}>
            {showFilterIcon ? (
              <Text testID={`${testID}-funnel`} style={styles.funnelIcon}>
                🔻
              </Text>
            ) : null}
            <Text testID={`${testID}-title`} style={styles.titleText}>
              {title}
            </Text>
          </View>

          {onClear ? (
            <TouchableOpacity
              testID={`${testID}-clear-btn`}
              style={styles.clearBtn}
              onPress={onClear}
              hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
            >
              <Text style={styles.clearBtnText}>✕</Text>
            </TouchableOpacity>
          ) : null}
        </View>
      ) : null}

      <View
        style={[
          styles.optionsContainer,
          layout === 'grid-2' && styles.grid2Container,
          layout === 'wrap' && styles.wrapContainer,
          layout === 'column' && styles.columnContainer,
        ]}
      >
        {options.map((opt, idx) => (
          <View
            key={`selection-opt-${String(opt.value)}-${idx}`}
            style={[
              layout === 'grid-2' && styles.grid2Item,
              layout === 'column' && styles.columnItem,
            ]}
          >
            <SelectionItem
              label={opt.label}
              value={opt.value}
              subtitle={opt.subtitle}
              badge={opt.badge}
              disabled={opt.disabled}
              selected={isSelected(opt.value)}
              onSelect={() => handleItemPress(opt.value)}
              type={effectiveType}
              activeColor={activeColor}
              testID={`${testID}-item-${idx}`}
            />
          </View>
        ))}
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    marginVertical: 8,
  },
  headerRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 8,
  },
  titleContainer: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  funnelIcon: {
    fontSize: 16,
    color: '#E7252B',
    marginRight: 8,
  },
  titleText: {
    fontSize: 16,
    fontWeight: '700',
    color: '#111827',
  },
  clearBtn: {
    width: 22,
    height: 22,
    borderRadius: 11,
    backgroundColor: '#E5E7EB',
    justifyContent: 'center',
    alignItems: 'center',
  },
  clearBtnText: {
    fontSize: 12,
    fontWeight: '700',
    color: '#6B7280',
    lineHeight: 14,
  },
  optionsContainer: {
    width: '100%',
  },
  columnContainer: {
    flexDirection: 'column',
  },
  grid2Container: {
    flexDirection: 'row',
    flexWrap: 'wrap',
  },
  wrapContainer: {
    flexDirection: 'row',
    flexWrap: 'wrap',
  },
  grid2Item: {
    width: '50%',
    paddingRight: 6,
  },
  columnItem: {
    width: '100%',
  },
});
