import { useEffect, useRef } from 'react';
import { BackHandler, Platform } from 'react-native';
import { DialogUtil } from '../modals/DialogUtil';
import { useI18n } from '@mfe/core/i18n';

export interface UseExitAppPromptOptions {
  /**
   * Whether the exit prompt hook is active.
   * Typically true on final/root screens where no further back history exists.
   * Default: true
   */
  enabled?: boolean;
  /**
   * Optional custom title for confirmation dialog.
   * If omitted, localized `common.exitAppTitle` will be used.
   */
  title?: string;
  /**
   * Optional custom message for confirmation dialog.
   * If omitted, localized `common.exitAppMessage` will be used.
   */
  message?: string;
  /**
   * Optional custom label for confirm button.
   * If omitted, localized `common.exit` will be used.
   */
  confirmLabel?: string;
  /**
   * Optional custom label for cancel button.
   * If omitted, localized `common.cancel` will be used.
   */
  cancelLabel?: string;
  /**
   * Optional callback invoked right before exiting the app.
   */
  onBeforeExit?: () => void;
}

/**
 * Custom hook to intercept back navigation on root/final screens and show
 * a confirmation dialog asking the user if they want to exit the app.
 *
 * Uses DialogUtil.confirm() to integrate seamlessly with the design system
 * (Figma COM* confirmation dialogs and GlobalModalHost).
 */
export function useExitAppPrompt({
  enabled = true,
  title,
  message,
  confirmLabel,
  cancelLabel,
  onBeforeExit,
}: UseExitAppPromptOptions = {}) {
  const { t } = useI18n();
  const isDialogActiveRef = useRef(false);

  const dialogTitle = title || t?.common?.exitAppTitle || 'Exit Application';
  const dialogMessage = message || t?.common?.exitAppMessage || 'Are you sure you want to exit the application?';
  const dialogConfirmLabel = confirmLabel || t?.common?.exit || 'Exit';
  const dialogCancelLabel = cancelLabel || t?.common?.cancel || 'Cancel';

  useEffect(() => {
    if (!enabled) return;

    const onHardwareBackPress = () => {
      // If confirmation dialog is already open, prevent multiple dialog instances
      if (isDialogActiveRef.current) {
        return true;
      }

      isDialogActiveRef.current = true;

      DialogUtil.confirm({
        title: dialogTitle,
        message: dialogMessage,
        confirmLabel: dialogConfirmLabel,
        cancelLabel: dialogCancelLabel,
        isDestructive: true,
        testID: 'confirm-exit-app-dialog',
      })
        .then((confirmed) => {
          isDialogActiveRef.current = false;
          if (confirmed) {
            if (onBeforeExit) {
              onBeforeExit();
            }
            if (Platform.OS === 'android') {
              BackHandler.exitApp();
            }
          }
        })
        .catch(() => {
          isDialogActiveRef.current = false;
        });

      return true; // Stop default back action / bubble up
    };

    const subscription = BackHandler.addEventListener(
      'hardwareBackPress',
      onHardwareBackPress
    );

    return () => {
      subscription.remove();
    };
  }, [
    enabled,
    dialogTitle,
    dialogMessage,
    dialogConfirmLabel,
    dialogCancelLabel,
    onBeforeExit,
  ]);
}
