import React from 'react';
import {
  View,
  Text,
  Image,
  ImageSourcePropType,
  StyleSheet,
} from 'react-native';
import { AppCard } from '@mfe/ui-components/components/card/AppCard';
import { LanguageOption, SupportedLanguage } from '../../models/LaunchModel';
import { LaunchColors, FontFamilies } from '../../theme/tokens';

export interface LanguageCardProps {
  language: LanguageOption;
  flagIcon?: React.ReactNode;
  flagSource?: ImageSourcePropType;
  isSelected: boolean;
  onSelect: (code: SupportedLanguage) => void;
  testID?: string;
}

export const LanguageCard: React.FC<LanguageCardProps> = ({
  language,
  flagIcon,
  flagSource,
  isSelected,
  onSelect,
  testID,
}) => {
  const cardTestID = testID || `language-option-${language.code}`;

  return (
    <AppCard
      testID={cardTestID}
      elevation="none"
      style={[
        styles.card,
        isSelected && styles.cardSelected,
      ]}
      onPress={() => onSelect(language.code)}
    >
      <View style={styles.contentLeft}>
        {flagIcon ? (
          <View
            testID={`language-flag-${language.code}`}
            style={styles.flagIconContainer}
          >
            {flagIcon}
          </View>
        ) : flagSource ? (
          <Image
            testID={`language-flag-${language.code}`}
            source={flagSource}
            style={styles.flagIcon}
            resizeMode="cover"
          />
        ) : null}

        <Text
          style={[
            styles.label,
            language.code === 'km' && styles.labelKhmer,
            isSelected && styles.labelSelected,
          ]}
        >
          {language.code === 'km' ? 'ភាសាខ្មែរ' : language.name}
        </Text>
      </View>

      {isSelected && (
        <View
          testID={`language-selected-${language.code}`}
          style={styles.checkCircle}
        >
          <Text style={styles.checkmarkIcon}>✓</Text>
        </View>
      )}
    </AppCard>
  );
};

const styles = StyleSheet.create({
  card: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 16,
    paddingVertical: 16,
    borderRadius: 12,
    borderWidth: 1.5,
    borderColor: '#F3F4F6',
    backgroundColor: LaunchColors.white,
  },
  cardSelected: {
    borderColor: LaunchColors.primary,
    backgroundColor: LaunchColors.white,
  },
  contentLeft: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 16,
  },
  flagIconContainer: {
    width: 44,
    height: 32,
    borderRadius: 8,
    overflow: 'hidden',
  },
  flagIcon: {
    width: 44,
    height: 32,
    borderRadius: 8,
  },
  label: {
    fontFamily: FontFamilies.pretendard.bold,
    fontSize: 16,
    fontWeight: '600',
    color: '#1F2937',
  },
  labelKhmer: {
    fontFamily: FontFamilies.hanuman.bold,
    fontSize: 16,
  },
  labelSelected: {
    color: LaunchColors.primary,
  },
  checkCircle: {
    width: 24,
    height: 24,
    borderRadius: 12,
    backgroundColor: LaunchColors.primary,
    alignItems: 'center',
    justifyContent: 'center',
  },
  checkmarkIcon: {
    color: LaunchColors.white,
    fontSize: 13,
    fontWeight: '800',
  },
});

