import React from 'react';

export type AlertType = 'info' | 'success' | 'warning' | 'error';

export interface AlertOptions {
  title?: string;
  message?: string;
  type?: AlertType;
  buttonText?: string;
  dismissible?: boolean;
  maxWidth?: number;
  testID?: string;
  /** Custom scrollable content or node */
  content?: React.ReactNode;
}

export interface ConfirmOptions {
  title?: string;
  message?: string;
  confirmLabel?: string;
  cancelLabel?: string;
  isDestructive?: boolean;
  dismissible?: boolean;
  testID?: string;
  content?: React.ReactNode;
}

export interface BottomSheetOptions {
  title?: string;
  showHeader?: boolean;
  dismissible?: boolean;
  draggable?: boolean;
  maxHeightPercent?: number;
  testID?: string;
  content: React.ReactNode;
}

export interface ImageConfirmOptions {
  title?: string;
  message?: string;
  confirmLabel?: string;
  cancelLabel?: string;
  isDestructive?: boolean;
  visualType?: 'big' | 'circle';
  preset?: 'loan-doc' | 'rejection' | 'maintenance' | 'success-done' | 'identity-card';
  imageUri?: string;
  dismissible?: boolean;
  testID?: string;
}

export interface AnotherDeviceLoginOptions {
  deviceName?: string;
  location?: string;
  timestamp?: string;
  testID?: string;
}

export type ModalState =
  | { isOpen: false }
  | { isOpen: true; modalType: 'alert'; options: AlertOptions; resolve: () => void }
  | { isOpen: true; modalType: 'confirm'; options: ConfirmOptions; resolve: (val: boolean) => void }
  | { isOpen: true; modalType: 'bottomSheet'; options: BottomSheetOptions; resolve: () => void }
  | { isOpen: true; modalType: 'imageConfirm'; options: ImageConfirmOptions; resolve: (val: boolean) => void }
  | { isOpen: true; modalType: 'anotherDeviceLogin'; options: AnotherDeviceLoginOptions; resolve: (isItMe: boolean) => void };

type Listener = (state: ModalState) => void;

class DialogController {
  private currentState: ModalState = { isOpen: false };
  private listeners: Listener[] = [];

  public getState(): ModalState {
    return this.currentState;
  }

  public subscribe(listener: Listener): () => void {
    this.listeners.push(listener);
    listener(this.currentState);
    return () => {
      this.listeners = this.listeners.filter((l) => l !== listener);
    };
  }

  private notify(state: ModalState) {
    this.currentState = state;
    this.listeners.forEach((listener) => listener(state));
  }

  /**
   * Show an imperative Alert modal with scrollable message/content.
   * Returns a Promise that resolves when the alert is dismissed.
   */
  public alert(options: AlertOptions | string): Promise<void> {
    const normalizedOptions: AlertOptions =
      typeof options === 'string' ? { message: options } : options;

    return new Promise<void>((resolve) => {
      this.notify({
        isOpen: true,
        modalType: 'alert',
        options: normalizedOptions,
        resolve: () => {
          this.close();
          resolve();
        },
      });
    });
  }

  /**
   * Helper specifically designed to display plugin responses / logs in an alert with scrollable content.
   */
  public alertPluginResponse(
    pluginName: string,
    response: any,
    status: 'SUCCESS' | 'ERROR' = 'SUCCESS'
  ): Promise<void> {
    const formatted =
      typeof response === 'object' && response !== null
        ? JSON.stringify(response, null, 2)
        : String(response ?? 'No payload returned');

    return this.alert({
      title: `${status === 'ERROR' ? '⚠️' : '⚡'} ${pluginName}`,
      message: formatted,
      type: status === 'ERROR' ? 'error' : 'info',
      buttonText: 'Close',
      dismissible: true,
      testID: 'plugin-response-alert',
    });
  }

  /**
   * Show an imperative Confirm dialog.
   * Returns a Promise resolving to true if confirmed, false if cancelled.
   */
  public confirm(options: ConfirmOptions | string): Promise<boolean> {
    const normalizedOptions: ConfirmOptions =
      typeof options === 'string' ? { message: options } : options;

    return new Promise<boolean>((resolve) => {
      this.notify({
        isOpen: true,
        modalType: 'confirm',
        options: normalizedOptions,
        resolve: (confirmed: boolean) => {
          this.close();
          resolve(confirmed);
        },
      });
    });
  }

  /**
   * Show an imperative BottomSheet.
   */
  public bottomSheet(options: BottomSheetOptions): Promise<void> {
    return new Promise<void>((resolve) => {
      this.notify({
        isOpen: true,
        modalType: 'bottomSheet',
        options,
        resolve: () => {
          this.close();
          resolve();
        },
      });
    });
  }

  /**
   * Show an imperative ImageConfirmModal.
   */
  public imageConfirm(options: ImageConfirmOptions): Promise<boolean> {
    return new Promise<boolean>((resolve) => {
      this.notify({
        isOpen: true,
        modalType: 'imageConfirm',
        options,
        resolve: (confirmed: boolean) => {
          this.close();
          resolve(confirmed);
        },
      });
    });
  }

  /**
   * Show an imperative AnotherDeviceLoginConfirmModal.
   * Resolves `true` if user selected "It's me", or `false` if user selected "It's not me" / closed.
   */
  public anotherDeviceLogin(options: AnotherDeviceLoginOptions = {}): Promise<boolean> {
    return new Promise<boolean>((resolve) => {
      this.notify({
        isOpen: true,
        modalType: 'anotherDeviceLogin',
        options,
        resolve: (isItMe: boolean) => {
          this.close();
          resolve(isItMe);
        },
      });
    });
  }

  /**
   * Dismiss the currently open modal.
   */
  public close() {
    if (this.currentState.isOpen) {
      this.notify({ isOpen: false });
    }
  }
}

export const DialogUtil = new DialogController();

