export class FormatUtil {
  /**
   * Format number to currency string with commas.
   * e.g., 1000000 -> "1,000,000"
   */
  public static formatAmount(value: number | string, delimiter: string = ','): string {
    if (value === null || value === undefined || value === '') {
      return '0';
    }
    const cleanStr = String(value).replace(/[^0-9.-]/g, '');
    const num = Number(cleanStr);
    if (!Number.isFinite(num)) {
      return '0';
    }

    const parts = cleanStr.split('.');
    parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, delimiter);
    return parts.join('.');
  }

  /**
   * Parse formatted currency string back to raw number.
   * e.g. "1,250.50" -> 1250.5
   */
  public static parseFormattedAmount(formattedStr: string): number {
    if (!formattedStr) {
      return 0;
    }
    const clean = String(formattedStr).replace(/,/g, '').trim();
    const num = Number(clean);
    return Number.isFinite(num) ? num : 0;
  }

  /**
   * Formats currency with ISO code or symbol.
   * e.g. formatCurrency(50000, 'USD') -> "$50,000" or "50,000 USD"
   */
  public static formatCurrency(value: number | string, currency: 'USD' | 'KHR' | 'VND' = 'USD'): string {
    const formatted = this.formatAmount(value);
    switch (currency) {
      case 'USD':
        return `$${formatted}`;
      case 'KHR':
        return `${formatted} ៛`;
      case 'VND':
        return `${formatted} ₫`;
      default:
        return `${formatted} ${currency}`;
    }
  }

  /**
   * Masks a phone number (e.g. 0912345678 -> "091***5678").
   */
  public static maskPhoneNumber(phone: string): string {
    if (!phone || phone.length < 7) {
      return phone || '';
    }
    const start = phone.slice(0, 3);
    const end = phone.slice(-4);
    const masked = '*'.repeat(Math.max(2, phone.length - 7));
    return `${start}${masked}${end}`;
  }

  /**
   * Masks National ID card number (e.g. 123456789 -> "123****89").
   */
  public static maskIdCard(idNumber: string): string {
    if (!idNumber || idNumber.length < 5) {
      return idNumber || '';
    }
    const start = idNumber.slice(0, 3);
    const end = idNumber.slice(-2);
    const masked = '*'.repeat(Math.max(2, idNumber.length - 5));
    return `${start}${masked}${end}`;
  }

  /**
   * Masks a bank account number (e.g. "19034567890123" -> "190••••0123").
   */
  public static maskAccountNumber(
    accountNumber: string,
    options: { visibleStart?: number; visibleEnd?: number; maskChar?: string } = {}
  ): string {
    if (!accountNumber) return '';
    const clean = accountNumber.replace(/[\s-]/g, '');
    const { visibleStart = 3, visibleEnd = 4, maskChar = '•' } = options;
    if (clean.length <= visibleStart + visibleEnd) return clean;

    const start = clean.slice(0, visibleStart);
    const end = clean.slice(-visibleEnd);
    const masked = maskChar.repeat(clean.length - (visibleStart + visibleEnd));
    return `${start}${masked}${end}`;
  }
}

