import React from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useBiometricViewModel, UseBiometricViewModelProps } from '../viewmodels/useBiometricViewModel';
import { AuthHeader } from './components/AuthHeader';
import { AuthButton } from './components/AuthButton';
import { AuthColors, AuthTypography } from '../theme/tokens';
import { useBackNavigation } from '@mfe/ui-components/hooks/useBackNavigation';

export interface BiometricSetupScreenProps {
  viewModelProps?: UseBiometricViewModelProps;
}

export const BiometricSetupScreen: React.FC<BiometricSetupScreenProps> = ({
  viewModelProps,
}) => {
  const { isLoading, errorMessage, enableBiometric, handleSkip, onBack } =
    useBiometricViewModel(viewModelProps);

  const backAction = onBack || handleSkip;

  const { panHandlers } = useBackNavigation({
    onBack: backAction,
    enabled: !isLoading,
  });

  return (
    <SafeAreaView testID="biometric-setup-screen" style={styles.safeArea} {...panHandlers}>
      <AuthHeader
        testID="biometric-header"
        title="Bio Authentication Register"
        onBack={backAction}
        showBack={!!backAction}
      />

      <View style={styles.container}>
        <View style={styles.content}>
          {/* Authentic Vector Fingerprint graphic matching Figma */}
          <View style={styles.iconCircle}>
            <View style={styles.fingerprintGraphic}>
              <View style={[styles.fingerArc, styles.arcOuter]} />
              <View style={[styles.fingerArc, styles.arcMid]} />
              <View style={[styles.fingerArc, styles.arcInner]} />
              <View style={styles.fingerCenter} />
            </View>
          </View>

          <Text testID="biometric-title" style={styles.title}>
            Do you want to use Fingerprint authentication?
          </Text>

          <Text style={styles.subtitle}>
            To log in quickly and conveniently! Please add your fingerprint
            authentication to complete the setup.
          </Text>

          {errorMessage ? (
            <View testID="biometric-error-banner" style={styles.errorBanner}>
              <Text style={styles.errorText}>{errorMessage}</Text>
            </View>
          ) : null}
        </View>

        <View style={styles.footerSection}>
          <AuthButton
            testID="biometric-enable-button"
            title="Enable Fingerprint"
            onPress={enableBiometric}
            isLoading={isLoading}
          />
          <TouchableOpacity
            testID="biometric-skip-button"
            style={styles.skipButton}
            onPress={handleSkip}
            activeOpacity={0.7}
          >
            <Text style={styles.skipText}>Skip for Now</Text>
          </TouchableOpacity>
        </View>
      </View>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
    backgroundColor: AuthColors.white,
  },
  container: {
    flex: 1,
    paddingHorizontal: 24,
    justifyContent: 'space-between',
  },
  content: {
    alignItems: 'center',
    marginTop: 48,
  },
  iconCircle: {
    width: 100,
    height: 100,
    borderRadius: 50,
    backgroundColor: AuthColors.primaryLight,
    alignItems: 'center',
    justifyContent: 'center',
    marginBottom: 32,
  },
  fingerprintGraphic: {
    width: 50,
    height: 50,
    alignItems: 'center',
    justifyContent: 'center',
  },
  fingerArc: {
    position: 'absolute',
    borderColor: AuthColors.primary,
    borderWidth: 2.5,
    borderRadius: 30,
    borderBottomColor: 'transparent',
  },
  arcOuter: {
    width: 48,
    height: 48,
  },
  arcMid: {
    width: 34,
    height: 34,
  },
  arcInner: {
    width: 20,
    height: 20,
  },
  fingerCenter: {
    width: 6,
    height: 12,
    backgroundColor: AuthColors.primary,
    borderRadius: 3,
  },
  title: {
    ...AuthTypography.h2,
    color: AuthColors.textPrimary,
    textAlign: 'center',
    marginBottom: 12,
    lineHeight: 28,
  },
  subtitle: {
    ...AuthTypography.bodyRegular,
    color: AuthColors.textSecondary,
    textAlign: 'center',
    lineHeight: 22,
    paddingHorizontal: 12,
  },
  errorBanner: {
    backgroundColor: AuthColors.errorBackground,
    borderWidth: 1,
    borderColor: AuthColors.borderError,
    borderRadius: 8,
    padding: 12,
    marginTop: 20,
    width: '100%',
  },
  errorText: {
    ...AuthTypography.error,
    color: AuthColors.errorText,
    textAlign: 'center',
  },
  footerSection: {
    paddingBottom: 24,
    gap: 12,
  },
  skipButton: {
    height: 48,
    alignItems: 'center',
    justifyContent: 'center',
  },
  skipText: {
    ...AuthTypography.bodySemiBold,
    color: AuthColors.textSecondary,
  },
});
