import React, { useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
} from 'react-native';
import { TypeSelectableInput, DropdownTypeOption, PresentationMode } from './TypeSelectableInput';

export interface IdDocumentEntry {
  id: string;
  category: 'MAIN_ID' | 'ADDITIONAL_ID';
  type: string;
  number: string;
  error?: string;
}

export interface MultiIdDocumentManagerProps {
  /** Screen or section title */
  title?: string;
  /** Subtitle / instruction */
  subtitle?: string;
  /** Main ID label */
  mainIdLabel?: string;
  /** Add additional ID button label */
  addLabel?: string;
  /** Presentation mode for options picker: 'bottomsheet' (default) or 'alert' */
  presentationMode?: PresentationMode;
  /** Available document types for Main ID */
  mainIdOptions?: DropdownTypeOption[];
  /** Available document types for Additional ID */
  additionalIdOptions?: DropdownTypeOption[];
  /** Controlled document list */
  documents: IdDocumentEntry[];
  /** Callback when document list changes */
  onChange: (docs: IdDocumentEntry[]) => void;
  /** Maximum number of additional IDs allowed */
  maxAdditionalIds?: number;
  /** Whether the manager is editable */
  editable?: boolean;
  /** Custom container style */
  style?: ViewStyle;
  /** Test ID */
  testID?: string;
}

export const defaultMainIdOptions: DropdownTypeOption[] = [
  { label: 'CCCD', value: 'CCCD', placeholder: '12-digit Citizen ID (e.g. 001090012345)', keyboardType: 'numeric' },
  { label: 'CMND', value: 'CMND', placeholder: '9-digit National ID', keyboardType: 'numeric' },
  { label: 'Hộ chiếu (Passport)', value: 'PASSPORT', placeholder: 'Passport Number (e.g. B1234567)' },
];

export const defaultAdditionalIdOptions: DropdownTypeOption[] = [
  { label: 'CMND Cũ (Old 9-digit)', value: 'OLD_CMND', placeholder: 'Old 9-digit National ID', keyboardType: 'numeric' },
  { label: 'CCCD Cũ (Old 12-digit)', value: 'OLD_CCCD', placeholder: 'Old 12-digit Citizen ID', keyboardType: 'numeric' },
  { label: 'Hộ chiếu (Passport)', value: 'PASSPORT', placeholder: 'Passport Number' },
  { label: 'Chứng minh quân đội (Military ID)', value: 'MILITARY_ID', placeholder: 'Military Identification Number' },
];

/**
 * Multi-ID document management component matching the screenshot:
 * "Bổ sung giấy tờ tùy thân"
 * "Trường hợp Khách hàng có nhiều hơn một giấy tờ tùy thân. Vui lòng hoàn thiện thông tin"
 * Supports Main ID (Giấy tờ tùy thân chính) + Dynamic Additional IDs with "+ Thêm loại giấy tờ tùy thân"
 * Shows option selection via BottomSheet or Alert Modal by param.
 */
export const MultiIdDocumentManager: React.FC<MultiIdDocumentManagerProps> = ({
  title = 'Bổ sung giấy tờ tùy thân',
  subtitle = 'Trường hợp Khách hàng có nhiều hơn một giấy tờ tùy thân. Vui lòng hoàn thiện thông tin',
  mainIdLabel = 'Giấy tờ tùy thân chính',
  addLabel = 'Thêm loại giấy tờ tùy thân',
  presentationMode = 'bottomsheet',
  mainIdOptions = defaultMainIdOptions,
  additionalIdOptions = defaultAdditionalIdOptions,
  documents,
  onChange,
  maxAdditionalIds = 3,
  editable = true,
  style,
  testID = 'multi-id-manager',
}) => {
  const mainDoc = documents.find((d) => d.category === 'MAIN_ID') || {
    id: 'main-doc-0',
    category: 'MAIN_ID',
    type: mainIdOptions[0]?.value || 'CCCD',
    number: '',
  };

  const additionalDocs = documents.filter((d) => d.category === 'ADDITIONAL_ID');

  const handleUpdateMainDoc = (updatedType: string, updatedNumber: string) => {
    const newDocs = documents.map((d) =>
      d.category === 'MAIN_ID'
        ? { ...d, type: updatedType, number: updatedNumber }
        : d
    );
    if (!documents.some((d) => d.category === 'MAIN_ID')) {
      newDocs.unshift({
        id: 'main-doc-0',
        category: 'MAIN_ID',
        type: updatedType,
        number: updatedNumber,
      });
    }
    onChange(newDocs);
  };

  const handleUpdateAdditionalDoc = (id: string, updatedType: string, updatedNumber: string) => {
    const newDocs = documents.map((d) =>
      d.id === id ? { ...d, type: updatedType, number: updatedNumber } : d
    );
    onChange(newDocs);
  };

  const handleAddAdditionalDoc = () => {
    if (additionalDocs.length >= maxAdditionalIds) return;
    const newId = `add-doc-${Date.now()}`;
    const newDoc: IdDocumentEntry = {
      id: newId,
      category: 'ADDITIONAL_ID',
      type: additionalIdOptions[0]?.value || 'OLD_CMND',
      number: '',
    };
    onChange([...documents, newDoc]);
  };

  const handleRemoveAdditionalDoc = (id: string) => {
    onChange(documents.filter((d) => d.id !== id));
  };

  return (
    <View testID={testID} style={[styles.container, style]}>
      {/* Title & Subtitle */}
      {title ? (
        <Text testID={`${testID}-title`} style={styles.title}>
          {title}
        </Text>
      ) : null}

      {subtitle ? (
        <Text testID={`${testID}-subtitle`} style={styles.subtitle}>
          {subtitle}
        </Text>
      ) : null}

      {/* Main ID Section */}
      <View style={styles.mainIdSection}>
        <TypeSelectableInput
          label={mainIdLabel}
          options={mainIdOptions}
          selectedType={mainDoc.type}
          onTypeChange={(newType) => handleUpdateMainDoc(newType, mainDoc.number)}
          inputValue={mainDoc.number}
          onInputChange={(newNumber) => handleUpdateMainDoc(mainDoc.type, newNumber)}
          presentationMode={presentationMode}
          selectorTitle="Chọn loại giấy tờ chính"
          error={mainDoc.error}
          testID={`${testID}-main-id`}
        />
      </View>

      {/* Additional IDs Section */}
      {additionalDocs.map((doc, index) => (
        <View key={doc.id} style={styles.additionalIdRow} testID={`${testID}-additional-row-${index}`}>
          <View style={styles.additionalInputWrapper}>
            <TypeSelectableInput
              label={`Giấy tờ tùy thân bổ sung #${index + 1}`}
              options={additionalIdOptions}
              selectedType={doc.type}
              onTypeChange={(newType) => handleUpdateAdditionalDoc(doc.id, newType, doc.number)}
              inputValue={doc.number}
              onInputChange={(newNumber) => handleUpdateAdditionalDoc(doc.id, doc.type, newNumber)}
              presentationMode={presentationMode}
              selectorTitle="Chọn loại giấy tờ bổ sung"
              error={doc.error}
              testID={`${testID}-additional-id-${index}`}
            />
          </View>

          {editable ? (
            <TouchableOpacity
              testID={`${testID}-remove-btn-${index}`}
              style={styles.removeBtn}
              onPress={() => handleRemoveAdditionalDoc(doc.id)}
              hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
            >
              <Text style={styles.removeBtnText}>✕</Text>
            </TouchableOpacity>
          ) : null}
        </View>
      ))}

      {/* "+ Thêm loại giấy tờ tùy thân" Trigger */}
      {editable && additionalDocs.length < maxAdditionalIds ? (
        <TouchableOpacity
          testID={`${testID}-add-btn`}
          style={styles.addBtn}
          onPress={handleAddAdditionalDoc}
          activeOpacity={0.7}
        >
          <View style={styles.addCircle}>
            <Text style={styles.plusSign}>+</Text>
          </View>
          <Text style={styles.addBtnText}>{addLabel}</Text>
        </TouchableOpacity>
      ) : null}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    width: '100%',
  },
  title: {
    fontSize: 22,
    fontWeight: '800',
    color: '#111827',
    marginBottom: 6,
  },
  subtitle: {
    fontSize: 14,
    color: '#6B7280',
    lineHeight: 20,
    marginBottom: 20,
  },
  mainIdSection: {
    marginBottom: 16,
  },
  additionalIdRow: {
    flexDirection: 'row',
    alignItems: 'flex-start',
    marginBottom: 16,
  },
  additionalInputWrapper: {
    flex: 1,
  },
  removeBtn: {
    marginTop: 32,
    marginLeft: 10,
    width: 28,
    height: 28,
    borderRadius: 14,
    backgroundColor: '#F3F4F6',
    justifyContent: 'center',
    alignItems: 'center',
  },
  removeBtnText: {
    fontSize: 14,
    color: '#9CA3AF',
    fontWeight: '700',
  },
  addBtn: {
    flexDirection: 'row',
    alignItems: 'center',
    marginTop: 8,
    paddingVertical: 8,
  },
  addCircle: {
    width: 22,
    height: 22,
    borderRadius: 11,
    backgroundColor: '#2563EB',
    justifyContent: 'center',
    alignItems: 'center',
    marginRight: 10,
  },
  plusSign: {
    fontSize: 16,
    color: '#FFFFFF',
    fontWeight: '700',
    lineHeight: 18,
  },
  addBtnText: {
    fontSize: 15,
    fontWeight: '700',
    color: '#2563EB',
  },
});
