import { useState, useEffect, useCallback } from 'react';
import { ILaunchService, LaunchService } from '../services/LaunchService';
import {
  SupportedLanguage,
  SUPPORTED_LANGUAGES,
  LanguageOption,
  LaunchValidator,
  DeviceInfoResult,
} from '../models/LaunchModel';

export interface UseChooseLanguageViewModelProps {
  launchService?: ILaunchService;
  onProceed?: (selectedLanguage: SupportedLanguage) => void;
  onSkip?: () => void;
  onCancel?: () => void;
}

export function useChooseLanguageViewModel({
  launchService = new LaunchService(),
  onProceed,
  onSkip,
  onCancel,
}: UseChooseLanguageViewModelProps = {}) {
  const [selectedLanguage, setSelectedLanguage] =
    useState<SupportedLanguage>('km');
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [languages] = useState<LanguageOption[]>(SUPPORTED_LANGUAGES);
  const [deviceInfo, setDeviceInfo] = useState<DeviceInfoResult | null>(null);

  useEffect(() => {
    let isMounted = true;
    (async () => {
      const [stored, info] = await Promise.all([
        launchService.getStoredLanguage(),
        launchService.getDeviceInfo(),
      ]);

      if (isMounted) {
        if (stored && LaunchValidator.isValidLanguage(stored)) {
          setSelectedLanguage(stored);
        }
        if (info) {
          setDeviceInfo(info);
        }
      }
    })();
    return () => {
      isMounted = false;
    };
  }, [launchService]);

  const selectLanguage = useCallback((lang: SupportedLanguage) => {
    if (LaunchValidator.isValidLanguage(lang)) {
      setSelectedLanguage(lang);
    }
  }, []);

  const handleNext = useCallback(async () => {
    setIsLoading(true);
    try {
      await launchService.saveLanguage(selectedLanguage);
      if (onProceed) {
        onProceed(selectedLanguage);
      }
    } finally {
      setIsLoading(false);
    }
  }, [launchService, onProceed, selectedLanguage]);

  const handleSkip = useCallback(() => {
    if (onSkip) {
      onSkip();
    } else {
      handleNext();
    }
  }, [handleNext, onSkip]);

  const handleCancel = useCallback(() => {
    if (onCancel) {
      onCancel();
    }
  }, [onCancel]);

  const fetchDeviceInfo = useCallback(async () => {
    const info = await launchService.getDeviceInfo();
    if (info) {
      setDeviceInfo(info);
    }
    return info;
  }, [launchService]);

  const invokePlugin = useCallback(
    async <TResult = any, TParams = Record<string, any>>(
      pluginId: string,
      params?: TParams
    ): Promise<TResult> => {
      return launchService.callPlugin<TResult, TParams>(pluginId, params);
    },
    [launchService]
  );

  return {
    languages,
    selectedLanguage,
    isLoading,
    deviceInfo,
    fetchDeviceInfo,
    invokePlugin,
    selectLanguage,
    handleNext,
    handleSkip,
    handleCancel: onCancel ? handleCancel : undefined,
  };
}
