import React, { useState } from 'react';
import { View, Text, StyleSheet } from 'react-native';
import {
  AppCard,
  AppButton,
  OnboardingSlider,
  OnboardingSlideItem,
} from '@mfe/ui-components/components';
import { useTheme, defaultTheme } from '@mfe/theme';
import { CodeBlock } from '../../components/CodeBlock';

const ONBOARDING_SLIDER_SNIPPET = `import { OnboardingSlider, OnboardingSlideItem } from '@mfe/ui-components/components';

const slides: OnboardingSlideItem[] = [
  {
    id: 'welcome',
    badge: 'Step 1',
    title: 'Fast Loan Origination',
    description: 'Submit and track customer loan applications from anywhere.',
  },
  {
    id: 'underwriting',
    badge: 'Step 2',
    title: 'Instant Underwriting',
    description: 'Calculate DSCR and LTV in real time with guided checklists.',
  },
  {
    id: 'approval',
    badge: 'Step 3',
    title: 'Secure Approvals',
    description: 'Review and approve cases with biometric verification.',
  },
];

<OnboardingSlider
  slides={slides}
  onComplete={() => console.log('Onboarding completed')}
  onSkip={() => console.log('Onboarding skipped')}
  onSlideChange={(index) => console.log('Active slide:', index)}
/>;`;

export const OnboardingSliderDetailSection: React.FC = () => {
  const themeContext = useTheme();
  const theme = themeContext?.theme || defaultTheme;
  const { colors, radius, spacing } = theme;

  const [activeSlide, setActiveSlide] = useState(0);
  const [statusMessage, setStatusMessage] = useState<string>(
    'Swipe or tap Next / dots to preview slides.'
  );
  const [sliderKey, setSliderKey] = useState(0);

  const slides: OnboardingSlideItem[] = [
    {
      id: 'welcome',
      badge: 'Step 1 of 3',
      title: 'Fast Loan Origination',
      description:
        'Capture customer profiles, documents, and loan requests seamlessly in one workflow.',
      illustration: (
        <View
          style={[
            styles.illustrationCircle,
            { backgroundColor: colors.primaryLight, borderRadius: radius.full },
          ]}
        >
          <Text style={[styles.illustrationText, { color: colors.primary }]}>01</Text>
        </View>
      ),
    },
    {
      id: 'underwriting',
      badge: 'Step 2 of 3',
      title: 'Instant Underwriting',
      description:
        'Evaluate DSCR, LTV, and collateral readiness with built-in enterprise rules.',
      illustration: (
        <View
          style={[
            styles.illustrationCircle,
            { backgroundColor: colors.secondaryLight, borderRadius: radius.full },
          ]}
        >
          <Text style={[styles.illustrationText, { color: colors.secondary }]}>02</Text>
        </View>
      ),
    },
    {
      id: 'approval',
      badge: 'Step 3 of 3',
      title: 'Secure Approvals',
      description:
        'Verify identity with OTP and biometrics before finalizing disbursement.',
      illustration: (
        <View
          style={[
            styles.illustrationCircle,
            { backgroundColor: colors.successBg, borderRadius: radius.full },
          ]}
        >
          <Text style={[styles.illustrationText, { color: colors.success }]}>03</Text>
        </View>
      ),
    },
  ];

  const handleReplay = () => {
    setActiveSlide(0);
    setStatusMessage('Slider reset to Slide 1.');
    setSliderKey((prev) => prev + 1);
  };

  return (
    <View testID="detail-onboarding-slider">
      <CodeBlock
        title="OnboardingSlider Usage"
        code={ONBOARDING_SLIDER_SNIPPET}
      />

      <AppCard style={styles.demoCard}>
        <View style={styles.headerRow}>
          <View style={styles.headerTextWrap}>
            <Text style={[styles.detailHeader, { color: colors.text }]}>
              Interactive Onboarding Slider
            </Text>
            <Text style={[styles.helperText, { color: colors.textMuted }]}>
              Active Slide: {activeSlide + 1} / {slides.length} — {statusMessage}
            </Text>
          </View>
          <AppButton
            title="Reset"
            variant="outline"
            size="sm"
            onPress={handleReplay}
            testID="demo-onboarding-reset-btn"
          />
        </View>

        <View
          style={[
            styles.sliderFrame,
            {
              borderColor: colors.border,
              borderRadius: radius.lg,
              marginTop: spacing.md,
            },
          ]}
        >
          <OnboardingSlider
            key={sliderKey}
            slides={slides}
            onSlideChange={(index) => {
              setActiveSlide(index);
              setStatusMessage(`Moved to Slide ${index + 1}`);
            }}
            onSkip={() => setStatusMessage('User tapped Skip')}
            onComplete={() => setStatusMessage('User completed onboarding!')}
            testID="demo-onboarding-slider"
          />
        </View>
      </AppCard>
    </View>
  );
};

const styles = StyleSheet.create({
  demoCard: {
    marginBottom: 16,
  },
  headerRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: 12,
  },
  headerTextWrap: {
    flex: 1,
  },
  detailHeader: {
    fontSize: 15,
    fontWeight: '700',
    marginBottom: 4,
  },
  helperText: {
    fontSize: 13,
    lineHeight: 18,
  },
  sliderFrame: {
    height: 440,
    borderWidth: 1,
    overflow: 'hidden',
  },
  illustrationCircle: {
    width: 88,
    height: 88,
    alignItems: 'center',
    justifyContent: 'center',
  },
  illustrationText: {
    fontSize: 28,
    fontWeight: '800',
  },
});
