export class JsonUtil {
  /**
   * Safely parse a JSON string with fallback default value.
   */
  public static parse<T>(jsonString: string | null | undefined, defaultValue: T): T {
    if (!jsonString || typeof jsonString !== 'string') {
      return defaultValue;
    }
    try {
      return JSON.parse(jsonString) as T;
    } catch {
      return defaultValue;
    }
  }

  /**
   * Safely stringify any object into JSON.
   */
  public static stringify(value: unknown, indent?: number): string {
    try {
      return JSON.stringify(value, null, indent);
    } catch {
      return '';
    }
  }

  /**
   * Deep clone an object using JSON serialization.
   */
  public static deepClone<T>(obj: T): T {
    if (!obj || typeof obj !== 'object') {
      return obj;
    }
    try {
      return JSON.parse(JSON.stringify(obj)) as T;
    } catch {
      return obj;
    }
  }
}

