import React, { useState, useEffect } from 'react';
import {
  FullScreenAlertUtil,
  FullScreenAlertOptions,
} from '@mfe/core/utils/fullScreenAlertUtil';
import { FullScreenAlertModal } from './FullScreenAlertModal';

export interface GlobalFullScreenAlertHostProps {
  testID?: string;
}

/**
 * Global Host/Root component for FullScreenAlert.
 * Subscribes to `FullScreenAlertUtil` and presents the alert modal globally
 * without needing props drilled through navigators.
 */
export const GlobalFullScreenAlertHost: React.FC<GlobalFullScreenAlertHostProps> = ({
  testID = 'global-full-screen-alert-host',
}) => {
  const [currentAlert, setCurrentAlert] = useState<FullScreenAlertOptions | null>(null);

  useEffect(() => {
    const unsubscribe = FullScreenAlertUtil.subscribe((alert) => {
      setCurrentAlert(alert);
    });
    return () => {
      unsubscribe();
    };
  }, []);

  if (!currentAlert) {
    return null;
  }

  return (
    <FullScreenAlertModal
      visible={true}
      alert={currentAlert}
      onClose={() => FullScreenAlertUtil.dismiss()}
      testID={testID}
    />
  );
};
