import React, { useRef } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  KeyboardAvoidingView,
  Platform,
  TouchableWithoutFeedback,
  Keyboard,
  TouchableOpacity,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useLoginViewModel, UseLoginViewModelProps } from '../viewmodels/useLoginViewModel';
import { AuthInputField } from './components/AuthInputField';
import { AuthButton } from './components/AuthButton';
import { AuthColors, AuthTypography } from '../theme/tokens';
import { LaunchLogo } from '../../src_launch/views/components/LaunchLogo';
import { useI18n } from '@mfe/core/i18n';
import { useAutoScrollOnInputFocus, useExitAppPrompt } from '@mfe/ui-components/hooks';

export interface LoginScreenProps {
  viewModelProps?: UseLoginViewModelProps;
  showCompanyId?: boolean;
}

export const LoginScreen: React.FC<LoginScreenProps> = ({
  viewModelProps,
  showCompanyId = false,
}) => {
  const { t, isKhmer } = useI18n();
  const {
    companyId,
    userId,
    password,
    isPasswordVisible,
    isLoading,
    fieldErrors,
    errorMessage,
    setCompanyId,
    setUserId,
    setPassword,
    togglePasswordVisibility,
    submitLogin,
    onNavigateToForgotPassword,
    onBack,
  } = useLoginViewModel(viewModelProps);

  // Prompt user to confirm exit when pressing back on the root Login screen (no parent back available)
  useExitAppPrompt({
    enabled: !isLoading && !onBack,
  });

  const scrollViewRef = useRef<ScrollView>(null);
  const { keyboardHeight, onScroll, scrollToFocusedInput } = useAutoScrollOnInputFocus({
    scrollViewRef,
    extraMargin: 48,
  });

  return (
    <SafeAreaView testID="login-screen" style={styles.safeArea}>
      <KeyboardAvoidingView
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
        style={styles.keyboardView}
      >
        <TouchableWithoutFeedback onPress={Keyboard.dismiss}>
          <ScrollView
            ref={scrollViewRef}
            contentContainerStyle={[
              styles.scrollContent,
              keyboardHeight > 0 && { paddingBottom: keyboardHeight + 48 },
            ]}
            keyboardShouldPersistTaps="handled"
            onScroll={onScroll}
            scrollEventThrottle={16}
          >
            {/* Top Brand Logo */}
            <View style={styles.logoSection}>
              <LaunchLogo testID="login-brand-logo" />
            </View>

            {/* Introductory Heading */}
            <View style={styles.headerSection}>
              <Text testID="login-welcome-title" style={styles.title}>
                {t.auth.login.title}
              </Text>
              <Text style={styles.subtitle}>
                {t.auth.login.subtitle}
              </Text>
            </View>

            {/* Error Banner */}
            {errorMessage ? (
              <View testID="login-error-banner" style={styles.errorBanner}>
                <Text style={styles.errorBannerText}>{errorMessage}</Text>
              </View>
            ) : null}

            {/* Input Fields */}
            <View style={styles.formSection}>
              {showCompanyId && (
                <AuthInputField
                  testID="company-id-input"
                  label={t.auth.login.companyId}
                  value={companyId}
                  onChangeText={setCompanyId}
                  placeholder={t.auth.login.companyIdPlaceholder}
                  errorMessage={fieldErrors.companyId}
                  onFocus={() => scrollToFocusedInput(80)}
                />
              )}

              <AuthInputField
                testID="user-id-input"
                label={t.auth.login.userId}
                value={userId}
                onChangeText={setUserId}
                placeholder={t.auth.login.userIdPlaceholder}
                autoCapitalize="none"
                errorMessage={fieldErrors.userId}
                onFocus={() => scrollToFocusedInput(100)}
              />

              <AuthInputField
                testID="password-input"
                label={t.auth.login.password}
                value={password}
                onChangeText={setPassword}
                placeholder={t.auth.login.passwordPlaceholder}
                secureTextEntry
                showTogglePassword
                isPasswordVisible={isPasswordVisible}
                onTogglePasswordVisibility={togglePasswordVisibility}
                errorMessage={fieldErrors.password}
                onFocus={() => scrollToFocusedInput(140)}
              />

              {/* Forgot Password Link */}
              <TouchableOpacity
                testID="forgot-password-link"
                style={styles.forgotPasswordContainer}
                onPress={onNavigateToForgotPassword}
                activeOpacity={0.7}
              >
                <Text style={styles.forgotPasswordText}>
                  {t.auth.login.forgotPassword}
                </Text>
              </TouchableOpacity>
            </View>

            {/* Full-width CTA Button */}
            <View style={styles.actionSection}>
              <AuthButton
                testID="login-submit-button"
                title={t.auth.login.signInButton}
                onPress={submitLogin}
                isLoading={isLoading}
              />
            </View>
          </ScrollView>
        </TouchableWithoutFeedback>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
    backgroundColor: AuthColors.white,
  },
  keyboardView: {
    flex: 1,
  },
  scrollContent: {
    flexGrow: 1,
    paddingHorizontal: 24,
    paddingVertical: 20,
  },
  logoSection: {
    alignItems: 'center',
    marginTop: 20,
    marginBottom: 8,
  },
  headerSection: {
    alignItems: 'center',
    marginBottom: 28,
  },
  title: {
    ...AuthTypography.h1,
    color: AuthColors.textPrimary,
    marginBottom: 6,
  },
  subtitle: {
    ...AuthTypography.bodyRegular,
    color: AuthColors.textSecondary,
    textAlign: 'center',
  },
  errorBanner: {
    backgroundColor: AuthColors.errorBackground,
    borderWidth: 1,
    borderColor: AuthColors.borderError,
    borderRadius: 8,
    padding: 12,
    marginBottom: 16,
  },
  errorBannerText: {
    ...AuthTypography.error,
    color: AuthColors.errorText,
    textAlign: 'center',
  },
  formSection: {
    width: '100%',
  },
  forgotPasswordContainer: {
    alignSelf: 'flex-end',
    marginTop: 4,
    marginBottom: 24,
  },
  forgotPasswordText: {
    ...AuthTypography.bodyMedium,
    color: AuthColors.textLink,
    fontWeight: '600',
  },
  actionSection: {
    width: '100%',
    marginTop: 'auto',
    paddingBottom: 16,
  },
});
