import {
  previewPdf as nativePreviewPdf,
  openPdf as nativeOpenPdf,
  type PdfPreviewRequest,
  type BizmobResponse,
  type PdfPreviewResult,
} from 'react-native-bizmob-plugin';
import { appLogger } from '../logger/AppLogger';

export interface PdfPluginAdapter {
  previewPdf: typeof nativePreviewPdf;
  openPdf: typeof nativeOpenPdf;
}

const defaultAdapter: PdfPluginAdapter = {
  previewPdf: nativePreviewPdf,
  openPdf: nativeOpenPdf,
};

/**
 * Native PDF Document Viewer Service (`PdfDocumentViewerService`)
 *
 * Renders encrypted loan agreements, credit approval slips, and CBC reports
 * inside a secure sandboxed native viewer.
 */
export class PdfDocumentViewerService {
  private static instance: PdfDocumentViewerService;
  private adapter: PdfPluginAdapter;

  constructor(adapter: PdfPluginAdapter = defaultAdapter) {
    this.adapter = adapter;
  }

  public static getInstance(): PdfDocumentViewerService {
    if (!PdfDocumentViewerService.instance) {
      PdfDocumentViewerService.instance = new PdfDocumentViewerService();
    }
    return PdfDocumentViewerService.instance;
  }

  /**
   * Opens a PDF from a local file path, remote URL, or Base64 string.
   */
  public async viewPdf(options: {
    title?: string;
    filePath?: string;
    url?: string;
    base64?: string;
  }): Promise<boolean> {
    const req: PdfPreviewRequest = {
      title: options.title || 'Document Viewer',
      filePath: options.filePath,
      target_path: options.filePath,
      url: options.url,
      base64: options.base64,
    };

    try {
      const res: BizmobResponse<PdfPreviewResult> = await this.adapter.previewPdf(req);
      const isSuccess = res?.header?.result ?? true;
      appLogger.i('PdfDocumentViewerService', `📄 PDF Viewer opened for [${options.title || 'PDF'}]`);
      return isSuccess;
    } catch (err) {
      appLogger.w('PdfDocumentViewerService', '⚠️ Failed to open PDF preview:', err);
      return false;
    }
  }
}

export const defaultPdfDocumentViewerService = PdfDocumentViewerService.getInstance();
