import React from 'react';
import {
  View,
  Text,
  Image,
  TouchableOpacity,
  Linking,
  StyleSheet,
  ViewStyle,
  TextStyle,
  ImageStyle,
  Platform,
} from 'react-native';

export interface HtmlStyleTags {
  p?: TextStyle;
  h1?: TextStyle;
  h2?: TextStyle;
  h3?: TextStyle;
  h4?: TextStyle;
  h5?: TextStyle;
  h6?: TextStyle;
  strong?: TextStyle;
  b?: TextStyle;
  em?: TextStyle;
  i?: TextStyle;
  u?: TextStyle;
  s?: TextStyle;
  strike?: TextStyle;
  a?: TextStyle;
  ul?: ViewStyle;
  ol?: ViewStyle;
  li?: TextStyle;
  blockquote?: ViewStyle;
  code?: TextStyle;
  pre?: ViewStyle;
  img?: ImageStyle;
}

export interface HtmlViewerProps {
  /**
   * Raw HTML string from rich text editors (CKEditor, Quill, TinyMCE, TipTap, etc.)
   */
  html: string;
  /**
   * Custom style tags mapping
   */
  tagsStyles?: HtmlStyleTags;
  /**
   * Overall container style
   */
  style?: ViewStyle;
  /**
   * Custom link press handler
   */
  onLinkPress?: (url: string) => void;
  /**
   * Test ID for accessibility and testing
   */
  testID?: string;
}

interface ParsedNode {
  type: 'tag' | 'text';
  tagName?: string;
  attributes?: Record<string, string>;
  children?: ParsedNode[];
  content?: string;
}

/**
 * Tokenize simple HTML strings into parsed DOM-like node hierarchy
 */
function parseHtml(html: string): ParsedNode[] {
  if (!html) return [];

  // Normalize self-closing and br tags
  const normalized = html
    .replace(/<br\s*[\/]?>/gi, '\n')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");

  const tagRegex = /<(\/)?([a-zA-Z0-9]+)([^>]*)>/g;
  const rootNodes: ParsedNode[] = [];
  const stack: { node: ParsedNode }[] = [];

  let lastIndex = 0;
  let match: RegExpExecArray | null;

  while ((match = tagRegex.exec(normalized)) !== null) {
    const textBefore = normalized.substring(lastIndex, match.index);
    if (textBefore) {
      const textNode: ParsedNode = { type: 'text', content: textBefore };
      if (stack.length > 0) {
        stack[stack.length - 1].node.children = stack[stack.length - 1].node.children || [];
        stack[stack.length - 1].node.children!.push(textNode);
      } else {
        rootNodes.push(textNode);
      }
    }

    const isClosing = !!match[1];
    const tagName = match[2].toLowerCase();
    const rawAttrs = match[3];

    if (isClosing) {
      if (stack.length > 0 && stack[stack.length - 1].node.tagName === tagName) {
        stack.pop();
      }
    } else {
      // Parse attributes (e.g. href="...", src="...")
      const attrs: Record<string, string> = {};
      const attrRegex = /([a-zA-Z0-9_-]+)(?:=(?:["']([^"']*)["']|([^\s>]+)))?/g;
      let attrMatch: RegExpExecArray | null;
      while ((attrMatch = attrRegex.exec(rawAttrs)) !== null) {
        const key = attrMatch[1].toLowerCase();
        const val = attrMatch[2] !== undefined ? attrMatch[2] : (attrMatch[3] || '');
        attrs[key] = val;
      }

      const isSelfClosing = rawAttrs.trim().endsWith('/') || tagName === 'img' || tagName === 'hr';
      const elementNode: ParsedNode = {
        type: 'tag',
        tagName,
        attributes: attrs,
        children: [],
      };

      if (stack.length > 0) {
        stack[stack.length - 1].node.children = stack[stack.length - 1].node.children || [];
        stack[stack.length - 1].node.children!.push(elementNode);
      } else {
        rootNodes.push(elementNode);
      }

      if (!isSelfClosing) {
        stack.push({ node: elementNode });
      }
    }

    lastIndex = tagRegex.lastIndex;
  }

  // Any trailing text
  if (lastIndex < normalized.length) {
    const trailingText = normalized.substring(lastIndex);
    if (trailingText) {
      rootNodes.push({ type: 'text', content: trailingText });
    }
  }

  return rootNodes;
}

/**
 * HtmlViewer (Pure Native / Web Cross-Platform HTML Renderer)
 *
 * Lightweight, zero-native-dependency rich text HTML renderer for:
 * - Headlines: h1, h2, h3, h4, h5, h6
 * - Formatting: strong, b, em, i, u, s, strike, mark
 * - Blocks: p, blockquote, pre, code
 * - Lists: ul, ol, li (with bullet points and ordered numbers)
 * - Media & Links: a (clickable), img (responsive images)
 * - Tables and dividers: hr
 */
export const HtmlViewer: React.FC<HtmlViewerProps> = ({
  html,
  tagsStyles = {},
  style,
  onLinkPress,
  testID = 'html-viewer',
}) => {
  const nodes = parseHtml(html);

  const handleLink = (url: string) => {
    if (onLinkPress) {
      onLinkPress(url);
    } else {
      Linking.openURL(url).catch((err) =>
        console.warn('Could not open link in HtmlViewer:', err)
      );
    }
  };

  const renderInlineText = (
    nodeList: ParsedNode[],
    parentStyles: TextStyle[] = [],
    keyPrefix = 'inline'
  ): React.ReactNode => {
    return nodeList.map((child, idx) => {
      const key = `${keyPrefix}-${idx}`;

      if (child.type === 'text') {
        return (
          <Text key={key} style={parentStyles}>
            {child.content}
          </Text>
        );
      }

      const tag = child.tagName || '';
      const currentStyle: TextStyle[] = [...parentStyles];

      if (tag === 'strong' || tag === 'b') currentStyle.push(styles.bold);
      if (tag === 'em' || tag === 'i') currentStyle.push(styles.italic);
      if (tag === 'u') currentStyle.push(styles.underline);
      if (tag === 's' || tag === 'strike') currentStyle.push(styles.strikethrough);
      if (tag === 'code') currentStyle.push(styles.inlineCode);

      // Custom tag style override
      const customTagStyle = (tagsStyles as any)[tag];
      if (customTagStyle) currentStyle.push(customTagStyle);

      if (tag === 'a') {
        const href = child.attributes?.href || '';
        return (
          <Text
            key={key}
            style={[styles.link, customTagStyle || {}, ...parentStyles]}
            onPress={() => href && handleLink(href)}
            testID={`${testID}-link`}
          >
            {renderInlineText(child.children || [], currentStyle, key)}
          </Text>
        );
      }

      return renderInlineText(child.children || [], currentStyle, key);
    });
  };

  const renderBlockNode = (node: ParsedNode, index: number): React.ReactNode => {
    const key = `block-${index}`;

    if (node.type === 'text') {
      const trimmed = node.content?.trim();
      if (!trimmed) return null;
      return (
        <Text key={key} style={styles.paragraph} testID={`${testID}-text`}>
          {node.content}
        </Text>
      );
    }

    const tag = node.tagName || '';
    const children = node.children || [];

    // Headings
    if (tag === 'h1') {
      return (
        <Text key={key} style={[styles.h1, tagsStyles.h1]} testID={`${testID}-h1`}>
          {renderInlineText(children, [styles.h1, tagsStyles.h1 || {}])}
        </Text>
      );
    }
    if (tag === 'h2') {
      return (
        <Text key={key} style={[styles.h2, tagsStyles.h2]} testID={`${testID}-h2`}>
          {renderInlineText(children, [styles.h2, tagsStyles.h2 || {}])}
        </Text>
      );
    }
    if (tag === 'h3') {
      return (
        <Text key={key} style={[styles.h3, tagsStyles.h3]} testID={`${testID}-h3`}>
          {renderInlineText(children, [styles.h3, tagsStyles.h3 || {}])}
        </Text>
      );
    }
    if (tag === 'h4' || tag === 'h5' || tag === 'h6') {
      return (
        <Text key={key} style={[styles.h4, tagsStyles.h4]} testID={`${testID}-h4`}>
          {renderInlineText(children, [styles.h4, tagsStyles.h4 || {}])}
        </Text>
      );
    }

    // Paragraph
    if (tag === 'p') {
      return (
        <Text key={key} style={[styles.paragraph, tagsStyles.p]} testID={`${testID}-p`}>
          {renderInlineText(children, [styles.paragraph, tagsStyles.p || {}])}
        </Text>
      );
    }

    // Unordered List <ul>
    if (tag === 'ul') {
      return (
        <View key={key} style={[styles.list, tagsStyles.ul]} testID={`${testID}-ul`}>
          {children
            .filter((c) => c.type === 'tag' && c.tagName === 'li')
            .map((li, lIdx) => (
              <View key={`li-${lIdx}`} style={styles.listItemRow}>
                <Text style={styles.bulletPoint}>•</Text>
                <Text style={[styles.listItemText, tagsStyles.li]}>
                  {renderInlineText(li.children || [], [styles.listItemText, tagsStyles.li || {}])}
                </Text>
              </View>
            ))}
        </View>
      );
    }

    // Ordered List <ol>
    if (tag === 'ol') {
      return (
        <View key={key} style={[styles.list, tagsStyles.ol]} testID={`${testID}-ol`}>
          {children
            .filter((c) => c.type === 'tag' && c.tagName === 'li')
            .map((li, lIdx) => (
              <View key={`oli-${lIdx}`} style={styles.listItemRow}>
                <Text style={styles.orderedNumber}>{lIdx + 1}.</Text>
                <Text style={[styles.listItemText, tagsStyles.li]}>
                  {renderInlineText(li.children || [], [styles.listItemText, tagsStyles.li || {}])}
                </Text>
              </View>
            ))}
        </View>
      );
    }

    // Blockquote
    if (tag === 'blockquote') {
      return (
        <View
          key={key}
          style={[styles.blockquote, tagsStyles.blockquote]}
          testID={`${testID}-blockquote`}
        >
          <Text style={styles.blockquoteText}>
            {renderInlineText(children, [styles.blockquoteText])}
          </Text>
        </View>
      );
    }

    // Preformatted Code Block
    if (tag === 'pre') {
      return (
        <View key={key} style={[styles.preBlock, tagsStyles.pre]} testID={`${testID}-pre`}>
          <Text style={[styles.preText, tagsStyles.code]}>
            {children.map((c) => c.content || '').join('')}
          </Text>
        </View>
      );
    }

    // Image <img>
    if (tag === 'img') {
      const src = node.attributes?.src;
      if (!src) return null;
      return (
        <Image
          key={key}
          source={{ uri: src }}
          style={[styles.image, tagsStyles.img]}
          resizeMode="cover"
          testID={`${testID}-img`}
        />
      );
    }

    // Horizontal Rule <hr>
    if (tag === 'hr') {
      return <View key={key} style={styles.hr} testID={`${testID}-hr`} />;
    }

    // Fallback: render inner text or children
    return (
      <View key={key} style={styles.defaultBlock}>
        {children.map((child, cIdx) => renderBlockNode(child, cIdx))}
      </View>
    );
  };

  return (
    <View style={[styles.container, style]} testID={testID}>
      {nodes.map((node, index) => renderBlockNode(node, index))}
    </View>
  );
};

