import React, { useState } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  Linking,
} from 'react-native';
import Svg, { Path, Circle, Rect } from 'react-native-svg';
import { PullToRefreshScrollView } from '@mfe/ui-components/components/scroll/PullToRefreshScrollView';
import { NoDataState } from '@mfe/ui-components/components/empty/NoDataState';
import {
  useDashboardViewModel,
  UseDashboardViewModelProps,
} from '../../viewmodels/useDashboardViewModel';

export interface DebtorTabContentProps {
  onBackToDashboard?: () => void;
  viewModelProps?: UseDashboardViewModelProps;
}

export const DebtorTabContent: React.FC<DebtorTabContentProps> = ({
  viewModelProps,
}) => {
  const [isDebtorListOpen, setIsDebtorListOpen] = useState(true);
  const { debtorList, isRefreshing, handleRefresh } = useDashboardViewModel(viewModelProps);

  const handleCall = (phoneNumber: string) => {
    Linking.openURL(`tel:${phoneNumber.replace(/[^0-9+]/g, '')}`);
  };

  return (
    <View testID="debtor-tab-content" style={styles.container}>
      {/* Header Bar */}
      <View style={styles.headerBar}>
        <Text style={styles.headerTitle}>Debtor Today</Text>
      </View>

      {/* Accordion Bar */}
      <TouchableOpacity
        testID="debtor-list-accordion-toggle"
        style={styles.accordionBar}
        activeOpacity={0.7}
        onPress={() => setIsDebtorListOpen(!isDebtorListOpen)}
      >
        <Text style={styles.accordionTitle}>Today's debtor list</Text>
        <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
          <Path
            d={isDebtorListOpen ? 'M18 15L12 9L6 15' : 'M6 9L12 15L18 9'}
            stroke="#1E293B"
            strokeWidth={2.2}
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </Svg>
      </TouchableOpacity>

      {/* Debtor Cards List */}
      {isDebtorListOpen && (
        <PullToRefreshScrollView
          refreshing={isRefreshing}
          onRefresh={handleRefresh}
          contentContainerStyle={styles.scrollList}
          showsVerticalScrollIndicator={false}
          testID="debtor-list-pull-refresh"
        >
          {debtorList.length === 0 ? (
            <View style={{ paddingVertical: 40 }}>
              <NoDataState title="No data available." testID="debtor-no-data" />
            </View>
          ) : (
            debtorList.map((debtor) => (
              <View
                key={debtor.id}
                testID={`debtor-card-${debtor.id}`}
                style={styles.debtorCard}
              >
                <View style={styles.debtorHeaderRow}>
                  <View
                    style={[
                      styles.debtorAvatarDark,
                      debtor.avatarVariant === 'indigo' && { backgroundColor: '#E0E7FF' },
                      debtor.avatarVariant === 'slate' && { backgroundColor: '#E2E8F0' },
                    ]}
                  >
                    {debtor.avatarVariant === 'indigo' ? (
                      <Svg width={22} height={22} viewBox="0 0 24 24" fill="none">
                        <Rect x="3" y="4" width="18" height="16" rx="2" fill="#4338CA" />
                        <Path d="M7 8H17M7 12H13" stroke="#FFFFFF" strokeWidth={1.5} />
                      </Svg>
                    ) : (
                      <Svg width={24} height={24} viewBox="0 0 24 24" fill="none">
                        <Circle cx="12" cy="8" r="4" fill="#64748B" />
                        <Path d="M4 20C4 16.6863 7.58172 14 12 14C16.4183 14 20 16.6863 20 20" fill="#64748B" />
                      </Svg>
                    )}
                  </View>
                  <Text style={styles.debtorName}>{debtor.name}</Text>
                  <View style={styles.normalPill}>
                    <Text style={styles.normalPillText}>{debtor.status}</Text>
                  </View>
                </View>

                {/* Address & Distance */}
                <View style={styles.addressBox}>
                  <View style={styles.addressLeftCol}>
                    {debtor.address ? (
                      <Text style={styles.addressText}>{debtor.address}</Text>
                    ) : (
                      <Text style={styles.addressTextEmpty}>—</Text>
                    )}
                  </View>
                  <View style={styles.distanceBadgeCol}>
                    <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                      <Rect x="3" y="3" width="18" height="18" rx="3" fill="#2563EB" />
                      <Path d="M9 15V10H14M14 10L11.5 7.5M14 10L11.5 12.5" stroke="#FFFFFF" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" />
                    </Svg>
                    <Text style={styles.distanceKmText}>{debtor.distanceKm}</Text>
                  </View>
                </View>

                {/* Call Action Button (only if phoneNumber is present) */}
                {!!debtor.phoneNumber && (
                  <TouchableOpacity
                    testID={`btn-call-debtor-${debtor.id}`}
                    style={styles.callActionButton}
                    activeOpacity={0.85}
                    onPress={() => handleCall(debtor.phoneNumber)}
                  >
                    <Svg width={16} height={16} viewBox="0 0 24 24" fill="none">
                      <Path
                        d="M22 16.92V19.92C22 20.4723 21.5523 20.92 21 20.92C11.6112 20.92 4 13.3088 4 3.92C4 3.36772 4.44772 2.92 5 2.92H8C8.55228 2.92 9 3.36772 9 3.92C9 5.3088 9.24 6.64 9.68 7.86C9.8 8.18 9.72 8.54 9.48 8.78L7.66 10.6C9.18 13.68 11.24 15.74 14.32 17.26L16.14 15.44C16.38 15.2 16.74 15.12 17.06 15.24C18.28 15.68 19.6112 15.92 21 15.92C21.5523 15.92 22 16.3677 22 16.92Z"
                        fill="#FFFFFF"
                      />
                    </Svg>
                    <Text style={styles.callButtonText}>Call ({debtor.phoneNumber})</Text>
                  </TouchableOpacity>
                )}
              </View>
            ))
          )}

          <View style={{ height: 110 }} />
        </PullToRefreshScrollView>
      )}
    </View>
  );
};

