import React from 'react';
import {
  View,
  Text,
  Image,
  ImageSourcePropType,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { CameraIcon, UserIcon } from '@mfe/assets/icons/CommonIcons';

export interface CircleProfileAvatarProps {
  source?: ImageSourcePropType | string;
  name?: string;
  size?: number; // e.g. 48, 72, 96
  showEditBadge?: boolean;
  onEditPress?: () => void;
  onPress?: () => void;
  style?: ViewStyle;
  testID?: string;
}

export const CircleProfileAvatar: React.FC<CircleProfileAvatarProps> = ({
  source,
  name,
  size = 72,
  showEditBadge = false,
  onEditPress,
  onPress,
  style,
  testID = 'circle-profile-avatar',
}) => {
  const { theme } = useTheme();

  const getInitials = (fullName?: string) => {
    if (!fullName) return '';
    const parts = fullName.trim().split(/\s+/);
    if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
    return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
  };

  const badgeSize = Math.max(24, Math.round(size * 0.32));
  const iconSize = Math.round(badgeSize * 0.55);

  const content = (
    <View
      testID={testID}
      style={[
        styles.avatarContainer,
        {
          width: size,
          height: size,
          borderRadius: size / 2,
          backgroundColor: theme.colors.primaryLight,
          borderColor: theme.colors.border,
        },
        style,
      ]}
    >
      {source ? (
        <Image
          testID={`${testID}-image`}
          source={typeof source === 'string' ? { uri: source } : source}
          style={{ width: size, height: size, borderRadius: size / 2 }}
          resizeMode="cover"
        />
      ) : name ? (
        <Text
          testID={`${testID}-initials`}
          style={[
            styles.initialsText,
            {
              fontSize: Math.round(size * 0.38),
              color: theme.colors.primary,
              fontFamily: theme.typography.fontFamilyBold,
            },
          ]}
        >
          {getInitials(name)}
        </Text>
      ) : (
        <UserIcon size={Math.round(size * 0.55)} color={theme.colors.primary} />
      )}

      {showEditBadge ? (
        <TouchableOpacity
          testID={`${testID}-edit-badge`}
          activeOpacity={0.8}
          onPress={onEditPress || onPress}
          style={[
            styles.editBadge,
            {
              width: badgeSize,
              height: badgeSize,
              borderRadius: badgeSize / 2,
              backgroundColor: theme.colors.primary,
            },
          ]}
        >
          <CameraIcon size={iconSize} color="#FFFFFF" />
        </TouchableOpacity>
      ) : null}
    </View>
  );

  if (onPress && !showEditBadge) {
    return (
      <TouchableOpacity activeOpacity={0.8} onPress={onPress}>
        {content}
      </TouchableOpacity>
    );
  }

  return content;
};

const styles = StyleSheet.create({
  avatarContainer: {
    justifyContent: 'center',
    alignItems: 'center',
    borderWidth: 1.5,
    position: 'relative',
  },
  initialsText: {
    fontWeight: '700',
  },
  editBadge: {
    position: 'absolute',
    bottom: 0,
    right: 0,
    justifyContent: 'center',
    alignItems: 'center',
    borderWidth: 2,
    borderColor: '#FFFFFF',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.15,
    shadowRadius: 4,
    elevation: 3,
  },
});

