import React from 'react';
import { StatusBar, StyleSheet, useColorScheme, View } from 'react-native';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import { NavigationContainer } from '@react-navigation/native';
import { I18nProvider } from '@mfe/core/i18n';
import { ThemeProvider } from '@mfe/theme';
import { RootNavigator } from './navigation/RootNavigator';
import { GlobalModalHost } from '@mfe/ui-components/modals';
import { LogConsole, ToastContainer } from '@mfe/ui-components';
import {
  useFourFingerDevConsole,
  useDeviceLoginPushSecurity,
  useNotificationDeepLinking,
  useGlobalActivityTelemetry,
  useGlobalPluginEvents,
} from '@mfe/ui-components/hooks';
import { navigationRef, NotificationRoutingService } from '@mfe/core/services';
import { hideSplashScreen } from 'react-native-bizmob-plugin';

// ==============================================================================
// 🛠️ ISOLATED REMOTE DEV SWITCH FOR FAST MOBILE DEVELOPMENT:
// ------------------------------------------------------------------------------
// Set to any remote name to boot ONLY that module on Android/iOS (Metro builds in ~2s):
//   - 'remote-notification'       : NTF0001 / NTF0002 Notification Center
//   - 'remote-dashboard'          : DAS0001 / APR0001 Dashboard & Approvals
//   - 'remote-showcase'           : Showcase UI Catalog & BizMOB SDK Features
//   - 'remote-launch-auth'        : Splash, Language, PIN & Biometric Auth
//   - 'remote-customer'           : CIF Registration & Profile Gateway
//   - 'remote-loan-origination'   : Loan Calculator & Underwriting Entry
//   - null                        : Run the FULL production application flow
// ==============================================================================
export type DevIsolatedRemote =
  | 'remote-notification'
  | 'remote-dashboard'
  | 'remote-showcase'
  | 'remote-launch-auth'
  | 'remote-customer'
  | 'remote-loan-origination'
  | null;

export const DEV_ISOLATED_REMOTE: DevIsolatedRemote = null;

function App() {
  const isDarkMode = useColorScheme() === 'dark';
  const { panHandlers } = useFourFingerDevConsole();
  useDeviceLoginPushSecurity();
  useNotificationDeepLinking();
  useGlobalPluginEvents();
  const { handleNavigationReady, handleNavigationStateChange } = useGlobalActivityTelemetry();

  // 1. Isolated Dev Mode: lazily require ONLY the chosen remote so unused remotes
  //    are never evaluated during normal app startup.
  const isDevMode = typeof __DEV__ !== 'undefined' ? __DEV__ : process.env.NODE_ENV !== 'production';
  if (isDevMode && DEV_ISOLATED_REMOTE) {
    let content: React.ReactNode = null;
    switch (DEV_ISOLATED_REMOTE) {
      case 'remote-notification': {
        const { NotificationStandaloneApp } = require('@mfe/remote-notification');
        content = <NotificationStandaloneApp />;
        break;
      }
      case 'remote-dashboard': {
        const { DashboardStandaloneApp } = require('@mfe/remote-dashboard');
        content = <DashboardStandaloneApp />;
        break;
      }
      case 'remote-showcase': {
        const { ShowcaseStandaloneApp } = require('@mfe/remote-showcase');
        content = <ShowcaseStandaloneApp />;
        break;
      }
      case 'remote-launch-auth': {
        const { LaunchAuthStandaloneApp } = require('@mfe/remote-launch-auth');
        content = <LaunchAuthStandaloneApp />;
        break;
      }
      case 'remote-customer': {
        const { CustomerStandaloneApp } = require('@mfe/remote-customer');
        content = <CustomerStandaloneApp />;
        break;
      }
      case 'remote-loan-origination': {
        const { LoanOriginationStandaloneApp } = require('@mfe/remote-loan-origination');
        content = <LoanOriginationStandaloneApp />;
        break;
      }
      default:
        break;
    }
    if (content) {
      return (
        <View style={styles.container} {...panHandlers}>
          {content}
        </View>
      );
    }
  }

  // 2. Full Application Flow (Splash -> Auth -> Dashboard -> Remote Navigators)
  return (
    <SafeAreaProvider>
      <ThemeProvider>
        <I18nProvider initialLanguage="km">
          <StatusBar barStyle={isDarkMode ? 'light-content' : 'dark-content'} />
          <NavigationContainer
            ref={navigationRef}
            onReady={() => {
              handleNavigationReady();
              NotificationRoutingService.flushPendingNotification();
            }}
            onStateChange={handleNavigationStateChange}
          >
            <View style={styles.container} {...panHandlers}>
              <RootNavigator
                onInitialRouteReady={() => {
                  // Dismiss native splash overlay only after RootNavigator resolves initialRoute and paints
                  hideSplashScreen({ duration: 100 }).catch(() => { });
                }}
              />
            </View>
          </NavigationContainer>
          <GlobalModalHost />
          <ToastContainer testID="global-toast-container" />
          {/* Global In-App Log Console with floating bottomsheet trigger */}
          <LogConsole extended={true} />
        </I18nProvider>
      </ThemeProvider>
    </SafeAreaProvider>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
});

export default App;
