import React, { useRef, useEffect } from 'react';
import {
  View,
  Text,
  ScrollView,
  TouchableOpacity,
  StyleSheet,
  NativeSyntheticEvent,
  NativeScrollEvent,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export interface WheelItem {
  key: string | number;
  value: string | number;
  label?: string;
}

export interface WheelPickerProps {
  items: WheelItem[];
  selectedValue: string | number;
  onValueChange: (item: WheelItem, index: number) => void;
  itemHeight?: number;
  visibleItems?: number;
  testID?: string;
}

/**
 * Native iOS / Android Wheel Spinner Picker matching DBCS LOS bm-looping-scroll.vue.
 * Features center selection highlight bar, top & bottom fade masks, and magnetic snap scrolling.
 */
export const WheelPicker: React.FC<WheelPickerProps> = ({
  items,
  selectedValue,
  onValueChange,
  itemHeight = 44,
  visibleItems = 5,
  testID = 'wheel-picker',
}) => {
  const { theme } = useTheme();
  const scrollRef = useRef<ScrollView>(null);
  const containerHeight = itemHeight * visibleItems;

  const selectedIndex = items.findIndex(
    (it) => it.key === selectedValue || it.value === selectedValue
  );
  const currentIndex = selectedIndex >= 0 ? selectedIndex : 0;

  const padCount = Math.floor(visibleItems / 2);

  // Pad the items list with dummy placeholders at the beginning and end
  // This guarantees identical height geometry on Web, iOS, and Android
  const paddedItems: (WheelItem | null)[] = [
    ...Array(padCount).fill(null),
    ...items,
    ...Array(padCount).fill(null),
  ];

  const scrollToTarget = (index: number, animated = true) => {
    const clampedIndex = Math.max(0, Math.min(items.length - 1, index));
    const targetY = clampedIndex * itemHeight;
    scrollRef.current?.scrollTo({
      y: targetY,
      animated,
    });
  };

  useEffect(() => {
    if (currentIndex >= 0 && scrollRef.current) {
      // In web and bottom sheets, initial layout needs a tiny moment or double-tick to scroll accurately
      const t1 = setTimeout(() => scrollToTarget(currentIndex, false), 10);
      const t2 = setTimeout(() => scrollToTarget(currentIndex, true), 120);
      return () => {
        clearTimeout(t1);
        clearTimeout(t2);
      };
    }
  }, [currentIndex, itemHeight, items.length]);

  const handleScrollEnd = (
    e: NativeSyntheticEvent<NativeScrollEvent>
  ) => {
    const offsetY = e.nativeEvent.contentOffset.y;
    const index = Math.round(offsetY / itemHeight);
    const clampedIndex = Math.max(0, Math.min(items.length - 1, index));
    // Magnetic snap to exact center
    scrollToTarget(clampedIndex, true);
    if (items[clampedIndex] && clampedIndex !== currentIndex) {
      onValueChange(items[clampedIndex], clampedIndex);
    }
  };

  return (
    <View
      testID={testID}
      style={[styles.container, { height: containerHeight }]}
    >
      {/* Selection Center Highlight Bar */}
      <View
        pointerEvents="none"
        style={[
          styles.selectionBar,
          {
            top: itemHeight * padCount,
            height: itemHeight,
            borderColor: theme.colors.border || '#E5E7EB',
            backgroundColor: '#F3F4F6',
          },
        ]}
      />

      {/* Top Gradient Shadow Mask */}
      <View
        pointerEvents="none"
        style={[
          styles.topFade,
          { height: itemHeight * padCount },
        ]}
      />

      {/* Bottom Gradient Shadow Mask */}
      <View
        pointerEvents="none"
        style={[
          styles.bottomFade,
          { height: itemHeight * padCount },
        ]}
      />

      {/* Scrollable list */}
      <ScrollView
        ref={scrollRef}
        showsVerticalScrollIndicator={false}
        snapToInterval={itemHeight}
        decelerationRate="fast"
        scrollEventThrottle={16}
        onMomentumScrollEnd={handleScrollEnd}
        onScrollEndDrag={handleScrollEnd}
      >
        {paddedItems.map((item, padIdx) => {
          if (!item) {
            return (
              <View
                key={`pad-${padIdx}`}
                style={[styles.itemRow, { height: itemHeight }]}
              />
            );
          }

          const actualIndex = padIdx - padCount;
          const isSelected = actualIndex === currentIndex;

          return (
            <TouchableOpacity
              key={`${item.key}-${actualIndex}`}
              testID={`${testID}-item-${item.key}`}
              activeOpacity={0.8}
              onPress={() => {
                scrollToTarget(actualIndex, true);
                onValueChange(item, actualIndex);
              }}
              style={[styles.itemRow, { height: itemHeight }]}
            >
              <Text
                style={[
                  styles.itemText,
                  {
                    height: itemHeight,
                    lineHeight: itemHeight,
                    color: isSelected ? theme.colors.primary : '#6B7280',
                    fontSize: isSelected ? 17 : 14,
                    fontWeight: isSelected ? '800' : '500',
                  },
                ]}
              >
                {item.label || item.value}
              </Text>
            </TouchableOpacity>
          );
        })}
      </ScrollView>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    position: 'relative',
    overflow: 'hidden',
    width: '100%',
  },
  selectionBar: {
    position: 'absolute',
    left: 0,
    right: 0,
    borderTopWidth: 1,
    borderBottomWidth: 1,
    borderRadius: 8,
    zIndex: 1,
    opacity: 0.85,
  },
  topFade: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    backgroundColor: '#FFFFFF',
    opacity: 0.7,
    zIndex: 2,
  },
  bottomFade: {
    position: 'absolute',
    bottom: 0,
    left: 0,
    right: 0,
    backgroundColor: '#FFFFFF',
    opacity: 0.7,
    zIndex: 2,
  },
  itemRow: {
    justifyContent: 'center',
    alignItems: 'center',
    paddingHorizontal: 8,
    zIndex: 3,
  },
  itemText: {
    textAlign: 'center',
  },
});

