import React, { useState } from 'react';
import { View, Text, StyleSheet } from 'react-native';
import {
  AppCard,
  AppButton,
  AppAlertModal,
  AppBottomSheet,
  ToggleSwitch,
  StatusBadge,
  ImageConfirmModal,
  ImageConfirmVisualType,
  ImageConfirmPreset,
  DialogUtil,
  CommentListModal,
  CommentItem,
  DropdownModal,
  DropdownSelectField,
  DropdownOption,
} from '@mfe/ui-components/components';
import { useTheme } from '@mfe/core/theme';
import { CodeBlock } from '../../components/CodeBlock';
import { CODE_SNIPPETS } from '../../constants/codeSnippets';

export interface ModalsDetailSectionProps {
  onOpenDialog: () => void;
}

export const ModalsDetailSection: React.FC<ModalsDetailSectionProps> = ({
  onOpenDialog,
}) => {
  const { theme, updateTheme } = useTheme();

  // Modal visibility states
  const [alertVisible, setAlertVisible] = useState(false);
  const [sheetVisible, setSheetVisible] = useState(false);

  // Image confirm modal states
  const [imageConfirmVisible, setImageConfirmVisible] = useState(false);
  const [confirmImageType, setConfirmImageType] = useState<ImageConfirmVisualType>('big');
  const [confirmPreset, setConfirmPreset] = useState<ImageConfirmPreset>('loan-doc');
  const [lastFeedback, setLastFeedback] = useState<string>('');

  // Comment list modal state
  const [commentsVisible, setCommentsVisible] = useState(false);
  const [comments, setComments] = useState<CommentItem[]>([
    {
      id: '1',
      authorName: 'Underwriter',
      authorInitials: 'UW',
      message: 'The portrait photo is blurry, please retake it and add the salary statement.',
      timestamp: '31/10 09:02',
      replies: [
        {
          id: '1-1',
          authorName: 'Nguyễn Sales',
          authorInitials: 'NS',
          message: 'Contacted the customer, will submit everything this afternoon.',
          timestamp: '31/10 10:30',
        },
      ],
    },
    {
      id: '2',
      authorName: 'Lê Quản Lý',
      authorInitials: 'QL',
      message: 'Please handle within the day.',
      timestamp: '31/10 11:05',
    },
  ]);

  // Dropdown / Value Picker (M7) state
  const [selectedWard, setSelectedWard] = useState<string>('sai-gon');
  const [standaloneDropdownVisible, setStandaloneDropdownVisible] = useState(false);

  const wardOptions: DropdownOption<string>[] = [
    { label: 'Bến Thành Ward', value: 'ben-thanh' },
    { label: 'Sài Gòn Ward', value: 'sai-gon' },
    { label: 'Tân Định Ward', value: 'tan-dinh' },
    { label: 'Cầu Ông Lãnh Ward', value: 'cau-ong-lanh' },
    { label: 'Bàn Cờ Ward', value: 'ban-co' },
    { label: 'Đa Kao Ward', value: 'da-kao' },
    { label: 'Nguyễn Cư Trinh Ward', value: 'nguyen-cu-trinh' },
  ];

  // Global modal options
  const isGlobalBlur = theme.modal?.bottomSheetBackdropBlur ?? false;
  const isGlobalDraggable = theme.modal?.bottomSheetDraggable ?? true;

  return (
    <View testID="detail-modals">
      <CodeBlock code={CODE_SNIPPETS.MODALS} title="Universal Alert & BottomSheet Usage" />

      {/* Global Settings Control */}
      <AppCard style={styles.configCard}>
        <Text style={styles.detailHeader}>Global Modal Configuration</Text>
        <Text style={styles.helperText}>
          Configure blur effect and gesture dragging across all wrapped dialogs and sheets in the app.
        </Text>

        <View style={styles.toggleRow}>
          <ToggleSwitch
            label="Enable Backdrop Blur (Global)"
            description="Applies frosted glass backdrop blur behind modals and bottom sheets"
            value={isGlobalBlur}
            onValueChange={(val) => {
              updateTheme({
                modal: {
                  alertBackdropBlur: val,
                  bottomSheetBackdropBlur: val,
                },
              });
            }}
          />
        </View>

        <View style={styles.toggleRow}>
          <ToggleSwitch
            label="Draggable Bottom Sheet (Global)"
            description="Allows pulling down the sheet handle bar to dismiss"
            value={isGlobalDraggable}
            onValueChange={(val) => {
              updateTheme({
                modal: {
                  bottomSheetDraggable: val,
                },
              });
            }}
          />
        </View>
      </AppCard>

      {/* Trigger Buttons Card */}
      <AppCard>
        <Text style={styles.detailHeader}>Universal Wrapper Modals</Text>
        <Text style={styles.helperText}>
          Wrap any screen, form, or custom component inside `AppAlertModal` or `AppBottomSheet`.
        </Text>

        <View style={styles.buttonCol}>
          <AppButton
            title="Open AppAlertModal (Alert Wrapper)"
            variant="primary"
            onPress={() => setAlertVisible(true)}
            testID="open-alert-modal-btn"
          />

          <View style={{ height: 10 }} />

          <AppButton
            title="Open AppBottomSheet (Drag / Blur Sheet)"
            variant="outline"
            onPress={() => setSheetVisible(true)}
            testID="open-bottom-sheet-btn"
          />

          <View style={{ height: 10 }} />

          <AppButton
            title="Open Standard ConfirmDialog (COM*)"
            variant="text"
            onPress={onOpenDialog}
            testID="open-dialog-btn"
          />

          <View style={{ height: 16 }} />

          <Text style={[styles.detailHeader, { fontSize: 14, marginBottom: 8 }]}>
            Imperative DialogUtil (Alert / Confirm / BottomSheet as Util)
          </Text>

          <AppButton
            title="DialogUtil.alert(...) [Scrollable Message]"
            variant="outline"
            onPress={() => {
              DialogUtil.alert({
                title: 'Compliance & Verification Notice',
                message:
                  'Customer verification for KYC tier 2 requires in-person biometrics or valid National ID. ' +
                  'Please review the underwriting standards in section 4.2 before approving higher loan bounds.\n\n' +
                  '1. Verified Primary Address\n' +
                  '2. Employment Verification Document\n' +
                  '3. Credit Bureau Report within 30 days\n' +
                  '4. Debt Service Coverage Ratio (DSCR) >= 1.25\n\n' +
                  'All documents must be signed and retained in compliance with regional banking regulations.',
              });
            }}
            testID="open-util-alert-btn"
          />

          <View style={{ height: 10 }} />

          <AppButton
            title="DialogUtil.confirm(...) [Promise-based]"
            variant="outline"
            onPress={async () => {
              const confirmed = await DialogUtil.confirm({
                title: 'Cancel Loan Application?',
                message: 'All unsaved loan origination drafts and uploaded attachments will be lost.',
                isDestructive: true,
                confirmLabel: 'Discard Application',
                cancelLabel: 'Keep Editing',
              });
              setLastFeedback(`DialogUtil.confirm returned: ${confirmed ? 'CONFIRMED' : 'CANCELLED'}`);
            }}
            testID="open-util-confirm-btn"
          />

          <View style={{ height: 10 }} />

          <AppButton
            title="DialogUtil.bottomSheet(...) [Imperative Sheet]"
            variant="outline"
            onPress={() => {
              DialogUtil.bottomSheet({
                title: 'Quick Filter & Options',
                content: (
                  <View style={{ padding: 16 }}>
                    <Text style={{ fontSize: 15, fontWeight: '600', marginBottom: 12 }}>
                      Select Branch Location
                    </Text>
                    <Text style={{ color: '#6B7280', marginBottom: 16 }}>
                      Imperatively opened bottom sheet via DialogUtil.bottomSheet({'{ ... }'}).
                    </Text>
                    <AppButton
                      title="Apply Filter"
                      variant="primary"
                      onPress={() => DialogUtil.close()}
                    />
                  </View>
                ),
              });
            }}
            testID="open-util-bottomsheet-btn"
          />
        </View>
      </AppCard>

      {/* Application comments (CommentListModal) */}
      <AppCard style={{ marginTop: 12 }}>
        <Text style={styles.detailHeader}>Application comments (CommentListModal)</Text>
        <Text style={styles.helperText}>
          Threaded comment bottom sheet with avatar initials, timestamps, Reply action and a pinned composer.
        </Text>
        <AppButton
          title="Open Comments"
          variant="primary"
          size="small"
          onPress={() => setCommentsVisible(true)}
          testID="open-comments-btn"
        />
        <CommentListModal
          visible={commentsVisible}
          onClose={() => setCommentsVisible(false)}
          comments={comments}
          onSend={(text, parentId) => {
            const entry: CommentItem = {
              id: `c${Date.now()}`,
              authorName: 'Me',
              message: text,
              timestamp: 'Now',
            };
            setComments((prev) =>
              parentId
                ? prev.map((c) => (c.id === parentId ? { ...c, replies: [...(c.replies ?? []), entry] } : c))
                : [...prev, entry],
            );
          }}
        />
      </AppCard>

      {/* Value Picker (DropdownModal - M7) */}
      <AppCard style={{ marginTop: 12 }}>
        <Text style={styles.detailHeader}>Value Picker (DropdownModal - M7)</Text>
        <Text style={styles.helperText}>
          BottomSheet picker for single/paginated selection with search bar, red active highlight with checkmark (✓), and footer notes.
        </Text>

        <View style={{ marginVertical: 8 }}>
          <DropdownSelectField
            label="Ward/Commune (Form Field Demo)"
            value={selectedWard}
            options={wardOptions}
            onSelect={(val) => setSelectedWard(val)}
            placeholder="Select ward/commune"
            title="Select ward/commune"
            searchPlaceholder="Search"
            footerNote="List from getWard, paginated by getPickerPaging."
            testID="demo-ward-select-field"
          />
        </View>

        <View style={{ height: 6 }} />

        <AppButton
          title="Open Standalone DropdownModal"
          variant="outline"
          size="small"
          onPress={() => setStandaloneDropdownVisible(true)}
          testID="open-standalone-dropdown-btn"
        />

        <DropdownModal
          visible={standaloneDropdownVisible}
          onClose={() => setStandaloneDropdownVisible(false)}
          title="Select ward/commune"
          options={wardOptions}
          selectedValue={selectedWard}
          onSelect={(val) => setSelectedWard(val)}
          searchPlaceholder="Search"
          footerNote="List from getWard, paginated by getPickerPaging."
          testID="demo-standalone-dropdown-modal"
        />
      </AppCard>

      {/* Image Confirm Modal Demo (ML-003, GL-06, GL-02) */}
      <AppCard style={{ marginTop: 12 }}>
        <Text style={styles.detailHeader}>Image / Icon Confirmation Modal</Text>
        <Text style={styles.helperText}>
          Supports Big 3D hero illustrations (e.g. ML-003 Incomplete Loan Application), Small badges (warning/info), or standard circular Icon dialogs with dual buttons and optional &quot;Do not show again&quot; checkbox.
        </Text>

        <View style={styles.buttonCol}>
          <AppButton
            title="Open Incomplete Loan Application (Big 3D Image)"
            variant="primary"
            onPress={() => {
              setConfirmImageType('big');
              setConfirmPreset('loan-doc');
              setImageConfirmVisible(true);
            }}
            testID="open-big-image-confirm-btn"
          />

          <View style={{ height: 10 }} />

          <AppButton
            title="Open Top-up Offer (Expanded Height - ML-004)"
            variant="primary"
            onPress={() => {
              setConfirmImageType('big');
              setConfirmPreset('popper');
              setImageConfirmVisible(true);
            }}
            testID="open-topup-image-confirm-btn"
          />

          <View style={{ height: 10 }} />

          <AppButton
            title="Open Interest Rate Warning (Small Illustration)"
            variant="outline"
            onPress={() => {
              setConfirmImageType('small');
              setConfirmPreset('warning');
              setImageConfirmVisible(true);
            }}
            testID="open-small-image-confirm-btn"
          />

          <View style={{ height: 10 }} />

          <AppButton
            title="Open Sign Out Confirmation (Circular Icon)"
            variant="text"
            onPress={() => {
              setConfirmImageType('icon');
              setConfirmPreset('logout');
              setImageConfirmVisible(true);
            }}
            testID="open-icon-image-confirm-btn"
          />

          {lastFeedback ? (
            <View style={{ marginTop: 10 }}>
              <StatusBadge label={lastFeedback} variant="info" />
            </View>
          ) : null}
        </View>
      </AppCard>

      {/* 1. AppAlertModal Demo */}
      <AppAlertModal
        visible={alertVisible}
        title="Custom Loan Calculation Alert"
        onClose={() => setAlertVisible(false)}
        testID="demo-alert-modal"
      >
        <View style={styles.modalBody}>
          <StatusBadge label="Instant Pre-Approval" variant="success" />
          <Text style={styles.modalText}>
            You can wrap any component, form, or calculator inside this `AppAlertModal`. It automatically obeys the global backdrop blur configuration.
          </Text>
          <View style={styles.actionRow}>
            <AppButton
              title="Close Modal"
              variant="primary"
              size="small"
              onPress={() => setAlertVisible(false)}
            />
          </View>
        </View>
      </AppAlertModal>

      {/* 2. AppBottomSheet Demo */}
      <AppBottomSheet
        visible={sheetVisible}
        title="Repayment Schedule Details"
        onClose={() => setSheetVisible(false)}
        testID="demo-bottom-sheet"
      >
        <View style={styles.modalBody}>
          <Text style={styles.modalText}>
            This `AppBottomSheet` is fully configurable:
          </Text>
          <View style={styles.bulletList}>
            <Text style={styles.bulletItem}>• Pull down on the drag handle bar to dismiss with bounce animation.</Text>
            <Text style={styles.bulletItem}>• Frosted glass backdrop blur ({isGlobalBlur ? 'Active' : 'Inactive'}).</Text>
            <Text style={styles.bulletItem}>• Wraps any dynamic React Native tree.</Text>
          </View>
          <View style={styles.actionRow}>
            <AppButton
              title="Done"
              variant="primary"
              size="small"
              onPress={() => setSheetVisible(false)}
            />
          </View>
        </View>
      </AppBottomSheet>

      {/* 3. ImageConfirmModal Demo */}
      <ImageConfirmModal
        visible={imageConfirmVisible}
        onClose={() => setImageConfirmVisible(false)}
        imageType={confirmImageType}
        preset={confirmPreset}
        buttonLayout={confirmPreset === 'popper' ? 'column' : 'row'}
        confirmButtonColor={confirmPreset === 'popper' ? '#E7252B' : undefined}
        title={
          confirmPreset === 'popper'
            ? 'Congratulations!'
            : confirmImageType === 'big'
            ? 'Incomplete loan application'
            : confirmImageType === 'small'
            ? 'Interest Rate Warning'
            : 'Sign Out Confirmation'
        }
        message={
          confirmPreset === 'popper'
            ? 'You are eligible for a loan of up to'
            : confirmImageType === 'big'
            ? "Your loan application is almost complete. Continue now so you don't miss the offer."
            : confirmImageType === 'small'
            ? 'Unticking credit life insurance may increase the nominal interest rate by 1.5% APR.'
            : 'Are you sure you want to sign out from your account?'
        }
        confirmText={
          confirmPreset === 'popper'
            ? 'Apply for a loan now'
            : confirmImageType === 'big'
            ? 'Continue'
            : confirmImageType === 'small'
            ? 'I Understand'
            : 'Sign Out'
        }
        cancelText={confirmImageType === 'small' ? undefined : confirmPreset === 'popper' ? 'Close' : 'Cancel'}
        showDoNotShowAgain={confirmImageType === 'big'}
        doNotShowAgainText="Do not show this notice again"
        isDestructive={confirmImageType === 'icon'}
        onConfirm={(doNotShow) => {
          setImageConfirmVisible(false);
          setLastFeedback(
            `Confirmed! (Do not show again: ${doNotShow ? 'Checked' : 'Unchecked'})`
          );
        }}
        onCancel={() => {
          setImageConfirmVisible(false);
          setLastFeedback('Cancelled dialog');
        }}
        testID="showcase-image-confirm-modal"
      >
        {confirmPreset === 'popper' ? (
          <View style={styles.topupContainer}>
            <Text style={styles.topupAmount}>500.000.000</Text>
            <Text style={styles.topupCurrency}>VND</Text>
            <Text style={styles.topupRateText}>
              Interest rate from only 1.50%/month,{'\n'}just provide your Citizen ID
            </Text>
          </View>
        ) : null}
      </ImageConfirmModal>
    </View>
  );
};

const styles = StyleSheet.create({
  configCard: {
    marginBottom: 12,
  },
  detailHeader: {
    fontSize: 16,
    fontWeight: '700',
    color: '#16181D',
    marginBottom: 6,
  },
  helperText: {
    fontSize: 13,
    color: '#7B8494',
    marginBottom: 12,
  },
  toggleRow: {
    marginTop: 10,
  },
  buttonCol: {
    marginTop: 4,
  },
  modalBody: {
    paddingVertical: 8,
  },
  modalText: {
    fontSize: 14,
    color: '#374151',
    lineHeight: 20,
    marginTop: 8,
  },
  bulletList: {
    marginTop: 10,
    marginBottom: 14,
  },
  bulletItem: {
    fontSize: 13,
    color: '#4B5563',
    lineHeight: 20,
    marginBottom: 4,
  },
  actionRow: {
    marginTop: 12,
    alignItems: 'flex-end',
  },
  topupContainer: {
    alignItems: 'center',
    marginVertical: 4,
  },
  topupAmount: {
    fontSize: 28,
    fontWeight: '800',
    color: '#E7252B',
    lineHeight: 34,
  },
  topupCurrency: {
    fontSize: 22,
    fontWeight: '800',
    color: '#E7252B',
    marginBottom: 10,
  },
  topupRateText: {
    fontSize: 13,
    color: '#4B5565',
    textAlign: 'center',
    lineHeight: 18,
  },
});

