import React, { useCallback, useRef, useState } from 'react';
import {
  LayoutChangeEvent,
  NativeScrollEvent,
  NativeSyntheticEvent,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  useWindowDimensions,
  View,
  ViewStyle,
} from 'react-native';
import { useTheme, defaultTheme } from '@mfe/theme';
import { AppButton } from '../button/AppButton';

export interface OnboardingSlideItem {
  id: string;
  title: string;
  description: string;
  illustration?: React.ReactNode;
  badge?: string;
  backgroundColor?: string;
}

export interface OnboardingSliderProps {
  slides: OnboardingSlideItem[];
  onComplete: () => void;
  onSkip?: () => void;
  onSlideChange?: (index: number) => void;
  initialIndex?: number;
  showSkip?: boolean;
  skipLabel?: string;
  nextLabel?: string;
  doneLabel?: string;
  containerStyle?: ViewStyle;
  testID?: string;
}

export const OnboardingSlider: React.FC<OnboardingSliderProps> = ({
  slides,
  onComplete,
  onSkip,
  onSlideChange,
  initialIndex = 0,
  showSkip = true,
  skipLabel = 'Skip',
  nextLabel = 'Next',
  doneLabel = 'Get Started',
  containerStyle,
  testID = 'onboarding-slider',
}) => {
  const themeContext = useTheme();
  const theme = themeContext?.theme || defaultTheme;
  const { colors, spacing, radius, typography } = theme;
  const { width: windowWidth } = useWindowDimensions();

  const clampedInitial =
    slides.length > 0
      ? Math.max(0, Math.min(initialIndex, slides.length - 1))
      : 0;

  const [activeIndex, setActiveIndex] = useState<number>(clampedInitial);
  const [containerWidth, setContainerWidth] = useState<number>(windowWidth);
  const scrollViewRef = useRef<ScrollView | null>(null);

  const slideWidth = containerWidth > 0 ? containerWidth : windowWidth;
  const isLastSlide = slides.length > 0 && activeIndex >= slides.length - 1;

  const goToSlide = useCallback(
    (targetIndex: number) => {
      if (slides.length === 0) return;
      const clamped = Math.max(0, Math.min(targetIndex, slides.length - 1));
      setActiveIndex(clamped);
      onSlideChange?.(clamped);
      scrollViewRef.current?.scrollTo({
        x: clamped * slideWidth,
        animated: true,
      });
    },
    [slides.length, slideWidth, onSlideChange]
  );

  const handleLayout = (event: LayoutChangeEvent) => {
    const measuredWidth = event.nativeEvent.layout.width;
    if (measuredWidth > 0 && measuredWidth !== containerWidth) {
      setContainerWidth(measuredWidth);
      if (activeIndex > 0) {
        scrollViewRef.current?.scrollTo({
          x: activeIndex * measuredWidth,
          animated: false,
        });
      }
    }
  };

  const handleScrollEnd = (event: NativeSyntheticEvent<NativeScrollEvent>) => {
    if (slideWidth <= 0 || slides.length === 0) return;
    const offsetX = event.nativeEvent.contentOffset.x;
    const nextIndex = Math.max(
      0,
      Math.min(Math.round(offsetX / slideWidth), slides.length - 1)
    );
    if (nextIndex !== activeIndex) {
      setActiveIndex(nextIndex);
      onSlideChange?.(nextIndex);
    }
  };

  const handlePrimaryPress = () => {
    if (isLastSlide) {
      onComplete();
    } else {
      goToSlide(activeIndex + 1);
    }
  };

  const handleSkipPress = () => {
    if (onSkip) {
      onSkip();
    } else {
      onComplete();
    }
  };

  if (slides.length === 0) {
    return null;
  }

  return (
    <View
      testID={testID}
      onLayout={handleLayout}
      style={[
        styles.container,
        { backgroundColor: colors.card },
        containerStyle,
      ]}
    >
      {/* Top Bar with Skip Action */}
      <View
        style={[
          styles.topBar,
          { paddingHorizontal: spacing.xxl, paddingTop: spacing.lg },
        ]}
      >
        {showSkip && !isLastSlide ? (
          <TouchableOpacity
            testID={`${testID}-skip-btn`}
            onPress={handleSkipPress}
            activeOpacity={0.7}
            accessibilityRole="button"
            style={[
              styles.skipButton,
              { paddingVertical: spacing.xs, paddingHorizontal: spacing.sm },
            ]}
          >
            <Text
              style={[
                styles.skipText,
                {
                  color: colors.textMuted,
                  fontSize: typography.sizes.md,
                  fontFamily: typography.fontFamily,
                },
              ]}
            >
              {skipLabel}
            </Text>
          </TouchableOpacity>
        ) : (
          <View style={styles.skipPlaceholder} />
        )}
      </View>

      {/* Horizontal Paged Slides */}
      <ScrollView
        ref={scrollViewRef}
        testID={`${testID}-scroll`}
        horizontal
        pagingEnabled
        showsHorizontalScrollIndicator={false}
        bounces={false}
        onMomentumScrollEnd={handleScrollEnd}
        scrollEventThrottle={16}
        style={styles.scrollView}
        contentContainerStyle={styles.scrollContent}
      >
        {slides.map((slide, index) => (
          <View
            key={slide.id}
            testID={`${testID}-slide-${index}`}
            style={[
              styles.slide,
              {
                width: slideWidth,
                paddingHorizontal: spacing.xxl,
                backgroundColor: slide.backgroundColor || colors.card,
              },
            ]}
          >
            {slide.illustration ? (
              <View
                testID={`${testID}-slide-${index}-illustration`}
                style={[styles.illustrationContainer, { marginBottom: spacing.xxl }]}
              >
                {slide.illustration}
              </View>
            ) : null}

            {slide.badge ? (
              <View
                style={[
                  styles.badge,
                  {
                    backgroundColor: colors.primaryLight,
                    borderRadius: radius.full,
                    paddingHorizontal: spacing.md,
                    paddingVertical: spacing.xs,
                    marginBottom: spacing.md,
                  },
                ]}
              >
                <Text
                  style={[
                    styles.badgeText,
                    {
                      color: colors.primary,
                      fontSize: typography.sizes.xs,
                      fontFamily: typography.fontFamilyBold,
                    },
                  ]}
                >
                  {slide.badge}
                </Text>
              </View>
            ) : null}

            <Text
              testID={`${testID}-slide-${index}-title`}
              style={[
                styles.title,
                {
                  color: colors.text,
                  fontSize: typography.sizes.xxl,
                  fontFamily: typography.fontFamilyBold,
                  marginBottom: spacing.md,
                },
              ]}
            >
              {slide.title}
            </Text>

            <Text
              testID={`${testID}-slide-${index}-description`}
              style={[
                styles.description,
                {
                  color: colors.textMuted,
                  fontSize: typography.sizes.md,
                  fontFamily: typography.fontFamily,
                },
              ]}
            >
              {slide.description}
            </Text>
          </View>
        ))}
      </ScrollView>

      {/* Footer: Pagination Dots & Primary Action */}
      <View
        style={[
          styles.footer,
          {
            paddingHorizontal: spacing.xxl,
            paddingBottom: spacing.xxl,
            paddingTop: spacing.lg,
          },
        ]}
      >
        <View
          testID={`${testID}-pagination`}
          style={[styles.paginationRow, { marginBottom: spacing.xl, gap: spacing.sm }]}
        >
          {slides.map((slide, index) => {
            const isActive = index === activeIndex;
            return (
              <TouchableOpacity
                key={slide.id}
                testID={`${testID}-dot-${index}`}
                accessibilityRole="button"
                accessibilityLabel={`Go to slide ${index + 1}`}
                accessibilityState={{ selected: isActive }}
                onPress={() => goToSlide(index)}
                activeOpacity={0.8}
                style={[
                  styles.dot,
                  {
                    width: isActive ? 24 : 8,
                    borderRadius: radius.full,
                    backgroundColor: isActive ? colors.primary : colors.border,
                  },
                ]}
              />
            );
          })}
        </View>

        <AppButton
          testID={`${testID}-primary-btn`}
          title={isLastSlide ? doneLabel : nextLabel}
          onPress={handlePrimaryPress}
          variant="primary"
          size="lg"
          fullWidth
        />
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    width: '100%',
  },
  topBar: {
    flexDirection: 'row',
    justifyContent: 'flex-end',
    alignItems: 'center',
    minHeight: 40,
  },
  skipButton: {
    alignSelf: 'flex-end',
  },
  skipPlaceholder: {
    height: 28,
  },
  skipText: {
    fontWeight: '600',
  },
  scrollView: {
    flex: 1,
  },
  scrollContent: {
    flexGrow: 1,
  },
  slide: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
  },
  illustrationContainer: {
    alignItems: 'center',
    justifyContent: 'center',
    width: '100%',
  },
  badge: {
    alignSelf: 'center',
  },
  badgeText: {
    fontWeight: '700',
    letterSpacing: 0.4,
    textTransform: 'uppercase',
  },
  title: {
    fontWeight: '700',
    textAlign: 'center',
    lineHeight: 30,
  },
  description: {
    textAlign: 'center',
    lineHeight: 22,
    maxWidth: 320,
  },
  footer: {
    width: '100%',
  },
  paginationRow: {
    flexDirection: 'row',
    justifyContent: 'center',
    alignItems: 'center',
  },
  dot: {
    height: 8,
  },
});

export default OnboardingSlider;
