export interface LoginCredentials {
  userId: string;
  password: string;
  companyId?: string;
}

export interface LoginResult {
  success: boolean;
  requiresOtp?: boolean;
  requiresBiometricSetup?: boolean;
  requiresPasswordChange?: boolean;
  token?: string;
  userEmail?: string;
  userPhone?: string;
  errorMessage?: string;
}

export interface OtpVerificationPayload {
  userId: string;
  otpCode: string;
  channel: 'email' | 'sms' | 'admin';
}

export interface OtpVerificationResult {
  success: boolean;
  token?: string;
  errorMessage?: string;
}

export interface BiometricSetupResult {
  success: boolean;
  biometricEnabled: boolean;
  errorMessage?: string;
}

export class AuthValidator {
  static validateUserId(userId: string): { isValid: boolean; error?: string } {
    if (!userId || userId.trim().length === 0) {
      return { isValid: false, error: 'User ID is required.' };
    }
    if (userId.trim().length < 3) {
      return { isValid: false, error: 'User ID must be at least 3 characters.' };
    }
    return { isValid: true };
  }

  static validatePassword(password: string): { isValid: boolean; error?: string } {
    if (!password || password.length === 0) {
      return { isValid: false, error: 'Password is required.' };
    }
    if (password.length < 6) {
      return { isValid: false, error: 'Password must be at least 6 characters.' };
    }
    return { isValid: true };
  }

  static validateOtpCode(code: string): { isValid: boolean; error?: string } {
    if (!code || code.length === 0) {
      return { isValid: false, error: 'OTP code is required.' };
    }
    if (!/^\d{6}$/.test(code)) {
      return { isValid: false, error: 'OTP code must be exactly 6 digits.' };
    }
    return { isValid: true };
  }

  static validateCredentials(credentials: LoginCredentials): { isValid: boolean; error?: string } {
    const userCheck = this.validateUserId(credentials.userId);
    if (!userCheck.isValid) return userCheck;

    const passCheck = this.validatePassword(credentials.password);
    if (!passCheck.isValid) return passCheck;

    return { isValid: true };
  }
}
