import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  ActivityIndicator,
  StyleSheet,
  TouchableOpacity,
  Platform,
  Modal,
} from 'react-native';
import { LoadingUtil, LoadingState } from '@mfe/core/utils/loadingUtil';

export interface GlobalLoadingOverlayProps {
  testID?: string;
}

/**
 * Global Host/Root Loading Overlay component.
 * Subscribes to `LoadingUtil` events and renders a high-elevation backdrop
 * with spinner, message card, and cancelable options.
 *
 * Wire once at root shell or application layout: `<GlobalLoadingOverlay />`.
 */
export const GlobalLoadingOverlay: React.FC<GlobalLoadingOverlayProps> = ({
  testID = 'global-loading-overlay',
}) => {
  const [loadingState, setLoadingState] = useState<LoadingState>({
    visible: false,
    options: {},
  });

  useEffect(() => {
    const unsubscribe = LoadingUtil.subscribe((state) => {
      setLoadingState(state);
    });
    return () => {
      unsubscribe();
    };
  }, []);

  if (!loadingState.visible) {
    return null;
  }

  const { options } = loadingState;
  const isModal = options.variant !== 'transparent';
  const spinnerColor = options.color || '#E5252A';
  const size = options.size === 'small' ? 'small' : 'large';

  const handleBackdropPress = () => {
    if (options.cancelable) {
      if (options.onCancel) {
        options.onCancel();
      }
      LoadingUtil.hide();
    }
  };

  return (
    <Modal
      transparent={true}
      visible={loadingState.visible}
      animationType="fade"
      onRequestClose={handleBackdropPress}
    >
      <View
        style={[
          styles.overlayBackdrop,
          options.variant === 'transparent' && styles.transparentBackdrop,
        ]}
        testID={options.testID || testID}
      >
        <TouchableOpacity
          activeOpacity={1}
          style={styles.backdropTouchable}
          onPress={handleBackdropPress}
          testID={`${testID}-backdrop`}
        >
          <View
            style={[
              styles.cardBox,
              !options.message && styles.cardBoxIconOnly,
            ]}
            onStartShouldSetResponder={() => true}
            testID={`${testID}-card`}
          >
            <ActivityIndicator
              size={size}
              color={spinnerColor}
              testID={`${testID}-spinner`}
            />

            {options.message ? (
              <Text style={styles.messageText} testID={`${testID}-message`}>
                {options.message}
              </Text>
            ) : null}

            {options.subMessage ? (
              <Text
                style={styles.subMessageText}
                testID={`${testID}-submessage`}
              >
                {options.subMessage}
              </Text>
            ) : null}
          </View>
        </TouchableOpacity>
      </View>
    </Modal>
  );
};

const styles = StyleSheet.create({
  overlayBackdrop: {
    flex: 1,
    backgroundColor: 'rgba(0, 0, 0, 0.45)',
    justifyContent: 'center',
    alignItems: 'center',
    zIndex: 999999,
  },
  transparentBackdrop: {
    backgroundColor: 'transparent',
  },
  backdropTouchable: {
    flex: 1,
    width: '100%',
    height: '100%',
    justifyContent: 'center',
    alignItems: 'center',
  },
  cardBox: {
    backgroundColor: '#FFFFFF',
    borderRadius: 14,
    paddingVertical: 24,
    paddingHorizontal: 28,
    alignItems: 'center',
    justifyContent: 'center',
    minWidth: 160,
    maxWidth: 280,
    ...Platform.select({
      ios: {
        shadowColor: '#000',
        shadowOffset: { width: 0, height: 4 },
        shadowOpacity: 0.25,
        shadowRadius: 12,
      },
      android: {
        elevation: 8,
      },
      default: {
        boxShadow: '0 8px 24px rgba(0, 0, 0, 0.2)',
      },
    }),
  },
  cardBoxIconOnly: {
    paddingVertical: 20,
    paddingHorizontal: 20,
    minWidth: 80,
  },
  messageText: {
    fontSize: 15,
    fontWeight: '600',
    color: '#1F2937',
    textAlign: 'center',
    marginTop: 14,
    lineHeight: 20,
  },
  subMessageText: {
    fontSize: 12,
    color: '#6B7280',
    textAlign: 'center',
    marginTop: 4,
    lineHeight: 16,
  },
});
