import React, { useState } from 'react';
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  StyleSheet,
  TextInputProps,
} from 'react-native';

export interface AppTextInputProps extends Omit<TextInputProps, 'style'> {
  label: string;
  errorMessage?: string;
  helperText?: string;
  isPassword?: boolean;
  required?: boolean;
  testID?: string;
}

export const AppTextInput: React.FC<AppTextInputProps> = ({
  label,
  value,
  onChangeText,
  placeholder,
  errorMessage,
  helperText,
  isPassword = false,
  required = false,
  testID = 'app-text-input',
  ...rest
}) => {
  const [isFocused, setIsFocused] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  const hasError = !!errorMessage;

  return (
    <View style={styles.container} testID={testID}>
      <Text style={styles.label}>
        {label}
        {required && <Text style={styles.requiredAsterisk}> *</Text>}
      </Text>

      <View
        style={[
          styles.inputWrapper,
          isFocused && styles.inputWrapperFocused,
          hasError && styles.inputWrapperError,
        ]}
      >
        <TextInput
          testID={`${testID}-field`}
          style={styles.input}
          value={value}
          onChangeText={onChangeText}
          placeholder={placeholder}
          placeholderTextColor="#98A2B3"
          secureTextEntry={isPassword ? !showPassword : false}
          onFocus={(e) => {
            setIsFocused(true);
            if (rest.onFocus) rest.onFocus(e);
          }}
          onBlur={(e) => {
            setIsFocused(false);
            if (rest.onBlur) rest.onBlur(e);
          }}
          {...rest}
        />

        {isPassword && (
          <TouchableOpacity
            testID={`${testID}-toggle-visibility`}
            onPress={() => setShowPassword((prev) => !prev)}
            style={styles.toggleButton}
            hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
          >
            <Text style={styles.toggleText}>{showPassword ? 'HIDE' : 'SHOW'}</Text>
          </TouchableOpacity>
        )}
      </View>

      {hasError ? (
        <Text testID={`${testID}-error`} style={styles.errorText}>
          {errorMessage}
        </Text>
      ) : helperText ? (
        <Text style={styles.helperText}>{helperText}</Text>
      ) : null}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    marginBottom: 16,
  },
  label: {
    fontSize: 14,
    fontWeight: '500',
    color: '#344054',
    marginBottom: 6,
  },
  requiredAsterisk: {
    color: '#D92D20',
  },
  inputWrapper: {
    height: 48,
    borderWidth: 1,
    borderColor: '#D0D5DD',
    borderRadius: 8,
    backgroundColor: '#FFFFFF',
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 14,
  },
  inputWrapperFocused: {
    borderColor: '#004880',
    borderWidth: 1.5,
  },
  inputWrapperError: {
    borderColor: '#FDA29B',
    backgroundColor: '#FFFBFA',
  },
  input: {
    flex: 1,
    height: 48,
    fontSize: 15,
    color: '#101828',
    padding: 0,
    outlineWidth: 0,
    outlineStyle: 'none',
  } as any,
  toggleButton: {
    paddingLeft: 8,
  },
  toggleText: {
    fontSize: 12,
    fontWeight: '600',
    color: '#475467',
  },
  errorText: {
    fontSize: 12,
    color: '#D92D20',
    marginTop: 4,
  },
  helperText: {
    fontSize: 12,
    color: '#667085',
    marginTop: 4,
  },
});
