import React from 'react';
import { View, Text, TextInput, StyleSheet } from 'react-native';
import { FormatUtil } from '@mfe/core/utils/formatUtil';

export interface AmountInputProps {
  label?: string;
  value?: number | string;
  onChangeAmount?: (numericValue: number) => void;
  currency?: 'USD' | 'KHR' | 'VND';
  min?: number;
  max?: number;
  error?: string;
  testID?: string;
}

export const AmountInput: React.FC<AmountInputProps> = ({
  label,
  value = 0,
  onChangeAmount,
  currency = 'USD',
  min,
  max,
  error,
  testID = 'amount-input',
}) => {
  const numericVal = typeof value === 'number' ? value : FormatUtil.parseFormattedAmount(value || '0');
  const displayVal = FormatUtil.formatAmount(numericVal);

  const handleChangeText = (text: string) => {
    const rawNumber = FormatUtil.parseFormattedAmount(text);
    if (typeof onChangeAmount === 'function') {
      onChangeAmount(rawNumber);
    }
  };

  return (
    <View testID={testID} style={styles.container}>
      {label ? <Text style={styles.label}>{label}</Text> : null}
      <View style={[styles.inputRow, error ? styles.inputError : null]}>
        <TextInput
          testID={`${testID}-field`}
          value={displayVal}
          onChangeText={handleChangeText}
          keyboardType="numeric"
          style={styles.input}
        />
        <Text style={styles.currencySuffix}>{currency}</Text>
      </View>
      {error ? (
        <Text testID={`${testID}-error`} style={styles.errorText}>
          {error}
        </Text>
      ) : min !== undefined && max !== undefined ? (
        <Text style={styles.helperText}>
          Range: {FormatUtil.formatAmount(min)} - {FormatUtil.formatAmount(max)} {currency}
        </Text>
      ) : null}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    marginVertical: 8,
  },
  label: {
    fontSize: 13,
    fontWeight: '600',
    color: '#4D5563',
    marginBottom: 6,
  },
  inputRow: {
    flexDirection: 'row',
    alignItems: 'center',
    borderWidth: 1,
    borderColor: '#E2E5EB',
    borderRadius: 8,
    paddingHorizontal: 12,
    backgroundColor: '#FFFFFF',
  },
  inputError: {
    borderColor: '#E7252B',
  },
  input: {
    flex: 1,
    height: 48,
    fontSize: 18,
    fontWeight: '700',
    color: '#16181D',
    outlineWidth: 0,
    outlineStyle: 'none',
  } as any,
  currencySuffix: {
    fontSize: 15,
    fontWeight: '600',
    color: '#7B8494',
    marginLeft: 8,
  },
  errorText: {
    fontSize: 12,
    color: '#E7252B',
    marginTop: 4,
  },
  helperText: {
    fontSize: 11,
    color: '#7B8494',
    marginTop: 4,
  },
});

