import React from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
  StyleProp,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export interface PinAddressData {
  latitude: number;
  longitude: number;
  addressDetail?: string;
  accuracyMeters?: number;
}

export interface PinAddressFieldProps {
  label?: string;
  value?: PinAddressData;
  onPinPress: () => void;
  onClear?: () => void;
  disabled?: boolean;
  required?: boolean;
  style?: StyleProp<ViewStyle>;
  testID?: string;
}

/**
 * Enterprise GPS Geolocation & Pin Address Card matching DBCS LOS bm-pin-address.vue.
 * Provides live latitude/longitude display, address resolution, clear action,
 * and a dedicated Map Pin button for field loan officers performing collateral site visits.
 */
export const PinAddressField: React.FC<PinAddressFieldProps> = ({
  label = 'Collateral GPS Location',
  value,
  onPinPress,
  onClear,
  disabled = false,
  required = false,
  style,
  testID = 'pin-address-field',
}) => {
  const { theme } = useTheme();

  const hasLocation = value && (value.latitude !== 0 || value.longitude !== 0);

  return (
    <View testID={testID} style={[styles.container, style]}>
      {/* Label Row */}
      <View style={styles.labelRow}>
        <Text style={styles.label}>
          {label}
          {required ? <Text style={styles.requiredStar}> *</Text> : null}
        </Text>
      </View>

      {/* Main Container */}
      <View style={styles.row}>
        {/* Address Display Box */}
        <View
          style={[
            styles.infoBox,
            {
              borderColor: '#D1D5DB',
              backgroundColor: disabled ? '#F3F4F6' : '#FFFFFF',
            },
          ]}
        >
          {hasLocation ? (
            <View style={styles.contentWrap}>
              {value?.addressDetail ? (
                <Text style={styles.addressText} numberOfLines={2}>
                  {value.addressDetail}
                </Text>
              ) : null}
              <View style={styles.coordsRow}>
                <Text style={styles.coordText}>
                  Lat: <Text style={styles.coordVal}>{value?.latitude.toFixed(6)}</Text>
                </Text>
                <Text style={styles.coordText}>
                  Lng: <Text style={styles.coordVal}>{value?.longitude.toFixed(6)}</Text>
                </Text>
              </View>
              {value?.accuracyMeters ? (
                <Text style={styles.accuracyText}>Accuracy: ±{value.accuracyMeters}m</Text>
              ) : null}
            </View>
          ) : (
            <Text style={styles.placeholder}>
              Tap &quot;Pin GPS&quot; to capture site visit coordinates
            </Text>
          )}

          {/* Clear button if coordinates present */}
          {hasLocation && onClear && !disabled ? (
            <TouchableOpacity
              testID={`${testID}-clear-btn`}
              style={styles.clearBtn}
              onPress={onClear}
              activeOpacity={0.7}
            >
              <Text style={styles.clearText}>✕</Text>
            </TouchableOpacity>
          ) : null}
        </View>

        {/* Pin Location Action Button */}
        <TouchableOpacity
          testID={`${testID}-pin-btn`}
          disabled={disabled}
          onPress={onPinPress}
          activeOpacity={0.8}
          style={[
            styles.pinButton,
            {
              backgroundColor: disabled ? '#9CA3AF' : theme.colors.primary,
            },
          ]}
        >
          <Text style={styles.pinIcon}>📍</Text>
          <Text style={styles.pinText}>Pin GPS</Text>
        </TouchableOpacity>
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    width: '100%',
  },
  labelRow: {
    marginBottom: 6,
  },
  label: {
    fontSize: 14,
    fontWeight: '600',
    color: '#374151',
  },
  requiredStar: {
    color: '#EF4444',
  },
  row: {
    flexDirection: 'row',
    height: 84,
    gap: 10,
  },
  infoBox: {
    flex: 1,
    borderRadius: 10,
    borderWidth: 1,
    padding: 12,
    justifyContent: 'center',
    position: 'relative',
  },
  contentWrap: {
    paddingRight: 24,
  },
  addressText: {
    fontSize: 13,
    fontWeight: '700',
    color: '#1F2937',
    marginBottom: 4,
  },
  coordsRow: {
    flexDirection: 'row',
    gap: 12,
  },
  coordText: {
    fontSize: 12,
    color: '#6B7280',
  },
  coordVal: {
    fontWeight: '700',
    color: '#111827',
  },
  accuracyText: {
    fontSize: 11,
    color: '#059669',
    marginTop: 2,
    fontWeight: '600',
  },
  placeholder: {
    fontSize: 13,
    color: '#9CA3AF',
    fontStyle: 'italic',
  },
  clearBtn: {
    position: 'absolute',
    top: 8,
    right: 8,
    width: 24,
    height: 24,
    borderRadius: 12,
    backgroundColor: '#F3F4F6',
    justifyContent: 'center',
    alignItems: 'center',
  },
  clearText: {
    fontSize: 12,
    color: '#6B7280',
    fontWeight: '700',
  },
  pinButton: {
    width: 78,
    borderRadius: 10,
    justifyContent: 'center',
    alignItems: 'center',
    paddingHorizontal: 6,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 3,
    elevation: 2,
  },
  pinIcon: {
    fontSize: 22,
    marginBottom: 2,
  },
  pinText: {
    color: '#FFFFFF',
    fontSize: 12,
    fontWeight: '700',
  },
});

