import {
  openDatabase,
  executeSql,
  executeSelect,
} from 'react-native-bizmob-plugin';
import { OfflineItem, SEED_OFFLINE_ITEMS } from '../models/OfflineDataModel';

export const OFFLINE_DB_NAME = 'los_offline.db';

export class OfflineDataService {
  private static isInitialized = false;
  private static initPromise: Promise<void> | null = null;
  private static inMemoryCache: OfflineItem[] = [...SEED_OFFLINE_ITEMS];

  /**
   * Initializes the native SQLite database with AES encryption.
   * String columns (titles, details, phone, addresses) are encrypted using AES-CBC before
   * saving to disk, and automatically decrypted when queried with executeSelect.
   */
  static async initDatabase(): Promise<void> {
    if (this.isInitialized) return;
    if (this.initPromise) return this.initPromise;

    this.initPromise = (async () => {
      try {
        // 1. Open the database with encryption enabled
        await openDatabase({ db_name: OFFLINE_DB_NAME, encrypt: true });

        // 2. Create the offline_items table
        await executeSql({
          query: `CREATE TABLE IF NOT EXISTS offline_items (
            id TEXT PRIMARY KEY,
            type TEXT,
            title TEXT,
            subtitle TEXT,
            detail TEXT,
            phone TEXT,
            hours TEXT,
            date TEXT,
            location TEXT,
            isFavorite INTEGER
          )`,
          encrypt: true,
        });

        // 3. Check if table has been seeded
        const checkRes = await executeSelect({
          query: 'SELECT COUNT(*) as count FROM offline_items',
          encrypt: true,
        });

        const count =
          Number(
            (checkRes?.body?.rows?.[0] as any)?.count ??
              (checkRes?.body as any)?.count ??
              0
          ) || 0;

        if (count === 0) {
          for (const item of SEED_OFFLINE_ITEMS) {
            // String values are encrypted via bind_array with AES-CBC
            await executeSql({
              query: `INSERT OR REPLACE INTO offline_items (id, type, title, subtitle, detail, phone, hours, date, location, isFavorite)
                      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
              bind_array: [
                item.id,
                item.type,
                item.title,
                item.subtitle,
                item.detail,
                item.phone || '',
                item.hours || '',
                item.date || '',
                item.location || '',
                item.isFavorite ? 1 : 0,
              ],
              encrypt: true,
            });
          }
        }
        this.isInitialized = true;
      } catch (err) {
        console.warn('[OfflineDataService] Encrypted SQLite initialization warning:', err);
      } finally {
        this.initPromise = null;
      }
    })();

    return this.initPromise;
  }

  static async getItems(type?: 'BRANCH' | 'EVENT'): Promise<OfflineItem[]> {
    await this.initDatabase();
    try {
      // When filtering by encrypted column 'type', use bind_array so the WHERE value is matching encrypted ciphertext
      const query = type
        ? 'SELECT * FROM offline_items WHERE type = ? ORDER BY id ASC'
        : 'SELECT * FROM offline_items ORDER BY id ASC';
      const bind_array = type ? [type] : undefined;

      const res = await executeSelect<OfflineItem>({
        query,
        bind_array,
        encrypt: true,
      });

      if (res?.header?.result && res.body?.rows && res.body.rows.length > 0) {
        return res.body.rows.map((r: any) => ({
          ...r,
          isFavorite: Boolean(r.isFavorite),
        }));
      }
    } catch {
      // Fallback
    }
    return type
      ? this.inMemoryCache.filter((item) => item.type === type)
      : this.inMemoryCache;
  }

  static async getItemById(id: string): Promise<OfflineItem | null> {
    await this.initDatabase();
    try {
      const res = await executeSelect<OfflineItem>({
        query: 'SELECT * FROM offline_items WHERE id = ? LIMIT 1',
        bind_array: [id],
        encrypt: true,
      });
      if (res?.header?.result && res.body?.rows && res.body.rows.length > 0) {
        const item: any = res.body.rows[0];
        return {
          ...item,
          isFavorite: Boolean(item.isFavorite),
        };
      }
    } catch {
      // Fallback
    }
    return this.inMemoryCache.find((it) => it.id === id) || null;
  }

  static async toggleFavorite(id: string): Promise<boolean> {
    await this.initDatabase();
    const item = await this.getItemById(id);
    const newStatus = !item?.isFavorite;
    try {
      await executeSql({
        query: 'UPDATE offline_items SET isFavorite = ? WHERE id = ?',
        bind_array: [newStatus ? 1 : 0, id],
        encrypt: true,
      });
    } catch {
      // Memory fallback
    }
    const inMem = this.inMemoryCache.find((it) => it.id === id);
    if (inMem) inMem.isFavorite = newStatus;
    return newStatus;
  }
}
