import { NavigationService } from './NavigationService';
import { appLogger } from '../logger/AppLogger';
import { NotificationItem } from '../../../remotes/remote-notification/src/models/NotificationModel';

export type NotificationTarget =
  | 'NOTIFICATION_DETAIL'
  | 'NOTIFICATION_LIST'
  | 'APPROVAL_DETAIL'
  | 'PRODUCT_DETAIL'
  | 'FAQ_DETAIL'
  | 'TERMS_DETAIL'
  | 'SHOWCASE';

export interface PushNotificationPayload {
  target?: NotificationTarget | string;
  notificationId?: string;
  approvalId?: string;
  productId?: string;
  faqUrl?: string;
  deeplink?: string;
  title?: string;
  body?: string;
  [key: string]: any;
}

/**
 * NotificationRoutingService
 *
 * Handles deep link parsing and notification click dispatching to target screens:
 * - Notification Detail (`NotificationFlow` -> `NotificationDetail`)
 * - Approval Detail (`ApprovalDetail`)
 * - FAQ / Web Consent (`ShowcaseList` -> `ConsentWebViewScreen`)
 * - Product / Loan Detail (`DashboardFlow` -> `ProductDetail`)
 */
export class NotificationRoutingService {
  private static pendingPayload: PushNotificationPayload | null = null;

  /**
   * Dispatches navigation when a push notification is tapped or deep link is triggered.
   */
  public static handleNotificationClick(payload: PushNotificationPayload): boolean {
    if (!payload) return false;

    appLogger.info('NotificationRoutingService', 'Dispatching notification click', payload);

    // 1. If deeplink string format is passed (e.g. losapp://approval/APR0001)
    if (payload.deeplink) {
      return this.handleDeepLinkUrl(payload.deeplink);
    }

    // 2. Structured target routing
    const target = (payload.target || '').toUpperCase();

    switch (target) {
      case 'NOTIFICATION_DETAIL': {
        const item: NotificationItem = {
          id: payload.notificationId || `NTF-${Date.now()}`,
          title: payload.title || 'Notification Update',
          message: payload.body || 'You have a new update regarding your loan.',
          date: new Date().toISOString(),
          type: 'INFO',
          isRead: false,
        };

        return NavigationService.navigate('NotificationFlow' as any, {
          screen: 'NotificationDetail',
          params: { notification: item },
        });
      }

      case 'NOTIFICATION_LIST': {
        return NavigationService.navigate('NotificationFlow');
      }

      case 'APPROVAL_DETAIL': {
        const approvalId = payload.approvalId || payload.id || 'APR0001';
        return NavigationService.navigate('ApprovalDetail', { approvalId });
      }

      case 'FAQ_DETAIL':
      case 'TERMS_DETAIL': {
        return NavigationService.navigate('ShowcaseList' as any, {
          screen: 'ConsentWebViewScreen',
          params: {
            title: payload.title || 'FAQ & Terms',
            url: payload.faqUrl || 'https://lottefinance.vn/faq',
          },
        });
      }

      case 'SHOWCASE': {
        return NavigationService.navigate('ShowcaseList');
      }

      default: {
        // Fallback: If unknown target, open Notification List
        appLogger.warn('NotificationRoutingService', 'Unknown notification target, navigating to NotificationFlow', { target });
        return NavigationService.navigate('NotificationFlow');
      }
    }
  }

  /**
   * Parses and navigates from deep link URLs (e.g. losapp://approval/APR0001)
   */
  public static handleDeepLinkUrl(url: string): boolean {
    if (!url) return false;
    appLogger.info('NotificationRoutingService', 'Parsing deep link URL', { url });

    try {
      const cleanUrl = url.replace(/^[a-zA-Z0-9]+:\/\//, ''); // strip scheme (losapp://)
      const parts = cleanUrl.split('?')[0].split('/');
      const section = parts[0]?.toLowerCase();
      const id = parts[1];

      if (section === 'approval' && id) {
        return NavigationService.navigate('ApprovalDetail', { approvalId: id });
      }

      if (section === 'notification') {
        if (id) {
          const item: NotificationItem = {
            id,
            title: 'Notification Detail',
            message: 'Viewing notification from deep link',
            date: new Date().toISOString(),
            type: 'INFO',
            isRead: true,
          };
          return NavigationService.navigate('NotificationFlow' as any, {
            screen: 'NotificationDetail',
            params: { notification: item },
          });
        }
        return NavigationService.navigate('NotificationFlow');
      }

      if (section === 'showcase') {
        return NavigationService.navigate('ShowcaseList');
      }

      if (section === 'dashboard') {
        return NavigationService.navigate('DashboardFlow');
      }

      return false;
    } catch (error) {
      appLogger.error('NotificationRoutingService', 'Failed to parse deep link URL', error);
      return false;
    }
  }

  /**
   * Sets pending notification for cold-launch handling
   */
  public static setPendingNotification(payload: PushNotificationPayload | null): void {
    this.pendingPayload = payload;
  }

  /**
   * Consumes and routes the cold-launch pending notification if available
   */
  public static flushPendingNotification(): boolean {
    if (this.pendingPayload) {
      const payload = this.pendingPayload;
      this.pendingPayload = null;
      return this.handleNotificationClick(payload);
    }
    return false;
  }
}
