export interface INotificationService {
  getNotificationList(
    category?: NotificationCategory,
    useMock?: boolean,
    options?: { cache?: boolean; cacheTTLMs?: number; forceRefresh?: boolean }
  ): Promise<NotificationItem[]>;
  getNotificationDetail(
    id: string,
    useMock?: boolean,
    options?: { cache?: boolean; cacheTTLMs?: number; forceRefresh?: boolean }
  ): Promise<NotificationItem | null>;
  markAsRead(id: string): Promise<void>;
}

export class NotificationService implements INotificationService {
  private static instance: NotificationService;
  private networkService: INetworkService;
  private useMock: boolean;
  private readIds: Set<string> = new Set();

  constructor(
    networkService: INetworkService = defaultNetworkService,
    useMock: boolean = true
  ) {
    this.networkService = networkService;
    this.useMock = useMock;
  }

  public static getInstance(): NotificationService {
    if (!NotificationService.instance) {
      NotificationService.instance = new NotificationService();
    }
    return NotificationService.instance;
  }

  public setUseMock(useMock: boolean): void {
    this.useMock = useMock;
  }

  public getUseMock(): boolean {
    return this.useMock;
  }

  async getNotificationList(
    category?: NotificationCategory,
    useMock: boolean = this.useMock,
    options?: { cache?: boolean; cacheTTLMs?: number; forceRefresh?: boolean }
  ): Promise<NotificationItem[]> {
    const response = await this.networkService.request<{ items: NotificationItem[] } | NotificationItem[]>({
      trCode: TR_CODES.NOTIFICATION_LIST,
      payload: category && category !== 'all' ? { category } : {},
      useMock,
      cache: options?.cache ?? false,
      cacheTTLMs: options?.cacheTTLMs,
      forceRefresh: options?.forceRefresh ?? false,
    });

    const rawItems: NotificationItem[] = Array.isArray(response.body)
      ? response.body
      : response.body?.items || MOCK_NOTIFICATIONS;

    const mapped = rawItems.map((item) => ({
      ...item,
      isUnread: this.readIds.has(item.id) ? false : item.isUnread,
    }));

    if (category && category !== 'all') {
      return mapped.filter((item) => item.category === category);
    }

    return mapped;
  }

  async getNotificationDetail(
    id: string,
    useMock: boolean = this.useMock,
    options?: { cache?: boolean; cacheTTLMs?: number; forceRefresh?: boolean }
  ): Promise<NotificationItem | null> {
    const response = await this.networkService.request<{ items?: NotificationItem[]; item?: NotificationItem } | NotificationItem>({
      trCode: TR_CODES.NOTIFICATION_DETAIL,
      payload: { id },
      useMock,
      // Default cache: true for repeated detail views unless explicitly disabled
      cache: options?.cache ?? true,
      cacheTTLMs: options?.cacheTTLMs,
      forceRefresh: options?.forceRefresh ?? false,
    });

    if (!response.result || !response.body) {
      return null;
    }

    const bodyAny = response.body as any;
    let found: NotificationItem | undefined;

    if (bodyAny.id && bodyAny.title) {
      found = bodyAny as NotificationItem;
    } else if (bodyAny.item) {
      found = bodyAny.item as NotificationItem;
    } else {
      const list: NotificationItem[] = Array.isArray(bodyAny)
        ? bodyAny
        : bodyAny.items || [];
      found = list.find((n) => n.id === id);
    }

    if (!found) return null;

    this.readIds.add(id);
    return {
      ...found,
      isUnread: false,
    };
  }

  async markAsRead(id: string): Promise<void> {
    this.readIds.add(id);
  }
}
