import React from 'react';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import {
  ShowcaseListScreen,
  ShowcaseDetailScreen,
  SliverFullScreenDemoScreen,
  OfflineDataScreen,
  ContractViewerScreen,
} from '../views';
import { CustomerVerificationCheckScreen } from '@mfe/ui-components/components/feedback/CustomerVerificationCheckScreen';

const Stack = createNativeStackNavigator();

export interface ShowcaseNavigatorProps {
  onBackToDashboard?: () => void;
}

export const ShowcaseNavigator: React.FC<ShowcaseNavigatorProps> = ({
  onBackToDashboard,
}) => {
  return (
    <Stack.Navigator screenOptions={{ headerShown: false, fullScreenGestureEnabled: false }}>
      <Stack.Screen name="ShowcaseListScreen">
        {() => <ShowcaseListScreen onBack={onBackToDashboard} />}
      </Stack.Screen>
      <Stack.Screen name="SliverFullScreenDemo" component={SliverFullScreenDemoScreen} />
      <Stack.Screen name="OfflineDataScreen" component={OfflineDataScreen} />
      <Stack.Screen name="ShowcaseDetail" component={ShowcaseDetailScreen as any} />
      <Stack.Screen name="ContractViewer" component={ContractViewerScreen} />
      <Stack.Screen name="CustomerVerificationCheck" component={CustomerVerificationCheckScreen} />
    </Stack.Navigator>
  );
};

export default ShowcaseNavigator;
