import React from 'react';
import { View, StyleSheet, Alert } from 'react-native';
import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import { ThemeProvider } from '@mfe/theme';
import { I18nProvider } from '@mfe/core/i18n';
import { GlobalModalHost } from '@mfe/ui-components/modals';
import { LaunchNavigator } from '../src_launch/navigation/LaunchNavigator';
import { AuthNavigator } from '../src_auth/navigation/AuthNavigator';

const Stack = createNativeStackNavigator();

export const LaunchAuthStandaloneApp: React.FC = () => {
  return (
    <SafeAreaProvider>
      <ThemeProvider>
        <I18nProvider initialLanguage="km">
          <View style={styles.container}>
            <NavigationContainer>
              <Stack.Navigator screenOptions={{ headerShown: false }} initialRouteName="Launch">
                <Stack.Screen name="Launch">
                  {({ navigation }) => (
                    <LaunchNavigator
                      onComplete={() => navigation.navigate('Auth')}
                    />
                  )}
                </Stack.Screen>
                <Stack.Screen name="Auth">
                  {() => (
                    <AuthNavigator
                      onLoginSuccess={() =>
                        Alert.alert('Standalone Dev', 'Login succeeded! Ready for Dashboard.')
                      }
                    />
                  )}
                </Stack.Screen>
              </Stack.Navigator>
            </NavigationContainer>
          </View>
          <GlobalModalHost />
        </I18nProvider>
      </ThemeProvider>
    </SafeAreaProvider>
  );
};

export default LaunchAuthStandaloneApp;

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#FFFFFF',
    height: '100%',
    width: '100%',
  },
});
