import { useState, useEffect, useCallback } from 'react';
import { ILaunchService, LaunchService } from '../services/LaunchService';
import { LaunchValidator } from '../models/LaunchModel';

export interface UseTermsAndConditionsViewModelProps {
  launchService?: ILaunchService;
  language?: string;
  onAgreeSuccess?: () => void;
  onCancel?: () => void;
  onSkip?: () => void;
}

export function useTermsAndConditionsViewModel({
  launchService = new LaunchService(),
  language,
  onAgreeSuccess,
  onCancel,
  onSkip,
}: UseTermsAndConditionsViewModelProps = {}) {
  const [termsText, setTermsText] = useState<string>('');
  const [hasAgreed, setHasAgreed] = useState<boolean>(false);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  useEffect(() => {
    let isMounted = true;
    (async () => {
      try {
        const text = await launchService.getTermsContent(language as any);
        if (isMounted) {
          setTermsText(text);
        }
      } catch (err: unknown) {
        if (isMounted) {
          setErrorMessage('Failed to load Terms and Conditions.');
        }
      }
    })();
    return () => {
      isMounted = false;
    };
  }, [launchService, language]);

  const toggleAgreement = useCallback(() => {
    setHasAgreed((prev) => !prev);
    setErrorMessage(null);
  }, []);

  const handleAgree = useCallback(async () => {
    if (!LaunchValidator.canProceedWithTerms(hasAgreed)) {
      setErrorMessage('Please agree to the Terms and Conditions to proceed.');
      return;
    }

    setIsLoading(true);
    setErrorMessage(null);
    try {
      await launchService.acceptTerms();
      if (onAgreeSuccess) {
        onAgreeSuccess();
      }
    } catch (err: unknown) {
      setErrorMessage('Could not record acceptance. Please try again.');
    } finally {
      setIsLoading(false);
    }
  }, [hasAgreed, launchService, onAgreeSuccess]);

  const handleCancel = useCallback(() => {
    if (onCancel) {
      onCancel();
    }
  }, [onCancel]);

  const handleSkip = useCallback(() => {
    if (onSkip) {
      onSkip();
    }
  }, [onSkip]);

  return {
    termsText,
    hasAgreed,
    isLoading,
    errorMessage,
    toggleAgreement,
    handleAgree,
    handleCancel,
    handleSkip,
  };
}
