/**
 * DisburseUtil: Utility for loan disbursement validation, beneficiary accounts,
 * NAPAS banking network verification, and fee deductibility.
 * Aligned with Lotte Finance Digital Channels (DL1, DL2, DL3, LFVN) and DBCS LOS workflows.
 */

export interface BeneficiaryBankAccount {
  bankCode: string;
  bankShortName?: string;
  accountNumber: string;
  accountHolderName: string;
  isVerified?: boolean;
}

export interface DisbursementMethodOption {
  code: 'BANK_TRANSFER' | 'SHOWROOM_ESCROW' | 'BRANCH_CASH' | 'DIGITAL_WALLET';
  name: string;
  description: string;
  requiresBeneficiaryAccount: boolean;
}

export interface DisbursementCalculationParams {
  approvedAmount: number;
  insuranceFee?: number;
  originationFee?: number;
  firstInstallmentUpfront?: number;
  deductFeesFromDisbursement?: boolean;
}

export interface DisbursementCalculationResult {
  approvedAmount: number;
  totalDeductions: number;
  netDisbursedAmount: number;
  breakdown: {
    insuranceFee: number;
    originationFee: number;
    firstInstallmentUpfront: number;
  };
}

export class DisburseUtil {
  /**
   * Supported disbursement channels in Core Banking / LOS.
   */
  public static readonly DISBURSEMENT_METHODS: DisbursementMethodOption[] = [
    {
      code: 'BANK_TRANSFER',
      name: 'Direct Bank Transfer',
      description: 'Transfer directly to verified customer bank account via NAPAS 24/7.',
      requiresBeneficiaryAccount: true,
    },
    {
      code: 'SHOWROOM_ESCROW',
      name: 'Showroom / Dealer Account',
      description: 'Disburse directly to authorized car dealer / merchant escrow account.',
      requiresBeneficiaryAccount: true,
    },
    {
      code: 'BRANCH_CASH',
      name: 'Cash at Bank Branch / Counter',
      description: 'Receive cash at designated bank partner branch with National ID card.',
      requiresBeneficiaryAccount: false,
    },
    {
      code: 'DIGITAL_WALLET',
      name: 'Connected E-Wallet',
      description: 'Instant transfer to verified linked e-wallet account.',
      requiresBeneficiaryAccount: false,
    },
  ];

  /**
   * Sanitizes and standardizes bank account number:
   * Strips spaces, dashes, and non-numeric characters.
   */
  public static sanitizeAccountNumber(accountNumber: string): string {
    if (!accountNumber) return '';
    return accountNumber.replace(/[^0-9]/g, '').trim();
  }

  /**
   * Validates bank account number format:
   * Standard account length in VN/KH/SEA banks is between 6 and 20 digits.
   */
  public static isValidAccountNumber(accountNumber: string): {
    valid: boolean;
    error?: string;
  } {
    const sanitized = this.sanitizeAccountNumber(accountNumber);
    if (!sanitized) {
      return { valid: false, error: 'Account number is required.' };
    }
    if (sanitized.length < 6) {
      return { valid: false, error: 'Account number is too short (min 6 digits).' };
    }
    if (sanitized.length > 22) {
      return { valid: false, error: 'Account number is too long (max 22 digits).' };
    }
    return { valid: true };
  }

  /**
   * Normalizes account holder names to standard banking uppercase format:
   * e.g., "nguyễn văn an" -> "NGUYEN VAN AN" (removes Vietnamese accents for CBS matching).
   */
  public static normalizeAccountHolderName(name: string): string {
    if (!name) return '';
    return name
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/đ/g, 'd')
      .replace(/Đ/g, 'D')
      .toUpperCase()
      .trim();
  }

  /**
   * Verifies if customer full name matches the beneficiary bank account holder name.
   * Banking rule: Borrower name must match bank account holder name (anti-money laundering rule).
   */
  public static isAccountHolderMatched(
    borrowerName: string,
    beneficiaryName: string
  ): boolean {
    const normBorrower = this.normalizeAccountHolderName(borrowerName);
    const normBeneficiary = this.normalizeAccountHolderName(beneficiaryName);

    if (!normBorrower || !normBeneficiary) return false;
    return normBorrower === normBeneficiary;
  }

  /**
   * Calculates net disbursement payout after optional fee deductions:
   * Net Disbursed = Approved Loan Amount - (Insurance Fee + Origination Fee + Upfront Installments).
   */
  public static calculateNetDisbursement(
    params: DisbursementCalculationParams
  ): DisbursementCalculationResult {
    const approved = Math.max(0, params.approvedAmount);
    const insurance = Math.max(0, params.insuranceFee || 0);
    const origination = Math.max(0, params.originationFee || 0);
    const upfront = Math.max(0, params.firstInstallmentUpfront || 0);

    const shouldDeduct = params.deductFeesFromDisbursement ?? true;

    const totalDeductions = shouldDeduct ? insurance + origination + upfront : 0;
    const netDisbursedAmount = Math.max(0, approved - totalDeductions);

    return {
      approvedAmount: approved,
      totalDeductions,
      netDisbursedAmount,
      breakdown: {
        insuranceFee: insurance,
        originationFee: origination,
        firstInstallmentUpfront: upfront,
      },
    };
  }

  /**
   * Masks a bank account number for privacy in UI cards:
   * e.g., "0123456789" -> "012****789"
   */
  public static maskAccountNumber(
    accountNumber: string,
    options: { visibleStart?: number; visibleEnd?: number; maskChar?: string } = {}
  ): string {
    const clean = this.sanitizeAccountNumber(accountNumber);
    const { visibleStart = 3, visibleEnd = 3, maskChar = '*' } = options;
    if (!clean || clean.length <= visibleStart + visibleEnd) return clean || '';

    const start = clean.slice(0, visibleStart);
    const end = clean.slice(-visibleEnd);
    const maskedLength = Math.max(3, clean.length - (visibleStart + visibleEnd));
    return `${start}${maskChar.repeat(maskedLength)}${end}`;
  }

  /**
   * Formats a 13-character Loan Application Code (Mã APL):
   * Pattern: "APL" followed by 10 alphanumeric characters.
   * e.g. "APL0000000012"
   */
  public static isValidAplCode(aplCode: string): boolean {
    if (!aplCode) return false;
    const trimmed = aplCode.trim().toUpperCase();
    return /^APL[A-Z0-9]{10}$/.test(trimmed);
  }
}

