const LaunchNavigator: React.FC<any> = (props) => {
  useEffect(() => {
    authRemote.prefetch();
  }, []);
  return <launchRemote.Component {...props} />;
};

const AuthNavigator: React.FC<any> = (props) => {
  useEffect(() => {
    dashboardRemote.prefetch();
  }, []);
  return <authRemote.Component {...props} />;
};

const DashboardScreen = dashboardRemote.Component;
const ApprovalDetailScreen = approvalDetailRemote.Component;
const NotificationNavigator = notificationRemote.Component;
const ShowcaseNavigator = showcaseRemote.Component;

const remoteStyles = StyleSheet.create({
  loader: {
    flex: 1,
    backgroundColor: '#FFFFFF',
    alignItems: 'center',
    justifyContent: 'center',
  },
});

const Stack = createNativeStackNavigator<RootStackParamList>();

// Kick off persisted route lookup immediately at module load (before React mounts)
// so initialRoute is ready sooner and RootNavigator doesn't stall on mount.
const prefetchedRoutePromise: Promise<PersistedAppRoute> = appRoutePersistenceService
  .getSavedRoute()
  .then((savedRoute) => savedRoute || 'LaunchFlow')
  .catch(() => 'LaunchFlow' as PersistedAppRoute);

export interface RootNavigatorProps {
  routePersistenceService?: AppRoutePersistenceService;
  onInitialRouteReady?: () => void;
}

export const RootNavigator: React.FC<RootNavigatorProps> = ({
  routePersistenceService = appRoutePersistenceService,
  onInitialRouteReady,
}) => {
  const [initialRoute, setInitialRoute] = useState<PersistedAppRoute | null>(null);
  const hasNotifiedReadyRef = useRef(false);

  useEffect(() => {
    let isMounted = true;
    const routePromise =
      routePersistenceService === appRoutePersistenceService
        ? prefetchedRoutePromise
        : routePersistenceService
            .getSavedRoute()
            .then((savedRoute) => savedRoute || 'LaunchFlow')
            .catch(() => 'LaunchFlow' as PersistedAppRoute);

    routePromise.then((resolvedRoute) => {
      if (isMounted) {
        setInitialRoute(resolvedRoute);
      }
    });

    return () => {
      isMounted = false;
    };
  }, [routePersistenceService]);

  const notifyInitialRouteReady = useCallback(() => {
    if (hasNotifiedReadyRef.current || !onInitialRouteReady) {
      return;
    }
    hasNotifiedReadyRef.current = true;
    onInitialRouteReady();
  }, [onInitialRouteReady]);

  // For DashboardFlow, wait for DashboardScreen's onFirstLayout (with a short fallback
  // in case an older remote-dashboard OTA bundle does not invoke onFirstLayout).
  // For other initial routes, wait 2 animation frames after initialRoute resolves.
  useEffect(() => {
    if (!initialRoute || hasNotifiedReadyRef.current || !onInitialRouteReady) {
      return;
    }
    if (initialRoute === 'DashboardFlow') {
      const fallbackTimer = setTimeout(() => {
        notifyInitialRouteReady();
      }, 400);
      return () => clearTimeout(fallbackTimer);
    }
    let raf2: number | null = null;
    const raf1 = requestAnimationFrame(() => {
      raf2 = requestAnimationFrame(() => {
        notifyInitialRouteReady();
      });
    });
    return () => {
      cancelAnimationFrame(raf1);
      if (raf2 !== null) {
        cancelAnimationFrame(raf2);
      }
    };
  }, [initialRoute, onInitialRouteReady, notifyInitialRouteReady]);

  if (!initialRoute) {
    return null;
  }

  return (
    <Stack.Navigator
      initialRouteName={initialRoute}
      screenOptions={{
        headerShown: false,
        animation: 'default',
        freezeOnBlur: true,
        gestureEnabled: true,
        fullScreenGestureEnabled: false,
        contentStyle: { backgroundColor: '#0F172A' },
      }}
    >
      {/* 1. Launch & Onboarding Domain Container */}
      <Stack.Screen
        name="LaunchFlow"
        component={LaunchNavigator}
        options={{ gestureEnabled: false }}
      />

      {/* 2. Authentication & Security Domain Container */}
      <Stack.Screen
        name="AuthFlow"
        component={AuthNavigator}
        options={{ gestureEnabled: false }}
        listeners={{
          focus: () => {
            routePersistenceService.saveRoute('AuthFlow');
          },
        }}
      />

      {/* 3. Dashboard Domain Container */}
      <Stack.Screen
        name="DashboardFlow"
        options={{ gestureEnabled: false }}
        listeners={{
          focus: () => {
            routePersistenceService.saveRoute('DashboardFlow');
          },
        }}
      >
        {({ navigation }) => (
          <DashboardScreen
            onFirstLayout={notifyInitialRouteReady}
            onNavigateToShowcase={() => navigation.navigate('ShowcaseList')}
            onNavigateToNotification={() => navigation.navigate('NotificationFlow')}
            onNavigateToApprovalDetail={(approvalId) =>
              navigation.navigate('ApprovalDetail', { approvalId })
            }
            onLogout={async () => {
              await routePersistenceService.clearSavedRoute();
              navigation.reset({
                index: 0,
                routes: [{ name: 'AuthFlow' }],
              });
            }}
          />
        )}
      </Stack.Screen>

      {/* 4. Approval Detail Screen (Dedicated navigation screen with native swipe back) */}
      <Stack.Screen
        name="ApprovalDetail"
        options={{
          animation: 'slide_from_right',
          gestureEnabled: true,
        }}
      >
        {({ navigation, route }) => (
          <ApprovalDetailScreen
            approvalId={route.params?.approvalId || ''}
            onBack={() => navigation.goBack()}
          />
        )}
      </Stack.Screen>

      {/* 4. Notification Domain Container (Remote Notification) */}
      <Stack.Screen
        name="NotificationFlow"
        options={{
          animation: 'default',
          gestureEnabled: true,
        }}
      >
        {({ navigation }) => (
          <NotificationNavigator
            onBackToDashboard={() => navigation.goBack()}
          />
        )}
      </Stack.Screen>

      {/* 5. Showcase Domain Container */}
      <Stack.Screen
        name="ShowcaseList"
        options={({ navigation }) => ({
          animation: 'default',
          gestureEnabled: navigation.canGoBack(),
        })}
      >
        {({ navigation }) => (
          <ShowcaseNavigator
            onBackToDashboard={
              navigation.canGoBack() ? () => navigation.goBack() : undefined
            }
          />
        )}
      </Stack.Screen>
    </Stack.Navigator>
  );
};

export default RootNavigator;
