import React, { useState, useMemo } from 'react';
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  ScrollView,
  StyleSheet,
  ViewStyle,
  Modal,
  Platform,
} from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

export interface FilterSelectOption<T = string> {
  label: string;
  value: T;
  subtitle?: string;
  disabled?: boolean;
}

export interface SearchableFilterBottomSheetProps<T = string> {
  visible: boolean;
  onClose: () => void;
  title?: string; // e.g. "Tên cơ quan/ nơi làm việc"
  searchPlaceholder?: string; // e.g. "Nhập tên cơ quan/ nơi làm việc"
  options: FilterSelectOption<T>[];
  selectedValue?: T;
  onSelect: (value: T, option: FilterSelectOption<T>) => void;
  /** Allow custom options addition, e.g. if not found */
  allowCustomInput?: boolean;
  onAddCustom?: (text: string) => void;
  containerStyle?: ViewStyle;
  testID?: string;
}

/**
 * Enterprise Searchable Filter & Selection BottomSheet.
 * Faithfully matches screenshot "Tên cơ quan/ nơi làm việc":
 * - Header with title and close button (✕)
 * - Magnifying glass search input ("Nhập tên cơ quan/ nơi làm việc")
 * - Radio-style circular option rows with clear typography
 * - Smooth vertical scrolling list with scroll indicators
 * - Instant real-time search filtering across options
 */
export function SearchableFilterBottomSheet<T extends string | number>({
  visible,
  onClose,
  title = 'Tên cơ quan/ nơi làm việc',
  searchPlaceholder = 'Nhập tên tên cơ quan/ nơi làm việc',
  options,
  selectedValue,
  onSelect,
  allowCustomInput = false,
  onAddCustom,
  containerStyle,
  testID = 'searchable-filter-bottomsheet',
}: SearchableFilterBottomSheetProps<T>) {
  const [searchQuery, setSearchQuery] = useState('');

  let insets = { top: 0, bottom: 0, left: 0, right: 0 };
  try {
    insets = useSafeAreaInsets();
  } catch (_e) {
    insets = { top: 0, bottom: 0, left: 0, right: 0 };
  }

  const filteredOptions = useMemo(() => {
    if (!searchQuery.trim()) return options;
    const q = searchQuery.toLowerCase().trim();
    return options.filter(
      (opt) =>
        opt.label.toLowerCase().includes(q) ||
        (opt.subtitle && opt.subtitle.toLowerCase().includes(q))
    );
  }, [options, searchQuery]);

  if (!visible) return null;

  return (
    <Modal
      visible={visible}
      transparent={true}
      animationType="slide"
      onRequestClose={onClose}
    >
      <View style={styles.modalBackdrop}>
        <TouchableOpacity
          activeOpacity={1}
          style={styles.backdropDismiss}
          onPress={onClose}
          testID={`${testID}-backdrop`}
        />

        <View
          style={[
            styles.sheetContainer,
            { paddingBottom: insets.bottom > 0 ? insets.bottom : 16 },
            containerStyle,
          ]}
          testID={testID}
        >
          {/* Top Drag Handle */}
          <View style={styles.dragHandle} />

          {/* Header */}
          <View style={styles.headerRow}>
            <Text style={styles.headerTitle} testID={`${testID}-title`}>
              {title}
            </Text>
            <TouchableOpacity
              activeOpacity={0.7}
              onPress={onClose}
              style={styles.closeBtn}
              hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
              testID={`${testID}-close-btn`}
            >
              <Text style={styles.closeIcon}>✕</Text>
            </TouchableOpacity>
          </View>

          {/* Search Input Bar */}
          <View style={styles.searchBar}>
            <Text style={styles.searchIcon}>🔍</Text>
            <TextInput
              value={searchQuery}
              onChangeText={setSearchQuery}
              placeholder={searchPlaceholder}
              placeholderTextColor="#9CA3AF"
              style={styles.searchInput}
              clearButtonMode="while-editing"
              autoCorrect={false}
              testID={`${testID}-search-input`}
            />
            {searchQuery.length > 0 && Platform.OS !== 'ios' && (
              <TouchableOpacity
                onPress={() => setSearchQuery('')}
                style={styles.clearSearchBtn}
                testID={`${testID}-clear-search`}
              >
                <Text style={styles.clearSearchIcon}>✕</Text>
              </TouchableOpacity>
            )}
          </View>

          {/* Options List */}
          <ScrollView
            style={styles.scrollView}
            contentContainerStyle={styles.scrollContent}
            keyboardShouldPersistTaps="handled"
            showsVerticalScrollIndicator={true}
            testID={`${testID}-scroll-view`}
          >
            {filteredOptions.length === 0 ? (
              <View style={styles.emptyContainer} testID={`${testID}-empty`}>
                <Text style={styles.emptyText}>Không tìm thấy kết quả phù hợp</Text>
                {allowCustomInput && onAddCustom && searchQuery.trim().length > 0 && (
                  <TouchableOpacity
                    style={styles.addCustomBtn}
                    onPress={() => {
                      onAddCustom(searchQuery.trim());
                      onClose();
                    }}
                    testID={`${testID}-add-custom-btn`}
                  >
                    <Text style={styles.addCustomText}>
                      + Chọn "{searchQuery.trim()}"
                    </Text>
                  </TouchableOpacity>
                )}
              </View>
            ) : (
              filteredOptions.map((opt, index) => {
                const isSelected = opt.value === selectedValue;
                return (
                  <TouchableOpacity
                    key={`${String(opt.value)}-${index}`}
                    activeOpacity={opt.disabled ? 1 : 0.7}
                    disabled={opt.disabled}
                    onPress={() => {
                      onSelect(opt.value, opt);
                      onClose();
                    }}
                    style={[
                      styles.optionRow,
                      opt.disabled && styles.optionRowDisabled,
                    ]}
                    testID={`${testID}-option-${String(opt.value)}`}
                  >
                    {/* Radio Circle */}
                    <View
                      style={[
                        styles.radioCircle,
                        isSelected && styles.radioCircleSelected,
                      ]}
                      testID={`${testID}-radio-${String(opt.value)}`}
                    >
                      {isSelected && <View style={styles.radioInnerDot} />}
                    </View>

                    {/* Option Text */}
                    <View style={styles.optionTextContainer}>
                      <Text
                        style={[
                          styles.optionLabel,
                          isSelected && styles.optionLabelSelected,
                          opt.disabled && styles.optionLabelDisabled,
                        ]}
                      >
                        {opt.label}
                      </Text>
                      {opt.subtitle ? (
                        <Text style={styles.optionSubtitle}>{opt.subtitle}</Text>
                      ) : null}
                    </View>
                  </TouchableOpacity>
                );
              })
            )}
          </ScrollView>
        </View>
      </View>
    </Modal>
  );
}

