import React, { useEffect, useRef } from 'react';
import {
  View,
  Text,
  StyleSheet,
  Animated,
  Easing,
  ViewStyle,
  Platform,
} from 'react-native';
import Svg, { Path } from 'react-native-svg';

export type ProcessItemStatus = 'completed' | 'in_progress' | 'pending' | 'failed';

export interface ProcessCheckItem {
  id: string;
  label: string;
  status: ProcessItemStatus;
  resultText?: string;
}

export interface ProcessCheckListProps {
  /**
   * Title displayed prominently at top (e.g., "Checking customer information")
   */
  title?: string;
  /**
   * Subtitle description beneath title (e.g., "The system is checking the customer information...")
   */
  description?: string;
  /**
   * Checklist items to render
   */
  items: ProcessCheckItem[];
  /**
   * Whether to spin the central sync/refresh icon
   */
  animated?: boolean;
  /**
   * Size of the round circular icon badge
   */
  iconSize?: number;
  /**
   * Accent color for primary elements (defaults to vibrant blue #2563EB)
   */
  primaryColor?: string;
  /**
   * Optional container style
   */
  style?: ViewStyle;
  /**
   * Accessible test ID
   */
  testID?: string;
}

/**
 * Animated Circular Refresh / Sync Icon
 */
const AnimatedSyncBadge: React.FC<{
  size: number;
  color: string;
  animated: boolean;
  testID?: string;
}> = ({ size, color, animated, testID }) => {
  const rotateAnim = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    if (!animated) return;

    const loop = Animated.loop(
      Animated.timing(rotateAnim, {
        toValue: 1,
        duration: 1600,
        easing: Easing.linear,
        useNativeDriver: Platform.OS !== 'web',
      })
    );
    loop.start();

    return () => loop.stop();
  }, [animated, rotateAnim]);

  const spin = rotateAnim.interpolate({
    inputRange: [0, 1],
    outputRange: ['0deg', '360deg'],
  });

  const iconDimension = size * 0.45;

  return (
    <View
      style={[
        styles.iconCircle,
        {
          width: size,
          height: size,
          borderRadius: size / 2,
        },
      ]}
      testID={testID}
    >
      <Animated.View
        style={{
          transform: [{ rotate: animated ? spin : '0deg' }],
        }}
      >
        <Svg
          width={iconDimension}
          height={iconDimension}
          viewBox="0 0 24 24"
          fill="none"
        >
          {/* Circular sync arrows icon */}
          <Path
            d="M4 4V9H4.582M20 20V15H19.418M19.938 11C19.7188 8.84758 18.6657 6.87764 16.9856 5.48512C15.3055 4.09261 13.1118 3.37121 10.8443 3.46513C8.57685 3.55904 6.38604 4.4621 4.70884 5.99285C3.03164 7.52361 2.02384 9.57868 1.887 11.75M4.062 13C4.28116 15.1524 5.3343 17.1224 7.01443 18.5149C8.69456 19.9074 10.8882 20.6288 13.1557 20.5349C15.4231 20.441 17.614 19.5379 19.2912 18.0071C20.9684 16.4764 21.9762 14.4213 22.113 12.25"
            stroke={color}
            strokeWidth={2.4}
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </Svg>
      </Animated.View>
    </View>
  );
};

/**
 * ProcessCheckList component
 *
 * Renders an animated or static progress verification status screen with:
 * - Circular light blue badge with rotating sync arrows
 * - Bold title & explanatory caption
 * - Check items with distinct visual indicators:
 *   - 'completed': Green checkmark ✓ + green text
 *   - 'in_progress': Ellipsis ... + slate/grey text
 *   - 'pending': Grey dash or dot
 *   - 'failed': Red cross ✕
 */
export const ProcessCheckList: React.FC<ProcessCheckListProps> = ({
  title = 'Checking customer information',
  description = 'The system is checking the customer information.\nPlease wait a moment for the check to complete.',
  items,
  animated = true,
  iconSize = 84,
  primaryColor = '#2563EB',
  style,
  testID = 'process-check-list',
}) => {
  return (
    <View style={[styles.container, style]} testID={testID}>
      {/* Top Animated Icon */}
      <View style={styles.iconContainer}>
        <AnimatedSyncBadge
          size={iconSize}
          color={primaryColor}
          animated={animated}
          testID={`${testID}-sync-icon`}
        />
      </View>

      {/* Main Title */}
      {title ? (
        <Text style={styles.title} testID={`${testID}-title`}>
          {title}
        </Text>
      ) : null}

      {/* Description */}
      {description ? (
        <Text style={styles.description} testID={`${testID}-description`}>
          {description}
        </Text>
      ) : null}

      {/* Check Process Items */}
      <View style={styles.checklistContainer} testID={`${testID}-items`}>
        {items.map((item, index) => {
          const isCompleted = item.status === 'completed';
          const isInProgress = item.status === 'in_progress';
          const isFailed = item.status === 'failed';

          // Color selection
          let statusColor = '#64748B'; // pending grey
          let iconSymbol = '•';

          if (isCompleted) {
            statusColor = '#16A34A'; // emerald green
            iconSymbol = '✓';
          } else if (isInProgress) {
            statusColor = '#475569'; // darker slate
            iconSymbol = '...';
          } else if (isFailed) {
            statusColor = '#DC2626'; // danger red
            iconSymbol = '✕';
          }

          return (
            <View
              key={item.id || `item-${index}`}
              style={styles.itemRow}
              testID={`${testID}-item-${item.id}`}
            >
              <Text
                style={[
                  styles.itemIcon,
                  { color: statusColor },
                  isInProgress && styles.ellipsisIcon,
                ]}
                testID={`${testID}-item-${item.id}-icon`}
              >
                {iconSymbol}
              </Text>
              <Text
                style={[
                  styles.itemLabel,
                  { color: statusColor },
                  isCompleted && styles.completedLabel,
                ]}
                testID={`${testID}-item-${item.id}-label`}
              >
                {item.label}
                {item.resultText ? `: ${item.resultText}` : ''}
              </Text>
            </View>
          );
        })}
      </View>
    </View>
  );
};

