import React, { useState } from 'react';
import { View, Text, StyleSheet } from 'react-native';
import { AppAlertModal } from '../../modals/AppAlertModal';
import { AppBottomSheet } from '../../modals/AppBottomSheet';
import { AppTextInput } from '../input/AppTextInput';
import { AppButton } from '../button/AppButton';
import { CircleProfileAvatar } from './CircleProfileAvatar';

export interface EditProfileFormData {
  fullName: string;
  phoneNumber: string;
  email: string;
  nric: string;
}

export interface EditProfileModalProps {
  visible: boolean;
  onClose: () => void;
  initialData?: Partial<EditProfileFormData>;
  onSave: (data: EditProfileFormData) => void;
  presentation?: 'alert' | 'bottomsheet';
  testID?: string;
}

export const EditProfileModal: React.FC<EditProfileModalProps> = ({
  visible,
  onClose,
  initialData,
  onSave,
  presentation = 'bottomsheet',
  testID = 'edit-profile-modal',
}) => {
  const [fullName, setFullName] = useState(initialData?.fullName || 'Nguyễn Văn An');
  const [phoneNumber, setPhoneNumber] = useState(initialData?.phoneNumber || '0901234567');
  const [email, setEmail] = useState(initialData?.email || 'customer@lottefinance.vn');
  const [nric, setNric] = useState(initialData?.nric || '012345678901');

  const handleSave = () => {
    onSave({ fullName, phoneNumber, email, nric });
    onClose();
  };

  const formBody = (
    <View style={styles.container}>
      <View style={styles.avatarHeader}>
        <CircleProfileAvatar
          name={fullName}
          size={76}
          showEditBadge
          onEditPress={() => {}}
          testID={`${testID}-avatar`}
        />
        <Text style={styles.changePhotoText}>Tap icon to change photo</Text>
      </View>

      <AppTextInput
        label="Full Name"
        value={fullName}
        onChangeText={setFullName}
        testID={`${testID}-input-name`}
      />

      <AppTextInput
        label="Phone Number"
        value={phoneNumber}
        onChangeText={setPhoneNumber}
        keyboardType="phone-pad"
        testID={`${testID}-input-phone`}
      />

      <AppTextInput
        label="Email Address"
        value={email}
        onChangeText={setEmail}
        keyboardType="email-address"
        autoCapitalize="none"
        testID={`${testID}-input-email`}
      />

      <AppTextInput
        label="National ID / CCCD"
        value={nric}
        onChangeText={setNric}
        keyboardType="numeric"
        testID={`${testID}-input-nric`}
      />

      <View style={styles.buttonRow}>
        <AppButton
          title="Cancel"
          variant="outline"
          size="medium"
          onPress={onClose}
          testID={`${testID}-cancel`}
        />
        <View style={{ width: 12 }} />
        <AppButton
          title="Save Changes"
          variant="primary"
          size="medium"
          onPress={handleSave}
          testID={`${testID}-submit`}
        />
      </View>
    </View>
  );

  if (presentation === 'alert') {
    return (
      <AppAlertModal
        visible={visible}
        title="Edit Personal Profile"
        onClose={onClose}
        testID={testID}
      >
        {formBody}
      </AppAlertModal>
    );
  }

  return (
    <AppBottomSheet
      visible={visible}
      title="Edit Personal Profile"
      onClose={onClose}
      testID={testID}
    >
      {formBody}
    </AppBottomSheet>
  );
};

const styles = StyleSheet.create({
  container: {
    paddingVertical: 8,
  },
  avatarHeader: {
    alignItems: 'center',
    marginBottom: 16,
  },
  changePhotoText: {
    fontSize: 12,
    color: '#6B7280',
    marginTop: 6,
  },
  buttonRow: {
    flexDirection: 'row',
    justifyContent: 'flex-end',
    marginTop: 16,
  },
});

