import React, { useRef } from 'react';
import {
  Animated,
  Image,
  ImageSourcePropType,
  Platform,
  StyleProp,
  StyleSheet,
  Text,
  View,
  ViewStyle,
} from 'react-native';
import Svg, { Defs, LinearGradient, Rect, Stop } from 'react-native-svg';
import { useTheme, defaultTheme } from '@mfe/theme';

export interface ParallaxScrollViewProps {
  /** Height of the expandable parallax hero header */
  headerHeight?: number;
  /** Height of the sticky header bar that fades in on scroll */
  stickyHeaderHeight?: number;
  /** Parallax speed ratio (0.5 = header moves at half the scroll speed) */
  parallaxFactor?: number;
  /** Render prop for the hero header foreground content */
  renderHeader: (scrollY: Animated.Value) => React.ReactNode;
  /** Optional title shown in the sticky bar once collapsed */
  stickyTitle?: string;
  /** Optional left accessory in the sticky bar (e.g. Back button) */
  renderStickyHeaderLeft?: () => React.ReactNode;
  /** Optional right accessory in the sticky bar */
  renderStickyHeaderRight?: () => React.ReactNode;
  /** Solid background color behind the header & sticky bar */
  headerBackgroundColor?: string;
  /** Optional background image for the parallax hero */
  headerImage?: ImageSourcePropType;
  /** Optional dark/tint scrim over headerImage for text legibility (default 'rgba(0,0,0,0.3)') */
  headerImageOverlayColor?: string;
  /** Optional linear gradient stops (e.g. ['#2C213F', '#5B21B6']) rendered via react-native-svg */
  headerGradientColors?: string[];
  /** Optional custom background node (e.g. BlurView, SVG art, video) */
  renderHeaderBackground?: (scrollY: Animated.Value) => React.ReactNode;
  /** Background color of the scrollable body container */
  contentBackgroundColor?: string;
  /** Optional style for the outer container */
  style?: StyleProp<ViewStyle>;
  /** Optional style for the scrollable content body */
  contentContainerStyle?: StyleProp<ViewStyle>;
  children: React.ReactNode;
  testID?: string;
}

export const ParallaxScrollView: React.FC<ParallaxScrollViewProps> = ({
  headerHeight = 240,
  stickyHeaderHeight = 56,
  parallaxFactor = 0.5,
  renderHeader,
  stickyTitle,
  renderStickyHeaderLeft,
  renderStickyHeaderRight,
  headerBackgroundColor,
  headerImage,
  headerImageOverlayColor = 'rgba(0,0,0,0.3)',
  headerGradientColors,
  renderHeaderBackground,
  contentBackgroundColor,
  style,
  contentContainerStyle,
  children,
  testID = 'parallax-scroll-view',
}) => {
  const themeContext = useTheme();
  const theme = themeContext?.theme || defaultTheme;
  const { colors, radius } = theme;

  const scrollY = useRef(new Animated.Value(0)).current;
  const scrollDistance = Math.max(headerHeight - stickyHeaderHeight, 1);

  const headerBg =
    headerBackgroundColor ||
    (headerGradientColors && headerGradientColors[0]) ||
    colors.primary;
  const bodyBg = contentBackgroundColor || colors.background;

  const renderBackgroundLayer = () => {
    if (renderHeaderBackground) {
      return (
        <View pointerEvents="none" style={StyleSheet.absoluteFillObject}>
          {renderHeaderBackground(scrollY)}
        </View>
      );
    }

    if (headerImage) {
      return (
        <View pointerEvents="none" style={StyleSheet.absoluteFillObject}>
          <Image
            testID={`${testID}-header-image`}
            source={headerImage}
            resizeMode="cover"
            style={StyleSheet.absoluteFillObject}
          />
          {headerImageOverlayColor ? (
            <View
              style={[
                StyleSheet.absoluteFillObject,
                { backgroundColor: headerImageOverlayColor },
              ]}
            />
          ) : null}
        </View>
      );
    }

    if (headerGradientColors && headerGradientColors.length >= 2) {
      const gradId = `parallax-grad-${testID}`;
      return (
        <View pointerEvents="none" style={StyleSheet.absoluteFillObject}>
          <Svg width="100%" height="100%" preserveAspectRatio="none">
            <Defs>
              <LinearGradient id={gradId} x1="0%" y1="0%" x2="100%" y2="100%">
                {headerGradientColors.map((color, idx) => (
                  <Stop
                    key={`${color}-${idx}`}
                    offset={`${(idx / (headerGradientColors.length - 1)) * 100}%`}
                    stopColor={color}
                  />
                ))}
              </LinearGradient>
            </Defs>
            <Rect x="0" y="0" width="100%" height="100%" fill={`url(#${gradId})`} />
          </Svg>
        </View>
      );
    }

    return null;
  };

  // Parallax vertical translation (moves slower than scroll) + overscroll stretch
  const headerTranslateY = scrollY.interpolate({
    inputRange: [-headerHeight, 0, scrollDistance],
    outputRange: [headerHeight * 0.4, 0, -scrollDistance * parallaxFactor],
    extrapolate: 'clamp',
  });

  const headerScale = scrollY.interpolate({
    inputRange: [-headerHeight, 0, 1],
    outputRange: [1.35, 1, 1],
    extrapolate: 'clamp',
  });

  const heroOpacity = scrollY.interpolate({
    inputRange: [0, scrollDistance * 0.65, scrollDistance],
    outputRange: [1, 0.4, 0],
    extrapolate: 'clamp',
  });

  const stickyBgOpacity = scrollY.interpolate({
    inputRange: [scrollDistance * 0.55, scrollDistance],
    outputRange: [0, 1],
    extrapolate: 'clamp',
  });

  const stickyTitleTranslateY = scrollY.interpolate({
    inputRange: [scrollDistance * 0.55, scrollDistance],
    outputRange: [10, 0],
    extrapolate: 'clamp',
  });

  const handleScroll = Animated.event(
    [{ nativeEvent: { contentOffset: { y: scrollY } } }],
    { useNativeDriver: Platform.OS !== 'web' }
  );

  return (
    <View testID={testID} style={[styles.container, { backgroundColor: bodyBg }, style]}>
      {/* Background Parallax Hero Header */}
      <Animated.View
        testID={`${testID}-header`}
        pointerEvents="box-none"
        style={[
          styles.heroContainer,
          {
            height: headerHeight,
            backgroundColor: headerBg,
            transform: [
              { translateY: headerTranslateY },
              { scale: headerScale },
            ],
          },
        ]}
      >
        {renderBackgroundLayer()}
        <Animated.View style={[styles.heroInner, { opacity: heroOpacity }]}>
          {renderHeader(scrollY)}
        </Animated.View>
      </Animated.View>

      {/* Main Scrollable Content */}
      <Animated.ScrollView
        testID={`${testID}-scroll`}
        scrollEventThrottle={16}
        onScroll={handleScroll}
        showsVerticalScrollIndicator={false}
        contentContainerStyle={[
          { paddingTop: headerHeight - radius.xl },
          contentContainerStyle,
        ]}
      >
        <View
          testID={`${testID}-body`}
          style={[
            styles.bodySurface,
            {
              backgroundColor: bodyBg,
              borderTopLeftRadius: radius.xl,
              borderTopRightRadius: radius.xl,
            },
          ]}
        >
          {children}
        </View>
      </Animated.ScrollView>

      {/* Sticky Collapsed Top Bar */}
      {(stickyTitle || renderStickyHeaderLeft || renderStickyHeaderRight) ? (
        <View
          testID={`${testID}-sticky-bar`}
          pointerEvents="box-none"
          style={[styles.stickyBar, { height: stickyHeaderHeight }]}
        >
          <Animated.View
            pointerEvents="none"
            style={[
              StyleSheet.absoluteFillObject,
              { backgroundColor: headerBg, opacity: stickyBgOpacity },
            ]}
          />
          <View style={styles.stickySlot}>
            {renderStickyHeaderLeft ? renderStickyHeaderLeft() : null}
          </View>
          <Animated.View
            style={[
              styles.stickyTitleWrap,
              {
                opacity: stickyBgOpacity,
                transform: [{ translateY: stickyTitleTranslateY }],
              },
            ]}
          >
            {stickyTitle ? (
              <Text
                numberOfLines={1}
                testID={`${testID}-sticky-title`}
                style={styles.stickyTitleText}
              >
                {stickyTitle}
              </Text>
            ) : null}
          </Animated.View>
          <View style={[styles.stickySlot, styles.stickySlotRight]}>
            {renderStickyHeaderRight ? renderStickyHeaderRight() : null}
          </View>
        </View>
      ) : null}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    overflow: 'hidden',
  },
  heroContainer: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    overflow: 'hidden',
  },
  heroInner: {
    flex: 1,
  },
  bodySurface: {
    flex: 1,
    minHeight: 300,
    paddingTop: 16,
  },
  stickyBar: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 16,
    zIndex: 10,
  },
  stickySlot: {
    width: 44,
    alignItems: 'flex-start',
    justifyContent: 'center',
  },
  stickySlotRight: {
    alignItems: 'flex-end',
  },
  stickyTitleWrap: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
  },
  stickyTitleText: {
    fontSize: 16,
    fontWeight: '700',
    color: '#FFFFFF',
  },
});

export default ParallaxScrollView;
