import React, { useEffect, useRef } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  Animated,
  Platform,
  ViewStyle,
} from 'react-native';
import { ToastOptions, ToastType } from '@mfe/core/utils/toastUtil';

export interface AppToastProps {
  toast: ToastOptions;
  onDismiss?: () => void;
  style?: ViewStyle;
  testID?: string;
}

/**
 * Enterprise Toast Notification Component.
 * Faithfully matches screenshot "E5 System error toast" (Toast System Error):
 * - Vivid red banner (#E5252A / #DC2626) with rounded corners (~8px)
 * - White circular exclamation icon `!` on left
 * - White clear typography with proper line wrapping
 * - White dismiss button `✕` on right
 * - Smooth entrance and exit animations (translateY + opacity)
 * - Accessible testIDs for end-to-end automated testing
 */
export const AppToast: React.FC<AppToastProps> = ({
  toast,
  onDismiss,
  style,
  testID = 'app-toast',
}) => {
  const translateY = useRef(new Animated.Value(toast.position === 'bottom' ? 50 : -50)).current;
  const opacity = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    Animated.parallel([
      Animated.timing(translateY, {
        toValue: 0,
        duration: 250,
        useNativeDriver: true,
      }),
      Animated.timing(opacity, {
        toValue: 1,
        duration: 250,
        useNativeDriver: true,
      }),
    ]).start();
  }, [translateY, opacity]);

  const handleDismiss = () => {
    Animated.parallel([
      Animated.timing(translateY, {
        toValue: toast.position === 'bottom' ? 50 : -50,
        duration: 200,
        useNativeDriver: true,
      }),
      Animated.timing(opacity, {
        toValue: 0,
        duration: 200,
        useNativeDriver: true,
      }),
    ]).start(() => {
      if (onDismiss) {
        onDismiss();
      }
    });
  };

  const getBackgroundColor = (type?: ToastType): string => {
    switch (type) {
      case 'error':
        // Match screenshot Lotte vibrant red
        return '#E5252A';
      case 'success':
        return '#10B981';
      case 'warning':
        return '#F59E0B';
      case 'info':
      default:
        return '#2563EB';
    }
  };

  const renderIcon = (type?: ToastType) => {
    // Distinct icons rendered with SVG-like geometric primitives for zero-dependency portability
    if (type === 'success') {
      return (
        <View style={styles.iconCircleWhite} testID={`${testID}-icon-success`}>
          <Text style={[styles.iconText, { color: getBackgroundColor(type) }]}>✓</Text>
        </View>
      );
    }
    if (type === 'warning') {
      return (
        <View style={styles.iconCircleWhite} testID={`${testID}-icon-warning`}>
          <Text style={[styles.iconText, { color: getBackgroundColor(type), fontWeight: '800' }]}>!</Text>
        </View>
      );
    }
    if (type === 'info') {
      return (
        <View style={styles.iconCircleWhite} testID={`${testID}-icon-info`}>
          <Text style={[styles.iconText, { color: getBackgroundColor(type), fontWeight: '700' }]}>i</Text>
        </View>
      );
    }
    // Default error: circular white badge with exclamation mark (matching screenshot)
    return (
      <View style={styles.iconCircleWhite} testID={`${testID}-icon-error`}>
        <Text style={[styles.iconText, { color: '#E5252A' }]}>!</Text>
      </View>
    );
  };

  const bgColor = getBackgroundColor(toast.type);

  return (
    <Animated.View
      style={[
        styles.toastWrapper,
        {
          backgroundColor: bgColor,
          opacity,
          transform: [{ translateY }],
        },
        style,
      ]}
      testID={testID}
    >
      <TouchableOpacity
        activeOpacity={toast.onPress ? 0.8 : 1}
        onPress={toast.onPress}
        style={styles.contentContainer}
        testID={`${testID}-touchable`}
      >
        {/* Leading Icon */}
        {toast.showIcon !== false && (
          <View style={styles.iconBox}>{renderIcon(toast.type)}</View>
        )}

        {/* Message */}
        <Text
          style={styles.messageText}
          numberOfLines={3}
          testID={`${testID}-message`}
        >
          {toast.message}
        </Text>
      </TouchableOpacity>

      {/* Trailing Dismiss Button */}
      {toast.showCloseButton !== false && (
        <TouchableOpacity
          activeOpacity={0.7}
          onPress={handleDismiss}
          style={styles.closeButton}
          hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
          testID={`${testID}-close-button`}
        >
          <Text style={styles.closeIcon}>✕</Text>
        </TouchableOpacity>
      )}
    </Animated.View>
  );
};

const styles = StyleSheet.create({
  toastWrapper: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingVertical: 12,
    paddingHorizontal: 16,
    borderRadius: 8,
    marginHorizontal: 16,
    ...Platform.select({
      ios: {
        shadowColor: '#000',
        shadowOffset: { width: 0, height: 4 },
        shadowOpacity: 0.15,
        shadowRadius: 8,
      },
      android: {
        elevation: 6,
      },
      default: {
        boxShadow: '0 4px 12px rgba(0, 0, 0, 0.15)',
      },
    }),
  },
  contentContainer: {
    flex: 1,
    flexDirection: 'row',
    alignItems: 'center',
  },
  iconBox: {
    marginRight: 10,
  },
  iconCircleWhite: {
    width: 20,
    height: 20,
    borderRadius: 10,
    backgroundColor: '#FFFFFF',
    alignItems: 'center',
    justifyContent: 'center',
  },
  iconText: {
    fontSize: 13,
    fontWeight: '800',
    lineHeight: 16,
  },
  messageText: {
    flex: 1,
    fontSize: 14,
    fontWeight: '500',
    color: '#FFFFFF',
    lineHeight: 20,
  },
  closeButton: {
    marginLeft: 12,
    padding: 4,
    alignItems: 'center',
    justifyContent: 'center',
  },
  closeIcon: {
    fontSize: 14,
    fontWeight: '700',
    color: '#FFFFFF',
  },
});
