import React from 'react';
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  StyleSheet,
  KeyboardTypeOptions,
} from 'react-native';
import { AuthColors, AuthTypography } from '../../theme/tokens';

export interface AuthInputFieldProps {
  label: string;
  value: string;
  onChangeText: (text: string) => void;
  placeholder?: string;
  secureTextEntry?: boolean;
  keyboardType?: KeyboardTypeOptions;
  autoCapitalize?: 'none' | 'sentences' | 'words' | 'characters';
  errorMessage?: string;
  showTogglePassword?: boolean;
  isPasswordVisible?: boolean;
  onTogglePasswordVisibility?: () => void;
  onFocus?: () => void;
  testID?: string;
}

export const AuthInputField: React.FC<AuthInputFieldProps> = ({
  label,
  value,
  onChangeText,
  placeholder,
  secureTextEntry = false,
  keyboardType = 'default',
  autoCapitalize = 'none',
  errorMessage,
  showTogglePassword = false,
  isPasswordVisible = false,
  onTogglePasswordVisibility,
  onFocus,
  testID = 'auth-input-field',
}) => {
  const hasError = !!errorMessage;

  return (
    <View style={styles.container}>
      <Text style={styles.label}>{label}</Text>
      <View
        style={[
          styles.inputContainer,
          hasError && styles.inputContainerError,
        ]}
      >
        <TextInput
          testID={testID}
          style={styles.textInput}
          value={value}
          onChangeText={onChangeText}
          onFocus={onFocus}
          placeholder={placeholder}
          placeholderTextColor={AuthColors.textMuted}
          secureTextEntry={secureTextEntry && !isPasswordVisible}
          keyboardType={keyboardType}
          autoCapitalize={autoCapitalize}
          autoCorrect={false}
        />
        {showTogglePassword && (
          <TouchableOpacity
            testID={`${testID}-toggle-visibility`}
            onPress={onTogglePasswordVisibility}
            style={styles.toggleButton}
            hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }}
          >
            <Text style={styles.toggleText}>
              {isPasswordVisible ? 'HIDE' : 'SHOW'}
            </Text>
          </TouchableOpacity>
        )}
      </View>
      {hasError ? (
        <Text testID={`${testID}-error`} style={styles.errorText}>
          {errorMessage}
        </Text>
      ) : null}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    marginBottom: 16,
  },
  label: {
    ...AuthTypography.label,
    color: AuthColors.textPrimary,
    marginBottom: 6,
  },
  inputContainer: {
    height: 48,
    borderWidth: 1,
    borderColor: AuthColors.border,
    borderRadius: 8,
    backgroundColor: AuthColors.inputBackground,
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 12,
  },
  inputContainerError: {
    borderColor: AuthColors.borderError,
    backgroundColor: AuthColors.errorBackground,
  },
  textInput: {
    flex: 1,
    height: 48,
    ...AuthTypography.bodyRegular,
    color: AuthColors.textPrimary,
    padding: 0,
  },
  toggleButton: {
    paddingHorizontal: 8,
    paddingVertical: 4,
  },
  toggleText: {
    ...AuthTypography.caption,
    color: AuthColors.textSecondary,
    fontWeight: '600',
  },
  errorText: {
    ...AuthTypography.error,
    color: AuthColors.errorText,
    marginTop: 4,
  },
});
