const NETWORK_TAG_REGEX = /network|http|api|fetch|axios|xhr|trcode|bizmob|rest|graphql/i;
const HTTP_STATUS_REGEX = /\b([1-5]\d{2})\b/;

function extractHttpStatus(entry: LogEntry): number | null {
  const match = entry.message?.match(HTTP_STATUS_REGEX);
  if (!match) return null;
  const code = Number(match[1]);
  if (code >= 100 && code <= 599) {
    return code;
  }
  return null;
}

function isNetworkLog(entry: LogEntry): boolean {
  if (NETWORK_TAG_REGEX.test(entry.tag || '')) return true;
  if (/\b(GET|POST|PUT|PATCH|DELETE|HTTP\/\d|status\s*[:=]?\s*[1-5]\d{2})\b/i.test(entry.message || '')) {
    return true;
  }
  return false;
}

function getHttpStatusColors(status: number): { text: string; bg: string; border: string } {
  if (status >= 500) return { text: '#DC2626', bg: '#FEF2F2', border: '#FECACA' };
  if (status >= 400) return { text: '#D97706', bg: '#FFFBEB', border: '#FDE68A' };
  if (status >= 300) return { text: '#2563EB', bg: '#EFF6FF', border: '#BFDBFE' };
  return { text: '#059669', bg: '#ECFDF5', border: '#A7F3D0' };
}

/**
 * Universal fallback clipboard copy for web, non-HTTPS environments, and headless environments
 */
function fallbackCopyTextToClipboard(text: string): boolean {
  if (typeof document === 'undefined') {
    return false;
  }
  try {
    const textArea = document.createElement('textarea');
    textArea.value = text;
    textArea.style.position = 'fixed';
    textArea.style.top = '0';
    textArea.style.left = '0';
    textArea.style.width = '2em';
    textArea.style.height = '2em';
    textArea.style.padding = '0';
    textArea.style.border = 'none';
    textArea.style.outline = 'none';
    textArea.style.boxShadow = 'none';
    textArea.style.background = 'transparent';
    textArea.setAttribute('readonly', '');
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();
    const successful = document.execCommand('copy');
    document.body.removeChild(textArea);
    return successful;
  } catch {
    return false;
  }
}

const formattedArgsCache = new WeakMap<any[], string>();

/**
 * Formats log entry arguments once per entry and caches the result
 * to avoid repeated JSON.stringify calls during scrolling, filtering, or re-renders.
 */
function formatLogArgs(args?: any[]): string | null {
  if (!args || args.length === 0) {
    return null;
  }
  const cached = formattedArgsCache.get(args);
  if (cached !== undefined) {
    return cached;
  }
  const formatted = args
    .map((arg) => {
      if (typeof arg === 'string') return arg;
      if (arg instanceof Error) {
        return `${arg.name}: ${arg.message}${arg.stack ? `\n${arg.stack}` : ''}`;
      }
      if (arg && typeof arg === 'object' && arg.name && arg.message && typeof arg.message === 'string') {
        return `${arg.name}: ${arg.message}${arg.stack ? `\n${arg.stack}` : ''}`;
      }
      try {
        return JSON.stringify(arg, null, 2);
      } catch {
        return String(arg);
      }
    })
    .join('\n');
  formattedArgsCache.set(args, formatted);
  return formatted;
}

interface LogItemCardProps {
  item: LogEntry;
  isCopied: boolean;
  testID: string;
  palette: ConsolePalette;
  onCopy: (item: LogEntry) => void;
  onPressTag: (tag: string) => void;
}

const LogItemCard: React.FC<LogItemCardProps> = React.memo(
  ({ item, isCopied, testID, palette, onCopy, onPressTag }) => {
    const colors = LEVEL_COLORS[item.level] || LEVEL_COLORS.INFO;
    const formattedArgs = useMemo(() => formatLogArgs(item.args), [item.args]);
    const isLongArgs = useMemo(() => {
      if (!formattedArgs) return false;
      return formattedArgs.length > 140 || formattedArgs.split('\n').length > 3;
    }, [formattedArgs]);
    const [argsExpanded, setArgsExpanded] = useState<boolean>(false);
    const httpStatus = useMemo(() => (isNetworkLog(item) ? extractHttpStatus(item) : null), [item]);
    const statusColors = httpStatus ? getHttpStatusColors(httpStatus) : null;

    const handlePressCopy = useCallback(() => {
      onCopy(item);
    }, [onCopy, item]);

    const handlePressTag = useCallback(() => {
      onPressTag(item.tag);
    }, [onPressTag, item.tag]);

    const handleToggleArgs = useCallback(() => {
      if (typeof process === 'undefined' || process.env?.NODE_ENV !== 'test') {
        LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);
      }
      setArgsExpanded((prev) => !prev);
    }, []);

    return (
      <TouchableOpacity
        testID={`${testID}-item-${item.id}`}
        style={[
          styles.logItemCard,
          {
            borderLeftColor: colors.text,
            backgroundColor: palette.cardBg,
            borderColor: palette.cardBorder,
          },
        ]}
        activeOpacity={0.92}
        delayLongPress={350}
        onLongPress={handlePressCopy}
      >
        <View style={styles.logItemHeader}>
          <View style={styles.logItemMetaRow}>
            <View style={[styles.levelBadge, { backgroundColor: colors.bg, borderColor: colors.border }]}>
              <Text style={[styles.levelBadgeText, { color: colors.text }]}>{item.level}</Text>
            </View>
            {httpStatus !== null && statusColors && (
              <View
                style={[
                  styles.levelBadge,
                  { backgroundColor: statusColors.bg, borderColor: statusColors.border },
                ]}
              >
                <Text style={[styles.levelBadgeText, { color: statusColors.text }]}>{httpStatus}</Text>
              </View>
            )}
            <TouchableOpacity
              testID={`${testID}-tag-${item.id}`}
              onPress={handlePressTag}
              activeOpacity={0.7}
              hitSlop={{ top: 4, bottom: 4, left: 4, right: 4 }}
            >
              <Text style={[styles.logTag, { color: palette.textSecondary }]}>{`[${item.tag}]`}</Text>
            </TouchableOpacity>
            <Text style={[styles.logTimestamp, { color: palette.textMuted }]}>{item.timestamp}</Text>
          </View>

          <TouchableOpacity
            testID={`${testID}-copy-${item.id}`}
            onPress={handlePressCopy}
            style={[
              styles.copyButton,
              { backgroundColor: palette.surfaceBg, borderColor: palette.cardBorder },
              isCopied && styles.copyButtonSuccess,
            ]}
            activeOpacity={0.7}
            hitSlop={{ top: 6, bottom: 6, left: 6, right: 6 }}
          >
            <View style={styles.btnContentRow}>
              {isCopied ? (
                <>
                  <CheckIconSvg size={11} color="#059669" />
                  <Text style={[styles.copyButtonText, styles.copyButtonTextSuccess]}>Copied</Text>
                </>
              ) : (
                <>
                  <CopyIconSvg size={11} color={palette.textSecondary} />
                  <Text style={[styles.copyButtonText, { color: palette.textSecondary }]}>Copy</Text>
                </>
              )}
            </View>
          </TouchableOpacity>
        </View>

        <Text style={[styles.logMessage, { color: palette.textPrimary }]} selectable={true}>
          {item.message}
        </Text>

        {formattedArgs !== null && (
          <View
            style={[
              styles.argsContainer,
              { backgroundColor: palette.argsBg, borderColor: palette.argsBorder },
            ]}
          >
            <Text
              style={[styles.argsText, { color: palette.argsText }]}
              selectable={true}
              numberOfLines={isLongArgs && !argsExpanded ? 3 : undefined}
            >
              {formattedArgs}
            </Text>
            {isLongArgs && (
              <TouchableOpacity
                testID={`${testID}-expand-${item.id}`}
                onPress={handleToggleArgs}
                style={styles.expandArgsBtn}
                activeOpacity={0.7}
              >
                <Text style={styles.expandArgsText}>
                  {argsExpanded ? 'Show less ▲' : 'Show more ▼'}
                </Text>
              </TouchableOpacity>
            )}
          </View>
        )}
      </TouchableOpacity>
    );
  }
);

export const LogConsole: React.FC<LogConsoleProps> = ({
  // showFloatingButton = typeof __DEV__ !== 'undefined' ? __DEV__ : true,
  showFloatingButton = true,
  extended = false,
  floatingButtonStyle,
  initialVisible = false,
  onVisibilityChange,
  testID = 'log-console',
}) => {
  const [isDark, setIsDark] = useState<boolean>(true);
  const [showVersions, setShowVersions] = useState<boolean>(false);
  const palette = isDark ? DARK_PALETTE : LIGHT_PALETTE;

  const [visible, setVisible] = useState<boolean>(initialVisible);
  const [sheetMode, setSheetMode] = useState<'full' | 'half'>('full');
  const backdropOpacity = useRef(new Animated.Value(initialVisible ? 1 : 0)).current;
  const sheetTranslateY = useRef(
    new Animated.Value(initialVisible ? 0 : Dimensions.get('window').height)
  ).current;

  const [logs, setLogs] = useState<LogEntry[]>(() => (initialVisible ? appLogger.getLogs() : []));
  const [errorCount, setErrorCount] = useState<number>(
    () => appLogger.getLogs().filter((l) => l.level === 'ERROR').length
  );
  const [activeTab, setActiveTab] = useState<LogFilterTab>('ALL');
  const [selectedTag, setSelectedTag] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [isPaused, setIsPaused] = useState<boolean>(false);
  const [isScrolledDown, setIsScrolledDown] = useState<boolean>(false);
  const [pausedNewCount, setPausedNewCount] = useState<number>(0);
  const [refreshing, setRefreshing] = useState<boolean>(false);

  const flatListRef = useRef<FlatList<LogEntry>>(null);
  const copyTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const visibleRef = useRef<boolean>(initialVisible);
  const isPausedRef = useRef<boolean>(false);
  const isScrolledDownRef = useRef<boolean>(false);
  const pendingLogsRef = useRef<LogEntry[]>([]);
  const pausedBufferRef = useRef<LogEntry[]>([]);
  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const lastErrorJumpIndexRef = useRef<number>(-1);

  visibleRef.current = visible;
  isPausedRef.current = isPaused;
  isScrolledDownRef.current = isScrolledDown;

  // Draggable floating button position & smooth dismiss animations
  const fabPan = useRef(new Animated.ValueXY({ x: 0, y: 0 })).current;
  const fabScale = useRef(new Animated.Value(1)).current;
  const fabOpacity = useRef(new Animated.Value(1)).current;
  const dismissZoneAnim = useRef(new Animated.Value(0)).current;
  const dismissZoneScale = useRef(new Animated.Value(1)).current;
  const fabOffsetRef = useRef<{ x: number; y: number }>({ x: 0, y: 0 });
  const fabDraggingRef = useRef<boolean>(false);
  const [fabDismissed, setFabDismissed] = useState<boolean>(false);
  const [isDraggingFab, setIsDraggingFab] = useState<boolean>(false);
  const [isOverDismissZone, setIsOverDismissZone] = useState<boolean>(false);
  const isOverDismissZoneRef = useRef<boolean>(false);

  useEffect(() => {
    return () => {
      if (copyTimerRef.current) {
        clearTimeout(copyTimerRef.current);
      }
      if (flushTimerRef.current) {
        clearTimeout(flushTimerRef.current);
      }
    };
  }, []);

  let insetsTop = 12;
  let insetsBottom = 16;
  try {
    const insets = useSafeAreaInsets();
    insetsTop = Math.max(insets?.top ?? 0, 12);
    insetsBottom = Math.max(insets?.bottom ?? 0, 16);
  } catch {
    insetsTop = 12;
    insetsBottom = 16;
  }

  // Keyboard avoidance: tracks native keyboard height and mobile web visualViewport
  const screenHeight = Dimensions.get('window').height;
  const kb = useKeyboardInfo(visible);
  const coveredByKeyboard = kb ? Math.max(kb.height, screenHeight - kb.top) : 0;
  const keyboardInset = kb ? coveredByKeyboard : 0;
  const isKeyboardOpen = keyboardInset > 0;
  // Explicit height above keyboard so the flex:1 FlatList never collapses to 0 height.
  // See docs/technical/issues/keyboard-and-input/log-console-keyboard-collapse.md
  const keyboardOpenSheetHeight = Math.max(screenHeight - keyboardInset - insetsTop - 8, 280);
  const sheetBottomPadding = isKeyboardOpen ? keyboardInset + 8 : insetsBottom;

  const triggerKeyboardHaptic = useCallback(() => {
    try {
      playHaptic({
        type: 2, // 2 = haptic only, 1 = sound only, 3 = both
        style: 'keyboard', // Keyboard tap style
      }).catch(() => { });
    } catch {
      // Ignore if haptic engine not available in current platform
    }
  }, []);

  // Keep logs synchronized with AppLogger stream without re-rendering when closed
  // and batch rapid bursts when open for smooth 60fps scrolling.
  useEffect(() => {
    appLogger.interceptConsole();
    const initial = appLogger.getLogs();
    setErrorCount(initial.filter((l) => l.level === 'ERROR').length);
    if (visibleRef.current) {
      setLogs(initial);
    }

    const unsubscribe = appLogger.subscribe((entry) => {
      if (entry.level === 'ERROR') {
        setErrorCount((prev) => prev + 1);
      }

      if (!visibleRef.current) {
        return;
      }

      if (isPausedRef.current || isScrolledDownRef.current) {
        pausedBufferRef.current.push(entry);
        setPausedNewCount(pausedBufferRef.current.length);
        return;
      }

      if (typeof process !== 'undefined' && process.env?.NODE_ENV === 'test') {
        setLogs((prev) => {
          const next = [...prev, entry];
          return next.length > 100 ? next.slice(next.length - 100) : next;
        });
        return;
      }

      pendingLogsRef.current.push(entry);
      if (!flushTimerRef.current) {
        flushTimerRef.current = setTimeout(() => {
          flushTimerRef.current = null;
          const batch = pendingLogsRef.current;
          pendingLogsRef.current = [];
          if (batch.length === 0) return;

          setLogs((prev) => {
            const next = [...prev, ...batch];
            return next.length > 100 ? next.slice(next.length - 100) : next;
          });
        }, 120);
      }
    });

    return () => {
      unsubscribe();
      if (flushTimerRef.current) {
        clearTimeout(flushTimerRef.current);
        flushTimerRef.current = null;
      }
      pendingLogsRef.current = [];
      pausedBufferRef.current = [];
    };
  }, []);

  // Smoothly animate backdrop fade + sheet slide-up in parallel on the native thread
  const runOpenAnimation = useCallback(
    (onComplete?: () => void) => {
      const startY = Dimensions.get('window').height;
      sheetTranslateY.setValue(startY);
      backdropOpacity.setValue(0);

      Animated.parallel([
        Animated.timing(backdropOpacity, {
          toValue: 1,
          duration: 220,
          easing: Easing.out(Easing.cubic),
          useNativeDriver: true,
        }),
        Animated.timing(sheetTranslateY, {
          toValue: 0,
          duration: 240,
          easing: Easing.out(Easing.cubic),
          useNativeDriver: true,
        }),
      ]).start(() => {
        onComplete?.();
      });
    },
    [backdropOpacity, sheetTranslateY]
  );

  const handleOpen = useCallback(() => {
    triggerKeyboardHaptic();
    pausedBufferRef.current = [];
    setPausedNewCount(0);
    setIsScrolledDown(false);
    setVisible(true);
    onVisibilityChange?.(true);

    if (typeof process !== 'undefined' && process.env?.NODE_ENV === 'test') {
      const currentLogs = appLogger.getLogs();
      setLogs(currentLogs);
      setErrorCount(currentLogs.filter((l) => l.level === 'ERROR').length);
      sheetTranslateY.setValue(0);
      backdropOpacity.setValue(1);
      return;
    }

    // Start slide-up on frame 1 and hydrate log cards once the slide finishes so animation stays 60fps
    requestAnimationFrame(() => {
      runOpenAnimation(() => {
        if (!visibleRef.current) return;
        const currentLogs = appLogger.getLogs();
        setLogs(currentLogs);
        setErrorCount(currentLogs.filter((l) => l.level === 'ERROR').length);
      });
    });
  }, [backdropOpacity, onVisibilityChange, runOpenAnimation, sheetTranslateY, triggerKeyboardHaptic]);

  const handleClose = useCallback(() => {
    triggerKeyboardHaptic();

    // In test environment, unmount immediately so tests run synchronously
    if (typeof process !== 'undefined' && process.env?.NODE_ENV === 'test') {
      setVisible(false);
      sheetTranslateY.setValue(0);
      onVisibilityChange?.(false);
      return;
    }

    const endY = Dimensions.get('window').height;
    Animated.parallel([
      Animated.timing(backdropOpacity, {
        toValue: 0,
        duration: 180,
        easing: Easing.in(Easing.cubic),
        useNativeDriver: true,
      }),
      Animated.timing(sheetTranslateY, {
        toValue: endY,
        duration: 190,
        easing: Easing.in(Easing.cubic),
        useNativeDriver: true,
      }),
    ]).start(() => {
      setVisible(false);
      onVisibilityChange?.(false);
    });
  }, [backdropOpacity, onVisibilityChange, sheetTranslateY, triggerKeyboardHaptic]);

  const handleClear = useCallback(() => {
    triggerKeyboardHaptic();
    appLogger.clearLogs();
    pendingLogsRef.current = [];
    pausedBufferRef.current = [];
    setPausedNewCount(0);
    setLogs([]);
    setErrorCount(0);
    setSelectedTag(null);
    lastErrorJumpIndexRef.current = -1;
  }, [triggerKeyboardHaptic]);

  const handleResumeAndScrollTop = useCallback(() => {
    triggerKeyboardHaptic();
    setIsPaused(false);
    setIsScrolledDown(false);
    const buffered = pausedBufferRef.current;
    pausedBufferRef.current = [];
    setPausedNewCount(0);
    if (buffered.length > 0) {
      setLogs((prev) => {
        const next = [...prev, ...buffered];
        return next.length > 100 ? next.slice(next.length - 100) : next;
      });
    }
    flatListRef.current?.scrollToOffset({ offset: 0, animated: true });
  }, [triggerKeyboardHaptic]);

  const handleRefresh = useCallback(() => {
    triggerKeyboardHaptic();
    setRefreshing(true);
    const currentLogs = appLogger.getLogs();
    pausedBufferRef.current = [];
    setPausedNewCount(0);
    setLogs(currentLogs);
    setErrorCount(currentLogs.filter((l) => l.level === 'ERROR').length);
    setRefreshing(false);
  }, [triggerKeyboardHaptic]);

  const handleListScroll = useCallback((event: NativeSyntheticEvent<NativeScrollEvent>) => {
    const offsetY = event.nativeEvent.contentOffset.y;
    const scrolled = offsetY > 40;
    if (scrolled !== isScrolledDownRef.current) {
      setIsScrolledDown(scrolled);
    }
  }, []);

  // Android hardware back button: clear active filters first, then close modal
  useEffect(() => {
    if (!visible) return;
    const subscription = BackHandler.addEventListener('hardwareBackPress', () => {
      if (searchQuery.length > 0) {
        setSearchQuery('');
        return true;
      }
      if (selectedTag) {
        setSelectedTag(null);
        return true;
      }
      handleClose();
      return true;
    });
    return () => subscription.remove();
  }, [visible, searchQuery, selectedTag, handleClose]);

  // Swipe-down to dismiss & drag between half/full snap points on sheet handle/header
  const sheetPanResponder = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => false,
        onMoveShouldSetPanResponder: (_, gesture) =>
          Math.abs(gesture.dy) > 8 && Math.abs(gesture.dy) > Math.abs(gesture.dx),
        onPanResponderMove: (_, gesture) => {
          if (gesture.dy > 0) {
            sheetTranslateY.setValue(gesture.dy);
          } else if (sheetMode === 'half' && gesture.dy < 0) {
            sheetTranslateY.setValue(Math.max(gesture.dy, -120));
          }
        },
        onPanResponderRelease: (_, gesture) => {
          if (gesture.dy > 140 || gesture.vy > 0.9) {
            handleClose();
            return;
          }
          if (gesture.dy > 55 && sheetMode === 'full') {
            setSheetMode('half');
          } else if (gesture.dy < -45 && sheetMode === 'half') {
            setSheetMode('full');
          }
          Animated.spring(sheetTranslateY, {
            toValue: 0,
            useNativeDriver: true,
            bounciness: 4,
          }).start();
        },
      }),
    [handleClose, sheetMode, sheetTranslateY]
  );

  // Draggable floating button with edge-snapping & smooth drag-to-bottom-center dismiss zone
  const fabPanResponder = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => false,
        onMoveShouldSetPanResponder: (_, gesture) =>
          Math.abs(gesture.dx) > 6 || Math.abs(gesture.dy) > 6,
        onPanResponderGrant: () => {
          fabDraggingRef.current = true;
          isOverDismissZoneRef.current = false;
          setIsDraggingFab(true);
          setIsOverDismissZone(false);
          fabPan.setOffset(fabOffsetRef.current);
          fabPan.setValue({ x: 0, y: 0 });

          // Smoothly slide & fade in the bottom dismiss zone
          Animated.spring(dismissZoneAnim, {
            toValue: 1,
            useNativeDriver: true,
            friction: 8,
            tension: 90,
          }).start();
        },
        onPanResponderMove: (_, gesture) => {
          fabPan.setValue({ x: gesture.dx, y: gesture.dy });
          const { width, height } = Dimensions.get('window');
          const overDismiss =
            gesture.moveY > height - 135 && Math.abs(gesture.moveX - width / 2) < 80;
          if (overDismiss !== isOverDismissZoneRef.current) {
            isOverDismissZoneRef.current = overDismiss;
            setIsOverDismissZone(overDismiss);
            if (overDismiss) {
              triggerKeyboardHaptic();
            }
            Animated.parallel([
              Animated.spring(dismissZoneScale, {
                toValue: overDismiss ? 1.12 : 1,
                useNativeDriver: true,
                friction: 7,
                tension: 120,
              }),
              Animated.spring(fabScale, {
                toValue: overDismiss ? 0.85 : 1,
                useNativeDriver: true,
                friction: 7,
                tension: 120,
              }),
            ]).start();
          }
        },
        onPanResponderRelease: (_, gesture) => {
          fabPan.flattenOffset();

          if (isOverDismissZoneRef.current) {
            isOverDismissZoneRef.current = false;
            triggerKeyboardHaptic();
            // Smoothly shrink & fade out both the floating button and dismiss zone before unmounting
            Animated.parallel([
              Animated.timing(fabScale, {
                toValue: 0,
                duration: 180,
                useNativeDriver: true,
              }),
              Animated.timing(fabOpacity, {
                toValue: 0,
                duration: 180,
                useNativeDriver: true,
              }),
              Animated.timing(dismissZoneAnim, {
                toValue: 0,
                duration: 180,
                useNativeDriver: true,
              }),
              Animated.timing(dismissZoneScale, {
                toValue: 0.85,
                duration: 180,
                useNativeDriver: true,
              }),
            ]).start(() => {
              fabDraggingRef.current = false;
              setIsDraggingFab(false);
              setIsOverDismissZone(false);
              fabOffsetRef.current = { x: 0, y: 0 };
              fabPan.setValue({ x: 0, y: 0 });
              fabScale.setValue(1);
              fabOpacity.setValue(1);
              dismissZoneScale.setValue(1);
              setFabDismissed(true);
            });
            return;
          }

          // Smoothly hide dismiss zone & restore button scale
          Animated.parallel([
            Animated.timing(dismissZoneAnim, {
              toValue: 0,
              duration: 160,
              useNativeDriver: true,
            }),
            Animated.spring(dismissZoneScale, {
              toValue: 1,
              useNativeDriver: true,
              friction: 7,
            }),
            Animated.spring(fabScale, {
              toValue: 1,
              useNativeDriver: true,
              friction: 7,
            }),
          ]).start(() => {
            setIsDraggingFab(false);
            setIsOverDismissZone(false);
          });

          const { width, height } = Dimensions.get('window');
          const finalX = fabOffsetRef.current.x + gesture.dx;
          const finalY = fabOffsetRef.current.y + gesture.dy;

          // Snap horizontally to left edge or right edge (default anchor is right: 16)
          const snapLeftX = -(width - 76);
          const targetX = finalX < snapLeftX / 2 ? snapLeftX : 0;
          const maxUpY = -(height - 180);
          const targetY = Math.max(maxUpY, Math.min(60, finalY));

          fabOffsetRef.current = { x: targetX, y: targetY };
          Animated.spring(fabPan, {
            toValue: { x: targetX, y: targetY },
            useNativeDriver: false,
            friction: 7,
          }).start(() => {
            fabDraggingRef.current = false;
          });
        },
        onPanResponderTerminate: () => {
          fabPan.flattenOffset();
          Animated.timing(dismissZoneAnim, {
            toValue: 0,
            duration: 140,
            useNativeDriver: true,
          }).start(() => {
            setIsDraggingFab(false);
            setIsOverDismissZone(false);
          });
          isOverDismissZoneRef.current = false;
          fabDraggingRef.current = false;
        },
      }),
    [dismissZoneAnim, dismissZoneScale, fabOpacity, fabPan, fabScale, triggerKeyboardHaptic]
  );

  const copyToClipboard = useCallback((text: string) => {
    // 1. React Native / react-native-web standard Clipboard module
    try {
      if (Clipboard && typeof Clipboard.setString === 'function') {
        Clipboard.setString(text);
      }
    } catch {
      // Ignore if Clipboard not available in current runtime
    }

    // 2. Modern browser navigator.clipboard API
    if (typeof navigator !== 'undefined' && navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
      navigator.clipboard.writeText(text).catch(() => {
        fallbackCopyTextToClipboard(text);
      });
      return;
    }

    // 3. Fallback to textarea selection + execCommand('copy')
    fallbackCopyTextToClipboard(text);
  }, []);

  const handleCopyLog = useCallback((item: LogEntry) => {
    triggerKeyboardHaptic();
    const serializedArgs = item.args
      ? `\nArguments: ${item.args
        .map((arg) => (typeof arg === 'string' ? arg : JSON.stringify(arg, null, 2)))
        .join('\n')}`
      : '';
    const fullLogText = `[${item.timestamp}] [${item.level}] [${item.tag}]: ${item.message}${serializedArgs}`;

    copyToClipboard(fullLogText);

    setCopiedId(item.id);
    if (copyTimerRef.current) clearTimeout(copyTimerRef.current);
    if (typeof process === 'undefined' || process.env?.NODE_ENV !== 'test') {
      copyTimerRef.current = setTimeout(() => {
        setCopiedId((current) => (current === item.id ? null : current));
      }, 2000);
    }
  }, [copyToClipboard, triggerKeyboardHaptic]);

  // Tab, Tag & Search Query Filter (newest first so latest records load immediately without scrollToEnd jump)
  const filteredLogs = useMemo(() => {
    const trimmedQuery = searchQuery.trim().toLowerCase();
    const result: LogEntry[] = [];

    for (let i = logs.length - 1; i >= 0; i -= 1) {
      const log = logs[i];
      if (activeTab === 'NETWORK') {
        if (!isNetworkLog(log)) {
          continue;
        }
      } else if (activeTab !== 'ALL' && log.level !== activeTab) {
        continue;
      }

      if (selectedTag && log.tag !== selectedTag) {
        continue;
      }

      if (trimmedQuery) {
        const tagMatch = log.tag?.toLowerCase().includes(trimmedQuery);
        const msgMatch = log.message?.toLowerCase().includes(trimmedQuery);
        const rawMatch = log.rawMessage?.toLowerCase().includes(trimmedQuery);
        const formattedArgs = formatLogArgs(log.args);
        const argsMatch = formattedArgs ? formattedArgs.toLowerCase().includes(trimmedQuery) : false;

        if (!tagMatch && !msgMatch && !rawMatch && !argsMatch) {
          continue;
        }
      }

      result.push(log);
    }

    return result;
  }, [logs, activeTab, selectedTag, searchQuery]);

  const handleCopyAll = useCallback(() => {
    triggerKeyboardHaptic();
    const allText = filteredLogs
      .map((item) => {
        const serializedArgs = item.args ? ` ${JSON.stringify(item.args)}` : '';
        return `[${item.timestamp}] [${item.level}] [${item.tag}]: ${item.message}${serializedArgs}`;
      })
      .join('\n');

    copyToClipboard(allText);

    setCopiedId('ALL');
    if (copyTimerRef.current) clearTimeout(copyTimerRef.current);
    if (typeof process === 'undefined' || process.env?.NODE_ENV !== 'test') {
      copyTimerRef.current = setTimeout(() => {
        setCopiedId((current) => (current === 'ALL' ? null : current));
      }, 2000);
    }
  }, [filteredLogs, copyToClipboard, triggerKeyboardHaptic]);

  const handleShareAll = useCallback(async () => {
    triggerKeyboardHaptic();
    const allText = filteredLogs
      .map((item) => {
        const serializedArgs = formatLogArgs(item.args);
        return `[${item.timestamp}] [${item.level}] [${item.tag}]: ${item.message}${serializedArgs ? `\n${serializedArgs}` : ''}`;
      })
      .join('\n');

    const MAX_SHARE_CHARS = 60000;
    const rawMessage = allText || 'No logs recorded.';
    const shareMessage =
      rawMessage.length > MAX_SHARE_CHARS
        ? `${rawMessage.slice(0, MAX_SHARE_CHARS)}\n\n... [truncated ${rawMessage.length - MAX_SHARE_CHARS} chars for OS share limit]`
        : rawMessage;

    try {
      if (Share && typeof Share.share === 'function') {
        const result = await Share.share(
          {
            title: 'App Log Console Export',
            message: shareMessage,
          },
          {
            dialogTitle: 'Share App Logs',
          }
        );
        if (result?.action !== Share.dismissedAction) {
          setCopiedId('SHARE');
          if (copyTimerRef.current) clearTimeout(copyTimerRef.current);
          if (typeof process === 'undefined' || process.env?.NODE_ENV !== 'test') {
            copyTimerRef.current = setTimeout(() => {
              setCopiedId((current) => (current === 'SHARE' ? null : current));
            }, 2000);
          }
        }
        return;
      }
    } catch {
      // Fall back to clipboard if native share sheet is unavailable or fails
    }

    copyToClipboard(rawMessage);
    setCopiedId('SHARE');
    if (copyTimerRef.current) clearTimeout(copyTimerRef.current);
    if (typeof process === 'undefined' || process.env?.NODE_ENV !== 'test') {
      copyTimerRef.current = setTimeout(() => {
        setCopiedId((current) => (current === 'SHARE' ? null : current));
      }, 2000);
    }
  }, [filteredLogs, copyToClipboard, triggerKeyboardHaptic]);

  const handlePressTag = useCallback(
    (tag: string) => {
      triggerKeyboardHaptic();
      setSelectedTag((prev) => (prev === tag ? null : tag));
    },
    [triggerKeyboardHaptic]
  );

  // Counts for each tab
  const tabCounts = useMemo(() => {
    const counts: Record<LogFilterTab, number> = {
      ALL: logs.length,
      INFO: 0,
      DEBUG: 0,
      WARN: 0,
      ERROR: 0,
      NETWORK: 0,
    };
    logs.forEach((l) => {
      if (l.level === 'INFO') counts.INFO += 1;
      else if (l.level === 'DEBUG') counts.DEBUG += 1;
      else if (l.level === 'WARN') counts.WARN += 1;
      else if (l.level === 'ERROR') counts.ERROR += 1;
      if (isNetworkLog(l)) counts.NETWORK += 1;
    });
    return counts;
  }, [logs]);

  const handleJumpToNextError = useCallback(() => {
    triggerKeyboardHaptic();
    const errorIndices: number[] = [];
    filteredLogs.forEach((item, idx) => {
      if (item.level === 'ERROR') errorIndices.push(idx);
    });
    if (errorIndices.length === 0) return;

    const nextIdx =
      errorIndices.find((idx) => idx > lastErrorJumpIndexRef.current) ?? errorIndices[0];
    lastErrorJumpIndexRef.current = nextIdx;
    try {
      flatListRef.current?.scrollToIndex({ index: nextIdx, animated: true, viewPosition: 0.2 });
    } catch {
      // Ignore if index is not yet measured
    }
  }, [filteredLogs, triggerKeyboardHaptic]);

  const keyExtractor = useCallback((item: LogEntry) => item.id, []);

  const renderLogItem = useCallback(
    ({ item }: ListRenderItemInfo<LogEntry>) => (
      <LogItemCard
        item={item}
        isCopied={copiedId === item.id}
        testID={testID}
        palette={palette}
        onCopy={handleCopyLog}
        onPressTag={handlePressTag}
      />
    ),
    [copiedId, handleCopyLog, handlePressTag, palette, testID]
  );

  const renderEmptyComponent = useCallback(
    () => (
      <View style={styles.emptyContainer} testID={`${testID}-empty`}>
        <ClipboardIconSvg size={36} color="#CBD5E1" />
        <Text style={styles.emptyTitle}>No Logs Found</Text>
        <Text style={styles.emptySubtitle}>
          {searchQuery
            ? `No entries match "${searchQuery}"`
            : `No ${activeTab === 'ALL' ? '' : activeTab} logs recorded yet`}
        </Text>
      </View>
    ),
    [activeTab, searchQuery, testID]
  );

  return (
    <>
      {/* Bottom-Center Dismiss Zone shown smoothly while dragging the floating button */}
      {showFloatingButton && !fabDismissed && isDraggingFab && (
        <Animated.View
          pointerEvents="none"
          testID={`${testID}-fab-dismiss-zone`}
          style={[
            styles.fabDismissZone,
            {
              bottom: insetsBottom + 16,
              opacity: dismissZoneAnim,
              transform: [
                {
                  translateY: dismissZoneAnim.interpolate({
                    inputRange: [0, 1],
                    outputRange: [44, 0],
                  }),
                },
                { scale: dismissZoneScale },
              ],
            },
            isOverDismissZone && styles.fabDismissZoneActive,
          ]}
        >
          <CloseIconSvg size={18} color={isOverDismissZone ? '#FFFFFF' : '#DC2626'} />
          <Text
            style={[
              styles.fabDismissLabel,
              isOverDismissZone && styles.fabDismissLabelActive,
            ]}
          >
            Drop to hide
          </Text>
        </Animated.View>
      )}

      {/* Draggable Floating Action Trigger Button with Edge Snapping & Smooth Drag-to-Dismiss */}
      {showFloatingButton && !fabDismissed && (
        <Animated.View
          {...fabPanResponder.panHandlers}
          style={[
            styles.floatingButtonAnchor,
            { transform: fabPan.getTranslateTransform() },
            floatingButtonStyle,
          ]}
        >
          <Animated.View
            style={{
              opacity: fabOpacity,
              transform: [{ scale: fabScale }],
            }}
          >
            <TouchableOpacity
              testID={`${testID}-floating-trigger`}
              style={[
                styles.floatingButton,
                extended && styles.floatingButtonExtended,
              ]}
              onPress={() => {
                if (!fabDraggingRef.current) {
                  handleOpen();
                }
              }}
              activeOpacity={0.8}
            >
              <View style={styles.floatingButtonInner}>
                <BugIcon size={18} color="#FFFFFF" />
                {extended && <Text style={styles.floatingButtonText}>Logs</Text>}
                {errorCount > 0 && (
                  <View style={styles.floatingBadge}>
                    <Text style={styles.floatingBadgeText}>{errorCount}</Text>
                  </View>
                )}
              </View>
            </TouchableOpacity>
          </Animated.View>
        </Animated.View>
      )}

      {/* Full Dedicated Log Console BottomSheet with Smooth Native-Driver Slide & Virtualized Scrolling */}
      <Modal
        visible={visible}
        transparent={true}
        animationType="none"
        statusBarTranslucent={true}
        navigationBarTranslucent={true}
        onRequestClose={handleClose}
        testID={testID}
      >
        <View style={styles.modalRoot}>
          {/* Backdrop overlay fades in smoothly alongside the sheet slide-up */}
          <Animated.View
            style={[
              styles.modalBackdrop,
              { opacity: backdropOpacity },
            ]}
          >
            <TouchableWithoutFeedback onPress={handleClose} testID={`${testID}-backdrop`}>
              <View style={styles.backdropDismiss} />
            </TouchableWithoutFeedback>
          </Animated.View>

          <Animated.View
            style={[
              styles.sheetContainer,
              {
                backgroundColor: palette.sheetBg,
                height: sheetMode === 'half' ? '48%' : '88%',
                transform: [{ translateY: sheetTranslateY }],
              },
              isKeyboardOpen
                ? {
                  height: keyboardOpenSheetHeight,
                  maxHeight: keyboardOpenSheetHeight,
                  marginBottom: keyboardInset,
                  paddingBottom: 8,
                }
                : { paddingBottom: insetsBottom },
            ]}
          >
            {/* Swipeable Drag Handle & Header */}
            <View {...sheetPanResponder.panHandlers}>
              <View
                style={[styles.dragHandle, { backgroundColor: palette.handleBg }]}
                testID={`${testID}-drag-handle`}
              />

              {/* Header: Title and Close */}
              <View style={[styles.headerRow, { borderBottomColor: palette.divider }]}>
                <View style={styles.headerLeft}>
                  <Text style={[styles.headerTitle, { color: palette.textPrimary }]} testID={`${testID}-title`}>
                    App Log Console
                  </Text>
                  <View style={[styles.headerTotalBadge, { backgroundColor: palette.surfaceBg }]}>
                    <Text style={[styles.headerTotalText, { color: palette.textSecondary }]}>{logs.length}</Text>
                  </View>
                  <TouchableOpacity
                    testID={`${testID}-versions-toggle`}
                    onPress={() => setShowVersions((v) => !v)}
                    style={[
                      styles.versionTogglePill,
                      {
                        backgroundColor: palette.surfaceBg,
                        borderColor: showVersions ? '#3B82F6' : palette.cardBorder,
                      },
                    ]}
                    activeOpacity={0.7}
                    hitSlop={{ top: 6, bottom: 6, left: 6, right: 6 }}
                  >
                    <Text
                      style={[
                        styles.versionToggleText,
                        { color: showVersions ? '#3B82F6' : palette.textSecondary },
                      ]}
                    >
                      {`v${HOST_VERSION} ${showVersions ? '▴' : '▾'}`}
                    </Text>
                  </TouchableOpacity>
                </View>

                <TouchableOpacity
                  testID={`${testID}-close`}
                  style={[styles.closeBtn, { backgroundColor: palette.surfaceBg }]}
                  onPress={handleClose}
                  hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
                  accessibilityRole="button"
                  accessibilityLabel="Close"
                >
                  <CloseIconSvg size={14} color={palette.textSecondary} />
                </TouchableOpacity>
              </View>

              {showVersions && (
                <View
                  testID={`${testID}-versions-panel`}
                  style={[
                    styles.versionsPanel,
                    { backgroundColor: palette.surfaceBg, borderBottomColor: palette.divider },
                  ]}
                >
                  {APP_MODULE_VERSIONS.map((mod) => (
                    <View
                      key={mod.key}
                      testID={`${testID}-version-${mod.key}`}
                      style={[
                        styles.versionChip,
                        {
                          backgroundColor: mod.isHost ? '#1D4ED8' : palette.cardBg,
                          borderColor: mod.isHost ? '#2563EB' : palette.cardBorder,
                        },
                      ]}
                    >
                      <Text
                        style={[
                          styles.versionChipLabel,
                          { color: mod.isHost ? '#DBEAFE' : palette.textMuted },
                        ]}
                      >
                        {mod.label}
                      </Text>
                      <Text
                        style={[
                          styles.versionChipValue,
                          { color: mod.isHost ? '#FFFFFF' : palette.textPrimary },
                        ]}
                      >
                        {`v${mod.version}`}
                      </Text>
                    </View>
                  ))}
                </View>
              )}
            </View>

            {/* Horizontally Scrollable Action Toolbar */}
            <View style={[styles.actionToolbarContainer, { borderBottomColor: palette.divider }]}>
              <ScrollView
                horizontal
                showsHorizontalScrollIndicator={false}
                nestedScrollEnabled={true}
                keyboardShouldPersistTaps="handled"
                contentContainerStyle={styles.actionToolbarScroll}
              >
                <TouchableOpacity
                  testID={`${testID}-pause-btn`}
                  style={[
                    styles.headerActionBtn,
                    { backgroundColor: palette.surfaceBg, borderColor: palette.cardBorder },
                    isPaused && styles.headerActionBtnActive,
                  ]}
                  onPress={() => {
                    if (isPaused) {
                      handleResumeAndScrollTop();
                    } else {
                      triggerKeyboardHaptic();
                      setIsPaused(true);
                    }
                  }}
                  activeOpacity={0.7}
                >
                  <Text
                    style={[
                      styles.headerActionBtnText,
                      { color: isPaused ? '#2563EB' : palette.textSecondary },
                    ]}
                  >
                    {isPaused ? 'Resume' : 'Pause'}
                  </Text>
                </TouchableOpacity>

                <TouchableOpacity
                  testID={`${testID}-copy-all-btn`}
                  style={[
                    styles.headerActionBtn,
                    { backgroundColor: palette.surfaceBg, borderColor: palette.cardBorder },
                  ]}
                  onPress={handleCopyAll}
                  activeOpacity={0.7}
                >
                  <Text
                    style={[
                      styles.headerActionBtnText,
                      { color: copiedId === 'ALL' ? '#059669' : palette.textSecondary },
                    ]}
                  >
                    {copiedId === 'ALL' ? 'Copied' : 'Copy All'}
                  </Text>
                </TouchableOpacity>

                <TouchableOpacity
                  testID={`${testID}-share-btn`}
                  style={[
                    styles.headerActionBtn,
                    { backgroundColor: palette.surfaceBg, borderColor: palette.cardBorder },
                  ]}
                  onPress={handleShareAll}
                  activeOpacity={0.7}
                >
                  <Text
                    style={[
                      styles.headerActionBtnText,
                      { color: copiedId === 'SHARE' ? '#059669' : palette.textSecondary },
                    ]}
                  >
                    {copiedId === 'SHARE' ? 'Shared' : 'Share'}
                  </Text>
                </TouchableOpacity>

                <TouchableOpacity
                  testID={`${testID}-snap-toggle`}
                  style={[
                    styles.headerActionBtn,
                    { backgroundColor: palette.surfaceBg, borderColor: palette.cardBorder },
                  ]}
                  onPress={() => {
                    triggerKeyboardHaptic();
                    setSheetMode((prev) => (prev === 'full' ? 'half' : 'full'));
                  }}
                  activeOpacity={0.7}
                >
                  <Text style={[styles.headerActionBtnText, { color: palette.textSecondary }]}>
                    {sheetMode === 'full' ? 'Half' : 'Full'}
                  </Text>
                </TouchableOpacity>

                <TouchableOpacity
                  testID={`${testID}-theme-toggle`}
                  style={[
                    styles.headerActionBtn,
                    { backgroundColor: palette.surfaceBg, borderColor: palette.cardBorder },
                  ]}
                  onPress={() => {
                    triggerKeyboardHaptic();
                    setIsDark((prev) => !prev);
                  }}
                  activeOpacity={0.7}
                >
                  <Text style={[styles.headerActionBtnText, { color: palette.textSecondary }]}>
                    {isDark ? 'Light' : 'Dark'}
                  </Text>
                </TouchableOpacity>
              </ScrollView>
            </View>

            {/* Segmented Pill Tab Bar (Modern Chip Style) */}
            <View style={[styles.tabContainer, { borderBottomColor: palette.divider }]}>
              <ScrollView
                horizontal
                showsHorizontalScrollIndicator={false}
                contentContainerStyle={styles.tabBarScroll}
              >
                {TABS.map((tab) => {
                  const isSelected = activeTab === tab.value;
                  const count = tabCounts[tab.value];
                  const levelColor =
                    tab.value === 'ALL'
                      ? { text: '#2563EB', bg: '#EFF6FF', border: '#BFDBFE' }
                      : tab.value === 'NETWORK'
                        ? NETWORK_COLOR
                        : LEVEL_COLORS[tab.value as LogLevel];

                  return (
                    <TouchableOpacity
                      key={tab.value}
                      testID={`${testID}-tab-${tab.value.toLowerCase()}`}
                      style={[
                        styles.chipTab,
                        { backgroundColor: palette.chipInactiveBg },
                        isSelected && {
                          backgroundColor: levelColor.text,
                          borderColor: levelColor.text,
                        },
                      ]}
                      onPress={() => {
                        triggerKeyboardHaptic();
                        setActiveTab(tab.value);
                      }}
                      activeOpacity={0.7}
                    >
                      <Text
                        style={[
                          styles.chipLabel,
                          isSelected && styles.chipLabelSelected,
                          !isSelected && { color: levelColor.text },
                        ]}
                      >
                        {tab.label}
                      </Text>
                      <View
                        style={[
                          styles.chipBadge,
                          isSelected && styles.chipBadgeSelected,
                          !isSelected && { backgroundColor: levelColor.bg },
                        ]}
                      >
                        <Text
                          style={[
                            styles.chipBadgeText,
                            isSelected && styles.chipBadgeTextSelected,
                            !isSelected && { color: levelColor.text },
                          ]}
                        >
                          {count}
                        </Text>
                      </View>
                    </TouchableOpacity>
                  );
                })}

                {tabCounts.ERROR > 0 && (
                  <TouchableOpacity
                    testID={`${testID}-jump-error-btn`}
                    style={[styles.chipTab, styles.chipTabErrorInactive]}
                    onPress={handleJumpToNextError}
                    activeOpacity={0.7}
                  >
                    <Text style={[styles.chipLabel, styles.chipLabelError]}>Next Error ↓</Text>
                  </TouchableOpacity>
                )}
              </ScrollView>

              {selectedTag && (
                <View style={styles.activeTagBar}>
                  <TouchableOpacity
                    testID={`${testID}-active-tag-chip`}
                    style={styles.activeTagChip}
                    onPress={() => setSelectedTag(null)}
                    activeOpacity={0.7}
                  >
                    <Text style={styles.activeTagChipText}>{`Tag: [${selectedTag}]  ×`}</Text>
                  </TouchableOpacity>
                </View>
              )}
            </View>

            {/* Virtualized Smooth Scrollable Log List View with Pull-to-Refresh & New Logs Pill */}
            <View style={styles.listWrapper}>
              <FlatList
                ref={flatListRef}
                testID={`${testID}-list`}
                data={filteredLogs}
                keyExtractor={keyExtractor}
                renderItem={renderLogItem}
                extraData={`${copiedId || ''}-${isDark ? 'd' : 'l'}`}
                style={styles.scrollList}
                contentContainerStyle={styles.listContent}
                keyboardShouldPersistTaps="handled"
                showsVerticalScrollIndicator={true}
                nestedScrollEnabled={true}
                initialNumToRender={12}
                maxToRenderPerBatch={10}
                updateCellsBatchingPeriod={40}
                windowSize={5}
                removeClippedSubviews={Platform.OS !== 'web'}
                onScroll={handleListScroll}
                scrollEventThrottle={100}
                refreshControl={
                  <RefreshControl refreshing={refreshing} onRefresh={handleRefresh} />
                }
                ListEmptyComponent={renderEmptyComponent}
              />

              {pausedNewCount > 0 && (
                <TouchableOpacity
                  testID={`${testID}-new-logs-pill`}
                  style={styles.newLogsPill}
                  onPress={handleResumeAndScrollTop}
                  activeOpacity={0.85}
                >
                  <Text style={styles.newLogsPillText}>
                    {`${pausedNewCount} new ${pausedNewCount === 1 ? 'log' : 'logs'} ↑`}
                  </Text>
                </TouchableOpacity>
              )}
            </View>

            {/* Bottom Controls Bar: Search Box & Clear Button */}
            <View
              style={[
                styles.bottomControlBar,
                { backgroundColor: palette.sheetBg, borderTopColor: palette.divider },
              ]}
            >
              <View
                style={[
                  styles.bottomSearchWrapper,
                  { backgroundColor: palette.surfaceBg, borderColor: palette.cardBorder },
                ]}
              >
                <View style={styles.searchIconWrapper}>
                  <SearchIconSvg size={14} color={palette.textSecondary} />
                </View>
                <TextInput
                  testID={`${testID}-search-input`}
                  style={[styles.bottomSearchInput, { color: palette.textPrimary }]}
                  placeholder="Search logs..."
                  placeholderTextColor={palette.textMuted}
                  value={searchQuery}
                  onChangeText={setSearchQuery}
                  autoCapitalize="none"
                  autoCorrect={false}
                  clearButtonMode="while-editing"
                />
                {searchQuery.length > 0 && (
                  <TouchableOpacity
                    testID={`${testID}-search-clear`}
                    onPress={() => setSearchQuery('')}
                    style={styles.clearSearchBtn}
                    hitSlop={{ top: 6, bottom: 6, left: 6, right: 6 }}
                  >
                    <CloseIconSvg size={12} color={palette.textMuted} />
                  </TouchableOpacity>
                )}
              </View>

              <TouchableOpacity
                testID={`${testID}-clear-btn`}
                style={styles.bottomClearBtn}
                onPress={handleClear}
                activeOpacity={0.7}
              >
                <View style={styles.btnContentRow}>
                  <TrashIconSvg size={12} color="#DC2626" />
                  <Text style={styles.bottomClearBtnText}>Clear</Text>
                </View>
              </TouchableOpacity>
            </View>
          </Animated.View>
        </View>
      </Modal>
    </>
  );
};

