import React, { useState } from 'react';
import { View, StyleSheet, Text } from 'react-native';
import { LoginScreen } from '../views/LoginScreen';
import { OtpVerificationScreen } from '../views/OtpVerificationScreen';
import { BiometricSetupScreen } from '../views/BiometricSetupScreen';
import { IAuthService, AuthService } from '../services/AuthService';
import { LoginResult } from '../models/AuthModel';
import { AuthColors, AuthTypography } from '../theme/tokens';

export type AuthScreenName =
  | 'Login'
  | 'LoginInvalid'
  | 'OtpVerification'
  | 'BiometricSetup'
  | 'AuthSuccess';

export interface AuthNavigatorProps {
  authService?: IAuthService;
  initialScreen?: AuthScreenName;
  onAuthComplete?: (sessionToken?: string) => void;
  onBack?: () => void;
  navigation?: any;
}

export const AuthNavigator: React.FC<AuthNavigatorProps> = ({
  authService = new AuthService(),
  initialScreen = 'Login',
  onAuthComplete,
  onBack,
  navigation: rootNavigation,
}) => {
  const [currentScreen, setCurrentScreen] = useState<AuthScreenName>(initialScreen);
  const [activeUser, setActiveUser] = useState<{
    userId: string;
    email?: string;
    phone?: string;
    token?: string;
  }>({
    userId: '',
  });

  const handleLoginSuccess = (result: LoginResult) => {
    setActiveUser({
      userId: 'user@example.com',
      email: result.userEmail || 'uy.***@gmail.com',
      phone: result.userPhone || '087****96',
      token: result.token,
    });

    if (result.requiresOtp) {
      setCurrentScreen('OtpVerification');
    } else if (result.requiresBiometricSetup) {
      setCurrentScreen('BiometricSetup');
    } else {
      finishAuthFlow(result.token);
    }
  };

  const handleOtpVerified = (verifiedToken?: string) => {
    const token = verifiedToken || activeUser.token;
    setActiveUser((prev) => ({ ...prev, token }));
    setCurrentScreen('BiometricSetup');
  };

  const handleBiometricFinished = () => {
    finishAuthFlow(activeUser.token);
  };

  const finishAuthFlow = (token?: string) => {
    if (onAuthComplete) {
      onAuthComplete(token);
    }
    // Terminal Auth boundary: Reset root navigation to DashboardFlow so user CANNOT back into Auth or Language
    if (rootNavigation && rootNavigation.reset) {
      rootNavigation.reset({
        index: 0,
        routes: [{ name: 'DashboardFlow' }],
      });
    } else if (rootNavigation && rootNavigation.navigate) {
      rootNavigation.navigate('DashboardFlow');
    } else {
      setCurrentScreen('AuthSuccess');
    }
  };

  return (
    <View testID="auth-navigator" style={styles.container}>
      {currentScreen === 'Login' && (
        <LoginScreen
          viewModelProps={{
            authService,
            onLoginSuccess: handleLoginSuccess,
            onNavigateToForgotPassword: () => setCurrentScreen('LoginInvalid'),
            onBack,
          }}
          showCompanyId={false}
        />
      )}

      {currentScreen === 'LoginInvalid' && (
        <LoginScreen
          viewModelProps={{
            authService,
            onLoginSuccess: handleLoginSuccess,
            onNavigateToForgotPassword: () => setCurrentScreen('Login'),
            onBack: () => setCurrentScreen('Login'),
          }}
          showCompanyId={true}
        />
      )}

      {currentScreen === 'OtpVerification' && (
        <OtpVerificationScreen
          viewModelProps={{
            authService,
            userId: activeUser.userId,
            userEmail: activeUser.email,
            userPhone: activeUser.phone,
            onOtpVerified: handleOtpVerified,
            onBack: () => setCurrentScreen('Login'),
          }}
        />
      )}

      {currentScreen === 'BiometricSetup' && (
        <BiometricSetupScreen
          viewModelProps={{
            authService,
            userId: activeUser.userId,
            onSetupSuccess: handleBiometricFinished,
            onSkip: handleBiometricFinished,
            onBack: () => setCurrentScreen('OtpVerification'),
          }}
        />
      )}

      {currentScreen === 'AuthSuccess' && (
        <View testID="auth-success-placeholder" style={styles.successContainer}>
          <Text style={styles.successTitle}>Authentication Successful</Text>
          <Text style={styles.successSubtitle}>
            You have logged in and completed verification!
          </Text>
        </View>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: AuthColors.white,
  },
  successContainer: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    padding: 24,
    backgroundColor: AuthColors.white,
  },
  successTitle: {
    ...AuthTypography.h1,
    color: AuthColors.primary,
    marginBottom: 8,
  },
  successSubtitle: {
    ...AuthTypography.bodyRegular,
    color: AuthColors.textSecondary,
    textAlign: 'center',
  },
});
