import React from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
  TextStyle,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export type ButtonGroupSize = 'sm' | 'md' | 'lg' | 'xs';
export type ButtonGroupVariant = 'segmented' | 'outlined' | 'solid' | 'pills';

export interface ButtonGroupItem<T = string> {
  value: T;
  label?: string;
  icon?: React.ReactNode;
  disabled?: boolean;
  badge?: number | string;
  testID?: string;
}

export interface ButtonGroupProps<T = string> {
  items: ButtonGroupItem<T>[];
  /**
   * For single selection: value of type T.
   * For multi selection: array of T.
   */
  value?: T | T[];
  onChange?: (value: T) => void;
  onMultiChange?: (values: T[]) => void;
  multiple?: boolean;
  size?: ButtonGroupSize;
  variant?: ButtonGroupVariant;
  orientation?: 'horizontal' | 'vertical';
  fullWidth?: boolean;
  rounded?: boolean;
  borderRadius?: number;
  disabled?: boolean;
  style?: ViewStyle;
  itemStyle?: ViewStyle;
  selectedItemStyle?: ViewStyle;
  textStyle?: TextStyle;
  selectedTextStyle?: TextStyle;
  activeColor?: string;
  testID?: string;
}

export const ButtonGroup = <T extends string | number>({
  items,
  value,
  onChange,
  onMultiChange,
  multiple = false,
  size = 'md',
  variant = 'segmented',
  orientation = 'horizontal',
  fullWidth = true,
  rounded = false,
  borderRadius,
  disabled = false,
  style,
  itemStyle,
  selectedItemStyle,
  textStyle,
  selectedTextStyle,
  activeColor,
  testID = 'button-group',
}: ButtonGroupProps<T>) => {
  const { theme } = useTheme();

  const isVertical = orientation === 'vertical';
  const resolvedActiveColor = activeColor || theme?.colors?.primary || '#E7252B';

  const isSelected = (val: T): boolean => {
    if (multiple && Array.isArray(value)) {
      return value.includes(val);
    }
    return value === val;
  };

  const handlePress = (item: ButtonGroupItem<T>) => {
    if (disabled || item.disabled) return;

    if (multiple) {
      const currentList = Array.isArray(value) ? [...value] : [];
      const index = currentList.indexOf(item.value);
      let nextList: T[];
      if (index > -1) {
        nextList = currentList.filter((v) => v !== item.value);
      } else {
        nextList = [...currentList, item.value];
      }
      onMultiChange?.(nextList);
    } else {
      onChange?.(item.value);
    }
  };

  // Determine container border radius
  const getResolvedBorderRadius = (): number => {
    if (typeof borderRadius === 'number') return borderRadius;
    if (rounded) return 9999;
    if (variant === 'pills') return 9999;
    return theme?.radius?.md ?? 8;
  };

  const containerRadius = getResolvedBorderRadius();

  // Size specifications
  const getSizeStyles = () => {
    switch (size) {
      case 'xs':
        return {
          height: 28,
          paddingHorizontal: 8,
          fontSize: 11,
          iconGap: 4,
        };
      case 'sm':
        return {
          height: 34,
          paddingHorizontal: 12,
          fontSize: 12,
          iconGap: 6,
        };
      case 'lg':
        return {
          height: 48,
          paddingHorizontal: 20,
          fontSize: 15,
          iconGap: 8,
        };
      case 'md':
      default:
        return {
          height: 40,
          paddingHorizontal: 16,
          fontSize: 13,
          iconGap: 6,
        };
    }
  };

  const currentSize = getSizeStyles();

  // Render badge helper
  const renderBadge = (badge: number | string | undefined, selected: boolean) => {
    if (badge === undefined || badge === null || badge === '') return null;
    return (
      <View
        style={[
          styles.badge,
          {
            backgroundColor: selected ? '#FFFFFF' : resolvedActiveColor,
          },
        ]}
      >
        <Text
          style={[
            styles.badgeText,
            {
              color: selected ? resolvedActiveColor : '#FFFFFF',
            },
          ]}
        >
          {badge}
        </Text>
      </View>
    );
  };

  return (
    <View
      testID={testID}
      style={[
        styles.container,
        isVertical ? styles.containerVertical : styles.containerHorizontal,
        variant === 'segmented' && styles.containerSegmented,
        variant === 'outlined' && styles.containerOutlined,
        variant === 'solid' && styles.containerSolid,
        variant === 'pills' && styles.containerPills,
        fullWidth && styles.fullWidth,
        {
          borderRadius: containerRadius,
          borderColor: theme?.colors?.border || '#E2E5EB',
        },
        style,
      ]}
    >
      {items.map((item, index) => {
        const selected = isSelected(item.value);
        const isFirst = index === 0;
        const isLast = index === items.length - 1;
        const isItemDisabled = disabled || Boolean(item.disabled);

        // Border radius on outer edges for segmented/outlined variants
        let itemBorderRadiusStyle: ViewStyle = {};
        if (variant === 'segmented' || variant === 'outlined') {
          if (rounded || variant === 'pills') {
            if (isVertical) {
              itemBorderRadiusStyle = {
                borderTopLeftRadius: isFirst ? containerRadius : 0,
                borderTopRightRadius: isFirst ? containerRadius : 0,
                borderBottomLeftRadius: isLast ? containerRadius : 0,
                borderBottomRightRadius: isLast ? containerRadius : 0,
              };
            } else {
              itemBorderRadiusStyle = {
                borderTopLeftRadius: isFirst ? containerRadius : 0,
                borderBottomLeftRadius: isFirst ? containerRadius : 0,
                borderTopRightRadius: isLast ? containerRadius : 0,
                borderBottomRightRadius: isLast ? containerRadius : 0,
              };
            }
          }
        } else if (variant === 'pills') {
          itemBorderRadiusStyle = { borderRadius: containerRadius };
        } else {
          itemBorderRadiusStyle = { borderRadius: theme?.radius?.sm ?? 6 };
        }

        // Inner item styling based on variant and selection
        let dynamicItemStyle: ViewStyle = {};
        let dynamicTextColor = theme?.colors?.text || '#16181D';

        switch (variant) {
          case 'outlined':
            dynamicItemStyle = {
              backgroundColor: selected ? resolvedActiveColor : 'transparent',
              borderWidth: 0.5,
              borderColor: selected ? resolvedActiveColor : theme?.colors?.border || '#E2E5EB',
            };
            dynamicTextColor = selected ? '#FFFFFF' : theme?.colors?.text || '#16181D';
            break;

          case 'solid':
            dynamicItemStyle = {
              backgroundColor: selected ? resolvedActiveColor : theme?.colors?.card || '#FFFFFF',
              marginHorizontal: isVertical ? 0 : 3,
              marginVertical: isVertical ? 3 : 0,
              borderWidth: 1,
              borderColor: selected ? resolvedActiveColor : theme?.colors?.border || '#E2E5EB',
            };
            dynamicTextColor = selected ? '#FFFFFF' : theme?.colors?.text || '#16181D';
            break;

          case 'pills':
            dynamicItemStyle = {
              backgroundColor: selected ? resolvedActiveColor : '#E5E7EB',
              marginHorizontal: isVertical ? 0 : 4,
              marginVertical: isVertical ? 4 : 0,
            };
            dynamicTextColor = selected ? '#FFFFFF' : theme?.colors?.textSubtle || '#64748B';
            break;

          case 'segmented':
          default:
            dynamicItemStyle = {
              backgroundColor: selected ? '#FFFFFF' : 'transparent',
              shadowColor: selected ? '#000000' : 'transparent',
              shadowOffset: { width: 0, height: 1 },
              shadowOpacity: selected ? 0.08 : 0,
              shadowRadius: selected ? 3 : 0,
              elevation: selected ? 2 : 0,
            };
            dynamicTextColor = selected
              ? resolvedActiveColor
              : theme?.colors?.textMuted || '#4B5563';
            break;
        }

        if (isItemDisabled) {
          dynamicItemStyle.opacity = 0.45;
        }

        return (
          <TouchableOpacity
            key={`btn-group-${item.value}`}
            testID={item.testID || `${testID}-item-${item.value}`}
            accessibilityRole="button"
            accessibilityState={{ selected, disabled: isItemDisabled }}
            activeOpacity={0.75}
            onPress={() => handlePress(item)}
            disabled={isItemDisabled}
            style={[
              styles.itemBase,
              {
                minHeight: currentSize.height,
                paddingHorizontal: currentSize.paddingHorizontal,
                gap: currentSize.iconGap,
              },
              fullWidth && (isVertical ? styles.itemFullWidth : styles.itemFlex),
              itemBorderRadiusStyle,
              dynamicItemStyle,
              itemStyle,
              selected && selectedItemStyle,
            ]}
          >
            {item.icon && <View style={styles.iconWrap}>{item.icon}</View>}

            {item.label ? (
              <Text
                testID={`${item.testID || `${testID}-item-${item.value}`}-label`}
                numberOfLines={1}
                style={[
                  styles.itemText,
                  {
                    fontSize: currentSize.fontSize,
                    color: dynamicTextColor,
                    fontFamily: selected
                      ? theme?.typography?.fontFamilyBold || 'Pretendard-Bold'
                      : theme?.typography?.fontFamily || 'Pretendard',
                    fontWeight: selected ? '700' : '500',
                  },
                  textStyle,
                  selected && selectedTextStyle,
                ]}
              >
                {item.label}
              </Text>
            ) : null}

            {renderBadge(item.badge, selected)}
          </TouchableOpacity>
        );
      })}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    overflow: 'hidden',
  },
  containerHorizontal: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  containerVertical: {
    flexDirection: 'column',
    alignItems: 'stretch',
  },
  containerSegmented: {
    backgroundColor: '#F1F3F6',
    padding: 3,
  },
  containerOutlined: {
    backgroundColor: 'transparent',
    borderWidth: 1,
  },
  containerSolid: {
    backgroundColor: 'transparent',
    padding: 2,
  },
  containerPills: {
    backgroundColor: 'transparent',
    padding: 2,
  },
  fullWidth: {
    width: '100%',
  },
  itemBase: {
    alignItems: 'center',
    justifyContent: 'center',
    flexDirection: 'row',
  },
  itemFlex: {
    flex: 1,
  },
  itemFullWidth: {
    width: '100%',
  },
  iconWrap: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  itemText: {
    textAlign: 'center',
  },
  badge: {
    minWidth: 18,
    height: 18,
    borderRadius: 9,
    paddingHorizontal: 4,
    alignItems: 'center',
    justifyContent: 'center',
    marginLeft: 4,
  },
  badgeText: {
    fontSize: 10,
    fontWeight: '700',
  },
});
