import React from 'react';
import { View, Text, TouchableOpacity, StyleSheet, ViewStyle } from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export interface KeyValueItem {
  key: string;
  label: string;
  value: string | number;
  highlight?: boolean;
  valueColor?: string;
  badge?: string;
  onPress?: () => void;
}

export interface SummaryKeyValueListProps {
  title?: string;
  items: KeyValueItem[];
  dense?: boolean;
  bordered?: boolean;
  style?: ViewStyle;
  testID?: string;
}

export const SummaryKeyValueList: React.FC<SummaryKeyValueListProps> = ({
  title,
  items,
  dense = false,
  bordered = false,
  style,
  testID = 'summary-key-value-list',
}) => {
  const { theme } = useTheme();

  return (
    <View
      testID={testID}
      style={[
        styles.container,
        bordered && [
          styles.bordered,
          {
            borderColor: theme.colors.border,
            borderRadius: theme.radius.lg,
            backgroundColor: theme.colors.card,
          },
        ],
        style,
      ]}
    >
      {title ? (
        <Text
          testID={`${testID}-title`}
          style={[
            styles.title,
            { color: theme.colors.text, fontFamily: theme.typography.fontFamilyBold },
          ]}
        >
          {title}
        </Text>
      ) : null}

      <View style={styles.list}>
        {items.map((item, index) => {
          const rowContent = (
            <View
              key={item.key}
              testID={`${testID}-row-${item.key}`}
              style={[
                styles.row,
                dense ? styles.denseRow : styles.normalRow,
                index < items.length - 1 && styles.rowDivider,
              ]}
            >
              <Text style={styles.label}>{item.label}</Text>

              <View style={styles.valueWrap}>
                <Text
                  testID={`${testID}-value-${item.key}`}
                  style={[
                    styles.value,
                    item.highlight && styles.highlightValue,
                    item.valueColor ? { color: item.valueColor } : null,
                  ]}
                >
                  {String(item.value)}
                </Text>

                {item.badge ? (
                  <View
                    style={[
                      styles.badge,
                      { backgroundColor: theme.colors.primaryLight },
                    ]}
                  >
                    <Text
                      style={[styles.badgeText, { color: theme.colors.primary }]}
                    >
                      {item.badge}
                    </Text>
                  </View>
                ) : null}
              </View>
            </View>
          );

          if (item.onPress) {
            return (
              <TouchableOpacity
                key={item.key}
                activeOpacity={0.7}
                onPress={item.onPress}
              >
                {rowContent}
              </TouchableOpacity>
            );
          }

          return rowContent;
        })}
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    marginVertical: 4,
  },
  bordered: {
    borderWidth: 1,
    padding: 14,
  },
  title: {
    fontSize: 15,
    fontWeight: '700',
    marginBottom: 8,
  },
  list: {
    width: '100%',
  },
  row: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  normalRow: {
    paddingVertical: 10,
  },
  denseRow: {
    paddingVertical: 6,
  },
  rowDivider: {
    borderBottomWidth: 1,
    borderBottomColor: '#F3F4F6',
  },
  label: {
    fontSize: 13,
    color: '#6B7280',
    flex: 1,
  },
  valueWrap: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 6,
  },
  value: {
    fontSize: 14,
    fontWeight: '600',
    color: '#111827',
    textAlign: 'right',
  },
  highlightValue: {
    fontSize: 16,
    fontWeight: '700',
    color: '#E7252B',
  },
  badge: {
    paddingHorizontal: 6,
    paddingVertical: 2,
    borderRadius: 4,
  },
  badgeText: {
    fontSize: 11,
    fontWeight: '700',
  },
});

