import React, { useState } from 'react';
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { AppButton } from '../button/AppButton';

export interface PasswordRule {
  id: string;
  label: string;
  test: (pw: string) => boolean;
}

export interface PasswordValidationFormProps {
  newPasswordLabel?: string;
  confirmPasswordLabel?: string;
  onSubmit: (password: string) => void;
  submitButtonText?: string;
  isLoading?: boolean;
  style?: ViewStyle;
  testID?: string;
}

export const DEFAULT_LOTTE_PASSWORD_RULES: PasswordRule[] = [
  {
    id: 'length',
    label: 'Password must be 8 to 15 characters',
    test: (pw) => pw.length >= 8 && pw.length <= 15,
  },
  {
    id: 'start-uppercase',
    label: 'Password must start with an uppercase letter',
    test: (pw) => /^[A-Z]/.test(pw),
  },
  {
    id: 'char-variety',
    label: 'Include letters, numbers and special characters',
    test: (pw) =>
      /[A-Za-z]/.test(pw) && /[0-9]/.test(pw) && /[^A-Za-z0-9]/.test(pw),
  },
];

export const PasswordValidationForm: React.FC<PasswordValidationFormProps> = ({
  newPasswordLabel = 'Enter new password',
  confirmPasswordLabel = 'Re-enter password',
  onSubmit,
  submitButtonText = 'Confirm',
  isLoading = false,
  style,
  testID = 'password-validation-form',
}) => {
  const { theme } = useTheme();
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  // Check rule states
  const ruleResults = DEFAULT_LOTTE_PASSWORD_RULES.map((rule) => ({
    id: rule.id,
    label: rule.label,
    valid: rule.test(password),
  }));

  const allRulesPassed = ruleResults.every((r) => r.valid);
  const passwordsMatch = password.length > 0 && password === confirmPassword;
  const isFormValid = allRulesPassed && passwordsMatch;

  const handleSubmit = () => {
    if (!isFormValid || isLoading) return;
    onSubmit(password);
  };

  return (
    <View testID={testID} style={[styles.container, style]}>
      {/* 1. Enter New Password Field */}
      <View style={styles.fieldGroup}>
        <Text style={styles.label}>
          {newPasswordLabel} <Text style={{ color: '#E7252B' }}>*</Text>
        </Text>
        <View style={styles.inputWrap}>
          <TextInput
            testID={`${testID}-new-input`}
            value={password}
            onChangeText={setPassword}
            placeholder="Enter new password"
            placeholderTextColor="#9CA3AF"
            secureTextEntry={!showPassword}
            autoCapitalize="none"
            autoCorrect={false}
            style={styles.input}
          />
          <TouchableOpacity
            testID={`${testID}-toggle-new`}
            onPress={() => setShowPassword(!showPassword)}
            style={styles.eyeBtn}
            activeOpacity={0.7}
          >
            <Text style={styles.eyeIcon}>{showPassword ? '🙈' : '👁'}</Text>
          </TouchableOpacity>
        </View>
      </View>

      {/* 2. Live Criteria Checklist */}
      <View style={styles.rulesList} testID={`${testID}-rules-list`}>
        {ruleResults.map((r) => (
          <View key={r.id} style={styles.ruleRow} testID={`${testID}-rule-${r.id}`}>
            <View
              style={[
                styles.checkCircle,
                r.valid ? styles.checkCircleValid : styles.checkCircleDefault,
              ]}
            >
              <Text style={[styles.checkMark, r.valid ? styles.checkMarkValid : styles.checkMarkDefault]}>
                ✓
              </Text>
            </View>
            <Text
              style={[
                styles.ruleText,
                r.valid ? styles.ruleTextValid : styles.ruleTextDefault,
              ]}
            >
              {r.label}
            </Text>
          </View>
        ))}
      </View>

      {/* 3. Re-enter Password Field */}
      <View style={styles.fieldGroup}>
        <Text style={styles.label}>
          {confirmPasswordLabel} <Text style={{ color: '#E7252B' }}>*</Text>
        </Text>
        <View style={styles.inputWrap}>
          <TextInput
            testID={`${testID}-confirm-input`}
            value={confirmPassword}
            onChangeText={setConfirmPassword}
            placeholder="Re-enter password"
            placeholderTextColor="#9CA3AF"
            secureTextEntry={!showConfirmPassword}
            autoCapitalize="none"
            autoCorrect={false}
            style={styles.input}
          />
          <TouchableOpacity
            testID={`${testID}-toggle-confirm`}
            onPress={() => setShowConfirmPassword(!showConfirmPassword)}
            style={styles.eyeBtn}
            activeOpacity={0.7}
          >
            <Text style={styles.eyeIcon}>{showConfirmPassword ? '🙈' : '👁'}</Text>
          </TouchableOpacity>
        </View>

        {confirmPassword.length > 0 && !passwordsMatch && (
          <Text testID={`${testID}-mismatch-msg`} style={styles.mismatchText}>
            ✕ Passwords do not match
          </Text>
        )}
      </View>

      {/* 4. Confirm Button */}
      <AppButton
        title={submitButtonText}
        variant="primary"
        disabled={!isFormValid}
        loading={isLoading}
        onPress={handleSubmit}
        testID={`${testID}-submit-btn`}
        style={styles.submitBtn}
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    width: '100%',
    backgroundColor: '#FFFFFF',
  },
  fieldGroup: {
    marginBottom: 16,
  },
  label: {
    fontSize: 14,
    fontWeight: '700',
    color: '#111827',
    marginBottom: 8,
  },
  inputWrap: {
    flexDirection: 'row',
    alignItems: 'center',
    height: 48,
    borderWidth: 1,
    borderColor: '#E5E7EB',
    borderRadius: 12,
    paddingHorizontal: 14,
    backgroundColor: '#FFFFFF',
  },
  input: {
    flex: 1,
    fontSize: 15,
    color: '#111827',
  },
  eyeBtn: {
    padding: 6,
  },
  eyeIcon: {
    fontSize: 18,
    color: '#6B7280',
  },
  rulesList: {
    gap: 12,
    marginBottom: 20,
    paddingLeft: 2,
  },
  ruleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 10,
  },
  checkCircle: {
    width: 20,
    height: 20,
    borderRadius: 10,
    justifyContent: 'center',
    alignItems: 'center',
  },
  checkCircleDefault: {
    backgroundColor: '#6B7280',
  },
  checkCircleValid: {
    backgroundColor: '#0E9F6E',
  },
  checkMark: {
    fontSize: 12,
    fontWeight: '800',
  },
  checkMarkDefault: {
    color: '#FFFFFF',
  },
  checkMarkValid: {
    color: '#FFFFFF',
  },
  ruleText: {
    fontSize: 13,
    lineHeight: 18,
  },
  ruleTextDefault: {
    color: '#4B5563',
  },
  ruleTextValid: {
    color: '#111827',
    fontWeight: '600',
  },
  mismatchText: {
    fontSize: 12,
    color: '#E7252B',
    marginTop: 6,
    fontWeight: '600',
  },
  submitBtn: {
    marginTop: 10,
    height: 48,
    backgroundColor: '#E7252B',
    borderRadius: 12,
  },
});

