import { useState, useEffect } from 'react';
import { Keyboard, Platform, Dimensions } from 'react-native';

export interface KeyboardInfo {
  /** Y (screen coords) of the keyboard's top edge */
  top: number;
  /** Height in density pixels reported by the OS */
  height: number;
}

/**
 * Tracks the on-screen keyboard height (native Keyboard events, or
 * visualViewport on mobile web) so modals and sheets can sit exactly on top of it.
 *
 * @param active Whether the component/modal using this hook is currently active/visible.
 */
export const useKeyboardInfo = (active: boolean = true): KeyboardInfo | null => {
  const [kb, setKb] = useState<KeyboardInfo | null>(null);

  useEffect(() => {
    if (!active) {
      setKb(null);
      return;
    }

    if (Platform.OS === 'web') {
      const win: any = typeof globalThis !== 'undefined' ? (globalThis as any).window : null;
      const vv: any = win ? win.visualViewport : null;
      if (!vv) return;
      const update = () => {
        const covered = win.innerHeight - vv.height - vv.offsetTop;
        setKb(covered > 80 ? { top: win.innerHeight - covered, height: covered } : null);
      };
      vv.addEventListener('resize', update);
      vv.addEventListener('scroll', update);
      update();
      return () => {
        vv.removeEventListener('resize', update);
        vv.removeEventListener('scroll', update);
      };
    }

    const showEvt = Platform.OS === 'ios' ? 'keyboardWillShow' : 'keyboardDidShow';
    const hideEvt = Platform.OS === 'ios' ? 'keyboardWillHide' : 'keyboardDidHide';
    const screenH = Dimensions.get('screen').height;
    const show = Keyboard.addListener(showEvt, (e) =>
      setKb({
        top: e.endCoordinates.screenY || screenH - e.endCoordinates.height,
        height: e.endCoordinates.height,
      }),
    );
    const hide = Keyboard.addListener(hideEvt, () => setKb(null));
    return () => {
      show.remove();
      hide.remove();
    };
  }, [active]);

  return kb;
};

