import { useState, useEffect, useMemo, useCallback } from 'react';
import { OfflineDataService } from '../services/OfflineDataService';
import { OfflineItem } from '../models/OfflineDataModel';

export function useOfflineDataViewModel() {
  const [activeTab, setActiveTab] = useState<'ALL' | 'BRANCH' | 'EVENT'>('ALL');
  const [searchQuery, setSearchQuery] = useState('');
  const [items, setItems] = useState<OfflineItem[]>([]);
  const [selectedItem, setSelectedItem] = useState<OfflineItem | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isOfflineReady, setIsOfflineReady] = useState(false);

  const loadData = useCallback(async () => {
    setIsLoading(true);
    try {
      const typeParam = activeTab === 'ALL' ? undefined : activeTab;
      const loaded = await OfflineDataService.getItems(typeParam);
      setItems(loaded);
      setIsOfflineReady(true);
    } finally {
      setIsLoading(false);
    }
  }, [activeTab]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const filteredItems = useMemo(() => {
    if (!searchQuery.trim()) return items;
    const q = searchQuery.toLowerCase();
    return items.filter(
      (it) =>
        it.title.toLowerCase().includes(q) ||
        it.subtitle.toLowerCase().includes(q) ||
        it.detail.toLowerCase().includes(q)
    );
  }, [items, searchQuery]);

  const handleToggleFavorite = async (id: string) => {
    const updatedStatus = await OfflineDataService.toggleFavorite(id);
    setItems((prev) =>
      prev.map((it) => (it.id === id ? { ...it, isFavorite: updatedStatus } : it))
    );
    if (selectedItem?.id === id) {
      setSelectedItem((prev) => (prev ? { ...prev, isFavorite: updatedStatus } : null));
    }
  };

  return {
    activeTab,
    setActiveTab,
    searchQuery,
    setSearchQuery,
    items: filteredItems,
    selectedItem,
    setSelectedItem,
    isLoading,
    isOfflineReady,
    handleToggleFavorite,
    reload: loadData,
  };
}

