import React, { useState } from 'react';
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  StyleSheet,
  TextInputProps,
  Platform,
} from 'react-native';
import { ValidationFormatUtil } from '@mfe/core/utils/validationFormatUtil';

export type ValidatedInputType = 'phone' | 'email' | 'password' | 'account' | 'cccd' | 'text';

export interface ValidatedInputProps extends Omit<TextInputProps, 'style'> {
  label: string;
  type?: ValidatedInputType;
  value: string;
  onChangeValue: (text: string, isValid: boolean) => void;
  required?: boolean;
  helperText?: string;
  customValidator?: (text: string) => { isValid: boolean; error?: string };
  autoFormat?: boolean;
  testID?: string;
}

/**
 * Enterprise Form Input with built-in:
 * - Phone validation & auto-formatting (0912 345 678)
 * - Email RFC 5322 validation
 * - Password Hide/Show toggle button with secureTextEntry
 * - Bank account formatting
 * - CCCD / Citizen ID validation
 * - Real-time error messages, clean focus states, and zero-outline web styling
 */
export const ValidatedInput: React.FC<ValidatedInputProps> = ({
  label,
  type = 'text',
  value,
  onChangeValue,
  required = false,
  helperText,
  customValidator,
  autoFormat = true,
  placeholder,
  testID = 'validated-input',
  ...rest
}) => {
  const [isFocused, setIsFocused] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [touched, setTouched] = useState(false);

  // Validate current value
  let isValid = true;
  let validationError: string | undefined = undefined;

  if (value.trim().length > 0 || touched) {
    if (required && !value.trim()) {
      isValid = false;
      validationError = `${label} is required`;
    } else if (customValidator) {
      const res = customValidator(value);
      isValid = res.isValid;
      validationError = res.error;
    } else {
      switch (type) {
        case 'phone': {
          const res = ValidationFormatUtil.validatePhoneNumber(value);
          isValid = res.isValid;
          validationError = res.error;
          break;
        }
        case 'email': {
          const res = ValidationFormatUtil.validateEmail(value);
          isValid = res.isValid;
          validationError = res.error;
          break;
        }
        case 'password': {
          if (value.length < 6) {
            isValid = false;
            validationError = 'Password must be at least 6 characters';
          }
          break;
        }
        case 'account': {
          const res = ValidationFormatUtil.validateAccountNumber(value);
          isValid = res.isValid;
          validationError = res.error;
          break;
        }
        case 'cccd': {
          const res = ValidationFormatUtil.validateCccdOrId(value);
          isValid = res.isValid;
          validationError = res.error;
          break;
        }
      }
    }
  }

  const handleChangeText = (rawText: string) => {
    setTouched(true);
    let processedText = rawText;

    if (type === 'phone') {
      // Filter out non-numeric characters (except leading +) and limit to max 10 domestic / 15 intl digits
      const sanitized = ValidationFormatUtil.sanitizePhoneNumber(rawText);
      processedText = autoFormat && !rawText.startsWith('+')
        ? ValidationFormatUtil.formatPhoneNumber(sanitized)
        : sanitized;
    } else if (autoFormat) {
      if (type === 'account') {
        processedText = ValidationFormatUtil.formatAccountNumber(rawText);
      } else if (type === 'cccd') {
        processedText = ValidationFormatUtil.formatCccd(rawText);
      }
    }

    // Determine validity with newly processed text
    let nextValid = true;
    if (type === 'phone') nextValid = ValidationFormatUtil.validatePhoneNumber(processedText).isValid;
    else if (type === 'email') nextValid = ValidationFormatUtil.validateEmail(processedText).isValid;
    else if (type === 'password') nextValid = processedText.length >= 6;
    else if (type === 'account') nextValid = ValidationFormatUtil.validateAccountNumber(processedText).isValid;
    else if (type === 'cccd') nextValid = ValidationFormatUtil.validateCccdOrId(processedText).isValid;

    onChangeValue(processedText, nextValid);
  };

  const getKeyboardType = () => {
    switch (type) {
      case 'phone':
        return 'phone-pad';
      case 'email':
        return 'email-address';
      case 'account':
      case 'cccd':
        return 'number-pad';
      default:
        return 'default';
    }
  };

  const hasError = touched && !isValid && !!validationError;

  return (
    <View style={styles.container} testID={testID}>
      <Text style={styles.label}>
        {label}
        {required && <Text style={styles.requiredAsterisk}> *</Text>}
      </Text>

      <View
        style={[
          styles.inputWrapper,
          isFocused && styles.inputWrapperFocused,
          hasError && styles.inputWrapperError,
        ]}
      >
        <TextInput
          testID={`${testID}-field`}
          style={[styles.input, webInputStyle]}
          value={value}
          onChangeText={handleChangeText}
          placeholder={placeholder}
          placeholderTextColor="#94A3B8"
          keyboardType={getKeyboardType()}
          autoCapitalize={type === 'email' ? 'none' : undefined}
          autoCorrect={false}
          secureTextEntry={type === 'password' ? !showPassword : false}
          onFocus={() => setIsFocused(true)}
          onBlur={() => {
            setIsFocused(false);
            setTouched(true);
          }}
          {...rest}
        />

        {type === 'password' && (
          <TouchableOpacity
            testID={`${testID}-toggle-visibility`}
            onPress={() => setShowPassword((prev) => !prev)}
            style={styles.toggleButton}
            hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
          >
            <Text style={styles.toggleText}>{showPassword ? 'HIDE' : 'SHOW'}</Text>
          </TouchableOpacity>
        )}

        {isValid && value.length > 0 && type !== 'password' && (
          <View testID={`${testID}-valid-badge`} style={styles.validCheckContainer}>
            <Text style={styles.validCheckText}>✓</Text>
          </View>
        )}
      </View>

      {hasError ? (
        <Text testID={`${testID}-error`} style={styles.errorText}>
          {validationError}
        </Text>
      ) : helperText ? (
        <Text style={styles.helperText}>{helperText}</Text>
      ) : null}
    </View>
  );
};

const webInputStyle: any = Platform.OS === 'web' ? { outlineWidth: 0, outlineStyle: 'none' } : {};

const styles = StyleSheet.create({
  container: {
    marginVertical: 6,
  },
  label: {
    fontSize: 14,
    fontWeight: '600',
    color: '#16181D',
    marginBottom: 6,
  },
  requiredAsterisk: {
    color: '#E7252B',
  },
  inputWrapper: {
    flexDirection: 'row',
    alignItems: 'center',
    borderWidth: 1.5,
    borderColor: '#E2E5EB',
    borderRadius: 10,
    backgroundColor: '#FFFFFF',
    paddingHorizontal: 14,
    height: 48,
  },
  inputWrapperFocused: {
    borderColor: '#E7252B',
  },
  inputWrapperError: {
    borderColor: '#E7252B',
    backgroundColor: '#FFF8F8',
  },
  input: {
    flex: 1,
    fontSize: 15,
    color: '#16181D',
    height: '100%',
    padding: 0,
  },
  toggleButton: {
    paddingLeft: 8,
  },
  toggleText: {
    fontSize: 12,
    fontWeight: '700',
    color: '#E7252B',
    letterSpacing: 0.5,
  },
  validCheckContainer: {
    width: 20,
    height: 20,
    borderRadius: 10,
    backgroundColor: '#16A34A',
    alignItems: 'center',
    justifyContent: 'center',
    marginLeft: 6,
  },
  validCheckText: {
    color: '#FFFFFF',
    fontSize: 12,
    fontWeight: '800',
  },
  errorText: {
    fontSize: 12,
    color: '#E7252B',
    marginTop: 4,
    fontWeight: '500',
  },
  helperText: {
    fontSize: 12,
    color: '#7B8494',
    marginTop: 4,
  },
});
