import React from 'react';
import { View, Text, TouchableOpacity, StyleSheet, ViewStyle } from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export interface SelectChipItem<T = string> {
  label: string;
  value: T;
  subtitle?: string;
  count?: number;
  disabled?: boolean;
}

export interface SelectChipGroupProps<T = string> {
  label?: string;
  items: SelectChipItem<T>[];
  selectedValue?: T | T[];
  onSelect: (value: T) => void;
  multiSelect?: boolean;
  style?: ViewStyle;
  testID?: string;
}

export function SelectChipGroup<T extends string | number>({
  label,
  items,
  selectedValue,
  onSelect,
  multiSelect = false,
  style,
  testID = 'select-chip-group',
}: SelectChipGroupProps<T>) {
  const { theme } = useTheme();

  const isSelected = (val: T) => {
    if (multiSelect && Array.isArray(selectedValue)) {
      return selectedValue.includes(val);
    }
    return selectedValue === val;
  };

  return (
    <View testID={testID} style={[styles.container, style]}>
      {label ? <Text style={styles.label}>{label}</Text> : null}
      <View style={styles.chipWrap}>
        {items.map((item) => {
          const selected = isSelected(item.value);
          return (
            <TouchableOpacity
              key={String(item.value)}
              testID={`${testID}-chip-${item.value}`}
              disabled={item.disabled}
              activeOpacity={0.7}
              onPress={() => onSelect(item.value)}
              style={[
                styles.chip,
                {
                  borderRadius: theme.radius.full,
                  borderColor: selected ? theme.colors.primary : theme.colors.border,
                  backgroundColor: selected ? theme.colors.primaryLight : theme.colors.card,
                },
                item.disabled && styles.disabledChip,
              ]}
            >
              <Text
                style={[
                  styles.chipText,
                  {
                    color: selected ? theme.colors.primary : theme.colors.text,
                    fontFamily: selected
                      ? theme.typography.fontFamilyBold
                      : theme.typography.fontFamily,
                  },
                ]}
              >
                {item.label}
              </Text>

              {item.count !== undefined ? (
                <View
                  style={[
                    styles.countBadge,
                    {
                      backgroundColor: selected ? theme.colors.primary : '#E5E7EB',
                    },
                  ]}
                >
                  <Text
                    style={[
                      styles.countText,
                      { color: selected ? '#FFFFFF' : '#4B5563' },
                    ]}
                  >
                    {item.count}
                  </Text>
                </View>
              ) : null}
            </TouchableOpacity>
          );
        })}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    marginVertical: 6,
  },
  label: {
    fontSize: 13,
    fontWeight: '600',
    color: '#333333',
    marginBottom: 8,
  },
  chipWrap: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 8,
  },
  chip: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 7,
    paddingHorizontal: 14,
    borderWidth: 1,
  },
  disabledChip: {
    opacity: 0.45,
  },
  chipText: {
    fontSize: 13,
  },
  countBadge: {
    marginLeft: 6,
    paddingHorizontal: 6,
    paddingVertical: 2,
    borderRadius: 10,
  },
  countText: {
    fontSize: 11,
    fontWeight: '700',
  },
});

