import React from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  StatusBar,
  ScrollView,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import {
  useTermsAndConditionsViewModel,
  UseTermsAndConditionsViewModelProps,
} from '../viewmodels/useTermsAndConditionsViewModel';
import { LaunchColors, LaunchTypography, FontFamilies } from '../theme/tokens';
import { LaunchFooter } from './components/LaunchFooter';
import { useBackNavigation } from '@mfe/ui-components/hooks/useBackNavigation';
import { useI18n } from '@mfe/core/i18n';
import { AppButton } from '@mfe/ui-components/components';

export interface TermsAndConditionsScreenProps {
  viewModelProps?: UseTermsAndConditionsViewModelProps;
}

export const TermsAndConditionsScreen: React.FC<TermsAndConditionsScreenProps> = ({
  viewModelProps,
}) => {
  const { t, isKhmer } = useI18n();
  const {
    termsText,
    hasAgreed,
    isLoading,
    errorMessage,
    toggleAgreement,
    handleAgree,
    handleCancel,
    handleSkip,
  } = useTermsAndConditionsViewModel(viewModelProps);

  const { panHandlers } = useBackNavigation({
    onBack: handleCancel,
    enabled: !isLoading,
  });

  return (
    <SafeAreaView
      testID="terms-screen"
      style={styles.container}
      edges={['top', 'left', 'right', 'bottom']}
      {...panHandlers}
    >
      <StatusBar barStyle="dark-content" backgroundColor={LaunchColors.white} />

      {/* Screen Header */}
      <View style={styles.header}>
        <TouchableOpacity
          testID="terms-back-button"
          onPress={handleCancel}
          style={styles.backButton}
          activeOpacity={0.7}
        >
          <Text style={styles.backChevron}>‹</Text>
        </TouchableOpacity>
        <Text
          testID="terms-header-title"
          style={[styles.headerTitle, isKhmer && styles.headerTitleKhmer]}
        >
          {t.launch.terms.title}
        </Text>
        <View style={styles.headerSpacer} />
      </View>

      {/* Main Content Area */}
      <ScrollView
        testID="terms-scroll-view"
        style={styles.scrollView}
        contentContainerStyle={styles.scrollContent}
        showsVerticalScrollIndicator={false}
      >
        <Text
          testID="terms-section-title"
          style={[styles.sectionTitle, isKhmer && styles.sectionTitleKhmer]}
        >
          {t.launch.terms.sectionIntro}
        </Text>

        <Text
          testID="terms-body-text"
          style={[styles.termsParagraph, isKhmer && styles.termsParagraphKhmer]}
        >
          {termsText || t.launch.terms.termsContent}
        </Text>

        {errorMessage && (
          <Text testID="terms-error-message" style={styles.errorText}>
            {errorMessage}
          </Text>
        )}
      </ScrollView>

      {/* Checkbox agreement positioned at bottom, outside terms-footer */}
      <View style={styles.agreementSection}>
        <TouchableOpacity
          testID="terms-agree-checkbox"
          style={styles.checkboxRow}
          onPress={toggleAgreement}
          activeOpacity={0.8}
        >
          <View
            style={[
              styles.checkboxBox,
              hasAgreed && styles.checkboxBoxChecked,
            ]}
          >
            {hasAgreed && <Text style={styles.checkmark}>✓</Text>}
          </View>
          <Text
            testID="terms-agree-label"
            style={[styles.agreeLabel, isKhmer && styles.agreeLabelKhmer]}
          >
            {t.launch.terms.agreeCheckboxLabel}
          </Text>
        </TouchableOpacity>
      </View>

      {/* Footer matching Figma with single 'I agree' button */}
      <View testID="terms-footer" style={styles.footerContainer}>
        <AppButton
          testID="terms-footer-confirm-button"
          title={isLoading ? t.common.processing : t.launch.terms.agreeButton}
          onPress={handleAgree}
          disabled={!hasAgreed || isLoading}
          isLoading={isLoading}
          variant="primary"
          size="lg"
          textStyle={isKhmer ? styles.agreeButtonTextKhmer : undefined}
        />
      </View>
    </SafeAreaView>
  );
};

