import { useEffect } from 'react';
import { Linking, Platform } from 'react-native';
import {
  NotificationRoutingService,
  PushNotificationPayload,
  NavigationService,
  navigationRef,
} from '@mfe/core/services';
import { appLogger } from '@mfe/core/logger/AppLogger';
import { AppEventBus } from '@mfe/core/services/AppEventBus';

export interface UseNotificationDeepLinkingOptions {
  /**
   * Optional custom handler if consumer wants to inspect or intercept
   */
  onNotificationTapped?: (payload: PushNotificationPayload) => void;
}

/**
 * Hook to manage notification click events and deep link URLs:
 * 1. Cold Launch: Retrieves the URL that launched the app or initial notification payload.
 * 2. Background/Foreground: Listens to Linking events and AppEventBus push click triggers.
 * 3. Dispatches navigation safely once NavigationContainer is mounted and ready.
 */
export function useNotificationDeepLinking(options: UseNotificationDeepLinkingOptions = {}) {
  useEffect(() => {
    let isMounted = true;

    // 1. Handle Cold Launch via standard Linking URL (e.g. losapp://approval/APR0001)
    const handleInitialUrl = async () => {
      try {
        const initialUrl = await Linking.getInitialURL();
        if (initialUrl && isMounted) {
          appLogger.info('useNotificationDeepLinking', 'Handling initial deep link URL on cold launch', { initialUrl });
          if (navigationRef.isReady()) {
            NotificationRoutingService.handleDeepLinkUrl(initialUrl);
          } else {
            NotificationRoutingService.setPendingNotification({ deeplink: initialUrl });
          }
        }
      } catch (err) {
        appLogger.error('useNotificationDeepLinking', 'Failed to get initial URL', err);
      }
    };

    handleInitialUrl();

    // 2. Handle Warm/Foreground deep link URL clicks
    const linkingSubscription = Linking.addEventListener('url', (event: { url: string }) => {
      if (!event.url) return;
      appLogger.info('useNotificationDeepLinking', 'App received deep link URL event', { url: event.url });
      NotificationRoutingService.handleDeepLinkUrl(event.url);
    });

    // 3. Handle Push Notification Click dispatched from Native/FCM or bizMOB push handler
    const unsubscribePushClick = AppEventBus.getInstance().subscribe(
      'notification:clicked',
      (payload: PushNotificationPayload) => {
        appLogger.info('useNotificationDeepLinking', 'Received notification:clicked event via AppEventBus', payload);
        if (options.onNotificationTapped) {
          options.onNotificationTapped(payload);
        }
        NotificationRoutingService.handleNotificationClick(payload);
      }
    );

    return () => {
      isMounted = false;
      linkingSubscription.remove();
      unsubscribePushClick();
    };
  }, [options]);
}
