/**
 * Sensitive Clipboard Protection Utility
 *
 * Temporarily copies sensitive banking data (OTP codes, Account numbers, CVV)
 * and schedules automatic clearing from the system clipboard to prevent leaks.
 */

export interface ClipboardAdapter {
  setString: (text: string) => void;
  getString: () => Promise<string>;
}

// Memory fallback adapter for test environments or headless platforms
let inMemoryClipboard = '';
const defaultClipboardAdapter: ClipboardAdapter = {
  setString: (text: string) => {
    inMemoryClipboard = text;
  },
  getString: async () => inMemoryClipboard,
};

let activeClearTimer: ReturnType<typeof setTimeout> | null = null;

/**
 * Copies text with automatic purge after `clearAfterMs` (default: 60 seconds).
 */
export function copySensitiveWithAutoClear(
  text: string,
  clearAfterMs: number = 60000,
  adapter: ClipboardAdapter = defaultClipboardAdapter
): { cancel: () => void } {
  if (activeClearTimer !== null) {
    clearTimeout(activeClearTimer);
    activeClearTimer = null;
  }

  adapter.setString(text);

  activeClearTimer = setTimeout(() => {
    adapter.setString('');
    activeClearTimer = null;
  }, clearAfterMs);

  return {
    cancel: () => {
      if (activeClearTimer !== null) {
        clearTimeout(activeClearTimer);
        activeClearTimer = null;
      }
    },
  };
}
