import React, { useState } from 'react';
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
  KeyboardTypeOptions,
  ScrollView,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { AppBottomSheet } from '../../modals/AppBottomSheet';
import { AppAlertModal } from '../../modals/AppAlertModal';

export interface DropdownTypeOption {
  label: string;
  value: string;
  category?: 'MAIN_ID' | 'ADDITIONAL_ID' | string;
  placeholder?: string;
  keyboardType?: KeyboardTypeOptions;
  helperText?: string;
  subtitle?: string;
}

export type PresentationMode = 'bottomsheet' | 'alert';

export interface TypeSelectableInputProps {
  /** Optional top field label */
  label?: string;
  /** Presentation mode: 'bottomsheet' (default) or 'alert' */
  presentationMode?: PresentationMode;
  /** Options list (e.g. CCCD, CMND, Passport, Additional ID) */
  options: DropdownTypeOption[];
  /** Selected option value */
  selectedType: string;
  /** Callback when option changes */
  onTypeChange: (typeValue: string) => void;
  /** Right text input value */
  inputValue: string;
  /** Right text input change callback */
  onInputChange: (text: string) => void;
  /** Right text input placeholder */
  placeholder?: string;
  /** Error message below input */
  error?: string;
  /** Required asterisk indicator */
  required?: boolean;
  /** Modal/BottomSheet title */
  selectorTitle?: string;
  /** Modal/BottomSheet subtitle */
  selectorSubtitle?: string;
  /** Whether the field is disabled or read-only */
  disabled?: boolean;
  /** Custom container style */
  style?: ViewStyle;
  /** Test ID */
  testID?: string;
}

export const TypeSelectableInput: React.FC<TypeSelectableInputProps> = ({
  label,
  presentationMode = 'bottomsheet',
  options,
  selectedType,
  onTypeChange,
  inputValue,
  onInputChange,
  placeholder,
  error,
  required = false,
  selectorTitle = 'Chọn loại giấy tờ tùy thân',
  selectorSubtitle,
  disabled = false,
  style,
  testID = 'type-selectable-input',
}) => {
  const { theme } = useTheme();
  const [selectorVisible, setSelectorVisible] = useState(false);

  const currentOption = options.find((opt) => opt.value === selectedType) || options[0];
  const activePlaceholder = placeholder || currentOption?.placeholder || 'Nhập số giấy tờ';
  const activeKeyboard = currentOption?.keyboardType || 'default';

  const handleSelectOption = (item: DropdownTypeOption) => {
    onTypeChange(item.value);
    setSelectorVisible(false);
  };

  const renderOptionsList = () => (
    <ScrollView style={styles.optionsList} showsVerticalScrollIndicator={false}>
      {options.map((item, index) => {
        const isSelected = item.value === selectedType;
        return (
          <TouchableOpacity
            key={`type-opt-${item.value}-${index}`}
            testID={`${testID}-option-${item.value}`}
            style={[
              styles.optionItem,
              isSelected && styles.optionItemSelected,
            ]}
            onPress={() => handleSelectOption(item)}
            activeOpacity={0.7}
          >
            <View style={styles.optionTextContainer}>
              <Text
                style={[
                  styles.optionLabel,
                  isSelected && styles.optionLabelSelected,
                ]}
              >
                {item.label}
              </Text>
              {item.subtitle ? (
                <Text style={styles.optionSubtitle}>{item.subtitle}</Text>
              ) : null}
            </View>
            {isSelected ? (
              <View style={styles.checkCircle}>
                <Text style={styles.checkIcon}>✓</Text>
              </View>
            ) : null}
          </TouchableOpacity>
        );
      })}
    </ScrollView>
  );

  return (
    <View testID={testID} style={[styles.container, style]}>
      {label ? (
        <Text testID={`${testID}-label`} style={styles.label}>
          {label} {required ? <Text style={{ color: '#E7252B' }}>*</Text> : null}
        </Text>
      ) : null}

      <View style={[styles.inputCompositeBox, error ? styles.inputBoxError : null, disabled && styles.inputDisabled]}>
        {/* Left Selectable Type Selector */}
        <TouchableOpacity
          testID={`${testID}-dropdown-trigger`}
          style={[styles.dropdownBtn, disabled && styles.dropdownDisabled]}
          onPress={() => !disabled && setSelectorVisible(true)}
          activeOpacity={0.7}
          disabled={disabled}
        >
          <Text style={styles.dropdownText} numberOfLines={1}>
            {currentOption?.label || selectedType}
          </Text>
          <Text style={styles.chevronIcon}>▾</Text>
        </TouchableOpacity>

        {/* Divider */}
        <View style={styles.divider} />

        {/* Right Free Text / Numeric Input */}
        <TextInput
          testID={`${testID}-text-input`}
          style={[styles.textInput, disabled && styles.textInputDisabled]}
          value={inputValue}
          onChangeText={onInputChange}
          placeholder={activePlaceholder}
          placeholderTextColor="#9CA3AF"
          keyboardType={activeKeyboard}
          autoCapitalize="none"
          editable={!disabled}
        />
      </View>

      {error ? (
        <Text testID={`${testID}-error-text`} style={styles.errorText}>
          {error}
        </Text>
      ) : currentOption?.helperText ? (
        <Text style={styles.helperText}>{currentOption.helperText}</Text>
      ) : null}

      {/* Presentation Mode: BottomSheet */}
      {presentationMode === 'bottomsheet' ? (
        <AppBottomSheet
          visible={selectorVisible}
          onClose={() => setSelectorVisible(false)}
          title={selectorTitle}
          testID={`${testID}-bottom-sheet`}
        >
          <View style={styles.sheetContent}>
            {selectorSubtitle ? (
              <Text style={styles.selectorSubtitle}>{selectorSubtitle}</Text>
            ) : null}
            {renderOptionsList()}
          </View>
        </AppBottomSheet>
      ) : (
        /* Presentation Mode: Alert Modal */
        <AppAlertModal
          visible={selectorVisible}
          onClose={() => setSelectorVisible(false)}
          title={selectorTitle}
          testID={`${testID}-alert-modal`}
        >
          <View style={styles.alertContent}>
            {selectorSubtitle ? (
              <Text style={styles.selectorSubtitle}>{selectorSubtitle}</Text>
            ) : null}
            {renderOptionsList()}
          </View>
        </AppAlertModal>
      )}
    </View>
  );
};

