import React from 'react';
import { View, StyleSheet, Alert } from 'react-native';
import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import { ThemeProvider } from '@mfe/theme';
import { I18nProvider } from '@mfe/core/i18n';
import { GlobalModalHost } from '@mfe/ui-components/modals';
import { DashboardScreen } from './views/DashboardScreen';
import { ApprovalDetailScreen } from './views/ApprovalDetailScreen';

const Stack = createNativeStackNavigator();

export const DashboardStandaloneApp: React.FC = () => {
  return (
    <SafeAreaProvider>
      <ThemeProvider>
        <I18nProvider initialLanguage="en">
          <View style={styles.container}>
            <NavigationContainer>
              <Stack.Navigator screenOptions={{ headerShown: false }}>
                <Stack.Screen name="DashboardMain">
                  {({ navigation }) => (
                    <DashboardScreen
                      onNavigateToShowcase={() =>
                        Alert.alert('Standalone Dev', 'Navigate to Showcase pressed.')
                      }
                      onNavigateToNotification={() =>
                        Alert.alert('Standalone Dev', 'Navigate to Notification pressed.')
                      }
                      onNavigateToApprovalDetail={(approvalId) =>
                        navigation.navigate('ApprovalDetail', { approvalId })
                      }
                      onLogout={() =>
                        Alert.alert('Standalone Dev', 'Logout pressed.')
                      }
                    />
                  )}
                </Stack.Screen>
                <Stack.Screen name="ApprovalDetail">
                  {({ navigation, route }: any) => (
                    <ApprovalDetailScreen
                      approvalId={route.params?.approvalId || ''}
                      onBack={() => navigation.goBack()}
                    />
                  )}
                </Stack.Screen>
              </Stack.Navigator>
            </NavigationContainer>
          </View>
          <GlobalModalHost />
        </I18nProvider>
      </ThemeProvider>
    </SafeAreaProvider>
  );
};

export default DashboardStandaloneApp;

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#FFFFFF',
    height: '100%',
    width: '100%',
  },
});
