import React from 'react';
import { View, Text, TouchableOpacity, StyleSheet, ScrollView } from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { ContactSupportUtil, HotlineContact, BankBranchOffice } from '@mfe/core/utils/contactSupportUtil';

export interface ContactSupportCardViewProps {
  hotlines?: HotlineContact[];
  headOffice?: BankBranchOffice;
  onCall?: (phoneNumber: string) => void;
  onEmail?: (email: string) => void;
  testID?: string;
}

/**
 * Dedicated Contact & Support Card view matching GL-18 / Support section in Lotte Digital Channels.
 * Provides domestic/international hotline cards, working hours, and physical head office address with GPS details.
 */
export const ContactSupportCardView: React.FC<ContactSupportCardViewProps> = ({
  hotlines = ContactSupportUtil.DEFAULT_HOTLINES,
  headOffice = ContactSupportUtil.HEAD_OFFICE,
  onCall,
  onEmail,
  testID = 'contact-support-card-view',
}) => {
  const { theme } = useTheme();

  const handleDial = (phoneNumber: string) => {
    if (onCall) {
      onCall(phoneNumber);
    } else {
      ContactSupportUtil.makePhoneCall(phoneNumber);
    }
  };

  const handleEmail = (email: string) => {
    if (onEmail) {
      onEmail(email);
    } else {
      ContactSupportUtil.sendSupportEmail(email);
    }
  };

  return (
    <View testID={testID} style={styles.container}>
      {/* Hotlines Section */}
      <Text style={styles.sectionHeader}>Customer Care Hotlines (Tổng đài hỗ trợ)</Text>
      <View style={styles.hotlinesGrid}>
        {hotlines.map((item, idx) => (
          <View
            key={`card-hotline-${idx}`}
            testID={`${testID}-hotline-card-${idx}`}
            style={[styles.hotlineCard, { borderColor: theme.colors.border || '#E5E7EB' }]}
          >
            <View style={styles.cardTopRow}>
              <View style={styles.iconBadge}>
                <Text style={styles.icon}>📞</Text>
              </View>
              <View style={styles.badge247}>
                <Text style={styles.badge247Text}>24/7 SUPPORT</Text>
              </View>
            </View>

            <Text style={styles.hotlineType}>{item.label}</Text>
            <Text
              testID={`${testID}-number-${idx}`}
              style={[styles.phoneNumberText, { color: theme.colors.primary || '#E7252B' }]}
            >
              {item.phoneNumber}
            </Text>
            <Text style={styles.operatingHoursText}>⏰ {item.operatingHours}</Text>

            <TouchableOpacity
              testID={`${testID}-dial-btn-${idx}`}
              onPress={() => handleDial(item.phoneNumber)}
              activeOpacity={0.8}
              style={[styles.callActionBtn, { backgroundColor: theme.colors.primary || '#E7252B' }]}
            >
              <Text style={styles.callActionBtnText}>Call Now ({item.phoneNumber})</Text>
            </TouchableOpacity>
          </View>
        ))}
      </View>

      {/* Head Office & Branch Directory Card */}
      <View style={[styles.headOfficeCard, { borderColor: theme.colors.border || '#E5E7EB' }]}>
        <View style={styles.officeHeaderRow}>
          <Text style={styles.officeIcon}>🏢</Text>
          <View style={styles.officeTitleWrapper}>
            <Text style={styles.officeName}>{headOffice.branchName}</Text>
            <Text style={styles.workingHoursBadge}>Working Hours: {headOffice.workingHours}</Text>
          </View>
        </View>

        <View style={styles.divider} />

        <Text style={styles.infoRowTitle}>📍 Office Address:</Text>
        <Text style={styles.infoRowBody}>{headOffice.address}</Text>

        <View style={styles.contactRow}>
          <TouchableOpacity
            testID={`${testID}-office-call`}
            onPress={() => handleDial(headOffice.phoneNumber)}
            style={styles.touchableInfo}
          >
            <Text style={styles.infoLinkText}>📞 {headOffice.phoneNumber}</Text>
          </TouchableOpacity>

          {headOffice.email && (
            <TouchableOpacity
              testID={`${testID}-office-email`}
              onPress={() => handleEmail(headOffice.email!)}
              style={styles.touchableInfo}
            >
              <Text style={styles.infoLinkText}>✉️ {headOffice.email}</Text>
            </TouchableOpacity>
          )}
        </View>
      </View>
    </View>
  );
};

