import React from 'react';
import { View, Text, TouchableOpacity, StyleSheet } from 'react-native';

export interface SegmentItem<T = string> {
  label: string;
  value: T;
}

export interface SegmentedControlProps<T = string> {
  items: SegmentItem<T>[];
  selectedValue: T;
  onSelect: (value: T) => void;
  variant?: 'light' | 'dark' | 'filled';
  containerStyle?: any;
  testID?: string;
}

export const SegmentedControl = <T extends string>({
  items,
  selectedValue,
  onSelect,
  variant = 'light',
  containerStyle,
  testID = 'segmented-control',
}: SegmentedControlProps<T>) => {
  const isFilled = variant === 'filled';

  return (
    <View
      testID={testID}
      style={[
        styles.container,
        isFilled && styles.filledContainer,
        containerStyle,
      ]}
    >
      {items.map((item, index) => {
        const isSelected = item.value === selectedValue;
        return (
          <TouchableOpacity
            key={`segment-${index}`}
            testID={`${testID}-item-${index}`}
            style={[
              styles.segment,
              isSelected ? (isFilled ? styles.filledSegmentSelected : styles.segmentSelected) : null,
            ]}
            onPress={() => onSelect(item.value)}
            activeOpacity={0.8}
          >
            <Text
              style={[
                styles.segmentText,
                isFilled && styles.filledSegmentText,
                isSelected ? (isFilled ? styles.filledSegmentTextSelected : styles.segmentTextSelected) : null,
              ]}
            >
              {item.label}
            </Text>
          </TouchableOpacity>
        );
      })}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flexDirection: 'row',
    backgroundColor: '#F4F5F7',
    borderRadius: 8,
    padding: 3,
    marginVertical: 8,
  },
  filledContainer: {
    backgroundColor: '#FFFFFF',
    borderRadius: 10,
    borderWidth: 1,
    borderColor: '#E5E7EB',
    padding: 4,
    marginVertical: 0,
  },
  segment: {
    flex: 1,
    paddingVertical: 10,
    borderRadius: 8,
    justifyContent: 'center',
    alignItems: 'center',
  },
  segmentSelected: {
    backgroundColor: '#FFFFFF',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 1 },
    shadowOpacity: 0.1,
    shadowRadius: 2,
    elevation: 2,
  },
  filledSegmentSelected: {
    backgroundColor: '#2C213F',
  },
  segmentText: {
    fontSize: 13,
    fontWeight: '600',
    color: '#4B5563',
  },
  filledSegmentText: {
    color: '#4B5563',
  },
  segmentTextSelected: {
    fontWeight: '700',
    color: '#16181D',
  },
  filledSegmentTextSelected: {
    color: '#FFFFFF',
    fontWeight: '700',
  },
});

