import { useState, useEffect, useCallback } from 'react';
import {
  NotificationItem,
  NotificationCategory,
} from '../models/NotificationModel';
import {
  INotificationService,
  NotificationService,
  MOCK_NOTIFICATIONS,
} from '../services/NotificationService';

export interface UseNotificationViewModelProps {
  notificationService?: INotificationService;
  useMock?: boolean;
  initialNotification?: NotificationItem;
  notificationId?: string;
}

export function useNotificationViewModel({
  notificationService = NotificationService.getInstance(),
  useMock = true,
  initialNotification,
  notificationId,
}: UseNotificationViewModelProps = {}) {
  const [activeTab, setActiveTab] = useState<NotificationCategory>('all');
  const [items, setItems] = useState<NotificationItem[]>(MOCK_NOTIFICATIONS);
  const [selectedNotification, setSelectedNotification] = useState<NotificationItem | null>(
    initialNotification || null
  );
  const [isRefreshing, setIsRefreshing] = useState<boolean>(false);

  const loadNotifications = useCallback(async () => {
    setIsRefreshing(true);
    try {
      const list = await notificationService.getNotificationList(undefined, useMock);
      setItems(list);
    } finally {
      setIsRefreshing(false);
    }
  }, [notificationService, useMock]);

  const loadNotificationDetail = useCallback(
    async (id: string) => {
      setIsRefreshing(true);
      try {
        const detail = await notificationService.getNotificationDetail(id, useMock);
        if (detail) {
          setSelectedNotification(detail);
        }
      } finally {
        setIsRefreshing(false);
      }
    },
    [notificationService, useMock]
  );

  useEffect(() => {
    if (notificationId) {
      loadNotificationDetail(notificationId);
    } else if (initialNotification?.id) {
      loadNotificationDetail(initialNotification.id);
    } else {
      loadNotifications();
    }
  }, [notificationId, initialNotification?.id, loadNotificationDetail, loadNotifications]);

  const filterByCategory = useCallback(
    (category: NotificationCategory) => {
      if (category === 'all') return items;
      return items.filter((item) => item.category === category);
    },
    [items]
  );

  return {
    activeTab,
    setActiveTab,
    items,
    selectedNotification,
    setSelectedNotification,
    isRefreshing,
    handleRefresh: loadNotifications,
    loadNotificationDetail,
    filterByCategory,
  };
}
