import React from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  ViewStyle,
  Platform,
} from 'react-native';
import Svg, { Path } from 'react-native-svg';

export type DocumentCardStatus = 'completed' | 'warning' | 'empty' | 'add';

export interface DocumentUploadItem {
  id: string;
  code?: string; // e.g. DOC100, DOC101
  name: string; // e.g. CMND/CCCD, Household registration
  status: DocumentCardStatus;
  fileCount?: number;
  onPress?: () => void;
}

export interface DocumentUploadSection {
  id: string;
  title: string; // e.g. Legal documents (required), Income documents
  required?: boolean;
  items: DocumentUploadItem[];
}

export interface DocumentUploadGridProps {
  /**
   * Title displayed at the top screen header (e.g. "Upload documents")
   */
  title?: string;
  /**
   * Back button callback
   */
  onBackPress?: () => void;
  /**
   * List of sections containing document items
   */
  sections?: DocumentUploadSection[];
  /**
   * Flat list of items if no sections are used
   */
  items?: DocumentUploadItem[];
  /**
   * Callback when a document card is tapped
   */
  onItemPress?: (item: DocumentUploadItem) => void;
  /**
   * Callback when add other document button is tapped
   */
  onAddPress?: () => void;
  /**
   * Custom container style
   */
  style?: ViewStyle;
  /**
   * Accessibility test ID
   */
  testID?: string;
}

/**
 * Status Icons for Document Cards
 */
const DocumentStatusIcon: React.FC<{ status: DocumentCardStatus; testID?: string }> = ({
  status,
  testID = 'doc-status',
}) => {
  switch (status) {
    case 'completed':
      // Red circular badge with white checkmark
      return (
        <View style={styles.completedBadge} testID={`${testID}-completed`}>
          <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
            <Path
              d="M5 13L9 17L19 7"
              stroke="#FFFFFF"
              strokeWidth={3}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </Svg>
        </View>
      );

    case 'warning':
      // Orange/amber circular badge with alert exclamation triangle
      return (
        <View style={styles.warningBadge} testID={`${testID}-warning`}>
          <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
            <Path
              d="M12 8V12M12 16H12.01"
              stroke="#FFFFFF"
              strokeWidth={2.8}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </Svg>
        </View>
      );

    case 'empty':
      // Soft grey circular background with upload arrow icon
      return (
        <View style={styles.emptyBadge} testID={`${testID}-empty`}>
          <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
            <Path
              d="M4 17V19C4 19.5304 4.21071 20.0391 4.58579 20.4142C4.96086 20.7893 5.46957 21 6 21H18C18.5304 21 19.0391 20.7893 19.4142 20.4142C19.7893 20.0391 20 19.5304 20 19V17"
              stroke="#94A3B8"
              strokeWidth={2.2}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
            <Path
              d="M7 9L12 4M12 4L17 9M12 4V15"
              stroke="#94A3B8"
              strokeWidth={2.2}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </Svg>
        </View>
      );

    case 'add':
      // Soft grey circular background with plus icon
      return (
        <View style={styles.emptyBadge} testID={`${testID}-add`}>
          <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
            <Path
              d="M12 5V19M5 12H19"
              stroke="#94A3B8"
              strokeWidth={2.5}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </Svg>
        </View>
      );
  }
};

/**
 * Individual Document Card Component
 */
export const DocumentCard: React.FC<{
  item: DocumentUploadItem;
  onPress?: () => void;
  testID?: string;
}> = ({ item, onPress, testID = 'doc-card' }) => {
  const isCompleted = item.status === 'completed';
  const isWarning = item.status === 'warning';

  return (
    <TouchableOpacity
      testID={`${testID}-${item.id}`}
      style={[
        styles.card,
        isCompleted && styles.completedCard,
        isWarning && styles.warningCard,
      ]}
      onPress={onPress || item.onPress}
      activeOpacity={0.7}
    >
      <View style={styles.iconWrapper}>
        <DocumentStatusIcon
          status={item.status}
          testID={`${testID}-${item.id}-status`}
        />
      </View>

      <View style={styles.cardContent}>
        {item.code ? (
          <Text
            style={[
              styles.cardCode,
              isCompleted && styles.completedText,
              isWarning && styles.warningText,
            ]}
            numberOfLines={1}
          >
            {item.code} •
          </Text>
        ) : null}
        <Text
          style={[
            styles.cardName,
            isCompleted && styles.completedText,
            isWarning && styles.warningText,
          ]}
          numberOfLines={2}
          testID={`${testID}-${item.id}-name`}
        >
          {item.name}
        </Text>
      </View>
    </TouchableOpacity>
  );
};

/**
 * DocumentUploadGrid (DL_SL_10) Component
 *
 * Renders document upload screen or section matching design DL_SL_10:
 * - Back button with screen title ("Upload documents")
 * - Document category headers (e.g. Legal documents, Income documents)
 * - 3-column responsive grid with rounded cards
 * - Distinct state styling:
 *   - Completed: Light pinkish-red card with red check icon badge
 *   - Warning: Soft amber card with orange warning badge
 *   - Empty: Clean white card with soft grey upload icon
 *   - Add/Others: White card with plus icon
 */
export const DocumentUploadGrid: React.FC<DocumentUploadGridProps> = ({
  title,
  onBackPress,
  sections,
  items,
  onItemPress,
  onAddPress,
  style,
  testID = 'doc-upload-grid',
}) => {
  // Normalize content: if items provided without sections, create single default section
  const resolvedSections: DocumentUploadSection[] = sections
    ? sections
    : items
    ? [{ id: 'default', title: '', items }]
    : [];

  return (
    <View style={[styles.container, style]} testID={testID}>
      {/* Header if title or onBackPress provided */}
      {title || onBackPress ? (
        <View style={styles.header} testID={`${testID}-header`}>
          {onBackPress ? (
            <TouchableOpacity
              testID={`${testID}-back-btn`}
              style={styles.backButton}
              onPress={onBackPress}
              activeOpacity={0.7}
            >
              <Svg width={24} height={24} viewBox="0 0 24 24" fill="none">
                <Path
                  d="M19 12H5M5 12L12 19M5 12L12 5"
                  stroke="#1E293B"
                  strokeWidth={2}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </Svg>
            </TouchableOpacity>
          ) : null}
          {title ? (
            <Text style={styles.headerTitle} testID={`${testID}-title`}>
              {title}
            </Text>
          ) : null}
        </View>
      ) : null}

      {/* Sections and Grids */}
      {resolvedSections.map((section, sIndex) => (
        <View
          key={section.id || `section-${sIndex}`}
          style={styles.sectionContainer}
          testID={`${testID}-section-${section.id}`}
        >
          {section.title ? (
            <View style={styles.sectionTitleRow}>
              <Text style={styles.sectionTitle}>
                {section.title}
                {section.required ? (
                  <Text style={styles.requiredMark}> (required)</Text>
                ) : null}
              </Text>
            </View>
          ) : null}

          <View style={styles.gridRow}>
            {section.items.map((item) => (
              <View key={item.id} style={styles.gridColumn}>
                <DocumentCard
                  item={item}
                  onPress={() => {
                    if (item.status === 'add' && onAddPress) {
                      onAddPress();
                    } else if (onItemPress) {
                      onItemPress(item);
                    }
                  }}
                  testID={`${testID}-card`}
                />
              </View>
            ))}
          </View>
        </View>
      ))}
    </View>
  );
};

