import React from 'react';
import { View, Text, TouchableOpacity, StyleSheet, ViewStyle } from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export interface ActionCardProps {
  title: string;
  description?: string;
  icon?: string | React.ReactNode;
  badge?: string;
  badgeVariant?: 'primary' | 'success' | 'warning';
  ctaText?: string;
  onPress: () => void;
  style?: ViewStyle;
  testID?: string;
}

export const ActionCard: React.FC<ActionCardProps> = ({
  title,
  description,
  icon,
  badge,
  badgeVariant = 'primary',
  ctaText = 'Apply Now',
  onPress,
  style,
  testID = 'action-card',
}) => {
  const { theme } = useTheme();

  const getBadgeColors = () => {
    switch (badgeVariant) {
      case 'success':
        return { bg: theme.colors.successBg, text: theme.colors.success };
      case 'warning':
        return { bg: theme.colors.warningBg, text: theme.colors.warning };
      default:
        return { bg: theme.colors.primaryLight, text: theme.colors.primary };
    }
  };

  const badgeColors = getBadgeColors();

  return (
    <TouchableOpacity
      testID={testID}
      activeOpacity={0.85}
      onPress={onPress}
      style={[
        styles.card,
        {
          borderColor: theme.colors.border,
          borderRadius: theme.radius.lg,
          backgroundColor: theme.colors.card,
        },
        style,
      ]}
    >
      <View style={styles.topRow}>
        <View style={styles.leftHeader}>
          {icon ? (
            <View
              style={[
                styles.iconWrap,
                { backgroundColor: theme.colors.primaryLight, borderRadius: theme.radius.md },
              ]}
            >
              {typeof icon === 'string' ? (
                <Text style={styles.iconEmoji}>{icon}</Text>
              ) : (
                icon
              )}
            </View>
          ) : null}

          <View style={styles.titleWrap}>
            <Text
              testID={`${testID}-title`}
              style={[
                styles.title,
                { color: theme.colors.text, fontFamily: theme.typography.fontFamilyBold },
              ]}
            >
              {title}
            </Text>
            {description ? (
              <Text testID={`${testID}-desc`} style={styles.description}>
                {description}
              </Text>
            ) : null}
          </View>
        </View>

        {badge ? (
          <View style={[styles.badge, { backgroundColor: badgeColors.bg }]}>
            <Text style={[styles.badgeText, { color: badgeColors.text }]}>
              {badge}
            </Text>
          </View>
        ) : null}
      </View>

      <View style={styles.footerRow}>
        <Text style={[styles.ctaText, { color: theme.colors.primary }]}>
          {ctaText} ➔
        </Text>
      </View>
    </TouchableOpacity>
  );
};

const styles = StyleSheet.create({
  card: {
    borderWidth: 1,
    padding: 16,
    marginVertical: 6,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.05,
    shadowRadius: 6,
    elevation: 2,
  },
  topRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
  },
  leftHeader: {
    flexDirection: 'row',
    alignItems: 'center',
    flex: 1,
  },
  iconWrap: {
    width: 44,
    height: 44,
    justifyContent: 'center',
    alignItems: 'center',
    marginRight: 12,
  },
  iconEmoji: {
    fontSize: 20,
  },
  titleWrap: {
    flex: 1,
  },
  title: {
    fontSize: 15,
    fontWeight: '700',
  },
  description: {
    fontSize: 12,
    color: '#6B7280',
    marginTop: 2,
    lineHeight: 16,
  },
  badge: {
    paddingHorizontal: 8,
    paddingVertical: 3,
    borderRadius: 4,
    marginLeft: 8,
  },
  badgeText: {
    fontSize: 11,
    fontWeight: '700',
  },
  footerRow: {
    flexDirection: 'row',
    justifyContent: 'flex-end',
    alignItems: 'center',
    marginTop: 12,
    paddingTop: 10,
    borderTopWidth: 1,
    borderTopColor: '#F3F4F6',
  },
  ctaText: {
    fontSize: 13,
    fontWeight: '700',
  },
});

