import React, { useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
  StyleProp,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { AppBottomSheet, AppAlertModal } from '../../modals';
import { WheelPicker } from './WheelPicker';

export interface MonthYearPickerProps {
  label?: string;
  selectedYear: number;
  selectedMonth: number; // 1 - 12
  onSelect: (year: number, month: number) => void;
  minYear?: number;
  maxYear?: number;
  wrapperType?: 'bottomsheet' | 'alert';
  disabled?: boolean;
  style?: StyleProp<ViewStyle>;
  testID?: string;
}

const MONTH_NAMES = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
];

/**
 * Month & Year dual column spinner picker matching DBCS LOS bm-month-year-picker.vue.
 * Features dual spinning wheel columns with looping snap scrolling and bottom sheet wrapper.
 */
export const MonthYearPickerField: React.FC<MonthYearPickerProps> = ({
  label,
  selectedYear,
  selectedMonth,
  onSelect,
  minYear = 2020,
  maxYear = 2030,
  wrapperType = 'bottomsheet',
  disabled = false,
  style,
  testID = 'month-year-picker',
}) => {
  const { theme } = useTheme();
  const [modalVisible, setModalVisible] = useState(false);
  const [tempYear, setTempYear] = useState(selectedYear);
  const [tempMonth, setTempMonth] = useState(selectedMonth);

  const formattedValue = `${MONTH_NAMES[selectedMonth - 1]} ${selectedYear}`;

  const yearItems = Array.from(
    { length: maxYear - minYear + 1 },
    (_, i) => {
      const yr = minYear + i;
      return { key: yr, value: yr, label: `${yr}` };
    }
  );

  const monthItems = MONTH_NAMES.map((m, idx) => ({
    key: idx + 1,
    value: idx + 1,
    label: `${String(idx + 1).padStart(2, '0')} - ${m.slice(0, 3)}`,
  }));

  const handleOpen = () => {
    if (disabled) return;
    setTempYear(selectedYear);
    setTempMonth(selectedMonth);
    setModalVisible(true);
  };

  const handleConfirm = () => {
    onSelect(tempYear, tempMonth);
    setModalVisible(false);
  };

  const pickerBody = (
    <View style={styles.modalBody}>
      {/* Dual Column Wheel Spinner */}
      <View style={styles.wheelColumnsRow}>
        {/* Month Spinner Column */}
        <View style={styles.wheelColumn}>
          <Text style={styles.columnLabel}>Month</Text>
          <WheelPicker
            items={monthItems}
            selectedValue={tempMonth}
            onValueChange={(it) => setTempMonth(Number(it.value))}
            testID={`${testID}-month-wheel`}
          />
        </View>

        {/* Year Spinner Column */}
        <View style={styles.wheelColumn}>
          <Text style={styles.columnLabel}>Year</Text>
          <WheelPicker
            items={yearItems}
            selectedValue={tempYear}
            onValueChange={(it) => setTempYear(Number(it.value))}
            testID={`${testID}-year-wheel`}
          />
        </View>
      </View>

      {/* Action Buttons */}
      <View style={styles.actionsRow}>
        <TouchableOpacity
          style={styles.cancelBtn}
          onPress={() => setModalVisible(false)}
        >
          <Text style={styles.cancelText}>Cancel</Text>
        </TouchableOpacity>
        <TouchableOpacity
          testID={`${testID}-confirm-btn`}
          style={[styles.confirmBtn, { backgroundColor: theme.colors.primary }]}
          onPress={handleConfirm}
        >
          <Text style={styles.confirmText}>Confirm</Text>
        </TouchableOpacity>
      </View>
    </View>
  );

  return (
    <View testID={testID} style={[styles.container, style]}>
      {label ? <Text style={styles.label}>{label}</Text> : null}

      <TouchableOpacity
        testID={`${testID}-trigger`}
        disabled={disabled}
        onPress={handleOpen}
        activeOpacity={0.7}
        style={[
          styles.inputBox,
          {
            borderColor: '#D1D5DB',
            backgroundColor: disabled ? '#F3F4F6' : '#FFFFFF',
          },
        ]}
      >
        <Text style={styles.valueText}>{formattedValue}</Text>
        <Text style={styles.calendarIcon}>🗓️</Text>
      </TouchableOpacity>

      {wrapperType === 'bottomsheet' ? (
        <AppBottomSheet
          visible={modalVisible}
          onClose={() => setModalVisible(false)}
          title="Period Selection"
        >
          {pickerBody}
        </AppBottomSheet>
      ) : (
        <AppAlertModal
          visible={modalVisible}
          onClose={() => setModalVisible(false)}
          title="Period Selection"
        >
          {pickerBody}
        </AppAlertModal>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    width: '100%',
  },
  label: {
    fontSize: 14,
    fontWeight: '600',
    color: '#374151',
    marginBottom: 6,
  },
  inputBox: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    height: 48,
    borderRadius: 8,
    borderWidth: 1,
    paddingHorizontal: 14,
  },
  valueText: {
    fontSize: 14,
    color: '#1F2937',
    fontWeight: '600',
  },
  calendarIcon: {
    fontSize: 18,
  },
  modalBody: {
    paddingVertical: 8,
  },
  wheelColumnsRow: {
    flexDirection: 'row',
    gap: 16,
    paddingVertical: 12,
  },
  wheelColumn: {
    flex: 1,
    alignItems: 'center',
  },
  columnLabel: {
    fontSize: 13,
    fontWeight: '700',
    color: '#4B5563',
    marginBottom: 10,
  },
  actionsRow: {
    flexDirection: 'row',
    justifyContent: 'flex-end',
    gap: 12,
    marginTop: 18,
  },
  cancelBtn: {
    paddingHorizontal: 16,
    paddingVertical: 10,
    borderRadius: 8,
  },
  cancelText: {
    fontSize: 14,
    fontWeight: '600',
    color: '#6B7280',
  },
  confirmBtn: {
    paddingHorizontal: 20,
    paddingVertical: 10,
    borderRadius: 8,
  },
  confirmText: {
    fontSize: 14,
    fontWeight: '700',
    color: '#FFFFFF',
  },
});

