import React, { useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
  ScrollView,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { AppBottomSheet } from '../../modals/AppBottomSheet';

export interface SelectOption<T = string> {
  label: string;
  value: T;
  subtitle?: string;
  badge?: string;
  disabled?: boolean;
}

export interface BottomSheetSelectFieldProps<T = string> {
  label?: string;
  options: SelectOption<T>[];
  selectedValue?: T;
  onSelect: (value: T) => void;
  placeholder?: string;
  title?: string;
  subtitle?: string;
  error?: string;
  style?: ViewStyle;
  testID?: string;
  renderCustomTrigger?: (selectedOption?: SelectOption<T>, onOpen?: () => void) => React.ReactNode;
}

export function BottomSheetSelectField<T extends string | number>({
  label,
  options,
  selectedValue,
  onSelect,
  placeholder = 'Select an option',
  title,
  subtitle,
  error,
  style,
  testID = 'bottom-sheet-select',
  renderCustomTrigger,
}: BottomSheetSelectFieldProps<T>) {
  const { theme } = useTheme();
  const [visible, setVisible] = useState(false);

  const selectedOption = options.find((o) => o.value === selectedValue);

  const handleSelect = (val: T) => {
    onSelect(val);
    setVisible(false);
  };

  return (
    <View testID={testID} style={[styles.container, style]}>
      {label ? <Text style={styles.label}>{label}</Text> : null}

      {/* Trigger Box or Custom Trigger */}
      {renderCustomTrigger ? (
        renderCustomTrigger(selectedOption, () => setVisible(true))
      ) : (
        <TouchableOpacity
          testID={`${testID}-trigger`}
          activeOpacity={0.7}
          onPress={() => setVisible(true)}
          style={[
            styles.triggerBox,
            {
              borderColor: error ? theme.colors.error : theme.colors.border,
              borderRadius: theme.radius.md,
              backgroundColor: theme.colors.card,
            },
          ]}
        >
          <Text
            testID={`${testID}-display-value`}
            style={[
              styles.valueText,
              !selectedOption && styles.placeholderText,
              { color: selectedOption ? theme.colors.text : '#9CA3AF' },
            ]}
            numberOfLines={1}
          >
            {selectedOption ? selectedOption.label : placeholder}
          </Text>

          <Text style={styles.chevron}>▾</Text>
        </TouchableOpacity>
      )}

      {error ? <Text style={styles.errorText}>{error}</Text> : null}

      {/* Options in AppBottomSheet */}
      <AppBottomSheet
        visible={visible}
        title={title || label || 'Select Option'}
        onClose={() => setVisible(false)}
        testID={`${testID}-modal`}
      >
        {subtitle ? (
          <Text style={styles.sheetSubtitle}>{subtitle}</Text>
        ) : null}
        <ScrollView style={styles.optionList} nestedScrollEnabled>
          {options.map((opt) => {
            const isSelected = opt.value === selectedValue;
            return (
              <TouchableOpacity
                key={String(opt.value)}
                testID={`${testID}-opt-${opt.value}`}
                disabled={opt.disabled}
                activeOpacity={0.7}
                onPress={() => handleSelect(opt.value)}
                style={[
                  styles.optionRow,
                  opt.disabled && styles.disabledOption,
                ]}
              >
                {/* Radio selection indicator */}
                <View
                  style={[
                    styles.radioCircle,
                    isSelected && { borderColor: '#2563EB' },
                  ]}
                >
                  {isSelected && <View style={styles.radioInner} />}
                </View>

                <View style={styles.optionContent}>
                  <Text
                    style={[
                      styles.optionLabel,
                      isSelected && {
                        color: '#0F172A',
                        fontWeight: '600',
                      },
                    ]}
                  >
                    {opt.label}
                  </Text>
                  {opt.subtitle ? (
                    <Text style={styles.optionSubtitle}>{opt.subtitle}</Text>
                  ) : null}
                </View>
              </TouchableOpacity>
            );
          })}
        </ScrollView>
      </AppBottomSheet>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    marginVertical: 6,
  },
  label: {
    fontSize: 13,
    fontWeight: '600',
    color: '#333333',
    marginBottom: 6,
  },
  triggerBox: {
    height: 48,
    borderWidth: 1,
    paddingHorizontal: 14,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  valueText: {
    fontSize: 14,
    fontWeight: '500',
    flex: 1,
  },
  placeholderText: {
    fontWeight: '400',
  },
  chevron: {
    fontSize: 14,
    color: '#6B7280',
    marginLeft: 8,
  },
  errorText: {
    fontSize: 12,
    color: '#E7252B',
    marginTop: 4,
  },
  optionList: {
    maxHeight: 360,
    marginVertical: 6,
  },
  optionRow: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 12,
    paddingHorizontal: 4,
    gap: 12,
    borderBottomWidth: 1,
    borderBottomColor: '#F3F4F6',
  },
  radioCircle: {
    width: 22,
    height: 22,
    borderRadius: 11,
    borderWidth: 2,
    borderColor: '#94A3B8',
    alignItems: 'center',
    justifyContent: 'center',
  },
  radioInner: {
    width: 12,
    height: 12,
    borderRadius: 6,
    backgroundColor: '#2563EB',
  },
  sheetSubtitle: {
    fontSize: 13,
    color: '#64748B',
    marginBottom: 12,
    paddingHorizontal: 4,
  },
  disabledOption: {
    opacity: 0.4,
  },
  optionContent: {
    flex: 1,
  },
  optionLabel: {
    fontSize: 15,
    color: '#111827',
  },
  optionSubtitle: {
    fontSize: 12,
    color: '#6B7280',
    marginTop: 2,
  },
  checkmark: {
    fontSize: 16,
    fontWeight: '700',
    marginLeft: 12,
  },
});

