import { useState, useCallback } from 'react';
import { IAuthService, AuthService } from '../services/AuthService';

export interface UseBiometricViewModelProps {
  authService?: IAuthService;
  userId?: string;
  onSetupSuccess?: () => void;
  onSkip?: () => void;
  onBack?: () => void;
}

export const useBiometricViewModel = ({
  authService = new AuthService(),
  userId = 'default-user',
  onSetupSuccess,
  onSkip,
  onBack,
}: UseBiometricViewModelProps = {}) => {
  const [isLoading, setIsLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const enableBiometric = useCallback(async () => {
    setIsLoading(true);
    setErrorMessage(null);
    try {
      const res = await authService.registerBiometric(userId, true);
      if (res.success) {
        if (onSetupSuccess) {
          onSetupSuccess();
        }
      } else {
        setErrorMessage(res.errorMessage || 'Failed to enable biometric authentication.');
      }
    } catch (err: any) {
      setErrorMessage(err?.message || 'Biometric registration failed.');
    } finally {
      setIsLoading(false);
    }
  }, [authService, userId, onSetupSuccess]);

  const handleSkip = useCallback(() => {
    if (onSkip) {
      onSkip();
    }
  }, [onSkip]);

  return {
    isLoading,
    errorMessage,
    enableBiometric,
    handleSkip,
    onBack,
  };
};
