import React from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export interface BottomTabItem {
  key: string;
  label?: string;
  icon?: (color: string, focused: boolean) => React.ReactNode;
  badgeCount?: number;
  customButton?: React.ReactNode;
}

export interface BottomNavigationBarProps {
  tabs: BottomTabItem[];
  activeTab: string;
  onTabPress: (tabKey: string) => void;
  style?: ViewStyle;
  testID?: string;
  safeAreaBottom?: number;
}

export const BottomNavigationBar: React.FC<BottomNavigationBarProps> = ({
  tabs,
  activeTab,
  onTabPress,
  style,
  testID = 'bottom-navigation-bar',
  safeAreaBottom = 0,
}) => {
  const { theme } = useTheme();

  return (
    <View
      testID={testID}
      style={[
        styles.barContainer,
        {
          backgroundColor: theme?.colors?.card || '#FFFFFF',
          borderTopColor: theme?.colors?.border || '#E5E7EB',
          paddingBottom: Math.max(safeAreaBottom, 6),
          height: 64 + Math.max(safeAreaBottom, 6),
        },
        style,
      ]}
    >
      {tabs.map((tab) => {
        if (tab.customButton) {
          return (
            <React.Fragment key={tab.key}>
              {tab.customButton}
            </React.Fragment>
          );
        }

        const isFocused = tab.key === activeTab;
        const activeColor = '#2C213F';
        const inactiveColor = '#94A3B8';
        const iconColor = isFocused ? activeColor : inactiveColor;

        return (
          <TouchableOpacity
            key={tab.key}
            testID={`${testID}-tab-${tab.key}`}
            activeOpacity={0.75}
            onPress={() => onTabPress(tab.key)}
            style={styles.tabButton}
          >
            <View style={styles.iconWrap}>
              {tab.icon ? tab.icon(iconColor, isFocused) : null}

              {tab.badgeCount !== undefined && tab.badgeCount > 0 ? (
                <View
                  style={[
                    styles.badge,
                    { backgroundColor: theme?.colors?.primary || '#E7252B' },
                  ]}
                >
                  <Text style={styles.badgeText}>
                    {tab.badgeCount > 99 ? '99+' : tab.badgeCount}
                  </Text>
                </View>
              ) : null}
            </View>

            {tab.label ? (
              <Text
                style={[
                  styles.tabLabel,
                  {
                    color: isFocused ? activeColor : '#64748B',
                    fontWeight: isFocused ? '700' : '500',
                  },
                ]}
                numberOfLines={1}
              >
                {tab.label}
              </Text>
            ) : null}
          </TouchableOpacity>
        );
      })}
    </View>
  );
};

const styles = StyleSheet.create({
  barContainer: {
    flexDirection: 'row',
    height: 64,
    borderTopWidth: 1,
    alignItems: 'center',
    justifyContent: 'space-around',
    paddingHorizontal: 8,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: -2 },
    shadowOpacity: 0.05,
    shadowRadius: 6,
    elevation: 8,
  },
  tabButton: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    paddingVertical: 4,
  },
  iconWrap: {
    position: 'relative',
    height: 28,
    alignItems: 'center',
    justifyContent: 'center',
  },
  badge: {
    position: 'absolute',
    top: -4,
    right: -10,
    minWidth: 16,
    height: 16,
    borderRadius: 8,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: 4,
  },
  badgeText: {
    color: '#FFFFFF',
    fontSize: 9,
    fontWeight: '700',
  },
  tabLabel: {
    fontSize: 11,
    marginTop: 2,
  },
});

