import React from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  ViewStyle,
  Platform,
} from 'react-native';
import Svg, { Circle, Path } from 'react-native-svg';
import { LoanAmountTermSlider } from './LoanAmountTermSlider';

export interface LoanFittingSelectionViewProps {
  /**
   * Title text (default: "Choose a loan that fits you")
   */
  title?: string;
  /**
   * Description text
   */
  description?: string;
  /**
   * Back button callback
   */
  onBackPress?: () => void;
  /**
   * Loan amount in millions
   */
  amount: number;
  onAmountChange: (amount: number) => void;
  minAmount?: number; // default: 10
  maxAmount?: number; // default: 100
  amountStep?: number; // default: 1
  amountUnit?: string; // default: "million VND"
  /**
   * Loan term in months
   */
  term: number;
  onTermChange: (term: number) => void;
  minTerm?: number; // default: 6
  maxTerm?: number; // default: 36
  termStep?: number; // default: 1
  termUnit?: string; // default: "months"
  /**
   * Monthly estimated repayment string (e.g. "2.954.000 ₫")
   */
  estimatedMonthlyRepayment?: string;
  /**
   * Continue button callback
   */
  onContinue?: () => void;
  /**
   * Custom style for container
   */
  style?: ViewStyle;
  /**
   * Accessibility test ID
   */
  testID?: string;
}

/**
 * Info Icon for Estimate
 */
const InfoCircleIcon: React.FC = () => (
  <Svg width={16} height={16} viewBox="0 0 24 24" fill="none" style={styles.estimateIcon}>
    <Circle cx="12" cy="12" r="10" stroke="#64748B" strokeWidth={2} />
    <Path d="M12 16V12M12 8H12.01" stroke="#64748B" strokeWidth={2.2} strokeLinecap="round" />
  </Svg>
);

/**
 * LoanFittingSelectionView
 *
 * Full screen / view matching the uploaded image:
 * - Back button top navigation
 * - Header: "Choose a loan that fits you"
 * - Subtitle: "You can adjust the loan amount and term to suit your needs"
 * - Loan amount slider with interactive box & min/max bounds
 * - Loan term slider with interactive box & min/max bounds
 * - Loan estimate card with formatted monthly repayment (e.g. "2.954.000 ₫")
 * - Continue button
 */
export const LoanFittingSelectionView: React.FC<LoanFittingSelectionViewProps> = ({
  title = 'Choose a loan that fits you',
  description = 'You can adjust the loan amount and term to suit your needs',
  onBackPress,
  amount,
  onAmountChange,
  minAmount = 10,
  maxAmount = 100,
  amountStep = 1,
  amountUnit = 'million VND',
  term,
  onTermChange,
  minTerm = 6,
  maxTerm = 36,
  termStep = 1,
  termUnit = 'months',
  estimatedMonthlyRepayment = '2.954.000 ₫',
  onContinue,
  style,
  testID = 'loan-fitting-view',
}) => {
  return (
    <View style={[styles.container, style]} testID={testID}>
      {/* Top Header / Back Arrow */}
      {onBackPress ? (
        <View style={styles.headerRow}>
          <TouchableOpacity
            testID={`${testID}-back-btn`}
            onPress={onBackPress}
            style={styles.backButton}
            activeOpacity={0.7}
          >
            <Svg width={24} height={24} viewBox="0 0 24 24" fill="none">
              <Path
                d="M19 12H5M5 12L12 19M5 12L12 5"
                stroke="#0F172A"
                strokeWidth={2.2}
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </Svg>
          </TouchableOpacity>
        </View>
      ) : null}

      {/* Main Title & Description */}
      <Text style={styles.title} testID={`${testID}-title`}>
        {title}
      </Text>
      <Text style={styles.description} testID={`${testID}-description`}>
        {description}
      </Text>

      {/* 1. Loan Amount Slider */}
      <LoanAmountTermSlider
        label="Loan amount"
        value={amount}
        min={minAmount}
        max={maxAmount}
        step={amountStep}
        unit={amountUnit}
        onChange={onAmountChange}
        testID={`${testID}-amount-slider`}
      />

      <View style={{ height: 16 }} />

      {/* 2. Loan Term Slider */}
      <LoanAmountTermSlider
        label="Loan term"
        value={term}
        min={minTerm}
        max={maxTerm}
        step={termStep}
        unit={termUnit}
        onChange={onTermChange}
        testID={`${testID}-term-slider`}
      />

      {/* 3. Loan Estimate Card */}
      <View style={styles.estimateSection}>
        <Text style={styles.estimateHeader}>Loan estimate</Text>
        <View style={styles.estimateCard} testID={`${testID}-estimate-card`}>
          <View style={styles.estimateTitleRow}>
            <InfoCircleIcon />
            <Text style={styles.estimateLabel}>Estimated monthly repayment</Text>
          </View>
          <Text style={styles.estimateAmount} testID={`${testID}-estimate-amount`}>
            {estimatedMonthlyRepayment}
          </Text>
        </View>
      </View>

      {/* 4. Continue Button */}
      {onContinue ? (
        <TouchableOpacity
          testID={`${testID}-continue-btn`}
          style={styles.continueButton}
          onPress={onContinue}
          activeOpacity={0.8}
        >
          <Text style={styles.continueText}>Continue</Text>
        </TouchableOpacity>
      ) : null}
    </View>
  );
};

