import { useEffect, useRef, useState, useCallback, RefObject } from 'react';
import { Keyboard, Platform, ScrollView, TextInput, Dimensions } from 'react-native';

export interface UseAutoScrollOptions {
  /** Reference to the enclosing ScrollView */
  scrollViewRef: RefObject<ScrollView | null>;
  /** Extra breathing room (in dp) above the keyboard. Default: 36 */
  extraMargin?: number;
  /** Whether auto-scrolling is enabled. Default: true */
  enabled?: boolean;
}

/**
 * Reusable hook providing reliable auto-scroll of any currently focused TextInput
 * cleanly above the virtual soft keyboard on both iOS and Android.
 *
 * Implements the standard from docs/technical/issues/keyboard-and-input/auto-scroll-focused-input-above-keyboard.md
 */
export function useAutoScrollOnInputFocus({
  scrollViewRef,
  extraMargin = 48,
  enabled = true,
}: UseAutoScrollOptions) {
  const [keyboardHeight, setKeyboardHeight] = useState(0);
  const currentScrollY = useRef(0);

  const onScroll = useCallback((e: any) => {
    currentScrollY.current = e.nativeEvent?.contentOffset?.y ?? 0;
  }, []);

  const scrollToFocusedInput = useCallback((extraOffset = extraMargin) => {
    setTimeout(() => {
      const currentlyFocused = TextInput.State?.currentlyFocusedInput?.();
      if (currentlyFocused && typeof currentlyFocused.measureInWindow === 'function') {
        currentlyFocused.measureInWindow((_x, y, _width, height) => {
          const windowHeight = Dimensions.get('window').height;
          const kbHeight = keyboardHeight > 0 ? keyboardHeight : 280; // Default estimate if not emitted yet
          const keyboardTopY = windowHeight - kbHeight;
          const inputBottomY = y + height;

          if (inputBottomY > keyboardTopY - 24 || y < 60) {
            const overflow = inputBottomY - keyboardTopY + extraOffset;
            const targetY = currentScrollY.current + overflow;

            scrollViewRef.current?.scrollTo({
              y: Math.max(0, targetY),
              animated: true,
            });
          }
        });
      }
    }, 120);
  }, [extraMargin, keyboardHeight, scrollViewRef]);

  useEffect(() => {
    if (!enabled) return;

    const showEvent = Platform.OS === 'ios' ? 'keyboardWillShow' : 'keyboardDidShow';
    const hideEvent = Platform.OS === 'ios' ? 'keyboardWillHide' : 'keyboardDidHide';

    const onShow = Keyboard.addListener(showEvent, (e) => {
      const kbHeight = e.endCoordinates.height;
      setKeyboardHeight(kbHeight);

      setTimeout(() => {
        const currentlyFocused = TextInput.State?.currentlyFocusedInput?.();
        if (currentlyFocused && typeof currentlyFocused.measureInWindow === 'function') {
          currentlyFocused.measureInWindow((_x, y, _width, height) => {
            const keyboardTopY = e.endCoordinates.screenY;
            const inputBottomY = y + height;

            // Lift input so it sits comfortably above keyboard height
            if (inputBottomY > keyboardTopY - 24 || y < 60) {
              const overflow = inputBottomY - keyboardTopY + extraMargin;
              const targetY = currentScrollY.current + overflow;

              scrollViewRef.current?.scrollTo({
                y: Math.max(0, targetY),
                animated: true,
              });
            }
          });
        }
      }, 100);
    });

    const onHide = Keyboard.addListener(hideEvent, () => {
      setKeyboardHeight(0);
    });

    return () => {
      onShow.remove();
      onHide.remove();
    };
  }, [enabled, extraMargin, scrollViewRef]);

  return {
    keyboardHeight,
    onScroll,
    currentScrollY,
    scrollToFocusedInput,
  };
}

