import React from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  StyleProp,
  ViewStyle,
} from 'react-native';

export interface HistoryStatusCardProps {
  label: string;
  count: number | string;
  countColor: string;
  icon: React.ReactNode;
  iconBgColor?: string;
  onPress?: () => void;
  style?: StyleProp<ViewStyle>;
  testID?: string;
}

export const HistoryStatusCard: React.FC<HistoryStatusCardProps> = ({
  label,
  count,
  countColor,
  icon,
  iconBgColor = '#F3F4F6',
  onPress,
  style,
  testID = 'history-status-card',
}) => {
  const content = (
    <View style={[styles.card, style]} testID={testID}>
      <View style={[styles.iconBox, { backgroundColor: iconBgColor }]}>
        {icon}
      </View>
      <View style={styles.cardRight}>
        <Text style={styles.cardLabel}>{label}</Text>
        <Text style={[styles.cardNumber, { color: countColor }]}>{count}</Text>
      </View>
    </View>
  );

  if (onPress) {
    return (
      <TouchableOpacity
        style={styles.touchableWrapper}
        activeOpacity={0.85}
        onPress={onPress}
      >
        {content}
      </TouchableOpacity>
    );
  }

  return <View style={styles.touchableWrapper}>{content}</View>;
};

const styles = StyleSheet.create({
  touchableWrapper: {
    width: '48.5%',
    marginBottom: 10,
  },
  card: {
    backgroundColor: '#FFFFFF',
    borderRadius: 12,
    padding: 14,
    flexDirection: 'row',
    alignItems: 'center',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 1 },
    shadowOpacity: 0.04,
    shadowRadius: 4,
    elevation: 2,
  },
  iconBox: {
    width: 36,
    height: 36,
    borderRadius: 8,
    alignItems: 'center',
    justifyContent: 'center',
    marginRight: 10,
  },
  cardRight: {
    flex: 1,
    alignItems: 'flex-end',
  },
  cardLabel: {
    fontSize: 12,
    color: '#4B5563',
    fontWeight: '500',
  },
  cardNumber: {
    fontSize: 20,
    fontWeight: '800',
    marginTop: 2,
  },
});

