import React from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export interface HeaderAction {
  key: string;
  icon: (color: string) => React.ReactNode;
  onPress: () => void;
  badgeCount?: number;
  accessibilityLabel?: string;
}

export interface ActionHeaderProps {
  title: string;
  subtitle?: string;
  onBackPress?: () => void;
  leftAction?: HeaderAction;
  rightActions?: HeaderAction[];
  style?: ViewStyle;
  testID?: string;
}

export const ActionHeader: React.FC<ActionHeaderProps> = ({
  title,
  subtitle,
  onBackPress,
  leftAction,
  rightActions = [],
  style,
  testID = 'action-header',
}) => {
  const { theme } = useTheme();

  return (
    <View
      testID={testID}
      style={[
        styles.headerContainer,
        {
          backgroundColor: theme.colors.card,
          borderBottomColor: theme.colors.border,
        },
        style,
      ]}
    >
      {/* Left Area (Back button or custom action) */}
      <View style={styles.leftContainer}>
        {onBackPress ? (
          <TouchableOpacity
            testID={`${testID}-back`}
            style={styles.iconButton}
            onPress={onBackPress}
            activeOpacity={0.7}
          >
            <Text style={[styles.backArrow, { color: theme.colors.text }]}>
              ←
            </Text>
          </TouchableOpacity>
        ) : leftAction ? (
          <TouchableOpacity
            testID={`${testID}-left-${leftAction.key}`}
            style={styles.iconButton}
            onPress={leftAction.onPress}
            activeOpacity={0.7}
          >
            {leftAction.icon(theme.colors.text)}
          </TouchableOpacity>
        ) : null}
      </View>

      {/* Center Title & Subtitle */}
      <View style={styles.centerContainer}>
        <Text
          testID={`${testID}-title`}
          style={[
            styles.title,
            { color: theme.colors.text, fontFamily: theme.typography.fontFamilyBold },
          ]}
          numberOfLines={1}
        >
          {title}
        </Text>
        {subtitle ? (
          <Text style={styles.subtitle} numberOfLines={1}>
            {subtitle}
          </Text>
        ) : null}
      </View>

      {/* Right Area (Action Buttons) */}
      <View style={styles.rightContainer}>
        {rightActions.map((action) => (
          <TouchableOpacity
            key={action.key}
            testID={`${testID}-action-${action.key}`}
            style={styles.iconButton}
            onPress={action.onPress}
            activeOpacity={0.7}
          >
            <View style={styles.actionIconWrap}>
              {action.icon(theme.colors.text)}

              {action.badgeCount !== undefined && action.badgeCount > 0 ? (
                <View
                  style={[
                    styles.actionBadge,
                    { backgroundColor: theme.colors.primary },
                  ]}
                >
                  <Text style={styles.actionBadgeText}>
                    {action.badgeCount > 99 ? '99+' : action.badgeCount}
                  </Text>
                </View>
              ) : null}
            </View>
          </TouchableOpacity>
        ))}
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  headerContainer: {
    height: 56,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 12,
    borderBottomWidth: 1,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 1 },
    shadowOpacity: 0.04,
    shadowRadius: 3,
    elevation: 2,
  },
  leftContainer: {
    minWidth: 44,
    alignItems: 'flex-start',
    justifyContent: 'center',
  },
  centerContainer: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: 8,
  },
  rightContainer: {
    minWidth: 44,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'flex-end',
    gap: 4,
  },
  iconButton: {
    width: 40,
    height: 40,
    justifyContent: 'center',
    alignItems: 'center',
    borderRadius: 20,
  },
  backArrow: {
    fontSize: 22,
    fontWeight: '600',
  },
  title: {
    fontSize: 16,
    fontWeight: '700',
  },
  subtitle: {
    fontSize: 11,
    color: '#6B7280',
    marginTop: 1,
  },
  actionIconWrap: {
    position: 'relative',
    justifyContent: 'center',
    alignItems: 'center',
  },
  actionBadge: {
    position: 'absolute',
    top: -4,
    right: -6,
    minWidth: 14,
    height: 14,
    borderRadius: 7,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: 3,
  },
  actionBadgeText: {
    color: '#FFFFFF',
    fontSize: 8,
    fontWeight: '700',
  },
});

