import React, { useState } from 'react';
import {
  View,
  Image,
  ImageSourcePropType,
  StyleSheet,
  ActivityIndicator,
  Text,
  TouchableOpacity,
  ImageStyle,
  ViewStyle,
} from 'react-native';

export interface NetworkImageProps {
  uri: string;
  fallbackSource?: ImageSourcePropType;
  style?: ImageStyle;
  containerStyle?: ViewStyle;
  resizeMode?: 'cover' | 'contain' | 'stretch' | 'center';
  borderRadius?: number;
  showSkeleton?: boolean;
  altText?: string;
  onRetry?: () => void;
  testID?: string;
}

/**
 * Enterprise Network Image Component with resilient state handling:
 * - Skeleton / Loading indicator while fetching remote URL
 * - Smooth transition upon load success
 * - Informative fallback UI or placeholder upon HTTP/network error
 * - One-tap Retry handler for unstable mobile connections
 */
export const NetworkImage: React.FC<NetworkImageProps> = ({
  uri,
  fallbackSource,
  style,
  containerStyle,
  resizeMode = 'cover',
  borderRadius = 8,
  showSkeleton = true,
  altText = 'Image failed to load',
  onRetry,
  testID = 'network-image',
}) => {
  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);
  const [retryKey, setRetryKey] = useState(0);

  const handleRetry = () => {
    setIsLoading(true);
    setHasError(false);
    setRetryKey((prev) => prev + 1);
    onRetry?.();
  };

  const hasValidUri = !!uri && uri.trim().length > 0;

  return (
    <View
      style={[
        styles.container,
        { borderRadius },
        containerStyle,
        style ? { width: style.width, height: style.height } : undefined,
      ]}
      testID={testID}
    >
      {/* 1. Loading Skeleton Overlay */}
      {isLoading && showSkeleton && !hasError && (
        <View testID={`${testID}-skeleton`} style={[styles.skeletonOverlay, { borderRadius }]}>
          <ActivityIndicator size="small" color="#94A3B8" />
        </View>
      )}

      {/* 2. Error State */}
      {(hasError || !hasValidUri) ? (
        fallbackSource ? (
          <Image
            source={fallbackSource}
            style={[styles.image, style, { borderRadius }]}
            resizeMode={resizeMode}
            testID={`${testID}-fallback`}
          />
        ) : (
          <View testID={`${testID}-error`} style={[styles.errorContainer, { borderRadius }]}>
            <Text style={styles.errorIcon}>⚠️</Text>
            <Text style={styles.errorText} numberOfLines={2}>
              {altText}
            </Text>
            {hasValidUri && (
              <TouchableOpacity
                testID={`${testID}-retry-btn`}
                style={styles.retryButton}
                onPress={handleRetry}
                activeOpacity={0.7}
              >
                <Text style={styles.retryText}>Retry</Text>
              </TouchableOpacity>
            )}
          </View>
        )
      ) : (
        /* 3. Remote Network Image */
        <Image
          key={`net-img-${retryKey}`}
          source={{ uri }}
          style={[styles.image, style, { borderRadius }]}
          resizeMode={resizeMode}
          onLoadStart={() => setIsLoading(true)}
          onLoadEnd={() => setIsLoading(false)}
          onError={() => {
            setIsLoading(false);
            setHasError(true);
          }}
          testID={`${testID}-img`}
        />
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    overflow: 'hidden',
    backgroundColor: '#F1F5F9',
    position: 'relative',
    justifyContent: 'center',
    alignItems: 'center',
  },
  image: {
    width: '100%',
    height: '100%',
  },
  skeletonOverlay: {
    ...StyleSheet.absoluteFillObject,
    backgroundColor: '#E2E8F0',
    alignItems: 'center',
    justifyContent: 'center',
    zIndex: 2,
  },
  errorContainer: {
    ...StyleSheet.absoluteFillObject,
    backgroundColor: '#F8FAFC',
    borderWidth: 1,
    borderColor: '#E2E8F0',
    alignItems: 'center',
    justifyContent: 'center',
    padding: 10,
  },
  errorIcon: {
    fontSize: 20,
    marginBottom: 4,
  },
  errorText: {
    fontSize: 11,
    color: '#64748B',
    textAlign: 'center',
    marginBottom: 6,
  },
  retryButton: {
    paddingHorizontal: 10,
    paddingVertical: 3,
    backgroundColor: '#E2E8F0',
    borderRadius: 4,
  },
  retryText: {
    fontSize: 10,
    fontWeight: '700',
    color: '#334155',
  },
});

