/**
 * Contract Document Model & Validation Rules
 */

export interface ContractParty {
  name: string;
  address?: string;
  identifier?: string;
}

export interface ContractDetails {
  contractId: string;
  contractTitle: string;
  provider: ContractParty;
  client: ContractParty;
  termStartDate: string;
  termNoticeDays: number;
  serviceDescription: string;
  paymentAmount: number;
  currency: string;
  totalPages: number;
  base64PdfData?: string;
}

export interface ContractReviewState {
  currentPage: number;
  totalPages: number;
  hasReachedLastPage: boolean;
  hasAgreed: boolean;
  zoomScale: number;
  isLoading: boolean;
  errorMessage?: string;
}

export class ContractModel {
  /**
   * Validate whether a contract review is complete and ready for signature
   */
  public static canSign(state: ContractReviewState): boolean {
    return state.hasReachedLastPage && state.hasAgreed && !state.isLoading;
  }

  /**
   * Format page indicator like "01/10"
   */
  public static formatPageIndicator(currentPage: number, totalPages: number): string {
    const safeCurrent = Math.max(1, currentPage);
    const safeTotal = Math.max(1, totalPages);
    const currentStr = String(safeCurrent).padStart(2, '0');
    const totalStr = String(safeTotal).padStart(2, '0');
    return `${currentStr}/${totalStr}`;
  }
}
