import React, { useCallback, useEffect, useRef, useState } from 'react';
import {
  LayoutChangeEvent,
  NativeScrollEvent,
  NativeSyntheticEvent,
  ScrollView,
  StyleProp,
  StyleSheet,
  TouchableOpacity,
  useWindowDimensions,
  View,
  ViewStyle,
} from 'react-native';
import Svg, { Path } from 'react-native-svg';
import { useTheme, defaultTheme } from '@mfe/theme';

export interface CarouselProps<T = any> {
  data: T[];
  renderItem: (item: T, index: number, isActive: boolean) => React.ReactNode;
  keyExtractor?: (item: T, index: number) => string;
  autoPlay?: boolean;
  autoPlayInterval?: number;
  loop?: boolean;
  showDots?: boolean;
  showArrows?: boolean;
  initialIndex?: number;
  onIndexChange?: (index: number) => void;
  style?: StyleProp<ViewStyle>;
  slideStyle?: StyleProp<ViewStyle>;
  testID?: string;
}

export function Carousel<T = any>({
  data,
  renderItem,
  keyExtractor,
  autoPlay = false,
  autoPlayInterval = 3500,
  loop = true,
  showDots = true,
  showArrows = false,
  initialIndex = 0,
  onIndexChange,
  style,
  slideStyle,
  testID = 'carousel',
}: CarouselProps<T>) {
  const themeContext = useTheme();
  const theme = themeContext?.theme || defaultTheme;
  const { colors, radius, spacing } = theme;
  const { width: windowWidth } = useWindowDimensions();

  const clampedInitial =
    data.length > 0 ? Math.max(0, Math.min(initialIndex, data.length - 1)) : 0;

  const [activeIndex, setActiveIndex] = useState<number>(clampedInitial);
  const [containerWidth, setContainerWidth] = useState<number>(windowWidth);
  const isDraggingRef = useRef(false);
  const scrollViewRef = useRef<ScrollView | null>(null);

  const slideWidth = containerWidth > 0 ? containerWidth : windowWidth;

  const goToIndex = useCallback(
    (targetIndex: number, animated = true) => {
      if (data.length === 0) return;
      let next = targetIndex;
      if (loop) {
        next = ((targetIndex % data.length) + data.length) % data.length;
      } else {
        next = Math.max(0, Math.min(targetIndex, data.length - 1));
      }
      setActiveIndex(next);
      onIndexChange?.(next);
      scrollViewRef.current?.scrollTo({
        x: next * slideWidth,
        animated,
      });
    },
    [data.length, loop, slideWidth, onIndexChange]
  );

  // Auto-play timer
  useEffect(() => {
    if (!autoPlay || data.length <= 1) return;
    const timer = setInterval(() => {
      if (!isDraggingRef.current) {
        goToIndex(activeIndex + 1, true);
      }
    }, autoPlayInterval);

    return () => clearInterval(timer);
  }, [autoPlay, autoPlayInterval, activeIndex, data.length, goToIndex]);

  const handleLayout = (event: LayoutChangeEvent) => {
    const measured = event.nativeEvent.layout.width;
    if (measured > 0 && measured !== containerWidth) {
      setContainerWidth(measured);
      if (activeIndex > 0) {
        scrollViewRef.current?.scrollTo({
          x: activeIndex * measured,
          animated: false,
        });
      }
    }
  };

  const handleScrollEnd = (event: NativeSyntheticEvent<NativeScrollEvent>) => {
    isDraggingRef.current = false;
    if (slideWidth <= 0 || data.length === 0) return;
    const offsetX = event.nativeEvent.contentOffset.x;
    const nextIdx = Math.max(
      0,
      Math.min(Math.round(offsetX / slideWidth), data.length - 1)
    );
    if (nextIdx !== activeIndex) {
      setActiveIndex(nextIdx);
      onIndexChange?.(nextIdx);
    }
  };

  if (data.length === 0) {
    return null;
  }

  return (
    <View testID={testID} onLayout={handleLayout} style={[styles.container, style]}>
      <View style={styles.trackWrapper}>
        <ScrollView
          ref={scrollViewRef}
          testID={`${testID}-scroll`}
          horizontal
          pagingEnabled
          showsHorizontalScrollIndicator={false}
          bounces={false}
          scrollEventThrottle={16}
          onScrollBeginDrag={() => {
            isDraggingRef.current = true;
          }}
          onMomentumScrollEnd={handleScrollEnd}
        >
          {data.map((item, index) => (
            <View
              key={keyExtractor ? keyExtractor(item, index) : `slide-${index}`}
              testID={`${testID}-slide-${index}`}
              style={[{ width: slideWidth }, slideStyle]}
            >
              {renderItem(item, index, index === activeIndex)}
            </View>
          ))}
        </ScrollView>

        {showArrows && data.length > 1 ? (
          <>
            <TouchableOpacity
              testID={`${testID}-prev-btn`}
              accessibilityRole="button"
              accessibilityLabel="Previous slide"
              activeOpacity={0.8}
              onPress={() => goToIndex(activeIndex - 1)}
              style={[
                styles.arrowBtn,
                styles.arrowLeft,
                { backgroundColor: colors.card, borderRadius: radius.full },
              ]}
            >
              <Svg width={16} height={16} viewBox="0 0 24 24" fill="none">
                <Path
                  d="M15 19L8 12L15 5"
                  stroke={colors.text}
                  strokeWidth={2.4}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </Svg>
            </TouchableOpacity>
            <TouchableOpacity
              testID={`${testID}-next-btn`}
              accessibilityRole="button"
              accessibilityLabel="Next slide"
              activeOpacity={0.8}
              onPress={() => goToIndex(activeIndex + 1)}
              style={[
                styles.arrowBtn,
                styles.arrowRight,
                { backgroundColor: colors.card, borderRadius: radius.full },
              ]}
            >
              <Svg width={16} height={16} viewBox="0 0 24 24" fill="none">
                <Path
                  d="M9 5L16 12L9 19"
                  stroke={colors.text}
                  strokeWidth={2.4}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </Svg>
            </TouchableOpacity>
          </>
        ) : null}
      </View>

      {showDots && data.length > 1 ? (
        <View
          testID={`${testID}-dots`}
          style={[styles.dotsRow, { marginTop: spacing.md, gap: spacing.xs }]}
        >
          {data.map((item, index) => {
            const isActive = index === activeIndex;
            return (
              <TouchableOpacity
                key={keyExtractor ? `${keyExtractor(item, index)}-dot` : `dot-${index}`}
                testID={`${testID}-dot-${index}`}
                accessibilityRole="button"
                accessibilityState={{ selected: isActive }}
                onPress={() => goToIndex(index)}
                activeOpacity={0.8}
                style={[
                  styles.dot,
                  {
                    width: isActive ? 20 : 8,
                    borderRadius: radius.full,
                    backgroundColor: isActive ? colors.primary : colors.border,
                  },
                ]}
              />
            );
          })}
        </View>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    width: '100%',
  },
  trackWrapper: {
    position: 'relative',
    width: '100%',
  },
  arrowBtn: {
    position: 'absolute',
    top: '50%',
    marginTop: -18,
    width: 36,
    height: 36,
    alignItems: 'center',
    justifyContent: 'center',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.12,
    shadowRadius: 4,
    elevation: 3,
  },
  arrowLeft: {
    left: 10,
  },
  arrowRight: {
    right: 10,
  },
  dotsRow: {
    flexDirection: 'row',
    justifyContent: 'center',
    alignItems: 'center',
  },
  dot: {
    height: 8,
  },
});

export default Carousel;
