import React, { useEffect, useRef } from 'react';
import { Animated, Easing, Platform, StyleSheet, View } from 'react-native';
import { AppBadge, AppBadgeProps } from './AppBadge';

export type AnimatedBadgeType = 'pop' | 'pulse' | 'bounce' | 'shake' | 'none';

export interface AnimatedBadgeProps extends AppBadgeProps {
  /** Animation style: 'pop' (on mount/change), 'pulse' (continuous), 'bounce' (continuous), 'shake' (on change), 'none' */
  animation?: AnimatedBadgeType;
  /** Toggle visibility with smooth scale/fade transition */
  visible?: boolean;
  /** Duration in ms for pulse/bounce loop cycle (default 1200) */
  duration?: number;
}

export const AnimatedBadge: React.FC<AnimatedBadgeProps> = ({
  animation = 'pop',
  visible = true,
  duration = 1200,
  content,
  testID = 'animated-badge',
  ...badgeProps
}) => {
  const scaleAnim = useRef(new Animated.Value(visible ? 1 : 0)).current;
  const opacityAnim = useRef(new Animated.Value(visible ? 1 : 0)).current;
  const translateYAnim = useRef(new Animated.Value(0)).current;
  const translateXAnim = useRef(new Animated.Value(0)).current;

  const useNative = Platform.OS !== 'web';

  // Visibility enter / exit transition
  useEffect(() => {
    Animated.parallel([
      Animated.spring(scaleAnim, {
        toValue: visible ? 1 : 0,
        tension: 180,
        friction: 12,
        useNativeDriver: useNative,
      }),
      Animated.timing(opacityAnim, {
        toValue: visible ? 1 : 0,
        duration: 180,
        useNativeDriver: useNative,
      }),
    ]).start();
  }, [visible, scaleAnim, opacityAnim, useNative]);

  // Content change pop / shake animation
  useEffect(() => {
    if (!visible || animation === 'none') return;

    if (animation === 'pop') {
      scaleAnim.setValue(0.75);
      Animated.spring(scaleAnim, {
        toValue: 1,
        tension: 220,
        friction: 8,
        useNativeDriver: useNative,
      }).start();
    } else if (animation === 'shake') {
      Animated.sequence([
        Animated.timing(translateXAnim, { toValue: -4, duration: 50, useNativeDriver: useNative }),
        Animated.timing(translateXAnim, { toValue: 4, duration: 50, useNativeDriver: useNative }),
        Animated.timing(translateXAnim, { toValue: -3, duration: 50, useNativeDriver: useNative }),
        Animated.timing(translateXAnim, { toValue: 3, duration: 50, useNativeDriver: useNative }),
        Animated.timing(translateXAnim, { toValue: 0, duration: 50, useNativeDriver: useNative }),
      ]).start();
    }
  }, [content, animation, visible, scaleAnim, translateXAnim, useNative]);

  // Continuous loop animations (pulse / bounce)
  useEffect(() => {
    if (!visible) return;
    let loop: Animated.CompositeAnimation | null = null;

    if (animation === 'pulse') {
      loop = Animated.loop(
        Animated.sequence([
          Animated.timing(scaleAnim, {
            toValue: 1.12,
            duration: duration / 2,
            easing: Easing.inOut(Easing.ease),
            useNativeDriver: useNative,
          }),
          Animated.timing(scaleAnim, {
            toValue: 1,
            duration: duration / 2,
            easing: Easing.inOut(Easing.ease),
            useNativeDriver: useNative,
          }),
        ])
      );
      loop.start();
    } else if (animation === 'bounce') {
      loop = Animated.loop(
        Animated.sequence([
          Animated.timing(translateYAnim, {
            toValue: -4,
            duration: duration / 2,
            easing: Easing.out(Easing.quad),
            useNativeDriver: useNative,
          }),
          Animated.timing(translateYAnim, {
            toValue: 0,
            duration: duration / 2,
            easing: Easing.in(Easing.quad),
            useNativeDriver: useNative,
          }),
        ])
      );
      loop.start();
    }

    return () => {
      loop?.stop();
      translateYAnim.setValue(0);
    };
  }, [animation, visible, duration, scaleAnim, translateYAnim, useNative]);

  return (
    <View testID={`${testID}-wrapper`} style={styles.wrapper}>
      <Animated.View
        testID={testID}
        style={{
          opacity: opacityAnim,
          transform: [
            { scale: scaleAnim },
            { translateX: translateXAnim },
            { translateY: translateYAnim },
          ],
        }}
      >
        <AppBadge
          {...badgeProps}
          content={content}
          testID={`${testID}-inner`}
        />
      </Animated.View>
    </View>
  );
};

const styles = StyleSheet.create({
  wrapper: {
    alignSelf: 'flex-start',
  },
});

export default AnimatedBadge;
