import React from 'react';
import { View, Text, StyleSheet, ViewStyle } from 'react-native';

export type BannerVariant = 'info' | 'success' | 'warning' | 'error';

export interface FeedbackBannerProps {
  message: string;
  variant?: BannerVariant;
  style?: ViewStyle;
  testID?: string;
}

export const FeedbackBanner: React.FC<FeedbackBannerProps> = ({
  message,
  variant = 'info',
  style,
  testID = 'feedback-banner',
}) => {
  return (
    <View style={[styles.banner, styles[variant], style]} testID={testID}>
      <Text style={[styles.text, styles[`text_${variant}`]]} testID={`${testID}-message`}>
        {message}
      </Text>
    </View>
  );
};

const styles = StyleSheet.create({
  banner: {
    padding: 12,
    borderRadius: 8,
    marginVertical: 8,
    borderWidth: 1,
  },
  info: {
    backgroundColor: '#F0F9FF',
    borderColor: '#B9E6FE',
  },
  success: {
    backgroundColor: '#ECFDF3',
    borderColor: '#A6F4C5',
  },
  warning: {
    backgroundColor: '#FFFAEB',
    borderColor: '#FEDF89',
  },
  error: {
    backgroundColor: '#FEF3F2',
    borderColor: '#FECDCA',
  },
  text: {
    fontSize: 14,
    lineHeight: 20,
    fontWeight: '500',
  },
  text_info: {
    color: '#026AA2',
  },
  text_success: {
    color: '#027A48',
  },
  text_warning: {
    color: '#B54708',
  },
  text_error: {
    color: '#B42318',
  },
});

