import React from 'react';
import { View, Text, TouchableOpacity, StyleSheet } from 'react-native';

export interface DocumentUploadBoxProps {
  label: string;
  description?: string;
  uploadedFileName?: string | null;
  onUpload: () => void;
  onRemove?: () => void;
  testID?: string;
}

export const DocumentUploadBox: React.FC<DocumentUploadBoxProps> = ({
  label,
  description,
  uploadedFileName,
  onUpload,
  onRemove,
  testID = 'doc-upload-box',
}) => {
  const isUploaded = !!uploadedFileName;

  return (
    <View testID={testID} style={styles.container}>
      <Text style={styles.label}>{label}</Text>
      {description ? <Text style={styles.description}>{description}</Text> : null}

      {!isUploaded ? (
        <TouchableOpacity
          testID={`${testID}-upload-trigger`}
          style={styles.uploadArea}
          onPress={onUpload}
          activeOpacity={0.7}
        >
          <Text style={styles.uploadIcon}>📷</Text>
          <Text style={styles.uploadText}>Tap to Capture or Upload Document</Text>
          <Text style={styles.hintText}>Supports JPG, PNG, PDF (Max 10MB)</Text>
        </TouchableOpacity>
      ) : (
        <View testID={`${testID}-uploaded-card`} style={styles.fileCard}>
          <View style={styles.fileInfo}>
            <Text style={styles.fileIcon}>📄</Text>
            <View style={styles.fileNameWrapper}>
              <Text numberOfLines={1} style={styles.fileName}>
                {uploadedFileName}
              </Text>
              <Text style={styles.fileStatus}>✓ Upload Completed</Text>
            </View>
          </View>
          {onRemove ? (
            <TouchableOpacity
              testID={`${testID}-remove-btn`}
              onPress={onRemove}
              activeOpacity={0.7}
              style={styles.removeBtn}
            >
              <Text style={styles.removeText}>Remove</Text>
            </TouchableOpacity>
          ) : null}
        </View>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    marginVertical: 8,
  },
  label: {
    fontSize: 14,
    fontWeight: '700',
    color: '#16181D',
    marginBottom: 4,
  },
  description: {
    fontSize: 12,
    color: '#7B8494',
    marginBottom: 8,
  },
  uploadArea: {
    borderWidth: 1.5,
    borderColor: '#3B82F6',
    borderStyle: 'dashed',
    borderRadius: 10,
    backgroundColor: '#EFF6FF',
    paddingVertical: 20,
    paddingHorizontal: 16,
    alignItems: 'center',
    justifyContent: 'center',
  },
  uploadIcon: {
    fontSize: 28,
    marginBottom: 6,
  },
  uploadText: {
    fontSize: 14,
    fontWeight: '600',
    color: '#1F5FA8',
  },
  hintText: {
    fontSize: 11,
    color: '#7B8494',
    marginTop: 4,
  },
  fileCard: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    backgroundColor: '#F8FAFC',
    borderWidth: 1,
    borderColor: '#E2E5EB',
    borderRadius: 8,
    padding: 12,
  },
  fileInfo: {
    flexDirection: 'row',
    alignItems: 'center',
    flex: 1,
    marginRight: 8,
  },
  fileIcon: {
    fontSize: 22,
    marginRight: 10,
  },
  fileNameWrapper: {
    flex: 1,
  },
  fileName: {
    fontSize: 13,
    fontWeight: '600',
    color: '#16181D',
  },
  fileStatus: {
    fontSize: 11,
    color: '#117A4D',
    fontWeight: '600',
    marginTop: 2,
  },
  removeBtn: {
    paddingHorizontal: 8,
    paddingVertical: 4,
  },
  removeText: {
    fontSize: 12,
    color: '#E7252B',
    fontWeight: '600',
  },
});

