import { useState, useRef, useCallback } from 'react';
import type { NativePdfRef } from '@mfe/ui-components/components';
import {
  ContractDetails,
  ContractReviewState,
  ContractModel,
} from '../models/ContractModel';
import {
  SERVICE_CONTRACT_PDF_BASE64,
  SERVICE_CONTRACT_TOTAL_PAGES,
} from '@mfe/assets/mock/serviceContractPdf';

export interface UseContractViewerViewModelProps {
  initialContract?: Partial<ContractDetails>;
  onBack?: () => void;
  onSignComplete?: (contractId: string) => void;
}

export const useContractViewerViewModel = (props?: UseContractViewerViewModelProps) => {
  const pdfRef = useRef<NativePdfRef>(null);

  const contract: ContractDetails = {
    contractId: props?.initialContract?.contractId || 'CTR-2026-00918',
    contractTitle: props?.initialContract?.contractTitle || 'SERVICE CONTRACT',
    provider: props?.initialContract?.provider || {
      name: 'ACME Financial Services LLC',
      address: 'Phnom Penh Tower, Monivong Blvd, Phnom Penh',
    },
    client: props?.initialContract?.client || {
      name: 'Sokha Chan',
      identifier: 'CIF-884920',
      address: 'St. 2004, Sangkat Teuk Thla, Phnom Penh',
    },
    termStartDate: props?.initialContract?.termStartDate || '15/11/2026',
    termNoticeDays: props?.initialContract?.termNoticeDays ?? 30,
    serviceDescription:
      props?.initialContract?.serviceDescription ||
      'Digital Loan Origination & Underwriting Services Agreement',
    paymentAmount: props?.initialContract?.paymentAmount ?? 5000,
    currency: props?.initialContract?.currency || 'USD',
    totalPages: props?.initialContract?.totalPages ?? SERVICE_CONTRACT_TOTAL_PAGES,
    base64PdfData: props?.initialContract?.base64PdfData || SERVICE_CONTRACT_PDF_BASE64,
  };

  const [reviewState, setReviewState] = useState<ContractReviewState>({
    currentPage: 1,
    totalPages: contract.totalPages,
    hasReachedLastPage: false,
    hasAgreed: false,
    zoomScale: 1.0,
    isLoading: false,
    errorMessage: undefined,
  });

  const handlePageChanged = useCallback((currentPage: number, totalPages?: number) => {
    setReviewState((prev) => {
      const safeTotal = totalPages || prev.totalPages;
      const isLast = currentPage >= safeTotal;
      return {
        ...prev,
        currentPage,
        totalPages: safeTotal,
        hasReachedLastPage: prev.hasReachedLastPage || isLast,
      };
    });
  }, []);

  const handleLastPage = useCallback(() => {
    setReviewState((prev) => ({
      ...prev,
      currentPage: prev.totalPages,
      hasReachedLastPage: true,
    }));
  }, []);

  const handleFirstPage = useCallback(() => {
    setReviewState((prev) => ({
      ...prev,
      currentPage: 1,
    }));
  }, []);

  const toggleAgreement = useCallback(() => {
    setReviewState((prev) => ({
      ...prev,
      hasAgreed: !prev.hasAgreed,
    }));
  }, []);

  const goToNextPage = useCallback(() => {
    pdfRef.current?.goToNextPage();
    setReviewState((prev) => {
      const next = Math.min(prev.totalPages, prev.currentPage + 1);
      return {
        ...prev,
        currentPage: next,
        hasReachedLastPage: prev.hasReachedLastPage || next >= prev.totalPages,
      };
    });
  }, []);

  const goToPreviousPage = useCallback(() => {
    pdfRef.current?.goToPreviousPage();
    setReviewState((prev) => ({
      ...prev,
      currentPage: Math.max(1, prev.currentPage - 1),
    }));
  }, []);

  const zoomIn = useCallback(() => {
    setReviewState((prev) => {
      const nextZoom = Math.min(3.0, prev.zoomScale + 0.25);
      pdfRef.current?.setZoom(nextZoom);
      return { ...prev, zoomScale: nextZoom };
    });
  }, []);

  const zoomOut = useCallback(() => {
    setReviewState((prev) => {
      const nextZoom = Math.max(0.5, prev.zoomScale - 0.25);
      pdfRef.current?.setZoom(nextZoom);
      return { ...prev, zoomScale: nextZoom };
    });
  }, []);

  const resetZoom = useCallback(() => {
    pdfRef.current?.resetZoom();
    setReviewState((prev) => ({ ...prev, zoomScale: 1.0 }));
  }, []);

  const handleBack = useCallback(() => {
    props?.onBack?.();
  }, [props]);

  const handleSign = useCallback(() => {
    if (!ContractModel.canSign(reviewState)) return;
    props?.onSignComplete?.(contract.contractId);
  }, [reviewState, contract.contractId, props]);

  return {
    pdfRef,
    contract,
    reviewState,
    formattedPageIndicator: ContractModel.formatPageIndicator(
      reviewState.currentPage,
      reviewState.totalPages
    ),
    canSign: ContractModel.canSign(reviewState),
    handlePageChanged,
    handleLastPage,
    handleFirstPage,
    toggleAgreement,
    goToNextPage,
    goToPreviousPage,
    zoomIn,
    zoomOut,
    resetZoom,
    handleBack,
    handleSign,
  };
};
