import React from 'react';
import {
  TouchableOpacity,
  View,
  Text,
  StyleSheet,
  ViewStyle,
  StyleProp,
} from 'react-native';

export type CheckboxVariant = 'primary' | 'brand' | 'success';

export interface CheckboxProps {
  label?: string;
  checked: boolean;
  onToggle: (checked: boolean) => void;
  disabled?: boolean;
  variant?: CheckboxVariant;
  size?: 'small' | 'medium' | 'large';
  subtitle?: string;
  style?: StyleProp<ViewStyle>;
  testID?: string;
}

export const Checkbox: React.FC<CheckboxProps> = ({
  label,
  checked,
  onToggle,
  disabled = false,
  variant = 'primary', // 'primary' uses royal blue (#2563EB) like the filter screenshot, 'brand' uses #E7252B
  size = 'medium',
  subtitle,
  style,
  testID = 'checkbox',
}) => {
  const getActiveColor = () => {
    switch (variant) {
      case 'brand':
        return '#E7252B';
      case 'success':
        return '#10B981';
      case 'primary':
      default:
        return '#2563EB'; // Blue as in Screenshot (Bộ lọc tìm kiếm)
    }
  };

  const getDimensions = () => {
    switch (size) {
      case 'small':
        return { boxSize: 18, radius: 4, checkSize: 11 };
      case 'large':
        return { boxSize: 26, radius: 6, checkSize: 16 };
      case 'medium':
      default:
        return { boxSize: 22, radius: 5, checkSize: 13 };
    }
  };

  const dims = getDimensions();
  const activeColor = getActiveColor();

  return (
    <View testID={testID} style={style}>
      <TouchableOpacity
        testID={`${testID}-touchable`}
        style={[styles.container, disabled && styles.disabled]}
        onPress={() => !disabled && onToggle(!checked)}
        activeOpacity={0.7}
        disabled={disabled}
        accessibilityRole="checkbox"
        accessibilityState={{ checked, disabled }}
      >
        <View
          testID={`${testID}-box`}
          style={[
          styles.box,
          {
            width: dims.boxSize,
            height: dims.boxSize,
            borderRadius: dims.radius,
            borderColor: checked ? activeColor : '#9CA3AF',
            backgroundColor: checked ? activeColor : '#FFFFFF',
          },
        ]}
      >
        {checked ? (
          <Text
            testID={`${testID}-check-icon`}
            style={[styles.checkmark, { fontSize: dims.checkSize }]}
          >
            ✓
          </Text>
        ) : null}
      </View>

      {label ? (
        <View style={styles.labelContainer}>
          <Text
            testID={`${testID}-label`}
            style={[
              styles.label,
              size === 'small' && { fontSize: 13 },
              size === 'large' && { fontSize: 16 },
              disabled && styles.labelDisabled,
            ]}
          >
            {label}
          </Text>
          {subtitle ? (
            <Text
              testID={`${testID}-subtitle`}
              style={styles.subtitle}
            >
              {subtitle}
            </Text>
          ) : null}
        </View>
      ) : null}
      </TouchableOpacity>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flexDirection: 'row',
    alignItems: 'center',
    marginVertical: 6,
  },
  disabled: {
    opacity: 0.5,
  },
  box: {
    borderWidth: 1.5,
    justifyContent: 'center',
    alignItems: 'center',
    marginRight: 10,
  },
  checkmark: {
    color: '#FFFFFF',
    fontWeight: '800',
    lineHeight: 14,
    textAlign: 'center',
  },
  labelContainer: {
    flex: 1,
  },
  label: {
    fontSize: 15,
    color: '#1F2937',
    fontWeight: '500',
  },
  labelDisabled: {
    color: '#9CA3AF',
  },
  subtitle: {
    fontSize: 12,
    color: '#6B7280',
    marginTop: 2,
  },
});
