import React, { useState, useEffect } from 'react';
import { View, StyleSheet, ViewStyle } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { Toast, ToastOptions } from '@mfe/core/utils/toastUtil';
import { AppToast } from './AppToast';

export interface ToastContainerProps {
  style?: ViewStyle;
  topOffset?: number;
  bottomOffset?: number;
  testID?: string;
}

/**
 * Global Host/Root Toast Container.
 * Subscribes to `Toast` events and renders floating notifications at the top or bottom of the screen
 * accounting for safe area insets (notches, status bars, home indicators).
 */
export const ToastContainer: React.FC<ToastContainerProps> = ({
  style,
  topOffset = 12,
  bottomOffset = 24,
  testID = 'toast-container',
}) => {
  const [currentToast, setCurrentToast] = useState<ToastOptions | null>(null);
  let insets = { top: 0, bottom: 0, left: 0, right: 0 };
  try {
    insets = useSafeAreaInsets();
  } catch (_e) {
    // Fallback if rendered outside SafeAreaProvider
    insets = { top: 0, bottom: 0, left: 0, right: 0 };
  }

  useEffect(() => {
    const unsubscribe = Toast.subscribe((toast) => {
      setCurrentToast(toast);
    });
    return () => {
      unsubscribe();
    };
  }, []);

  if (!currentToast) {
    return null;
  }

  const isBottom = currentToast.position === 'bottom';
  const computedInset = isBottom
    ? { bottom: insets.bottom + bottomOffset }
    : { top: insets.top + topOffset };

  return (
    <View
      pointerEvents="box-none"
      style={[styles.container, computedInset, style]}
      testID={testID}
    >
      <AppToast
        toast={currentToast}
        onDismiss={() => Toast.dismiss(currentToast.id)}
        testID={currentToast.id || `${testID}-active`}
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    position: 'absolute',
    left: 0,
    right: 0,
    zIndex: 99999,
    elevation: 99999,
  },
});
