import React, { useState } from 'react';
import {
  View,
  Text,
  ScrollView,
  StyleSheet,
  TouchableOpacity,
  Dimensions,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { LoanCalculator, AmortizationScheduleRow } from '@mfe/core/utils/loanCalculator';
import { DateTimeUtil } from '@mfe/core/utils/dateTimeUtil';
import { CurrencyWordsUtil } from '@mfe/core/utils/currencyWordsUtil';

export interface RepaymentScheduleTableProps {
  principal: number;
  annualInterestRate: number; // e.g. 18 for 18%
  tenureMonths: number;
  disbursementDate?: Date | string;
  pageSize?: number;
  testID?: string;
}

/**
 * Enterprise Amortization & Repayment Schedule Table matching LO-006 / Lịch trả nợ from Lotte projects.
 * Replaces demo tables with true financial annuity calculations, paging, and legal summary totals.
 */
export const RepaymentScheduleTable: React.FC<RepaymentScheduleTableProps> = ({
  principal,
  annualInterestRate,
  tenureMonths,
  disbursementDate = new Date(),
  pageSize = 6,
  testID = 'repayment-schedule-table',
}) => {
  const { theme } = useTheme();
  const [currentPage, setCurrentPage] = useState(1);

  // Generate schedule using standard banking annuity formulas
  const fullSchedule = LoanCalculator.generateAmortizationSchedule(
    principal,
    annualInterestRate,
    tenureMonths
  );

  const totalPages = Math.ceil(fullSchedule.length / pageSize) || 1;
  const startIndex = (currentPage - 1) * pageSize;
  const visibleRows = fullSchedule.slice(startIndex, startIndex + pageSize);

  const totalInterest = fullSchedule.reduce((sum, r) => sum + r.interestPaid, 0);
  const totalRepayment = principal + totalInterest;

  return (
    <View testID={testID} style={styles.container}>
      {/* Financial Summary Header Card */}
      <View style={[styles.summaryBox, { borderColor: theme.colors.border || '#E5E7EB' }]}>
        <View style={styles.summaryItem}>
          <Text style={styles.summaryLabel}>Principal Loan</Text>
          <Text style={[styles.summaryValue, { color: theme.colors.text || '#111827' }]}>
            {principal.toLocaleString()} ₫
          </Text>
        </View>
        <View style={styles.summaryItem}>
          <Text style={styles.summaryLabel}>Total Interest</Text>
          <Text style={[styles.summaryValue, { color: '#E7252B' }]}>
            {totalInterest.toLocaleString()} ₫
          </Text>
        </View>
        <View style={styles.summaryItem}>
          <Text style={styles.summaryLabel}>Total Payoff</Text>
          <Text style={[styles.summaryValue, { color: '#059669' }]}>
            {totalRepayment.toLocaleString()} ₫
          </Text>
        </View>
      </View>

      {/* Responsive Horizontal Scroll Table */}
      <ScrollView horizontal showsHorizontalScrollIndicator={true} style={styles.tableScroll}>
        <View style={styles.table}>
          {/* Header Row */}
          <View style={[styles.headerRow, { backgroundColor: '#F3F4F6' }]}>
            <Text style={[styles.th, styles.colIdx]}>Kỳ / No.</Text>
            <Text style={[styles.th, styles.colDate]}>Ngày đến hạn / Due</Text>
            <Text style={[styles.th, styles.colNum]}>Số tiền trả / Installment</Text>
            <Text style={[styles.th, styles.colNum]}>Gốc / Principal</Text>
            <Text style={[styles.th, styles.colNum]}>Lãi / Interest</Text>
            <Text style={[styles.th, styles.colNum]}>Dư nợ cuối / Balance</Text>
          </View>

          {/* Schedule Data Rows */}
          {visibleRows.map((row) => {
            const dueDate = DateTimeUtil.calculateDueDate(disbursementDate, row.month);
            return (
              <View
                key={`installment-${row.month}`}
                testID={`${testID}-row-${row.month}`}
                style={[
                  styles.dataRow,
                  row.month % 2 === 0 ? { backgroundColor: '#F9FAFB' } : { backgroundColor: '#FFFFFF' },
                ]}
              >
                <Text style={[styles.td, styles.colIdx, styles.bold]}>#{row.month}</Text>
                <Text style={[styles.td, styles.colDate]}>
                  {DateTimeUtil.formatDate(dueDate, 'DD/MM/YYYY')}
                </Text>
                <Text style={[styles.td, styles.colNum, styles.bold, { color: theme.colors.primary }]}>
                  {row.payment.toLocaleString()} ₫
                </Text>
                <Text style={[styles.td, styles.colNum]}>{row.principalPaid.toLocaleString()} ₫</Text>
                <Text style={[styles.td, styles.colNum, { color: '#D97706' }]}>
                  {row.interestPaid.toLocaleString()} ₫
                </Text>
                <Text style={[styles.td, styles.colNum, { color: '#4B5563' }]}>
                  {row.closingBalance.toLocaleString()} ₫
                </Text>
              </View>
            );
          })}
        </View>
      </ScrollView>

      {/* Pagination Controls */}
      <View style={styles.paginationRow}>
        <Text style={styles.pageIndicator}>
          Page {currentPage} of {totalPages} ({fullSchedule.length} installments)
        </Text>
        <View style={styles.paginationButtons}>
          <TouchableOpacity
            testID={`${testID}-prev-page`}
            disabled={currentPage <= 1}
            onPress={() => setCurrentPage((p) => Math.max(1, p - 1))}
            style={[styles.pageBtn, currentPage <= 1 && styles.pageBtnDisabled]}
          >
            <Text style={[styles.pageBtnText, currentPage <= 1 && styles.pageBtnTextDisabled]}>
              ◀ Prev
            </Text>
          </TouchableOpacity>
          <TouchableOpacity
            testID={`${testID}-next-page`}
            disabled={currentPage >= totalPages}
            onPress={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
            style={[styles.pageBtn, currentPage >= totalPages && styles.pageBtnDisabled]}
          >
            <Text style={[styles.pageBtnText, currentPage >= totalPages && styles.pageBtnTextDisabled]}>
              Next ▶
            </Text>
          </TouchableOpacity>
        </View>
      </View>
    </View>
  );
};

