import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  Animated,
  GestureResponderHandlers,
  LayoutChangeEvent,
  PanResponder,
  StyleSheet,
  Text,
  TouchableOpacity,
  View,
  ViewStyle,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

/**
 * Pure utility to immutably move an item from `fromIndex` to `toIndex`.
 */
export function reorderItems<T>(
  items: readonly T[],
  fromIndex: number,
  toIndex: number
): T[] {
  if (
    fromIndex < 0 ||
    toIndex < 0 ||
    fromIndex >= items.length ||
    toIndex >= items.length ||
    fromIndex === toIndex
  ) {
    return [...items];
  }

  const next = [...items];
  const [moved] = next.splice(fromIndex, 1);
  next.splice(toIndex, 0, moved);
  return next;
}

export interface SortableRenderItemInfo<T> {
  item: T;
  index: number;
  isDragging: boolean;
  /** Attach these handlers to a custom drag handle if `showDragHandle` is false. */
  dragHandleProps: GestureResponderHandlers;
  moveUp: () => void;
  moveDown: () => void;
  canMoveUp: boolean;
  canMoveDown: boolean;
}

export interface SortableProps<T> {
  /** Ordered array of items to display and sort. */
  items: T[];
  /** Extracts a stable unique key for each item. */
  keyExtractor: (item: T, index: number) => string;
  /** Renders the content of each sortable row. */
  renderItem: (info: SortableRenderItemInfo<T>) => React.ReactNode;
  /** Called when the user finishes reordering an item. */
  onReorder: (nextItems: T[], fromIndex: number, toIndex: number) => void;
  /** Called when a drag gesture starts (e.g. to lock a parent ScrollView). */
  onDragStart?: (index: number) => void;
  /** Called when a drag gesture ends. */
  onDragEnd?: (fromIndex: number, toIndex: number) => void;
  /** Disables all drag and move interactions. */
  disabled?: boolean;
  /** When true, only the drag handle initiates dragging (recommended inside ScrollView). */
  dragHandleOnly?: boolean;
  /** Whether to render the built-in 6-dot grip handle on the left/right. */
  showDragHandle?: boolean;
  /** Position of the built-in drag handle. */
  dragHandlePosition?: 'left' | 'right';
  /** Optional custom drag handle renderer. */
  renderDragHandle?: (isDragging: boolean) => React.ReactNode;
  /** Show accessible up/down reorder buttons on each row. */
  showMoveButtons?: boolean;
  /** Vertical gap between rows in pixels. */
  itemGap?: number;
  /** Fallback row height before onLayout measures each row. */
  estimatedItemHeight?: number;
  /** Render each row inside a themed card border. */
  bordered?: boolean;
  /** Message displayed when `items` is empty. */
  emptyText?: string;
  /** Container style. */
  style?: ViewStyle;
  /** Style applied to each row wrapper. */
  itemContainerStyle?: ViewStyle;
  /** Extra style applied to the actively dragged row. */
  activeItemStyle?: ViewStyle;
  /** Base testID for automated testing. */
  testID?: string;
}

interface DefaultGripHandleProps {
  color: string;
}

const DefaultGripHandle: React.FC<DefaultGripHandleProps> = ({ color }) => (
  <View style={styles.gripGrid} accessible={false}>
    <View style={styles.gripRow}>
      <View style={[styles.gripDot, { backgroundColor: color }]} />
      <View style={[styles.gripDot, { backgroundColor: color }]} />
    </View>
    <View style={styles.gripRow}>
      <View style={[styles.gripDot, { backgroundColor: color }]} />
      <View style={[styles.gripDot, { backgroundColor: color }]} />
    </View>
    <View style={styles.gripRow}>
      <View style={[styles.gripDot, { backgroundColor: color }]} />
      <View style={[styles.gripDot, { backgroundColor: color }]} />
    </View>
  </View>
);

export function Sortable<T>({
  items,
  keyExtractor,
  renderItem,
  onReorder,
  onDragStart,
  onDragEnd,
  disabled = false,
  dragHandleOnly = true,
  showDragHandle = true,
  dragHandlePosition = 'left',
  renderDragHandle,
  showMoveButtons = false,
  itemGap = 8,
  estimatedItemHeight = 56,
  bordered = true,
  emptyText,
  style,
  itemContainerStyle,
  activeItemStyle,
  testID = 'sortable',
}: SortableProps<T>) {
  const { theme } = useTheme();

  const [draggingIndex, setDraggingIndex] = useState<number | null>(null);
  const [targetIndex, setTargetIndex] = useState<number | null>(null);

  const dragY = useRef(new Animated.Value(0)).current;
  const dragScale = useRef(new Animated.Value(1)).current;
  const itemHeightsRef = useRef<Record<string, number>>({});

  // Keep latest values in refs for PanResponder closures
  const itemsRef = useRef(items);
  itemsRef.current = items;

  const keyExtractorRef = useRef(keyExtractor);
  keyExtractorRef.current = keyExtractor;

  const onReorderRef = useRef(onReorder);
  onReorderRef.current = onReorder;

  const onDragStartRef = useRef(onDragStart);
  onDragStartRef.current = onDragStart;

  const onDragEndRef = useRef(onDragEnd);
  onDragEndRef.current = onDragEnd;

  const draggingIndexRef = useRef<number | null>(null);
  const targetIndexRef = useRef<number | null>(null);

  const getRowHeight = useCallback(
    (index: number): number => {
      const currentItems = itemsRef.current;
      const item = currentItems[index];
      if (!item) return estimatedItemHeight;
      const key = keyExtractorRef.current(item, index);
      return itemHeightsRef.current[key] ?? estimatedItemHeight;
    },
    [estimatedItemHeight]
  );

  const computeTargetIndex = useCallback(
    (fromIndex: number, dy: number): number => {
      const count = itemsRef.current.length;
      if (count <= 1) return fromIndex;

      let nextIndex = fromIndex;
      if (dy > 0) {
        let remaining = dy;
        while (nextIndex < count - 1) {
          const step = (getRowHeight(nextIndex + 1) + itemGap) * 0.5;
          if (remaining >= step) {
            remaining -= getRowHeight(nextIndex + 1) + itemGap;
            nextIndex += 1;
          } else {
            break;
          }
        }
      } else if (dy < 0) {
        let remaining = Math.abs(dy);
        while (nextIndex > 0) {
          const step = (getRowHeight(nextIndex - 1) + itemGap) * 0.5;
          if (remaining >= step) {
            remaining -= getRowHeight(nextIndex - 1) + itemGap;
            nextIndex -= 1;
          } else {
            break;
          }
        }
      }
      return nextIndex;
    },
    [getRowHeight, itemGap]
  );

  const handleMove = useCallback(
    (fromIndex: number, toIndex: number) => {
      if (disabled) return;
      const current = itemsRef.current;
      if (
        toIndex < 0 ||
        toIndex >= current.length ||
        fromIndex === toIndex
      ) {
        return;
      }
      const next = reorderItems(current, fromIndex, toIndex);
      onReorderRef.current(next, fromIndex, toIndex);
    },
    [disabled]
  );

  const finishDrag = useCallback(() => {
    const from = draggingIndexRef.current;
    const to = targetIndexRef.current;

    draggingIndexRef.current = null;
    targetIndexRef.current = null;
    setDraggingIndex(null);
    setTargetIndex(null);

    dragY.setValue(0);
    Animated.spring(dragScale, {
      toValue: 1,
      useNativeDriver: true,
      speed: 24,
      bounciness: 0,
    }).start();

    if (from !== null && to !== null) {
      if (from !== to) {
        const next = reorderItems(itemsRef.current, from, to);
        onReorderRef.current(next, from, to);
      }
      onDragEndRef.current?.(from, to);
    }
  }, [dragScale, dragY]);

  useEffect(() => {
    return () => {
      dragY.stopAnimation();
      dragScale.stopAnimation();
    };
  }, [dragScale, dragY]);

  const panResponders = useMemo(
    () =>
      items.map((_, index) =>
        PanResponder.create({
          onStartShouldSetPanResponder: () => !disabled,
          onMoveShouldSetPanResponder: (_, gestureState) =>
            !disabled && Math.abs(gestureState.dy) > 3,
          onPanResponderGrant: () => {
            draggingIndexRef.current = index;
            targetIndexRef.current = index;
            setDraggingIndex(index);
            setTargetIndex(index);
            dragY.setValue(0);
            Animated.spring(dragScale, {
              toValue: 1.02,
              useNativeDriver: true,
              speed: 24,
              bounciness: 0,
            }).start();
            onDragStartRef.current?.(index);
          },
          onPanResponderMove: (_, gestureState) => {
            if (draggingIndexRef.current === null) return;
            dragY.setValue(gestureState.dy);
            const nextTarget = computeTargetIndex(
              draggingIndexRef.current,
              gestureState.dy
            );
            if (nextTarget !== targetIndexRef.current) {
              targetIndexRef.current = nextTarget;
              setTargetIndex(nextTarget);
            }
          },
          onPanResponderRelease: () => {
            finishDrag();
          },
          onPanResponderTerminate: () => {
            finishDrag();
          },
        })
      ),
    [computeTargetIndex, disabled, dragScale, dragY, finishDrag, items]
  );

  const handleRowLayout = useCallback(
    (key: string) => (event: LayoutChangeEvent) => {
      const { height } = event.nativeEvent.layout;
      if (height > 0) {
        itemHeightsRef.current[key] = height;
      }
    },
    []
  );

  const primaryColor = theme?.colors?.primary ?? '#E7252B';
  const cardBg = theme?.colors?.card ?? '#FFFFFF';
  const borderColor = theme?.colors?.border ?? '#E5E7EB';
  const mutedColor = theme?.colors?.textSecondary ?? '#9CA3AF';
  const radiusMd = theme?.radius?.md ?? 10;

  if (items.length === 0) {
    return (
      <View testID={`${testID}-empty`} style={[styles.emptyContainer, style]}>
        {emptyText ? (
          <Text style={[styles.emptyText, { color: mutedColor }]}>
            {emptyText}
          </Text>
        ) : null}
      </View>
    );
  }

  return (
    <View testID={testID} style={[styles.container, style]}>
      {items.map((item, index) => {
        const key = keyExtractor(item, index);
        const isDragging = draggingIndex === index;
        const panHandlers = panResponders[index]?.panHandlers ?? {};
        const canMoveUp = !disabled && index > 0;
        const canMoveDown = !disabled && index < items.length - 1;

        // Calculate visual shift for non-dragged sibling items
        let siblingShiftY = 0;
        if (
          draggingIndex !== null &&
          targetIndex !== null &&
          !isDragging
        ) {
          const draggedHeight = getRowHeight(draggingIndex) + itemGap;
          if (
            draggingIndex < targetIndex &&
            index > draggingIndex &&
            index <= targetIndex
          ) {
            siblingShiftY = -draggedHeight;
          } else if (
            draggingIndex > targetIndex &&
            index >= targetIndex &&
            index < draggingIndex
          ) {
            siblingShiftY = draggedHeight;
          }
        }

        const dragHandleNode = showDragHandle ? (
          <View
            testID={`${testID}-handle-${key}`}
            accessibilityRole="adjustable"
            accessibilityLabel="Drag to reorder"
            style={[
              styles.dragHandle,
              disabled && styles.disabledControl,
            ]}
            {...(dragHandleOnly ? panHandlers : {})}
          >
            {renderDragHandle ? (
              renderDragHandle(isDragging)
            ) : (
              <DefaultGripHandle
                color={isDragging ? primaryColor : mutedColor}
              />
            )}
          </View>
        ) : null;

        const moveButtonsNode = showMoveButtons ? (
          <View style={styles.moveButtons}>
            <TouchableOpacity
              testID={`${testID}-move-up-${key}`}
              accessibilityRole="button"
              accessibilityLabel="Move item up"
              disabled={!canMoveUp}
              onPress={() => handleMove(index, index - 1)}
              style={[
                styles.moveButton,
                { borderColor },
                !canMoveUp && styles.disabledControl,
              ]}
            >
              <Text style={[styles.moveButtonText, { color: mutedColor }]}>
                ▲
              </Text>
            </TouchableOpacity>
            <TouchableOpacity
              testID={`${testID}-move-down-${key}`}
              accessibilityRole="button"
              accessibilityLabel="Move item down"
              disabled={!canMoveDown}
              onPress={() => handleMove(index, index + 1)}
              style={[
                styles.moveButton,
                { borderColor },
                !canMoveDown && styles.disabledControl,
              ]}
            >
              <Text style={[styles.moveButtonText, { color: mutedColor }]}>
                ▼
              </Text>
            </TouchableOpacity>
          </View>
        ) : null;

        return (
          <Animated.View
            key={key}
            testID={`${testID}-item-${key}`}
            onLayout={handleRowLayout(key)}
            {...(!dragHandleOnly ? panHandlers : {})}
            style={[
              styles.itemRow,
              bordered && {
                backgroundColor: cardBg,
                borderColor: isDragging ? primaryColor : borderColor,
                borderWidth: 1,
                borderRadius: radiusMd,
              },
              index < items.length - 1 && { marginBottom: itemGap },
              itemContainerStyle,
              isDragging && [
                styles.activeItem,
                {
                  transform: [
                    { translateY: dragY },
                    { scale: dragScale },
                  ],
                },
                activeItemStyle,
              ],
              !isDragging &&
                siblingShiftY !== 0 && {
                  transform: [{ translateY: siblingShiftY }],
                },
            ]}
          >
            {dragHandlePosition === 'left' ? dragHandleNode : null}

            <View style={styles.itemContent}>
              {renderItem({
                item,
                index,
                isDragging,
                dragHandleProps: panHandlers,
                moveUp: () => handleMove(index, index - 1),
                moveDown: () => handleMove(index, index + 1),
                canMoveUp,
                canMoveDown,
              })}
            </View>

            {moveButtonsNode}
            {dragHandlePosition === 'right' ? dragHandleNode : null}
          </Animated.View>
        );
      })}
    </View>
  );
}

export const SortableList = Sortable;

const styles = StyleSheet.create({
  container: {
    width: '100%',
  },
  itemRow: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 12,
    paddingVertical: 10,
  },
  itemContent: {
    flex: 1,
  },
  activeItem: {
    zIndex: 999,
    elevation: 6,
    shadowColor: '#000000',
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.14,
    shadowRadius: 8,
  },
  dragHandle: {
    paddingHorizontal: 8,
    paddingVertical: 6,
    justifyContent: 'center',
    alignItems: 'center',
  },
  gripGrid: {
    gap: 3,
  },
  gripRow: {
    flexDirection: 'row',
    gap: 3,
  },
  gripDot: {
    width: 3.5,
    height: 3.5,
    borderRadius: 2,
  },
  moveButtons: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 4,
    marginLeft: 8,
  },
  moveButton: {
    width: 28,
    height: 28,
    borderRadius: 6,
    borderWidth: 1,
    justifyContent: 'center',
    alignItems: 'center',
  },
  moveButtonText: {
    fontSize: 10,
    fontWeight: '700',
  },
  disabledControl: {
    opacity: 0.35,
  },
  emptyContainer: {
    paddingVertical: 16,
    alignItems: 'center',
    justifyContent: 'center',
  },
  emptyText: {
    fontSize: 13,
  },
});
