import React from 'react';
import {
  View,
  Text,
  ScrollView,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
  ImageSourcePropType,
  Image,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { NetworkImage } from '../media/NetworkImage';

export interface HorizontalCardItem {
  id: string;
  title: string;
  subtitle?: string;
  badge?: string;
  imageUrl?: string;
  imageSource?: ImageSourcePropType;
  cardArtColor?: string; // e.g. '#C8102E' or '#0F172A'
  tag?: string;
  onPress?: () => void;
  metadata?: Record<string, any>;
}

export interface HorizontalCardListProps {
  title?: string;
  subtitle?: string;
  actionText?: string;
  onActionPress?: () => void;
  items: HorizontalCardItem[];
  cardWidth?: number;
  itemSpacing?: number;
  containerStyle?: ViewStyle;
  testID?: string;
  renderCustomCard?: (item: HorizontalCardItem, index: number) => React.ReactNode;
}

/**
 * Clean enterprise Horizontal Card List component.
 * Displays card carousels (e.g. Recommended Cards, Loan products, Offers)
 * with section title, action link, horizontal scrolling, and responsive styling.
 * Matches Lotte Digital Finance "RECOMMENDED CARD >" section.
 */
export const HorizontalCardList: React.FC<HorizontalCardListProps> = ({
  title,
  subtitle,
  actionText,
  onActionPress,
  items,
  cardWidth = 140,
  itemSpacing = 14,
  containerStyle,
  testID = 'horizontal-card-list',
  renderCustomCard,
}) => {
  const { theme } = useTheme();

  return (
    <View testID={testID} style={[styles.container, containerStyle]}>
      {/* Header with Title and Action CTA */}
      {(title || actionText) && (
        <View style={styles.headerRow}>
          <View style={styles.titleWrap}>
            {title ? (
              <TouchableOpacity
                activeOpacity={onActionPress ? 0.7 : 1}
                onPress={onActionPress}
                disabled={!onActionPress}
                style={styles.titlePressable}
              >
                <Text
                  testID={`${testID}-title`}
                  style={[styles.title, { color: theme.colors.text }]}
                >
                  {title}
                </Text>
                {onActionPress && !actionText ? (
                  <Text style={[styles.titleArrow, { color: theme.colors.text }]}>
                    {' 〉'}
                  </Text>
                ) : null}
              </TouchableOpacity>
            ) : null}
            {subtitle ? <Text style={styles.subtitle}>{subtitle}</Text> : null}
          </View>

          {actionText && onActionPress ? (
            <TouchableOpacity
              testID={`${testID}-action-btn`}
              activeOpacity={0.7}
              onPress={onActionPress}
              style={styles.actionBtn}
            >
              <Text
                style={[
                  styles.actionText,
                  { color: theme.colors.textMuted || '#4D5563' },
                ]}
              >
                {actionText}
              </Text>
            </TouchableOpacity>
          ) : null}
        </View>
      )}

      {/* Horizontal Scroll Area */}
      <ScrollView
        horizontal
        showsHorizontalScrollIndicator={false}
        contentContainerStyle={[
          styles.scrollContent,
          { gap: itemSpacing },
        ]}
        testID={`${testID}-scroll-view`}
      >
        {items.map((item, index) => {
          if (renderCustomCard) {
            return (
              <React.Fragment key={item.id}>
                {renderCustomCard(item, index)}
              </React.Fragment>
            );
          }

          return (
            <TouchableOpacity
              key={item.id}
              testID={`${testID}-item-${item.id}`}
              activeOpacity={0.85}
              onPress={item.onPress}
              style={[
                styles.card,
                {
                  width: cardWidth,
                  borderColor: theme.colors.border || '#E5E7EB',
                },
              ]}
            >
              {/* Card Visual / Thumbnail */}
              <View
                style={[
                  styles.cardVisualContainer,
                  item.cardArtColor
                    ? { backgroundColor: item.cardArtColor }
                    : { backgroundColor: '#1A1C20' },
                ]}
              >
                {item.imageUrl ? (
                  <NetworkImage
                    uri={item.imageUrl}
                    style={styles.cardImage}
                    resizeMode="cover"
                    borderRadius={8}
                    testID={`${testID}-image-${item.id}`}
                  />
                ) : item.imageSource ? (
                  <Image
                    source={item.imageSource}
                    style={styles.cardImage}
                    resizeMode="cover"
                  />
                ) : (
                  <View style={styles.defaultCardGraphic}>
                    {/* Chip & Logo accents */}
                    <View style={styles.cardChip} />
                    <View style={styles.cardLogoRow}>
                      <View style={styles.cardCircleSmall} />
                      <Text style={styles.cardBrandText}>VISA</Text>
                    </View>
                  </View>
                )}

                {item.badge ? (
                  <View
                    style={[
                      styles.badgeWrapper,
                      { backgroundColor: theme.colors.primary },
                    ]}
                  >
                    <Text style={styles.badgeText}>{item.badge}</Text>
                  </View>
                ) : null}
              </View>

              {/* Title & Description Copy */}
              <View style={styles.cardMeta}>
                <Text
                  numberOfLines={2}
                  style={[styles.cardTitle, { color: theme.colors.text }]}
                  testID={`${testID}-item-title-${item.id}`}
                >
                  {item.title}
                </Text>

                {item.subtitle ? (
                  <Text
                    numberOfLines={2}
                    style={[
                      styles.cardSubtitle,
                      { color: theme.colors.textSubtle || '#6B7280' },
                    ]}
                  >
                    {item.subtitle}
                  </Text>
                ) : null}
              </View>
            </TouchableOpacity>
          );
        })}
      </ScrollView>
    </View>
  );
};

