import React, { useState } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ViewStyle,
  ScrollView,
  TouchableOpacity,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export interface DataTableColumn<T = any> {
  key: string;
  title: string;
  width?: number;
  minWidth?: number;
  align?: 'left' | 'center' | 'right';
  render?: (row: T, index: number) => React.ReactNode;
}

export interface TablePaginationConfig {
  /** Total count of items across all pages */
  totalItems: number;
  /** Current page index (1-based) */
  currentPage: number;
  /** Number of items displayed per page */
  pageSize: number;
  /** Callback fired when page changes */
  onPageChange: (page: number) => void;
  /** Custom label for results counter, e.g. "Kết quả" or "Results" */
  resultsLabel?: string;
}

export interface DataTableProps<T = any> {
  columns: DataTableColumn<T>[];
  data: T[];
  keyExtractor: (item: T, index: number) => string;
  emptyText?: string;
  bordered?: boolean;
  /** Optional pagination config matching Lotte Finance enterprise tables */
  pagination?: TablePaginationConfig;
  style?: ViewStyle;
  testID?: string;
}

export function DataTable<T = any>({
  columns,
  data,
  keyExtractor,
  emptyText = 'No records available',
  bordered = true,
  pagination,
  style,
  testID = 'data-table',
}: DataTableProps<T>) {
  const { theme } = useTheme();

  // Calculate items to display: if client-side slicing without server pagination
  let displayData = data;
  if (pagination && data.length > pagination.pageSize) {
    const startIndex = (pagination.currentPage - 1) * pagination.pageSize;
    displayData = data.slice(startIndex, startIndex + pagination.pageSize);
  }

  // Pagination bounds
  const totalItems = pagination?.totalItems ?? data.length;
  const currentPage = pagination?.currentPage ?? 1;
  const pageSize = pagination?.pageSize ?? 10;
  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));

  const startRecord = totalItems === 0 ? 0 : (currentPage - 1) * pageSize + 1;
  const endRecord = Math.min(totalItems, currentPage * pageSize);
  const resultsLabel = pagination?.resultsLabel ?? 'Kết quả';

  // Build page numbers array (e.g. 1, 2, 3...)
  const getPageNumbers = () => {
    const pages: (number | string)[] = [];
    const maxButtons = 5;
    if (totalPages <= maxButtons) {
      for (let i = 1; i <= totalPages; i++) pages.push(i);
    } else {
      let start = Math.max(1, currentPage - 2);
      let end = Math.min(totalPages, start + maxButtons - 1);
      if (end - start < maxButtons - 1) {
        start = Math.max(1, end - maxButtons + 1);
      }
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
    }
    return pages;
  };

  return (
    <View
      testID={testID}
      style={[
        styles.tableContainer,
        bordered && [
          styles.bordered,
          {
            borderColor: theme.colors.border || '#E5E7EB',
            borderRadius: theme.radius.md,
            backgroundColor: theme.colors.card || '#FFFFFF',
          },
        ],
        style,
      ]}
    >
      <ScrollView horizontal showsHorizontalScrollIndicator={false}>
        <View style={styles.tableInner}>
          {/* Header Row */}
          <View
            style={[
              styles.row,
              styles.headerRow,
              { borderBottomColor: theme.colors.border || '#E5E7EB' },
            ]}
          >
            {columns.map((col) => (
              <View
                key={col.key}
                style={[
                  styles.cell,
                  col.width ? { width: col.width } : styles.flexCell,
                  col.minWidth ? { minWidth: col.minWidth } : null,
                  col.align === 'center'
                    ? styles.alignCenter
                    : col.align === 'right'
                    ? styles.alignRight
                    : styles.alignLeft,
                ]}
              >
                <Text
                  testID={`${testID}-col-${col.key}`}
                  style={[
                    styles.headerText,
                    {
                      color: theme.colors.text || '#16181D',
                      fontFamily: theme.typography.fontFamilyBold,
                    },
                  ]}
                >
                  {col.title}
                </Text>
              </View>
            ))}
          </View>

          {/* Body Rows */}
          {displayData.length === 0 ? (
            <View style={styles.emptyContainer}>
              <Text style={styles.emptyText}>{emptyText}</Text>
            </View>
          ) : (
            displayData.map((row, rowIndex) => {
              const rowKey = keyExtractor(row, rowIndex);
              const isEven = rowIndex % 2 === 0;

              return (
                <View
                  key={rowKey}
                  testID={`${testID}-row-${rowIndex}`}
                  style={[
                    styles.row,
                    isEven ? styles.evenRow : styles.oddRow,
                    rowIndex < displayData.length - 1 && styles.rowDivider,
                  ]}
                >
                  {columns.map((col) => (
                    <View
                      key={col.key}
                      style={[
                        styles.cell,
                        col.width ? { width: col.width } : styles.flexCell,
                        col.minWidth ? { minWidth: col.minWidth } : null,
                        col.align === 'center'
                          ? styles.alignCenter
                          : col.align === 'right'
                          ? styles.alignRight
                          : styles.alignLeft,
                      ]}
                    >
                      {col.render ? (
                        col.render(row, rowIndex)
                      ) : (
                        <Text
                          testID={`${testID}-cell-${rowIndex}-${col.key}`}
                          style={styles.cellText}
                          numberOfLines={2}
                        >
                          {String((row as any)[col.key] ?? '-')}
                        </Text>
                      )}
                    </View>
                  ))}
                </View>
              );
            })
          )}
        </View>
      </ScrollView>

      {/* Pagination Footer (Matching Screenshot Style) */}
      {pagination && totalItems > 0 && (
        <View
          style={[
            styles.paginationContainer,
            { borderTopColor: theme.colors.border || '#E5E7EB' },
          ]}
          testID={`${testID}-pagination`}
        >
          {/* Left summary counter: e.g. 1-8/100 Kết quả */}
          <Text
            style={[styles.paginationCounter, { color: theme.colors.textSubtle || '#6B7280' }]}
            testID={`${testID}-pagination-counter`}
          >
            {`${startRecord}-${endRecord}/${totalItems} ${resultsLabel}`}
          </Text>

          {/* Right Page Controls: [<] [1] [2] [3] [>] */}
          <View style={styles.pageButtonsRow}>
            {/* Previous Button */}
            <TouchableOpacity
              testID={`${testID}-page-prev`}
              activeOpacity={0.7}
              disabled={currentPage <= 1}
              onPress={() => pagination.onPageChange(currentPage - 1)}
              style={[
                styles.pageArrowBtn,
                currentPage <= 1 && styles.disabledBtn,
              ]}
              accessibilityLabel="Trang trước"
            >
              <Text
                style={[
                  styles.arrowText,
                  currentPage <= 1 ? styles.disabledText : styles.activeArrowText,
                ]}
              >
                ‹
              </Text>
            </TouchableOpacity>

            {/* Page Number Buttons */}
            {getPageNumbers().map((p) => {
              const isCurrent = p === currentPage;
              const pageNum = Number(p);

              return (
                <TouchableOpacity
                  key={`page-${p}`}
                  testID={`${testID}-page-${p}`}
                  activeOpacity={0.8}
                  onPress={() => pagination.onPageChange(pageNum)}
                  style={[
                    styles.pageNumberBtn,
                    isCurrent
                      ? styles.currentPageBtn
                      : styles.inactivePageBtn,
                  ]}
                >
                  <Text
                    style={[
                      styles.pageNumberText,
                      isCurrent
                        ? styles.currentPageText
                        : styles.inactivePageText,
                    ]}
                  >
                    {p}
                  </Text>
                </TouchableOpacity>
              );
            })}

            {/* Next Button */}
            <TouchableOpacity
              testID={`${testID}-page-next`}
              activeOpacity={0.7}
              disabled={currentPage >= totalPages}
              onPress={() => pagination.onPageChange(currentPage + 1)}
              style={[
                styles.pageArrowBtn,
                currentPage >= totalPages && styles.disabledBtn,
              ]}
              accessibilityLabel="Trang sau"
            >
              <Text
                style={[
                  styles.arrowText,
                  currentPage >= totalPages
                    ? styles.disabledText
                    : styles.activeArrowText,
                ]}
              >
                ›
              </Text>
            </TouchableOpacity>
          </View>
        </View>
      )}
    </View>
  );
}

