import React, { useEffect, useMemo, useState } from 'react';
import { View, Text, StyleSheet } from 'react-native';
import {
  AppButton,
  AppTextInput,
  StatusBadge,
  DraftApplicationCard,
  DraftApplicationItem,
} from '@mfe/ui-components/components';
import { CodeBlock } from '../../components/CodeBlock';
import { DraftStorageUtil } from '@mfe/core/utils/DraftStorageUtil';
import { Colors } from '@mfe/core/theme';

interface LoanDraftForm {
  customerName: string;
  loanAmount: string;
  tenureMonths: string;
}

const EMPTY_FORM: LoanDraftForm = {
  customerName: '',
  loanAmount: '',
  tenureMonths: '',
};

const DRAFT_KEY = 'showcase_loan_submit_draft';

const B12_DEMO_DRAFTS: DraftApplicationItem[] = [
  {
    id: 'draft-1',
    customerName: 'Hoàng Văn Tùng',
    productType: 'Cash Loan',
    idNumberMasked: 'CCCD 079***4521',
    currentStep: 5,
    totalSteps: 12,
    stepTitle: 'Additional information',
    statusBadgeLabel: 'Draft',
  },
  {
    id: 'draft-2',
    customerName: 'Bùi Thị Mai',
    productType: 'Durable Loan',
    idNumberMasked: 'CCCD 001***8830',
    currentStep: 7,
    totalSteps: 12,
    stepTitle: 'Select scheme',
    statusBadgeLabel: 'Draft',
  },
  {
    id: 'draft-3',
    customerName: 'Lý Quốc Huy',
    productType: 'Car Loan',
    idNumberMasked: 'CCCD 079***1207',
    currentStep: 2,
    totalSteps: 12,
    stepTitle: 'Scan ID chip',
    statusBadgeLabel: 'Draft',
  },
];

const USAGE_SNIPPET = `import { DraftStorageUtil } from '@mfe/core/utils/DraftStorageUtil';

const autoSave = DraftStorageUtil.createAutoSave<LoanForm>('loan_submit', {
  debounceMs: 500,
});

// 1. On screen mount: check if an unfinished draft exists
const exists = await autoSave.hasDraft();
if (exists) {
  // Show "You have an unfinished task. Continue or Cancel?"
}

// 2. If user taps Continue:
const draft = await autoSave.load();
if (draft) setForm(draft.data);

// 3. On any form field change:
autoSave.scheduleSave(updatedForm, 'step_1');

// 4. If user taps Cancel or completes Submit:
await autoSave.clear();`;

export const AutoSaveDraftDetailSection: React.FC = () => {
  const autoSave = useMemo(
    () => DraftStorageUtil.createAutoSave<LoanDraftForm>(DRAFT_KEY, { debounceMs: 300 }),
    []
  );

  const [form, setForm] = useState<LoanDraftForm>(EMPTY_FORM);
  const [showResumePrompt, setShowResumePrompt] = useState(false);
  const [statusMessage, setStatusMessage] = useState<string>('No draft saved');

  const checkExistingDraft = async () => {
    const exists = await autoSave.hasDraft();
    setShowResumePrompt(exists);
    if (exists) {
      setStatusMessage('Unfinished draft detected');
    }
  };

  useEffect(() => {
    checkExistingDraft();
    return () => {
      autoSave.cancelPending();
    };
  }, [autoSave]);

  const handleFieldChange = (field: keyof LoanDraftForm, value: string) => {
    const updated = { ...form, [field]: value };
    setForm(updated);
    autoSave.scheduleSave(updated, 'loan_form_step_1');
    setStatusMessage('Auto-saving draft...');
  };

  const handleContinueDraft = async () => {
    const draft = await autoSave.load();
    if (draft) {
      setForm(draft.data);
      setStatusMessage('Draft restored');
    }
    setShowResumePrompt(false);
  };

  const handleCancelDraft = async () => {
    await autoSave.clear();
    setForm(EMPTY_FORM);
    setShowResumePrompt(false);
    setStatusMessage('Draft cleared (cancelled)');
  };

  const handleSubmitComplete = async () => {
    await autoSave.clear();
    setForm(EMPTY_FORM);
    setShowResumePrompt(false);
    setStatusMessage('Loan submitted! Draft cleared.');
  };

  return (
    <View testID="auto-save-draft-detail-section" style={styles.container}>
      <View style={styles.card}>
        <Text style={styles.cardTitle}>Auto-Save Draft (Loan Form Sample)</Text>
        <View style={styles.statusRow}>
          <StatusBadge label={statusMessage} variant="info" />
        </View>

        {showResumePrompt && (
          <View testID="draft-resume-prompt" style={styles.promptBox}>
            <Text style={styles.promptTitle}>Unfinished Loan Application</Text>
            <Text style={styles.promptDesc}>
              You have not finished your previous loan submission. Would you like to continue or cancel?
            </Text>
            <View style={styles.promptActions}>
              <AppButton
                title="Continue"
                onPress={handleContinueDraft}
                testID="draft-continue-btn"
              />
              <AppButton
                title="Cancel"
                variant="outline"
                onPress={handleCancelDraft}
                testID="draft-cancel-btn"
              />
            </View>
          </View>
        )}

        <AppTextInput
          label="Customer Name"
          value={form.customerName}
          onChangeText={(v) => handleFieldChange('customerName', v)}
          placeholder="Enter customer name"
          testID="draft-customer-name-input"
        />

        <AppTextInput
          label="Loan Amount (USD)"
          value={form.loanAmount}
          onChangeText={(v) => handleFieldChange('loanAmount', v)}
          placeholder="e.g. 5000"
          keyboardType="numeric"
          testID="draft-loan-amount-input"
        />

        <AppTextInput
          label="Tenure (Months)"
          value={form.tenureMonths}
          onChangeText={(v) => handleFieldChange('tenureMonths', v)}
          placeholder="e.g. 12"
          keyboardType="numeric"
          testID="draft-tenure-input"
        />

        <View style={styles.actionRow}>
          <AppButton
            title="Submit Loan (Clear Draft)"
            onPress={handleSubmitComplete}
            testID="draft-submit-btn"
          />
          <AppButton
            title="Simulate Re-open Form"
            variant="outline"
            onPress={async () => {
              await autoSave.flush();
              setForm(EMPTY_FORM);
              await checkExistingDraft();
            }}
            testID="draft-reopen-btn"
          />
        </View>
      </View>

      <View style={styles.card}>
        <Text style={styles.cardTitle}>Draft Applications List (B12 Style)</Text>
        <Text style={styles.promptDesc}>
          Persistent multi-application draft recovery list with progress bars, masked CCCDs, and step descriptions.
        </Text>

        <View style={{ marginTop: 12 }}>
          {B12_DEMO_DRAFTS.map((item) => (
            <DraftApplicationCard
              key={item.id}
              item={item}
              onPress={(selected) => {
                alert(`Resuming draft for ${selected.customerName} at step ${selected.currentStep}/${selected.totalSteps}`);
              }}
              testID={`b12-draft-${item.id}`}
            />
          ))}
          <Text style={styles.footerTip}>
            Tap an application to continue from where it stopped.
          </Text>
        </View>
      </View>

      <View style={styles.card}>
        <Text style={styles.cardTitle}>DraftStorageUtil Usage Guide</Text>
        <CodeBlock code={USAGE_SNIPPET} />
      </View>
    </View>
  );
};

