import React from 'react';
import {
  View,
  Text,
  StyleSheet,
  ViewStyle,
  Image,
  ImageSourcePropType,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { AppButton } from '../button/AppButton';

export type StatusResultType = 'success' | 'failed' | 'warning' | 'info';

export interface ResultScreenViewProps {
  type?: StatusResultType;
  title: string;
  description?: string;
  /**
   * Primary action button text (default: 'Continue')
   */
  primaryButtonText?: string;
  onPrimaryPress: () => void;
  /**
   * Optional secondary action button text (e.g. 'Back to Home' or 'Retry')
   */
  secondaryButtonText?: string;
  onSecondaryPress?: () => void;
  /**
   * Custom hero image or illustration component (e.g. 3D party popper, alert badge)
   */
  heroImage?: ImageSourcePropType | React.ReactNode;
  /**
   * Extra information box or transaction summary rendered between description and buttons
   */
  children?: React.ReactNode;
  style?: ViewStyle;
  testID?: string;
}

export const ResultScreenView: React.FC<ResultScreenViewProps> = ({
  type = 'success',
  title,
  description,
  primaryButtonText = 'Continue',
  onPrimaryPress,
  secondaryButtonText,
  onSecondaryPress,
  heroImage,
  children,
  style,
  testID = 'result-screen-view',
}) => {
  const { theme } = useTheme();

  const renderDefaultHero = () => {
    if (heroImage) {
      if (typeof heroImage === 'object' && !('uri' in heroImage) && React.isValidElement(heroImage)) {
        return <View style={styles.heroWrap}>{heroImage}</View>;
      }
      return (
        <View style={styles.heroWrap}>
          <Image
            source={heroImage as ImageSourcePropType}
            style={styles.heroImg}
            resizeMode="contain"
            testID={`${testID}-hero-image`}
          />
        </View>
      );
    }

    // High quality themed icon badges
    const isSuccess = type === 'success';
    const isFailed = type === 'failed';
    const isWarning = type === 'warning';

    const circleBg = isSuccess
      ? '#DEF7EC'
      : isFailed
      ? '#FDE8E8'
      : isWarning
      ? '#FEF08A'
      : '#E1EFFE';

    const iconColor = isSuccess
      ? '#0E9F6E'
      : isFailed
      ? '#E7252B'
      : isWarning
      ? '#CA8A04'
      : '#1C64F2';

    return (
      <View style={styles.heroWrap} testID={`${testID}-badge-hero`}>
        {isSuccess ? (
          // Celebratory Party Popper Illustration with confetti
          <View style={styles.partyPopperContainer}>
            <View style={[styles.popperCone]}>
              <Text style={{ fontSize: 72 }}>🎉</Text>
            </View>
          </View>
        ) : (
          <View style={[styles.statusCircle, { backgroundColor: circleBg }]}>
            <Text style={[styles.statusSymbol, { color: iconColor }]}>
              {isFailed ? '✕' : isWarning ? '!' : 'ℹ'}
            </Text>
          </View>
        )}
      </View>
    );
  };

  return (
    <View testID={testID} style={[styles.container, style]}>
      {/* Top Graphic / Hero Section */}
      <View style={styles.topSection}>
        {renderDefaultHero()}

        <Text
          testID={`${testID}-title`}
          style={[
            styles.title,
            { color: theme.colors.text, fontFamily: theme.typography.fontFamilyBold },
          ]}
        >
          {title}
        </Text>

        {description ? (
          <Text testID={`${testID}-desc`} style={styles.description}>
            {description}
          </Text>
        ) : null}

        {children ? <View style={styles.customContent}>{children}</View> : null}
      </View>

      {/* Bottom Sticky Action Buttons */}
      <View style={styles.bottomSection}>
        <AppButton
          title={primaryButtonText}
          variant="primary"
          onPress={onPrimaryPress}
          testID={`${testID}-primary-btn`}
          style={styles.primaryBtn}
        />

        {secondaryButtonText && onSecondaryPress ? (
          <AppButton
            title={secondaryButtonText}
            variant="outline"
            onPress={onSecondaryPress}
            testID={`${testID}-secondary-btn`}
            style={styles.secondaryBtn}
          />
        ) : null}
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#FFFFFF',
    justifyContent: 'space-between',
    paddingHorizontal: 24,
    paddingTop: 48,
    paddingBottom: 28,
  },
  topSection: {
    alignItems: 'center',
    paddingTop: 24,
  },
  heroWrap: {
    alignItems: 'center',
    justifyContent: 'center',
    marginBottom: 28,
  },
  heroImg: {
    width: 180,
    height: 180,
  },
  partyPopperContainer: {
    width: 140,
    height: 140,
    borderRadius: 70,
    backgroundColor: '#FFF1F2',
    alignItems: 'center',
    justifyContent: 'center',
    shadowColor: '#E7252B',
    shadowOffset: { width: 0, height: 6 },
    shadowOpacity: 0.15,
    shadowRadius: 16,
    elevation: 4,
  },
  popperCone: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  statusCircle: {
    width: 96,
    height: 96,
    borderRadius: 48,
    alignItems: 'center',
    justifyContent: 'center',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.08,
    shadowRadius: 8,
    elevation: 3,
  },
  statusSymbol: {
    fontSize: 44,
    fontWeight: '800',
  },
  title: {
    fontSize: 24,
    fontWeight: '800',
    textAlign: 'center',
    marginBottom: 14,
    letterSpacing: -0.4,
  },
  description: {
    fontSize: 15,
    color: '#4B5563',
    textAlign: 'center',
    lineHeight: 22,
    paddingHorizontal: 12,
  },
  customContent: {
    width: '100%',
    marginTop: 20,
  },
  bottomSection: {
    width: '100%',
    gap: 12,
  },
  primaryBtn: {
    width: '100%',
    height: 48,
    backgroundColor: '#E7252B',
  },
  secondaryBtn: {
    width: '100%',
    height: 48,
  },
});

