import React from 'react';
import { View, Text, TouchableOpacity, StyleSheet } from 'react-native';
import { AuthColors, AuthTypography } from '../../theme/tokens';

export interface AuthHeaderProps {
  title?: string;
  onBack?: () => void;
  showBack?: boolean;
  testID?: string;
}

export const AuthHeader: React.FC<AuthHeaderProps> = ({
  title,
  onBack,
  showBack = true,
  testID = 'auth-header',
}) => {
  return (
    <View testID={testID} style={styles.container}>
      {showBack ? (
        <TouchableOpacity
          testID={`${testID}-back-button`}
          style={styles.backButton}
          onPress={onBack}
          activeOpacity={0.7}
        >
          <View style={styles.chevron}>
            <View style={styles.chevronLineTop} />
            <View style={styles.chevronLineBottom} />
          </View>
        </TouchableOpacity>
      ) : (
        <View style={styles.backPlaceholder} />
      )}
      {title ? (
        <Text testID={`${testID}-title`} style={styles.title} numberOfLines={1}>
          {title}
        </Text>
      ) : null}
      <View style={styles.rightPlaceholder} />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    height: 52,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 16,
    backgroundColor: AuthColors.white,
    borderBottomWidth: 1,
    borderBottomColor: AuthColors.border,
  },
  backButton: {
    width: 36,
    height: 36,
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: 8,
  },
  backPlaceholder: {
    width: 36,
  },
  rightPlaceholder: {
    width: 36,
  },
  title: {
    ...AuthTypography.bodySemiBold,
    color: AuthColors.textPrimary,
    textAlign: 'center',
    flex: 1,
  },
  chevron: {
    width: 12,
    height: 20,
    justifyContent: 'center',
    alignItems: 'center',
  },
  chevronLineTop: {
    width: 10,
    height: 2,
    backgroundColor: AuthColors.textPrimary,
    transform: [{ rotate: '-45deg' }, { translateY: 3 }],
    borderRadius: 1,
  },
  chevronLineBottom: {
    width: 10,
    height: 2,
    backgroundColor: AuthColors.textPrimary,
    transform: [{ rotate: '45deg' }, { translateY: -3 }],
    borderRadius: 1,
  },
});
