import React, { useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  ScrollView,
  StyleSheet,
  ViewStyle,
} from 'react-native';

export interface TabItem {
  key: string;
  label: string;
  badgeCount?: number;
  icon?: string;
  content: React.ReactNode;
}

export interface AppTabsProps {
  tabs: TabItem[];
  initialActiveKey?: string;
  activeKey?: string;
  onTabChange?: (key: string) => void;
  scrollable?: boolean;
  variant?: 'underline' | 'pills' | 'segmented';
  containerStyle?: ViewStyle;
  tabBarStyle?: ViewStyle;
  contentContainerStyle?: ViewStyle;
  testID?: string;
}

/**
 * Enterprise Tab Bar with dynamic content container.
 * Supports:
 * - 'underline' standard header tab style with active indicator bar (GL-16, LO-001)
 * - 'pills' bubble filter tabs
 * - 'segmented' rounded card switcher
 * - Unread / item badge count bubbles
 * - Scrollable tab headers for multiple categories
 */
export const AppTabs: React.FC<AppTabsProps> = ({
  tabs,
  initialActiveKey,
  activeKey: controlledActiveKey,
  onTabChange,
  scrollable = false,
  variant = 'underline',
  containerStyle,
  tabBarStyle,
  contentContainerStyle,
  testID = 'app-tabs',
}) => {
  const [internalActiveKey, setInternalActiveKey] = useState<string>(
    initialActiveKey || (tabs.length > 0 ? tabs[0].key : '')
  );

  const activeKey = controlledActiveKey !== undefined ? controlledActiveKey : internalActiveKey;

  const handleTabPress = (key: string) => {
    if (controlledActiveKey === undefined) {
      setInternalActiveKey(key);
    }
    onTabChange?.(key);
  };

  const activeTab = tabs.find((t) => t.key === activeKey) || tabs[0];

  const renderTabBar = () => {
    const tabsContent = tabs.map((tab) => {
      const isActive = tab.key === activeKey;

      if (variant === 'pills') {
        return (
          <TouchableOpacity
            key={tab.key}
            testID={`${testID}-tab-${tab.key}`}
            style={[styles.pillItem, isActive && styles.pillItemActive]}
            onPress={() => handleTabPress(tab.key)}
            activeOpacity={0.7}
          >
            {tab.icon ? <Text style={styles.tabIcon}>{tab.icon}</Text> : null}
            <Text style={[styles.pillText, isActive && styles.pillTextActive]}>
              {tab.label}
            </Text>
            {tab.badgeCount !== undefined && tab.badgeCount > 0 ? (
              <View style={[styles.badge, isActive && styles.badgeActive]}>
                <Text style={styles.badgeText}>{tab.badgeCount}</Text>
              </View>
            ) : null}
          </TouchableOpacity>
        );
      }

      if (variant === 'segmented') {
        return (
          <TouchableOpacity
            key={tab.key}
            testID={`${testID}-tab-${tab.key}`}
            style={[styles.segmentedItem, isActive && styles.segmentedItemActive]}
            onPress={() => handleTabPress(tab.key)}
            activeOpacity={0.8}
          >
            <Text style={[styles.segmentedText, isActive && styles.segmentedTextActive]}>
              {tab.label}
            </Text>
          </TouchableOpacity>
        );
      }

      // Default: 'underline' tab
      return (
        <TouchableOpacity
          key={tab.key}
          testID={`${testID}-tab-${tab.key}`}
          style={[styles.underlineItem, isActive && styles.underlineItemActive]}
          onPress={() => handleTabPress(tab.key)}
          activeOpacity={0.7}
        >
          <View style={styles.tabLabelRow}>
            {tab.icon ? <Text style={styles.tabIcon}>{tab.icon}</Text> : null}
            <Text style={[styles.underlineText, isActive && styles.underlineTextActive]}>
              {tab.label}
            </Text>
            {tab.badgeCount !== undefined && tab.badgeCount > 0 ? (
              <View style={styles.badge}>
                <Text style={styles.badgeText}>{tab.badgeCount}</Text>
              </View>
            ) : null}
          </View>
          {isActive ? <View style={styles.activeIndicator} /> : null}
        </TouchableOpacity>
      );
    });

    if (scrollable) {
      return (
        <View style={[styles.scrollableWrapper, tabBarStyle]}>
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={styles.scrollableHeaderContainer}
          >
            {tabsContent}
          </ScrollView>
        </View>
      );
    }

    return (
      <View
        style={[
          variant === 'segmented' ? styles.segmentedContainer : styles.fixedHeaderContainer,
          tabBarStyle,
        ]}
      >
        {tabsContent}
      </View>
    );
  };

  return (
    <View style={[styles.container, containerStyle]} testID={testID}>
      {/* Header Bar */}
      {renderTabBar()}

      {/* Active Tab Content */}
      <View
        testID={`${testID}-content`}
        style={[styles.contentContainer, contentContainerStyle]}
      >
        {activeTab ? activeTab.content : null}
      </View>
    </View>
  );
};

