import React from 'react';
import {
  View,
  Text,
  ScrollView,
  TouchableOpacity,
  StyleSheet,
  ActivityIndicator,
  ViewStyle,
  Platform,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { DraftApplicationCard, DraftApplicationItem } from '../card/DraftApplicationCard';

export interface DraftApplicationsListViewProps {
  /**
   * Title shown in the header (default: "Draft applications").
   */
  title?: string;

  /**
   * List of draft applications.
   */
  drafts: DraftApplicationItem[];

  /**
   * Callback when a draft application card is tapped.
   */
  onSelectDraft: (item: DraftApplicationItem) => void;

  /**
   * Callback when back button in header is tapped.
   */
  onBack?: () => void;

  /**
   * Optional loading state while drafts are being fetched from local storage.
   */
  isLoading?: boolean;

  /**
   * Footer tip copy (default: "Tap an application to continue from where it stopped.").
   */
  footerTip?: string;

  /**
   * Empty state copy when no drafts exist.
   */
  emptyText?: string;

  style?: ViewStyle;
  testID?: string;
}

export const DraftApplicationsListView: React.FC<DraftApplicationsListViewProps> = ({
  title = 'Draft applications',
  drafts,
  onSelectDraft,
  onBack,
  isLoading = false,
  footerTip = 'Tap an application to continue from where it stopped.',
  emptyText = 'No draft applications saved.',
  style,
  testID = 'draft-applications-list',
}) => {
  return (
    <SafeAreaView testID={testID} style={[styles.safeArea, style]} edges={['top', 'left', 'right']}>
      {/* Top Header */}
      <View style={styles.header}>
        {onBack ? (
          <TouchableOpacity
            testID={`${testID}-back-btn`}
            onPress={onBack}
            style={styles.backButton}
            hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
            accessibilityRole="button"
            accessibilityLabel="Go back"
          >
            <Text style={styles.backArrow}>←</Text>
          </TouchableOpacity>
        ) : (
          <View style={styles.backButtonPlaceholder} />
        )}
        <Text testID={`${testID}-title`} style={styles.headerTitle}>
          {title}
        </Text>
      </View>

      {/* Main Content Area */}
      {isLoading ? (
        <View style={styles.loadingContainer}>
          <ActivityIndicator size="large" color="#D3141B" />
        </View>
      ) : drafts.length === 0 ? (
        <View style={styles.emptyContainer}>
          <Text style={styles.emptyText}>{emptyText}</Text>
        </View>
      ) : (
        <ScrollView
          style={styles.scrollArea}
          contentContainerStyle={styles.scrollContent}
          showsVerticalScrollIndicator={false}
        >
          {drafts.map((draft, idx) => (
            <DraftApplicationCard
              key={draft.id || `draft-${idx}`}
              item={draft}
              onPress={onSelectDraft}
              testID={`${testID}-card-${idx}`}
            />
          ))}

          {/* Bottom helper footnote */}
          {footerTip ? (
            <View style={styles.footerTipWrapper}>
              <Text testID={`${testID}-footer-tip`} style={styles.footerTipText}>
                {footerTip}
              </Text>
            </View>
          ) : null}
        </ScrollView>
      )}
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
    backgroundColor: '#F9FAFB',
  },
  header: {
    height: 52,
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 16,
    backgroundColor: '#FFFFFF',
    borderBottomWidth: 1,
    borderBottomColor: '#F3F4F6',
  },
  backButton: {
    width: 36,
    height: 36,
    alignItems: 'center',
    justifyContent: 'center',
    marginRight: 8,
  },
  backButtonPlaceholder: {
    width: 12,
  },
  backArrow: {
    fontSize: 22,
    color: '#16181D',
    fontWeight: '600',
  },
  headerTitle: {
    fontSize: 18,
    lineHeight: 24,
    fontWeight: '700',
    color: '#16181D',
    ...Platform.select({
      ios: { fontFamily: 'Pretendard-Bold' },
      android: { fontFamily: 'Pretendard-Bold' },
    }),
  },
  scrollArea: {
    flex: 1,
  },
  scrollContent: {
    padding: 16,
    paddingBottom: 32,
  },
  loadingContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
  },
  emptyContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    paddingHorizontal: 24,
  },
  emptyText: {
    fontSize: 14,
    color: '#9CA3AF',
    textAlign: 'center',
  },
  footerTipWrapper: {
    marginTop: 16,
    marginBottom: 8,
    alignItems: 'center',
    justifyContent: 'center',
  },
  footerTipText: {
    fontSize: 13,
    color: '#6B7280',
    textAlign: 'center',
    ...Platform.select({
      ios: { fontFamily: 'Pretendard-Regular' },
      android: { fontFamily: 'Pretendard-Regular' },
    }),
  },
});
