import React, { useRef, useState, useEffect } from 'react';
import {
  View,
  Text,
  ScrollView,
  TouchableOpacity,
  StyleSheet,
  Dimensions,
  NativeSyntheticEvent,
  NativeScrollEvent,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export interface PromoBannerItem {
  id: string;
  badge?: string;
  title: string;
  subtitle: string;
  ctaText?: string;
  onPress?: () => void;
  backgroundColor?: string;
}

export interface PromoBannerCarouselProps {
  banners: PromoBannerItem[];
  autoPlayIntervalMs?: number; // e.g. 5000 for 5 seconds
  testID?: string;
}

/**
 * Promotional Banner Carousel matching ML-BAN-001 / Carousel sections in Lotte Digital Channels.
 * Provides smooth horizontal pagination, active dot indicators, and optional auto-play.
 */
export const PromoBannerCarousel: React.FC<PromoBannerCarouselProps> = ({
  banners,
  autoPlayIntervalMs = 0,
  testID = 'promo-banner-carousel',
}) => {
  const { theme } = useTheme();
  const [activeIndex, setActiveIndex] = useState(0);
  const scrollRef = useRef<ScrollView>(null);
  const screenWidth = Dimensions.get('window').width;
  const cardWidth = Math.min(360, screenWidth - 32);

  // Auto-play timer
  useEffect(() => {
    if (autoPlayIntervalMs <= 0 || banners.length <= 1) return;

    const timer = setInterval(() => {
      setActiveIndex((prev) => {
        const next = (prev + 1) % banners.length;
        scrollRef.current?.scrollTo({ x: next * (cardWidth + 12), animated: true });
        return next;
      });
    }, autoPlayIntervalMs);

    return () => clearInterval(timer);
  }, [autoPlayIntervalMs, banners.length, cardWidth]);

  const handleScroll = (e: NativeSyntheticEvent<NativeScrollEvent>) => {
    const offsetX = e.nativeEvent.contentOffset.x;
    const index = Math.round(offsetX / (cardWidth + 12));
    if (index >= 0 && index < banners.length && index !== activeIndex) {
      setActiveIndex(index);
    }
  };

  return (
    <View testID={testID} style={styles.container}>
      <ScrollView
        ref={scrollRef}
        horizontal
        pagingEnabled={false}
        snapToInterval={cardWidth + 12}
        decelerationRate="fast"
        showsHorizontalScrollIndicator={false}
        contentContainerStyle={styles.scrollContent}
        onMomentumScrollEnd={handleScroll}
      >
        {banners.map((item, idx) => (
          <TouchableOpacity
            key={item.id}
            testID={`${testID}-banner-${idx}`}
            activeOpacity={0.85}
            onPress={item.onPress}
            style={[
              styles.card,
              {
                width: cardWidth,
                backgroundColor: item.backgroundColor || theme.colors.primary || '#E7252B',
              },
            ]}
          >
            {item.badge ? (
              <View style={styles.badgeWrapper}>
                <Text style={styles.badgeText}>{item.badge}</Text>
              </View>
            ) : null}
            <Text style={styles.title}>{item.title}</Text>
            <Text style={styles.subtitle}>{item.subtitle}</Text>
            {item.ctaText ? (
              <View style={styles.ctaWrapper}>
                <Text style={styles.ctaText}>{item.ctaText} →</Text>
              </View>
            ) : null}
          </TouchableOpacity>
        ))}
      </ScrollView>

      {/* Dot Indicators */}
      {banners.length > 1 && (
        <View style={styles.dotsRow}>
          {banners.map((_, dotIdx) => (
            <View
              key={`dot-${dotIdx}`}
              style={[
                styles.dot,
                dotIdx === activeIndex
                  ? [styles.activeDot, { backgroundColor: theme.colors.primary }]
                  : styles.inactiveDot,
              ]}
            />
          ))}
        </View>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    width: '100%',
    marginVertical: 10,
  },
  scrollContent: {
    paddingHorizontal: 16,
    gap: 12,
  },
  card: {
    borderRadius: 14,
    padding: 16,
    minHeight: 120,
    justifyContent: 'space-between',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 2,
  },
  badgeWrapper: {
    alignSelf: 'flex-start',
    backgroundColor: 'rgba(255, 255, 255, 0.25)',
    paddingHorizontal: 8,
    paddingVertical: 3,
    borderRadius: 12,
    marginBottom: 6,
  },
  badgeText: {
    color: '#FFFFFF',
    fontSize: 11,
    fontWeight: '700',
    textTransform: 'uppercase',
  },
  title: {
    color: '#FFFFFF',
    fontSize: 16,
    fontWeight: '800',
    marginBottom: 4,
  },
  subtitle: {
    color: 'rgba(255, 255, 255, 0.85)',
    fontSize: 12,
    lineHeight: 16,
  },
  ctaWrapper: {
    alignSelf: 'flex-end',
    marginTop: 8,
  },
  ctaText: {
    color: '#FFFFFF',
    fontSize: 12,
    fontWeight: '700',
    textDecorationLine: 'underline',
  },
  dotsRow: {
    flexDirection: 'row',
    justifyContent: 'center',
    alignItems: 'center',
    marginTop: 8,
    gap: 6,
  },
  dot: {
    height: 6,
    borderRadius: 3,
  },
  activeDot: {
    width: 18,
  },
  inactiveDot: {
    width: 6,
    backgroundColor: '#D1D5DB',
  },
});

