import React, { useState } from 'react';
import { View, Text, StyleSheet } from 'react-native';
import {
  AppCard,
  AppButton,
  RadioGroup,
  Checkbox,
  CheckboxGroup,
  SelectionItem,
  SelectionGroup,
  SearchFilterDrawer,
  ToggleSwitch,
  SegmentedControl,
  SearchableFilterBottomSheet,
  DropdownList,
  DropdownListItem,
} from '@mfe/ui-components/components';
import { CodeBlock } from '../../components/CodeBlock';
import { CODE_SNIPPETS } from '../../constants/codeSnippets';

export interface SelectionDetailSectionProps {
  agreeTerms?: boolean;
  biometricEnabled?: boolean;
  onToggleTerms?: () => void;
  onToggleBiometric?: () => void;
  activeSegment?: 'SIMULATION' | 'COMPONENTS' | 'APPLICATIONS';
  onSegmentChange?: (segment: any) => void;
  // Optional backwards compatibility
  scheme?: 'CASH' | 'CAR' | 'DURABLE';
  onSchemeChange?: (scheme: 'CASH' | 'CAR' | 'DURABLE') => void;
  tenure?: number;
  onTenureChange?: (tenure: number) => void;
  onBiometricChange?: (enabled: boolean) => void;
  onAgreeTermsChange?: (agreed: boolean) => void;
}

export const SelectionDetailSection: React.FC<SelectionDetailSectionProps> = ({
  agreeTerms = true,
  biometricEnabled = false,
  onToggleTerms,
  onToggleBiometric,
  activeSegment = 'COMPONENTS',
  onSegmentChange,
  scheme = 'CASH',
  onSchemeChange,
  tenure = 12,
  onTenureChange,
}) => {
  // 6. Searchable Filter BottomSheet state matching Screenshot
  const [filterSheetVisible, setFilterSheetVisible] = useState(false);
  const [selectedEmployer, setSelectedEmployer] = useState('wayne');

  // DropdownList states
  const [selectedProduct, setSelectedProduct] = useState<string>('personal');
  const [multiProducts, setMultiProducts] = useState<string[]>(['personal', 'auto']);

  const productOptions: DropdownListItem<string>[] = [
    { value: 'personal', label: 'Personal Consumer Loan', subtitle: 'Unsecured financing up to $10,000' },
    { value: 'mortgage', label: 'Residential Mortgage', subtitle: 'Long term home financing' },
    { value: 'auto', label: 'Automotive Financing', badge: 'Hot' },
    { value: 'sme', label: 'SME Business Credit Line', disabled: true, subtitle: 'Currently unavailable' },
  ];

  const employerOptions = [
    { label: 'Khác', value: 'other' },
    { label: 'Công ty TNHH ABC', value: 'abc' },
    { label: 'Globex Corp', value: 'globex' },
    { label: 'Wayne Enterprises', value: 'wayne' },
    { label: 'Stark Industries', value: 'stark' },
    { label: 'Oscorp', value: 'oscorp' },
    { label: 'Cyberdyne Systems', value: 'cyberdyne' },
    { label: 'Umbrella Corp', value: 'umbrella' },
    { label: 'Initech', value: 'initech' },
  ];
  const [singleChecked, setSingleChecked] = useState(true);
  const [brandChecked, setBrandChecked] = useState(false);

  // 2. Group Checkbox state matching Screenshot
  const [selectedSources, setSelectedSources] = useState<string[]>(['TASCO']);
  const [selectedStatus, setSelectedStatus] = useState<string[]>([]);
  const [selectedSteps, setSelectedSteps] = useState<string[]>(['DATA_ENTRY', 'SCORING']);

  // 3. SelectionGroup single & multi states
  const [singleSelection, setSingleSelection] = useState<string>('TASCO');
  const [multiPillSelection, setMultiPillSelection] = useState<string[]>(['TASCO', 'LFVN']);

  // 4. Search Filter Drawer modal state (Full filter screen matching screenshot)
  const [filterDrawerVisible, setFilterDrawerVisible] = useState(false);
  const [drawerFilters, setDrawerFilters] = useState<Record<string, string[]>>({
    source: ['TASCO'],
    status: [],
    process_step: [],
    time_period: ['TODAY'],
  });

  return (
    <View testID="detail-selection">
      <CodeBlock
        code={CODE_SNIPPETS.SELECTION}
        title="Checkbox, Selection & Filter Groups Usage"
      />

      {/* 1. SCREENSHOT DEMO: SearchFilterDrawer Trigger */}
      <AppCard>
        <Text style={styles.detailHeader}>1. Search Filter Drawer (Bộ lọc tìm kiếm)</Text>
        <Text style={styles.helperText}>
          Full-screen filter modal matching the uploaded design with red funnel headers, 2-column checkboxes, category reset actions, and bottom buttons.
        </Text>
        <AppButton
          title="Open 'Bộ lọc tìm kiếm' Filter Drawer"
          variant="primary"
          onPress={() => setFilterDrawerVisible(true)}
          testID="open-filter-drawer-btn"
        />
        <Text style={styles.stateNotice}>
          Active Drawer Filters: {JSON.stringify(drawerFilters)}
        </Text>
      </AppCard>

      {/* 2. CHECKBOX GROUP (Matching Screenshot In-line) */}
      <AppCard>
        <Text style={styles.detailHeader}>2. CheckboxGroup (Nguồn hồ sơ &amp; Bước xử lý)</Text>
        <Text style={styles.helperText}>
          Displays a section header with red filter funnel icon, dismissal clear action (✕), and a responsive 2-column checkbox layout.
        </Text>

        {/* Nguồn hồ sơ (2 Columns) */}
        <CheckboxGroup
          title="Nguồn hồ sơ"
          showFilterIcon={true}
          columns={2}
          options={[
            { label: 'TASCO', value: 'TASCO' },
            { label: 'LFVN', value: 'LFVN' },
            { label: 'VINFAST', value: 'VINFAST' },
            { label: 'THACO', value: 'THACO' },
          ]}
          selectedValues={selectedSources}
          onChange={setSelectedSources}
          onClear={() => setSelectedSources([])}
          testID="group-nguon-ho-so"
        />

        <View style={styles.divider} />

        {/* Trạng thái (2 Columns) */}
        <CheckboxGroup
          title="Trạng thái"
          showFilterIcon={true}
          columns={2}
          options={[
            { label: 'Open', value: 'OPEN' },
            { label: 'Close', value: 'CLOSE' },
          ]}
          selectedValues={selectedStatus}
          onChange={setSelectedStatus}
          onClear={() => setSelectedStatus([])}
          testID="group-trang-thai"
        />

        <View style={styles.divider} />

        {/* Bước xử lý (2 Columns) */}
        <CheckboxGroup
          title="Bước xử lý"
          showFilterIcon={true}
          columns={2}
          options={[
            { label: 'Data Entry', value: 'DATA_ENTRY' },
            { label: 'Precheck', value: 'PRECHECK' },
            { label: 'Scoring', value: 'SCORING' },
            { label: 'Review', value: 'REVIEW' },
            { label: 'Upload Document', value: 'UPLOAD_DOCUMENT' },
            { label: 'Account Entry', value: 'ACCOUNT_ENTRY' },
            { label: 'Sign', value: 'SIGN' },
            { label: 'Operation', value: 'OPERATION' },
            { label: 'Disbursement', value: 'DISBURSEMENT' },
          ]}
          selectedValues={selectedSteps}
          onChange={setSelectedSteps}
          onClear={() => setSelectedSteps([])}
          testID="group-buoc-xu-ly"
        />
      </AppCard>

      {/* 3. INDIVIDUAL CHECKBOX (Variants & Sizes) */}
      <AppCard>
        <Text style={styles.detailHeader}>3. Checkbox Component (Sizes &amp; Variants)</Text>
        <Text style={styles.helperText}>
          Accessible, customizable checkbox supporting &apos;primary&apos; (royal blue), &apos;brand&apos; (Lotte red), &apos;success&apos; (emerald green), and sizes.
        </Text>

        <Checkbox
          label="Royal Blue Checkbox (Medium - Default)"
          checked={singleChecked}
          onToggle={setSingleChecked}
          variant="primary"
          testID="checkbox-primary"
        />

        <Checkbox
          label="Lotte Brand Red Checkbox (Large)"
          subtitle="Special terms of service agreement"
          checked={brandChecked}
          onToggle={setBrandChecked}
          variant="brand"
          size="large"
          testID="checkbox-brand"
        />

        <Checkbox
          label="Disabled Checked Box"
          checked={true}
          disabled={true}
          onToggle={() => {}}
          testID="checkbox-disabled"
        />
      </AppCard>

      {/* 4. SELECTION GROUP & SELECTION ITEM */}
      <AppCard>
        <Text style={styles.detailHeader}>4. SelectionGroup (Single Radio vs Multi Checkbox)</Text>
        <Text style={styles.helperText}>
          Unified selector component handling Radio, Checkbox, and Pill tag layouts.
        </Text>

        <Text style={styles.subHeader}>Single Selection (Radio Mode):</Text>
        <SelectionGroup
          options={[
            { label: 'TASCO Automobile Finance', value: 'TASCO', badge: 'Preferred' },
            { label: 'LFVN Consumer Credit', value: 'LFVN' },
            { label: 'THACO Commercial Line', value: 'THACO' },
          ]}
          selectedValue={singleSelection}
          onSelect={setSingleSelection}
          type="radio"
          testID="selection-group-radio"
        />

        <Text style={[styles.subHeader, { marginTop: 14 }]}>Multi Selection (Pill Filter Mode):</Text>
        <SelectionGroup
          layout="wrap"
          type="pill"
          multiSelect
          options={[
            { label: 'TASCO', value: 'TASCO' },
            { label: 'LFVN', value: 'LFVN' },
            { label: 'VINFAST', value: 'VINFAST' },
            { label: 'THACO', value: 'THACO' },
            { label: 'HYUNDAI', value: 'HYUNDAI' },
          ]}
          selectedValues={multiPillSelection}
          onChange={setMultiPillSelection}
          testID="selection-group-pills"
        />
      </AppCard>

      {/* 5. SEGMENTED CONTROL & TOGGLE SWITCH */}
      <AppCard>
        <Text style={styles.detailHeader}>5. SegmentedControl &amp; ToggleSwitch</Text>
        <SegmentedControl
          items={[
            { label: 'Cash Loan', value: 'CASH' },
            { label: 'Auto Finance', value: 'CAR' },
            { label: 'Durable Goods', value: 'DURABLE' },
          ]}
          selectedValue={scheme}
          onSelect={(val) => onSchemeChange?.(val as any)}
          testID="segment-demo"
        />

        <View style={{ height: 16 }} />

        <ToggleSwitch
          label="Biometric Authentication"
          description="Authenticate via fingerprint or Face ID"
          value={biometricEnabled}
          onValueChange={() => onToggleBiometric?.()}
          testID="toggle-demo"
        />
      </AppCard>

      {/* 6. SearchFilterDrawer Modal */}
      <SearchFilterDrawer
        visible={filterDrawerVisible}
        onClose={() => setFilterDrawerVisible(false)}
        selectedFilters={drawerFilters}
        onFilterChange={(catId, vals) => {
          setDrawerFilters((prev) => ({ ...prev, [catId]: vals }));
        }}
        onClearCategory={(catId) => {
          setDrawerFilters((prev) => ({ ...prev, [catId]: [] }));
        }}
        onResetAll={() => {
          setDrawerFilters({
            source: [],
            status: [],
            process_step: [],
            time_period: [],
          });
        }}
        testID="demo-filter-drawer"
      />

      {/* 6. Searchable Selection BottomSheet matching Screenshot */}
      <AppCard>
        <Text style={styles.detailHeader}>Searchable Selection BottomSheet (Tên cơ quan/ nơi làm việc)</Text>
        <Text style={styles.helperText}>
          Faithfully matches screenshot with bottom sheet container, real-time search filtering, radio selection circles, and scrollable company list.
        </Text>
        <View style={{ marginBottom: 10 }}>
          <Text style={styles.stateNotice}>
            Đang chọn:{' '}
            <Text style={{ fontWeight: '700', color: '#16181D' }}>
              {employerOptions.find((e) => e.value === selectedEmployer)?.label || 'Chưa chọn'}
            </Text>
          </Text>
        </View>
        <AppButton
          title="Mở chọn Tên cơ quan/ nơi làm việc"
          variant="primary"
          size="medium"
          onPress={() => setFilterSheetVisible(true)}
          testID="open-employer-sheet-btn"
        />
      </AppCard>

      {/* 7. DropdownList Component (Inline, Searchable, Clearable & Multi-Select) */}
      <AppCard>
        <Text style={styles.detailHeader}>7. DropdownList Component</Text>
        <Text style={styles.helperText}>
          Inline or popover dropdown list with search filtering, subtitles, clear buttons, badges, and multi-select support:
        </Text>

        <View style={{ gap: 14 }}>
          {/* Single Select with Search & Clear */}
          <DropdownList
            label="Loan Product (Single Select & Searchable)"
            placeholder="Select loan product"
            options={productOptions}
            value={selectedProduct}
            onChange={(val) => setSelectedProduct(val)}
            searchable
            clearable
            testID="demo-dropdown-single"
          />

          {/* Multi-Select Dropdown */}
          <DropdownList
            label="Allowed Products (Multi-Select)"
            placeholder="Select multiple products"
            options={productOptions}
            value={multiProducts}
            multiple
            onMultiChange={(vals) => setMultiProducts(vals)}
            clearable
            testID="demo-dropdown-multi"
          />
        </View>
      </AppCard>

      <SearchableFilterBottomSheet
        visible={filterSheetVisible}
        title="Tên cơ quan/ nơi làm việc"
        searchPlaceholder="Nhập tên tên cơ quan/ nơi làm việc"
        options={employerOptions}
        selectedValue={selectedEmployer}
        onSelect={(val) => setSelectedEmployer(val)}
        onClose={() => setFilterSheetVisible(false)}
        allowCustomInput={true}
        testID="demo-employer-filter-sheet"
      />
    </View>
  );
};

const styles = StyleSheet.create({
  detailHeader: {
    fontSize: 16,
    fontWeight: '700',
    color: '#16181D',
    marginBottom: 6,
  },
  subHeader: {
    fontSize: 13,
    fontWeight: '600',
    color: '#374151',
    marginBottom: 6,
  },
  helperText: {
    fontSize: 13,
    color: '#4D5563',
    lineHeight: 18,
    marginBottom: 12,
  },
  stateNotice: {
    fontSize: 12,
    color: '#6B7280',
    marginTop: 8,
  },
  divider: {
    height: 1,
    backgroundColor: '#F3F4F6',
    marginVertical: 12,
  },
});
