import { Platform } from 'react-native';
import {
  downloadFile,
  extractZipFile,
  addFileTransferProgressListener,
  type BizmobEventSubscription,
} from 'react-native-bizmob-plugin';

export interface RemoteVersionItem {
  remote_id: string;
  current_version: string;
}

export interface RemoteUpdateItem {
  remote_id: string;
  update_available: boolean;
  content_type?: 'MAJOR' | 'PATCH' | 'MINOR';
  target_version?: string;
  file_name?: string;
  file_url?: string;
  file_size?: number;
  checksum_sha256?: string;
  force_update?: 'Y' | 'N';
  description?: string;
}

export interface ContentUpdateCheckResponse {
  header: {
    result: boolean;
    error_code: string;
    error_text: string;
    info_text?: string;
    message_version?: string;
  };
  body: {
    has_updates?: boolean;
    content_result?: boolean;
    total_download_size?: number;
    force_update_flag?: string;
    content_filename?: string;
    content_major_version?: string;
    content_minor_version?: string;
    updates?: RemoteUpdateItem[];
  };
}

export interface OTAProgressCallback {
  (progress: {
    percentage: number;
    statusText: string;
    remoteId?: string;
    isComplete?: boolean;
    error?: string | null;
  }): void;
}

export class ContentUpdateService {
  private static readonly UPDATE_CHECK_URL =
    'https://kh-mcnc-001.mcnc.com.kh/contents/api/update-check';
  private static readonly DOWNLOAD_BASE_URL =
    'https://kh-mcnc-001.mcnc.com.kh/contents/api/download';

  private static inMemoryManifest: RemoteVersionItem[] = [
    { remote_id: 'core_shell', current_version: '1.0.0' },
    { remote_id: 'remote_launch_auth', current_version: '1.0.0' },
    { remote_id: 'remote_loan_origination', current_version: '1.0.0' },
    { remote_id: 'remote_dashboard', current_version: '1.0.0' },
    { remote_id: 'remote_customer', current_version: '1.0.0' },
    { remote_id: 'remote_notification', current_version: '1.0.0' },
  ];

  /**
   * Retrieves installed versions for all remotes.
   */
  public static async getInstalledVersions(): Promise<RemoteVersionItem[]> {
    return [...this.inMemoryManifest];
  }

  /**
   * Checks the custom server (kh-mcnc-001) for updates.
   * Supports both legacy single-bundle and multi-remote contracts with fallback.
   */
  public static async checkForUpdates(
    remotes: RemoteVersionItem[]
  ): Promise<RemoteUpdateItem[]> {
    try {
      const response = await fetch(this.UPDATE_CHECK_URL, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Accept: 'application/json',
        },
        body: JSON.stringify({
          header: {
            result: true,
            error_code: '',
            error_text: '',
            message_version: '2.0.0',
          },
          body: {
            app_key: Platform.OS === 'android' ? 'REACTAN0' : 'REACTIOS0',
            os_type: Platform.OS === 'android' ? 'Android' : 'iOS',
            app_major_version: 1,
            app_minor_version: 0,
            app_build_version: 0,
            content_major_version: 0,
            content_minor_version: 0,
            app_tester: false,
            remotes,
          },
        }),
      });

      if (!response.ok) {
        throw new Error(`Server returned HTTP ${response.status}`);
      }

      const data: ContentUpdateCheckResponse = await response.json();

      // Case 1: Multi-remote API updates array
      if (data.body?.updates && Array.isArray(data.body.updates)) {
        return data.body.updates.filter((u) => u.update_available);
      }

      // Case 2: Legacy single-bundle response (REACTAN0.content.2.7_0.zip)
      if (data.body?.content_result && data.body?.content_filename) {
        return [
          {
            remote_id: 'all_remotes',
            update_available: true,
            content_type: 'MAJOR',
            target_version: `${data.body.content_major_version || 2}.${data.body.content_minor_version || 7}`,
            file_name: data.body.content_filename,
            file_url: `${this.DOWNLOAD_BASE_URL}/${data.body.content_filename}`,
            description: 'Core content and remote bundles package',
          },
        ];
      }

      return [];
    } catch (error) {
      console.warn('[OTA] Update check failed, fallback to local bundle:', error);
      return [];
    }
  }

  /**
   * Downloads and extracts updates with real-time progress callbacks.
   */
  public static async downloadAndApplyUpdates(
    updates: RemoteUpdateItem[],
    onProgress: OTAProgressCallback
  ): Promise<boolean> {
    if (updates.length === 0) {
      onProgress({
        percentage: 100,
        statusText: 'All contents up to date.',
        isComplete: true,
      });
      return true;
    }

    const totalSteps = updates.length;

    for (let index = 0; index < totalSteps; index++) {
      const item = updates[index];
      const remoteLabel = item.remote_id.replace(/_/g, '-');
      const startPercent = (index / totalSteps) * 100;
      const endPercent = ((index + 1) / totalSteps) * 100;

      onProgress({
        percentage: startPercent + 5,
        statusText: `Downloading ${remoteLabel} (${index + 1}/${totalSteps})...`,
        remoteId: item.remote_id,
        isComplete: false,
      });

      // 1. Subscribe to bizMOB Native File Transfer Progress (if available)
      let progressSub: BizmobEventSubscription | null = null;
      try {
        progressSub = addFileTransferProgressListener((event) => {
          if (event && event.totalBytes > 0) {
            const fileFraction = event.bytesTransferred / event.totalBytes;
            const currentTotalPercent =
              startPercent + fileFraction * (endPercent - startPercent) * 0.8;
            onProgress({
              percentage: Math.min(95, currentTotalPercent),
              statusText: `Downloading ${remoteLabel} (${Math.round(fileFraction * 100)}%)...`,
              remoteId: item.remote_id,
              isComplete: false,
            });
          }
        });
      } catch {
        // Native event listener fallback
      }

      try {
        // 2. Download file via BizMOB native downloadFile plugin
        const downloadUrl =
          item.file_url || `${this.DOWNLOAD_BASE_URL}/${item.file_name}`;

        await downloadFile({
          url: downloadUrl,
          file_name: item.file_name || `${item.remote_id}.zip`,
          target_path: `mfe_downloads/${item.file_name}`,
          directory: 'document',
        });

        // 3. Extract downloaded ZIP archive to internal document storage
        onProgress({
          percentage: endPercent - 5,
          statusText: `Extracting ${remoteLabel}...`,
          remoteId: item.remote_id,
          isComplete: false,
        });

        await extractZipFile({
          source_path: `mfe_downloads/${item.file_name}`,
          source_path_type: 'document',
          target_directory: `mfe_contents/${item.remote_id}`,
          target_directory_type: 'document',
        });

        // Update in-memory manifest
        const found = this.inMemoryManifest.find(
          (m) => m.remote_id === item.remote_id
        );
        if (found && item.target_version) {
          found.current_version = item.target_version;
        }
      } catch (extractError) {
        console.warn(
          `[OTA] Failed to process bundle for ${item.remote_id}:`,
          extractError
        );
      } finally {
        if (progressSub) {
          try {
            progressSub.remove();
          } catch {}
        }
      }
    }

    onProgress({
      percentage: 100,
      statusText: 'Updating Complete! Launching...',
      isComplete: true,
    });

    return true;
  }
}
