import { useState, useCallback, useEffect } from 'react';
import { IAuthService, AuthService } from '../services/AuthService';
import { AuthValidator } from '../models/AuthModel';

export interface UseOtpViewModelProps {
  authService?: IAuthService;
  userId?: string;
  userEmail?: string;
  userPhone?: string;
  initialCountdown?: number;
  onOtpVerified?: (token?: string) => void;
  onResendOtp?: () => void;
  onBack?: () => void;
}

export const useOtpViewModel = ({
  authService = new AuthService(),
  userId = 'user@example.com',
  userEmail = 'uy.***@gmail.com',
  userPhone = '087****96',
  initialCountdown = 60,
  onOtpVerified,
  onBack,
}: UseOtpViewModelProps = {}) => {
  const [channel, setChannel] = useState<'email' | 'sms' | 'admin'>('email');
  const [otpCode, setOtpCode] = useState(['', '', '', '', '', '']);
  const [countdown, setCountdown] = useState(initialCountdown);
  const [canResend, setCanResend] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [infoMessage, setInfoMessage] = useState<string | null>(null);

  // Timer countdown effect
  useEffect(() => {
    let timer: any = null;
    if (countdown > 0) {
      timer = setInterval(() => {
        setCountdown((prev) => prev - 1);
      }, 1000);
    } else {
      setCanResend(true);
    }
    return () => {
      if (timer) clearInterval(timer);
    };
  }, [countdown]);

  const handleDigitChange = useCallback(
    (index: number, value: string) => {
      const sanitized = value.replace(/[^0-9]/g, '').slice(-1);
      setOtpCode((prev) => {
        const next = [...prev];
        next[index] = sanitized;
        return next;
      });
      setErrorMessage(null);
    },
    []
  );

  const requestNewCode = useCallback(async () => {
    if (!canResend && countdown > 0) return;
    setIsLoading(true);
    setErrorMessage(null);
    try {
      const res = await authService.requestOtp(userId, channel);
      if (res.success) {
        setCountdown(60);
        setCanResend(false);
        setOtpCode(['', '', '', '', '', '']);
        setInfoMessage(res.message);
      }
    } catch (err: any) {
      setErrorMessage(err?.message || 'Failed to request new OTP code.');
    } finally {
      setIsLoading(false);
    }
  }, [authService, canResend, countdown, userId, channel]);

  const submitOtp = useCallback(async () => {
    const fullCode = otpCode.join('');
    const validation = AuthValidator.validateOtpCode(fullCode);
    if (!validation.isValid) {
      setErrorMessage(validation.error || 'Please enter all 6 digits of the OTP.');
      return;
    }

    setIsLoading(true);
    setErrorMessage(null);
    try {
      const res = await authService.verifyOtp({
        userId,
        otpCode: fullCode,
        channel,
      });

      if (!res.success) {
        setErrorMessage(res.errorMessage || 'Invalid verification code.');
      } else {
        if (onOtpVerified) {
          onOtpVerified(res.token);
        }
      }
    } catch (err: any) {
      setErrorMessage(err?.message || 'Failed to verify OTP.');
    } finally {
      setIsLoading(false);
    }
  }, [authService, otpCode, userId, channel, onOtpVerified]);

  return {
    channel,
    otpCode,
    countdown,
    canResend,
    isLoading,
    errorMessage,
    infoMessage,
    userEmail,
    userPhone,
    setChannel,
    handleDigitChange,
    requestNewCode,
    submitOtp,
    onBack,
  };
};
