import React from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
  Animated,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export type SliverAppBarVariant =
  | 'lotte-brand-red' // Rich curved red wave header matching Lotte Digital Finance (AU-002/AU-003)
  | 'clean-minimal'   // Clean white/light surface with subtle border
  | 'navy-gradient'   // Deep enterprise midnight blue / sapphire gradient
  | 'curved-sheet'    // Overlapping rounded white sheet sliding up
  | 'emerald-wealth'  // Wealth & prosperity emerald gradient
  | 'dark-elevation'; // Dark mode elevated slate surface

export interface SliverAppBarAction {
  key: string;
  icon: (color: string) => React.ReactNode;
  onPress: () => void;
  badgeCount?: number;
  accessibilityLabel?: string;
}

export interface AndroidSliverAppBarProps {
  title: string;
  subtitle?: string;
  /**
   * Visual theme variant. Defaults to 'clean-minimal' for backwards compatibility.
   * Use 'lotte-brand-red' for the authentic Lotte Finance curved red wave header.
   */
  variant?: SliverAppBarVariant;
  /**
   * Brand / Top logo text (e.g. 'LOTTE FINANCE' in all caps)
   */
  brandLogoText?: string;
  /**
   * Greeting / Top headline (e.g. 'Welcome to,')
   */
  welcomeText?: string;
  /**
   * Bold Hero highlight title (e.g. 'LOTTE FINANCE Digital Finance')
   */
  heroTitle?: string;
  expandedHeight?: number; // e.g. 180 or 240
  collapsedHeight?: number; // e.g. 56 or 60
  scrollY?: Animated.Value;
  onBackPress?: () => void;
  rightAction?: React.ReactNode;
  /**
   * Action buttons displayed in the app bar top row (e.g. search, notification, filter)
   */
  actions?: SliverAppBarAction[];
  heroContent?: React.ReactNode;
  /**
   * Optional Avatar configuration for collapsing avatar (e.g., Profile picture in Hero)
   * Animates smoothly in size and translation from expanded hero to collapsed top navbar
   */
  avatar?: {
    source?: any;
    name?: string;
    expandedSize?: number; // default 52
    collapsedSize?: number; // default 34
    onPress?: () => void;
  };
  style?: ViewStyle;
  testID?: string;
}

export const AndroidSliverAppBar: React.FC<AndroidSliverAppBarProps> = ({
  title,
  subtitle,
  variant = 'clean-minimal',
  brandLogoText,
  welcomeText,
  heroTitle,
  expandedHeight = 160,
  collapsedHeight = 56,
  scrollY,
  onBackPress,
  rightAction,
  actions = [],
  heroContent,
  avatar,
  style,
  testID = 'android-sliver-app-bar',
}) => {
  const { theme } = useTheme();

  const effectiveExpandedHeight = expandedHeight;
  const effectiveCollapsedHeight = collapsedHeight;
  const scrollRange = Math.max(1, effectiveExpandedHeight - effectiveCollapsedHeight);

  // Animated interpolations if scrollY is provided
  const headerHeight = scrollY
    ? scrollY.interpolate({
        inputRange: [0, scrollRange],
        outputRange: [effectiveExpandedHeight, effectiveCollapsedHeight],
        extrapolate: 'clamp',
      })
    : effectiveExpandedHeight;

  // Linear, continuous cross-fade for seamless slow scrolling:
  // As the user scrolls up, expanded hero content smoothly dims from 1.0 to 0.0 across 0 -> 60% of the scroll range.
  const contentOpacity = scrollY
    ? scrollY.interpolate({
        inputRange: [0, scrollRange * 0.6],
        outputRange: [1, 0],
        extrapolate: 'clamp',
      })
    : 1;

  // Gentle, continuous upward translation proportional to scroll distance without sudden jumps
  const contentTranslateY = scrollY
    ? scrollY.interpolate({
        inputRange: [0, scrollRange * 0.6],
        outputRange: [0, -16],
        extrapolate: 'clamp',
      })
    : 0;

  // Collapsed title starts gradually fading in at 40% and reaches full opacity at 85% of scrollRange
  // eliminating any "dead-zone" gap where the bar looks empty when scrolling slowly
  const collapsedTitleOpacity = scrollY
    ? scrollY.interpolate({
        inputRange: [scrollRange * 0.4, scrollRange * 0.85],
        outputRange: [0, 1],
        extrapolate: 'clamp',
      })
    : 0;

  const collapsedTitleTranslateY = scrollY
    ? scrollY.interpolate({
        inputRange: [scrollRange * 0.4, scrollRange * 0.85],
        outputRange: [6, 0],
        extrapolate: 'clamp',
      })
    : 0;

  // Avatar positioning calculations:
  const avatarExpandedSize = avatar?.expandedSize || 52;
  const avatarCollapsedSize = avatar?.collapsedSize || 34;
  const avatarScale = scrollY
    ? scrollY.interpolate({
        inputRange: [0, scrollRange],
        outputRange: [1, avatarCollapsedSize / avatarExpandedSize],
        extrapolate: 'clamp',
      })
    : 1;

  const expandedAvatarLeft = 20;
  const collapsedAvatarLeft = onBackPress ? 52 : 16;
  const deltaX = collapsedAvatarLeft - expandedAvatarLeft;

  // Align avatar vertically with hero text when expanded
  const initialTop = effectiveExpandedHeight - avatarExpandedSize - 38;
  const targetCollapsedTop = (effectiveCollapsedHeight - avatarExpandedSize) / 2;
  const deltaY = targetCollapsedTop - initialTop;

  const avatarTranslateY = scrollY
    ? scrollY.interpolate({
        inputRange: [0, scrollRange],
        outputRange: [0, deltaY],
        extrapolate: 'clamp',
      })
    : 0;

  const avatarTranslateX = scrollY
    ? scrollY.interpolate({
        inputRange: [0, scrollRange],
        outputRange: [0, deltaX],
        extrapolate: 'clamp',
      })
    : 0;

  // Determine styling attributes based on variant
  const isLotteRed = variant === 'lotte-brand-red';
  const isNavy = variant === 'navy-gradient';
  const isEmerald = variant === 'emerald-wealth';
  const isDark = variant === 'dark-elevation';
  const isCurvedSheet = variant === 'curved-sheet';

  const isLightTextVariant = isLotteRed || isNavy || isEmerald || isDark || isCurvedSheet;
  const foregroundColor = isLightTextVariant ? '#FFFFFF' : theme.colors.text;
  const subtextColor = isLightTextVariant ? 'rgba(255, 255, 255, 0.90)' : '#6B7280';
  const backIconColor = isLightTextVariant ? '#FFFFFF' : theme.colors.text;

  // Background style based on variant
  const getVariantContainerStyle = (): ViewStyle => {
    switch (variant) {
      case 'lotte-brand-red':
        return {
          backgroundColor: '#D32F2F', // Authentic Lotte Red
          borderBottomWidth: 0,
        };
      case 'navy-gradient':
        return {
          backgroundColor: '#0F172A', // Midnight Navy
          borderBottomWidth: 0,
        };
      case 'emerald-wealth':
        return {
          backgroundColor: '#065F46', // Emerald Wealth
          borderBottomWidth: 0,
        };
      case 'dark-elevation':
        return {
          backgroundColor: '#1E293B', // Slate Dark
          borderBottomWidth: 0,
        };
      case 'curved-sheet':
        return {
          backgroundColor: '#D32F2F', // Lotte Red header matching AU-002
          borderBottomWidth: 0,
        };
      case 'clean-minimal':
      default:
        return {
          backgroundColor: theme.colors.card,
          borderBottomColor: theme.colors.border,
          borderBottomWidth: 1,
        };
    }
  };

  const renderAvatarContent = (size: number) => {
    if (!avatar) return null;
    const initials = avatar.name
      ? avatar.name
          .split(' ')
          .map((n) => n[0])
          .slice(0, 2)
          .join('')
          .toUpperCase()
      : 'U';

    return (
      <TouchableOpacity
        testID={`${testID}-collapsing-avatar`}
        onPress={avatar.onPress}
        disabled={!avatar.onPress}
        activeOpacity={0.8}
        style={[
          styles.avatarCircle,
          {
            width: size,
            height: size,
            borderRadius: size / 2,
            backgroundColor: isLightTextVariant ? '#FFFFFF' : theme.colors.primary,
            borderWidth: isLightTextVariant ? 2 : 0,
            borderColor: '#FFFFFF',
          },
        ]}
      >
        <Text
          style={[
            styles.avatarInitials,
            {
              fontSize: Math.round(size * 0.38),
              color: isLightTextVariant ? '#D32F2F' : '#FFFFFF',
            },
          ]}
        >
          {initials}
        </Text>
      </TouchableOpacity>
    );
  };

  return (
    <Animated.View
      testID={testID}
      style={[
        styles.container,
        {
          height: headerHeight,
        },
        getVariantContainerStyle(),
        style,
      ]}
    >
      {/* Decorative Brand Curves / Waves Background for Lotte Red and Gradient Variants */}
      {(isLotteRed || isCurvedSheet) && (
        <View pointerEvents="none" style={styles.decorativeBackgroundContainer}>
          <View style={[styles.redGlowAura, { opacity: 0.35 }]} />
          <View style={styles.redWaveCircleOne} />
          <View style={styles.redWaveCircleTwo} />
        </View>
      )}

      {isNavy && (
        <View pointerEvents="none" style={styles.decorativeBackgroundContainer}>
          <View style={styles.navyWaveOne} />
          <View style={styles.navyWaveTwo} />
        </View>
      )}

      {isEmerald && (
        <View pointerEvents="none" style={styles.decorativeBackgroundContainer}>
          <View style={styles.emeraldWaveOne} />
          <View style={styles.emeraldWaveTwo} />
        </View>
      )}

      {/* Top Navbar Row */}
      <View style={[styles.topBar, { height: effectiveCollapsedHeight }]}>
        <View style={styles.leftAction}>
          {onBackPress ? (
            <TouchableOpacity
              testID={`${testID}-back`}
              style={styles.backBtn}
              onPress={onBackPress}
              activeOpacity={0.7}
              accessibilityLabel="Go back"
              accessibilityRole="button"
            >
              <Text style={[styles.backText, { color: backIconColor }]}>
                ‹
              </Text>
            </TouchableOpacity>
          ) : null}
        </View>

        {/* Collapsed Title shown only when scrolled up */}
        <Animated.View
          testID={`${testID}-collapsed-title-container`}
          style={[
            styles.centerTitleContainer,
            {
              opacity: collapsedTitleOpacity,
              transform: [{ translateY: collapsedTitleTranslateY }],
            },
          ]}
        >
          <Text
            numberOfLines={1}
            style={[
              styles.collapsedTitle,
              {
                color: foregroundColor,
                fontFamily: theme.typography.fontFamilyBold,
              },
            ]}
          >
            {title}
          </Text>
        </Animated.View>

        <View style={styles.rightAction}>
          {actions.map((act) => (
            <TouchableOpacity
              key={act.key}
              testID={`${testID}-action-${act.key}`}
              style={styles.actionBtn}
              onPress={act.onPress}
              accessibilityLabel={act.accessibilityLabel}
              activeOpacity={0.7}
            >
              {act.icon(foregroundColor)}
              {act.badgeCount && act.badgeCount > 0 ? (
                <View
                  style={[
                    styles.badge,
                    {
                      backgroundColor: isLightTextVariant ? '#FFFFFF' : theme.colors.primary,
                    },
                  ]}
                >
                  <Text
                    style={[
                      styles.badgeText,
                      { color: isLightTextVariant ? '#D32F2F' : '#FFFFFF' },
                    ]}
                  >
                    {act.badgeCount > 99 ? '99+' : act.badgeCount}
                  </Text>
                </View>
              ) : null}
            </TouchableOpacity>
          ))}
          {rightAction}
        </View>
      </View>

      {/* Floating Collapsing Avatar that Stays in AppBar */}
      {avatar ? (
        <Animated.View
          pointerEvents="box-none"
          style={[
            styles.floatingAvatarWrapper,
            {
              top: initialTop,
              left: expandedAvatarLeft,
              transform: [
                { translateY: avatarTranslateY },
                { translateX: avatarTranslateX },
                { scale: avatarScale },
              ],
            },
          ]}
        >
          {renderAvatarContent(avatarExpandedSize)}
        </Animated.View>
      ) : null}

      {/* Expanded Hero Area */}
      <View style={styles.expandedHeroRow}>
        {/* Placeholder spacer so title doesn't overlap expanded avatar */}
        {avatar ? <View style={{ width: avatarExpandedSize + 12 }} /> : null}

        {/* Title, Subtitle, Brand Headings and Hero Content */}
        <Animated.View
          style={[
            styles.expandedContent,
            {
              opacity: contentOpacity,
              transform: [{ translateY: contentTranslateY }],
            },
          ]}
        >
          {/* Authentic Lotte Brand Header Typography Layout */}
          {brandLogoText ? (
            <View testID={`${testID}-brand-logo-wrap`} style={styles.brandLogoRow}>
              <Text style={styles.brandLogoMain}>{brandLogoText}</Text>
            </View>
          ) : null}

          {welcomeText ? (
            <Text
              testID={`${testID}-welcome-text`}
              style={[
                styles.welcomeText,
                { color: subtextColor, fontFamily: theme.typography.fontFamilyRegular },
              ]}
            >
              {welcomeText}
            </Text>
          ) : null}

          {heroTitle ? (
            <Text
              testID={`${testID}-hero-title`}
              style={[
                styles.heroDisplayTitle,
                { color: foregroundColor, fontFamily: theme.typography.fontFamilyBold },
              ]}
            >
              {heroTitle}
            </Text>
          ) : (
            <Text
              testID={`${testID}-expanded-title`}
              style={[
                styles.expandedTitle,
                { color: foregroundColor, fontFamily: theme.typography.fontFamilyBold },
              ]}
            >
              {title}
            </Text>
          )}

          {subtitle ? (
            <Text
              testID={`${testID}-subtitle`}
              style={[styles.subtitle, { color: subtextColor }]}
            >
              {subtitle}
            </Text>
          ) : null}

          {heroContent ? (
            <View style={styles.heroContentWrap}>{heroContent}</View>
          ) : null}
        </Animated.View>
      </View>

      {/* Decorative Bottom Curved Mask for curved-sheet variant - fades out as header collapses */}
      {isCurvedSheet && (
        <Animated.View
          pointerEvents="none"
          style={[
            styles.curvedSheetLip,
            {
              opacity: contentOpacity,
            },
          ]}
        />
      )}
    </Animated.View>
  );
};

