import React, { useState } from 'react';
import { View, Text, StyleSheet } from 'react-native';
import { AppCard, ColorPicker } from '@mfe/ui-components/components';
import { CodeBlock } from '../../components/CodeBlock';

const COLOR_PICKER_SNIPPET = `import { ColorPicker } from '@mfe/ui-components/components';

const [brandColor, setBrandColor] = useState('#E7252B');

<ColorPicker
  label="Primary Brand Color"
  value={brandColor}
  onChange={setBrandColor}
  allowCustomHex
/>;`;

export const ColorPickerDetailSection: React.FC = () => {
  const [selectedColor, setSelectedColor] = useState('#E7252B');

  return (
    <View testID="detail-color-picker">
      <CodeBlock title="ColorPicker Usage" code={COLOR_PICKER_SNIPPET} />

      <AppCard style={styles.card}>
        <ColorPicker
          label="Primary Accent Color"
          value={selectedColor}
          onChange={setSelectedColor}
          allowCustomHex
          testID="demo-color-picker"
        />

        <View style={[styles.previewBanner, { backgroundColor: selectedColor }]}>
          <Text style={styles.previewBannerText}>
            Selected Color: {selectedColor}
          </Text>
        </View>
      </AppCard>
    </View>
  );
};

const styles = StyleSheet.create({
  card: {
    marginBottom: 16,
  },
  previewBanner: {
    marginTop: 16,
    borderRadius: 10,
    paddingVertical: 14,
    paddingHorizontal: 16,
    alignItems: 'center',
  },
  previewBannerText: {
    color: '#FFFFFF',
    fontSize: 14,
    fontWeight: '700',
  },
});
