import {
  LoginCredentials,
  LoginResult,
  OtpVerificationPayload,
  OtpVerificationResult,
  BiometricSetupResult,
} from '../models/AuthModel';
import { executeBiometric } from 'react-native-bizmob-plugin';
import {
  defaultNetworkService,
  INetworkService,
  TR_CODES,
} from '@mfe/core';

export interface IAuthService {
  login(credentials: LoginCredentials, useMock?: boolean): Promise<LoginResult>;
  requestOtp(
    userId: string,
    channel: 'email' | 'sms' | 'admin',
    useMock?: boolean
  ): Promise<{ success: boolean; message: string }>;
  verifyOtp(payload: OtpVerificationPayload, useMock?: boolean): Promise<OtpVerificationResult>;
  registerBiometric(userId: string, enabled: boolean): Promise<BiometricSetupResult>;
  checkBiometricSupport(): Promise<{
    available: boolean;
    biometryType: 'FaceID' | 'TouchID' | 'Fingerprint' | 'Biometrics' | null;
  }>;
}

export class AuthService implements IAuthService {
  private delayMs: number;
  private networkService: INetworkService;
  private useMock: boolean;

  constructor(
    delayMs: number = 0,
    networkService: INetworkService = defaultNetworkService,
    useMock: boolean = true
  ) {
    this.delayMs = delayMs;
    this.networkService = networkService;
    this.useMock = useMock;
  }

  private async sleep(): Promise<void> {
    if (this.delayMs > 0) {
      await new Promise((resolve) => setTimeout(resolve, this.delayMs));
    }
  }

  async login(
    credentials: LoginCredentials,
    useMock: boolean = this.useMock
  ): Promise<LoginResult> {
    await this.sleep();

    if (credentials.password === 'wrongpass' || credentials.userId === 'invalid') {
      return {
        success: false,
        errorMessage: 'Invalid User ID or Password. Please check your credentials.',
      };
    }

    const res = await this.networkService.request<LoginResult>({
      trCode: TR_CODES.AUTH_LOGIN,
      payload: credentials,
      useMock,
    });

    if (res.result && res.body) {
      return res.body;
    }

    return {
      success: true,
      requiresOtp: true,
      userEmail: 'uy.***@gmail.com',
      userPhone: '087****96',
      token: 'mock-auth-jwt-token',
    };
  }

  async requestOtp(
    userId: string,
    channel: 'email' | 'sms' | 'admin',
    useMock: boolean = this.useMock
  ): Promise<{ success: boolean; message: string }> {
    await this.sleep();
    const res = await this.networkService.request<{ success: boolean; message: string }>({
      trCode: TR_CODES.AUTH_OTP_REQUEST,
      payload: { userId, channel },
      useMock,
    });

    if (res.result && res.body && !useMock) {
      return res.body;
    }

    return {
      success: true,
      message: `A 6-digit verification code has been dispatched via ${channel}.`,
    };
  }

  async verifyOtp(
    payload: OtpVerificationPayload,
    useMock: boolean = this.useMock
  ): Promise<OtpVerificationResult> {
    await this.sleep();

    if (payload.otpCode !== '123456') {
      return {
        success: false,
        errorMessage: 'The OTP code entered is incorrect or has expired.',
      };
    }

    const res = await this.networkService.request<OtpVerificationResult>({
      trCode: TR_CODES.AUTH_OTP_VERIFY,
      payload,
      useMock,
    });

    if (res.result && res.body) {
      return res.body;
    }

    return {
      success: true,
      token: 'mock-verified-session-token',
    };
  }

  async registerBiometric(
    _userId: string,
    enabled: boolean
  ): Promise<BiometricSetupResult> {
    await this.sleep();

    if (enabled) {
      try {
        const bioRes: any = await executeBiometric({
          type: 'auth',
          title: 'Biometric Verification',
          subTitle: 'Touch the fingerprint sensor to verify identity',
        });

        // Check if plugin returned success
        const isSuccess = bioRes?.header?.result === true || bioRes?.result === true;
        if (!isSuccess) {
          const errMsg =
            bioRes?.header?.error_text ||
            bioRes?.error_text ||
            bioRes?.message ||
            'Biometric verification was cancelled or failed.';
          return {
            success: false,
            errorMessage: errMsg,
          };
        }
      } catch (err: any) {
        console.warn('[AuthService] executeBiometric error:', err);
        return {
          success: false,
          errorMessage: err?.message || 'Biometric hardware error.',
        };
      }
    }

    return {
      success: true,
      biometricEnabled: enabled,
    };
  }

  async checkBiometricSupport(): Promise<{
    available: boolean;
    biometryType: 'FaceID' | 'TouchID' | 'Fingerprint' | 'Biometrics' | null;
  }> {
    return {
      available: true,
      biometryType: 'Fingerprint',
    };
  }
}
