import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
  Platform,
} from 'react-native';

export interface CountdownTimerProps {
  /**
   * Total seconds for countdown (default: 180s = 3 minutes)
   */
  initialSeconds?: number;
  /**
   * Format for displaying the remaining time ('mm:ss' | 'ss' | 'm:s')
   * Default: 'mm:ss'
   */
  format?: 'mm:ss' | 'ss';
  /**
   * Prefix text before timer (e.g. "The code can be resent after:")
   */
  prefixText?: string;
  /**
   * Label for the resend button (default: "Resend code")
   */
  resendText?: string;
  /**
   * Triggered when user taps the enabled resend button
   */
  onResend?: () => void;
  /**
   * Triggered when timer counts down to 0
   */
  onExpire?: () => void;
  /**
   * Whether to auto-start countdown (default: true)
   */
  autoStart?: boolean;
  /**
   * Custom style for container
   */
  style?: ViewStyle;
  /**
   * Accessibility test ID
   */
  testID?: string;
}

/**
 * CountdownTimer Component
 *
 * Dedicated timer & resend controller matching AU-010 Phone OTP Verification:
 * Displays left-aligned countdown text: "The code can be resent after: mm:ss"
 * and right-aligned action: "Resend code" (disabled grey while running, interactive blue/primary when expired).
 */
export const CountdownTimer: React.FC<CountdownTimerProps> = ({
  initialSeconds = 180,
  format = 'mm:ss',
  prefixText = 'The code can be resent after:',
  resendText = 'Resend code',
  onResend,
  onExpire,
  autoStart = true,
  style,
  testID = 'countdown-timer',
}) => {
  const [secondsRemaining, setSecondsRemaining] = useState(initialSeconds);
  const [isRunning, setIsRunning] = useState(autoStart);

  useEffect(() => {
    if (!isRunning) {
      return;
    }

    if (secondsRemaining <= 0) {
      setIsRunning(false);
      onExpire?.();
      return;
    }

    const timer = setInterval(() => {
      setSecondsRemaining((prev) => {
        if (prev <= 1) {
          clearInterval(timer);
          setIsRunning(false);
          onExpire?.();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [isRunning]);

  const handleResendPress = () => {
    if (secondsRemaining > 0) return;
    setSecondsRemaining(initialSeconds);
    setIsRunning(true);
    onResend?.();
  };

  const minutes = Math.floor(secondsRemaining / 60);
  const seconds = secondsRemaining % 60;
  const formattedTime =
    format === 'ss'
      ? `${secondsRemaining}s`
      : `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;

  const canResend = secondsRemaining === 0;

  return (
    <View style={[styles.container, style]} testID={testID}>
      {/* Left side: Countdown text */}
      <View style={styles.textWrapper}>
        <Text style={styles.prefixText} testID={`${testID}-prefix`}>
          {prefixText}{' '}
          <Text style={styles.timeText} testID={`${testID}-time`}>
            {formattedTime}
          </Text>
        </Text>
      </View>

      {/* Right side: Resend action button */}
      <TouchableOpacity
        testID={`${testID}-resend-btn`}
        onPress={handleResendPress}
        disabled={!canResend}
        activeOpacity={0.7}
        style={styles.resendBtn}
      >
        <Text
          style={[
            styles.resendText,
            canResend ? styles.resendActiveText : styles.resendDisabledText,
          ]}
          testID={`${testID}-resend-text`}
        >
          {resendText}
        </Text>
      </TouchableOpacity>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    width: '100%',
    paddingVertical: 12,
  },
  textWrapper: {
    flex: 1,
    paddingRight: 8,
  },
  prefixText: {
    fontSize: 13,
    color: '#334155', // slate-700
    fontFamily: Platform.select({
      ios: 'Pretendard-Regular',
      android: 'Pretendard-Regular',
      default: 'system-ui',
    }),
  },
  timeText: {
    fontWeight: '600',
    color: '#0F172A', // slate-900
    fontVariant: ['tabular-nums'],
    fontFamily: Platform.select({
      ios: 'Pretendard-SemiBold',
      android: 'Pretendard-SemiBold',
      default: 'system-ui',
    }),
  },
  resendBtn: {
    paddingVertical: 4,
    paddingHorizontal: 4,
  },
  resendText: {
    fontSize: 14,
    fontWeight: '600',
    fontFamily: Platform.select({
      ios: 'Pretendard-SemiBold',
      android: 'Pretendard-SemiBold',
      default: 'system-ui',
    }),
  },
  resendActiveText: {
    color: '#2563EB', // vibrant blue
  },
  resendDisabledText: {
    color: '#94A3B8', // soft slate grey
  },
});
