import React from 'react';
import { View, Text, TouchableOpacity, StyleSheet } from 'react-native';
import { DatePickerField } from './DatePickerField';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export interface DateRangePickerProps {
  label?: string;
  startDate: string; // YYYY-MM-DD
  endDate: string; // YYYY-MM-DD
  onChangeStartDate: (date: string) => void;
  onChangeEndDate: (date: string) => void;
  onClear?: () => void;
  error?: string;
  testID?: string;
}

export const DateRangePicker: React.FC<DateRangePickerProps> = ({
  label = 'Date Range',
  startDate,
  endDate,
  onChangeStartDate,
  onChangeEndDate,
  onClear,
  error,
  testID = 'date-range-picker',
}) => {
  const { theme } = useTheme();

  return (
    <View testID={testID} style={styles.container}>
      <View style={styles.headerRow}>
        {label ? <Text style={styles.label}>{label}</Text> : null}
        {onClear && (startDate || endDate) ? (
          <TouchableOpacity
            testID={`${testID}-clear-btn`}
            onPress={onClear}
            activeOpacity={0.7}
          >
            <Text style={[styles.clearBtnText, { color: theme.colors.primary }]}>
              Clear Range
            </Text>
          </TouchableOpacity>
        ) : null}
      </View>

      <View style={styles.pickersRow}>
        <View style={styles.pickerCol}>
          <DatePickerField
            label="From Date"
            value={startDate}
            onChangeDate={onChangeStartDate}
            testID={`${testID}-start`}
          />
        </View>

        <View style={styles.tildeWrapper}>
          <Text style={styles.tildeText}>~</Text>
        </View>

        <View style={styles.pickerCol}>
          <DatePickerField
            label="To Date"
            value={endDate}
            onChangeDate={onChangeEndDate}
            minDate={startDate}
            testID={`${testID}-end`}
          />
        </View>
      </View>

      {error ? <Text style={styles.errorText}>{error}</Text> : null}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    marginVertical: 6,
  },
  headerRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 4,
  },
  label: {
    fontSize: 13,
    fontWeight: '600',
    color: '#333333',
  },
  clearBtnText: {
    fontSize: 12,
    fontWeight: '700',
  },
  pickersRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
  },
  pickerCol: {
    flex: 1,
  },
  tildeWrapper: {
    paddingTop: 18,
    justifyContent: 'center',
    alignItems: 'center',
  },
  tildeText: {
    fontSize: 18,
    color: '#666666',
    fontWeight: '700',
  },
  errorText: {
    fontSize: 12,
    color: '#E7252B',
    marginTop: 4,
  },
});
