import React, { useRef, useEffect, useState } from 'react';
import {
  StyleSheet,
  TouchableOpacity,
  Animated,
  ViewStyle,
  StyleProp,
  Text,
  View,
  TouchableWithoutFeedback,
  Platform,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { PlusIcon } from '@mfe/assets/icons/CommonIcons';

export interface FloatingActionItem {
  id: string;
  label?: string;
  icon?: (color: string) => React.ReactNode;
  onPress: () => void;
  backgroundColor?: string;
  textColor?: string;
  badge?: number | string;
  badgeColor?: string;
  testID?: string;
}

export type FloatingButtonPosition =
  | 'bottom-right'
  | 'bottom-left'
  | 'bottom-center'
  | 'top-right'
  | 'top-left';

export interface FloatingActionButtonProps {
  /**
   * Primary button label when extended
   */
  label?: string;
  /**
   * Main button icon renderer. Defaults to PlusIcon.
   */
  icon?: (color: string) => React.ReactNode;
  /**
   * Active icon when action group is expanded (e.g. Close / Cross icon).
   * Defaults to rotated PlusIcon if not provided.
   */
  activeIcon?: (color: string) => React.ReactNode;
  onPress?: () => void;
  extended?: boolean;
  position?: FloatingButtonPosition;
  style?: StyleProp<ViewStyle>;
  backgroundColor?: string;
  textColor?: string;
  collapsedSize?: number;
  extendedWidth?: number;
  testID?: string;

  /**
   * Badge counter or label displayed on top-right of main FAB
   */
  badge?: number | string;
  badgeColor?: string;
  badgeTextColor?: string;

  /**
   * Optional tooltip text displayed next to or above the button
   */
  tooltip?: string;
  tooltipPosition?: 'top' | 'left' | 'right' | 'bottom';
  showTooltip?: boolean;

  /**
   * Speed dial / Group sub-actions floating above/beside the main FAB
   */
  actions?: FloatingActionItem[];
  /**
   * Direction to fan out group buttons: 'up' (default) | 'down' | 'left' | 'right'
   */
  groupDirection?: 'up' | 'down' | 'left' | 'right';
  /**
   * Controlled open state for group menu
   */
  isOpen?: boolean;
  /**
   * Callback fired when speed dial / group expands or collapses
   */
  onToggleOpen?: (open: boolean) => void;
  /**
   * Whether to dim the background backdrop when group is open
   */
  overlayBackdrop?: boolean;
}

export const FloatingActionButton: React.FC<FloatingActionButtonProps> = ({
  label,
  icon,
  activeIcon,
  onPress,
  extended = false,
  position = 'bottom-right',
  style,
  backgroundColor,
  textColor,
  collapsedSize = 50,
  extendedWidth = 98,
  testID = 'floating-action-button',
  badge,
  badgeColor,
  badgeTextColor = '#FFFFFF',
  tooltip,
  tooltipPosition = 'top',
  showTooltip = false,
  actions = [],
  groupDirection = 'up',
  isOpen: controlledIsOpen,
  onToggleOpen,
  overlayBackdrop = false,
}) => {
  const { theme } = useTheme();

  // Speed-dial open state
  const [internalOpen, setInternalOpen] = useState(false);
  const isGroupOpen = controlledIsOpen !== undefined ? controlledIsOpen : internalOpen;

  // Extension animation
  const isExtended = extended && Boolean(label) && !isGroupOpen;
  const animValue = useRef(new Animated.Value(isExtended ? 1 : 0)).current;

  // Group expansion & icon rotation animation
  const groupAnim = useRef(new Animated.Value(isGroupOpen ? 1 : 0)).current;

  // Tooltip fade animation
  const tooltipAnim = useRef(new Animated.Value(showTooltip ? 1 : 0)).current;

  useEffect(() => {
    Animated.spring(animValue, {
      toValue: isExtended ? 1 : 0,
      friction: 8,
      tension: 65,
      useNativeDriver: false,
    }).start();
  }, [isExtended, animValue]);

  useEffect(() => {
    Animated.spring(groupAnim, {
      toValue: isGroupOpen ? 1 : 0,
      friction: 7,
      tension: 70,
      useNativeDriver: false,
    }).start();
  }, [isGroupOpen, groupAnim]);

  useEffect(() => {
    Animated.timing(tooltipAnim, {
      toValue: showTooltip ? 1 : 0,
      duration: 200,
      useNativeDriver: true,
    }).start();
  }, [showTooltip, tooltipAnim]);

  const handleToggle = () => {
    if (actions.length > 0) {
      const nextState = !isGroupOpen;
      if (controlledIsOpen === undefined) {
        setInternalOpen(nextState);
      }
      onToggleOpen?.(nextState);
    }
    onPress?.();
  };

  const handleBackdropPress = () => {
    if (controlledIsOpen === undefined) {
      setInternalOpen(false);
    }
    onToggleOpen?.(false);
  };

  const getPositionStyle = (): ViewStyle => {
    switch (position) {
      case 'bottom-left':
        return { bottom: 24, left: 24 };
      case 'bottom-center':
        return { bottom: 24, alignSelf: 'center' };
      case 'top-right':
        return { top: 24, right: 20 };
      case 'top-left':
        return { top: 24, left: 24 };
      default:
        return { bottom: 24, right: 20 };
    }
  };

  const animatedWidth = animValue.interpolate({
    inputRange: [0, 1],
    outputRange: [collapsedSize, extendedWidth],
  });

  const labelOpacity = animValue.interpolate({
    inputRange: [0, 0.4, 1],
    outputRange: [0, 0, 1],
  });

  const labelMaxWidth = animValue.interpolate({
    inputRange: [0, 1],
    outputRange: [0, extendedWidth - collapsedSize + 10],
  });

  const labelMarginLeft = animValue.interpolate({
    inputRange: [0, 0.3, 1],
    outputRange: [0, 0, 6],
  });

  // Rotation for the main plus icon when action items are expanded
  const iconRotate = groupAnim.interpolate({
    inputRange: [0, 1],
    outputRange: ['0deg', '45deg'],
  });

  const resolvedBg = backgroundColor || theme?.colors?.primary || '#E7252B';
  const resolvedColor = textColor || '#FFFFFF';
  const resolvedBadgeBg = badgeColor || theme?.colors?.error || '#E7252B';

  // Badge formatted display
  const renderBadge = (val: number | string | undefined, testIdSuffix = 'badge', bgCol = resolvedBadgeBg) => {
    if (val === undefined || val === null || val === '') return null;
    const displayVal = typeof val === 'number' && val > 99 ? '99+' : `${val}`;
    return (
      <View
        testID={`${testID}-${testIdSuffix}`}
        style={[
          styles.badgeContainer,
          { backgroundColor: bgCol },
        ]}
      >
        <Text style={[styles.badgeText, { color: badgeTextColor }]}>
          {displayVal}
        </Text>
      </View>
    );
  };

  // Tooltip positioning
  const getTooltipStyle = (): ViewStyle => {
    switch (tooltipPosition) {
      case 'bottom':
        return { top: collapsedSize + 8, alignSelf: 'center' };
      case 'left':
        return { right: collapsedSize + 10, alignSelf: 'center' };
      case 'right':
        return { left: collapsedSize + 10, alignSelf: 'center' };
      case 'top':
      default:
        return { bottom: collapsedSize + 8, alignSelf: 'center' };
    }
  };

  // Group items layout calculation
  const renderActionGroup = () => {
    if (actions.length === 0) return null;

    return (
      <View
        pointerEvents={isGroupOpen ? 'auto' : 'none'}
        style={[
          styles.groupContainer,
          groupDirection === 'down' && styles.groupDirectionDown,
          groupDirection === 'left' && styles.groupDirectionLeft,
          groupDirection === 'right' && styles.groupDirectionRight,
        ]}
        testID={`${testID}-action-group`}
      >
        {actions.map((item, index) => {
          const itemDelay = (actions.length - 1 - index) * 0.15;
          const itemScale = groupAnim.interpolate({
            inputRange: [0, Math.min(1, itemDelay + 0.5), 1],
            outputRange: [0, 0.4, 1],
          });
          const itemOpacity = groupAnim.interpolate({
            inputRange: [0, Math.min(1, itemDelay + 0.3), 1],
            outputRange: [0, 0, 1],
          });

          const itemDistance = (index + 1) * (collapsedSize - 4);
          const itemTranslateY =
            groupDirection === 'up'
              ? groupAnim.interpolate({
                  inputRange: [0, 1],
                  outputRange: [0, -itemDistance],
                })
              : groupDirection === 'down'
              ? groupAnim.interpolate({
                  inputRange: [0, 1],
                  outputRange: [0, itemDistance],
                })
              : 0;

          const itemTranslateX =
            groupDirection === 'left'
              ? groupAnim.interpolate({
                  inputRange: [0, 1],
                  outputRange: [0, -itemDistance],
                })
              : groupDirection === 'right'
              ? groupAnim.interpolate({
                  inputRange: [0, 1],
                  outputRange: [0, itemDistance],
                })
              : 0;

          const itemBg = item.backgroundColor || '#FFFFFF';
          const itemFg = item.textColor || theme?.colors?.primary || '#E7252B';

          return (
            <Animated.View
              key={item.id}
              style={[
                styles.actionItemWrap,
                {
                  opacity: itemOpacity,
                  transform: [
                    { scale: itemScale },
                    { translateY: itemTranslateY },
                    { translateX: itemTranslateX },
                  ],
                },
              ]}
            >
              {/* Optional Item Label Pill */}
              {item.label && groupDirection !== 'left' && groupDirection !== 'right' && (
                <View style={styles.actionLabelPill} testID={`${item.testID || item.id}-label`}>
                  <Text style={[styles.actionLabelText, { color: theme?.colors?.text || '#16181D' }]}>
                    {item.label}
                  </Text>
                </View>
              )}

              {/* Action Button Bubble */}
              <TouchableOpacity
                testID={item.testID || `${testID}-action-${item.id}`}
                activeOpacity={0.8}
                onPress={() => {
                  item.onPress();
                  if (controlledIsOpen === undefined) {
                    setInternalOpen(false);
                  }
                  onToggleOpen?.(false);
                }}
                style={[
                  styles.actionButtonBubble,
                  {
                    width: collapsedSize - 8,
                    height: collapsedSize - 8,
                    borderRadius: (collapsedSize - 8) / 2,
                    backgroundColor: itemBg,
                  },
                ]}
              >
                {item.icon ? (
                  item.icon(itemFg)
                ) : (
                  <PlusIcon size={18} color={itemFg} />
                )}
                {renderBadge(item.badge, `badge-${item.id}`, item.badgeColor)}
              </TouchableOpacity>
            </Animated.View>
          );
        })}
      </View>
    );
  };

  const isPositionedAbsolute = !style || !StyleSheet.flatten(style)?.position || StyleSheet.flatten(style)?.position === 'absolute';

  return (
    <>
      {/* Optional Fullscreen Overlay Backdrop for Group Fan-out */}
      {overlayBackdrop && isGroupOpen && (
        <TouchableWithoutFeedback onPress={handleBackdropPress}>
          <View
            style={[
              StyleSheet.absoluteFill,
              { backgroundColor: 'rgba(0, 0, 0, 0.35)', zIndex: 98 },
            ]}
            testID={`${testID}-backdrop`}
          />
        </TouchableWithoutFeedback>
      )}

      <View
        style={[
          isPositionedAbsolute && styles.absoluteWrapper,
          isPositionedAbsolute && getPositionStyle(),
          style,
        ]}
        pointerEvents="box-none"
      >
        {/* Fan-out Action Group */}
        {renderActionGroup()}

        {/* Optional Tooltip Bubble */}
        {tooltip && showTooltip ? (
          <Animated.View
            style={[
              styles.tooltipContainer,
              getTooltipStyle(),
              { opacity: tooltipAnim },
            ]}
            testID={`${testID}-tooltip`}
          >
            <Text style={styles.tooltipText}>{tooltip}</Text>
          </Animated.View>
        ) : null}

        {/* Main Floating Action Button */}
        <Animated.View
          style={[
            styles.fabContainer,
            {
              width: animatedWidth,
              height: collapsedSize,
              borderRadius: collapsedSize / 2,
              backgroundColor: resolvedBg,
              shadowColor: resolvedBg,
            },
          ]}
          testID={testID}
        >
          <TouchableOpacity
            testID={`${testID}-touchable`}
            style={styles.innerTouchable}
            activeOpacity={0.85}
            onPress={handleToggle}
          >
            <Animated.View
              style={[
                styles.iconWrap,
                actions.length > 0 && !activeIcon
                  ? { transform: [{ rotate: iconRotate }] }
                  : undefined,
              ]}
              testID={`${testID}-icon-wrap`}
            >
              {isGroupOpen && activeIcon
                ? activeIcon(resolvedColor)
                : icon
                ? icon(resolvedColor)
                : <PlusIcon size={22} color={resolvedColor} />}
            </Animated.View>

            <Animated.View
              style={[
                styles.labelWrapper,
                {
                  opacity: labelOpacity,
                  maxWidth: labelMaxWidth,
                  marginLeft: labelMarginLeft,
                },
              ]}
            >
              {label ? (
                <Text
                  testID={`${testID}-label`}
                  style={[
                    styles.label,
                    { color: resolvedColor },
                  ]}
                  numberOfLines={1}
                >
                  {label}
                </Text>
              ) : null}
            </Animated.View>
          </TouchableOpacity>

          {/* Badge indicator on main button */}
          {renderBadge(badge, 'badge')}
        </Animated.View>
      </View>
    </>
  );
};

const styles = StyleSheet.create({
  absoluteWrapper: {
    position: 'absolute',
    zIndex: 99,
    alignItems: 'center',
    justifyContent: 'center',
  },
  fabContainer: {
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.25,
    shadowRadius: 8,
    elevation: 6,
    overflow: 'visible',
    justifyContent: 'center',
    alignItems: 'center',
  },
  innerTouchable: {
    width: '100%',
    height: '100%',
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: 0,
    overflow: 'hidden',
    borderRadius: 9999,
  },
  iconWrap: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  labelWrapper: {
    overflow: 'hidden',
  },
  label: {
    fontSize: 12,
    fontWeight: '800',
  },
  // Badge Styles
  badgeContainer: {
    position: 'absolute',
    top: -4,
    right: -4,
    minWidth: 20,
    height: 20,
    borderRadius: 10,
    paddingHorizontal: 5,
    alignItems: 'center',
    justifyContent: 'center',
    borderWidth: 1.5,
    borderColor: '#FFFFFF',
    zIndex: 10,
    elevation: 7,
  },
  badgeText: {
    fontSize: 10,
    fontWeight: '800',
    textAlign: 'center',
    lineHeight: 12,
  },
  // Tooltip Styles
  tooltipContainer: {
    position: 'absolute',
    backgroundColor: '#1E293B',
    paddingHorizontal: 10,
    paddingVertical: 5,
    borderRadius: 6,
    zIndex: 102,
    elevation: 8,
    shadowColor: '#000000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.2,
    shadowRadius: 4,
    whiteSpace: Platform.OS === 'web' ? ('nowrap' as any) : undefined,
  },
  tooltipText: {
    color: '#FFFFFF',
    fontSize: 11,
    fontWeight: '600',
  },
  // Action Group Styles
  groupContainer: {
    position: 'absolute',
    bottom: 0,
    right: 0,
    left: 0,
    alignItems: 'center',
    justifyContent: 'center',
    zIndex: 97,
  },
  groupDirectionDown: {
    bottom: 'auto',
    top: 0,
  },
  groupDirectionLeft: {
    right: 0,
    flexDirection: 'row',
  },
  groupDirectionRight: {
    left: 0,
    flexDirection: 'row',
  },
  actionItemWrap: {
    position: 'absolute',
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
  },
  actionLabelPill: {
    backgroundColor: '#FFFFFF',
    paddingHorizontal: 10,
    paddingVertical: 4,
    borderRadius: 12,
    marginRight: 10,
    elevation: 4,
    shadowColor: '#000000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.15,
    shadowRadius: 4,
  },
  actionLabelText: {
    fontSize: 12,
    fontWeight: '700',
  },
  actionButtonBubble: {
    alignItems: 'center',
    justifyContent: 'center',
    elevation: 5,
    shadowColor: '#000000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.2,
    shadowRadius: 5,
    borderWidth: 1,
    borderColor: 'rgba(0, 0, 0, 0.05)',
  },
});
