import React, { useCallback, useEffect, useRef, useState } from 'react';
import {
  Animated,
  Image,
  ImageSourcePropType,
  Modal,
  NativeScrollEvent,
  NativeSyntheticEvent,
  Platform,
  ScrollView,
  StyleSheet,
  Text,
  TouchableOpacity,
  useWindowDimensions,
  View,
} from 'react-native';
import Svg, { Path } from 'react-native-svg';

export interface ImageViewerItem {
  id?: string;
  source: ImageSourcePropType;
  title?: string;
  caption?: string;
}

export interface ImageViewerProps {
  visible: boolean;
  images: ImageViewerItem[];
  initialIndex?: number;
  onClose: () => void;
  onIndexChange?: (index: number) => void;
  testID?: string;
}

export const ImageViewer: React.FC<ImageViewerProps> = ({
  visible,
  images,
  initialIndex = 0,
  onClose,
  onIndexChange,
  testID = 'image-viewer',
}) => {
  const { width: windowWidth, height: windowHeight } = useWindowDimensions();
  const clampedInitial =
    images.length > 0 ? Math.max(0, Math.min(initialIndex, images.length - 1)) : 0;

  const [activeIndex, setActiveIndex] = useState<number>(clampedInitial);
  const [zoomScale, setZoomScale] = useState<number>(1);
  const scrollViewRef = useRef<ScrollView | null>(null);

  const openScale = useRef(new Animated.Value(0.92)).current;
  const openOpacity = useRef(new Animated.Value(0)).current;
  const zoomAnim = useRef(new Animated.Value(1)).current;
  const useNative = Platform.OS !== 'web';

  useEffect(() => {
    if (visible) {
      const idx =
        images.length > 0 ? Math.max(0, Math.min(initialIndex, images.length - 1)) : 0;
      setActiveIndex(idx);
      setZoomScale(1);
      zoomAnim.setValue(1);
      openScale.setValue(0.92);
      openOpacity.setValue(0);

      Animated.parallel([
        Animated.spring(openScale, {
          toValue: 1,
          tension: 140,
          friction: 14,
          useNativeDriver: useNative,
        }),
        Animated.timing(openOpacity, {
          toValue: 1,
          duration: 180,
          useNativeDriver: useNative,
        }),
      ]).start();

      setTimeout(() => {
        scrollViewRef.current?.scrollTo({
          x: idx * windowWidth,
          animated: false,
        });
      }, 0);
    }
  }, [visible, initialIndex, images.length, windowWidth, openScale, openOpacity, zoomAnim, useNative]);

  const applyZoom = useCallback(
    (nextScale: number) => {
      const clamped = Math.max(1, Math.min(3, nextScale));
      setZoomScale(clamped);
      Animated.spring(zoomAnim, {
        toValue: clamped,
        tension: 140,
        friction: 14,
        useNativeDriver: useNative,
      }).start();
    },
    [zoomAnim, useNative]
  );

  const goToIndex = useCallback(
    (targetIdx: number) => {
      if (images.length === 0) return;
      const clamped = Math.max(0, Math.min(targetIdx, images.length - 1));
      setActiveIndex(clamped);
      applyZoom(1);
      onIndexChange?.(clamped);
      scrollViewRef.current?.scrollTo({
        x: clamped * windowWidth,
        animated: true,
      });
    },
    [images.length, windowWidth, applyZoom, onIndexChange]
  );

  const handleScrollEnd = (event: NativeSyntheticEvent<NativeScrollEvent>) => {
    if (windowWidth <= 0 || images.length === 0) return;
    const offsetX = event.nativeEvent.contentOffset.x;
    const nextIdx = Math.max(
      0,
      Math.min(Math.round(offsetX / windowWidth), images.length - 1)
    );
    if (nextIdx !== activeIndex) {
      setActiveIndex(nextIdx);
      applyZoom(1);
      onIndexChange?.(nextIdx);
    }
  };

  if (!visible || images.length === 0) {
    return null;
  }

  const currentItem = images[activeIndex] || images[0];

  return (
    <Modal
      visible={visible}
      transparent
      animationType="none"
      onRequestClose={onClose}
    >
      <Animated.View
        testID={testID}
        style={[
          styles.backdrop,
          { opacity: openOpacity },
          Platform.OS === 'web'
            ? ({ backdropFilter: 'blur(16px)', WebkitBackdropFilter: 'blur(16px)' } as any)
            : null,
        ]}
      >
        {/* Top Bar: Counter & Close */}
        <View style={styles.topBar}>
          <View style={styles.counterPill}>
            <Text testID={`${testID}-counter`} style={styles.counterText}>
              {activeIndex + 1} / {images.length}
            </Text>
          </View>

          <View style={styles.zoomControls}>
            <TouchableOpacity
              testID={`${testID}-zoom-out`}
              style={styles.iconBtn}
              activeOpacity={0.75}
              onPress={() => applyZoom(zoomScale - 0.5)}
            >
              <Text style={styles.zoomBtnText}>−</Text>
            </TouchableOpacity>
            <TouchableOpacity
              testID={`${testID}-zoom-reset`}
              style={styles.zoomLabelBtn}
              activeOpacity={0.75}
              onPress={() => applyZoom(zoomScale === 1 ? 2 : 1)}
            >
              <Text style={styles.zoomLabelText}>{Math.round(zoomScale * 100)}%</Text>
            </TouchableOpacity>
            <TouchableOpacity
              testID={`${testID}-zoom-in`}
              style={styles.iconBtn}
              activeOpacity={0.75}
              onPress={() => applyZoom(zoomScale + 0.5)}
            >
              <Text style={styles.zoomBtnText}>+</Text>
            </TouchableOpacity>
            <TouchableOpacity
              testID={`${testID}-close-btn`}
              style={styles.iconBtn}
              activeOpacity={0.75}
              onPress={onClose}
            >
              <Svg width={18} height={18} viewBox="0 0 24 24" fill="none">
                <Path
                  d="M6 6L18 18M18 6L6 18"
                  stroke="#FFFFFF"
                  strokeWidth={2.4}
                  strokeLinecap="round"
                />
              </Svg>
            </TouchableOpacity>
          </View>
        </View>

        {/* Horizontal Swipeable Image Stage */}
        <Animated.View
          style={[
            styles.stage,
            { transform: [{ scale: openScale }] },
          ]}
        >
          <ScrollView
            ref={scrollViewRef}
            testID={`${testID}-scroll`}
            horizontal
            pagingEnabled
            showsHorizontalScrollIndicator={false}
            scrollEnabled={zoomScale === 1}
            onMomentumScrollEnd={handleScrollEnd}
          >
            {images.map((item, idx) => (
              <View
                key={item.id || `img-${idx}`}
                testID={`${testID}-slide-${idx}`}
                style={[styles.slide, { width: windowWidth, height: windowHeight * 0.72 }]}
              >
                <TouchableOpacity
                  activeOpacity={1}
                  onPress={() => applyZoom(zoomScale === 1 ? 2 : 1)}
                  style={styles.imageTapArea}
                >
                  <Animated.View
                    style={[
                      styles.imageWrap,
                      idx === activeIndex ? { transform: [{ scale: zoomAnim }] } : null,
                    ]}
                  >
                    <Image
                      source={item.source}
                      resizeMode="contain"
                      style={{
                        width: windowWidth - 32,
                        height: windowHeight * 0.65,
                      }}
                    />
                  </Animated.View>
                </TouchableOpacity>
              </View>
            ))}
          </ScrollView>

          {/* Left / Right Swipe Arrows */}
          {images.length > 1 && activeIndex > 0 ? (
            <TouchableOpacity
              testID={`${testID}-prev-btn`}
              style={[styles.navArrow, styles.navLeft]}
              activeOpacity={0.75}
              onPress={() => goToIndex(activeIndex - 1)}
            >
              <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                <Path
                  d="M15 19L8 12L15 5"
                  stroke="#FFFFFF"
                  strokeWidth={2.4}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </Svg>
            </TouchableOpacity>
          ) : null}

          {images.length > 1 && activeIndex < images.length - 1 ? (
            <TouchableOpacity
              testID={`${testID}-next-btn`}
              style={[styles.navArrow, styles.navRight]}
              activeOpacity={0.75}
              onPress={() => goToIndex(activeIndex + 1)}
            >
              <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                <Path
                  d="M9 5L16 12L9 19"
                  stroke="#FFFFFF"
                  strokeWidth={2.4}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </Svg>
            </TouchableOpacity>
          ) : null}
        </Animated.View>

        {/* Bottom Caption */}
        {(currentItem.title || currentItem.caption) ? (
          <View style={styles.captionBar}>
            {currentItem.title ? (
              <Text style={styles.captionTitle}>{currentItem.title}</Text>
            ) : null}
            {currentItem.caption ? (
              <Text style={styles.captionText}>{currentItem.caption}</Text>
            ) : null}
          </View>
        ) : null}
      </Animated.View>
    </Modal>
  );
};

