import React, { useState } from 'react';
import { View, Text, TouchableOpacity, StyleSheet } from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { CalendarIcon } from '@mfe/assets/icons/PickerIcons';
import { AppAlertModal } from '../../modals/AppAlertModal';
import { AppBottomSheet } from '../../modals/AppBottomSheet';
import { CalendarView, CalendarLocale } from './CalendarView';

export type PresentationMode = 'alert' | 'bottomsheet';
export type DateSelectionMode = 'day' | 'range' | 'week';

export interface DatePickerFieldProps {
  label: string;
  value?: string; // YYYY-MM-DD (for day mode)
  startDate?: string; // YYYY-MM-DD (for range / week mode)
  endDate?: string; // YYYY-MM-DD (for range / week mode)
  selectionMode?: DateSelectionMode; // 'day' | 'range' | 'week'
  presentation?: PresentationMode; // 'alert' | 'bottomsheet'
  locale?: CalendarLocale;
  minDate?: string; // YYYY-MM-DD
  maxDate?: string; // YYYY-MM-DD
  holidays?: string[]; // Array of 'YYYY-MM-DD'
  highlightSundays?: boolean;
  disabledDates?: string[]; // Array of 'YYYY-MM-DD'
  onChangeDay?: (date: string) => void;
  onChangeDate?: (date: string) => void;
  onChangeRange?: (start: string, end: string) => void;
  error?: string;
  placeholder?: string;
  testID?: string;
}

export const DatePickerField: React.FC<DatePickerFieldProps> = ({
  label,
  value,
  startDate,
  endDate,
  selectionMode = 'day',
  presentation = 'alert',
  locale,
  minDate,
  maxDate,
  holidays = [],
  highlightSundays = true,
  disabledDates = [],
  onChangeDay,
  onChangeDate,
  onChangeRange,
  error,
  placeholder,
  testID = 'date-picker-field',
}) => {
  const { theme } = useTheme();
  const [modalVisible, setModalVisible] = useState(false);

  const formatDisplayValue = () => {
    if (selectionMode === 'day') {
      return value || placeholder || 'Select Date (YYYY-MM-DD)';
    }
    if (selectionMode === 'week') {
      return startDate && endDate
        ? `Week: ${startDate} ~ ${endDate}`
        : placeholder || 'Select a Week';
    }
    return startDate || endDate
      ? `${startDate || 'Start'} ~ ${endDate || 'End'}`
      : placeholder || 'Select Date Range';
  };

  const calendarContent = (
    <CalendarView
      selectionMode={selectionMode}
      locale={locale}
      startDate={selectionMode === 'day' ? value || '' : startDate || ''}
      endDate={selectionMode === 'day' ? value || '' : endDate || ''}
      minDate={minDate}
      maxDate={maxDate}
      holidays={holidays}
      disabledDates={disabledDates}
      highlightSundays={highlightSundays}
      accentColor={theme.colors.primary}
      showConfirmButton={selectionMode === 'range'}
      onSelectDate={(start, end) => {
        if (selectionMode === 'day') {
          onChangeDay?.(start);
          onChangeDate?.(start);
          setModalVisible(false);
        } else if (selectionMode === 'week') {
          onChangeRange?.(start, end);
          setModalVisible(false);
        }
      }}
      onConfirm={(start, end) => {
        onChangeRange?.(start, end);
        setModalVisible(false);
      }}
      onCancel={() => setModalVisible(false)}
      testID={testID}
    />
  );

  return (
    <View testID={testID} style={styles.container}>
      <Text style={styles.label}>{label}</Text>

      <View style={[styles.inputGroup, error ? styles.inputError : null]}>
        <Text style={[styles.valueText, !value && !startDate && styles.placeholderText]}>
          {formatDisplayValue()}
        </Text>

        <TouchableOpacity
          testID={`${testID}-trigger`}
          style={styles.calendarBtn}
          onPress={() => setModalVisible(true)}
          activeOpacity={0.7}
        >
          <CalendarIcon size={20} color={theme.colors.primary} />
        </TouchableOpacity>
      </View>

      {error ? <Text style={styles.errorText}>{error}</Text> : null}

      {presentation === 'bottomsheet' ? (
        <AppBottomSheet
          visible={modalVisible}
          showHeader={false}
          onClose={() => setModalVisible(false)}
          testID={`${testID}-bottom-sheet`}
        >
          {calendarContent}
        </AppBottomSheet>
      ) : (
        <AppAlertModal
          visible={modalVisible}
          showHeader={false}
          maxWidth={360}
          onClose={() => setModalVisible(false)}
          testID={`${testID}-alert-modal`}
        >
          {calendarContent}
        </AppAlertModal>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    marginVertical: 6,
  },
  label: {
    fontSize: 13,
    fontWeight: '600',
    color: '#333333',
    marginBottom: 6,
  },
  inputGroup: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    height: 48,
    borderWidth: 1,
    borderColor: '#DDDDDD',
    borderRadius: 8,
    backgroundColor: '#FFFFFF',
    paddingHorizontal: 14,
  },
  inputError: {
    borderColor: '#DC2626',
  },
  valueText: {
    flex: 1,
    fontSize: 14,
    color: '#111827',
  },
  placeholderText: {
    color: '#9CA3AF',
  },
  calendarBtn: {
    paddingLeft: 10,
    paddingVertical: 6,
    alignItems: 'center',
    justifyContent: 'center',
  },
  errorText: {
    fontSize: 12,
    color: '#DC2626',
    marginTop: 4,
  },
});
