import React, { useState, useMemo } from 'react';
import { View, StyleSheet, Text } from 'react-native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { SplashScreen } from '../views/SplashScreen';
import { ChooseLanguageScreen } from '../views/ChooseLanguageScreen';
import { TermsAndConditionsScreen } from '../views/TermsAndConditionsScreen';
import { ILaunchService, LaunchService } from '../services/LaunchService';
import { SupportedLanguage } from '../models/LaunchModel';
import { LaunchColors, LaunchTypography } from '../theme/tokens';
import { useI18n } from '@mfe/core/i18n';
import { LaunchStackParamList } from './LaunchNavigationTypes';

export type LaunchScreenName = 'ChooseLanguage' | 'Terms' | 'MainApp';

export interface LaunchNavigatorProps {
  launchService?: ILaunchService;
  initialScreen?: LaunchScreenName;
  onFlowComplete?: () => void;
  navigation?: any;
}

const Stack = createNativeStackNavigator<LaunchStackParamList>();

export const LaunchNavigator: React.FC<LaunchNavigatorProps> = ({
  launchService: propLaunchService,
  initialScreen = 'ChooseLanguage',
  onFlowComplete,
  navigation: rootNavigation,
}) => {
  const launchService = useMemo(
    () => propLaunchService || new LaunchService(),
    [propLaunchService]
  );
  const { language: currentGlobalLang, setLanguage: setGlobalLanguage } = useI18n();
  const [selectedLanguage, setSelectedLanguage] =
    useState<SupportedLanguage>(currentGlobalLang || 'km');

  const handleFinishOnboarding = (nav: any) => {
    if (onFlowComplete) {
      onFlowComplete();
    }
    // Terminal onboarding boundary: reset root history to AuthFlow so user CANNOT back into onboarding
    const rootNav = rootNavigation || (nav && nav.getParent && nav.getParent());
    if (rootNav && rootNav.reset) {
      rootNav.reset({
        index: 0,
        routes: [{ name: 'AuthFlow' }],
      });
    } else if (rootNav && rootNav.navigate) {
      rootNav.navigate('AuthFlow');
    } else if (nav && nav.navigate) {
      nav.navigate('MainAppPlaceholder');
    }
  };

  return (
    <View testID="launch-navigator" style={styles.container}>
      <Stack.Navigator
        initialRouteName={initialScreen === 'Terms' ? 'TermsAndConditions' : (initialScreen as any)}
        screenOptions={{
          headerShown: false,
          animation: 'default',
          gestureEnabled: true,
          fullScreenGestureEnabled: false,
        }}
      >
        <Stack.Screen
          name="ChooseLanguage"
          options={{ gestureEnabled: false }}
        >
          {({ navigation }) => (
            <ChooseLanguageScreen
              viewModelProps={{
                launchService,
                onProceed: (lang) => {
                  setSelectedLanguage(lang);
                  setGlobalLanguage(lang);
                  navigation.navigate('TermsAndConditions', { language: lang });
                },
                onSkip: () => navigation.navigate('TermsAndConditions', { language: selectedLanguage }),
              }}
            />
          )}
        </Stack.Screen>

        <Stack.Screen
          name="TermsAndConditions"
          options={{ gestureEnabled: true }}
        >
          {({ navigation }) => (
            <TermsAndConditionsScreen
              viewModelProps={{
                launchService,
                language: selectedLanguage,
                onAgreeSuccess: () => handleFinishOnboarding(navigation),
                onCancel: () => navigation.goBack(),
                onSkip: () => handleFinishOnboarding(navigation),
              }}
            />
          )}
        </Stack.Screen>

        <Stack.Screen
          name="MainAppPlaceholder"
          options={{ gestureEnabled: false }}
        >
          {() => (
            <View testID="main-app-placeholder" style={styles.mainAppContainer}>
              <Text style={styles.mainAppTitle}>Welcome to LOS</Text>
              <Text style={styles.mainAppSubtitle}>
                Launch process flow completed successfully!
              </Text>
              <Text style={styles.mainAppLang}>
                Active Language: {selectedLanguage.toUpperCase()}
              </Text>
            </View>
          )}
        </Stack.Screen>
      </Stack.Navigator>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: LaunchColors.background,
  },
  mainAppContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    padding: 24,
    backgroundColor: LaunchColors.background,
  },
  mainAppTitle: {
    fontSize: 24,
    fontFamily: LaunchTypography.fontFamilyBold,
    color: LaunchColors.primary,
    marginBottom: 8,
  },
  mainAppSubtitle: {
    fontSize: 14,
    fontFamily: LaunchTypography.fontFamilyRegular,
    color: LaunchColors.textSecondary,
    textAlign: 'center',
    marginBottom: 16,
  },
  mainAppLang: {
    fontSize: 12,
    fontFamily: LaunchTypography.fontFamilyMedium,
    color: LaunchColors.primary,
    backgroundColor: LaunchColors.surface,
    paddingHorizontal: 12,
    paddingVertical: 6,
    borderRadius: 8,
    borderWidth: 1,
    borderColor: LaunchColors.border,
  },
});
