import React from 'react';
import {
  View,
  Text,
  ActivityIndicator,
  StyleSheet,
  ViewStyle,
  Platform,
} from 'react-native';

export type SpinnerSize = 'small' | 'large' | number;

export interface AppSpinnerProps {
  size?: SpinnerSize;
  color?: string; // Default: Lotte Red #E5252A or Primary Blue
  message?: string;
  subMessage?: string;
  inline?: boolean; // If true, displays horizontally side-by-side
  style?: ViewStyle;
  testID?: string;
}

/**
 * Universal Enterprise Spinner / Loading indicator component.
 * Can be used inline inside cards, buttons, or content areas.
 */
export const AppSpinner: React.FC<AppSpinnerProps> = ({
  size = 'large',
  color = '#E5252A',
  message,
  subMessage,
  inline = false,
  style,
  testID = 'app-spinner',
}) => {
  const isNumericSize = typeof size === 'number';
  const indicatorSize = isNumericSize ? 'large' : size;

  return (
    <View
      style={[
        styles.container,
        inline ? styles.inlineRow : styles.verticalColumn,
        style,
      ]}
      testID={testID}
    >
      <ActivityIndicator
        size={indicatorSize}
        color={color}
        testID={`${testID}-indicator`}
      />

      {(message || subMessage) && (
        <View
          style={[
            styles.textContainer,
            inline ? styles.inlineTextMargin : styles.verticalTextMargin,
          ]}
        >
          {message ? (
            <Text
              style={[styles.messageText, inline && styles.inlineMessage]}
              testID={`${testID}-message`}
            >
              {message}
            </Text>
          ) : null}
          {subMessage ? (
            <Text style={styles.subMessageText} testID={`${testID}-submessage`}>
              {subMessage}
            </Text>
          ) : null}
        </View>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    justifyContent: 'center',
    padding: 12,
  },
  verticalColumn: {
    flexDirection: 'column',
  },
  inlineRow: {
    flexDirection: 'row',
  },
  textContainer: {
    alignItems: 'center',
  },
  verticalTextMargin: {
    marginTop: 12,
  },
  inlineTextMargin: {
    marginLeft: 10,
    alignItems: 'flex-start',
  },
  messageText: {
    fontSize: 14,
    fontWeight: '600',
    color: '#1F2937',
    textAlign: 'center',
  },
  inlineMessage: {
    textAlign: 'left',
  },
  subMessageText: {
    fontSize: 12,
    color: '#6B7280',
    marginTop: 3,
    textAlign: 'center',
  },
});
