/**
 * CurrencyWordsUtil: Converts numbers and loan amounts into formal words
 * for contracts, promissory notes, and disbursement receipts.
 * Supports Vietnamese (đồng), English (USD / currency units), and Khmer (Riel).
 */

export class CurrencyWordsUtil {
  private static readonly VI_DIGITS = [
    'không',
    'một',
    'hai',
    'ba',
    'bốn',
    'năm',
    'sáu',
    'bảy',
    'tám',
    'chín',
  ];

  private static readonly EN_ONES = [
    '',
    'One',
    'Two',
    'Three',
    'Four',
    'Five',
    'Six',
    'Seven',
    'Eight',
    'Nine',
    'Ten',
    'Eleven',
    'Twelve',
    'Thirteen',
    'Fourteen',
    'Fifteen',
    'Sixteen',
    'Seventeen',
    'Eighteen',
    'Nineteen',
  ];

  private static readonly EN_TENS = [
    '',
    '',
    'Twenty',
    'Thirty',
    'Forty',
    'Fifty',
    'Sixty',
    'Seventy',
    'Eighty',
    'Ninety',
  ];

  /**
   * Converts numeric amount into Vietnamese currency in words:
   * e.g., 50,000,000 -> "Năm mươi triệu đồng chẵn"
   */
  public static toVietnameseWords(amount: number): string {
    if (!Number.isFinite(amount) || amount === 0) {
      return 'Không đồng';
    }

    const absAmount = Math.floor(Math.abs(amount));
    if (absAmount === 0) return 'Không đồng';

    const groups: number[] = [];
    let temp = absAmount;
    while (temp > 0) {
      groups.push(temp % 1000);
      temp = Math.floor(temp / 1000);
    }

    const groupNames = ['', 'nghìn', 'triệu', 'tỷ', 'nghìn tỷ', 'triệu tỷ'];
    const parts: string[] = [];

    for (let i = groups.length - 1; i >= 0; i--) {
      const g = groups[i];
      if (g > 0) {
        const text = this.readThreeDigitsVi(g, i < groups.length - 1);
        parts.push(`${text} ${groupNames[i]}`.trim());
      }
    }

    const result = parts.join(' ').replace(/\s+/g, ' ').trim();
    // Capitalize first letter and append currency suffix
    const capitalized = result.charAt(0).toUpperCase() + result.slice(1);
    return `${capitalized} đồng chẵn`;
  }

  private static readThreeDigitsVi(num: number, full: boolean): string {
    const hundred = Math.floor(num / 100);
    const remainder = num % 100;
    const ten = Math.floor(remainder / 10);
    const one = remainder % 10;
    let res = '';

    if (hundred > 0 || full) {
      res += `${this.VI_DIGITS[hundred]} trăm `;
    }

    if (ten > 1) {
      res += `${this.VI_DIGITS[ten]} mươi `;
      if (one === 1) res += 'mốt ';
      else if (one === 5) res += 'lăm ';
      else if (one > 0) res += `${this.VI_DIGITS[one]} `;
    } else if (ten === 1) {
      res += 'mười ';
      if (one === 5) res += 'lăm ';
      else if (one > 0) res += `${this.VI_DIGITS[one]} `;
    } else if (ten === 0 && one > 0) {
      if (hundred > 0 || full) res += 'lẻ ';
      res += `${this.VI_DIGITS[one]} `;
    }

    return res.trim();
  }

  /**
   * Converts numeric amount into English words:
   * e.g., 50000 -> "Fifty Thousand Dollars"
   */
  public static toEnglishWords(
    amount: number,
    currencySuffix: string = 'Dollars'
  ): string {
    if (!Number.isFinite(amount) || amount === 0) {
      return `Zero ${currencySuffix}`;
    }

    const absAmount = Math.floor(Math.abs(amount));
    const words = this.convertNumberToEnglish(absAmount).trim();
    return `${words} ${currencySuffix}`.trim();
  }

  private static convertNumberToEnglish(num: number): string {
    if (num === 0) return '';
    if (num < 20) return this.EN_ONES[num];
    if (num < 100) {
      return `${this.EN_TENS[Math.floor(num / 10)]} ${this.EN_ONES[num % 10]}`.trim();
    }
    if (num < 1000) {
      return `${this.EN_ONES[Math.floor(num / 100)]} Hundred ${this.convertNumberToEnglish(num % 100)}`.trim();
    }
    if (num < 1_000_000) {
      return `${this.convertNumberToEnglish(Math.floor(num / 1000))} Thousand ${this.convertNumberToEnglish(num % 1000)}`.trim();
    }
    if (num < 1_000_000_000) {
      return `${this.convertNumberToEnglish(Math.floor(num / 1_000_000))} Million ${this.convertNumberToEnglish(num % 1_000_000)}`.trim();
    }
    return `${this.convertNumberToEnglish(Math.floor(num / 1_000_000_000))} Billion ${this.convertNumberToEnglish(num % 1_000_000_000)}`.trim();
  }

  /**
   * Dispatches currency conversion based on currency code (VND, USD, KHR).
   */
  public static toWords(
    amount: number,
    currency: 'VND' | 'USD' | 'KHR' = 'VND'
  ): string {
    switch (currency) {
      case 'VND':
        return this.toVietnameseWords(amount);
      case 'USD':
        return this.toEnglishWords(amount, 'US Dollars');
      case 'KHR':
        return this.toEnglishWords(amount, 'Khmer Riels');
      default:
        return this.toVietnameseWords(amount);
    }
  }
}

