import React from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  Modal,
  Platform,
} from 'react-native';
import { DraftActionChoice } from '@mfe/core/utils/draftPromptUtil';

export interface UnsavedChangesModalProps {
  visible: boolean;
  title?: string;
  message?: string;
  /** Label for Continue Editing, default: 'Tiếp tục chỉnh sửa' */
  continueLabel?: string;
  /** Label for Save to Draft, default: 'Lưu bản nháp' */
  saveDraftLabel?: string;
  /** Label for Leave without saving, default: 'Rời khỏi trang' */
  leaveLabel?: string;
  onChoice: (choice: DraftActionChoice) => void;
  onDismiss?: () => void;
  testID?: string;
}

/**
 * Enterprise Unsaved Changes & Draft Prompt Modal.
 * Prompts user when attempting to navigate away from an incomplete form:
 * - Title: "Chưa hoàn tất nhập thông tin" ("You haven't finished inputting all information yet")
 * - 3 Options:
 *   1. "Tiếp tục" (Continue editing)
 *   2. "Lưu bản nháp" (Save to draft)
 *   3. "Rời khỏi" (Leave without saving)
 */
export const UnsavedChangesModal: React.FC<UnsavedChangesModalProps> = ({
  visible,
  title = 'Chưa hoàn tất nhập thông tin',
  message = 'Bạn có thông tin đang nhập dở. Bạn muốn tiếp tục hoàn thiện, lưu bản nháp để tiếp tục sau, hay rời khỏi trang?',
  continueLabel = 'Tiếp tục chỉnh sửa',
  saveDraftLabel = 'Lưu bản nháp',
  leaveLabel = 'Rời khỏi trang',
  onChoice,
  onDismiss,
  testID = 'unsaved-changes-modal',
}) => {
  if (!visible) return null;

  const handleDismiss = () => {
    if (onDismiss) {
      onDismiss();
    } else {
      onChoice('continue');
    }
  };

  return (
    <Modal
      visible={visible}
      transparent={true}
      animationType="fade"
      onRequestClose={handleDismiss}
    >
      <View style={styles.backdrop} testID={testID}>
        <TouchableOpacity
          activeOpacity={1}
          style={styles.backdropDismiss}
          onPress={handleDismiss}
          testID={`${testID}-backdrop-dismiss`}
        />

        <View style={styles.cardContainer} testID={`${testID}-card`}>
          {/* Warning Icon Badge */}
          <View style={styles.iconCircle}>
            <Text style={styles.iconExclamation}>!</Text>
          </View>

          {/* Title */}
          <Text style={styles.titleText} testID={`${testID}-title`}>
            {title}
          </Text>

          {/* Message */}
          <Text style={styles.messageText} testID={`${testID}-message`}>
            {message}
          </Text>

          {/* Action Button 1: Save to Draft (Primary / Recommended) */}
          <TouchableOpacity
            activeOpacity={0.85}
            style={styles.saveDraftButton}
            onPress={() => onChoice('save_draft')}
            testID={`${testID}-save-draft-btn`}
          >
            <Text style={styles.saveDraftText}>💾 {saveDraftLabel}</Text>
          </TouchableOpacity>

          {/* Action Button 2: Continue Editing */}
          <TouchableOpacity
            activeOpacity={0.8}
            style={styles.continueButton}
            onPress={() => onChoice('continue')}
            testID={`${testID}-continue-btn`}
          >
            <Text style={styles.continueText}>{continueLabel}</Text>
          </TouchableOpacity>

          {/* Action Button 3: Leave without saving (Destructive / Muted) */}
          <TouchableOpacity
            activeOpacity={0.7}
            style={styles.leaveButton}
            onPress={() => onChoice('leave')}
            testID={`${testID}-leave-btn`}
          >
            <Text style={styles.leaveText}>{leaveLabel}</Text>
          </TouchableOpacity>
        </View>
      </View>
    </Modal>
  );
};

