import React from 'react';
import { View, Text, StyleSheet } from 'react-native';
import { AppButton } from '../button/AppButton';

export interface EmptyStateProps {
  icon?: string;
  title: string;
  message?: string;
  actionTitle?: string;
  onAction?: () => void;
  testID?: string;
}

export const EmptyState: React.FC<EmptyStateProps> = ({
  icon = '📂',
  title,
  message,
  actionTitle,
  onAction,
  testID = 'empty-state',
}) => {
  return (
    <View testID={testID} style={styles.container}>
      <Text style={styles.icon}>{icon}</Text>
      <Text style={styles.title}>{title}</Text>
      {message ? <Text style={styles.message}>{message}</Text> : null}
      {actionTitle && onAction ? (
        <View style={styles.actionWrapper}>
          <AppButton
            title={actionTitle}
            variant="outline"
            size="small"
            onPress={onAction}
            testID={`${testID}-action-btn`}
          />
        </View>
      ) : null}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    justifyContent: 'center',
    paddingVertical: 32,
    paddingHorizontal: 20,
    backgroundColor: '#FFFFFF',
    borderRadius: 12,
    borderWidth: 1,
    borderColor: '#E2E5EB',
    borderStyle: 'dashed',
    marginVertical: 8,
  },
  icon: {
    fontSize: 40,
    marginBottom: 10,
  },
  title: {
    fontSize: 16,
    fontWeight: '700',
    color: '#16181D',
    textAlign: 'center',
    marginBottom: 4,
  },
  message: {
    fontSize: 13,
    color: '#7B8494',
    textAlign: 'center',
    lineHeight: 18,
    maxWidth: 280,
  },
  actionWrapper: {
    marginTop: 14,
  },
});

