import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  ScrollView,
  Platform,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useNavigation, useRoute } from '@react-navigation/native';
import Svg, { Path } from 'react-native-svg';
import { ProcessCheckList, ProcessCheckItem } from '@mfe/ui-components/components/feedback/ProcessCheckList';
import { AppButton } from '@mfe/ui-components/components/button/AppButton';

export interface CustomerVerificationCheckScreenProps {
  title?: string;
  description?: string;
  onBackPress?: () => void;
  onComplete?: () => void;
  testID?: string;
}

export const CustomerVerificationCheckScreen: React.FC<CustomerVerificationCheckScreenProps> = ({
  title = 'Checking customer information',
  description = 'The system is checking the customer information.\nPlease wait a moment for the check to complete.',
  onBackPress,
  onComplete,
  testID = 'customer-verification-check-screen',
}) => {
  const navigation = useNavigation<any>();
  const route = useRoute<any>();

  const [items, setItems] = useState<ProcessCheckItem[]>([
    {
      id: 'screening',
      label: 'Automatic screening result',
      status: 'completed',
      resultText: 'Passed',
    },
    {
      id: 'existing',
      label: 'Existing application check result',
      status: 'completed',
    },
    {
      id: 'submitting',
      label: 'Sending loan application for preliminary screening',
      status: 'in_progress',
    },
  ]);

  const [isFinished, setIsFinished] = useState(false);

  // Simulate progress transition from in_progress to completed after 3s
  useEffect(() => {
    const timer = setTimeout(() => {
      setItems((prev) =>
        prev.map((item) =>
          item.id === 'submitting'
            ? { ...item, status: 'completed', resultText: 'Complete' }
            : item
        )
      );
      setIsFinished(true);
      if (onComplete) {
        onComplete();
      }
    }, 3500);

    return () => clearTimeout(timer);
  }, [onComplete]);

  const handleBack = () => {
    if (onBackPress) {
      onBackPress();
    } else if (navigation?.canGoBack && navigation.canGoBack()) {
      navigation.goBack();
    }
  };

  return (
    <SafeAreaView
      style={styles.container}
      edges={['top', 'left', 'right', 'bottom']}
      testID={testID}
    >
      {/* Header with back navigation chevron */}
      <View style={styles.header}>
        <TouchableOpacity
          testID={`${testID}-back-btn`}
          onPress={handleBack}
          style={styles.backButton}
          activeOpacity={0.7}
          hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
        >
          <Svg width={24} height={24} viewBox="0 0 24 24" fill="none">
            <Path
              d="M15 19L8 12L15 5"
              stroke="#0F172A"
              strokeWidth={2.4}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </Svg>
        </TouchableOpacity>
        <Text style={styles.headerTitle}>Verification Status</Text>
        <View style={styles.headerRightPlaceholder} />
      </View>

      <ScrollView
        contentContainerStyle={styles.contentContainer}
        showsVerticalScrollIndicator={false}
      >
        <View style={styles.cardContainer}>
          <ProcessCheckList
            title={title}
            description={description}
            items={items}
            animated={!isFinished}
            iconSize={64}
            testID={`${testID}-process-list`}
          />
        </View>

        {isFinished && (
          <View style={styles.actionContainer}>
            <AppButton
              testID={`${testID}-continue-btn`}
              title="Continue to Loan Offer"
              variant="primary"
              size="large"
              onPress={handleBack}
            />
          </View>
        )}
      </ScrollView>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#FFFFFF',
  },
  header: {
    height: 52,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 16,
    borderBottomWidth: StyleSheet.hairlineWidth,
    borderBottomColor: '#F1F5F9',
  },
  backButton: {
    width: 40,
    height: 40,
    alignItems: 'center',
    justifyContent: 'center',
  },
  headerTitle: {
    fontSize: 17,
    fontWeight: '600',
    color: '#0F172A',
  },
  headerRightPlaceholder: {
    width: 40,
  },
  contentContainer: {
    flexGrow: 1,
    justifyContent: 'center',
    paddingHorizontal: 20,
    paddingVertical: 32,
  },
  cardContainer: {
    width: '100%',
    alignItems: 'center',
  },
  actionContainer: {
    marginTop: 40,
    width: '100%',
    paddingHorizontal: 12,
  },
});
