import React, { useState, useEffect } from 'react';
import {
  DraftPromptUtil,
  UnsavedChangesPromptOptions,
  DraftActionChoice,
} from '@mfe/core/utils/draftPromptUtil';
import { UnsavedChangesModal } from './UnsavedChangesModal';

export interface GlobalDraftPromptHostProps {
  testID?: string;
}

/**
 * Global Host/Root component for Draft Prompting.
 * Listens to `DraftPromptUtil.prompt()` calls from any screen or navigation interceptor,
 * rendering the 3-option UnsavedChangesModal automatically.
 */
export const GlobalDraftPromptHost: React.FC<GlobalDraftPromptHostProps> = ({
  testID = 'global-draft-prompt-host',
}) => {
  const [promptOptions, setPromptOptions] = useState<UnsavedChangesPromptOptions | null>(null);
  const [resolver, setResolver] = useState<((choice: DraftActionChoice) => void) | null>(null);

  useEffect(() => {
    const unsubscribe = DraftPromptUtil.subscribe((options, resolveFn) => {
      setPromptOptions(options);
      setResolver(() => resolveFn || null);
    });
    return () => {
      unsubscribe();
    };
  }, []);

  if (!promptOptions || !resolver) {
    return null;
  }

  return (
    <UnsavedChangesModal
      visible={true}
      title={promptOptions.title}
      message={promptOptions.message}
      continueLabel={promptOptions.continueLabel}
      saveDraftLabel={promptOptions.saveDraftLabel}
      leaveLabel={promptOptions.leaveLabel}
      onChoice={(choice) => {
        resolver(choice);
      }}
      onDismiss={() => {
        resolver('continue');
      }}
      testID={testID}
    />
  );
};
