import React, { useEffect, useRef } from 'react';
import {
  View,
  StyleSheet,
  Animated,
  ViewStyle,
  StyleProp,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export interface SkeletonProps {
  /**
   * Width of the skeleton bar (e.g. 100, '100%', 60). Defaults to '100%'.
   */
  width?: number | string;
  /**
   * Height of the skeleton bar. Defaults to 16.
   */
  height?: number;
  /**
   * Border radius. Defaults to 4 (or rounded pill if round=true).
   */
  borderRadius?: number;
  /**
   * Whether to make it circular (e.g., avatar placeholder).
   */
  circle?: boolean;
  /**
   * Optional custom style.
   */
  style?: StyleProp<ViewStyle>;
  testID?: string;
}

/**
 * Universal Skeleton Loader with animated shimmering opacity loop.
 */
export const AppSkeleton: React.FC<SkeletonProps> = ({
  width = '100%',
  height = 16,
  borderRadius = 4,
  circle = false,
  style,
  testID = 'app-skeleton',
}) => {
  const { theme } = useTheme();
  const shimmerAnim = useRef(new Animated.Value(0.3)).current;

  useEffect(() => {
    const animation = Animated.loop(
      Animated.sequence([
        Animated.timing(shimmerAnim, {
          toValue: 0.9,
          duration: 750,
          useNativeDriver: true,
        }),
        Animated.timing(shimmerAnim, {
          toValue: 0.3,
          duration: 750,
          useNativeDriver: true,
        }),
      ])
    );
    animation.start();

    return () => animation.stop();
  }, [shimmerAnim]);

  const finalHeight = circle && typeof width === 'number' ? width : height;
  const finalRadius = circle
    ? typeof width === 'number'
      ? width / 2
      : height / 2
    : borderRadius;

  return (
    <Animated.View
      testID={testID}
      style={[
        styles.skeletonBase,
        {
          width: width as any,
          height: finalHeight,
          borderRadius: finalRadius,
          backgroundColor: theme.colors.border || '#E5E7EB',
          opacity: shimmerAnim,
        },
        style,
      ]}
    />
  );
};

export interface SkeletonListProps {
  rows?: number;
  showHeader?: boolean;
  style?: StyleProp<ViewStyle>;
  testID?: string;
}

/**
 * Preset Skeleton Group matching DBCS LOS bm-skeleton.vue (header badge + key-value rows).
 */
export const SkeletonList: React.FC<SkeletonListProps> = ({
  rows = 3,
  showHeader = true,
  style,
  testID = 'skeleton-list',
}) => {
  return (
    <View testID={testID} style={[styles.listContainer, style]}>
      {showHeader ? (
        <View style={styles.headerRow}>
          <AppSkeleton width={70} height={24} borderRadius={12} testID={`${testID}-header`} />
        </View>
      ) : null}

      <View style={styles.rowsWrapper}>
        {Array.from({ length: rows }).map((_, index) => (
          <View key={`row-${index}`} style={styles.rowItem} testID={`${testID}-row-${index}`}>
            <AppSkeleton width={90} height={14} />
            <AppSkeleton width={130} height={16} />
          </View>
        ))}
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  skeletonBase: {
    overflow: 'hidden',
  },
  listContainer: {
    width: '100%',
    paddingVertical: 8,
  },
  headerRow: {
    marginBottom: 14,
  },
  rowsWrapper: {
    gap: 12,
  },
  rowItem: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    paddingVertical: 4,
  },
});

