import React, { useState, useEffect } from 'react';
import {
  StyleProp,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
  ViewStyle,
} from 'react-native';
import Svg, { Path } from 'react-native-svg';
import { useTheme, defaultTheme } from '@mfe/theme';

export const DEFAULT_COLOR_SWATCHES: string[] = [
  '#E7252B', // LOTTE Red
  '#DC2626',
  '#EA580C',
  '#D97706',
  '#117A4D', // Enterprise Green
  '#059669',
  '#0D9488',
  '#1F5FA8', // Ocean Blue
  '#2563EB',
  '#4F46E5',
  '#7C3AED',
  '#2C213F', // Brand Dark Plum
  '#16181D',
  '#4D5563',
  '#94A3B8',
];

const HEX_COLOR_REGEX = /^#([0-9A-Fa-f]{6})$/;

function isLightColor(hex: string): boolean {
  const clean = hex.replace('#', '');
  if (clean.length !== 6) return false;
  const r = parseInt(clean.slice(0, 2), 16);
  const g = parseInt(clean.slice(2, 4), 16);
  const b = parseInt(clean.slice(4, 6), 16);
  const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return luminance > 0.72;
}

export interface ColorPickerProps {
  label?: string;
  value: string;
  onChange: (hex: string) => void;
  colors?: string[];
  allowCustomHex?: boolean;
  swatchSize?: number;
  style?: StyleProp<ViewStyle>;
  testID?: string;
}

export const ColorPicker: React.FC<ColorPickerProps> = ({
  label,
  value,
  onChange,
  colors = DEFAULT_COLOR_SWATCHES,
  allowCustomHex = true,
  swatchSize = 38,
  style,
  testID = 'color-picker',
}) => {
  const themeContext = useTheme();
  const theme = themeContext?.theme || defaultTheme;
  const { colors: themeColors, radius, spacing } = theme;

  const normalizedValue = value.toUpperCase();
  const [hexInput, setHexInput] = useState(normalizedValue);

  useEffect(() => {
    setHexInput(value.toUpperCase());
  }, [value]);

  const handleHexChange = (raw: string) => {
    let cleaned = raw.trim().toUpperCase();
    if (cleaned && !cleaned.startsWith('#')) {
      cleaned = `#${cleaned}`;
    }
    if (cleaned.length <= 7) {
      setHexInput(cleaned);
      if (HEX_COLOR_REGEX.test(cleaned)) {
        onChange(cleaned);
      }
    }
  };

  return (
    <View testID={testID} style={[styles.container, style]}>
      {label ? (
        <View style={[styles.headerRow, { marginBottom: spacing.sm }]}>
          <Text style={[styles.label, { color: themeColors.text }]}>{label}</Text>
          <View style={styles.previewBadge}>
            <View
              testID={`${testID}-preview`}
              style={[
                styles.previewDot,
                { backgroundColor: value, borderColor: themeColors.border },
              ]}
            />
            <Text style={[styles.previewHex, { color: themeColors.textMuted }]}>
              {normalizedValue}
            </Text>
          </View>
        </View>
      ) : null}

      {/* Swatch Grid */}
      <View testID={`${testID}-swatches`} style={styles.swatchGrid}>
        {colors.map((swatch) => {
          const upper = swatch.toUpperCase();
          const isSelected = upper === normalizedValue;
          const checkColor = isLightColor(upper) ? '#16181D' : '#FFFFFF';

          return (
            <TouchableOpacity
              key={upper}
              testID={`${testID}-swatch-${upper.replace('#', '')}`}
              accessibilityRole="button"
              accessibilityLabel={`Select color ${upper}`}
              accessibilityState={{ selected: isSelected }}
              activeOpacity={0.8}
              onPress={() => onChange(upper)}
              style={[
                styles.swatch,
                {
                  width: swatchSize,
                  height: swatchSize,
                  borderRadius: radius.full,
                  backgroundColor: upper,
                  borderColor: isSelected ? themeColors.text : themeColors.border,
                  borderWidth: isSelected ? 2.5 : 1,
                },
              ]}
            >
              {isSelected ? (
                <Svg width={16} height={16} viewBox="0 0 24 24" fill="none">
                  <Path
                    d="M5 13L9 17L19 7"
                    stroke={checkColor}
                    strokeWidth={2.8}
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </Svg>
              ) : null}
            </TouchableOpacity>
          );
        })}
      </View>

      {/* Custom Hex Input */}
      {allowCustomHex ? (
        <View style={[styles.hexRow, { marginTop: spacing.md }]}>
          <View
            style={[
              styles.hexSwatch,
              {
                backgroundColor: HEX_COLOR_REGEX.test(hexInput) ? hexInput : value,
                borderColor: themeColors.border,
                borderRadius: radius.sm,
              },
            ]}
          />
          <TextInput
            testID={`${testID}-hex-input`}
            value={hexInput}
            onChangeText={handleHexChange}
            placeholder="#E7252B"
            placeholderTextColor={themeColors.textSubtle}
            keyboardType="default"
            autoCapitalize="characters"
            autoCorrect={false}
            maxLength={7}
            style={[
              styles.hexInput,
              {
                borderColor: themeColors.border,
                borderRadius: radius.md,
                color: themeColors.text,
                backgroundColor: themeColors.card,
              },
            ]}
          />
        </View>
      ) : null}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    width: '100%',
  },
  headerRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  label: {
    fontSize: 13,
    fontWeight: '700',
  },
  previewBadge: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 6,
  },
  previewDot: {
    width: 14,
    height: 14,
    borderRadius: 7,
    borderWidth: 1,
  },
  previewHex: {
    fontSize: 12,
    fontWeight: '700',
  },
  swatchGrid: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 10,
  },
  swatch: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  hexRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 10,
  },
  hexSwatch: {
    width: 36,
    height: 36,
    borderWidth: 1,
  },
  hexInput: {
    flex: 1,
    height: 40,
    borderWidth: 1,
    paddingHorizontal: 12,
    fontSize: 14,
    fontWeight: '600',
  },
});

export default ColorPicker;
