import React from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
  Platform,
} from 'react-native';
import { ProgressBar } from '../progress/ProgressBar';

export interface DraftApplicationItem {
  id: string;
  customerName: string;
  productType: string; // e.g. "Cash Loan", "Durable Loan", "Car Loan"
  idNumberMasked: string; // e.g. "CCCD 079***4521"
  currentStep: number; // e.g. 5
  totalSteps: number; // e.g. 12
  stepTitle: string; // e.g. "Additional information", "Select scheme", "Scan ID chip"
  statusBadgeLabel?: string; // Default: 'Draft'
  data?: any;
}

export interface DraftApplicationCardProps {
  item: DraftApplicationItem;
  onPress?: (item: DraftApplicationItem) => void;
  style?: ViewStyle;
  testID?: string;
}

export const DraftApplicationCard: React.FC<DraftApplicationCardProps> = ({
  item,
  onPress,
  style,
  testID = 'draft-application-card',
}) => {
  const {
    customerName,
    productType,
    idNumberMasked,
    currentStep,
    totalSteps,
    stepTitle,
    statusBadgeLabel = 'Draft',
  } = item;

  // Calculate percentage (e.g. 5 / 12 * 100)
  const progressPercent = totalSteps > 0 ? (currentStep / totalSteps) * 100 : 0;

  return (
    <TouchableOpacity
      testID={testID}
      style={[styles.card, style]}
      onPress={() => onPress?.(item)}
      activeOpacity={0.85}
      accessibilityRole="button"
      accessibilityLabel={`Draft application for ${customerName}`}
    >
      {/* Top Header Row: Customer Name & Draft Badge */}
      <View style={styles.topRow}>
        <Text testID={`${testID}-customer-name`} style={styles.customerName} numberOfLines={1}>
          {customerName}
        </Text>
        <View style={styles.badge}>
          <Text style={styles.badgeText}>{statusBadgeLabel}</Text>
        </View>
      </View>

      {/* Subtitle: Product Type, ID Number */}
      <Text testID={`${testID}-product-id`} style={styles.subText} numberOfLines={1}>
        {productType}, {idNumberMasked}
      </Text>

      {/* Stopped At Step Description */}
      <Text testID={`${testID}-step-description`} style={styles.stepDesc} numberOfLines={1}>
        Stopped at step {currentStep}/{totalSteps}: {stepTitle}
      </Text>

      {/* Progress Bar (Lotte Red Fill) */}
      <View style={styles.progressBarWrapper}>
        <ProgressBar
          progress={progressPercent}
          height={6}
          color="#D3141B"
          backgroundColor="#F0F1F4"
          testID={`${testID}-progress`}
        />
      </View>
    </TouchableOpacity>
  );
};

const styles = StyleSheet.create({
  card: {
    backgroundColor: '#FFFFFF',
    borderRadius: 14,
    paddingTop: 16,
    paddingBottom: 14,
    paddingHorizontal: 16,
    marginBottom: 12,
    shadowColor: '#000000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.05,
    shadowRadius: 6,
    elevation: 2,
    borderWidth: 1,
    borderColor: '#F3F4F6',
  },
  topRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 6,
  },
  customerName: {
    fontSize: 16,
    lineHeight: 22,
    fontWeight: '700',
    color: '#16181D',
    flex: 1,
    marginRight: 10,
    ...Platform.select({
      ios: { fontFamily: 'Pretendard-Bold' },
      android: { fontFamily: 'Pretendard-Bold' },
    }),
  },
  badge: {
    backgroundColor: '#F3F4F6',
    borderRadius: 12,
    paddingHorizontal: 12,
    paddingVertical: 4,
    alignSelf: 'center',
  },
  badgeText: {
    fontSize: 12,
    lineHeight: 16,
    color: '#6B7280',
    fontWeight: '500',
    ...Platform.select({
      ios: { fontFamily: 'Pretendard-Medium' },
      android: { fontFamily: 'Pretendard-Medium' },
    }),
  },
  subText: {
    fontSize: 13,
    lineHeight: 18,
    color: '#6B7280',
    marginBottom: 4,
    ...Platform.select({
      ios: { fontFamily: 'Pretendard-Regular' },
      android: { fontFamily: 'Pretendard-Regular' },
    }),
  },
  stepDesc: {
    fontSize: 13,
    lineHeight: 18,
    color: '#6B7280',
    marginBottom: 10,
    ...Platform.select({
      ios: { fontFamily: 'Pretendard-Regular' },
      android: { fontFamily: 'Pretendard-Regular' },
    }),
  },
  progressBarWrapper: {
    width: '100%',
    marginTop: 2,
  },
});
