import React from 'react';
import {
  View,
  Text,
  Image,
  ImageSourcePropType,
  StyleSheet,
  ViewStyle,
} from 'react-native';
import { AppBottomSheet } from '../../modals/AppBottomSheet';
import { AppButton } from '../button/AppButton';

export interface ImageBottomSheetModalProps {
  visible: boolean;
  onClose: () => void;
  title: string;
  description?: string;
  imageSource?: ImageSourcePropType | React.ReactNode;
  primaryButtonText?: string;
  onPrimaryPress?: () => void;
  secondaryButtonText?: string;
  onSecondaryPress?: () => void;
  style?: ViewStyle;
  testID?: string;
}

export const ImageBottomSheetModal: React.FC<ImageBottomSheetModalProps> = ({
  visible,
  onClose,
  title,
  description,
  imageSource,
  primaryButtonText = 'Close',
  onPrimaryPress,
  secondaryButtonText,
  onSecondaryPress,
  style,
  testID = 'image-bottom-sheet-modal',
}) => {
  const handlePrimary = () => {
    if (onPrimaryPress) {
      onPrimaryPress();
    } else {
      onClose();
    }
  };

  const renderIllustration = () => {
    if (imageSource) {
      if (typeof imageSource === 'object' && !('uri' in imageSource) && React.isValidElement(imageSource)) {
        return <View style={styles.imageCardContainer}>{imageSource}</View>;
      }
      return (
        <View style={styles.imageCardContainer}>
          <Image
            source={imageSource as ImageSourcePropType}
            style={styles.heroImg}
            resizeMode="contain"
            testID={`${testID}-image`}
          />
        </View>
      );
    }

    // Default 3D Loan Calculation / Document illustration placeholder matching ML-003 / Loan Estimate
    return (
      <View style={styles.imageCardContainer} testID={`${testID}-schematic-illustration`}>
        <View style={styles.schematicPhone}>
          <View style={styles.phoneHeaderBar} />
          <View style={styles.receiptPaper}>
            <View style={styles.receiptLine} />
            <View style={[styles.receiptLine, { width: '60%' }]} />
            <View style={[styles.receiptLine, { width: '80%' }]} />
          </View>
        </View>
        <View style={styles.schematicCoins}>
          <Text style={{ fontSize: 36 }}>💰</Text>
        </View>
      </View>
    );
  };

  return (
    <AppBottomSheet
      visible={visible}
      onClose={onClose}
      showHeader={false}
      dismissible
      testID={testID}
      style={style}
    >
      <View style={styles.contentWrap}>
        {/* Top Hero Illustration Card */}
        {renderIllustration()}

        {/* Title */}
        <Text testID={`${testID}-title`} style={styles.title}>
          {title}
        </Text>

        {/* Description / Subtext */}
        {description ? (
          <Text testID={`${testID}-desc`} style={styles.description}>
            {description}
          </Text>
        ) : null}

        {/* CTA Actions */}
        <View style={styles.actionsWrap}>
          <AppButton
            title={primaryButtonText}
            variant="primary"
            onPress={handlePrimary}
            testID={`${testID}-primary-btn`}
            style={styles.primaryBtn}
          />
          {secondaryButtonText && onSecondaryPress ? (
            <AppButton
              title={secondaryButtonText}
              variant="outline"
              onPress={onSecondaryPress}
              testID={`${testID}-secondary-btn`}
              style={styles.secondaryBtn}
            />
          ) : null}
        </View>
      </View>
    </AppBottomSheet>
  );
};

const styles = StyleSheet.create({
  contentWrap: {
    paddingHorizontal: 20,
    paddingTop: 8,
    paddingBottom: 24,
    alignItems: 'center',
  },
  imageCardContainer: {
    width: '100%',
    height: 180,
    backgroundColor: '#F0F5FF',
    borderRadius: 20,
    justifyContent: 'center',
    alignItems: 'center',
    marginBottom: 20,
    position: 'relative',
    overflow: 'hidden',
  },
  heroImg: {
    width: '80%',
    height: '80%',
  },
  schematicPhone: {
    width: 90,
    height: 120,
    backgroundColor: '#FFFFFF',
    borderRadius: 14,
    borderWidth: 2,
    borderColor: '#3B82F6',
    padding: 8,
    alignItems: 'center',
    shadowColor: '#2563EB',
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.15,
    shadowRadius: 8,
    elevation: 3,
  },
  phoneHeaderBar: {
    width: 40,
    height: 4,
    backgroundColor: '#DBEAFE',
    borderRadius: 2,
    marginBottom: 10,
  },
  receiptPaper: {
    width: '100%',
    backgroundColor: '#EFF6FF',
    borderRadius: 6,
    padding: 8,
    gap: 6,
  },
  receiptLine: {
    height: 4,
    backgroundColor: '#93C5FD',
    borderRadius: 2,
    width: '100%',
  },
  schematicCoins: {
    position: 'absolute',
    bottom: 16,
    right: 48,
  },
  title: {
    fontSize: 20,
    fontWeight: '800',
    color: '#111827',
    textAlign: 'center',
    marginBottom: 10,
  },
  description: {
    fontSize: 14,
    color: '#4B5563',
    textAlign: 'center',
    lineHeight: 20,
    paddingHorizontal: 16,
    marginBottom: 24,
  },
  actionsWrap: {
    width: '100%',
    gap: 10,
  },
  primaryBtn: {
    width: '100%',
    height: 48,
    backgroundColor: '#2563EB',
    borderRadius: 12,
  },
  secondaryBtn: {
    width: '100%',
    height: 48,
    borderRadius: 12,
  },
});

