import React from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  ScrollView,
  StyleSheet,
  Modal,
  Platform,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { CheckboxGroup, CheckboxOption } from './CheckboxGroup';

export interface FilterCategoryConfig<T = string> {
  id: string;
  title: string;
  options: CheckboxOption<T>[];
  columns?: 1 | 2;
}

export interface SearchFilterDrawerProps {
  visible: boolean;
  onClose: () => void;
  title?: string;
  /** Current state mapping: { [categoryId]: string[] } */
  selectedFilters: Record<string, string[]>;
  onFilterChange: (categoryId: string, values: string[]) => void;
  onClearCategory?: (categoryId: string) => void;
  onResetAll?: () => void;
  onApply?: () => void;
  categories?: FilterCategoryConfig[];
  testID?: string;
}

/**
 * Filter modal / slide-over dialog matching the screenshot:
 * "Bộ lọc tìm kiếm" with dismissal 'X', Red Funnel section headers,
 * 2-column checkboxes, category clear icons, and bottom action bar.
 */
export const SearchFilterDrawer: React.FC<SearchFilterDrawerProps> = ({
  visible,
  onClose,
  title = 'Bộ lọc tìm kiếm',
  selectedFilters,
  onFilterChange,
  onClearCategory,
  onResetAll,
  onApply,
  categories = defaultFilterCategories,
  testID = 'search-filter-drawer',
}) => {
  return (
    <Modal
      visible={visible}
      animationType="slide"
      transparent={false}
      onRequestClose={onClose}
    >
      <SafeAreaView style={styles.safeArea}>
        <View testID={testID} style={styles.container}>
          {/* Top Title & Close Button */}
          <View style={styles.header}>
            <Text testID={`${testID}-title`} style={styles.headerTitle}>
              {title}
            </Text>
            <TouchableOpacity
              testID={`${testID}-close-btn`}
              style={styles.closeBtn}
              onPress={onClose}
              hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
            >
              <Text style={styles.closeBtnText}>✕</Text>
            </TouchableOpacity>
          </View>

          {/* Filter Categories Scrollable Content */}
          <ScrollView
            testID={`${testID}-scroll`}
            contentContainerStyle={styles.scrollContent}
            showsVerticalScrollIndicator={false}
          >
            {categories.map((category) => (
              <View
                key={category.id}
                testID={`${testID}-category-${category.id}`}
                style={styles.categoryBlock}
              >
                <CheckboxGroup
                  title={category.title}
                  showFilterIcon={true}
                  options={category.options}
                  selectedValues={selectedFilters[category.id] || []}
                  onChange={(vals) => onFilterChange(category.id, vals)}
                  onClear={() => {
                    if (onClearCategory) {
                      onClearCategory(category.id);
                    } else {
                      onFilterChange(category.id, []);
                    }
                  }}
                  columns={category.columns || 2}
                  variant="primary"
                  testID={`${testID}-group-${category.id}`}
                />
              </View>
            ))}
          </ScrollView>

          {/* Footer with Reset & Apply buttons */}
          <View style={styles.footer}>
            {onResetAll ? (
              <TouchableOpacity
                testID={`${testID}-reset-btn`}
                style={styles.resetBtn}
                onPress={onResetAll}
                activeOpacity={0.7}
              >
                <Text style={styles.resetBtnText}>Thiết lập lại</Text>
              </TouchableOpacity>
            ) : null}

            <TouchableOpacity
              testID={`${testID}-apply-btn`}
              style={styles.applyBtn}
              onPress={() => {
                onApply?.();
                onClose();
              }}
              activeOpacity={0.8}
            >
              <Text style={styles.applyBtnText}>Áp dụng</Text>
            </TouchableOpacity>
          </View>
        </View>
      </SafeAreaView>
    </Modal>
  );
};

