import React from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ActivityIndicator,
} from 'react-native';
import { AuthColors, AuthTypography } from '../../theme/tokens';

export interface AuthButtonProps {
  title: string;
  onPress: () => void;
  variant?: 'primary' | 'secondary' | 'outline';
  disabled?: boolean;
  isLoading?: boolean;
  testID?: string;
}

export const AuthButton: React.FC<AuthButtonProps> = ({
  title,
  onPress,
  variant = 'primary',
  disabled = false,
  isLoading = false,
  testID = 'auth-button',
}) => {
  const isPrimary = variant === 'primary';
  const isOutline = variant === 'outline';

  return (
    <TouchableOpacity
      testID={testID}
      style={[
        styles.button,
        isPrimary && styles.buttonPrimary,
        !isPrimary && !isOutline && styles.buttonSecondary,
        isOutline && styles.buttonOutline,
        disabled && styles.buttonDisabled,
      ]}
      onPress={onPress}
      disabled={disabled || isLoading}
      activeOpacity={0.8}
    >
      {isLoading ? (
        <ActivityIndicator
          testID={`${testID}-loading`}
          color={isPrimary ? AuthColors.white : AuthColors.primary}
          size="small"
        />
      ) : (
        <Text
          style={[
            styles.text,
            isPrimary && styles.textPrimary,
            !isPrimary && !isOutline && styles.textSecondary,
            isOutline && styles.textOutline,
            disabled && styles.textDisabled,
          ]}
        >
          {title}
        </Text>
      )}
    </TouchableOpacity>
  );
};

const styles = StyleSheet.create({
  button: {
    height: 48,
    borderRadius: 8,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: 16,
  },
  buttonPrimary: {
    backgroundColor: AuthColors.primary,
  },
  buttonSecondary: {
    backgroundColor: AuthColors.buttonSecondary,
  },
  buttonOutline: {
    backgroundColor: 'transparent',
    borderWidth: 1,
    borderColor: AuthColors.border,
  },
  buttonDisabled: {
    backgroundColor: AuthColors.buttonDisabled,
  },
  text: {
    ...AuthTypography.bodyBold,
  },
  textPrimary: {
    color: AuthColors.white,
  },
  textSecondary: {
    color: AuthColors.buttonSecondaryText,
  },
  textOutline: {
    color: AuthColors.textPrimary,
  },
  textDisabled: {
    color: AuthColors.buttonDisabledText,
  },
});
