import React from 'react';
import {
  Modal,
  View,
  Text,
  TouchableOpacity,
  TouchableWithoutFeedback,
  StyleSheet,
  ViewStyle,
  Platform,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { AppBlurBackdrop } from '../components/feedback/AppBlurBackdrop';

export interface AppAlertModalProps {
  visible: boolean;
  onClose: () => void;
  title?: string;
  showHeader?: boolean;
  children: React.ReactNode;
  dismissible?: boolean;
  maxWidth?: number;
  backdropBlur?: boolean;
  style?: ViewStyle;
  testID?: string;
}

export const AppAlertModal: React.FC<AppAlertModalProps> = ({
  visible,
  onClose,
  title,
  showHeader = true,
  children,
  dismissible = true,
  maxWidth = 360,
  backdropBlur,
  style,
  testID = 'app-alert-modal',
}) => {
  const { theme } = useTheme();

  // If not explicitly passed, fallback to global theme modal config
  const shouldBlur = backdropBlur ?? theme.modal?.alertBackdropBlur ?? false;

  const handleBackdropPress = () => {
    if (dismissible) {
      onClose();
    }
  };

  return (
    <Modal
      transparent
      statusBarTranslucent
      animationType="fade"
      visible={visible}
      onRequestClose={() => {
        if (dismissible) {
          onClose();
        }
      }}
    >
      <View style={[styles.backdrop, shouldBlur && { backgroundColor: 'transparent' }]}>
        {shouldBlur && (
          <AppBlurBackdrop
            testID={`${testID}-blur`}
            blurType="dark"
            blurAmount={15}
          />
        )}
        <TouchableOpacity
          activeOpacity={1}
          style={StyleSheet.absoluteFill}
          onPress={handleBackdropPress}
          testID={`${testID}-backdrop`}
        />
        <View
          testID={`${testID}-card`}
          style={[
            styles.dialogCard,
            {
              maxWidth,
              backgroundColor: theme.colors.card,
              borderRadius: theme.radius.xl,
              borderColor: theme.colors.border,
            },
            style,
          ]}
        >
          {showHeader && title ? (
            <View style={styles.header}>
              <Text
                testID={`${testID}-title`}
                style={[
                  styles.title,
                  { color: theme.colors.text, fontFamily: theme.typography.fontFamilyBold },
                ]}
              >
                {title}
              </Text>
              {dismissible ? (
                <TouchableOpacity
                  testID={`${testID}-close-btn`}
                  style={styles.closeBtn}
                  onPress={onClose}
                >
                  <Text style={styles.closeBtnText}>✕</Text>
                </TouchableOpacity>
              ) : null}
            </View>
          ) : null}

          <View style={styles.contentWrap}>{children}</View>
        </View>
      </View>
    </Modal>
  );
};

const styles = StyleSheet.create({
  backdrop: {
    flex: 1,
    backgroundColor: 'rgba(22, 24, 29, 0.45)',
    justifyContent: 'center',
    alignItems: 'center',
    padding: 20,
  },
  blurBackdrop: {
    backgroundColor: 'rgba(15, 23, 42, 0.6)',
  },
  webBlurBackdrop: {
    backgroundColor: 'rgba(15, 23, 42, 0.4)',
    // @ts-ignore Web CSS backdropFilter
    backdropFilter: 'blur(8px)',
    WebkitBackdropFilter: 'blur(8px)',
  },
  dialogCard: {
    width: '100%',
    padding: 20,
    borderWidth: 1,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 8 },
    shadowOpacity: 0.18,
    shadowRadius: 20,
    elevation: 10,
  },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 14,
  },
  title: {
    fontSize: 17,
    fontWeight: '700',
    flex: 1,
  },
  closeBtn: {
    width: 32,
    height: 32,
    borderRadius: 16,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#F3F4F6',
    marginLeft: 8,
  },
  closeBtnText: {
    fontSize: 14,
    color: '#6B7280',
    fontWeight: '600',
  },
  contentWrap: {
    width: '100%',
  },
});

