import React, { useRef, useState, useEffect } from 'react';
import { View, TextInput, StyleSheet } from 'react-native';

export interface OtpInputProps {
  length?: number;
  value?: string;
  onChangeOtp?: (otp: string) => void;
  onOtpComplete?: (otp: string) => void;
  testID?: string;
}

export const OtpInput: React.FC<OtpInputProps> = ({
  length = 6,
  value: controlledValue,
  onChangeOtp,
  onOtpComplete,
  testID = 'otp-input',
}) => {
  const [internalValue, setInternalValue] = useState<string>(controlledValue || '');
  const inputsRef = useRef<Array<TextInput | null>>([]);

  const isControlled = controlledValue !== undefined;
  const currentValue = isControlled ? controlledValue : internalValue;

  useEffect(() => {
    if (controlledValue !== undefined) {
      setInternalValue(controlledValue);
    }
  }, [controlledValue]);

  const updateOtp = (newOtp: string) => {
    if (!isControlled) {
      setInternalValue(newOtp);
    }
    onChangeOtp?.(newOtp);
    if (newOtp.length === length) {
      onOtpComplete?.(newOtp);
    }
  };

  const handleChange = (text: string, index: number) => {
    const rawDigits = text.replace(/[^0-9]/g, '');

    // Handle full or partial paste: if pasting more than 1 digit into the box
    if (rawDigits.length > 1) {
      // Check if user is typing a single new digit into an already populated box
      // e.g. currentValue[index] was '5' and user typed '3' -> text is '53' or '35'
      const existingChar = currentValue[index] || '';
      if (rawDigits.length === 2 && existingChar && rawDigits.includes(existingChar)) {
        // User typed a new digit to replace or append to the current box
        const newDigit = rawDigits.replace(existingChar, '').slice(-1) || rawDigits.slice(-1);
        const chars = currentValue.split('');
        chars[index] = newDigit;
        const newOtp = chars.join('').slice(0, length);
        updateOtp(newOtp);
        if (newDigit && index < length - 1) {
          inputsRef.current[index + 1]?.focus();
        }
        return;
      }

      // Actual multi-digit paste: distribute across boxes starting from `index`
      const chars = currentValue.split('');
      for (let i = 0; i < rawDigits.length && index + i < length; i++) {
        chars[index + i] = rawDigits[i];
      }
      const newOtp = chars.join('').slice(0, length);
      updateOtp(newOtp);
      const nextIndex = Math.min(index + rawDigits.length, length - 1);
      inputsRef.current[nextIndex]?.focus();
      return;
    }

    const cleanChar = rawDigits.slice(-1);
    const chars = currentValue.split('');
    chars[index] = cleanChar;
    const newOtp = chars.join('').slice(0, length);
    updateOtp(newOtp);

    if (cleanChar && index < length - 1) {
      inputsRef.current[index + 1]?.focus();
    } else if (!cleanChar && index > 0) {
      // If deleted via onChangeText (e.g. mobile soft keyboard backspace), navigate to previous box
      inputsRef.current[index - 1]?.focus();
    }
  };

  const handleKeyPress = (e: any, index: number) => {
    if (e.nativeEvent.key === 'Backspace') {
      if (currentValue[index]) {
        // Current box has a digit: clear it and move focus to previous box immediately
        const chars = currentValue.split('');
        chars[index] = '';
        updateOtp(chars.join('').slice(0, length));
        if (index > 0) {
          inputsRef.current[index - 1]?.focus();
        }
      } else if (index > 0) {
        // Current box was already empty: clear previous box and focus it
        const chars = currentValue.split('');
        chars[index - 1] = '';
        updateOtp(chars.join('').slice(0, length));
        inputsRef.current[index - 1]?.focus();
      }
    }
  };

  return (
    <View testID={testID} style={styles.container}>
      {Array.from({ length }).map((_, index) => {
        const char = currentValue[index] || '';
        return (
          <TextInput
            key={`otp-${index}`}
            ref={(ref) => (inputsRef.current[index] = ref)}
            testID={`${testID}-digit-${index}`}
            value={char}
            onChangeText={(text) => handleChange(text, index)}
            onKeyPress={(e) => handleKeyPress(e, index)}
            keyboardType="number-pad"
            maxLength={1}
            selectTextOnFocus
            style={[styles.box, char ? styles.boxFilled : null]}
          />
        );
      })}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flexDirection: 'row',
    justifyContent: 'center',
    gap: 8,
    marginVertical: 12,
  },
  box: {
    width: 44,
    height: 52,
    borderWidth: 1.5,
    borderColor: '#E2E5EB',
    borderRadius: 8,
    textAlign: 'center',
    fontSize: 20,
    fontWeight: '700',
    color: '#16181D',
    backgroundColor: '#FFFFFF',
  },
  boxFilled: {
    borderColor: '#E7252B',
  },
});
