import {
  setFStorage as nativeSetFStorage,
  getFStorage as nativeGetFStorage,
  removeFStorage as nativeRemoveFStorage,
} from 'react-native-bizmob-plugin';
import { appLogger } from '../logger/AppLogger';

export type PersistedAppRoute = 'LaunchFlow' | 'AuthFlow' | 'DashboardFlow';

const VALID_PERSISTED_ROUTES: ReadonlySet<string> = new Set<PersistedAppRoute>([
  'LaunchFlow',
  'AuthFlow',
  'DashboardFlow',
]);

export interface FStorageAdapter {
  setFStorage: typeof nativeSetFStorage;
  getFStorage: typeof nativeGetFStorage;
  removeFStorage: typeof nativeRemoveFStorage;
}

const defaultAdapter: FStorageAdapter = {
  setFStorage: nativeSetFStorage,
  getFStorage: nativeGetFStorage,
  removeFStorage: nativeRemoveFStorage,
};

/**
 * Persists the user's last reached top-level app route (`AuthFlow` / `DashboardFlow`)
 * using the bizMOB `FStorage` plugin so reopening the app resumes at the appropriate screen.
 */
export class AppRoutePersistenceService {
  public static readonly KEY_LAST_ROUTE = 'LOS_LAST_REACHED_ROUTE';

  private static instance: AppRoutePersistenceService;
  private adapter: FStorageAdapter;

  constructor(adapter: FStorageAdapter = defaultAdapter) {
    this.adapter = adapter;
  }

  public static getInstance(): AppRoutePersistenceService {
    if (!AppRoutePersistenceService.instance) {
      AppRoutePersistenceService.instance = new AppRoutePersistenceService();
    }
    return AppRoutePersistenceService.instance;
  }

  /**
   * Saves the reached route (`AuthFlow` for Login, `DashboardFlow` for Dashboard) to FStorage.
   */
  public async saveRoute(route: PersistedAppRoute): Promise<boolean> {
    try {
      const res = await this.adapter.setFStorage({
        key: AppRoutePersistenceService.KEY_LAST_ROUTE,
        value: route,
      });
      return res?.header?.result ?? true;
    } catch (err) {
      appLogger.w(
        'AppRoutePersistenceService',
        `Failed to save route [${route}] to FStorage:`,
        err
      );
      return false;
    }
  }

  /**
   * Reads the last reached route from FStorage.
   * Returns `null` when no valid route is stored or if FStorage is unavailable.
   */
  public async getSavedRoute(): Promise<PersistedAppRoute | null> {
    try {
      const res = await this.adapter.getFStorage(
        AppRoutePersistenceService.KEY_LAST_ROUTE
      );
      if (res?.header && res.header.result === false) {
        return null;
      }

      const rawValue =
        res?.body?.value ??
        res?.body?.data?.[AppRoutePersistenceService.KEY_LAST_ROUTE] ??
        (typeof res?.body?.fstorage === 'string' ? res.body.fstorage : undefined);

      if (typeof rawValue === 'string' && VALID_PERSISTED_ROUTES.has(rawValue)) {
        return rawValue as PersistedAppRoute;
      }

      return null;
    } catch (err) {
      appLogger.w(
        'AppRoutePersistenceService',
        'Failed to read saved route from FStorage:',
        err
      );
      return null;
    }
  }

  /**
   * Clears the persisted route from FStorage.
   */
  public async clearSavedRoute(): Promise<boolean> {
    try {
      const res = await this.adapter.removeFStorage(
        AppRoutePersistenceService.KEY_LAST_ROUTE
      );
      return res?.header?.result ?? true;
    } catch (err) {
      appLogger.w(
        'AppRoutePersistenceService',
        'Failed to clear saved route from FStorage:',
        err
      );
      return false;
    }
  }
}

export const appRoutePersistenceService = AppRoutePersistenceService.getInstance();
