import React, { useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  ScrollView,
  StyleSheet,
  ActivityIndicator,
  ViewStyle,
  Platform,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import Svg, { Path } from 'react-native-svg';
import { HtmlViewer, HtmlStyleTags } from './HtmlViewer';

export interface ConsentWebViewScreenProps {
  /**
   * Screen header title (e.g. "Data collection", "Personal Data Processing Consent")
   */
  title?: string;
  /**
   * Back button callback
   */
  onBackPress?: () => void;
  /**
   * Direct HTML content (from CMS, rich text editor, or API)
   */
  htmlContent?: string;
  /**
   * Remote URL to display or fetch content from
   */
  url?: string;
  /**
   * Empty/placeholder message when no content is provided
   * (Matches design: "Content configured by the system")
   */
  placeholderText?: string;
  /**
   * Optional bottom action bar or button (e.g. "Agree and Continue", "Accept")
   */
  bottomAction?: React.ReactNode;
  /**
   * Custom HTML tag styles
   */
  tagsStyles?: HtmlStyleTags;
  /**
   * Loading state
   */
  isLoading?: boolean;
  /**
   * Custom style for container
   */
  style?: ViewStyle;
  /**
   * Accessibility test ID
   */
  testID?: string;
}

/**
 * ConsentWebViewScreen (Personal Data Processing Consent WebView)
 *
 * Full WebView screen matching the design:
 * - Clean status bar and safe area insets
 * - Standard navigation header with back chevron: "Data collection"
 * - Responsive body displaying rich HTML terms or fallback placeholder ("Content configured by the system")
 * - Optional bottom action bar for user consent confirmation
 * - Works natively across iOS, Android, and Web without broken native dependencies
 */
export const ConsentWebViewScreen: React.FC<ConsentWebViewScreenProps> = ({
  title = 'Data collection',
  onBackPress,
  htmlContent,
  url,
  placeholderText = 'Content configured by the system',
  bottomAction,
  tagsStyles,
  isLoading = false,
  style,
  testID = 'consent-webview-screen',
}) => {
  const [fetchedHtml, setFetchedHtml] = useState<string | null>(null);
  const [internalLoading, setInternalLoading] = useState<boolean>(false);
  const [fetchError, setFetchError] = useState<string | null>(null);

  React.useEffect(() => {
    if (!url) {
      setFetchedHtml(null);
      setFetchError(null);
      return;
    }

    let isMounted = true;

    // In web browsers, fetching external origins like google.com via fetch() is blocked by CORS.
    // We use an <iframe> directly on Web so the browser handles cookies, redirects, and sandbox naturally.
    if (Platform.OS === 'web') {
      return;
    }

    setInternalLoading(true);
    setFetchError(null);

    fetch(url)
      .then((res) => {
        if (!res.ok) {
          throw new Error(`Failed to load URL: ${res.status} ${res.statusText}`);
        }
        return res.text();
      })
      .then((data) => {
        if (isMounted) {
          setFetchedHtml(data);
          setInternalLoading(false);
        }
      })
      .catch((err) => {
        if (isMounted) {
          setFetchError(err.message || 'Error loading web content');
          setInternalLoading(false);
        }
      });

    return () => {
      isMounted = false;
    };
  }, [url]);

  const activeHtml = htmlContent || fetchedHtml;
  const hasContent = !!(activeHtml && activeHtml.trim());
  const effectiveLoading = isLoading || (internalLoading && Platform.OS !== 'web');

  // On Web with URL provided: render native iframe to avoid CORS fetch blocks
  const isWebUrlMode = Platform.OS === 'web' && !!url && !htmlContent;

  return (
    <SafeAreaView
      style={[styles.container, style]}
      edges={['top', 'left', 'right', 'bottom']}
      testID={testID}
    >
      {/* Top Navigation Header */}
      <View style={styles.header} testID={`${testID}-header`}>
        {onBackPress ? (
          <TouchableOpacity
            testID={`${testID}-back-btn`}
            onPress={onBackPress}
            style={styles.backButton}
            activeOpacity={0.7}
            hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
          >
            <Svg width={24} height={24} viewBox="0 0 24 24" fill="none">
              <Path
                d="M15 19L8 12L15 5"
                stroke="#0F172A"
                strokeWidth={2.4}
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </Svg>
          </TouchableOpacity>
        ) : (
          <View style={styles.headerSpacer} />
        )}

        <Text style={styles.headerTitle} testID={`${testID}-title`} numberOfLines={1}>
          {title}
        </Text>

        <View style={styles.headerSpacer} />
      </View>

      {/* Main Content Area */}
      {isWebUrlMode ? (
        <View style={styles.iframeContainer} testID={`${testID}-iframe-wrapper`}>
          {React.createElement('iframe', {
            src: url,
            style: {
              width: '100%',
              height: '100%',
              border: 'none',
              backgroundColor: '#FFFFFF',
            },
            title: title || 'Web Content',
            sandbox: 'allow-scripts allow-same-origin allow-forms',
          })}
        </View>
      ) : effectiveLoading ? (
        <View style={styles.loadingContainer} testID={`${testID}-loading`}>
          <ActivityIndicator size="large" color="#E5252A" />
        </View>
      ) : fetchError ? (
        <View style={styles.placeholderContainer} testID={`${testID}-error`}>
          <Text style={[styles.placeholderText, styles.errorText]}>
            {fetchError}
          </Text>
        </View>
      ) : hasContent ? (
        <ScrollView
          style={styles.contentScrollView}
          contentContainerStyle={styles.contentContainer}
          showsVerticalScrollIndicator={false}
          testID={`${testID}-scroll-content`}
        >
          <HtmlViewer
            html={activeHtml!}
            tagsStyles={tagsStyles}
            testID={`${testID}-html-viewer`}
          />
        </ScrollView>
      ) : (
        /* Empty / Placeholder State matching design */
        <View style={styles.placeholderContainer} testID={`${testID}-placeholder`}>
          <Text style={styles.placeholderText} testID={`${testID}-placeholder-text`}>
            {placeholderText}
          </Text>
        </View>
      )}

      {/* Optional Bottom Action Area */}
      {bottomAction ? (
        <View style={styles.bottomBar} testID={`${testID}-bottom-bar`}>
          {bottomAction}
        </View>
      ) : null}
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#FFFFFF',
  },
  header: {
    height: 52,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 16,
    borderBottomWidth: StyleSheet.hairlineWidth,
    borderBottomColor: '#F1F5F9',
    backgroundColor: '#FFFFFF',
  },
  backButton: {
    width: 36,
    height: 36,
    alignItems: 'center',
    justifyContent: 'center',
    marginLeft: -4,
  },
  headerTitle: {
    fontSize: 17,
    fontWeight: '700',
    color: '#0F172A',
    textAlign: 'center',
    fontFamily: Platform.select({
      ios: 'Pretendard-Bold',
      android: 'Pretendard-Bold',
      default: 'system-ui',
    }),
  },
  headerSpacer: {
    width: 36,
  },
  loadingContainer: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
  },
  iframeContainer: {
    flex: 1,
    width: '100%',
    height: '100%',
  },
  contentScrollView: {
    flex: 1,
  },
  contentContainer: {
    paddingHorizontal: 20,
    paddingVertical: 18,
  },
  placeholderContainer: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: 32,
  },
  placeholderText: {
    fontSize: 14,
    color: '#94A3B8', // Soft muted gray matching image
    textAlign: 'center',
    lineHeight: 22,
    fontFamily: Platform.select({
      ios: 'Pretendard-Regular',
      android: 'Pretendard-Regular',
      default: 'system-ui',
    }),
  },
  errorText: {
    color: '#E11D48',
  },
  bottomBar: {
    paddingHorizontal: 20,
    paddingVertical: 14,
    borderTopWidth: StyleSheet.hairlineWidth,
    borderTopColor: '#E2E8F0',
    backgroundColor: '#FFFFFF',
  },
});
