import React, { useRef } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TextInput,
  TouchableOpacity,
  KeyboardAvoidingView,
  Platform,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useOtpViewModel, UseOtpViewModelProps } from '../viewmodels/useOtpViewModel';
import { AuthHeader } from './components/AuthHeader';
import { AuthButton } from './components/AuthButton';
import { AuthColors, AuthTypography } from '../theme/tokens';
import { useBackNavigation } from '@mfe/ui-components/hooks/useBackNavigation';

export interface OtpVerificationScreenProps {
  viewModelProps?: UseOtpViewModelProps;
}

export const OtpVerificationScreen: React.FC<OtpVerificationScreenProps> = ({
  viewModelProps,
}) => {
  const {
    channel,
    otpCode,
    countdown,
    canResend,
    isLoading,
    errorMessage,
    infoMessage,
    userEmail,
    handleDigitChange,
    requestNewCode,
    submitOtp,
    onBack,
  } = useOtpViewModel(viewModelProps);

  const { panHandlers } = useBackNavigation({
    onBack,
    enabled: !isLoading && !!onBack,
  });

  const inputRefs = useRef<Array<TextInput | null>>([]);

  const handleChange = (index: number, val: string) => {
    handleDigitChange(index, val);
    if (val && index < 5) {
      inputRefs.current[index + 1]?.focus();
    } else if (!val && index > 0) {
      inputRefs.current[index - 1]?.focus();
    }
  };

  const handleKeyPress = (index: number, key: string) => {
    if (key === 'Backspace') {
      if (otpCode[index]) {
        // Clear current box and move focus to previous box immediately
        handleDigitChange(index, '');
        if (index > 0) {
          inputRefs.current[index - 1]?.focus();
        }
      } else if (index > 0) {
        // Current box already empty: clear previous box and focus it
        handleDigitChange(index - 1, '');
        inputRefs.current[index - 1]?.focus();
      }
    }
  };

  return (
    <SafeAreaView testID="otp-verification-screen" style={styles.safeArea} {...panHandlers}>
      <AuthHeader
        testID="otp-header"
        title="OTP Verification"
        onBack={onBack}
        showBack={!!onBack}
      />

      <KeyboardAvoidingView
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
        style={styles.container}
      >
        <View style={styles.content}>
          <Text style={styles.title}>Verification Code</Text>
          <Text style={styles.instruction}>
            {channel === 'email'
              ? `Your OTP will be sent to ${userEmail} after you tap Request Verification Code.`
              : 'Enter the One-Time Password from your administrator to continue.'}
          </Text>

          {/* Messages */}
          {errorMessage ? (
            <View testID="otp-error-banner" style={styles.errorBanner}>
              <Text style={styles.errorText}>{errorMessage}</Text>
            </View>
          ) : null}

          {infoMessage ? (
            <View testID="otp-info-banner" style={styles.infoBanner}>
              <Text style={styles.infoText}>{infoMessage}</Text>
            </View>
          ) : null}

          {/* 6 Digit Input Boxes (Frame 2117906620 - 2117906625 in Figma) */}
          <View style={styles.otpInputRow}>
            {otpCode.map((digit, index) => (
              <TextInput
                key={index}
                ref={(ref) => (inputRefs.current[index] = ref)}
                testID={`otp-input-${index}`}
                style={[
                  styles.digitInput,
                  digit ? styles.digitInputFilled : null,
                ]}
                keyboardType="numeric"
                maxLength={1}
                value={digit}
                onChangeText={(val) => handleChange(index, val)}
                onKeyPress={({ nativeEvent }) =>
                  handleKeyPress(index, nativeEvent.key)
                }
                autoFocus={index === 0}
              />
            ))}
          </View>

          {/* Resend / Request Code Timer */}
          <View style={styles.timerRow}>
            {canResend ? (
              <TouchableOpacity
                testID="otp-resend-button"
                onPress={requestNewCode}
                activeOpacity={0.7}
              >
                <Text style={styles.resendText}>Request Verification Code</Text>
              </TouchableOpacity>
            ) : (
              <Text style={styles.countdownText}>
                Resend code in{' '}
                <Text style={styles.countdownHighlight}>
                  {countdown}s
                </Text>
              </Text>
            )}
          </View>
        </View>

        <View style={styles.footerSection}>
          <AuthButton
            testID="otp-submit-button"
            title="Verify & Continue"
            onPress={submitOtp}
            isLoading={isLoading}
            disabled={otpCode.some((d) => !d)}
          />
        </View>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
    backgroundColor: AuthColors.white,
  },
  container: {
    flex: 1,
    paddingHorizontal: 24,
    justifyContent: 'space-between',
  },
  content: {
    marginTop: 28,
  },
  title: {
    ...AuthTypography.h1,
    color: AuthColors.textPrimary,
    marginBottom: 8,
  },
  instruction: {
    ...AuthTypography.bodyRegular,
    color: AuthColors.textSecondary,
    marginBottom: 24,
    lineHeight: 22,
  },
  errorBanner: {
    backgroundColor: AuthColors.errorBackground,
    borderWidth: 1,
    borderColor: AuthColors.borderError,
    borderRadius: 8,
    padding: 12,
    marginBottom: 16,
  },
  errorText: {
    ...AuthTypography.error,
    color: AuthColors.errorText,
    textAlign: 'center',
  },
  infoBanner: {
    backgroundColor: AuthColors.primaryLight,
    borderRadius: 8,
    padding: 12,
    marginBottom: 16,
  },
  infoText: {
    ...AuthTypography.caption,
    color: AuthColors.primaryDark,
    textAlign: 'center',
  },
  otpInputRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    width: '100%',
    marginVertical: 20,
    gap: 8,
  },
  digitInput: {
    flex: 1,
    minWidth: 0,
    maxWidth: 54,
    height: 54,
    paddingHorizontal: 0,
    borderWidth: 1.5,
    borderColor: AuthColors.border,
    borderRadius: 10,
    backgroundColor: AuthColors.inputBackground,
    textAlign: 'center',
    fontSize: 22,
    fontWeight: '700',
    color: AuthColors.textPrimary,
    ...(Platform.OS === 'web' ? ({ width: 0, outlineStyle: 'none' } as any) : {}),
  },
  digitInputFilled: {
    borderColor: AuthColors.primary,
    backgroundColor: AuthColors.white,
  },
  timerRow: {
    alignItems: 'center',
    marginTop: 12,
  },
  resendText: {
    ...AuthTypography.bodySemiBold,
    color: AuthColors.primary,
  },
  countdownText: {
    ...AuthTypography.bodyRegular,
    color: AuthColors.textSecondary,
  },
  countdownHighlight: {
    ...AuthTypography.bodyBold,
    color: AuthColors.primary,
  },
  footerSection: {
    paddingBottom: 24,
  },
});
