import React from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
  StyleProp,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export interface RadioCardOption {
  value: string;
  title: string;
  subtitle?: string;
  badge?: string;
  icon?: (selected: boolean) => React.ReactNode;
}

export interface RadioCardGroupProps {
  label?: string;
  options: RadioCardOption[];
  selectedValue: string;
  onSelect: (value: string) => void;
  disabled?: boolean;
  style?: StyleProp<ViewStyle>;
  testID?: string;
}

/**
 * Enterprise Radio Card Selector matching DBCS LOS bm-radio-card.vue.
 * Features full card highlight, primary color outline border, and optional badge/icon.
 */
export const RadioCardGroup: React.FC<RadioCardGroupProps> = ({
  label,
  options,
  selectedValue,
  onSelect,
  disabled = false,
  style,
  testID = 'radio-card-group',
}) => {
  const { theme } = useTheme();

  return (
    <View testID={testID} style={[styles.container, style]}>
      {label ? <Text style={styles.groupLabel}>{label}</Text> : null}

      <View style={styles.list}>
        {options.map((opt) => {
          const isSelected = opt.value === selectedValue;

          return (
            <TouchableOpacity
              key={opt.value}
              testID={`${testID}-option-${opt.value}`}
              disabled={disabled}
              onPress={() => onSelect(opt.value)}
              activeOpacity={0.7}
              style={[
                styles.card,
                {
                  borderColor: isSelected ? theme.colors.primary : '#E5E7EB',
                  backgroundColor: isSelected ? '#FEF2F2' : '#FFFFFF',
                },
              ]}
            >
              <View style={styles.leftRow}>
                {/* Radio Circle */}
                <View
                  style={[
                    styles.radioCircle,
                    {
                      borderColor: isSelected ? theme.colors.primary : '#D1D5DB',
                    },
                  ]}
                >
                  {isSelected ? (
                    <View
                      style={[
                        styles.radioInner,
                        { backgroundColor: theme.colors.primary },
                      ]}
                    />
                  ) : null}
                </View>

                {opt.icon ? <View style={styles.iconWrap}>{opt.icon(isSelected)}</View> : null}

                {/* Text Labels */}
                <View style={styles.textWrap}>
                  <View style={styles.titleRow}>
                    <Text
                      style={[
                        styles.title,
                        isSelected && {
                          color: theme.colors.primary,
                          fontFamily: theme.typography.fontFamilyBold,
                        },
                      ]}
                    >
                      {opt.title}
                    </Text>
                    {opt.badge ? (
                      <View
                        style={[
                          styles.badge,
                          {
                            backgroundColor: isSelected
                              ? theme.colors.primary
                              : '#E5E7EB',
                          },
                        ]}
                      >
                        <Text
                          style={[
                            styles.badgeText,
                            { color: isSelected ? '#FFFFFF' : '#4B5563' },
                          ]}
                        >
                          {opt.badge}
                        </Text>
                      </View>
                    ) : null}
                  </View>

                  {opt.subtitle ? (
                    <Text style={styles.subtitle}>{opt.subtitle}</Text>
                  ) : null}
                </View>
              </View>
            </TouchableOpacity>
          );
        })}
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    width: '100%',
  },
  groupLabel: {
    fontSize: 14,
    fontWeight: '600',
    color: '#374151',
    marginBottom: 8,
  },
  list: {
    gap: 10,
  },
  card: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: 14,
    borderRadius: 12,
    borderWidth: 1.5,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 1 },
    shadowOpacity: 0.04,
    shadowRadius: 2,
    elevation: 1,
  },
  leftRow: {
    flexDirection: 'row',
    alignItems: 'center',
    flex: 1,
  },
  radioCircle: {
    width: 20,
    height: 20,
    borderRadius: 10,
    borderWidth: 2,
    justifyContent: 'center',
    alignItems: 'center',
    marginRight: 12,
  },
  radioInner: {
    width: 10,
    height: 10,
    borderRadius: 5,
  },
  iconWrap: {
    marginRight: 12,
  },
  textWrap: {
    flex: 1,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  title: {
    fontSize: 15,
    fontWeight: '600',
    color: '#1F2937',
  },
  badge: {
    paddingHorizontal: 8,
    paddingVertical: 2,
    borderRadius: 10,
    marginLeft: 8,
  },
  badgeText: {
    fontSize: 10,
    fontWeight: '700',
  },
  subtitle: {
    fontSize: 12,
    color: '#6B7280',
    marginTop: 2,
  },
});

