/**
 * AddressLocationUtil: Utility for hierarchical administrative addresses (Province, District, Ward),
 * GPS geofencing distance calculation (Haversine formula), and street address formatting.
 * Aligned with Lotte Finance branch locator, pin address, and CIF address forms.
 */

export interface AdministrativeAddress {
  provinceCity: string;
  district: string;
  wardCommune?: string;
  streetAddress?: string;
  countryCode?: string;
  postalCode?: string;
}

export interface GeoCoordinate {
  latitude: number;
  longitude: number;
}

export class AddressLocationUtil {
  /**
   * Formats a complete single-line address string from administrative components:
   * e.g., "123 Le Loi Street, Ben Nghe Ward, District 1, Ho Chi Minh City"
   */
  public static formatAddress(addr: AdministrativeAddress): string {
    if (!addr) return '';
    const parts = [
      addr.streetAddress,
      addr.wardCommune,
      addr.district,
      addr.provinceCity,
    ].filter(Boolean);
    return parts.join(', ');
  }

  /**
   * Calculates distance between two GPS coordinates using the Haversine formula (in kilometers).
   */
  public static calculateDistanceKm(
    point1: GeoCoordinate,
    point2: GeoCoordinate
  ): number {
    const toRad = (x: number) => (x * Math.PI) / 180;
    const R = 6371; // Earth radius in km

    const dLat = toRad(point2.latitude - point1.latitude);
    const dLon = toRad(point2.longitude - point1.longitude);
    const lat1 = toRad(point1.latitude);
    const lat2 = toRad(point2.latitude);

    const a =
      Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.sin(dLon / 2) * Math.sin(dLon / 2) * Math.cos(lat1) * Math.cos(lat2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

    const distance = R * c;
    return Math.round(distance * 100) / 100;
  }

  /**
   * Checks whether a customer coordinate is within a branch service geofence (in kilometers).
   */
  public static isWithinBranchServiceArea(
    customerLoc: GeoCoordinate,
    branchLoc: GeoCoordinate,
    maxDistanceKm: number = 30
  ): { isWithin: boolean; distanceKm: number } {
    const distanceKm = this.calculateDistanceKm(customerLoc, branchLoc);
    return {
      isWithin: distanceKm <= maxDistanceKm,
      distanceKm,
    };
  }

  /**
   * Validates GPS latitude and longitude values:
   * Latitude: -90 to +90
   * Longitude: -180 to +180
   */
  public static isValidCoordinate(coord: GeoCoordinate): boolean {
    if (!coord) return false;
    const { latitude, longitude } = coord;
    if (typeof latitude !== 'number' || typeof longitude !== 'number') return false;
    if (isNaN(latitude) || isNaN(longitude)) return false;
    return latitude >= -90 && latitude <= 90 && longitude >= -180 && longitude <= 180;
  }
}

