import React, { useState } from 'react';
import {
  View,
  Text,
  ScrollView,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
  Platform,
  Linking,
  Share,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { previewPdf } from 'react-native-bizmob-plugin';

export interface PdfViewerPageItem {
  pageNumber: number;
  headerTitle?: string;
  headerSubtitle?: string;
  title?: string;
  articles?: Array<{
    title: string;
    body: string;
  }>;
  footerText?: string;
}

export interface PdfViewerProps {
  title?: string;
  documentTitle?: string;
  documentSubtitle?: string;
  effectiveDate?: string;
  sourceUri?: string;
  filePath?: string;
  pages?: PdfViewerPageItem[];
  totalPages?: number;
  onDownload?: () => void;
  onPrint?: () => void;
  onShare?: () => void;
  onOpenNativeViewer?: () => void;
  containerStyle?: ViewStyle;
  testID?: string;
}

/**
 * Enterprise PDF Viewer component matching digital banking document review screens
 * (Credit Card Terms & Conditions, Loan Agreements, Disclaimers).
 * Provides dark top toolbar (download, print, share), page navigation,
 * document typography, watermark/confidential notices, and responsive styling.
 */
export const PdfViewer: React.FC<PdfViewerProps> = ({
  title,
  documentTitle = 'TERMS AND CONDITIONS FOR INDIVIDUAL CREDIT CARD',
  documentSubtitle = 'Terms and conditions for individual credit card',
  effectiveDate = 'Effective from 30/01/2026',
  sourceUri,
  filePath,
  pages,
  totalPages = pages?.length || 2,
  onDownload,
  onPrint,
  onShare,
  onOpenNativeViewer,
  containerStyle,
  testID = 'pdf-viewer',
}) => {
  const { theme } = useTheme();
  const [currentPage, setCurrentPage] = useState(1);
  const [zoomLevel, setZoomLevel] = useState<number>(1);

  const handleOpenNative = async () => {
    if (onOpenNativeViewer) {
      onOpenNativeViewer();
      return;
    }
    const targetFile = filePath || sourceUri || 'sample_terms.pdf';
    try {
      await previewPdf({
        title: documentTitle || 'PDF Preview',
        filePath: targetFile,
        uri: sourceUri,
      });
    } catch (_) {
      if (sourceUri) {
        Linking.openURL(sourceUri).catch(() => {});
      }
    }
  };

  // Default sample structured pages if none passed
  const documentPages: PdfViewerPageItem[] = pages || [
    {
      pageNumber: 1,
      headerTitle: documentSubtitle,
      headerSubtitle: 'LOTTE FINANCE',
      title: documentTitle,
      articles: [
        {
          title: 'Article 1: Interpretation of Terms',
          body:
            'The terms used in this Credit Card Terms and Conditions will be interpreted as follows:\n\n' +
            '1. ATM (Automatic Teller Machine): Automatic transaction machine. This device allows the Cardholder to perform one or more transactions, including but not limited to: cash deposit, cash top-up, cash withdrawal, fund transfers, payment of bills for goods and services, account inquiry, PIN change, card information inquiry, or other transactions as permitted by applicable laws and regulations.\n\n' +
            '2. LOTTE Finance: Lotte General Finance Vietnam Co., Ltd.\n\n' +
            '3. Cardholder: An individual or organization LOTTE Finance agrees to provide the card for card transactions based on terms and conditions agreed on by the involved parties. Card holders include primary card holder and supplementary card holder(s).\n\n' +
            '4. Primary card holder: An individual whose name is registered in the contract for the issuance and use of the card with LOTTE Finance and who is obligated to comply with and perform the provisions of this agreement.\n\n' +
            '5. Supplementary card holder: An individual authorized in writing by the Primary cardholder to use the card in accordance with the agreement on card usage between the Primary cardholder and LOTTE Finance.\n\n' +
            '6. Insurance contract holder: is LOTTE Finance.\n\n' +
            '7. Retail: A payment transaction using the physical card or card information for goods and services that the Cardholder has used but not a cash withdrawal or cash advance.\n\n' +
            '8. Non-settlement transaction/standard: the transaction authentication eligible for implementation. The system recognizes these transactions and reduces the available credit but has not created the outstanding debt of the Cardholder.\n\n' +
            '9. Signature: The Cardholder\'s hand signature or electronic signature in accordance with the law.\n\n' +
            '10. Installment Program: A function that allows the Cardholder of the LOTTE Finance to transfer one or several transactions for consumption (except withdraw/cash advance) in many times while value of transactions by the Card is arranged into equal amounts and proceeded for consecutive payment periodically.\n\n' +
            '11. Insurance Company: is Company is a company providing Insurance Products in accordance with the law of Vietnam.\n\n' +
            '12. CS: LOTTE Finance Customer Service Department. Hotline 1900 6866 (domestic) / +84 24 7302 0202 (overseas) or email: cskh@lottefinance.vn.',
        },
      ],
      footerText: 'Tài liệu Internal: Cấm sao chép, in ấn dưới mọi hình thức nếu không được sự cho phép của Lotte Finance.  Page: 1',
    },
    {
      pageNumber: 2,
      headerTitle: documentSubtitle,
      headerSubtitle: 'LOTTE FINANCE',
      title: documentTitle,
      articles: [
        {
          title: 'Article 2: Card Issuance & Usage Security',
          body:
            '13. CVV2 / CVC2: Is a 3-digit number sequence printed on physical cards, used in online transactions or transactions that do not present other cards for the purpose of securing Card transactions.\n\n' +
            '14. Principal outstanding: The total value of card transactions paid by LOTTE Finance to related parties when the Cardholder uses the Credit Card. Principal outstanding includes expenditure outstanding and excludes interests and fees.\n\n' +
            '15. Statement outstanding (Ending Balance): The amount recorded on the statement. This is the total outstanding balance on the Cardholder\'s credit card account as of the statement closing date, including settled outstanding amounts during the statement period, fees, accrued interest, due installment amounts, and the previous period balance, less any payments made during the statement period.\n\n' +
            '16. Merchants: means organizations, individuals providing goods and services, cash advance points to accept Cards as payment instruments, including online card acceptance units (goods and services supply and sales via electronic channels).\n\n' +
            '17. Card Acceptance Devices at Point of Sale: Include Point of Sale (POS), Mobile Point of Sale (mPOS), and other card acceptance devices, which are card-reading devices and terminals installed and used at merchants.',
        },
      ],
      footerText: 'Tài liệu Internal: Cấm sao chép, in ấn dưới mọi hình thức nếu không được sự cho phép của Lotte Finance.  Page: 2',
    },
  ];

  const handleDownloadPress = () => {
    if (onDownload) {
      onDownload();
    } else if (sourceUri) {
      Linking.openURL(sourceUri).catch(() => {});
    }
  };

  const handlePrintPress = () => {
    if (onPrint) {
      onPrint();
    } else if (sourceUri) {
      if (Platform.OS === 'web' && typeof window !== 'undefined') {
        window.print();
      }
    }
  };

  const handleSharePress = async () => {
    if (onShare) {
      onShare();
    } else if (sourceUri) {
      try {
        await Share.share({
          message: `Document: ${documentTitle} - ${sourceUri}`,
          url: sourceUri,
        });
      } catch (_) {}
    }
  };

  return (
    <View testID={testID} style={[styles.container, containerStyle]}>
      {/* Title Header with Red Accent Underline */}
      {title ? (
        <View style={styles.titleSection}>
          <Text
            testID={`${testID}-main-title`}
            style={[styles.mainTitle, { color: theme.colors.text }]}
          >
            {title}
          </Text>
          <View
            style={[
              styles.redAccentLine,
              { backgroundColor: theme.colors.primary || '#E7252B' },
            ]}
          />
        </View>
      ) : null}

      {/* PDF Viewport Outer Container */}
      <View style={styles.viewerWrapper}>
        {/* PDF Dark Action Toolbar */}
        <View style={styles.toolbarRow}>
          {/* Page Indicator / Status */}
          <View style={styles.pageIndicatorWrap}>
            <Text style={styles.toolbarPageText}>
              Page {currentPage} / {documentPages.length}
            </Text>
            {/* Zoom Controls */}
            <View style={styles.zoomRow}>
              <TouchableOpacity
                testID={`${testID}-zoom-out`}
                activeOpacity={0.7}
                onPress={() => setZoomLevel((z) => Math.max(0.85, z - 0.1))}
                style={styles.zoomBtn}
              >
                <Text style={styles.zoomText}>-</Text>
              </TouchableOpacity>
              <Text style={styles.zoomLevelText}>{Math.round(zoomLevel * 100)}%</Text>
              <TouchableOpacity
                testID={`${testID}-zoom-in`}
                activeOpacity={0.7}
                onPress={() => setZoomLevel((z) => Math.min(1.3, z + 0.1))}
                style={styles.zoomBtn}
              >
                <Text style={styles.zoomText}>+</Text>
              </TouchableOpacity>
            </View>
          </View>

          {/* Action Icons (Native Fullscreen Preview, Download, Print, More / Share) */}
          <View style={styles.actionsWrap}>
            <TouchableOpacity
              testID={`${testID}-btn-native-preview`}
              activeOpacity={0.7}
              onPress={handleOpenNative}
              style={styles.toolbarIconBtn}
              accessibilityLabel="Open Fullscreen Native PDF Viewer"
            >
              {/* Fullscreen icon */}
              <Text style={styles.toolbarIcon}>⛶</Text>
            </TouchableOpacity>

            <TouchableOpacity
              testID={`${testID}-btn-download`}
              activeOpacity={0.7}
              onPress={handleDownloadPress}
              style={styles.toolbarIconBtn}
              accessibilityLabel="Download Document"
            >
              {/* SVG Download icon symbol */}
              <Text style={styles.toolbarIcon}>↓</Text>
            </TouchableOpacity>

            <TouchableOpacity
              testID={`${testID}-btn-print`}
              activeOpacity={0.7}
              onPress={handlePrintPress}
              style={styles.toolbarIconBtn}
              accessibilityLabel="Print Document"
            >
              {/* SVG Print icon symbol */}
              <Text style={styles.toolbarIcon}>⎙</Text>
            </TouchableOpacity>

            <TouchableOpacity
              testID={`${testID}-btn-share`}
              activeOpacity={0.7}
              onPress={handleSharePress}
              style={styles.toolbarIconBtn}
              accessibilityLabel="Share / More"
            >
              {/* SVG More/Share icon symbol */}
              <Text style={styles.toolbarIcon}>⋮</Text>
            </TouchableOpacity>
          </View>
        </View>

        {/* Scrollable Document Canvas */}
        <ScrollView
          style={styles.canvasScrollView}
          contentContainerStyle={styles.canvasContent}
          nestedScrollEnabled
          testID={`${testID}-scroll-canvas`}
          onScroll={(e) => {
            const y = e.nativeEvent.contentOffset.y;
            const pageH = 500;
            const pg = Math.min(documentPages.length, Math.max(1, Math.floor(y / pageH) + 1));
            if (pg !== currentPage) {
              setCurrentPage(pg);
            }
          }}
          scrollEventThrottle={16}
        >
          {documentPages.map((page) => (
            <View
              key={`page-${page.pageNumber}`}
              testID={`${testID}-page-${page.pageNumber}`}
              style={[
                styles.paperSheet,
                {
                  transform: [{ scale: zoomLevel }],
                  borderColor: theme.colors.border || '#E5E7EB',
                },
              ]}
            >
              {/* Document Header */}
              <View style={styles.docHeader}>
                <Text style={styles.docHeaderTitle}>{page.headerTitle}</Text>
                <Text style={styles.docBrandLogo}>{page.headerSubtitle}</Text>
              </View>

              {/* Title & Effective Date Box */}
              <View style={styles.docHeroBox}>
                <Text style={styles.docMainHeading}>{page.title}</Text>
                <Text style={styles.docEffectiveDate}>({effectiveDate})</Text>
              </View>

              {/* Introductory Lead Text */}
              {page.pageNumber === 1 && (
                <Text style={styles.docIntroText}>
                  A copy of the comprehensive agreement between Lotte General Finance Vietnam Co., Ltd and
                  Customer consists of Terms and conditions (T&amp;C) for LOTTE Finance Credit Card, Credit Card
                  Application and Agreement for Card Issuance and Use, Service fees and interests, and specific terms
                  and conditions for each program and special service (if applicable).{'\n\n'}
                  If agreeable, since signing the Credit Card Application and Agreement on Credit Card’s Issuance
                  and Use, and having an approval of the LOTTE Finance on Credit card issuance, the Customer will
                  be binding under this Credit Card Terms and Conditions.
                </Text>
              )}

              {/* Articles & Legal Clauses */}
              {page.articles?.map((article, idx) => (
                <View key={`art-${idx}`} style={styles.articleSection}>
                  <Text style={styles.articleHeading}>{article.title}</Text>
                  <Text style={styles.articleBody}>{article.body}</Text>
                </View>
              ))}

              {/* Document Footer Notice */}
              {page.footerText ? (
                <View style={styles.docFooter}>
                  <Text style={styles.docFooterNotice}>{page.footerText}</Text>
                </View>
              ) : null}
            </View>
          ))}
        </ScrollView>
      </View>
    </View>
  );
};

