import React, { useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
  Linking,
  Platform,
} from 'react-native';

export interface MapMarkerLocation {
  id: string;
  title: string;
  address: string;
  latitude: number;
  longitude: number;
  phone?: string;
  businessHours?: string;
}

export interface MapBranchViewProps {
  locations: MapMarkerLocation[];
  selectedLocationId?: string;
  onSelectLocation?: (location: MapMarkerLocation) => void;
  showNavigationButton?: boolean;
  /**
   * Embed real interactive Google Maps (iframe on web, satellite/street views)
   * Defaults to true
   */
  useInteractiveGoogleMap?: boolean;
  containerStyle?: ViewStyle;
  testID?: string;
}

/**
 * Enterprise Map Component for Branches & Collateral Site Visits (GL-19 / Branches / CIF / Collateral).
 * Provides:
 * - Real embedded interactive Google Maps canvas (via live embed on web & dynamic pins)
 * - Map type switcher: "Street Map" vs "Google Live Map"
 * - Dynamic interactive pin markers for all bank branches
 * - Branch information card (title, address, hours, phone)
 * - "Directions in Google Maps" external navigation trigger (Google Maps / Apple Maps E.164)
 * - One-tap phone dialer action
 */
export const MapBranchView: React.FC<MapBranchViewProps> = ({
  locations,
  selectedLocationId,
  onSelectLocation,
  showNavigationButton = true,
  useInteractiveGoogleMap = true,
  containerStyle,
  testID = 'map-branch-view',
}) => {
  const [selectedId, setSelectedId] = useState<string>(
    selectedLocationId || (locations.length > 0 ? locations[0].id : '')
  );

  const [mapMode, setMapMode] = useState<'google' | 'schematic'>('google');

  const activeLoc = locations.find((l) => l.id === selectedId) || locations[0];

  const handleSelect = (loc: MapMarkerLocation) => {
    setSelectedId(loc.id);
    onSelectLocation?.(loc);
  };

  const handleOpenExternalGoogleMap = () => {
    if (!activeLoc) return;
    const { latitude, longitude, title } = activeLoc;
    const label = encodeURIComponent(title);
    const url =
      Platform.OS === 'ios'
        ? `maps:0,0?q=${label}@${latitude},${longitude}`
        : `https://www.google.com/maps/search/?api=1&query=${latitude},${longitude}`;

    Linking.openURL(url).catch(() => {
      Linking.openURL(`https://www.google.com/maps/search/?api=1&query=${latitude},${longitude}`);
    });
  };

  const handleCallBranch = () => {
    if (!activeLoc?.phone) return;
    Linking.openURL(`tel:${activeLoc.phone.replace(/\s+/g, '')}`);
  };

  // Google Maps embed URL for the selected branch coordinates
  const googleMapEmbedUrl = activeLoc
    ? `https://maps.google.com/maps?q=${activeLoc.latitude},${activeLoc.longitude}&hl=en&z=15&output=embed`
    : '';

  return (
    <View style={[styles.container, containerStyle]} testID={testID}>
      {/* Map Header Switcher Bar */}
      <View style={styles.mapHeaderBar}>
        <View style={styles.mapTitleRow}>
          <Text style={styles.googleMapLogoText}>
            <Text style={{ color: '#4285F4' }}>G</Text>
            <Text style={{ color: '#EA4335' }}>o</Text>
            <Text style={{ color: '#FBBC05' }}>o</Text>
            <Text style={{ color: '#4285F4' }}>g</Text>
            <Text style={{ color: '#34A853' }}>l</Text>
            <Text style={{ color: '#EA4335' }}>e</Text> Maps
          </Text>
        </View>

        <View style={styles.modeToggleGroup}>
          <TouchableOpacity
            testID={`${testID}-mode-google`}
            style={[styles.modeToggleBtn, mapMode === 'google' && styles.modeToggleBtnActive]}
            onPress={() => setMapMode('google')}
            activeOpacity={0.8}
          >
            <Text style={[styles.modeToggleText, mapMode === 'google' && styles.modeToggleTextActive]}>
              Live Map
            </Text>
          </TouchableOpacity>

          <TouchableOpacity
            testID={`${testID}-mode-schematic`}
            style={[styles.modeToggleBtn, mapMode === 'schematic' && styles.modeToggleBtnActive]}
            onPress={() => setMapMode('schematic')}
            activeOpacity={0.8}
          >
            <Text style={[styles.modeToggleText, mapMode === 'schematic' && styles.modeToggleTextActive]}>
              Pins ({locations.length})
            </Text>
          </TouchableOpacity>
        </View>
      </View>

      {/* Map Canvas Area */}
      <View style={styles.mapCanvas} testID={`${testID}-canvas`}>
        {Platform.OS === 'web' && mapMode === 'google' && useInteractiveGoogleMap && googleMapEmbedUrl ? (
          // Web Interactive Embedded Google Map Iframe
          // @ts-ignore
          <iframe
            title="Google Map Branch Location"
            src={googleMapEmbedUrl}
            style={webIframeStyle}
            loading="lazy"
            allowFullScreen
          />
        ) : (
          // Native / Schematic Multi-Pin Map View
          <View style={styles.schematicView}>
            {/* Roads & River Layout */}
            <View style={styles.roadHorizontal} />
            <View style={styles.roadVertical} />
            <View style={styles.riverCurve} />

            {/* Map Marker Pins */}
            <View style={styles.pinsLayer}>
              {locations.map((loc, idx) => {
                const isSelected = loc.id === activeLoc?.id;
                const leftPct = 18 + (idx % 4) * 24;
                const topPct = 25 + Math.floor(idx / 4) * 35;

                return (
                  <TouchableOpacity
                    key={loc.id}
                    testID={`${testID}-pin-${loc.id}`}
                    style={[
                      styles.pinWrapper,
                      { left: `${leftPct}%`, top: `${topPct}%` },
                      isSelected && styles.pinWrapperActive,
                    ]}
                    onPress={() => handleSelect(loc)}
                    activeOpacity={0.8}
                  >
                    <View style={[styles.pinBubble, isSelected && styles.pinBubbleActive]}>
                      <Text style={[styles.pinNumber, isSelected && styles.pinNumberActive]}>
                        {idx + 1}
                      </Text>
                    </View>
                    <View style={[styles.pinPoint, isSelected && styles.pinPointActive]} />
                  </TouchableOpacity>
                );
              })}
            </View>
          </View>
        )}

        {/* Floating Open Google Maps Chip Button */}
        <TouchableOpacity
          testID={`${testID}-open-maps-chip`}
          style={styles.floatingGoogleMapsChip}
          onPress={handleOpenExternalGoogleMap}
          activeOpacity={0.85}
        >
          <Text style={styles.googleMapsChipText}>📍 Open in Google Maps ↗</Text>
        </TouchableOpacity>

        {/* GPS Coordinates Badge */}
        <View style={styles.mapBadge}>
          <Text style={styles.mapBadgeText}>
            GPS: {activeLoc ? `${activeLoc.latitude.toFixed(4)}, ${activeLoc.longitude.toFixed(4)}` : '0, 0'}
          </Text>
        </View>
      </View>

      {/* Selected Location Information Card */}
      {activeLoc && (
        <View testID={`${testID}-detail-card`} style={styles.infoCard}>
          <View style={styles.infoHeaderRow}>
            <View style={{ flex: 1 }}>
              <Text testID={`${testID}-branch-title`} style={styles.branchTitle}>
                {activeLoc.title}
              </Text>
              <Text style={styles.branchAddress}>{activeLoc.address}</Text>
            </View>
            <View style={styles.pinTagBadge}>
              <Text style={styles.pinTagText}>Branch</Text>
            </View>
          </View>

          {activeLoc.businessHours && (
            <Text style={styles.metaRow}>
              🕒 Hours: <Text style={styles.metaHighlight}>{activeLoc.businessHours}</Text>
            </Text>
          )}

          {/* Quick Action Buttons */}
          <View style={styles.ctaRow}>
            {activeLoc.phone && (
              <TouchableOpacity
                testID={`${testID}-call-btn`}
                style={[styles.actionBtn, styles.callBtn]}
                onPress={handleCallBranch}
                activeOpacity={0.8}
              >
                <Text style={styles.callBtnText}>📞 {activeLoc.phone}</Text>
              </TouchableOpacity>
            )}

            {showNavigationButton && (
              <TouchableOpacity
                testID={`${testID}-navigate-btn`}
                style={[styles.actionBtn, styles.navBtn]}
                onPress={handleOpenExternalGoogleMap}
                activeOpacity={0.8}
              >
                <Text style={styles.navBtnText}>Directions ↗</Text>
              </TouchableOpacity>
            )}
          </View>
        </View>
      )}
    </View>
  );
};

