import {
  setSecureStorage as nativeSetSecure,
  getSecureStorage as nativeGetSecure,
  removeSecureStorage as nativeRemoveSecure,
  clearSecureStorage as nativeClearSecure,
} from 'react-native-bizmob-plugin';
import { appLogger } from '../logger/AppLogger';

export interface SecureStorageAdapter {
  setSecureStorage: typeof nativeSetSecure;
  getSecureStorage: typeof nativeGetSecure;
  removeSecureStorage: typeof nativeRemoveSecure;
  clearSecureStorage: typeof nativeClearSecure;
}

const defaultAdapter: SecureStorageAdapter = {
  setSecureStorage: nativeSetSecure,
  getSecureStorage: nativeGetSecure,
  removeSecureStorage: nativeRemoveSecure,
  clearSecureStorage: nativeClearSecure,
};

export interface TokenSessionPayload {
  accessToken: string;
  refreshToken?: string;
  expiresAt: number; // Unix timestamp ms
  userId: string;
  userEmail?: string;
  userRole?: string;
}

/**
 * Secure Token & Keystore Storage Service (`SecureTokenStorageService`)
 *
 * Backed by native Secure Enclave / KeyStore via `react-native-bizmob-plugin`.
 * Stores JWT authentication tokens, session metadata, and biometric credentials securely.
 */
export class SecureTokenStorageService {
  private static instance: SecureTokenStorageService;
  private adapter: SecureStorageAdapter;
  private memoryCache: Map<string, string> = new Map();

  private static readonly KEY_ACCESS_TOKEN = 'LOS_SEC_ACCESS_TOKEN';
  private static readonly KEY_REFRESH_TOKEN = 'LOS_SEC_REFRESH_TOKEN';
  private static readonly KEY_SESSION_PAYLOAD = 'LOS_SEC_SESSION_DATA';

  constructor(adapter: SecureStorageAdapter = defaultAdapter) {
    this.adapter = adapter;
  }

  public static getInstance(): SecureTokenStorageService {
    if (!SecureTokenStorageService.instance) {
      SecureTokenStorageService.instance = new SecureTokenStorageService();
    }
    return SecureTokenStorageService.instance;
  }

  /**
   * Saves a key-value pair into hardware-encrypted storage.
   */
  public async setItem(key: string, value: string): Promise<boolean> {
    this.memoryCache.set(key, value);
    try {
      const res = await this.adapter.setSecureStorage(key, value);
      return res?.header?.result ?? true;
    } catch (err) {
      appLogger.w('SecureTokenStorageService', `⚠️ Failed to save key [${key}] in secure storage, maintained in memory:`, err);
      return true;
    }
  }

  /**
   * Retrieves a key-value pair from hardware-encrypted storage.
   */
  public async getItem(key: string): Promise<string | null> {
    try {
      const res = await this.adapter.getSecureStorage(key);
      if (res?.header?.result && res?.body?.value !== undefined && res.body.value !== null) {
        this.memoryCache.set(key, res.body.value);
        return res.body.value;
      }
    } catch {}

    return this.memoryCache.get(key) || null;
  }

  /**
   * Deletes a key from secure storage.
   */
  public async removeItem(key: string): Promise<boolean> {
    this.memoryCache.delete(key);
    try {
      const res = await this.adapter.removeSecureStorage(key);
      return res?.header?.result ?? true;
    } catch {
      return true;
    }
  }

  /**
   * Saves the active authentication session.
   */
  public async saveSession(session: TokenSessionPayload): Promise<boolean> {
    await this.setItem(SecureTokenStorageService.KEY_ACCESS_TOKEN, session.accessToken);
    if (session.refreshToken) {
      await this.setItem(SecureTokenStorageService.KEY_REFRESH_TOKEN, session.refreshToken);
    }
    await this.setItem(SecureTokenStorageService.KEY_SESSION_PAYLOAD, JSON.stringify(session));
    return true;
  }

  /**
   * Retrieves the active authentication session.
   */
  public async getSession(): Promise<TokenSessionPayload | null> {
    const raw = await this.getItem(SecureTokenStorageService.KEY_SESSION_PAYLOAD);
    if (!raw) return null;
    try {
      return JSON.parse(raw) as TokenSessionPayload;
    } catch {
      return null;
    }
  }

  /**
   * Checks if the active access token is valid and unexpired.
   */
  public async isTokenValid(): Promise<boolean> {
    const session = await this.getSession();
    if (!session || !session.accessToken) return false;
    return Date.now() < session.expiresAt;
  }

  /**
   * Emergency wipe on user logout or compromise.
   */
  public async clearAll(): Promise<boolean> {
    this.memoryCache.clear();
    try {
      const res = await this.adapter.clearSecureStorage();
      return res?.header?.result ?? true;
    } catch {
      return true;
    }
  }
}

export const defaultSecureTokenStorageService = SecureTokenStorageService.getInstance();
