import React from 'react';
import { View, Text, StyleSheet, ViewStyle, TextStyle } from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export type AppBadgeVariant = 'primary' | 'success' | 'warning' | 'error' | 'info' | 'neutral' | 'outline';
export type AppBadgeSize = 'sm' | 'md' | 'lg';

export interface AppBadgeProps {
  /**
   * The text or number to display inside the badge.
   * If omitted or undefined, and dot is true, a standalone dot badge will be rendered.
   */
  content?: string | number;

  /**
   * Maximum numeric value before formatting with '+'. E.g. maxCount=99 renders '99+' when content > 99.
   */
  maxCount?: number;

  /**
   * Color theme variant of the badge.
   * Default: 'primary'
   */
  variant?: AppBadgeVariant;

  /**
   * Size scale of the badge.
   * Default: 'md'
   */
  size?: AppBadgeSize;

  /**
   * If true, renders as a small dot indicator (content is ignored).
   */
  dot?: boolean;

  /**
   * Custom style overrides for the outer badge container.
   */
  style?: ViewStyle;

  /**
   * Custom style overrides for the inner badge text.
   */
  textStyle?: TextStyle;

  /**
   * Optional icon to render on the left of content (for pill / chip badges).
   */
  leftIcon?: React.ReactNode;

  /**
   * Accessible test ID.
   */
  testID?: string;
}

export const AppBadge: React.FC<AppBadgeProps> = ({
  content,
  maxCount = 99,
  variant = 'primary',
  size = 'md',
  dot = false,
  style,
  textStyle,
  leftIcon,
  testID = 'app-badge',
}) => {
  const { theme } = useTheme();

  // If content is empty/undefined and dot is not explicitly true, do not render
  if (content === undefined && !dot) {
    return null;
  }

  // Format content (supports maxCount)
  let displayContent: string | number = '';
  if (!dot) {
    if (typeof content === 'number' && maxCount !== undefined && content > maxCount) {
      displayContent = `${maxCount}+`;
    } else {
      displayContent = content ?? '';
    }
  }

  // Variant color definitions
  const getVariantStyles = (): { bg: string; text: string; border?: string } => {
    switch (variant) {
      case 'primary':
        return { bg: theme.colors.primary, text: '#FFFFFF' };
      case 'success':
        return { bg: theme.colors.success, text: '#FFFFFF' };
      case 'warning':
        return { bg: theme.colors.warning, text: '#FFFFFF' };
      case 'error':
        return { bg: theme.colors.error, text: '#FFFFFF' };
      case 'info':
        return { bg: theme.colors.info, text: '#FFFFFF' };
      case 'neutral':
        return { bg: theme.colors.border, text: theme.colors.text };
      case 'outline':
        return {
          bg: 'transparent',
          text: theme.colors.text,
          border: theme.colors.border,
        };
      default:
        return { bg: theme.colors.primary, text: '#FFFFFF' };
    }
  };

  const { bg, text, border } = getVariantStyles();

  // Dot styles
  if (dot) {
    const dotDimension = size === 'sm' ? 6 : size === 'lg' ? 12 : 8;
    return (
      <View
        testID={testID}
        style={[
          styles.dot,
          {
            width: dotDimension,
            height: dotDimension,
            borderRadius: dotDimension / 2,
            backgroundColor: bg,
          },
          border ? { borderWidth: 1, borderColor: border } : null,
          style,
        ]}
      />
    );
  }

  // Size configurations
  const getSizeStyles = () => {
    switch (size) {
      case 'sm':
        return {
          minWidth: 16,
          height: 16,
          paddingHorizontal: 4,
          fontSize: 10,
          borderRadius: 8,
        };
      case 'lg':
        return {
          minWidth: 26,
          height: 26,
          paddingHorizontal: 8,
          fontSize: 14,
          borderRadius: 13,
        };
      case 'md':
      default:
        return {
          minWidth: 20,
          height: 20,
          paddingHorizontal: 6,
          fontSize: 11,
          borderRadius: 10,
        };
    }
  };

  const sizeStyle = getSizeStyles();

  return (
    <View
      testID={testID}
      style={[
        styles.badge,
        {
          minWidth: sizeStyle.minWidth,
          height: sizeStyle.height,
          borderRadius: sizeStyle.borderRadius,
          paddingHorizontal: sizeStyle.paddingHorizontal,
          backgroundColor: bg,
        },
        border ? { borderWidth: 1, borderColor: border } : null,
        style,
      ]}
    >
      {leftIcon ? <View style={styles.leftIconContainer}>{leftIcon}</View> : null}
      <Text
        style={[
          styles.text,
          {
            fontSize: sizeStyle.fontSize,
            lineHeight: sizeStyle.height,
            color: text,
          },
          textStyle,
        ]}
        numberOfLines={1}
      >
        {displayContent}
      </Text>
    </View>
  );
};

const styles = StyleSheet.create({
  badge: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    alignSelf: 'flex-start',
  },
  dot: {
    alignSelf: 'center',
  },
  leftIconContainer: {
    marginRight: 4,
  },
  text: {
    fontWeight: '700',
    textAlign: 'center',
    includeFontPadding: false,
  },
});
