/**
 * SecurityAuthUtil: Utility for authentication security policies, password complexity,
 * PIN security rules, failed login lockout countdowns, and masking.
 * Aligned with Lotte Finance AU-002, AU-005, AU-014, and GL-15 lockout specifications.
 */

export interface PasswordRuleCheck {
  id: 'LENGTH' | 'HAS_UPPER' | 'HAS_LOWER' | 'HAS_NUMBER' | 'HAS_SPECIAL' | 'NO_SPACES';
  label: string;
  isSatisfied: boolean;
}

export interface PasswordValidationResult {
  isValid: boolean;
  score: number; // 0 - 100
  rules: PasswordRuleCheck[];
  strength: 'WEAK' | 'MEDIUM' | 'STRONG';
}

export class SecurityAuthUtil {
  public static readonly MAX_FAILED_ATTEMPTS = 5;
  public static readonly LOCKOUT_DURATION_MINUTES = 15;

  /**
   * Validates password against enterprise banking complexity rules:
   * 1. 8 to 20 characters
   * 2. At least 1 uppercase letter
   * 3. At least 1 lowercase letter
   * 4. At least 1 numeric digit
   * 5. At least 1 special character (!@#$%^&*()_+)
   * 6. No whitespace
   */
  public static validatePassword(password: string): PasswordValidationResult {
    const pwd = password || '';

    const rules: PasswordRuleCheck[] = [
      {
        id: 'LENGTH',
        label: '8 to 20 characters',
        isSatisfied: pwd.length >= 8 && pwd.length <= 20,
      },
      {
        id: 'HAS_UPPER',
        label: 'At least 1 uppercase letter (A-Z)',
        isSatisfied: /[A-Z]/.test(pwd),
      },
      {
        id: 'HAS_LOWER',
        label: 'At least 1 lowercase letter (a-z)',
        isSatisfied: /[a-z]/.test(pwd),
      },
      {
        id: 'HAS_NUMBER',
        label: 'At least 1 number (0-9)',
        isSatisfied: /[0-9]/.test(pwd),
      },
      {
        id: 'HAS_SPECIAL',
        label: 'At least 1 special character (!@#$%^&*)',
        isSatisfied: /[!@#$%^&*()_+\-=[\]{};':"\\|,.<>/?]/.test(pwd),
      },
      {
        id: 'NO_SPACES',
        label: 'No whitespace',
        isSatisfied: !/\s/.test(pwd) && pwd.length > 0,
      },
    ];

    const satisfiedCount = rules.filter((r) => r.isSatisfied).length;
    const score = Math.round((satisfiedCount / rules.length) * 100);

    let strength: 'WEAK' | 'MEDIUM' | 'STRONG' = 'WEAK';
    if (satisfiedCount === rules.length) {
      strength = 'STRONG';
    } else if (satisfiedCount >= 4) {
      strength = 'MEDIUM';
    }

    return {
      isValid: satisfiedCount === rules.length,
      score,
      rules,
      strength,
    };
  }

  /**
   * Validates banking 6-digit transaction PIN / Passcode:
   * Disallows sequential numbers (123456, 654321) and repeated digits (111111).
   */
  public static validatePin(pin: string): { valid: boolean; error?: string } {
    if (!pin) return { valid: false, error: 'PIN is required.' };
    const clean = pin.trim();

    if (!/^\d{6}$/.test(clean)) {
      return { valid: false, error: 'PIN must be exactly 6 digits.' };
    }

    // Repeated digits (e.g. 111111, 000000)
    if (/^(\d)\1{5}$/.test(clean)) {
      return {
        valid: false,
        error: 'PIN cannot consist of repeating identical digits.',
      };
    }

    // Sequential forward (e.g. 123456)
    const sequentialAsc = '0123456789';
    const sequentialDesc = '9876543210';
    if (sequentialAsc.includes(clean) || sequentialDesc.includes(clean)) {
      return {
        valid: false,
        error: 'PIN cannot be sequential numbers (e.g. 123456).',
      };
    }

    return { valid: true };
  }

  /**
   * Tracks failed login attempts and calculates lockout status.
   */
  public static checkLockoutStatus(params: {
    failedAttempts: number;
    lastFailedTimestamp?: number;
    now?: number;
  }): {
    isLocked: boolean;
    remainingMinutes: number;
    remainingAttempts: number;
  } {
    const { failedAttempts, lastFailedTimestamp, now = Date.now() } = params;

    const remainingAttempts = Math.max(0, this.MAX_FAILED_ATTEMPTS - failedAttempts);

    if (failedAttempts < this.MAX_FAILED_ATTEMPTS) {
      return { isLocked: false, remainingMinutes: 0, remainingAttempts };
    }

    if (!lastFailedTimestamp) {
      return {
        isLocked: true,
        remainingMinutes: this.LOCKOUT_DURATION_MINUTES,
        remainingAttempts: 0,
      };
    }

    const elapsedMs = now - lastFailedTimestamp;
    const lockoutMs = this.LOCKOUT_DURATION_MINUTES * 60 * 1000;

    if (elapsedMs >= lockoutMs) {
      // Lockout expired
      return { isLocked: false, remainingMinutes: 0, remainingAttempts: this.MAX_FAILED_ATTEMPTS };
    }

    const remainingMinutes = Math.ceil((lockoutMs - elapsedMs) / (60 * 1000));
    return { isLocked: true, remainingMinutes, remainingAttempts: 0 };
  }
}

