import {
  defaultNetworkService,
  INetworkService,
  TR_CODES,
} from '@mfe/core';
import {
  DashboardKpiDTO,
  DashboardSummaryDTO,
  DebtorItemDTO,
} from '../models/DashboardModel';

export type {
  DashboardKpiDTO,
  DashboardSummaryDTO,
  DebtorItemDTO,
  DashboardPeriodTab,
  DashboardAuthStatsDTO,
  DashboardTodoHistoryDTO,
  DashboardDebtorPeriodMetricDTO,
} from '../models/DashboardModel';

export interface IDashboardService {
  getDashboardSummary(useMock?: boolean): Promise<DashboardSummaryDTO>;
  getSalesKpi(useMock?: boolean): Promise<DashboardKpiDTO>;
  getDebtorList(useMock?: boolean): Promise<DebtorItemDTO[]>;
}

