import React from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  ViewStyle,
  Platform,
} from 'react-native';
import Svg, { Path, Rect } from 'react-native-svg';
import { OtpInput } from '../input/OtpInput';
import { CountdownTimer } from '../feedback/CountdownTimer';

export interface PhoneOtpVerificationViewProps {
  /**
   * Title (default: "Verify phone number")
   */
  title?: string;
  /**
   * Explanatory text (default: "Enter the OTP sent to your phone number.")
   */
  subtitle?: string;
  /**
   * Phone number to display with red phone icon (e.g. "09*****567")
   */
  phoneNumber?: string;
  /**
   * OTP code length (default: 6)
   */
  length?: number;
  /**
   * Current OTP value
   */
  value?: string;
  /**
   * Callback when OTP changes
   */
  onChangeOtp?: (otp: string) => void;
  /**
   * Callback when user enters all digits
   */
  onOtpComplete?: (otp: string) => void;
  /**
   * Initial timer countdown in seconds (default: 180s = 03:00)
   */
  countdownSeconds?: number;
  /**
   * Callback triggered when resend code is pressed
   */
  onResendCode?: () => void;
  /**
   * Back button callback (top left arrow)
   */
  onBackPress?: () => void;
  /**
   * Custom style for container
   */
  style?: ViewStyle;
  /**
   * Accessibility test ID
   */
  testID?: string;
}

