/**
 * PhoneOtpVerificationView (AU-010)
 *
 * Full verification view matching AU-010 Phone OTP Verification:
 * - Back button top navigation
 * - Centered Lock 3D graphic illustration
 * - Bold title & subtitle
 * - Phone indicator with red mobile phone icon
 * - 6 rounded digit boxes for OTP
 * - Countdown timer + resend button
 */
export const PhoneOtpVerificationView: React.FC<PhoneOtpVerificationViewProps> = ({
  title = 'Verify phone number',
  subtitle = 'Enter the OTP sent to your phone number.',
  phoneNumber = '09*****567',
  length = 6,
  value,
  onChangeOtp,
  onOtpComplete,
  countdownSeconds = 180,
  onResendCode,
  onBackPress,
  style,
  testID = 'phone-otp-view',
}) => {
  return (
    <View style={[styles.container, style]} testID={testID}>
      {/* Top Header / Back Arrow */}
      {onBackPress ? (
        <View style={styles.headerRow}>
          <TouchableOpacity
            testID={`${testID}-back-btn`}
            onPress={onBackPress}
            style={styles.backButton}
            activeOpacity={0.7}
          >
            <Svg width={24} height={24} viewBox="0 0 24 24" fill="none">
              <Path
                d="M19 12H5M5 12L12 19M5 12L12 5"
                stroke="#0F172A"
                strokeWidth={2.2}
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </Svg>
          </TouchableOpacity>
        </View>
      ) : null}

      {/* Lock Graphic */}
      <View style={styles.centerSection}>
        <PhoneSecurityLockIcon />

        {/* Title */}
        <Text style={styles.title} testID={`${testID}-title`}>
          {title}
        </Text>

        {/* Subtitle */}
        <Text style={styles.subtitle} testID={`${testID}-subtitle`}>
          {subtitle}
        </Text>

        {/* Phone number row */}
        {phoneNumber ? (
          <View style={styles.phoneRow} testID={`${testID}-phone-row`}>
            <RedMobilePhoneIcon />
            <Text style={styles.phoneNumber} testID={`${testID}-phone-number`}>
              {phoneNumber}
            </Text>
          </View>
        ) : null}

        {/* 6-box OTP Input */}
        <View style={styles.otpWrapper}>
          <OtpInput
            length={length}
            value={value}
            onChangeOtp={onChangeOtp}
            onOtpComplete={onOtpComplete}
            testID={`${testID}-input`}
          />
        </View>

        {/* Countdown Timer with Resend Code */}
        <View style={styles.timerWrapper}>
          <CountdownTimer
            initialSeconds={countdownSeconds}
            prefixText="The code can be resent after:"
            resendText="Resend code"
            onResend={onResendCode}
            testID={`${testID}-timer`}
          />
        </View>
      </View>
    </View>
  );
};

