import {
  defaultOfflineDataService,
  IOfflineDataService,
  OfflineRecord,
} from '../storage/OfflineDataService';
import {
  defaultNetworkService,
  INetworkService,
} from '../network/NetworkService';
import { defaultAppEventBus, AppEventBus, APP_EVENTS } from './AppEventBus';
import { appLogger } from '../logger/AppLogger';

export interface SyncProgressInfo {
  total: number;
  processed: number;
  successful: number;
  failed: number;
  currentRecord?: OfflineRecord;
  isComplete: boolean;
}

export type SyncHandler = (record: OfflineRecord) => Promise<boolean>;

/**
 * Offline-to-Cloud Sync Reconciliation Service (`SyncReconciliationService`)
 *
 * Coordinates automatic or on-demand synchronization of offline draft records
 * (e.g. Loan Application Drafts, Customer Registrations, Site Inspection Reports)
 * to Core Banking and remote backends.
 */
export class SyncReconciliationService {
  private static instance: SyncReconciliationService;
  private offlineService: IOfflineDataService;
  private networkService: INetworkService;
  private eventBus: AppEventBus;
  private isSyncing = false;
  private categoryHandlers: Map<string, SyncHandler> = new Map();

  constructor(
    offlineService: IOfflineDataService = defaultOfflineDataService,
    networkService: INetworkService = defaultNetworkService,
    eventBus: AppEventBus = defaultAppEventBus
  ) {
    this.offlineService = offlineService;
    this.networkService = networkService;
    this.eventBus = eventBus;
  }

  public static getInstance(): SyncReconciliationService {
    if (!SyncReconciliationService.instance) {
      SyncReconciliationService.instance = new SyncReconciliationService();
    }
    return SyncReconciliationService.instance;
  }

  /**
   * Registers a domain handler for reconciling records of a specific category.
   * e.g. 'LOAN_APPLICATION' -> (record) => loanService.submit(record.data)
   */
  public registerCategoryHandler(category: string, handler: SyncHandler): void {
    this.categoryHandlers.set(category, handler);
  }

  /**
   * Triggers synchronization of all pending offline records.
   */
  public async reconcilePendingRecords(): Promise<{
    processed: number;
    successful: number;
    failed: number;
  }> {
    if (this.isSyncing) {
      appLogger.w('SyncReconciliationService', '⚠️ Synchronization already in progress.');
      return { processed: 0, successful: 0, failed: 0 };
    }

    // 1. Verify connectivity
    const connectivity = await this.networkService.checkConnectivity();
    if (!connectivity.isConnected) {
      appLogger.w('SyncReconciliationService', '⚠️ Cannot sync: Device is currently offline.');
      return { processed: 0, successful: 0, failed: 0 };
    }

    this.isSyncing = true;
    this.eventBus.publish(APP_EVENTS.SYNC_STARTED, { timestamp: Date.now() });

    try {
      const pendingRecords = await this.offlineService.getPendingSyncRecords();
      const total = pendingRecords.length;
      let successful = 0;
      let failed = 0;

      if (total === 0) {
        this.eventBus.publish(APP_EVENTS.SYNC_COMPLETED, {
          total: 0,
          successful: 0,
          failed: 0,
        });
        return { processed: 0, successful: 0, failed: 0 };
      }

      for (let i = 0; i < total; i++) {
        const record = pendingRecords[i];
        const handler = this.categoryHandlers.get(record.category);

        let isSuccess = false;
        if (handler) {
          try {
            isSuccess = await handler(record);
          } catch (handlerErr) {
            appLogger.e('SyncReconciliationService', `❌ Handler error for [${record.category}:${record.key}]`, handlerErr);
            isSuccess = false;
          }
        } else {
          // Default: Mark record as reconciled if no special handler is bound
          isSuccess = true;
        }

        if (isSuccess) {
          await this.offlineService.markRecordSynced(record.category, record.key);
          successful++;
        } else {
          failed++;
        }

        this.eventBus.publish<SyncProgressInfo>(APP_EVENTS.SYNC_PROGRESS, {
          total,
          processed: i + 1,
          successful,
          failed,
          currentRecord: record,
          isComplete: i === total - 1,
        });
      }

      this.eventBus.publish(APP_EVENTS.SYNC_COMPLETED, {
        total,
        successful,
        failed,
      });

      return { processed: total, successful, failed };
    } finally {
      this.isSyncing = false;
    }
  }

  public getIsSyncing(): boolean {
    return this.isSyncing;
  }
}

export const defaultSyncReconciliationService = SyncReconciliationService.getInstance();
