import React from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  Modal,
  Platform,
  ViewStyle,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export interface AnotherDeviceLoginConfirmModalProps {
  /**
   * Modal visibility state.
   */
  visible: boolean;

  /**
   * Device model/name attempting login (e.g. "iPhone 15 Pro", "Samsung SM-S918B").
   * Optional details.
   */
  deviceName?: string;

  /**
   * Location or IP of attempt (e.g. "Ho Chi Minh City, VN", "Phnom Penh, KH").
   */
  location?: string;

  /**
   * Timestamp of attempt.
   */
  timestamp?: string;

  /**
   * Triggered when the user taps "It's me" (authorizes other device or logs out current device).
   */
  onConfirmItsMe: () => void;

  /**
   * Triggered when the user taps "It's not me" (blocks access, secures account).
   */
  onRejectNotMe: () => void;

  /**
   * Triggered when user closes via backdrop or top-right close '✕' button.
   */
  onClose?: () => void;

  /**
   * Loading indicator when an action is in flight.
   */
  isLoading?: boolean;

  /**
   * Custom style overrides.
   */
  style?: ViewStyle;

  /**
   * Accessible test ID.
   */
  testID?: string;
}

export const AnotherDeviceLoginConfirmModal: React.FC<AnotherDeviceLoginConfirmModalProps> = ({
  visible,
  deviceName,
  location,
  timestamp,
  onConfirmItsMe,
  onRejectNotMe,
  onClose,
  isLoading = false,
  testID = 'another-device-login-modal',
}) => {
  const { theme } = useTheme();

  return (
    <Modal
      transparent
      animationType="fade"
      visible={visible}
      onRequestClose={onClose || onRejectNotMe}
      statusBarTranslucent
    >
      <View testID={testID} style={styles.backdrop}>
        <View testID={`${testID}-card`} style={styles.card}>
          {/* Close button (✕) */}
          <TouchableOpacity
            testID={`${testID}-close-button`}
            style={styles.closeButton}
            onPress={onClose || onRejectNotMe}
            disabled={isLoading}
            hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
            activeOpacity={0.7}
          >
            <Text style={styles.closeIcon}>✕</Text>
          </TouchableOpacity>

          {/* Heading */}
          <Text testID={`${testID}-title`} style={styles.title}>
            An unknown device is trying to log in to your account
          </Text>

          {/* Subtitle / Policy info */}
          <Text testID={`${testID}-subtitle`} style={styles.subtitle}>
            Each account can log in on one device only
          </Text>

          {/* Optional Details Box if device info / location is passed */}
          {deviceName || location || timestamp ? (
            <View testID={`${testID}-device-info`} style={styles.infoBox}>
              {deviceName ? (
                <View style={styles.infoRow}>
                  <Text style={styles.infoLabel}>Device:</Text>
                  <Text style={styles.infoValue}>{deviceName}</Text>
                </View>
              ) : null}
              {location ? (
                <View style={styles.infoRow}>
                  <Text style={styles.infoLabel}>Location:</Text>
                  <Text style={styles.infoValue}>{location}</Text>
                </View>
              ) : null}
              {timestamp ? (
                <View style={styles.infoRow}>
                  <Text style={styles.infoLabel}>Time:</Text>
                  <Text style={styles.infoValue}>{timestamp}</Text>
                </View>
              ) : null}
            </View>
          ) : null}

          {/* Primary Action: It's me (Red filled) */}
          <TouchableOpacity
            testID={`${testID}-confirm-button`}
            style={[
              styles.primaryButton,
              { backgroundColor: theme.colors.primary || '#D3141B' },
              isLoading && styles.buttonDisabled,
            ]}
            onPress={onConfirmItsMe}
            disabled={isLoading}
            activeOpacity={0.8}
          >
            <Text style={styles.primaryButtonText}>It's me</Text>
          </TouchableOpacity>

          {/* Secondary Action: It's not me (Outlined with red border & text) */}
          <TouchableOpacity
            testID={`${testID}-reject-button`}
            style={[
              styles.secondaryButton,
              { borderColor: theme.colors.primary || '#D3141B' },
              isLoading && styles.buttonDisabled,
            ]}
            onPress={onRejectNotMe}
            disabled={isLoading}
            activeOpacity={0.8}
          >
            <Text style={[styles.secondaryButtonText, { color: theme.colors.primary || '#D3141B' }]}>
              It's not me
            </Text>
          </TouchableOpacity>
        </View>
      </View>
    </Modal>
  );
};

