import {
  AppVersionInfo,
  SupportedLanguage,
  DeviceInfoResult,
  ContentUpdateProgress,
} from '../models/LaunchModel';
import { getDeviceInfo, callPlugin, CallPluginOptions } from 'react-native-bizmob-plugin';
import { getTranslation } from '@mfe/core/i18n';
import {
  defaultNetworkService,
  INetworkService,
  TR_CODES,
  ContentUpdateService,
  type RemoteUpdateItem,
} from '@mfe/core';

export interface ILaunchService {
  getAppVersion(useMock?: boolean): Promise<AppVersionInfo>;
  checkForUpdates(
    onProgress: (progress: { percentage: number; statusText: string }) => void
  ): Promise<boolean>;
  getStoredLanguage(): Promise<SupportedLanguage | null>;
  saveLanguage(lang: SupportedLanguage): Promise<void>;
  hasAcceptedTerms(): Promise<boolean>;
  acceptTerms(): Promise<void>;
  getTermsContent(lang?: SupportedLanguage): Promise<string>;
  getDeviceInfo(): Promise<DeviceInfoResult | null>;
  callPlugin<TResult = any, TParams = Record<string, any>>(
    pluginIdOrOptions: string | CallPluginOptions<TParams, TResult>,
    params?: TParams
  ): Promise<TResult>;
}

export class LaunchService implements ILaunchService {
  private static readonly DEFAULT_VERSION: AppVersionInfo = {
    version: '1.0.0',
    copyright: '© Mobile C&C Cambodia Co., Ltd. 2025',
  };

  private static readonly DEFAULT_TERMS: string =
    'I. Introduction\nThese General Terms and Conditions (the “Terms”) govern the use of products and services offered by [Microfinance Institution Plc.] (the “Institution”). They are provided to help all clients (the “Client”) understand their rights and obligations before applying for or using any of the Institution’s products or services.\n\nBy signing any application form for the Institution’s products or services, or by providing instructions or using the services without an application form, the Client is deemed to have read, understood, and accepted these Terms, as well as any additional specific terms and conditions applicable to each product or service.\n\nAll personal data, transaction records, and identity documents are stored in strict compliance with the applicable data protection regulations of Cambodia and the National Bank of Cambodia.';

  private mockSelectedLanguage: SupportedLanguage | null = null;
  private mockTermsAccepted: boolean = false;
  private networkService: INetworkService;
  private useMock: boolean;

  constructor(
    networkService: INetworkService = defaultNetworkService,
    useMock: boolean = true
  ) {
    this.networkService = networkService;
    this.useMock = useMock;
  }

  async getAppVersion(useMock: boolean = this.useMock): Promise<AppVersionInfo> {
    const res = await this.networkService.request<AppVersionInfo>({
      trCode: TR_CODES.LAUNCH_INIT,
      useMock,
    });
    if (res.result && res.body?.version) {
      return {
        version: res.body.version,
        copyright: res.body.copyright || LaunchService.DEFAULT_VERSION.copyright,
      };
    }
    return LaunchService.DEFAULT_VERSION;
  }

  async checkForUpdates(
    onProgress: (progress: { percentage: number; statusText: string }) => void
  ): Promise<boolean> {
    try {
      // 1. Fetch current local remote versions
      const localVersions = await ContentUpdateService.getInstalledVersions();

      // 2. Query enterprise OTA Content Server
      onProgress({ percentage: 5, statusText: 'Checking for updates...' });
      const updates = await ContentUpdateService.checkForUpdates(localVersions);

      if (!updates || updates.length === 0) {
        onProgress({ percentage: 100, statusText: 'Ready' });
        return true;
      }

      // 3. Download and extract each updated remote bundle
      await ContentUpdateService.downloadAndApplyUpdates(updates, (info) => {
        onProgress({
          percentage: info.percentage,
          statusText: info.statusText,
        });
      });

      return true;
    } catch (error) {
      console.warn('[LaunchService] OTA Update failed, continuing with cached bundle:', error);
      onProgress({ percentage: 100, statusText: 'Ready' });
      return false;
    }
  }

  async getStoredLanguage(): Promise<SupportedLanguage | null> {
    return Promise.resolve(this.mockSelectedLanguage);
  }

  async saveLanguage(lang: SupportedLanguage): Promise<void> {
    this.mockSelectedLanguage = lang;
    return Promise.resolve();
  }

  async hasAcceptedTerms(): Promise<boolean> {
    return Promise.resolve(this.mockTermsAccepted);
  }

  async acceptTerms(): Promise<void> {
    this.mockTermsAccepted = true;
    return Promise.resolve();
  }

  async getTermsContent(lang?: SupportedLanguage): Promise<string> {
    const targetLang = lang || this.mockSelectedLanguage || 'en';
    const translation = getTranslation(targetLang);
    return Promise.resolve(translation.launch.terms.termsContent || LaunchService.DEFAULT_TERMS);
  }

  async getDeviceInfo(): Promise<DeviceInfoResult | null> {
    try {
      const response: any = await getDeviceInfo();
      const body = response?.body || response;
      if (body) {
        return {
          deviceId: body.device_id || body.device_uuid || '',
          osType: body.os_type || '',
          osVersion: body.os_version || '',
          model: body.model,
          manufacturer: body.manufacturer,
          language: body.language,
        };
      }
      return null;
    } catch (error) {
      console.warn('Failed to getDeviceInfo via bizMOB plugin:', error);
      return null;
    }
  }

  async callPlugin<TResult = any, TParams = Record<string, any>>(
    pluginIdOrOptions: string | CallPluginOptions<TParams, TResult>,
    params?: TParams
  ): Promise<TResult> {
    return callPlugin<TResult, TParams>(pluginIdOrOptions, params);
  }
}
