import React, { createContext, useContext, useState, useMemo } from 'react';
import { AppTheme, defaultTheme } from './tokens';

export type DeepPartial<T> = {
  [P in keyof T]?: T[P] extends object ? DeepPartial<T[P]> : T[P];
};

interface ThemeContextType {
  theme: AppTheme;
  setTheme: (theme: AppTheme) => void;
  updateTheme: (overrides: DeepPartial<AppTheme>) => void;
  resetTheme: () => void;
}

const ThemeContext = createContext<ThemeContextType>({
  theme: defaultTheme,
  setTheme: () => {},
  updateTheme: () => {},
  resetTheme: () => {},
});

export interface ThemeProviderProps {
  initialTheme?: AppTheme;
  children: React.ReactNode;
}

export const ThemeProvider: React.FC<ThemeProviderProps> = ({
  initialTheme = defaultTheme,
  children,
}) => {
  const [theme, setTheme] = useState<AppTheme>(initialTheme);

  const updateTheme = (overrides: DeepPartial<AppTheme>) => {
    setTheme((prev) => ({
      colors: { ...prev.colors, ...(overrides.colors || {}) },
      radius: { ...prev.radius, ...(overrides.radius || {}) },
      spacing: { ...prev.spacing, ...(overrides.spacing || {}) },
      typography: {
        ...prev.typography,
        ...(overrides.typography || {}),
        sizes: {
          ...prev.typography.sizes,
          ...((overrides.typography && overrides.typography.sizes) || {}),
        },
      },
      modal: {
        ...prev.modal,
        ...(overrides.modal || {}),
      },
    }));
  };

  const resetTheme = () => {
    setTheme(defaultTheme);
  };

  const value = useMemo(
    () => ({
      theme,
      setTheme,
      updateTheme,
      resetTheme,
    }),
    [theme]
  );

  return (
    <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>
  );
};

export const useTheme = (): ThemeContextType => {
  return useContext(ThemeContext);
};

