import React, { useState } from 'react';
import { View, Text, StyleSheet } from 'react-native';
import {
  AppCard,
  PeriodPickerField,
  PeriodValue,
  SegmentedControl,
  CalendarLocale,
} from '@mfe/ui-components/components';
import { CodeBlock } from '../../components/CodeBlock';

const PERIOD_PICKER_SNIPPET = `import { PeriodPickerField, PeriodValue } from '@mfe/ui-components/components';

// Single Month / Quarter / Semester / Year
<PeriodPickerField
  label="Select Quarter"
  granularity="quarter" // 'month' | 'quarter' | 'semester' | 'year'
  selectionMode="single"
  value={quarter}
  onChange={(val, display) => setQuarter(val)}
/>

// Period Range (From ~ To)
<PeriodPickerField
  label="Select Month Range"
  granularity="month"
  selectionMode="range"
  startValue={monthStart}
  endValue={monthEnd}
  onChangeRange={(start, end) => {
    setMonthStart(start);
    setMonthEnd(end);
  }}
/>`;

const LOCALE_OPTIONS: { label: string; value: CalendarLocale }[] = [
  { label: 'EN', value: 'en' },
  { label: 'KM', value: 'km' },
  { label: 'VI', value: 'vi' },
  { label: 'KO', value: 'ko' },
  { label: 'ZH', value: 'zh' },
];

export const PeriodPickerDetailSection: React.FC = () => {
  const [locale, setLocale] = useState<CalendarLocale>('en');

  // Single values
  const [singleMonth, setSingleMonth] = useState<PeriodValue>({ year: 2026, period: 10 });
  const [singleQuarter, setSingleQuarter] = useState<PeriodValue>({ year: 2026, period: 3 });
  const [singleSemester, setSingleSemester] = useState<PeriodValue>({ year: 2026, period: 1 });
  const [singleYear, setSingleYear] = useState<PeriodValue>({ year: 2026 });

  // Range values
  const [monthStart, setMonthStart] = useState<PeriodValue>({ year: 2026, period: 1 });
  const [monthEnd, setMonthEnd] = useState<PeriodValue>({ year: 2026, period: 6 });

  const [quarterStart, setQuarterStart] = useState<PeriodValue>({ year: 2026, period: 1 });
  const [quarterEnd, setQuarterEnd] = useState<PeriodValue>({ year: 2026, period: 3 });

  const [semesterStart, setSemesterStart] = useState<PeriodValue>({ year: 2026, period: 1 });
  const [semesterEnd, setSemesterEnd] = useState<PeriodValue>({ year: 2026, period: 2 });

  const [yearStart, setYearStart] = useState<PeriodValue>({ year: 2024 });
  const [yearEnd, setYearEnd] = useState<PeriodValue>({ year: 2026 });

  return (
    <View testID="detail-period-picker">
      <CodeBlock title="PeriodPickerField Usage" code={PERIOD_PICKER_SNIPPET} />

      <AppCard style={styles.card}>
        <Text style={styles.sectionTitle}>Language Preview</Text>
        <SegmentedControl
          items={LOCALE_OPTIONS}
          selectedValue={locale}
          onSelect={(val) => setLocale(val as CalendarLocale)}
          testID="period-picker-locale-switch"
        />
      </AppCard>

      <AppCard style={styles.card}>
        <Text style={styles.sectionTitle}>Single Selection</Text>
        <PeriodPickerField
          label="Month"
          granularity="month"
          selectionMode="single"
          locale={locale}
          value={singleMonth}
          onChange={(val) => setSingleMonth(val)}
          testID="demo-single-month"
        />
        <PeriodPickerField
          label="Quarter"
          granularity="quarter"
          selectionMode="single"
          locale={locale}
          value={singleQuarter}
          onChange={(val) => setSingleQuarter(val)}
          testID="demo-single-quarter"
        />
        <PeriodPickerField
          label="Semester"
          granularity="semester"
          selectionMode="single"
          locale={locale}
          value={singleSemester}
          onChange={(val) => setSingleSemester(val)}
          testID="demo-single-semester"
        />
        <PeriodPickerField
          label="Year"
          granularity="year"
          selectionMode="single"
          locale={locale}
          value={singleYear}
          onChange={(val) => setSingleYear(val)}
          testID="demo-single-year"
        />
      </AppCard>

      <AppCard style={styles.card}>
        <Text style={styles.sectionTitle}>Range Selection (From ~ To)</Text>
        <PeriodPickerField
          label="Month Range"
          granularity="month"
          selectionMode="range"
          locale={locale}
          startValue={monthStart}
          endValue={monthEnd}
          onChangeRange={(s, e) => {
            setMonthStart(s);
            setMonthEnd(e);
          }}
          testID="demo-range-month"
        />
        <PeriodPickerField
          label="Quarter Range"
          granularity="quarter"
          selectionMode="range"
          locale={locale}
          startValue={quarterStart}
          endValue={quarterEnd}
          onChangeRange={(s, e) => {
            setQuarterStart(s);
            setQuarterEnd(e);
          }}
          testID="demo-range-quarter"
        />
        <PeriodPickerField
          label="Semester Range"
          granularity="semester"
          selectionMode="range"
          locale={locale}
          startValue={semesterStart}
          endValue={semesterEnd}
          onChangeRange={(s, e) => {
            setSemesterStart(s);
            setSemesterEnd(e);
          }}
          testID="demo-range-semester"
        />
        <PeriodPickerField
          label="Year Range"
          granularity="year"
          selectionMode="range"
          locale={locale}
          startValue={yearStart}
          endValue={yearEnd}
          onChangeRange={(s, e) => {
            setYearStart(s);
            setYearEnd(e);
          }}
          testID="demo-range-year"
        />
      </AppCard>
    </View>
  );
};

const styles = StyleSheet.create({
  card: {
    marginBottom: 16,
  },
  sectionTitle: {
    fontSize: 15,
    fontWeight: '700',
    color: '#111827',
    marginBottom: 10,
  },
});
