import React, { useState, useEffect, useCallback } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  TextInput,
  StatusBar,
  KeyboardAvoidingView,
  Platform,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import Svg, { Path, Circle, Rect } from 'react-native-svg';
import { ScreenHeader } from '@mfe/ui-components/components/header/ScreenHeader';
import { PullToRefreshScrollView } from '@mfe/ui-components/components/scroll/PullToRefreshScrollView';
import { useBackNavigation } from '@mfe/ui-components/hooks/useBackNavigation';
import { ApprovalItemDTO } from '../models/ApprovalModel';
import { IApprovalService, ApprovalService } from '../services/ApprovalService';

export interface ApprovalDetailScreenProps {
  approvalId: string;
  onBack: () => void;
  approvalService?: IApprovalService;
  useMock?: boolean;
}

export const ApprovalDetailScreen: React.FC<ApprovalDetailScreenProps> = ({
  approvalId,
  onBack,
  approvalService = ApprovalService.getInstance(),
  useMock = true,
}) => {
  const [item, setItem] = useState<ApprovalItemDTO | null>(null);
  const [refreshing, setRefreshing] = useState(false);
  const [activeSubTab, setActiveSubTab] = useState<'info' | 'line'>('info');
  const [isFilterOpen, setIsFilterOpen] = useState(true);
  const [isAppInfoOpen, setIsAppInfoOpen] = useState(true);
  const [remarkInput, setRemarkInput] = useState('');
  const [expandedStepId, setExpandedStepId] = useState<string | null>('step-1');

  // Swipe back & hardware back navigation hook
  const { panHandlers } = useBackNavigation({
    onBack,
    enabled: true,
  });

  const loadDetail = useCallback(async () => {
    const data = await approvalService.getApprovalDetail(approvalId, useMock);
    if (data) {
      setItem(data);
    }
  }, [approvalId, approvalService, useMock]);

  useEffect(() => {
    loadDetail();
  }, [loadDetail]);

  const handleRefresh = useCallback(async () => {
    setRefreshing(true);
    try {
      await loadDetail();
    } finally {
      setRefreshing(false);
    }
  }, [loadDetail]);

  const handleCancelModify = async (stepId: string) => {
    if (!item) return;
    const success = await approvalService.cancelModify(item.id, stepId, remarkInput, useMock);
    if (success) {
      await loadDetail();
    }
  };

  return (
    <SafeAreaView
      testID="approval-detail-screen"
      style={styles.safeArea}
      edges={['top', 'left', 'right', 'bottom']}
      {...panHandlers}
    >
      <StatusBar barStyle="dark-content" backgroundColor="#FFFFFF" />

      {/* ScreenHeader component with onBack trigger */}
      <ScreenHeader
        title="Loan New Application Approval"
        onBack={onBack}
        testID="approval-detail-header"
      />

      <KeyboardAvoidingView
        style={{ flex: 1 }}
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
      >
        <PullToRefreshScrollView
          refreshing={refreshing}
          onRefresh={handleRefresh}
          refreshTitle="Updating approval data..."
          contentContainerStyle={styles.scrollContent}
          testID="approval-detail-pull-to-refresh"
        >
          {/* Filter Section Accordion */}
          <View style={styles.accordionSection}>
            <TouchableOpacity
              style={styles.accordionHeader}
              activeOpacity={0.7}
              onPress={() => setIsFilterOpen(!isFilterOpen)}
            >
              <Text style={styles.accordionTitle}>Filter</Text>
              <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                <Path
                  d={isFilterOpen ? 'M18 15L12 9L6 15' : 'M6 9L12 15L18 9'}
                  stroke="#1E293B"
                  strokeWidth={2.2}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </Svg>
            </TouchableOpacity>

            {isFilterOpen && (
              <View style={styles.filterBody}>
                <Text style={styles.inputLabel}>Application No</Text>
                <View style={styles.inputRow}>
                  <View style={styles.inputField}>
                    <Text style={styles.inputText}>
                      {item ? item.applicationNo : approvalId}
                    </Text>
                    <TouchableOpacity activeOpacity={0.7}>
                      <Svg width={18} height={18} viewBox="0 0 24 24" fill="none">
                        <Circle cx="12" cy="12" r="10" fill="#64748B" />
                        <Path d="M15 9L9 15M9 9L15 15" stroke="#FFFFFF" strokeWidth={2} strokeLinecap="round" />
                      </Svg>
                    </TouchableOpacity>
                  </View>
                  <TouchableOpacity style={styles.searchIconBtn} activeOpacity={0.8}>
                    <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                      <Path
                        d="M21 21L16.65 16.65M19 11C19 15.4183 15.4183 19 11 19C6.58172 19 3 15.4183 3 11C3 6.58172 6.58172 3 11 3C15.4183 3 19 6.58172 19 11Z"
                        stroke="#FFFFFF"
                        strokeWidth={2.4}
                        strokeLinecap="round"
                      />
                    </Svg>
                  </TouchableOpacity>
                </View>

                <Text style={[styles.inputLabel, { marginTop: 14 }]}>Loan Account No</Text>
                <View style={styles.inputRow}>
                  <View style={styles.inputField}>
                    <Text style={styles.placeholderText}>
                      {item?.loanAccountNo || 'Enter account number'}
                    </Text>
                  </View>
                  <TouchableOpacity style={styles.searchIconBtn} activeOpacity={0.8}>
                    <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                      <Path
                        d="M21 21L16.65 16.65M19 11C19 15.4183 15.4183 19 11 19C6.58172 19 3 15.4183 3 11C3 6.58172 6.58172 3 11 3C15.4183 3 19 6.58172 19 11Z"
                        stroke="#FFFFFF"
                        strokeWidth={2.4}
                        strokeLinecap="round"
                      />
                    </Svg>
                  </TouchableOpacity>
                </View>
              </View>
            )}
          </View>

          {/* SubTab Switcher: Application Info vs Approval Line */}
          <View style={styles.tabSwitcher}>
            <TouchableOpacity
              testID="tab-application-info"
              style={[styles.subTabBtn, activeSubTab === 'info' && styles.subTabBtnActive]}
              activeOpacity={0.8}
              onPress={() => setActiveSubTab('info')}
            >
              <Text
                style={[
                  styles.subTabText,
                  activeSubTab === 'info' && styles.subTabTextActive,
                ]}
              >
                Application Info
              </Text>
            </TouchableOpacity>
            <TouchableOpacity
              testID="tab-approval-line"
              style={[styles.subTabBtn, activeSubTab === 'line' && styles.subTabBtnActive]}
              activeOpacity={0.8}
              onPress={() => setActiveSubTab('line')}
            >
              <Text
                style={[
                  styles.subTabText,
                  activeSubTab === 'line' && styles.subTabTextActive,
                ]}
              >
                Approval Line
              </Text>
            </TouchableOpacity>
          </View>

          {/* Application Info Content */}
          {activeSubTab === 'info' && item && (
            <View testID="detail-info-content">
              {/* Customer Summary Card */}
              <View style={styles.customerCard}>
                <View style={styles.customerHeader}>
                  <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                    <Rect x="2" y="4" width="20" height="16" rx="2" stroke="#1E293B" strokeWidth={2} />
                    <Path d="M6 8H10M6 12H10M14 8H18M14 12H18M6 16H18" stroke="#1E293B" strokeWidth={1.8} strokeLinecap="round" />
                  </Svg>
                  <Text style={styles.customerNoText}>{item.customerNo}</Text>
                </View>
                <View style={styles.rowItem}>
                  <Text style={styles.rowLabel}>Customer Name</Text>
                  <Text style={styles.rowValueBold}>{item.customerName}</Text>
                </View>
              </View>

              {/* Application Information Details Card */}
              <View style={styles.accordionSection}>
                <TouchableOpacity
                  style={styles.accordionHeader}
                  activeOpacity={0.7}
                  onPress={() => setIsAppInfoOpen(!isAppInfoOpen)}
                >
                  <Text style={styles.accordionTitle}>Application Information</Text>
                  <Svg width={20} height={20} viewBox="0 0 24 24" fill="none">
                    <Path
                      d={isAppInfoOpen ? 'M18 15L12 9L6 15' : 'M6 9L12 15L18 9'}
                      stroke="#1E293B"
                      strokeWidth={2.2}
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </Svg>
                </TouchableOpacity>

                {isAppInfoOpen && (
                  <View style={styles.infoCard}>
                    <View style={styles.infoRow}>
                      <Text style={styles.infoLabel}>Application No</Text>
                      <Text style={styles.infoValueBold}>{item.applicationNo}</Text>
                    </View>
                    <View style={styles.infoRow}>
                      <Text style={styles.infoLabel}>Application Type</Text>
                      <Text style={styles.infoValueBold}>{item.applicationType || 'New Application'}</Text>
                    </View>
                    <View style={styles.infoRow}>
                      <Text style={styles.infoLabel}>Application Progress Status</Text>
                      <Text style={styles.infoValueBold}>{item.applicationProgressStatus || 'Branch Approval Request'}</Text>
                    </View>
                    <View style={styles.infoRow}>
                      <Text style={styles.infoLabel}>Application Kind</Text>
                      <Text style={styles.infoValueBold}>{item.applicationKind || 'Full Disbursement'}</Text>
                    </View>
                    <View style={styles.infoRow}>
                      <Text style={styles.infoLabel}>Loan Category Type</Text>
                      <Text style={styles.infoValueBold}>{item.loanCategoryType || '-'}</Text>
                    </View>
                    <View style={styles.infoRow}>
                      <Text style={styles.infoLabel}>Loan Product</Text>
                      <Text style={styles.infoValueBold}>{item.loanProduct || 'Car Loan'}</Text>
                    </View>
                    <View style={styles.infoRow}>
                      <Text style={styles.infoLabel}>Fund Source</Text>
                      <Text style={styles.infoValueBold}>{item.fundSource || 'FUND.CODE.DEFAULT'}</Text>
                    </View>
                    <View style={styles.infoRow}>
                      <Text style={styles.infoLabel}>Currency Code</Text>
                      <Text style={styles.infoValueBold}>{item.currencyCode || 'KHR'}</Text>
                    </View>
                  </View>
                )}
              </View>
            </View>
          )}

          {/* Approval Line Timeline Content */}
          {activeSubTab === 'line' && item && (
            <View testID="detail-line-content" style={styles.timelineContainer}>
              {item.approvalLine?.map((step, index) => {
                const isLast = index === (item.approvalLine?.length || 0) - 1;
                const isExpanded = expandedStepId === step.id;

                return (
                  <View key={step.id} style={styles.timelineItem}>
                    {/* Timeline Node & Line */}
                    <View style={styles.timelineColumn}>
                      <View
                        style={[
                          styles.timelineCircle,
                          step.status === 'Requested'
                            ? styles.circleActive
                            : styles.circleWaiting,
                        ]}
                      />
                      {!isLast && <View style={styles.timelineVerticalLine} />}
                    </View>

                    {/* Step Content */}
                    <View style={styles.stepContent}>
                      <Text style={styles.stepDateText}>{step.dateStr}</Text>

                      <View style={styles.stepCard}>
                        <TouchableOpacity
                          style={styles.stepCardHeader}
                          activeOpacity={0.7}
                          onPress={() =>
                            setExpandedStepId(isExpanded ? null : step.id)
                          }
                        >
                          <Text style={styles.stepNameText}>{step.name}</Text>
                          <View style={styles.headerRightGroup}>
                            <View
                              style={[
                                styles.badgePill,
                                step.status === 'Requested'
                                  ? styles.badgeRequested
                                  : styles.badgeWaiting,
                              ]}
                            >
                              <Text style={styles.badgePillText}>{step.status}</Text>
                            </View>
                            <Svg width={18} height={18} viewBox="0 0 24 24" fill="none">
                              <Path
                                d={isExpanded ? 'M18 15L12 9L6 15' : 'M6 9L12 15L18 9'}
                                stroke="#64748B"
                                strokeWidth={2}
                                strokeLinecap="round"
                              />
                            </Svg>
                          </View>
                        </TouchableOpacity>

                        {isExpanded && (
                          <View style={styles.stepCardBody}>
                            <View style={styles.positionRow}>
                              <Text style={styles.positionLabel}>Position</Text>
                              <Text style={styles.positionValue}>{step.position}</Text>
                            </View>

                            <Text style={styles.remarkLabel}>Remark</Text>
                            <TextInput
                              style={styles.remarkInput}
                              placeholder="Enter Remark"
                              placeholderTextColor="#94A3B8"
                              value={remarkInput || step.remark || ''}
                              onChangeText={setRemarkInput}
                              multiline
                            />

                            {step.canCancelModify && (
                              <TouchableOpacity
                                testID="btn-cancel-to-modify"
                                style={styles.cancelModifyBtn}
                                activeOpacity={0.8}
                                onPress={() => handleCancelModify(step.id)}
                              >
                                <Text style={styles.cancelModifyBtnText}>
                                  Cancel to Modify
                                </Text>
                              </TouchableOpacity>
                            )}
                          </View>
                        )}
                      </View>
                    </View>
                  </View>
                );
              })}
            </View>
          )}

          <View style={{ height: 40 }} />
        </PullToRefreshScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
};

