import React from 'react';
import {
  View,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
} from 'react-native';
import { AppBadge, AppBadgeProps } from './AppBadge';

export type BadgePosition = 'top-right' | 'top-left' | 'bottom-right' | 'bottom-left';

export interface IconWithBadgeProps {
  /**
   * The icon, button, or any interactive component to attach the badge to.
   */
  children?: React.ReactNode;

  /**
   * Direct icon element or render function if children is not used.
   */
  icon?: React.ReactNode;

  /**
   * Badge content (string or number). E.g. count `5`, `'NEW'`, `'HOT'`.
   * If undefined/null, badge will not show unless `showZero` or `dot` is true.
   */
  badgeCount?: number | string;

  /**
   * If true, shows a badge even when badgeCount is 0.
   * Default: false
   */
  showZero?: boolean;

  /**
   * If true, renders a small dot badge indicator instead of text/count.
   * Default: false
   */
  dot?: boolean;

  /**
   * Maximum count before formatting with `+` (e.g. 99 renders `99+`).
   * Default: 99
   */
  maxCount?: number;

  /**
   * Color theme variant of badge.
   * Default: 'primary'
   */
  badgeVariant?: AppBadgeProps['variant'];

  /**
   * Size of badge.
   * Default: 'md'
   */
  badgeSize?: AppBadgeProps['size'];

  /**
   * Position anchor of the badge relative to the icon.
   * Default: 'top-right'
   */
  position?: BadgePosition;

  /**
   * Additional badge offset [x, y] in pixels.
   * Useful for fine-tuning positioning over circular icons or buttons.
   */
  offset?: [number, number];

  /**
   * Optional click handler for the whole icon container.
   */
  onPress?: () => void;

  /**
   * Container style overrides.
   */
  style?: ViewStyle;

  /**
   * Badge style overrides.
   */
  badgeStyle?: ViewStyle;

  /**
   * Accessible test ID.
   */
  testID?: string;
}

export const IconWithBadge: React.FC<IconWithBadgeProps> = ({
  children,
  icon,
  badgeCount,
  showZero = false,
  dot = false,
  maxCount = 99,
  badgeVariant = 'primary',
  badgeSize = 'md',
  position = 'top-right',
  offset = [0, 0],
  onPress,
  style,
  badgeStyle,
  testID = 'icon-with-badge',
}) => {
  // Determine if badge should be shown
  const isNumeric = typeof badgeCount === 'number';
  const shouldRenderBadge =
    dot ||
    (badgeCount !== undefined && badgeCount !== null && (isNumeric ? badgeCount > 0 || showZero : badgeCount !== ''));

  // Calculate position coordinate offsets
  const getPositionStyle = (): ViewStyle => {
    const [offsetX, offsetY] = offset;
    switch (position) {
      case 'top-left':
        return {
          position: 'absolute',
          top: -4 + offsetY,
          left: -4 + offsetX,
        };
      case 'bottom-right':
        return {
          position: 'absolute',
          bottom: -4 + offsetY,
          right: -4 + offsetX,
        };
      case 'bottom-left':
        return {
          position: 'absolute',
          bottom: -4 + offsetY,
          left: -4 + offsetX,
        };
      case 'top-right':
      default:
        return {
          position: 'absolute',
          top: -4 + offsetY,
          right: -4 + offsetX,
        };
    }
  };

  const targetContent = children || icon;

  const content = (
    <View style={[styles.wrapper, style]} testID={testID}>
      {targetContent}
      {shouldRenderBadge ? (
        <View style={[getPositionStyle(), styles.badgeContainer, badgeStyle]} pointerEvents="none">
          <AppBadge
            content={badgeCount}
            dot={dot}
            maxCount={maxCount}
            variant={badgeVariant}
            size={badgeSize}
            testID={`${testID}-badge`}
          />
        </View>
      ) : null}
    </View>
  );

  if (onPress) {
    return (
      <TouchableOpacity
        testID={`${testID}-touchable`}
        onPress={onPress}
        activeOpacity={0.7}
        hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
      >
        {content}
      </TouchableOpacity>
    );
  }

  return content;
};

const styles = StyleSheet.create({
  wrapper: {
    position: 'relative',
    alignSelf: 'flex-start',
    justifyContent: 'center',
    alignItems: 'center',
  },
  badgeContainer: {
    zIndex: 10,
    elevation: 4,
  },
});
