import React, { useState } from 'react';
import { View, Text, StyleSheet } from 'react-native';
import { AppCard, AppButton, StatusBadge } from '@mfe/ui-components/components';
import { CodeBlock } from '../../components/CodeBlock';
import { useTheme } from '@mfe/core/theme';

export const ThemeCustomizationDetailSection: React.FC = () => {
  const { theme, updateTheme, resetTheme } = useTheme();
  const [activeBrand, setActiveBrand] = useState<'LOTTE' | 'DBCS_BLUE' | 'EMERALD'>('LOTTE');

  const applyLotteRed = () => {
    setActiveBrand('LOTTE');
    updateTheme({
      colors: {
        primary: '#E7252B',
        primaryLight: '#FDECEB',
        secondary: '#1F5FA8',
      },
      radius: { md: 8, lg: 12 },
    });
  };

  const applyDbcsBlue = () => {
    setActiveBrand('DBCS_BLUE');
    updateTheme({
      colors: {
        primary: '#004880',
        primaryLight: '#E6F0FA',
        secondary: '#0070BA',
      },
      radius: { md: 4, lg: 6 },
    });
  };

  const applyEmerald = () => {
    setActiveBrand('EMERALD');
    updateTheme({
      colors: {
        primary: '#059669',
        primaryLight: '#ECFDF5',
        secondary: '#047857',
      },
      radius: { md: 16, lg: 20 },
    });
  };

  const themeCodeSnippet = `import { ThemeProvider, useTheme } from '@/core/theme';

// 1. Wrap App root in ThemeProvider
<ThemeProvider initialTheme={defaultTheme}>
  <App />
</ThemeProvider>

// 2. Access or dynamically update theme in any screen or component
const { theme, updateTheme } = useTheme();

// Override colors, radius, or spacing globally:
updateTheme({
  colors: {
    primary: '#004880', // Switch brand color across all buttons & badges
  },
  radius: {
    md: 12, // Update corner radius for all inputs, buttons & cards
  },
});`;

  return (
    <View testID="detail-theme-customization">
      <CodeBlock code={themeCodeSnippet} title="Global Theme Provider Usage" />

      <AppCard>
        <Text style={styles.detailHeader}>Dynamic Global Theme Switcher</Text>
        <Text style={styles.helperText}>
          Switch brand themes or modify radius/colors below. All buttons, badges,
          cards, and inputs will automatically adapt in real-time across the app!
        </Text>

        <View style={styles.buttonStack}>
          <AppButton
            title="Brand: LOTTE Red (Default)"
            variant={activeBrand === 'LOTTE' ? 'primary' : 'outline'}
            onPress={applyLotteRed}
            testID="theme-lotte-btn"
          />
          <AppButton
            title="Brand: DBCS Banking Blue (Sharp Radius)"
            variant={activeBrand === 'DBCS_BLUE' ? 'primary' : 'outline'}
            onPress={applyDbcsBlue}
            testID="theme-dbcs-btn"
          />
          <AppButton
            title="Brand: Emerald Green (Rounded Soft Radius)"
            variant={activeBrand === 'EMERALD' ? 'primary' : 'outline'}
            onPress={applyEmerald}
            testID="theme-emerald-btn"
          />
          <AppButton
            title="Reset to Factory Defaults"
            variant="text"
            onPress={resetTheme}
          />
        </View>

        <View style={styles.tokenBox}>
          <Text style={styles.tokenTitle}>Active Global Tokens:</Text>
          <Text style={styles.tokenItem}>
            • Primary Color:{' '}
            <Text style={{ fontWeight: '700', color: theme.colors.primary }}>
              {theme.colors.primary}
            </Text>
          </Text>
          <Text style={styles.tokenItem}>
            • Card Radius: <Text style={styles.boldText}>{theme.radius.lg}px</Text>
          </Text>
          <Text style={styles.tokenItem}>
            • Button Radius: <Text style={styles.boldText}>{theme.radius.md}px</Text>
          </Text>
          <Text style={styles.tokenItem}>
            • Default Spacing: <Text style={styles.boldText}>{theme.spacing.lg}px</Text>
          </Text>
        </View>

        <Text style={[styles.detailHeader, { marginTop: 16 }]}>
          Live Theme Preview Samples
        </Text>
        <View style={styles.previewRow}>
          <AppButton title="Primary" variant="primary" size="small" onPress={() => {}} />
          <AppButton title="Secondary" variant="secondary" size="small" onPress={() => {}} />
          <AppButton title="Outline" variant="outline" size="small" onPress={() => {}} />
          <StatusBadge label="Dynamic Badge" variant="success" />
        </View>
      </AppCard>
    </View>
  );
};

const styles = StyleSheet.create({
  detailHeader: {
    fontSize: 16,
    fontWeight: '700',
    color: '#16181D',
    marginBottom: 8,
  },
  helperText: {
    fontSize: 13,
    color: '#7B8494',
    marginBottom: 12,
    lineHeight: 18,
  },
  buttonStack: {
    gap: 8,
    marginBottom: 16,
  },
  tokenBox: {
    backgroundColor: '#F4F5F7',
    padding: 12,
    borderRadius: 8,
  },
  tokenTitle: {
    fontSize: 13,
    fontWeight: '700',
    color: '#16181D',
    marginBottom: 6,
  },
  tokenItem: {
    fontSize: 13,
    color: '#4D5563',
    marginVertical: 2,
  },
  boldText: {
    fontWeight: '700',
    color: '#16181D',
  },
  previewRow: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 8,
    alignItems: 'center',
    marginTop: 8,
  },
});

