import {
  openDatabase,
  closeDatabase,
  beginTransaction,
  commitTransaction,
  rollbackTransaction,
  executeSql,
  executeBatchSql,
  executeSelect,
  type SQLiteOpenRequest,
  type SQLiteQueryRequest,
  type SQLiteBatchQueryRequest,
  type SQLiteResponse,
} from 'react-native-bizmob-plugin';
import { appLogger } from '../logger/AppLogger';

export interface SQLitePluginAdapter {
  openDatabase: typeof openDatabase;
  closeDatabase: typeof closeDatabase;
  beginTransaction: typeof beginTransaction;
  commitTransaction: typeof commitTransaction;
  rollbackTransaction: typeof rollbackTransaction;
  executeSql: typeof executeSql;
  executeBatchSql: typeof executeBatchSql;
  executeSelect: typeof executeSelect;
}

const defaultSQLiteAdapter: SQLitePluginAdapter = {
  openDatabase,
  closeDatabase,
  beginTransaction,
  commitTransaction,
  rollbackTransaction,
  executeSql,
  executeBatchSql,
  executeSelect,
};

export interface OfflineDatabaseConfig {
  dbName: string;
  encrypt?: boolean;
  cipherKey?: string;
}

export interface OfflineRecord {
  key: string;
  category: string;
  data: any;
  updatedAt: number;
  syncStatus?: 'SYNCED' | 'PENDING' | 'FAILED';
}

export interface IOfflineDataService {
  init(config?: Partial<OfflineDatabaseConfig>): Promise<boolean>;
  close(): Promise<boolean>;
  execute<T = any>(sql: string, params?: any[]): Promise<SQLiteResponse<T>>;
  select<T = any>(sql: string, params?: any[]): Promise<T[]>;
  saveData(category: string, key: string, data: any, syncStatus?: 'SYNCED' | 'PENDING' | 'FAILED'): Promise<boolean>;
  getData<T = any>(category: string, key: string): Promise<T | null>;
  getDataByCategory<T = any>(category: string): Promise<Array<{ key: string; data: T; updatedAt: number; syncStatus?: string }>>;
  deleteData(category: string, key: string): Promise<boolean>;
  deleteCategory(category: string): Promise<boolean>;
  clearAllData(): Promise<boolean>;
  getPendingSyncRecords(): Promise<OfflineRecord[]>;
  markRecordSynced(category: string, key: string): Promise<boolean>;
  runInTransaction<T = any>(work: () => Promise<T>): Promise<T>;
}

/**
 * Universal Offline Storage Service for LOS Application
 *
 * Backed by `react-native-bizmob-plugin` SQLite native module with:
 * - Transparent AES-CBC column/parameter encryption
 * - Key-Value & Category based offline document storage (FAQs, Notifications, News, Drafts)
 * - Raw SQL and parameterized query execution
 * - ACID Transactions (`beginTransaction`, `commitTransaction`, `rollbackTransaction`)
 * - In-memory fallback if native SQLite is unavailable or during headless unit testing
 */
export class OfflineDataService implements IOfflineDataService {
  private static instance: OfflineDataService;
  private config: OfflineDatabaseConfig = {
    dbName: 'los_offline_data.db',
    encrypt: true,
  };
  private isInitialized = false;
  private initPromise: Promise<boolean> | null = null;
  private adapter: SQLitePluginAdapter;

  // In-memory fallback map for environments where native SQLite is unavailable (e.g. Node tests / Web)
  private memoryStore: Map<string, OfflineRecord> = new Map();

  constructor(
    config?: Partial<OfflineDatabaseConfig>,
    adapter: SQLitePluginAdapter = defaultSQLiteAdapter
  ) {
    if (config) {
      this.config = { ...this.config, ...config };
    }
    this.adapter = adapter;
  }

  public static getInstance(config?: Partial<OfflineDatabaseConfig>): OfflineDataService {
    if (!OfflineDataService.instance) {
      OfflineDataService.instance = new OfflineDataService(config);
    }
    return OfflineDataService.instance;
  }

  /**
   * Initializes database connection and ensures core offline key-value table schema.
   */
  public async init(customConfig?: Partial<OfflineDatabaseConfig>): Promise<boolean> {
    if (this.isInitialized) return true;
    if (this.initPromise) return this.initPromise;

    if (customConfig) {
      this.config = { ...this.config, ...customConfig };
    }

    this.initPromise = (async () => {
      try {
        appLogger.d('OfflineDataService', `📂 Opening SQLite database: ${this.config.dbName}`);
        const openRes = await this.adapter.openDatabase({
          db_name: this.config.dbName,
          encrypt: this.config.encrypt,
          key: this.config.cipherKey,
        });

        if (!openRes || openRes?.header?.result === false) {
          appLogger.w('OfflineDataService', '⚠️ Failed to open native SQLite database. Using in-memory fallback.');
        }

        // Create unified generic offline key-value table
        await this.adapter.executeSql({
          query: `CREATE TABLE IF NOT EXISTS los_offline_store (
            category TEXT NOT NULL,
            key TEXT NOT NULL,
            payload TEXT NOT NULL,
            updated_at INTEGER NOT NULL,
            sync_status TEXT DEFAULT 'SYNCED',
            PRIMARY KEY (category, key)
          )`,
          encrypt: this.config.encrypt,
          key: this.config.cipherKey,
        });

        // Index for rapid category and syncStatus lookups
        await this.adapter.executeSql({
          query: `CREATE INDEX IF NOT EXISTS idx_offline_category_sync 
                  ON los_offline_store (category, sync_status)`,
          encrypt: false,
        });

        this.isInitialized = true;
        appLogger.i('OfflineDataService', `✅ SQLite Database [${this.config.dbName}] initialized successfully.`);
        return true;
      } catch (err: any) {
        appLogger.w('OfflineDataService', '⚠️ Native SQLite initialization encountered an error:', err);
        // Fallback to in-memory mode
        this.isInitialized = true;
        return true;
      } finally {
        this.initPromise = null;
      }
    })();

    return this.initPromise;
  }

  public async close(): Promise<boolean> {
    try {
      const res = await this.adapter.closeDatabase();
      this.isInitialized = false;
      return res?.header?.result ?? true;
    } catch {
      this.isInitialized = false;
      return true;
    }
  }

  /**
   * Executes arbitrary SQL statements (CREATE, INSERT, UPDATE, DELETE).
   */
  public async execute<T = any>(sql: string, params: any[] = []): Promise<SQLiteResponse<T>> {
    await this.init();
    try {
      return await this.adapter.executeSql({
        query: sql,
        bind_array: params,
        encrypt: this.config.encrypt,
        key: this.config.cipherKey,
      });
    } catch (err: any) {
      appLogger.e('OfflineDataService', `❌ SQL execute failed for query: ${sql}`, err);
      throw err;
    }
  }

  /**
   * Executes a SELECT query and returns typed row results.
   */
  public async select<T = any>(sql: string, params: any[] = []): Promise<T[]> {
    await this.init();
    try {
      const res = await this.adapter.executeSelect<T>({
        query: sql,
        bind_array: params.length > 0 ? params : undefined,
        encrypt: this.config.encrypt,
        key: this.config.cipherKey,
      });

      if (res?.body?.rows && Array.isArray(res.body.rows)) {
        return res.body.rows;
      }
      if (res?.body?.data?.result_set?.rows && Array.isArray(res.body.data.result_set.rows)) {
        return res.body.data.result_set.rows;
      }
      return [];
    } catch (err: any) {
      appLogger.w('OfflineDataService', `⚠️ SQL select fallback for query: ${sql}`, err);
      return [];
    }
  }

  /**
   * Saves or updates an offline object identified by category and key.
   * Serializes payload to JSON with automatic AES-CBC encryption.
   */
  public async saveData(
    category: string,
    key: string,
    data: any,
    syncStatus: 'SYNCED' | 'PENDING' | 'FAILED' = 'SYNCED'
  ): Promise<boolean> {
    await this.init();
    const payloadStr = JSON.stringify(data);
    const now = Date.now();
    const storeKey = `${category}:${key}`;

    // Update in-memory fallback
    this.memoryStore.set(storeKey, {
      category,
      key,
      data,
      updatedAt: now,
      syncStatus,
    });

    try {
      const res = await this.adapter.executeSql({
        query: `INSERT OR REPLACE INTO los_offline_store (category, key, payload, updated_at, sync_status)
                VALUES (?, ?, ?, ?, ?)`,
        bind_array: [category, key, payloadStr, now, syncStatus],
        encrypt: this.config.encrypt,
        key: this.config.cipherKey,
      });

      return res?.header?.result ?? true;
    } catch (err: any) {
      appLogger.w('OfflineDataService', `⚠️ Native SQLite insert failed for [${storeKey}], maintained in memory store`, err);
      return true;
    }
  }

  /**
   * Retrieves an offline object by category and key.
   */
  public async getData<T = any>(category: string, key: string): Promise<T | null> {
    await this.init();
    const storeKey = `${category}:${key}`;

    try {
      const rows = await this.select<{ payload: string; updated_at: number; sync_status: string }>(
        'SELECT payload FROM los_offline_store WHERE category = ? AND key = ? LIMIT 1',
        [category, key]
      );

      if (rows && rows.length > 0 && rows[0]?.payload) {
        return JSON.parse(rows[0].payload) as T;
      }
    } catch (err) {
      // Fallback
    }

    const mem = this.memoryStore.get(storeKey);
    return mem ? (mem.data as T) : null;
  }

  /**
   * Retrieves all items belonging to a category (e.g. all cached FAQs or drafts).
   */
  public async getDataByCategory<T = any>(
    category: string
  ): Promise<Array<{ key: string; data: T; updatedAt: number; syncStatus?: string }>> {
    await this.init();

    try {
      const rows = await this.select<{
        key: string;
        payload: string;
        updated_at: number;
        sync_status: string;
      }>(
        'SELECT key, payload, updated_at, sync_status FROM los_offline_store WHERE category = ? ORDER BY updated_at DESC',
        [category]
      );

      if (rows && rows.length > 0) {
        return rows.map((r) => ({
          key: r.key,
          data: JSON.parse(r.payload) as T,
          updatedAt: r.updated_at,
          syncStatus: r.sync_status,
        }));
      }
    } catch (err) {
      // Fallback
    }

    const results: Array<{ key: string; data: T; updatedAt: number; syncStatus?: string }> = [];
    for (const item of Array.from(this.memoryStore.values())) {
      if (item.category === category) {
        results.push({
          key: item.key,
          data: item.data as T,
          updatedAt: item.updatedAt,
          syncStatus: item.syncStatus,
        });
      }
    }
    return results;
  }

  /**
   * Deletes a specific offline record by category and key.
   */
  public async deleteData(category: string, key: string): Promise<boolean> {
    await this.init();
    const storeKey = `${category}:${key}`;
    this.memoryStore.delete(storeKey);

    try {
      const res = await this.adapter.executeSql({
        query: 'DELETE FROM los_offline_store WHERE category = ? AND key = ?',
        bind_array: [category, key],
        encrypt: this.config.encrypt,
        key: this.config.cipherKey,
      });
      return res?.header?.result ?? true;
    } catch {
      return true;
    }
  }

  /**
   * Deletes all records belonging to a category.
   */
  public async deleteCategory(category: string): Promise<boolean> {
    await this.init();
    for (const [k, v] of Array.from(this.memoryStore.entries())) {
      if (v.category === category) {
        this.memoryStore.delete(k);
      }
    }

    try {
      const res = await this.adapter.executeSql({
        query: 'DELETE FROM los_offline_store WHERE category = ?',
        bind_array: [category],
        encrypt: this.config.encrypt,
        key: this.config.cipherKey,
      });
      return res?.header?.result ?? true;
    } catch {
      return true;
    }
  }

  /**
   * Clears all offline records.
   */
  public async clearAllData(): Promise<boolean> {
    await this.init();
    this.memoryStore.clear();

    try {
      const res = await this.adapter.executeSql({
        query: 'DELETE FROM los_offline_store',
        bind_array: [],
        encrypt: false,
      });
      return res?.header?.result ?? true;
    } catch {
      return true;
    }
  }

  /**
   * Returns records marked as PENDING for two-way synchronization back to Core Banking / Cloud.
   */
  public async getPendingSyncRecords(): Promise<OfflineRecord[]> {
    await this.init();

    try {
      const rows = await this.select<{
        category: string;
        key: string;
        payload: string;
        updated_at: number;
        sync_status: string;
      }>(
        "SELECT category, key, payload, updated_at, sync_status FROM los_offline_store WHERE sync_status = 'PENDING'",
        []
      );

      if (rows && rows.length > 0) {
        return rows.map((r) => ({
          category: r.category,
          key: r.key,
          data: JSON.parse(r.payload),
          updatedAt: r.updated_at,
          syncStatus: 'PENDING',
        }));
      }
    } catch (err) {
      // Fallback
    }

    return Array.from(this.memoryStore.values()).filter((it) => it.syncStatus === 'PENDING');
  }

  /**
   * Updates sync status to SYNCED after successful cloud reconciliation.
   */
  public async markRecordSynced(category: string, key: string): Promise<boolean> {
    await this.init();
    const storeKey = `${category}:${key}`;
    const mem = this.memoryStore.get(storeKey);
    if (mem) {
      mem.syncStatus = 'SYNCED';
    }

    try {
      const res = await this.adapter.executeSql({
        query: "UPDATE los_offline_store SET sync_status = 'SYNCED' WHERE category = ? AND key = ?",
        bind_array: [category, key],
        encrypt: this.config.encrypt,
        key: this.config.cipherKey,
      });
      return res?.header?.result ?? true;
    } catch {
      return true;
    }
  }

  /**
   * Executes multiple queries within an ACID transaction block.
   * Automatically rolls back on error.
   */
  public async runInTransaction<T = any>(work: () => Promise<T>): Promise<T> {
    await this.init();
    try {
      await this.adapter.beginTransaction();
      const result = await work();
      await this.adapter.commitTransaction();
      return result;
    } catch (error) {
      appLogger.w('OfflineDataService', '⚠️ Transaction failed, performing rollback:', error);
      try {
        await this.adapter.rollbackTransaction();
      } catch (rbError) {
        appLogger.e('OfflineDataService', '❌ Rollback failed:', rbError);
      }
      throw error;
    }
  }
}

export const defaultOfflineDataService = OfflineDataService.getInstance();
