import React, { useRef, useState } from 'react';
import {
  View,
  Text,
  ScrollView,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
  ImageSourcePropType,
  Image,
  Dimensions,
  NativeSyntheticEvent,
  NativeScrollEvent,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { NetworkImage } from '../media/NetworkImage';

export interface HistoryMilestoneItem {
  id: string;
  yearMonth: string; // e.g. "Sep.2017" or "2024.11"
  dayDate?: string; // e.g. "Sep.28" or "Oct.15"
  title: string;
  description?: string;
  imageUrl?: string;
  imageSource?: ImageSourcePropType;
  onPress?: () => void;
}

export interface HistoryTimelineProps {
  title?: string;
  milestones: HistoryMilestoneItem[];
  activeMilestoneId?: string;
  onMilestoneSelect?: (milestone: HistoryMilestoneItem) => void;
  cardWidth?: number;
  containerStyle?: ViewStyle;
  testID?: string;
}

/**
 * Enterprise History Timeline Component matching Lotte Digital "Company history" screen.
 * Displays milestone milestone cards with day-date, title, photo thumbnail, and an interactive
 * horizontal axis with milestone year-month speech-bubble pills and central node indicators.
 */
export const HistoryTimeline: React.FC<HistoryTimelineProps> = ({
  title,
  milestones,
  activeMilestoneId,
  onMilestoneSelect,
  cardWidth = 240,
  containerStyle,
  testID = 'history-timeline',
}) => {
  const { theme } = useTheme();
  const primaryColor = theme.colors.primary || '#E7252B';

  const [activeIndex, setActiveIndex] = useState(() => {
    if (activeMilestoneId) {
      const found = milestones.findIndex((m) => m.id === activeMilestoneId);
      return found >= 0 ? found : 0;
    }
    return 0;
  });

  const scrollRef = useRef<ScrollView>(null);
  const cardSpacing = 16;
  const snapInterval = cardWidth + cardSpacing;

  const handleScrollEnd = (e: NativeSyntheticEvent<NativeScrollEvent>) => {
    const offsetX = e.nativeEvent.contentOffset.x;
    const index = Math.round(offsetX / snapInterval);
    if (index >= 0 && index < milestones.length && index !== activeIndex) {
      setActiveIndex(index);
      onMilestoneSelect?.(milestones[index]);
    }
  };

  const handleCardPress = (item: HistoryMilestoneItem, idx: number) => {
    setActiveIndex(idx);
    scrollRef.current?.scrollTo({ x: idx * snapInterval, animated: true });
    item.onPress?.();
    onMilestoneSelect?.(item);
  };

  const activeMilestone = milestones[activeIndex] || milestones[0];

  return (
    <View testID={testID} style={[styles.container, containerStyle]}>
      {/* Title Header with Red Accent Line */}
      {title ? (
        <View style={styles.titleSection}>
          <Text
            testID={`${testID}-main-title`}
            style={[styles.mainTitle, { color: theme.colors.text }]}
          >
            {title}
          </Text>
          <View style={[styles.redAccentLine, { backgroundColor: primaryColor }]} />
        </View>
      ) : null}

      {/* Horizontal Milestone Cards Carousel */}
      <ScrollView
        ref={scrollRef}
        horizontal
        showsHorizontalScrollIndicator={false}
        snapToInterval={snapInterval}
        decelerationRate="fast"
        contentContainerStyle={[styles.scrollContent, { gap: cardSpacing }]}
        onMomentumScrollEnd={handleScrollEnd}
        testID={`${testID}-cards-scroll`}
      >
        {milestones.map((item, idx) => {
          const isSelected = idx === activeIndex;

          return (
            <TouchableOpacity
              key={item.id}
              testID={`${testID}-card-${item.id}`}
              activeOpacity={0.88}
              onPress={() => handleCardPress(item, idx)}
              style={[
                styles.milestoneCard,
                { width: cardWidth },
                isSelected
                  ? [styles.selectedCard, { borderColor: theme.colors.border || '#E5E7EB' }]
                  : styles.unselectedCard,
              ]}
            >
              {/* Day Date Header */}
              {item.dayDate ? (
                <View style={styles.dayDateRow}>
                  <Text
                    style={[styles.dayDateText, { color: theme.colors.textMuted || '#4B5563' }]}
                    testID={`${testID}-day-${item.id}`}
                  >
                    {item.dayDate}
                  </Text>
                </View>
              ) : null}

              {/* Title Copy */}
              <Text
                numberOfLines={2}
                style={[styles.cardTitle, { color: theme.colors.text || '#111827' }]}
                testID={`${testID}-title-${item.id}`}
              >
                {item.title}
              </Text>

              {/* Description if present */}
              {item.description ? (
                <Text
                  numberOfLines={2}
                  style={[styles.cardDesc, { color: theme.colors.textSubtle || '#6B7280' }]}
                >
                  {item.description}
                </Text>
              ) : null}

              {/* Media Thumbnail */}
              <View style={styles.thumbnailWrapper}>
                {item.imageUrl ? (
                  <NetworkImage
                    uri={item.imageUrl}
                    style={styles.thumbnailImage}
                    resizeMode="cover"
                    borderRadius={8}
                    testID={`${testID}-img-${item.id}`}
                  />
                ) : item.imageSource ? (
                  <Image
                    source={item.imageSource}
                    style={styles.thumbnailImage}
                    resizeMode="cover"
                  />
                ) : (
                  <View style={styles.placeholderThumbnail}>
                    <Text style={styles.placeholderIcon}>📈</Text>
                  </View>
                )}
              </View>
            </TouchableOpacity>
          );
        })}
      </ScrollView>

      {/* Axis & Speech-Bubble Year/Month Pill */}
      {activeMilestone ? (
        <View style={styles.axisSection} testID={`${testID}-axis-section`}>
          {/* Active Date Speech Bubble */}
          <View style={styles.speechBubbleWrap}>
            <View
              style={[styles.speechBubblePill, { backgroundColor: primaryColor }]}
              testID={`${testID}-active-pill`}
            >
              <Text style={styles.speechBubbleText}>{activeMilestone.yearMonth}</Text>
            </View>
            {/* Small Downward Arrow Point */}
            <View style={[styles.speechBubbleArrow, { borderTopColor: primaryColor }]} />
          </View>

          {/* Central Connecting Node & Track Line */}
          <View style={styles.trackLineContainer}>
            <View style={styles.trackHorizontalLine} />
            <View style={[styles.outerNodeCircle, { borderColor: primaryColor }]}>
              <View style={[styles.innerNodeDot, { backgroundColor: primaryColor }]} />
            </View>
          </View>
        </View>
      ) : null}
    </View>
  );
};

