import React, { useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  StatusBar,
  BackHandler,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { ScreenHeader } from '@mfe/ui-components/components/header/ScreenHeader';
import { PullToRefreshScrollView } from '@mfe/ui-components/components/scroll/PullToRefreshScrollView';
import { NotificationItem } from '../models/NotificationModel';
import {
  useNotificationViewModel,
  UseNotificationViewModelProps,
} from '../viewmodels/useNotificationViewModel';

export interface NotificationDetailScreenProps {
  notification: NotificationItem;
  onBack: () => void;
  viewModelProps?: UseNotificationViewModelProps;
}

export const NotificationDetailScreen: React.FC<NotificationDetailScreenProps> = ({
  notification,
  onBack,
  viewModelProps,
}) => {
  const {
    selectedNotification,
    isRefreshing,
    loadNotificationDetail,
  } = useNotificationViewModel({
    initialNotification: notification,
    ...viewModelProps,
  });

  const displayNotification = selectedNotification || notification;

  useEffect(() => {
    const backAction = () => {
      onBack();
      return true;
    };
    const sub = BackHandler.addEventListener('hardwareBackPress', backAction);
    return () => sub.remove();
  }, [onBack]);

  return (
    <SafeAreaView
      testID="notification-detail-screen"
      style={styles.safeArea}
      edges={['top', 'left', 'right', 'bottom']}
    >
      <StatusBar barStyle="dark-content" backgroundColor="#FFFFFF" />

      {/* Standard ScreenHeader Component */}
      <ScreenHeader
        title="Notification Detail"
        onBack={onBack}
        testID="notification-detail-header"
      />

      <PullToRefreshScrollView
        refreshing={isRefreshing}
        onRefresh={() => loadNotificationDetail(displayNotification.id)}
        contentContainerStyle={styles.contentWrap}
        showsVerticalScrollIndicator={false}
        testID="notification-detail-pull-refresh"
      >
        {/* Category & Timestamp Row */}
        <View style={styles.metaRow}>
          <Text style={styles.categoryBadge}>
            {displayNotification.category.charAt(0).toUpperCase() +
              displayNotification.category.slice(1)}
          </Text>
          <Text style={styles.timestampText}>{displayNotification.datetime}</Text>
        </View>

        {/* Title */}
        <Text testID="notification-detail-title" style={styles.detailTitle}>
          {displayNotification.title}
        </Text>

        {/* Body Content */}
        <Text testID="notification-detail-body" style={styles.detailBody}>
          {displayNotification.body}
        </Text>
      </PullToRefreshScrollView>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
    backgroundColor: '#FFFFFF',
  },
  contentWrap: {
    paddingHorizontal: 20,
    paddingTop: 20,
  },
  metaRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 12,
  },
  categoryBadge: {
    fontSize: 13,
    fontWeight: '800',
    color: '#2C213F',
  },
  timestampText: {
    fontSize: 12,
    color: '#94A3B8',
  },
  detailTitle: {
    fontSize: 18,
    fontWeight: '800',
    color: '#1E293B',
    marginBottom: 16,
  },
  detailBody: {
    fontSize: 14,
    color: '#334155',
    lineHeight: 22,
  },
});
