import React, { useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
  StyleProp,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { AppBottomSheet, AppAlertModal } from '../../modals';
import { WheelPicker } from './WheelPicker';

export interface QuarterPickerProps {
  label?: string;
  selectedYear: number;
  selectedQuarter: number; // 1 - 4
  onSelect: (year: number, quarter: number) => void;
  minYear?: number;
  maxYear?: number;
  wrapperType?: 'bottomsheet' | 'alert';
  disabled?: boolean;
  style?: StyleProp<ViewStyle>;
  testID?: string;
}

const QUARTER_INFO = [
  { q: 1, label: 'Q1 (Jan - Mar)' },
  { q: 2, label: 'Q2 (Apr - Jun)' },
  { q: 3, label: 'Q3 (Jul - Sep)' },
  { q: 4, label: 'Q4 (Oct - Dec)' },
];

/**
 * Enterprise Quarter & Financial Year Spinner Picker matching DBCS LOS bm-quarter-picker.vue.
 * Features dual spinning wheel columns with looping snap scrolling and bottom sheet wrapper.
 */
export const QuarterPickerField: React.FC<QuarterPickerProps> = ({
  label,
  selectedYear,
  selectedQuarter,
  onSelect,
  minYear = 2020,
  maxYear = 2030,
  wrapperType = 'bottomsheet',
  disabled = false,
  style,
  testID = 'quarter-picker',
}) => {
  const { theme } = useTheme();
  const [modalVisible, setModalVisible] = useState(false);
  const [tempYear, setTempYear] = useState(selectedYear);
  const [tempQuarter, setTempQuarter] = useState(selectedQuarter);

  const formattedValue = `Q${selectedQuarter} ${selectedYear} (${QUARTER_INFO[selectedQuarter - 1]?.label || ''})`;

  const yearItems = Array.from(
    { length: maxYear - minYear + 1 },
    (_, i) => {
      const yr = minYear + i;
      return { key: yr, value: yr, label: `${yr}` };
    }
  );

  const quarterItems = QUARTER_INFO.map((item) => ({
    key: item.q,
    value: item.q,
    label: item.label,
  }));

  const handleOpen = () => {
    if (disabled) return;
    setTempYear(selectedYear);
    setTempQuarter(selectedQuarter);
    setModalVisible(true);
  };

  const handleConfirm = () => {
    onSelect(tempYear, tempQuarter);
    setModalVisible(false);
  };

  const pickerBody = (
    <View style={styles.modalBody}>
      {/* Dual Column Wheel Spinner */}
      <View style={styles.wheelColumnsRow}>
        {/* Quarter Spinner Column */}
        <View style={styles.wheelColumn}>
          <Text style={styles.columnLabel}>Quarter</Text>
          <WheelPicker
            items={quarterItems}
            selectedValue={tempQuarter}
            onValueChange={(it) => setTempQuarter(Number(it.value))}
            testID={`${testID}-quarter-wheel`}
          />
        </View>

        {/* Year Spinner Column */}
        <View style={styles.wheelColumn}>
          <Text style={styles.columnLabel}>Year</Text>
          <WheelPicker
            items={yearItems}
            selectedValue={tempYear}
            onValueChange={(it) => setTempYear(Number(it.value))}
            testID={`${testID}-year-wheel`}
          />
        </View>
      </View>

      {/* Action Buttons */}
      <View style={styles.actionsRow}>
        <TouchableOpacity
          style={styles.cancelBtn}
          onPress={() => setModalVisible(false)}
        >
          <Text style={styles.cancelText}>Cancel</Text>
        </TouchableOpacity>
        <TouchableOpacity
          testID={`${testID}-confirm-btn`}
          style={[styles.confirmBtn, { backgroundColor: theme.colors.primary }]}
          onPress={handleConfirm}
        >
          <Text style={styles.confirmText}>Confirm</Text>
        </TouchableOpacity>
      </View>
    </View>
  );

  return (
    <View testID={testID} style={[styles.container, style]}>
      {label ? <Text style={styles.label}>{label}</Text> : null}

      <TouchableOpacity
        testID={`${testID}-trigger`}
        disabled={disabled}
        onPress={handleOpen}
        activeOpacity={0.7}
        style={[
          styles.inputBox,
          {
            borderColor: '#D1D5DB',
            backgroundColor: disabled ? '#F3F4F6' : '#FFFFFF',
          },
        ]}
      >
        <Text style={styles.valueText} numberOfLines={1}>
          {formattedValue}
        </Text>
        <Text style={styles.icon}>📊</Text>
      </TouchableOpacity>

      {wrapperType === 'bottomsheet' ? (
        <AppBottomSheet
          visible={modalVisible}
          onClose={() => setModalVisible(false)}
          title="Quarter Selection"
        >
          {pickerBody}
        </AppBottomSheet>
      ) : (
        <AppAlertModal
          visible={modalVisible}
          onClose={() => setModalVisible(false)}
          title="Quarter Selection"
        >
          {pickerBody}
        </AppAlertModal>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    width: '100%',
  },
  label: {
    fontSize: 14,
    fontWeight: '600',
    color: '#374151',
    marginBottom: 6,
  },
  inputBox: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    height: 48,
    borderRadius: 8,
    borderWidth: 1,
    paddingHorizontal: 14,
  },
  valueText: {
    fontSize: 14,
    color: '#1F2937',
    fontWeight: '600',
    flex: 1,
    paddingRight: 8,
  },
  icon: {
    fontSize: 18,
  },
  modalBody: {
    paddingVertical: 8,
  },
  wheelColumnsRow: {
    flexDirection: 'row',
    gap: 16,
    paddingVertical: 12,
  },
  wheelColumn: {
    flex: 1,
    alignItems: 'center',
  },
  columnLabel: {
    fontSize: 13,
    fontWeight: '700',
    color: '#4B5563',
    marginBottom: 10,
  },
  actionsRow: {
    flexDirection: 'row',
    justifyContent: 'flex-end',
    gap: 12,
    marginTop: 18,
  },
  cancelBtn: {
    paddingHorizontal: 16,
    paddingVertical: 10,
    borderRadius: 8,
  },
  cancelText: {
    fontSize: 14,
    fontWeight: '600',
    color: '#6B7280',
  },
  confirmBtn: {
    paddingHorizontal: 20,
    paddingVertical: 10,
    borderRadius: 8,
  },
  confirmText: {
    fontSize: 14,
    fontWeight: '700',
    color: '#FFFFFF',
  },
});

