import React, { useEffect } from 'react';
import {
  View,
  StyleSheet,
  StatusBar,
  BackHandler,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { ScreenHeader } from '@mfe/ui-components/components/header/ScreenHeader';
import { AppTabs, TabItem } from '@mfe/ui-components/components/navigation/AppTabs';
import { NoDataState } from '@mfe/ui-components/components/empty/NoDataState';
import { PullToRefreshScrollView } from '@mfe/ui-components/components/scroll/PullToRefreshScrollView';
import { NotificationItem, NotificationCategory } from '../models/NotificationModel';
import { NotificationItemCard } from './components/NotificationItemCard';
import {
  useNotificationViewModel,
  UseNotificationViewModelProps,
} from '../viewmodels/useNotificationViewModel';

export interface NotificationListScreenProps {
  onBack: () => void;
  onSelectNotification: (item: NotificationItem) => void;
  viewModelProps?: UseNotificationViewModelProps;
}

export const NotificationListScreen: React.FC<NotificationListScreenProps> = ({
  onBack,
  onSelectNotification,
  viewModelProps,
}) => {
  const {
    activeTab,
    setActiveTab,
    isRefreshing,
    handleRefresh,
    filterByCategory,
  } = useNotificationViewModel(viewModelProps);

  // Support Android hardware back button
  useEffect(() => {
    const backAction = () => {
      onBack();
      return true;
    };
    const sub = BackHandler.addEventListener('hardwareBackPress', backAction);
    return () => sub.remove();
  }, [onBack]);

  const renderNotificationCardList = (category: NotificationCategory) => {
    const list = filterByCategory(category);

    if (list.length === 0) {
      return (
        <PullToRefreshScrollView
          refreshing={isRefreshing}
          onRefresh={handleRefresh}
          contentContainerStyle={styles.emptyContainer}
          showsVerticalScrollIndicator={false}
        >
          <NoDataState
            title="No data available."
            message="No notifications in this category."
            testID="notification-no-data"
          />
        </PullToRefreshScrollView>
      );
    }

    return (
      <PullToRefreshScrollView
        refreshing={isRefreshing}
        onRefresh={handleRefresh}
        contentContainerStyle={styles.scrollList}
        showsVerticalScrollIndicator={false}
        testID="notification-list-pull-refresh"
      >
        {list.map((item) => (
          <NotificationItemCard
            key={item.id}
            item={item}
            onPress={onSelectNotification}
          />
        ))}

        <View style={{ height: 40 }} />
      </PullToRefreshScrollView>
    );
  };

  const tabs: TabItem[] = [
    {
      key: 'all',
      label: 'All',
      content: renderNotificationCardList('all'),
    },
    {
      key: 'approval',
      label: 'Approval',
      content: renderNotificationCardList('approval'),
    },
    {
      key: 'reminder',
      label: 'Reminder',
      content: renderNotificationCardList('reminder'),
    },
    {
      key: 'announcements',
      label: 'Announcements',
      content: renderNotificationCardList('announcements'),
    },
  ];

  return (
    <SafeAreaView
      testID="notification-list-screen"
      style={styles.safeArea}
      edges={['top', 'left', 'right', 'bottom']}
    >
      <StatusBar barStyle="dark-content" backgroundColor="#FFFFFF" />

      {/* Standard ScreenHeader Component */}
      <ScreenHeader
        title="Notification"
        onBack={onBack}
        testID="notification-list-header"
      />

      {/* Standard AppTabs Tab Bar & Content Switcher */}
      <AppTabs
        tabs={tabs}
        activeKey={activeTab}
        onTabChange={(k) => setActiveTab(k as NotificationCategory)}
        variant="pills"
        scrollable={true}
        containerStyle={styles.tabsContainer}
        tabBarStyle={styles.tabBarPadding}
        contentContainerStyle={styles.tabContentArea}
      />
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
    backgroundColor: '#F8FAFC',
  },
  tabsContainer: {
    flex: 1,
  },
  tabBarPadding: {
    backgroundColor: '#FFFFFF',
    paddingHorizontal: 16,
    paddingVertical: 10,
    borderBottomWidth: 1,
    borderBottomColor: '#F1F5F9',
  },
  tabContentArea: {
    flex: 1,
    paddingVertical: 0,
  },
  scrollList: {
    paddingHorizontal: 16,
    paddingTop: 16,
    backgroundColor: '#F8FAFC',
  },
  emptyContainer: {
    paddingVertical: 60,
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: '#F8FAFC',
  },
});
