import React, { forwardRef, useImperativeHandle, useRef } from 'react';
import {
  Platform,
  View,
  Text,
  StyleSheet,
  StyleProp,
  ViewStyle,
} from 'react-native';
import {
  NativePdfView as BizmobNativePdfView,
  type NativePdfRef,
  type NativePdfViewProps,
  type NativePdfPageChangeEvent,
  type NativePdfLoadEvent,
  type NativePdfProgressEvent,
  type NativePdfZoomEvent,
  type NativePdfErrorEvent,
  type NativePdfScrollEvent,
} from 'react-native-bizmob-plugin';

export type {
  NativePdfRef,
  NativePdfViewProps,
  NativePdfPageChangeEvent,
  NativePdfLoadEvent,
  NativePdfProgressEvent,
  NativePdfZoomEvent,
  NativePdfErrorEvent,
  NativePdfScrollEvent,
};

/**
 * Enterprise Native PDF View Component for LosReactNative.
 * Encapsulates react-native-bizmob-plugin NativePdfView across Mobile (Android PdfRenderer, iOS PDFKit)
 * and Web/Test environments (HTML5 iframe & Jest mock view).
 */
export const NativePdfView = forwardRef<NativePdfRef, NativePdfViewProps>((props, ref) => {
  const innerRef = useRef<any>(null);

  useImperativeHandle(ref, () => ({
    goToPreviousPage: () => innerRef.current?.goToPreviousPage?.(),
    goToNextPage: () => innerRef.current?.goToNextPage?.(),
    goToFirstPage: () => innerRef.current?.goToFirstPage?.(),
    goToLastPage: () => innerRef.current?.goToLastPage?.(),
    moveToPage: (page: number, animated?: boolean) => innerRef.current?.moveToPage?.(page, animated),
    setZoom: (scale: number) => innerRef.current?.setZoom?.(scale),
    resetZoom: () => innerRef.current?.resetZoom?.(),
  }));

  // On Jest / simulated test environments where native components are unmanaged:
  if (process.env.NODE_ENV === 'test') {
    return (
      <View
        testID={props.testID || 'native-pdf-view'}
        style={[styles.testFallback, props.style]}
      >
        <Text testID={`${props.testID || 'native-pdf-view'}-mock-indicator`} style={styles.testText}>
          {props.sourceUrl || props.filePath ? 'NativePdfView: File Source' : 'NativePdfView: Embedded Base64'}
        </Text>
      </View>
    );
  }

  return (
    <BizmobNativePdfView
      ref={innerRef}
      {...props}
      testID={props.testID || 'native-pdf-view'}
    />
  );
});

NativePdfView.displayName = 'NativePdfView';

const styles = StyleSheet.create({
  testFallback: {
    backgroundColor: '#F3F4F6',
    justifyContent: 'center',
    alignItems: 'center',
    minHeight: 200,
  },
  testText: {
    fontSize: 12,
    color: '#6B7280',
  },
});
