import React from 'react';
import { View, Text, StyleSheet } from 'react-native';

export interface StepItem {
  key: string;
  label: string;
}

export interface StepIndicatorProps {
  steps: StepItem[];
  currentStepIndex: number;
  testID?: string;
}

export const StepIndicator: React.FC<StepIndicatorProps> = ({
  steps,
  currentStepIndex,
  testID = 'step-indicator',
}) => {
  return (
    <View testID={testID} style={styles.container}>
      <View style={styles.stepsRow}>
        {steps.map((step, index) => {
          const isCompleted = index < currentStepIndex;
          const isCurrent = index === currentStepIndex;
          const isLast = index === steps.length - 1;

          return (
            <React.Fragment key={step.key || `step-${index}`}>
              <View style={styles.nodeWrapper}>
                <View
                  testID={`${testID}-node-${index}`}
                  style={[
                    styles.node,
                    isCompleted && styles.nodeCompleted,
                    isCurrent && styles.nodeCurrent,
                  ]}
                >
                  <Text
                    style={[
                      styles.nodeText,
                      (isCompleted || isCurrent) && styles.nodeTextActive,
                    ]}
                  >
                    {isCompleted ? '✓' : String(index + 1)}
                  </Text>
                </View>
                <Text
                  numberOfLines={1}
                  style={[
                    styles.label,
                    isCurrent && styles.labelCurrent,
                    isCompleted && styles.labelCompleted,
                  ]}
                >
                  {step.label}
                </Text>
              </View>

              {!isLast && (
                <View
                  testID={`${testID}-line-${index}`}
                  style={[
                    styles.connectorLine,
                    isCompleted && styles.connectorLineCompleted,
                  ]}
                />
              )}
            </React.Fragment>
          );
        })}
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    paddingVertical: 12,
    paddingHorizontal: 8,
  },
  stepsRow: {
    flexDirection: 'row',
    alignItems: 'flex-start',
    justifyContent: 'space-between',
  },
  nodeWrapper: {
    alignItems: 'center',
    width: 60,
  },
  node: {
    width: 28,
    height: 28,
    borderRadius: 14,
    backgroundColor: '#E2E5EB',
    justifyContent: 'center',
    alignItems: 'center',
    marginBottom: 6,
  },
  nodeCurrent: {
    backgroundColor: '#E7252B',
  },
  nodeCompleted: {
    backgroundColor: '#117A4D',
  },
  nodeText: {
    color: '#7B8494',
    fontSize: 12,
    fontWeight: '700',
  },
  nodeTextActive: {
    color: '#FFFFFF',
  },
  label: {
    fontSize: 11,
    color: '#7B8494',
    textAlign: 'center',
  },
  labelCurrent: {
    color: '#E7252B',
    fontWeight: '700',
  },
  labelCompleted: {
    color: '#117A4D',
    fontWeight: '600',
  },
  connectorLine: {
    flex: 1,
    height: 2,
    backgroundColor: '#E2E5EB',
    marginTop: 13,
    marginHorizontal: 4,
  },
  connectorLineCompleted: {
    backgroundColor: '#117A4D',
  },
});

