import React from 'react';
import { View, TouchableOpacity, StyleSheet, ViewStyle } from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export interface AppCardProps {
  children: React.ReactNode;
  style?: ViewStyle | (ViewStyle | false | null | undefined)[];
  elevation?: 'none' | 'low' | 'medium' | 'high';
  onPress?: () => void;
  testID?: string;
}

export const AppCard: React.FC<AppCardProps> = ({
  children,
  style,
  elevation = 'medium',
  onPress,
  testID = 'app-card',
}) => {
  const { theme } = useTheme();

  const elevationStyle =
    elevation === 'none'
      ? { shadowOpacity: 0, elevation: 0 }
      : elevation === 'low'
      ? { shadowOpacity: 0.03, elevation: 1 }
      : elevation === 'high'
      ? { shadowOpacity: 0.1, elevation: 4 }
      : { shadowOpacity: 0.05, elevation: 2 };

  const cardContent = (
    <View
      testID={testID}
      style={[
        styles.card,
        {
          backgroundColor: theme.colors.card,
          borderRadius: theme.radius.lg,
          borderColor: theme.colors.border,
          padding: theme.spacing.lg,
        },
        elevationStyle,
        style as any,
      ]}
    >
      {children}
    </View>
  );

  if (onPress) {
    return (
      <TouchableOpacity
        testID={`${testID}-touchable`}
        activeOpacity={0.8}
        onPress={onPress}
      >
        {cardContent}
      </TouchableOpacity>
    );
  }

  return cardContent;
};

const styles = StyleSheet.create({
  card: {
    borderWidth: 1,
    marginVertical: 6,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.05,
    shadowRadius: 6,
    elevation: 2,
  },
});
