import React, { useState } from 'react';
import { View } from 'react-native';
import { ShowcaseListScreen } from './ShowcaseListScreen';
import { ShowcaseDetailScreen, ShowcaseCategoryId } from './ShowcaseDetailScreen';

export interface ShowcaseScreenProps {
  initialCategoryId?: ShowcaseCategoryId;
}

/**
 * ShowcaseScreen wrapper component:
 * When rendered standalone (or in unit/UI tests without navigation params),
 * it manages master-detail state internally.
 * When integrated into RootNavigator, ShowcaseListScreen and ShowcaseDetailScreen
 * are navigated as native stack screens for authentic iOS swipe-back.
 */
export const ShowcaseScreen: React.FC<ShowcaseScreenProps> = ({
  initialCategoryId = null,
}) => {
  const [selectedItem, setSelectedItem] = useState<ShowcaseCategoryId | null>(initialCategoryId);

  if (selectedItem) {
    return (
      <ShowcaseDetailScreen
        categoryId={selectedItem}
        onBack={() => setSelectedItem(null)}
      />
    );
  }

  // Master list view
  return (
    <View style={{ flex: 1 }}>
      <ShowcaseListScreen onSelectItem={(id) => setSelectedItem(id)} />
    </View>
  );
};
