import React from 'react';
import {
  View,
  Text,
  StyleSheet,
  ViewStyle,
  TextStyle,
  Platform,
} from 'react-native';
import Svg, { Path } from 'react-native-svg';

export type InfoBannerVariant = 'info' | 'tip' | 'warning' | 'success';

export interface InfoBannerProps {
  /**
   * Main message text
   */
  message: string;
  /**
   * Visual variant: 'info' (default) | 'tip' | 'warning' | 'success'
   */
  variant?: InfoBannerVariant;
  /**
   * Custom icon component or render function
   */
  icon?: React.ReactNode;
  /**
   * Container style override
   */
  style?: ViewStyle;
  /**
   * Message text style override
   */
  textStyle?: TextStyle;
  /**
   * Accessibility test ID
   */
  testID?: string;
}

/**
 * Lightbulb / Idea Tip Icon
 */
const LightbulbIcon: React.FC<{ color?: string; size?: number }> = ({
  color = '#FFFFFF',
  size = 16,
}) => (
  <Svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    {/* Lightbulb glass */}
    <Path
      d="M9 21H15M10 24H14"
      stroke={color}
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
    />
    <Path
      d="M12 2C8.13401 2 5 5.13401 5 9C5 11.3867 6.19687 13.4941 8 14.7431V17C8 17.5523 8.44772 18 9 18H15C15.5523 18 16 17.5523 16 17V14.7431C17.8031 13.4941 19 11.3867 19 9C19 5.13401 15.866 2 12 2Z"
      stroke={color}
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
    />
    {/* Inner filament light ray */}
    <Path
      d="M12 6V9M9.5 7.5L11 9M14.5 7.5L13 9"
      stroke={color}
      strokeWidth={1.8}
      strokeLinecap="round"
    />
  </Svg>
);

/**
 * InfoBanner (Information Callout Box)
 *
 * Matching Lotte Finance ID Verification & Help callouts:
 * - Soft rounded container with subtle background
 * - Distinct circular icon badge with white lightbulb/tip/info icon
 * - Clean text explaining editable or helpful context
 */
export const InfoBanner: React.FC<InfoBannerProps> = ({
  message,
  variant = 'info',
  icon,
  style,
  textStyle,
  testID = 'info-banner',
}) => {
  const isTipOrInfo = variant === 'info' || variant === 'tip';
  const isWarning = variant === 'warning';
  const isSuccess = variant === 'success';

  return (
    <View
      style={[
        styles.container,
        isTipOrInfo && styles.containerInfo,
        isWarning && styles.containerWarning,
        isSuccess && styles.containerSuccess,
        style,
      ]}
      testID={testID}
    >
      <View
        style={[
          styles.iconBadge,
          isTipOrInfo && styles.iconBadgeInfo,
          isWarning && styles.iconBadgeWarning,
          isSuccess && styles.iconBadgeSuccess,
        ]}
        testID={`${testID}-icon-badge`}
      >
        {icon ? icon : <LightbulbIcon size={14} color="#FFFFFF" />}
      </View>

      <Text
        style={[
          styles.message,
          isTipOrInfo && styles.messageInfo,
          isWarning && styles.messageWarning,
          isSuccess && styles.messageSuccess,
          textStyle,
        ]}
        testID={`${testID}-message`}
      >
        {message}
      </Text>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flexDirection: 'row',
    alignItems: 'center',
    borderRadius: 12,
    paddingVertical: 14,
    paddingHorizontal: 16,
    width: '100%',
  },
  containerInfo: {
    backgroundColor: '#F3F6FD', // Soft subtle cool blue background
  },
  containerWarning: {
    backgroundColor: '#FFF7ED', // Soft subtle amber background
  },
  containerSuccess: {
    backgroundColor: '#F0FDF4', // Soft subtle green background
  },
  iconBadge: {
    width: 26,
    height: 26,
    borderRadius: 13,
    alignItems: 'center',
    justifyContent: 'center',
    marginRight: 12,
    flexShrink: 0,
  },
  iconBadgeInfo: {
    backgroundColor: '#2563EB', // Vibrant blue circular badge
  },
  iconBadgeWarning: {
    backgroundColor: '#F97316', // Orange circular badge
  },
  iconBadgeSuccess: {
    backgroundColor: '#16A34A', // Green circular badge
  },
  message: {
    flex: 1,
    fontSize: 14,
    lineHeight: 20,
    fontWeight: '400',
    fontFamily: Platform.select({
      ios: 'Pretendard-Regular',
      android: 'Pretendard-Regular',
      default: 'system-ui',
    }),
  },
  messageInfo: {
    color: '#334155', // Slate-700
  },
  messageWarning: {
    color: '#9A3412', // Orange-800
  },
  messageSuccess: {
    color: '#166534', // Green-800
  },
});
