import React, { useEffect, useRef } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  Animated,
  Easing,
  ViewStyle,
} from 'react-native';
import { FullScreenAlertType } from '@mfe/core/utils/fullScreenAlertUtil';

export interface AnimatedStatusIconProps {
  type: FullScreenAlertType;
  animated?: boolean;
  size?: number; // default 96
  style?: ViewStyle;
  testID?: string;
}

/**
 * Animated Status Icon for Success / Failed / Warning states.
 * Faithfully reproduces the screenshot's circular green icon with a checkmark
 * and surrounding dashed orbit accent, with optional smooth spring/rotation animation.
 */
export const AnimatedStatusIcon: React.FC<AnimatedStatusIconProps> = ({
  type,
  animated = true,
  size = 96,
  style,
  testID = 'animated-status-icon',
}) => {
  const scaleAnim = useRef(new Animated.Value(animated ? 0.3 : 1)).current;
  const rotateAnim = useRef(new Animated.Value(0)).current;
  const opacityAnim = useRef(new Animated.Value(animated ? 0 : 1)).current;

  useEffect(() => {
    if (animated) {
      Animated.parallel([
        Animated.spring(scaleAnim, {
          toValue: 1,
          friction: 4,
          tension: 40,
          useNativeDriver: true,
        }),
        Animated.timing(opacityAnim, {
          toValue: 1,
          duration: 300,
          useNativeDriver: true,
        }),
        Animated.timing(rotateAnim, {
          toValue: 1,
          duration: 700,
          easing: Easing.out(Easing.cubic),
          useNativeDriver: true,
        }),
      ]).start();
    }
  }, [animated, scaleAnim, opacityAnim, rotateAnim]);

  const spin = rotateAnim.interpolate({
    inputRange: [0, 1],
    outputRange: ['-45deg', '0deg'],
  });

  const getColor = () => {
    switch (type) {
      case 'success':
        return '#00C853'; // Lotte / Vietnamese Banking Emerald Green
      case 'failed':
        return '#E5252A'; // Lotte Red
      case 'warning':
        return '#F59E0B'; // Amber
      case 'info':
      default:
        return '#2563EB'; // Royal Blue
    }
  };

  const color = getColor();
  const innerSize = size * 0.75;
  const strokeWidth = size * 0.065;

  return (
    <Animated.View
      style={[
        styles.container,
        {
          width: size,
          height: size,
          opacity: opacityAnim,
          transform: [{ scale: scaleAnim }, { rotate: spin }],
        },
        style,
      ]}
      testID={testID}
    >
      {/* Surrounding orbit/accent dots (visible in screenshot around top-left) */}
      <View
        style={[
          styles.orbitDot,
          {
            backgroundColor: color,
            top: size * 0.08,
            left: size * 0.22,
            width: size * 0.065,
            height: size * 0.065,
            borderRadius: (size * 0.065) / 2,
          },
        ]}
      />
      <View
        style={[
          styles.orbitDot,
          {
            backgroundColor: color,
            top: size * 0.22,
            left: size * 0.08,
            width: size * 0.05,
            height: size * 0.05,
            borderRadius: (size * 0.05) / 2,
          },
        ]}
      />

      {/* Main Circular Ring */}
      <View
        style={[
          styles.mainCircle,
          {
            width: innerSize,
            height: innerSize,
            borderRadius: innerSize / 2,
            borderColor: color,
            borderWidth: strokeWidth,
          },
        ]}
        testID={`${testID}-circle`}
      >
        {type === 'success' && (
          <Text
            style={[
              styles.symbolText,
              { color, fontSize: innerSize * 0.55, marginTop: -innerSize * 0.08 },
            ]}
            testID={`${testID}-check`}
          >
            ✓
          </Text>
        )}
        {type === 'failed' && (
          <Text
            style={[
              styles.symbolText,
              { color, fontSize: innerSize * 0.52, marginTop: -innerSize * 0.05 },
            ]}
            testID={`${testID}-cross`}
          >
            ✕
          </Text>
        )}
        {type === 'warning' && (
          <Text
            style={[
              styles.symbolText,
              { color, fontSize: innerSize * 0.52, fontWeight: '800' },
            ]}
            testID={`${testID}-exclamation`}
          >
            !
          </Text>
        )}
        {type === 'info' && (
          <Text
            style={[
              styles.symbolText,
              { color, fontSize: innerSize * 0.5, fontWeight: '700' },
            ]}
            testID={`${testID}-info`}
          >
            i
          </Text>
        )}
      </View>
    </Animated.View>
  );
};

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    justifyContent: 'center',
    position: 'relative',
  },
  orbitDot: {
    position: 'absolute',
    opacity: 0.85,
  },
  mainCircle: {
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: '#FFFFFF',
  },
  symbolText: {
    fontWeight: '800',
    textAlign: 'center',
    lineHeight: undefined,
  },
});
