import { Platform } from 'react-native';

/**
 * Maps Module Federation container names to local OTA folder names under mfe_contents/.
 */
const REMOTE_CONTAINER_TO_FOLDER: Record<string, string> = {
  remote_launch_auth: 'remote-launch-auth',
  remote_dashboard: 'remote-dashboard',
  remote_customer: 'remote-customer',
  remote_loan_origination: 'remote-loan-origination',
  remote_notification: 'remote-notification',
  remote_showcase: 'remote-showcase',
};

const REMOTE_DEV_PORTS: Record<string, number> = {
  remote_launch_auth: 9001,
  remote_dashboard: 9002,
  remote_customer: 9003,
  remote_loan_origination: 9004,
  remote_notification: 9005,
  remote_showcase: 9006,
};

let initialized = false;

/**
 * Configures Re.Pack ScriptManager to load federated remote bundles from:
 * - Local dev server (http://localhost:<port>/<platform>/...) in __DEV__
 * - Local OTA storage (file://<mfeContentsBaseDir>/<remoteFolder>/...) in production
 */
export function initRepackOtaResolver(mfeContentsBaseDir?: string): void {
  if (initialized || Platform.OS === 'web') return;
  initialized = true;

  try {
    // Dynamic require so Jest / Web / Metro environments never fail if ScriptManager is absent
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const { ScriptManager, Script } = require('@callstack/repack/client');
    if (!ScriptManager?.shared) return;

    ScriptManager.shared.addResolver(async (scriptId: string, caller?: string) => {
      const containerKey = caller && REMOTE_CONTAINER_TO_FOLDER[caller] ? caller : scriptId;
      const remoteFolder = REMOTE_CONTAINER_TO_FOLDER[containerKey];
      if (!remoteFolder) {
        return undefined;
      }

      const isContainerEntry = scriptId === containerKey || scriptId === remoteFolder;
      const fileName = isContainerEntry
        ? `${remoteFolder}.container.bundle`
        : scriptId.endsWith('.bundle')
          ? scriptId
          : `${scriptId}.bundle`;

      if (__DEV__) {
        const port = REMOTE_DEV_PORTS[containerKey] || 9001;
        const devHost = Platform.OS === 'android' ? '10.0.2.2' : 'localhost';
        return {
          url: Script.getRemoteURL(`http://${devHost}:${port}/${Platform.OS}/${fileName}`),
          cache: true,
        };
      }

      if (mfeContentsBaseDir) {
        const cleanBase = mfeContentsBaseDir.replace(/\/+$/, '');
        return {
          url: Script.getFileSystemURL(`${cleanBase}/${remoteFolder}/${fileName}`),
          cache: false,
        };
      }

      return {
        url: Script.getFileSystemURL(`mfe_contents/${remoteFolder}/${fileName}`),
        cache: false,
      };
    });
  } catch {
    // Running under Metro / Jest / Web without Re.Pack runtime — safely ignore
  }
}
