import React, { useRef, useState } from 'react';
import {
  Modal,
  StyleProp,
  StyleSheet,
  Text,
  TouchableOpacity,
  TouchableWithoutFeedback,
  useWindowDimensions,
  View,
  ViewStyle,
} from 'react-native';
import { useTheme, defaultTheme } from '@mfe/theme';

export interface ContextMenuItem {
  id: string;
  label: string;
  icon?: React.ReactNode;
  destructive?: boolean;
  disabled?: boolean;
  dividerBefore?: boolean;
  onPress: () => void;
}

export interface ContextMenuProps {
  items: ContextMenuItem[];
  trigger?: 'press' | 'longPress';
  menuWidth?: number;
  title?: string;
  style?: StyleProp<ViewStyle>;
  children: React.ReactNode;
  testID?: string;
}

export const ContextMenu: React.FC<ContextMenuProps> = ({
  items,
  trigger = 'press',
  menuWidth = 210,
  title,
  style,
  children,
  testID = 'context-menu',
}) => {
  const themeContext = useTheme();
  const theme = themeContext?.theme || defaultTheme;
  const { colors, radius } = theme;
  const { width: windowWidth, height: windowHeight } = useWindowDimensions();

  const triggerRef = useRef<View | null>(null);
  const [visible, setVisible] = useState(false);
  const [anchor, setAnchor] = useState({ top: 120, left: 16 });

  const openMenu = () => {
    const estimatedHeight = items.length * 46 + (title ? 36 : 0) + 16;
    setVisible(true);

    if (triggerRef.current && typeof triggerRef.current.measureInWindow === 'function') {
      triggerRef.current.measureInWindow((x, y, w, h) => {
        const clampedLeft = Math.max(
          12,
          Math.min(x + w - menuWidth, windowWidth - menuWidth - 12)
        );
        const fitsBelow = y + h + 8 + estimatedHeight <= windowHeight - 16;
        const computedTop = fitsBelow
          ? y + h + 6
          : Math.max(16, y - estimatedHeight - 6);

        setAnchor({ top: computedTop, left: clampedLeft });
      });
    }
  };

  const handleSelectItem = (item: ContextMenuItem) => {
    if (item.disabled) return;
    setVisible(false);
    item.onPress();
  };

  return (
    <View ref={triggerRef} collapsable={false} style={style}>
      <TouchableOpacity
        testID={`${testID}-trigger`}
        activeOpacity={0.75}
        onPress={trigger === 'press' ? openMenu : undefined}
        onLongPress={trigger === 'longPress' ? openMenu : undefined}
      >
        {children}
      </TouchableOpacity>

      <Modal
        visible={visible}
        transparent
        animationType="fade"
        onRequestClose={() => setVisible(false)}
      >
        <TouchableWithoutFeedback
          testID={`${testID}-backdrop`}
          onPress={() => setVisible(false)}
        >
          <View style={styles.backdrop}>
            <TouchableWithoutFeedback>
              <View
                testID={`${testID}-popover`}
                style={[
                  styles.menuCard,
                  {
                    width: menuWidth,
                    top: anchor.top,
                    left: anchor.left,
                    backgroundColor: colors.card,
                    borderColor: colors.border,
                    borderRadius: radius.lg,
                  },
                ]}
              >
                {title ? (
                  <View
                    style={[
                      styles.titleHeader,
                      { borderBottomColor: colors.borderLight },
                    ]}
                  >
                    <Text
                      numberOfLines={1}
                      style={[styles.titleText, { color: colors.textSubtle }]}
                    >
                      {title}
                    </Text>
                  </View>
                ) : null}

                {items.map((item) => (
                  <React.Fragment key={item.id}>
                    {item.dividerBefore ? (
                      <View
                        style={[
                          styles.divider,
                          { backgroundColor: colors.borderLight },
                        ]}
                      />
                    ) : null}
                    <TouchableOpacity
                      testID={`${testID}-item-${item.id}`}
                      activeOpacity={0.7}
                      disabled={item.disabled}
                      onPress={() => handleSelectItem(item)}
                      style={[
                        styles.menuItem,
                        item.disabled && styles.menuItemDisabled,
                      ]}
                    >
                      {item.icon ? (
                        <View style={styles.itemIcon}>{item.icon}</View>
                      ) : null}
                      <Text
                        numberOfLines={1}
                        style={[
                          styles.itemLabel,
                          {
                            color: item.destructive
                              ? colors.error
                              : colors.text,
                          },
                        ]}
                      >
                        {item.label}
                      </Text>
                    </TouchableOpacity>
                  </React.Fragment>
                ))}
              </View>
            </TouchableWithoutFeedback>
          </View>
        </TouchableWithoutFeedback>
      </Modal>
    </View>
  );
};

const styles = StyleSheet.create({
  backdrop: {
    flex: 1,
    backgroundColor: 'rgba(15, 23, 42, 0.14)',
  },
  menuCard: {
    position: 'absolute',
    borderWidth: 1,
    paddingVertical: 6,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 6 },
    shadowOpacity: 0.14,
    shadowRadius: 14,
    elevation: 8,
  },
  titleHeader: {
    paddingHorizontal: 14,
    paddingVertical: 8,
    borderBottomWidth: 1,
    marginBottom: 4,
  },
  titleText: {
    fontSize: 11,
    fontWeight: '700',
    textTransform: 'uppercase',
    letterSpacing: 0.4,
  },
  divider: {
    height: 1,
    marginVertical: 4,
  },
  menuItem: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 14,
    paddingVertical: 11,
  },
  menuItemDisabled: {
    opacity: 0.4,
  },
  itemIcon: {
    marginRight: 10,
  },
  itemLabel: {
    fontSize: 14,
    fontWeight: '600',
    flex: 1,
  },
});

export default ContextMenu;
