export type SupportedLanguage = 'km' | 'en' | 'ko' | 'zh';

export interface LanguageOption {
  code: SupportedLanguage;
  name: string;
  nativeName: string;
  countryCode: string;
}

export const SUPPORTED_LANGUAGES: LanguageOption[] = [
  {
    code: 'km',
    name: 'Khmer',
    nativeName: 'ភាសាខ្មែរ',
    countryCode: 'KH',
  },
  {
    code: 'en',
    name: 'English',
    nativeName: 'English',
    countryCode: 'GB',
  },
  {
    code: 'ko',
    name: 'Korean',
    nativeName: 'Korean',
    countryCode: 'KR',
  },
  {
    code: 'zh',
    name: 'Chinese',
    nativeName: 'Chinese',
    countryCode: 'CN',
  },
];

export interface AppVersionInfo {
  version: string;
  copyright: string;
  buildNumber?: string;
}

export interface ContentUpdateProgress {
  progressPercentage: number;
  statusText: string;
  isComplete: boolean;
  error?: string | null;
}

export interface DeviceInfoResult {
  deviceId: string;
  osType: string;
  osVersion: string;
  model?: string;
  manufacturer?: string;
  language?: string;
}

export interface TermsAndConditionsState {
  hasAgreed: boolean;
  title: string;
  content: string;
}

export class LaunchValidator {
  static isValidLanguage(code: string): code is SupportedLanguage {
    return SUPPORTED_LANGUAGES.some((lang) => lang.code === code);
  }

  static canProceedWithTerms(agreed: boolean): boolean {
    return agreed === true;
  }

  static clampProgress(percentage: number): number {
    if (isNaN(percentage)) return 0;
    return Math.min(100, Math.max(0, percentage));
  }
}
