/**
 * Multi-Method Loan Interest Amortization Engine
 *
 * Supports:
 * - Equal Principal (Declining Balance)
 * - Equal Installment (Annuity / EMI)
 * - Flat Interest (Simple Microfinance)
 */

export interface AmortizationScheduleRow {
  period: number;
  principal: number;
  interest: number;
  totalPayment: number;
  remainingBalance: number;
}

export type InterestMethod = 'EQUAL_INSTALLMENT' | 'EQUAL_PRINCIPAL' | 'FLAT';

export interface AmortizationParams {
  principalAmount: number;
  annualInterestRatePercent: number;
  tenureMonths: number;
  method?: InterestMethod;
}

export interface AmortizationSummary {
  method: InterestMethod;
  monthlyInstallment: number;
  totalInterest: number;
  totalPayment: number;
  schedule: AmortizationScheduleRow[];
}

/**
 * Computes complete loan amortization schedule across banking models.
 */
export function calculateAmortizationSchedule(
  params: AmortizationParams
): AmortizationSummary {
  const {
    principalAmount,
    annualInterestRatePercent,
    tenureMonths,
    method = 'EQUAL_INSTALLMENT',
  } = params;

  const monthlyRate = annualInterestRatePercent / 100 / 12;
  const schedule: AmortizationScheduleRow[] = [];
  let remaining = principalAmount;
  let totalInterest = 0;

  if (method === 'FLAT') {
    const monthlyPrincipal = Math.round((principalAmount / tenureMonths) * 100) / 100;
    const monthlyInterest = Math.round((principalAmount * monthlyRate) * 100) / 100;
    const monthlyPayment = monthlyPrincipal + monthlyInterest;

    for (let p = 1; p <= tenureMonths; p++) {
      remaining = Math.max(0, Math.round((remaining - monthlyPrincipal) * 100) / 100);
      totalInterest += monthlyInterest;
      schedule.push({
        period: p,
        principal: monthlyPrincipal,
        interest: monthlyInterest,
        totalPayment: monthlyPayment,
        remainingBalance: remaining,
      });
    }

    return {
      method: 'FLAT',
      monthlyInstallment: monthlyPayment,
      totalInterest: Math.round(totalInterest * 100) / 100,
      totalPayment: Math.round((principalAmount + totalInterest) * 100) / 100,
      schedule,
    };
  }

  if (method === 'EQUAL_PRINCIPAL') {
    const fixedPrincipal = Math.round((principalAmount / tenureMonths) * 100) / 100;

    for (let p = 1; p <= tenureMonths; p++) {
      const interest = Math.round((remaining * monthlyRate) * 100) / 100;
      totalInterest += interest;
      remaining = Math.max(0, Math.round((remaining - fixedPrincipal) * 100) / 100);

      schedule.push({
        period: p,
        principal: fixedPrincipal,
        interest,
        totalPayment: Math.round((fixedPrincipal + interest) * 100) / 100,
        remainingBalance: remaining,
      });
    }

    return {
      method: 'EQUAL_PRINCIPAL',
      monthlyInstallment: schedule[0]?.totalPayment || 0,
      totalInterest: Math.round(totalInterest * 100) / 100,
      totalPayment: Math.round((principalAmount + totalInterest) * 100) / 100,
      schedule,
    };
  }

  // Default: EQUAL_INSTALLMENT (Annuity / EMI)
  const emi =
    monthlyRate > 0
      ? (principalAmount * monthlyRate * Math.pow(1 + monthlyRate, tenureMonths)) /
        (Math.pow(1 + monthlyRate, tenureMonths) - 1)
      : principalAmount / tenureMonths;

  const roundedEmi = Math.round(emi * 100) / 100;

  for (let p = 1; p <= tenureMonths; p++) {
    const interest = Math.round((remaining * monthlyRate) * 100) / 100;
    const principal = Math.min(remaining, Math.round((roundedEmi - interest) * 100) / 100);
    totalInterest += interest;
    remaining = Math.max(0, Math.round((remaining - principal) * 100) / 100);

    schedule.push({
      period: p,
      principal,
      interest,
      totalPayment: Math.round((principal + interest) * 100) / 100,
      remainingBalance: remaining,
    });
  }

  return {
    method: 'EQUAL_INSTALLMENT',
    monthlyInstallment: roundedEmi,
    totalInterest: Math.round(totalInterest * 100) / 100,
    totalPayment: Math.round((principalAmount + totalInterest) * 100) / 100,
    schedule,
  };
}
