import { useState, useCallback } from 'react';
import { LoanCalculator } from '@mfe/core/utils/loanCalculator';
import { FormatUtil } from '@mfe/core/utils/formatUtil';
import { IdCardValidator } from '@mfe/core/utils/idCardValidator';
import { DraftStorage } from '@mfe/core/utils/draftStorage';
import { LoanOriginationService, LoanApplicationDTO } from '@mfe/remote-loan-origination';

export interface ShowcaseState {
  // Calculator interactive state
  principal: number;
  rate: number;
  tenure: number;
  monthlyPayment: number;
  totalInterest: number;

  // Selection state
  scheme: 'CASH' | 'CAR' | 'DURABLE';
  currentStep: number;
  badgeStatus: 'success' | 'warning' | 'error' | 'info';
  agreeTerms: boolean;
  biometricEnabled: boolean;
  activeSegment: 'SIMULATION' | 'COMPONENTS' | 'APPLICATIONS';
  otpCode: string;

  // Validation tester
  testIdCard: string;
  idCardResult: string;

  // Dialog state
  dialogVisible: boolean;

  // Applications list
  applications: LoanApplicationDTO[];
  isLoadingApps: boolean;
}

export const useShowcaseViewModel = () => {
  const [principal, setPrincipal] = useState<number>(5000);
  const [rate, setRate] = useState<number>(12);
  const [tenure, setTenure] = useState<number>(12);
  const [scheme, setScheme] = useState<'CASH' | 'CAR' | 'DURABLE'>('CASH');
  const [currentStep, setCurrentStep] = useState<number>(1);
  const [agreeTerms, setAgreeTerms] = useState<boolean>(true);
  const [biometricEnabled, setBiometricEnabled] = useState<boolean>(false);
  const [activeSegment, setActiveSegment] = useState<
    'SIMULATION' | 'COMPONENTS' | 'APPLICATIONS'
  >('SIMULATION');
  const [otpCode, setOtpCode] = useState<string>('1234');
  const [dialogVisible, setDialogVisible] = useState<boolean>(false);

  const [testIdCard, setTestIdCard] = useState<string>('012345678901');
  const [idCardResult, setIdCardResult] = useState<string>('Valid 12-digit ID');

  const [applications, setApplications] = useState<LoanApplicationDTO[]>([]);
  const [isLoadingApps, setIsLoadingApps] = useState<boolean>(false);

  // Derived calculation
  const simulation = LoanCalculator.simulateLoan({
    principal,
    annualInterestRate: rate,
    tenureMonths: tenure,
  });

  const handlePrincipalChange = (val: number) => {
    setPrincipal(val);
  };

  const handleTenureChange = (val: number) => {
    setTenure(val);
  };

  const handleValidateId = (id: string) => {
    setTestIdCard(id);
    const res = IdCardValidator.validateIdCard(id);
    if (res.isValid) {
      setIdCardResult(`✓ Valid ${res.type}`);
    } else {
      setIdCardResult(`✗ ${res.error || 'Invalid format'}`);
    }
  };

  const loadApplications = useCallback(async () => {
    setIsLoadingApps(true);
    const service = LoanOriginationService.getInstance();
    const list = await service.listApplications();
    setApplications(list);
    setIsLoadingApps(false);
  }, []);

  const handleCreateMockLoan = async () => {
    const service = LoanOriginationService.getInstance();
    await service.createApplication({
      schemeCode: scheme,
      requestedAmount: principal,
      tenureMonths: tenure,
      customerNric: testIdCard,
      customerName: 'Demo Borrower',
      currency: 'USD',
    });
    await loadApplications();
    setDialogVisible(false);
  };

  const handleSaveDraft = async () => {
    await DraftStorage.saveDraft('SHOWCASE_LOAN', {
      principal,
      tenure,
      scheme,
      updated: new Date().toISOString(),
    });
  };

  return {
    state: {
      principal,
      rate,
      tenure,
      monthlyPayment: simulation.monthlyPayment,
      totalInterest: simulation.totalInterest,
      totalPayment: simulation.totalPayment,
      scheme,
      currentStep,
      agreeTerms,
      biometricEnabled,
      activeSegment,
      otpCode,
      dialogVisible,
      testIdCard,
      idCardResult,
      applications,
      isLoadingApps,
    },
    actions: {
      setPrincipal,
      setTenure,
      setRate,
      setScheme,
      setCurrentStep,
      setAgreeTerms,
      setBiometricEnabled,
      setActiveSegment,
      setOtpCode,
      setDialogVisible,
      handleValidateId,
      handleCreateMockLoan,
      handleSaveDraft,
      loadApplications,
    },
  };
};

