import React, { useState, useEffect } from 'react';
import { View, Text, TouchableOpacity, StyleSheet } from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { OtpInput } from '../input/OtpInput';

export interface OtpVerificationWithTimerProps {
  onOtpComplete: (otp: string) => void;
  onResendOtp?: () => void;
  length?: number;
  initialCountdownSeconds?: number;
  phoneNumber?: string;
  testID?: string;
}

/**
 * Enterprise OTP Verification with 3-minute Countdown Timer matching AU-INP-005 / AU-010 from Lotte Digital.
 * Supports auto-countdown, resend lockout, and accessible digits.
 */
export const OtpVerificationWithTimer: React.FC<OtpVerificationWithTimerProps> = ({
  onOtpComplete,
  onResendOtp,
  length = 6,
  initialCountdownSeconds = 180, // 3 minutes standard
  phoneNumber,
  testID = 'otp-timer-verification',
}) => {
  const { theme } = useTheme();
  const [secondsRemaining, setSecondsRemaining] = useState(initialCountdownSeconds);
  const [canResend, setCanResend] = useState(false);

  useEffect(() => {
    if (secondsRemaining <= 0) {
      setCanResend(true);
      return;
    }

    const timer = setInterval(() => {
      setSecondsRemaining((prev) => {
        if (prev <= 1) {
          clearInterval(timer);
          setCanResend(true);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [secondsRemaining]);

  const handleResend = () => {
    if (!canResend) return;
    setSecondsRemaining(initialCountdownSeconds);
    setCanResend(false);
    onResendOtp?.();
  };

  const minutes = Math.floor(secondsRemaining / 60);
  const seconds = secondsRemaining % 60;
  const timerText = `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;

  return (
    <View testID={testID} style={styles.container}>
      {phoneNumber && (
        <Text style={styles.instructionText}>
          Enter the 6-digit verification code sent to <Text style={styles.boldPhone}>{phoneNumber}</Text>
        </Text>
      )}

      {/* 6-box OTP digits */}
      <View style={styles.otpBoxWrapper}>
        <OtpInput length={length} onOtpComplete={onOtpComplete} testID={`${testID}-input`} />
      </View>

      {/* Countdown Timer or Resend Button */}
      <View style={styles.timerRow}>
        {!canResend ? (
          <Text testID={`${testID}-timer`} style={styles.timerNotice}>
            Resend code in <Text style={[styles.timerNumber, { color: theme.colors.primary }]}>{timerText}</Text>
          </Text>
        ) : (
          <TouchableOpacity
            testID={`${testID}-resend-btn`}
            onPress={handleResend}
            activeOpacity={0.7}
            style={styles.resendBtn}
          >
            <Text style={[styles.resendText, { color: theme.colors.primary }]}>Resend OTP Code</Text>
          </TouchableOpacity>
        )}
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    width: '100%',
    alignItems: 'center',
    paddingVertical: 12,
  },
  instructionText: {
    fontSize: 13,
    color: '#4B5563',
    textAlign: 'center',
    marginBottom: 16,
    lineHeight: 18,
  },
  boldPhone: {
    fontWeight: '700',
    color: '#111827',
  },
  otpBoxWrapper: {
    marginBottom: 16,
  },
  timerRow: {
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: 36,
  },
  timerNotice: {
    fontSize: 13,
    color: '#6B7280',
  },
  timerNumber: {
    fontWeight: '700',
  },
  resendBtn: {
    paddingVertical: 6,
    paddingHorizontal: 12,
  },
  resendText: {
    fontSize: 14,
    fontWeight: '700',
    textDecorationLine: 'underline',
  },
});

