import React from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ViewStyle,
  StyleProp,
} from 'react-native';
import { Checkbox, CheckboxVariant } from './Checkbox';

export interface CheckboxOption<T = string> {
  label: string;
  value: T;
  disabled?: boolean;
  subtitle?: string;
}

export interface CheckboxGroupProps<T = string> {
  /** Optional section title or group label */
  title?: string;
  /** Red funnel filter icon or optional custom icon to the left of the title (like Screenshot) */
  showFilterIcon?: boolean;
  /** Clear button 'x' or reset action on the right side of group header */
  onClear?: () => void;
  /** List of selectable options */
  options: CheckboxOption<T>[];
  /** Currently selected values array */
  selectedValues: T[];
  /** Callback fired when selections change */
  onChange: (values: T[]) => void;
  /** Grid columns: 1 (vertical column) or 2 (side-by-side matching screenshot) or 'wrap' */
  columns?: 1 | 2;
  /** Color theme variant */
  variant?: CheckboxVariant;
  /** Size variant */
  size?: 'small' | 'medium' | 'large';
  /** Custom wrapper style */
  style?: StyleProp<ViewStyle>;
  /** Optional testID */
  testID?: string;
}

export const CheckboxGroup = <T extends string | number>({
  title,
  showFilterIcon = false,
  onClear,
  options,
  selectedValues,
  onChange,
  columns = 2,
  variant = 'primary',
  size = 'medium',
  style,
  testID = 'checkbox-group',
}: CheckboxGroupProps<T>) => {
  const handleToggle = (value: T) => {
    const isChecked = selectedValues.includes(value);
    if (isChecked) {
      onChange(selectedValues.filter((v) => v !== value));
    } else {
      onChange([...selectedValues, value]);
    }
  };

  const handleSelectAll = () => {
    const allEnabledValues = options
      .filter((opt) => !opt.disabled)
      .map((opt) => opt.value);
    onChange(allEnabledValues);
  };

  return (
    <View testID={testID} style={[styles.container, style]}>
      {/* Header section with Filter Funnel & Dismiss Clear button */}
      {title ? (
        <View style={styles.headerRow}>
          <View style={styles.titleWithIcon}>
            {showFilterIcon ? (
              <Text testID={`${testID}-filter-icon`} style={styles.filterFunnelIcon}>
                🔻
              </Text>
            ) : null}
            <Text testID={`${testID}-title`} style={styles.groupTitle}>
              {title}
            </Text>
          </View>

          {onClear ? (
            <TouchableOpacity
              testID={`${testID}-clear-btn`}
              style={styles.clearBtn}
              onPress={onClear}
              hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
              accessibilityLabel={`Clear ${title} selection`}
            >
              <Text style={styles.clearBtnText}>✕</Text>
            </TouchableOpacity>
          ) : null}
        </View>
      ) : null}

      {/* Options Layout (1 Column or 2 Columns Grid) */}
      <View
        style={[
          styles.optionsContainer,
          columns === 2 ? styles.twoColumnGrid : styles.singleColumnList,
        ]}
      >
        {options.map((option, index) => {
          const isChecked = selectedValues.includes(option.value);
          return (
            <View
              key={`checkbox-opt-${String(option.value)}-${index}`}
              style={[
                columns === 2 ? styles.gridCol : styles.listRow,
              ]}
            >
              <Checkbox
                label={option.label}
                subtitle={option.subtitle}
                checked={isChecked}
                disabled={option.disabled}
                variant={variant}
                size={size}
                onToggle={() => handleToggle(option.value)}
                testID={`${testID}-option-${index}`}
              />
            </View>
          );
        })}
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    marginVertical: 10,
  },
  headerRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 12,
  },
  titleWithIcon: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  filterFunnelIcon: {
    fontSize: 16,
    color: '#E7252B',
    marginRight: 8,
  },
  groupTitle: {
    fontSize: 17,
    fontWeight: '700',
    color: '#111827',
  },
  clearBtn: {
    width: 22,
    height: 22,
    borderRadius: 11,
    backgroundColor: '#E5E7EB',
    justifyContent: 'center',
    alignItems: 'center',
  },
  clearBtnText: {
    fontSize: 12,
    fontWeight: '700',
    color: '#6B7280',
    lineHeight: 14,
  },
  optionsContainer: {
    width: '100%',
  },
  twoColumnGrid: {
    flexDirection: 'row',
    flexWrap: 'wrap',
  },
  singleColumnList: {
    flexDirection: 'column',
  },
  gridCol: {
    width: '50%',
    paddingRight: 8,
  },
  listRow: {
    width: '100%',
  },
});
