import React from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  StatusBar,
  Platform,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { NativePdfView, AppButton } from '@mfe/ui-components/components';
import {
  useContractViewerViewModel,
  UseContractViewerViewModelProps,
} from '../../viewmodels/useContractViewerViewModel';
import { useBackNavigation } from '@mfe/ui-components/hooks/useBackNavigation';

export interface ContractViewerScreenProps {
  viewModelProps?: UseContractViewerViewModelProps;
  onBack?: () => void;
  onSignComplete?: (contractId: string) => void;
}

/**
 * Enterprise Service Contract Viewer Screen matching exact mobile mockup:
 * - Top back navigation chevron header
 * - Embedded NativePdfView rendering 10-page SERVICE CONTRACT PDF
 * - Floating dark translucent pill badge displaying current page: "01/10"
 * - Multi-page navigation (Next, Previous, First, Last, Zoom)
 * - Read-to-bottom agreement validation before digital signature
 */
export const ContractViewerScreen: React.FC<ContractViewerScreenProps> = ({
  viewModelProps,
  onBack,
  onSignComplete,
}) => {
  const effectiveProps: UseContractViewerViewModelProps = {
    ...viewModelProps,
    onBack: onBack || viewModelProps?.onBack,
    onSignComplete: onSignComplete || viewModelProps?.onSignComplete,
  };

  const {
    pdfRef,
    contract,
    reviewState,
    formattedPageIndicator,
    canSign,
    handlePageChanged,
    handleLastPage,
    handleFirstPage,
    toggleAgreement,
    goToNextPage,
    goToPreviousPage,
    zoomIn,
    zoomOut,
    handleBack,
    handleSign,
  } = useContractViewerViewModel(effectiveProps);

  const { panHandlers } = useBackNavigation({
    onBack: handleBack,
    enabled: true,
  });

  return (
    <SafeAreaView
      testID="contract-viewer-screen"
      style={styles.container}
      edges={['top', 'left', 'right', 'bottom']}
      {...panHandlers}
    >
      <StatusBar barStyle="dark-content" backgroundColor="#FFFFFF" />

      {/* 1. Header Bar matching Screenshot */}
      <View style={styles.header} testID="contract-header">
        <TouchableOpacity
          testID="contract-back-button"
          onPress={handleBack}
          style={styles.backButton}
          activeOpacity={0.7}
          accessibilityRole="button"
          accessibilityLabel="Back"
        >
          <Text style={styles.backChevron}>‹</Text>
        </TouchableOpacity>
        <Text style={styles.headerTitle} testID="contract-header-title">
          {contract.contractTitle}
        </Text>
        <View style={styles.headerSpacer} />
      </View>

      {/* 2. Embedded NativePdfView Document Surface */}
      <View style={styles.pdfContainer} testID="contract-pdf-wrapper">
        <NativePdfView
          ref={pdfRef}
          testID="contract-native-pdf-view"
          base64Data={contract.base64PdfData}
          style={styles.pdfView}
          fitPolicy="width"
          displayDirection="vertical"
          enablePinchZoom={true}
          showsScrollIndicators={true}
          onPageChanged={(e) => {
            const current = e.nativeEvent.currentPage;
            const total = e.nativeEvent.totalPages;
            handlePageChanged(current, total);
          }}
          onLastPage={handleLastPage}
          onFirstPage={handleFirstPage}
        />

        {/* 3. Floating Pill Page Indicator ("01/10") */}
        <View style={styles.floatingPillContainer} pointerEvents="box-none">
          <View style={styles.floatingPill} testID="contract-page-indicator-pill">
            <Text style={styles.floatingPillText} testID="contract-page-indicator-text">
              {formattedPageIndicator}
            </Text>
          </View>
        </View>
      </View>

      {/* 4. Document Controls Toolbar */}
      <View style={styles.controlsBar} testID="contract-controls-bar">
        <TouchableOpacity
          testID="btn-pdf-prev"
          style={[styles.pageNavBtn, reviewState.currentPage <= 1 && styles.btnDisabled]}
          onPress={goToPreviousPage}
          disabled={reviewState.currentPage <= 1}
        >
          <Text style={styles.pageNavBtnText}>‹ Previous</Text>
        </TouchableOpacity>

        <View style={styles.zoomControls}>
          <TouchableOpacity
            testID="btn-pdf-zoom-out"
            style={styles.zoomBtn}
            onPress={zoomOut}
            accessibilityLabel="Zoom Out"
          >
            <Text style={styles.zoomBtnText}>−</Text>
          </TouchableOpacity>
          <Text style={styles.zoomLabel} testID="label-pdf-zoom">
            {Math.round(reviewState.zoomScale * 100)}%
          </Text>
          <TouchableOpacity
            testID="btn-pdf-zoom-in"
            style={styles.zoomBtn}
            onPress={zoomIn}
            accessibilityLabel="Zoom In"
          >
            <Text style={styles.zoomBtnText}>+</Text>
          </TouchableOpacity>
        </View>

        <TouchableOpacity
          testID="btn-pdf-next"
          style={[
            styles.pageNavBtn,
            reviewState.currentPage >= reviewState.totalPages && styles.btnDisabled,
          ]}
          onPress={goToNextPage}
          disabled={reviewState.currentPage >= reviewState.totalPages}
        >
          <Text style={styles.pageNavBtnText}>Next ›</Text>
        </TouchableOpacity>
      </View>

      {/* 5. Bottom Agreement & Signing Action */}
      <View style={styles.footer} testID="contract-footer">
        <TouchableOpacity
          testID="checkbox-agree-contract"
          style={styles.checkboxRow}
          onPress={toggleAgreement}
          activeOpacity={0.8}
        >
          <View
            style={[
              styles.checkboxBox,
              reviewState.hasAgreed && styles.checkboxBoxChecked,
            ]}
          >
            {reviewState.hasAgreed && <Text style={styles.checkmark}>✓</Text>}
          </View>
          <Text style={styles.agreeLabel} testID="label-agree-contract">
            I have reviewed and agree to all terms of this Service Contract.
          </Text>
        </TouchableOpacity>

        <AppButton
          testID="btn-sign-contract"
          title={reviewState.hasReachedLastPage ? 'Sign Service Contract' : 'Scroll to End to Sign'}
          onPress={handleSign}
          disabled={!canSign}
          variant="primary"
          size="lg"
          style={styles.signButton}
        />
      </View>
    </SafeAreaView>
  );
};

