import { useState, useCallback } from 'react';
import { IAuthService, AuthService } from '../services/AuthService';
import { AuthValidator, LoginResult } from '../models/AuthModel';

export interface UseLoginViewModelProps {
  authService?: IAuthService;
  onLoginSuccess?: (result: LoginResult) => void;
  onNavigateToForgotPassword?: () => void;
  onBack?: () => void;
}

export const useLoginViewModel = ({
  authService = new AuthService(),
  onLoginSuccess,
  onNavigateToForgotPassword,
  onBack,
}: UseLoginViewModelProps = {}) => {
  const [companyId, setCompanyId] = useState('');
  const [userId, setUserId] = useState('');
  const [password, setPassword] = useState('');
  const [isPasswordVisible, setIsPasswordVisible] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [fieldErrors, setFieldErrors] = useState<{
    companyId?: string;
    userId?: string;
    password?: string;
  }>({});
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const togglePasswordVisibility = useCallback(() => {
    setIsPasswordVisible((prev) => !prev);
  }, []);

  const handleCompanyIdChange = useCallback((text: string) => {
    setCompanyId(text);
    setFieldErrors((prev) => ({ ...prev, companyId: undefined }));
    setErrorMessage(null);
  }, []);

  const handleUserIdChange = useCallback((text: string) => {
    setUserId(text);
    setFieldErrors((prev) => ({ ...prev, userId: undefined }));
    setErrorMessage(null);
  }, []);

  const handlePasswordChange = useCallback((text: string) => {
    setPassword(text);
    setFieldErrors((prev) => ({ ...prev, password: undefined }));
    setErrorMessage(null);
  }, []);

  const submitLogin = useCallback(async () => {
    setErrorMessage(null);

    // Validate inputs
    const userVal = AuthValidator.validateUserId(userId);
    const passVal = AuthValidator.validatePassword(password);

    if (!userVal.isValid || !passVal.isValid) {
      setFieldErrors({
        userId: userVal.error,
        password: passVal.error,
      });
      return;
    }

    setIsLoading(true);
    try {
      const result = await authService.login({
        companyId: companyId.trim() || undefined,
        userId: userId.trim(),
        password,
      });

      if (!result.success) {
        setErrorMessage(
          result.errorMessage || 'Invalid credentials. Please verify and try again.'
        );
      } else {
        if (onLoginSuccess) {
          onLoginSuccess(result);
        }
      }
    } catch (err: any) {
      setErrorMessage(err?.message || 'A network error occurred. Please try again.');
    } finally {
      setIsLoading(false);
    }
  }, [authService, companyId, userId, password, onLoginSuccess]);

  return {
    companyId,
    userId,
    password,
    isPasswordVisible,
    isLoading,
    fieldErrors,
    errorMessage,
    setCompanyId: handleCompanyIdChange,
    setUserId: handleUserIdChange,
    setPassword: handlePasswordChange,
    togglePasswordVisibility,
    submitLogin,
    onNavigateToForgotPassword,
    onBack,
  };
};
