import React, { useState, useMemo, useRef, useCallback } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  Animated,
  PanResponder,
  Dimensions,
  LayoutChangeEvent,
  Platform,
} from 'react-native';
import Svg, { Path } from 'react-native-svg';
import { useI18n } from '@mfe/core/i18n';
import { useTheme, defaultTheme } from '@mfe/theme';
import { CalendarIcon } from '@mfe/assets/icons/PickerIcons';
import { AppBottomSheet } from '../../modals/AppBottomSheet';
import { AppAlertModal } from '../../modals/AppAlertModal';
import { CALENDAR_LOCALES, CalendarLocale } from './CalendarView';

export type PeriodGranularity = 'month' | 'quarter' | 'semester' | 'year';
export type PeriodSelectionMode = 'single' | 'range';
export type PeriodPresentationMode = 'bottomsheet' | 'alert';

export interface PeriodValue {
  year: number;
  /** 1-12 for month, 1-4 for quarter, 1-2 for semester, undefined for year */
  period?: number;
}

export interface PeriodPickerFieldProps {
  label: string;
  granularity: PeriodGranularity;
  selectionMode?: PeriodSelectionMode;
  presentation?: PeriodPresentationMode;
  locale?: CalendarLocale;
  value?: PeriodValue;
  startValue?: PeriodValue;
  endValue?: PeriodValue;
  placeholder?: string;
  error?: string;
  accentColor?: string;
  onChange?: (val: PeriodValue, displayStr: string) => void;
  onChangeRange?: (start: PeriodValue, end: PeriodValue, displayStr: string) => void;
  testID?: string;
}

const QUARTER_RANGES = ['Jan–Mar', 'Apr–Jun', 'Jul–Sep', 'Oct–Dec'];
const SEMESTER_RANGES = ['Jan–Jun', 'Jul–Dec'];

function toComparable(granularity: PeriodGranularity, v: PeriodValue): number {
  if (granularity === 'year') return v.year;
  const multiplier = granularity === 'month' ? 12 : granularity === 'quarter' ? 4 : 2;
  return v.year * multiplier + ((v.period || 1) - 1);
}

export function formatPeriodValue(
  granularity: PeriodGranularity,
  val: PeriodValue,
  locale: CalendarLocale = 'en'
): string {
  const strings = CALENDAR_LOCALES[locale] || CALENDAR_LOCALES.en;
  if (granularity === 'year') {
    return `${val.year}`;
  }
  if (granularity === 'month') {
    const idx = Math.max(0, Math.min(11, (val.period || 1) - 1));
    return `${strings.months[idx]} ${val.year}`;
  }
  if (granularity === 'quarter') {
    return `Q${val.period || 1} ${val.year}`;
  }
  return `S${val.period || 1} ${val.year}`;
}

export const PeriodPickerField: React.FC<PeriodPickerFieldProps> = ({
  label,
  granularity,
  selectionMode = 'single',
  presentation = 'bottomsheet',
  locale,
  value,
  startValue,
  endValue,
  placeholder,
  error,
  accentColor,
  onChange,
  onChangeRange,
  testID = 'period-picker-field',
}) => {
  const i18n = useI18n();
  const themeContext = useTheme();
  const theme = themeContext?.theme || defaultTheme;
  const primaryFill = accentColor || theme.colors.primary;

  const activeLocale: CalendarLocale =
    locale && CALENDAR_LOCALES[locale]
      ? locale
      : i18n?.language && CALENDAR_LOCALES[i18n.language as CalendarLocale]
      ? (i18n.language as CalendarLocale)
      : 'en';
  const localeStrings = CALENDAR_LOCALES[activeLocale];

  const currentYear = new Date().getFullYear();
  const [visible, setVisible] = useState(false);
  const [viewYear, setViewYear] = useState<number>(
    value?.year || startValue?.year || currentYear
  );
  const [decadeStart, setDecadeStart] = useState<number>(
    Math.floor((value?.year || startValue?.year || currentYear) / 12) * 12
  );

  const [draftStart, setDraftStart] = useState<PeriodValue | null>(
    selectionMode === 'single' ? value || null : startValue || null
  );
  const [draftEnd, setDraftEnd] = useState<PeriodValue | null>(
    selectionMode === 'range' ? endValue || null : null
  );

  const defaultSlideWidth = Math.max((Dimensions.get('window').width || 375) - 48, 260);
  const [slideWidth, setSlideWidth] = useState<number>(defaultSlideWidth);
  const slideWidthRef = useRef<number>(slideWidth);
  slideWidthRef.current = slideWidth;
  const dragX = useRef(new Animated.Value(0)).current;
  const isAnimating = useRef(false);
  const useNative = Platform.OS !== 'web';

  const openModal = () => {
    dragX.stopAnimation();
    dragX.setValue(0);
    isAnimating.current = false;
    const baseYear = value?.year || startValue?.year || currentYear;
    setViewYear(baseYear);
    setDecadeStart(Math.floor(baseYear / 12) * 12);
    setDraftStart(selectionMode === 'single' ? value || null : startValue || null);
    setDraftEnd(selectionMode === 'range' ? endValue || null : null);
    setVisible(true);
  };

  const closeModal = () => {
    dragX.stopAnimation();
    dragX.setValue(0);
    isAnimating.current = false;
    setVisible(false);
  };

  const displayText = useMemo(() => {
    if (selectionMode === 'single') {
      if (value) return formatPeriodValue(granularity, value, activeLocale);
      return placeholder || `Select ${granularity}`;
    }
    if (startValue && endValue) {
      return `${formatPeriodValue(granularity, startValue, activeLocale)} ~ ${formatPeriodValue(granularity, endValue, activeLocale)}`;
    }
    if (startValue) {
      return `${formatPeriodValue(granularity, startValue, activeLocale)} ~ ...`;
    }
    return placeholder || `Select ${granularity} range`;
  }, [selectionMode, value, startValue, endValue, granularity, activeLocale, placeholder]);

  const buildItemsForBase = useCallback(
    (baseYear: number, baseDecade: number) => {
      if (granularity === 'month') {
        return localeStrings.months.map((m, idx) => ({
          key: `${baseYear}-M${idx + 1}`,
          label: m,
          subLabel: undefined as string | undefined,
          val: { year: baseYear, period: idx + 1 } as PeriodValue,
        }));
      }
      if (granularity === 'quarter') {
        return [1, 2, 3, 4].map((q, idx) => ({
          key: `${baseYear}-Q${q}`,
          label: `Q${q}`,
          subLabel: QUARTER_RANGES[idx],
          val: { year: baseYear, period: q } as PeriodValue,
        }));
      }
      if (granularity === 'semester') {
        return [1, 2].map((s, idx) => ({
          key: `${baseYear}-S${s}`,
          label: `S${s}`,
          subLabel: SEMESTER_RANGES[idx],
          val: { year: baseYear, period: s } as PeriodValue,
        }));
      }
      return Array.from({ length: 12 }, (_, idx) => {
        const y = baseDecade + idx;
        return {
          key: `Y${y}`,
          label: `${y}`,
          subLabel: undefined as string | undefined,
          val: { year: y } as PeriodValue,
        };
      });
    },
    [granularity, localeStrings.months]
  );

  const prevItems = useMemo(
    () => buildItemsForBase(viewYear - 1, decadeStart - 12),
    [buildItemsForBase, viewYear, decadeStart]
  );
  const items = useMemo(
    () => buildItemsForBase(viewYear, decadeStart),
    [buildItemsForBase, viewYear, decadeStart]
  );
  const nextItems = useMemo(
    () => buildItemsForBase(viewYear + 1, decadeStart + 12),
    [buildItemsForBase, viewYear, decadeStart]
  );

  const handleSelectItem = (selected: PeriodValue) => {
    if (selectionMode === 'single') {
      setDraftStart(selected);
      const display = formatPeriodValue(granularity, selected, activeLocale);
      onChange?.(selected, display);
      setVisible(false);
      return;
    }

    if (!draftStart || (draftStart && draftEnd)) {
      setDraftStart(selected);
      setDraftEnd(null);
    } else {
      const startNum = toComparable(granularity, draftStart);
      const selNum = toComparable(granularity, selected);
      if (selNum < startNum) {
        setDraftEnd(draftStart);
        setDraftStart(selected);
      } else {
        setDraftEnd(selected);
      }
    }
  };

  const handleConfirmRange = () => {
    if (draftStart) {
      const end = draftEnd || draftStart;
      const display = `${formatPeriodValue(granularity, draftStart, activeLocale)} ~ ${formatPeriodValue(granularity, end, activeLocale)}`;
      onChangeRange?.(draftStart, end, display);
    }
    setVisible(false);
  };

  const slideToPage = useCallback(
    (direction: 'prev' | 'next') => {
      if (isAnimating.current) return;
      isAnimating.current = true;
      const width = slideWidthRef.current;
      const targetX = direction === 'next' ? -width : width;

      Animated.timing(dragX, {
        toValue: targetX,
        duration: 220,
        useNativeDriver: useNative,
      }).start(({ finished }) => {
        if (finished) {
          if (granularity === 'year') {
            setDecadeStart((d) => (direction === 'prev' ? d - 12 : d + 12));
          } else {
            setViewYear((y) => (direction === 'prev' ? y - 1 : y + 1));
          }
          dragX.setValue(0);
        }
        isAnimating.current = false;
      });
    },
    [dragX, granularity]
  );

  const handlePrevNav = useCallback(() => slideToPage('prev'), [slideToPage]);
  const handleNextNav = useCallback(() => slideToPage('next'), [slideToPage]);

  const swipePanResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => false,
      onMoveShouldSetPanResponder: (_, gestureState) =>
        !isAnimating.current &&
        Math.abs(gestureState.dx) > 10 &&
        Math.abs(gestureState.dx) > Math.abs(gestureState.dy),
      onPanResponderMove: (_, gestureState) => {
        if (!isAnimating.current) {
          const maxDrag = slideWidthRef.current;
          dragX.setValue(Math.max(-maxDrag, Math.min(maxDrag, gestureState.dx)));
        }
      },
      onPanResponderTerminationRequest: () => false,
      onPanResponderRelease: (_, gestureState) => {
        const threshold = slideWidthRef.current * 0.2;
        if (gestureState.dx < -threshold || gestureState.vx < -0.35) {
          slideToPage('next');
        } else if (gestureState.dx > threshold || gestureState.vx > 0.35) {
          slideToPage('prev');
        } else {
          Animated.spring(dragX, {
            toValue: 0,
            useNativeDriver: useNative,
            tension: 120,
            friction: 14,
          }).start();
        }
      },
      onPanResponderTerminate: () => {
        Animated.spring(dragX, {
          toValue: 0,
          useNativeDriver: useNative,
          tension: 120,
          friction: 14,
        }).start();
      },
    })
  ).current;

  const handleSwipeLayout = (event: LayoutChangeEvent) => {
    const measured = event.nativeEvent.layout.width;
    if (measured > 0 && measured !== slideWidth) {
      setSlideWidth(measured);
    }
  };

  const headerTitle =
    granularity === 'year'
      ? `${decadeStart} – ${decadeStart + 11}`
      : `${viewYear}`;

  const itemWidth =
    granularity === 'semester'
      ? '48%'
      : granularity === 'quarter'
      ? '48%'
      : '31.5%';

  const renderGridPane = (paneItems: typeof items, isInteractive: boolean) => (
    <View style={[styles.grid, { width: slideWidth }]}>
      {paneItems.map((item) => {
        const itemNum = toComparable(granularity, item.val);
        const startNum = draftStart ? toComparable(granularity, draftStart) : null;
        const endNum = draftEnd ? toComparable(granularity, draftEnd) : null;

        const isStart = startNum !== null && itemNum === startNum;
        const isEnd = endNum !== null && itemNum === endNum;
        const isInRange =
          selectionMode === 'range' &&
          startNum !== null &&
          endNum !== null &&
          itemNum > startNum &&
          itemNum < endNum;

        return (
          <TouchableOpacity
            key={item.key}
            testID={isInteractive ? `${testID}-item-${item.key}` : undefined}
            activeOpacity={0.75}
            disabled={!isInteractive}
            onPress={() => handleSelectItem(item.val)}
            style={[
              styles.cell,
              { width: itemWidth as any },
              isInRange && styles.cellInRange,
              (isStart || isEnd) && [styles.cellSelected, { backgroundColor: primaryFill }],
            ]}
          >
            <Text
              style={[
                styles.cellLabel,
                (isStart || isEnd) && styles.cellLabelSelected,
              ]}
            >
              {item.label}
            </Text>
            {item.subLabel ? (
              <Text
                style={[
                  styles.cellSubLabel,
                  (isStart || isEnd) && styles.cellSubLabelSelected,
                ]}
              >
                {item.subLabel}
              </Text>
            ) : null}
            {selectionMode === 'range' && isStart && (
              <Text style={styles.edgeBadge}>{localeStrings.from}</Text>
            )}
            {selectionMode === 'range' && isEnd && !isStart && (
              <Text style={styles.edgeBadge}>{localeStrings.to}</Text>
            )}
          </TouchableOpacity>
        );
      })}
    </View>
  );

  const pickerContent = (
    <View testID={`${testID}-content`} style={styles.content}>
      {/* Header */}
      <View style={styles.header}>
        <Text testID={`${testID}-header-title`} style={styles.headerTitle}>
          {headerTitle}
        </Text>
        <View style={styles.navGroup}>
          <TouchableOpacity
            testID={`${testID}-prev`}
            style={styles.navBtn}
            activeOpacity={0.7}
            onPress={handlePrevNav}
          >
            <Svg width={16} height={16} viewBox="0 0 24 24" fill="none">
              <Path
                d="M15 19L8 12L15 5"
                stroke="#1E293B"
                strokeWidth={2.4}
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </Svg>
          </TouchableOpacity>
          <TouchableOpacity
            testID={`${testID}-next`}
            style={styles.navBtn}
            activeOpacity={0.7}
            onPress={handleNextNav}
          >
            <Svg width={16} height={16} viewBox="0 0 24 24" fill="none">
              <Path
                d="M9 5L16 12L9 19"
                stroke="#1E293B"
                strokeWidth={2.4}
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </Svg>
          </TouchableOpacity>
        </View>
      </View>

      {/* Swipeable 3-Pane Period Grid */}
      <View
        {...swipePanResponder.panHandlers}
        onLayout={handleSwipeLayout}
        style={styles.swipeContainer}
      >
        <Animated.View
          style={[
            styles.sliderTrack,
            {
              width: slideWidth * 3,
              marginLeft: -slideWidth,
              transform: [{ translateX: dragX }],
            },
          ]}
        >
          {renderGridPane(prevItems, false)}
          {renderGridPane(items, true)}
          {renderGridPane(nextItems, false)}
        </Animated.View>
      </View>

      {/* Footer Actions */}
      <View style={styles.footerRow}>
        <TouchableOpacity
          testID={`${testID}-cancel-btn`}
          style={styles.cancelBtn}
          activeOpacity={0.8}
          onPress={closeModal}
        >
          <Text style={styles.cancelText}>{localeStrings.cancel}</Text>
        </TouchableOpacity>

        {selectionMode === 'range' ? (
          <TouchableOpacity
            testID={`${testID}-confirm-btn`}
            style={[
              styles.confirmBtn,
              { backgroundColor: primaryFill, opacity: draftStart ? 1 : 0.5 },
            ]}
            disabled={!draftStart}
            activeOpacity={0.85}
            onPress={handleConfirmRange}
          >
            <Text style={styles.confirmText}>{localeStrings.confirm}</Text>
          </TouchableOpacity>
        ) : null}
      </View>
    </View>
  );

  return (
    <View testID={testID} style={styles.container}>
      <Text style={styles.label}>{label}</Text>
      <TouchableOpacity
        testID={`${testID}-trigger`}
        style={[styles.inputGroup, error ? styles.inputError : null]}
        activeOpacity={0.75}
        onPress={openModal}
      >
        <Text
          style={[
            styles.valueText,
            !value && !startValue && styles.placeholderText,
          ]}
        >
          {displayText}
        </Text>
        <CalendarIcon size={20} color={primaryFill} />
      </TouchableOpacity>
      {error ? <Text style={styles.errorText}>{error}</Text> : null}

      {presentation === 'bottomsheet' ? (
        <AppBottomSheet
          visible={visible}
          showHeader={false}
          onClose={closeModal}
          testID={`${testID}-bottom-sheet`}
        >
          {pickerContent}
        </AppBottomSheet>
      ) : (
        <AppAlertModal
          visible={visible}
          showHeader={false}
          maxWidth={360}
          onClose={closeModal}
          testID={`${testID}-alert-modal`}
        >
          {pickerContent}
        </AppAlertModal>
      )}
    </View>
  );
};

