import React from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  StyleProp,
  ViewStyle,
} from 'react-native';

export interface DebtorMetricCardProps {
  title: string;
  count: number | string;
  unit?: string;
  icon: React.ReactNode;
  iconBgColor?: string;
  onPress?: () => void;
  style?: StyleProp<ViewStyle>;
  testID?: string;
}

export const DebtorMetricCard: React.FC<DebtorMetricCardProps> = ({
  title,
  count,
  unit = 'People',
  icon,
  iconBgColor = '#F3F4F6',
  onPress,
  style,
  testID = 'debtor-metric-card',
}) => {
  const content = (
    <View style={[styles.card, style]} testID={testID}>
      <View style={styles.topRow}>
        <View style={[styles.iconWrap, { backgroundColor: iconBgColor }]}>
          {icon}
        </View>
        <View style={styles.numberWrap}>
          <Text style={styles.largeNum}>{count}</Text>
          <Text style={styles.unitText}>{unit}</Text>
        </View>
      </View>
      <Text style={styles.titleText}>{title}</Text>
    </View>
  );

  if (onPress) {
    return (
      <TouchableOpacity
        style={styles.touchableWrapper}
        activeOpacity={0.85}
        onPress={onPress}
      >
        {content}
      </TouchableOpacity>
    );
  }

  return <View style={styles.touchableWrapper}>{content}</View>;
};

const styles = StyleSheet.create({
  touchableWrapper: {
    width: '48.5%',
  },
  card: {
    backgroundColor: '#FFFFFF',
    borderRadius: 14,
    padding: 16,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.05,
    shadowRadius: 6,
    elevation: 3,
  },
  topRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 14,
  },
  iconWrap: {
    width: 38,
    height: 38,
    borderRadius: 19,
    alignItems: 'center',
    justifyContent: 'center',
  },
  numberWrap: {
    alignItems: 'flex-end',
  },
  largeNum: {
    fontSize: 24,
    fontWeight: '800',
    color: '#1F2937',
  },
  unitText: {
    fontSize: 11,
    color: '#6B7280',
    marginTop: -2,
  },
  titleText: {
    fontSize: 13,
    color: '#4B5563',
    fontWeight: '600',
  },
});

