import { useRef, useCallback } from 'react';
import {
  PanResponder,
  GestureResponderEvent,
  PanResponderGestureState,
  PanResponderInstance,
} from 'react-native';
import { openDeveloperConsole } from 'react-native-bizmob-plugin';

export interface UseFourFingerDevConsoleOptions {
  /** Optional custom callback override when 4 fingers touch */
  onTrigger?: () => void | Promise<void>;
  /** Disable the gesture detection if needed */
  enabled?: boolean;
}

/**
 * Hook to detect a 4-finger touch/tap anywhere on screen and trigger BizMOB developer console.
 * Uses capturing phase so it catches multi-touch events without blocking child tap interactions.
 */
export function useFourFingerDevConsole(options: UseFourFingerDevConsoleOptions = {}) {
  const { onTrigger, enabled = true } = options;
  const isTriggeringRef = useRef(false);

  const handleTrigger = useCallback(async () => {
    if (isTriggeringRef.current) return;
    isTriggeringRef.current = true;

    try {
      if (onTrigger) {
        await onTrigger();
      } else {
        await openDeveloperConsole();
      }
    } catch (error) {
      console.warn('[useFourFingerDevConsole] Failed to open developer console:', error);
    } finally {
      // Cooldown timer to prevent rapid duplicate calls
      setTimeout(() => {
        isTriggeringRef.current = false;
      }, 1000);
    }
  }, [onTrigger]);

  const panResponder = useRef<PanResponderInstance>(
    PanResponder.create({
      onStartShouldSetPanResponderCapture: (
        evt: GestureResponderEvent,
        _gestureState: PanResponderGestureState
      ) => {
        if (!enabled) return false;
        const touches = evt.nativeEvent.touches || [];
        if (touches.length >= 4) {
          handleTrigger();
        }
        return false;
      },
      onMoveShouldSetPanResponderCapture: (
        evt: GestureResponderEvent,
        _gestureState: PanResponderGestureState
      ) => {
        if (!enabled) return false;
        const touches = evt.nativeEvent.touches || [];
        if (touches.length >= 4) {
          handleTrigger();
        }
        return false;
      },
      onStartShouldSetPanResponder: () => false,
      onMoveShouldSetPanResponder: () => false,
    })
  ).current;

  return {
    panHandlers: panResponder.panHandlers,
    triggerConsole: handleTrigger,
  };
}
