import React, { useState } from 'react';
import { View, Text, Image, TouchableOpacity, StyleSheet } from 'react-native';
import {
  AppCard,
  ImageViewer,
  ImageViewerItem,
} from '@mfe/ui-components/components';
import { CodeBlock } from '../../components/CodeBlock';

const IMAGE_VIEWER_SNIPPET = `import { ImageViewer, ImageViewerItem } from '@mfe/ui-components/components';

const images: ImageViewerItem[] = [
  { id: '1', source: { uri: 'https://...' }, title: 'Collateral Front View', caption: 'Site visit photo' },
  { id: '2', source: { uri: 'https://...' }, title: 'Land Title Document', caption: 'Hard title scan' },
];

<ImageViewer
  visible={viewerOpen}
  images={images}
  initialIndex={selectedIdx}
  onClose={() => setViewerOpen(false)}
/>;`;

const DEMO_IMAGES: ImageViewerItem[] = [
  {
    id: 'img-1',
    source: { uri: 'https://images.unsplash.com/photo-1560518883-ce09059eeffa?w=800' },
    title: 'Collateral Property — Front View',
    caption: 'Tap image or + / − to zoom, swipe left/right to browse.',
  },
  {
    id: 'img-2',
    source: { uri: 'https://images.unsplash.com/photo-1554224155-6726b3ff858f?w=800' },
    title: 'Financial Statement Review',
    caption: 'Verified income & DSCR supporting document.',
  },
  {
    id: 'img-3',
    source: { uri: 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=800' },
    title: 'Commercial Building Valuation',
    caption: 'Phnom Penh CBD — Appraised 2026.',
  },
];

export const ImageViewerDetailSection: React.FC = () => {
  const [viewerVisible, setViewerVisible] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(0);

  const openAt = (idx: number) => {
    setSelectedIndex(idx);
    setViewerVisible(true);
  };

  return (
    <View testID="detail-image-viewer">
      <CodeBlock title="ImageViewer Usage" code={IMAGE_VIEWER_SNIPPET} />

      <AppCard style={styles.card}>
        <Text style={styles.sectionTitle}>Tap Any Thumbnail to Open Viewer</Text>
        <Text style={styles.helperText}>
          Opens over a blurred backdrop with swipe navigation and zoom controls.
        </Text>

        <View style={styles.thumbRow}>
          {DEMO_IMAGES.map((img, idx) => (
            <TouchableOpacity
              key={img.id}
              testID={`demo-image-thumb-${idx}`}
              activeOpacity={0.85}
              onPress={() => openAt(idx)}
              style={styles.thumbCard}
            >
              <Image source={img.source} style={styles.thumbImage} resizeMode="cover" />
              <Text numberOfLines={1} style={styles.thumbTitle}>
                {img.title}
              </Text>
            </TouchableOpacity>
          ))}
        </View>
      </AppCard>

      <ImageViewer
        visible={viewerVisible}
        images={DEMO_IMAGES}
        initialIndex={selectedIndex}
        onClose={() => setViewerVisible(false)}
        testID="demo-image-viewer"
      />
    </View>
  );
};

const styles = StyleSheet.create({
  card: {
    marginBottom: 16,
  },
  sectionTitle: {
    fontSize: 15,
    fontWeight: '700',
    color: '#111827',
    marginBottom: 4,
  },
  helperText: {
    fontSize: 13,
    color: '#4B5563',
    marginBottom: 14,
  },
  thumbRow: {
    flexDirection: 'row',
    gap: 10,
  },
  thumbCard: {
    flex: 1,
    borderRadius: 10,
    overflow: 'hidden',
    borderWidth: 1,
    borderColor: '#E2E8F0',
    backgroundColor: '#FFFFFF',
  },
  thumbImage: {
    width: '100%',
    height: 96,
  },
  thumbTitle: {
    fontSize: 11,
    fontWeight: '600',
    color: '#1E293B',
    padding: 6,
  },
});
