import React from 'react';
import { View, Text, TouchableOpacity, StyleSheet, ViewStyle } from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export interface NumberStepperProps {
  label?: string;
  value: number;
  min?: number;
  max?: number;
  step?: number;
  unit?: string;
  onChangeValue: (nextValue: number) => void;
  disabled?: boolean;
  style?: ViewStyle;
  testID?: string;
}

export const NumberStepper: React.FC<NumberStepperProps> = ({
  label,
  value,
  min = 1,
  max = 100,
  step = 1,
  unit,
  onChangeValue,
  disabled = false,
  style,
  testID = 'number-stepper',
}) => {
  const { theme } = useTheme();

  const canDecrease = !disabled && value > min;
  const canIncrease = !disabled && value < max;

  const handleDecrease = () => {
    if (canDecrease) {
      const next = Math.max(min, value - step);
      onChangeValue(next);
    }
  };

  const handleIncrease = () => {
    if (canIncrease) {
      const next = Math.min(max, value + step);
      onChangeValue(next);
    }
  };

  return (
    <View testID={testID} style={[styles.container, style]}>
      {label ? <Text style={styles.label}>{label}</Text> : null}

      <View
        style={[
          styles.stepperBox,
          {
            borderColor: theme.colors.border,
            borderRadius: theme.radius.md,
            backgroundColor: theme.colors.card,
          },
        ]}
      >
        <TouchableOpacity
          testID={`${testID}-minus`}
          disabled={!canDecrease}
          activeOpacity={0.6}
          onPress={handleDecrease}
          style={[styles.stepBtn, !canDecrease && styles.disabledBtn]}
        >
          <Text style={[styles.btnSymbol, !canDecrease && styles.disabledText]}>
            −
          </Text>
        </TouchableOpacity>

        <View style={styles.valueWrap}>
          <Text testID={`${testID}-value`} style={styles.valueText}>
            {value}
            {unit ? <Text style={styles.unitText}> {unit}</Text> : null}
          </Text>
        </View>

        <TouchableOpacity
          testID={`${testID}-plus`}
          disabled={!canIncrease}
          activeOpacity={0.6}
          onPress={handleIncrease}
          style={[styles.stepBtn, !canIncrease && styles.disabledBtn]}
        >
          <Text style={[styles.btnSymbol, !canIncrease && styles.disabledText]}>
            +
          </Text>
        </TouchableOpacity>
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    marginVertical: 6,
  },
  label: {
    fontSize: 13,
    fontWeight: '600',
    color: '#333333',
    marginBottom: 6,
  },
  stepperBox: {
    flexDirection: 'row',
    alignItems: 'center',
    height: 48,
    borderWidth: 1,
    overflow: 'hidden',
  },
  stepBtn: {
    width: 48,
    height: '100%',
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#F9FAFB',
  },
  disabledBtn: {
    backgroundColor: '#F3F4F6',
    opacity: 0.5,
  },
  btnSymbol: {
    fontSize: 22,
    fontWeight: '600',
    color: '#111827',
  },
  disabledText: {
    color: '#9CA3AF',
  },
  valueWrap: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
  },
  valueText: {
    fontSize: 16,
    fontWeight: '700',
    color: '#111827',
  },
  unitText: {
    fontSize: 13,
    fontWeight: '500',
    color: '#6B7280',
  },
});

