import React, { useState, useRef, useMemo } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  TextInput,
  ScrollView,
  StyleSheet,
  ViewStyle,
  TextStyle,
  Animated,
  Modal,
  TouchableWithoutFeedback,
  LayoutChangeEvent,
  Platform,
} from 'react-native';
import Svg, { Path } from 'react-native-svg';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { SearchIconSvg } from '@mfe/assets/icons/CommonIcons';

export interface DropdownListItem<T = string | number> {
  value: T;
  label: string;
  subtitle?: string;
  icon?: React.ReactNode;
  badge?: number | string;
  disabled?: boolean;
}

export type DropdownMode = 'inline' | 'popover' | 'modal';

export interface DropdownListProps<T = string | number> {
  options: DropdownListItem<T>[];
  value?: T | T[];
  onChange?: (value: T, item: DropdownListItem<T>) => void;
  onMultiChange?: (values: T[], items: DropdownListItem<T>[]) => void;
  multiple?: boolean;
  label?: string;
  placeholder?: string;
  searchable?: boolean;
  searchPlaceholder?: string;
  clearable?: boolean;
  disabled?: boolean;
  error?: string;
  helperText?: string;
  mode?: DropdownMode;
  maxHeight?: number;
  testID?: string;
  style?: ViewStyle;
  triggerStyle?: ViewStyle;
  dropdownStyle?: ViewStyle;
  labelStyle?: TextStyle;
  itemStyle?: ViewStyle;
  textStyle?: TextStyle;
  selectedTextStyle?: TextStyle;
}

export const DropdownList = <T extends string | number = string>({
  options,
  value,
  onChange,
  onMultiChange,
  multiple = false,
  label,
  placeholder = 'Select an option',
  searchable = false,
  searchPlaceholder = 'Search...',
  clearable = false,
  disabled = false,
  error,
  helperText,
  mode = 'inline',
  maxHeight = 240,
  testID = 'dropdown-list',
  style,
  triggerStyle,
  dropdownStyle,
  labelStyle,
  itemStyle,
  textStyle,
  selectedTextStyle,
}: DropdownListProps<T>) => {
  const { theme } = useTheme();

  const [isOpen, setIsOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [triggerLayout, setTriggerLayout] = useState<{
    x: number;
    y: number;
    width: number;
    height: number;
  }>({ x: 0, y: 0, width: 0, height: 0 });

  const triggerRef = useRef<View>(null);
  const rotateAnim = useRef(new Animated.Value(0)).current;

  // Toggle dropdown with rotation animation
  const handleToggle = () => {
    if (disabled) return;

    if (!isOpen && mode === 'popover' && triggerRef.current) {
      triggerRef.current.measureInWindow((x, y, width, height) => {
        setTriggerLayout({ x, y, width, height });
      });
    }

    const nextState = !isOpen;
    setIsOpen(nextState);

    Animated.timing(rotateAnim, {
      toValue: nextState ? 1 : 0,
      duration: 200,
      useNativeDriver: true,
    }).start();

    if (!nextState) {
      setSearchQuery('');
    }
  };

  const handleClose = () => {
    setIsOpen(false);
    setSearchQuery('');
    Animated.timing(rotateAnim, {
      toValue: 0,
      duration: 150,
      useNativeDriver: true,
    }).start();
  };

  // Determine selection
  const isSelected = (val: T): boolean => {
    if (multiple && Array.isArray(value)) {
      return value.includes(val);
    }
    return value === val;
  };

  const handleSelectItem = (item: DropdownListItem<T>) => {
    if (item.disabled) return;

    if (multiple) {
      const currentVals = Array.isArray(value) ? [...value] : [];
      const idx = currentVals.indexOf(item.value);
      let nextVals: T[];
      if (idx > -1) {
        nextVals = currentVals.filter((v) => v !== item.value);
      } else {
        nextVals = [...currentVals, item.value];
      }
      const selectedItems = options.filter((opt) => nextVals.includes(opt.value));
      onMultiChange?.(nextVals, selectedItems);
    } else {
      onChange?.(item.value, item);
      handleClose();
    }
  };

  const handleClear = () => {
    if (multiple) {
      onMultiChange?.([], []);
    } else {
      onChange?.('' as any, {} as any);
    }
  };

  // Filter options
  const filteredOptions = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    if (!q) return options;
    return options.filter(
      (opt) =>
        opt.label.toLowerCase().includes(q) ||
        (opt.subtitle && opt.subtitle.toLowerCase().includes(q))
    );
  }, [options, searchQuery]);

  // Selected item label formatting
  const getDisplayLabel = () => {
    if (multiple && Array.isArray(value)) {
      if (value.length === 0) return placeholder;
      if (value.length === 1) {
        const found = options.find((opt) => opt.value === value[0]);
        return found ? found.label : placeholder;
      }
      return `${value.length} selected`;
    }

    const found = options.find((opt) => opt.value === value);
    return found ? found.label : placeholder;
  };

  const isPlaceholder = multiple
    ? !Array.isArray(value) || value.length === 0
    : value === undefined || value === null || value === '';

  const chevronRotate = rotateAnim.interpolate({
    inputRange: [0, 1],
    outputRange: ['0deg', '180deg'],
  });

  // Render list contents
  const renderListItems = () => (
    <View style={[styles.listCard, dropdownStyle]} testID={`${testID}-menu`}>
      {/* Search Input Filter */}
      {searchable && (
        <View style={styles.searchContainer}>
          <SearchIconSvg size={16} color={theme?.colors?.textSubtle || '#7B8494'} />
          <TextInput
            testID={`${testID}-search-input`}
            style={[
              styles.searchInput,
              { color: theme?.colors?.text || '#16181D' },
            ]}
            placeholder={searchPlaceholder}
            placeholderTextColor={theme?.colors?.textSubtle || '#7B8494'}
            value={searchQuery}
            onChangeText={setSearchQuery}
            autoCorrect={false}
            autoCapitalize="none"
          />
          {searchQuery ? (
            <TouchableOpacity
              onPress={() => setSearchQuery('')}
              hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
            >
              <Text style={styles.clearSearchIcon}>✕</Text>
            </TouchableOpacity>
          ) : null}
        </View>
      )}

      {/* Options Scroll */}
      <ScrollView
        style={{ maxHeight }}
        keyboardShouldPersistTaps="handled"
        nestedScrollEnabled
      >
        {filteredOptions.length === 0 ? (
          <View style={styles.emptyContainer} testID={`${testID}-empty`}>
            <Text style={styles.emptyText}>No results found</Text>
          </View>
        ) : (
          filteredOptions.map((opt) => {
            const selected = isSelected(opt.value);
            return (
              <TouchableOpacity
                key={`dropdown-opt-${opt.value}`}
                testID={`${testID}-item-${opt.value}`}
                accessibilityRole="button"
                accessibilityState={{ selected, disabled: opt.disabled }}
                activeOpacity={0.7}
                disabled={opt.disabled}
                onPress={() => handleSelectItem(opt)}
                style={[
                  styles.optionRow,
                  selected && styles.optionRowSelected,
                  opt.disabled && styles.optionRowDisabled,
                  itemStyle,
                ]}
              >
                {/* Optional Icon */}
                {opt.icon && <View style={styles.optionIconWrap}>{opt.icon}</View>}

                {/* Text Content */}
                <View style={styles.optionContent}>
                  <Text
                    style={[
                      styles.optionLabel,
                      {
                        color: selected
                          ? theme?.colors?.primary || '#E7252B'
                          : theme?.colors?.text || '#16181D',
                        fontFamily: selected
                          ? theme?.typography?.fontFamilyBold || 'Pretendard-Bold'
                          : theme?.typography?.fontFamily || 'Pretendard',
                      },
                      textStyle,
                      selected && selectedTextStyle,
                    ]}
                  >
                    {opt.label}
                  </Text>
                  {opt.subtitle ? (
                    <Text style={styles.optionSubtitle}>{opt.subtitle}</Text>
                  ) : null}
                </View>

                {/* Badge if present */}
                {opt.badge !== undefined && (
                  <View style={styles.optionBadge}>
                    <Text style={styles.optionBadgeText}>{opt.badge}</Text>
                  </View>
                )}

                {/* Checkmark or Checkbox Indicator */}
                {selected && (
                  <View testID={`${testID}-checkmark-${opt.value}`} style={styles.checkmarkWrap}>
                    <Text style={[styles.checkmarkText, { color: theme?.colors?.primary || '#E7252B' }]}>
                      ✓
                    </Text>
                  </View>
                )}
              </TouchableOpacity>
            );
          })
        )}
      </ScrollView>
    </View>
  );

  return (
    <View style={[styles.wrapper, style]} testID={testID}>
      {/* Optional Form Field Label */}
      {label && (
        <Text
          style={[
            styles.label,
            { color: theme?.colors?.text || '#16181D' },
            labelStyle,
          ]}
          testID={`${testID}-label`}
        >
          {label}
        </Text>
      )}

      {/* Dropdown Input Trigger Box */}
      <View ref={triggerRef} collapsable={false}>
        <TouchableOpacity
          testID={`${testID}-trigger`}
          accessibilityRole="combobox"
          accessibilityState={{ expanded: isOpen, disabled }}
          activeOpacity={0.8}
          disabled={disabled}
          onPress={handleToggle}
          style={[
            styles.triggerBox,
            {
              borderColor: error
                ? theme?.colors?.error || '#E7252B'
                : isOpen
                ? theme?.colors?.primary || '#E7252B'
                : theme?.colors?.border || '#E2E5EB',
              backgroundColor: disabled
                ? theme?.colors?.background || '#F4F5F7'
                : theme?.colors?.card || '#FFFFFF',
            },
            triggerStyle,
          ]}
        >
          <Text
            numberOfLines={1}
            style={[
              styles.triggerText,
              {
                color: isPlaceholder
                  ? theme?.colors?.textSubtle || '#7B8494'
                  : theme?.colors?.text || '#16181D',
              },
            ]}
          >
            {getDisplayLabel()}
          </Text>

          <View style={styles.triggerRightActions}>
            {/* Optional Clear Button */}
            {clearable && !isPlaceholder && !disabled && (
              <TouchableOpacity
                onPress={handleClear}
                testID={`${testID}-clear`}
                hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }}
                style={styles.clearBtn}
              >
                <Text style={styles.clearText}>✕</Text>
              </TouchableOpacity>
            )}

            {/* Animated Chevron Arrow */}
            <Animated.View style={{ transform: [{ rotate: chevronRotate }] }}>
              <Svg width={18} height={18} viewBox="0 0 24 24" fill="none">
                <Path
                  d="M6 9l6 6 6-6"
                  stroke={theme?.colors?.textSubtle || '#7B8494'}
                  strokeWidth={2}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </Svg>
            </Animated.View>
          </View>
        </TouchableOpacity>
      </View>

      {/* Error or Helper Text */}
      {error ? (
        <Text testID={`${testID}-error`} style={styles.errorText}>
          {error}
        </Text>
      ) : helperText ? (
        <Text style={styles.helperText}>{helperText}</Text>
      ) : null}

      {/* Render based on mode */}
      {isOpen && mode === 'inline' && (
        <View style={styles.inlineMenuWrapper}>{renderListItems()}</View>
      )}

      {isOpen && (mode === 'popover' || mode === 'modal') && (
        <Modal
          visible={isOpen}
          transparent
          animationType="fade"
          onRequestClose={handleClose}
        >
          <TouchableWithoutFeedback onPress={handleClose}>
            <View style={styles.modalBackdrop}>
              <TouchableWithoutFeedback>
                <View
                  style={[
                    mode === 'popover'
                      ? {
                          position: 'absolute',
                          top: triggerLayout.y + triggerLayout.height + 4,
                          left: triggerLayout.x,
                          width: triggerLayout.width,
                        }
                      : styles.centeredModalBox,
                  ]}
                >
                  {renderListItems()}
                </View>
              </TouchableWithoutFeedback>
            </View>
          </TouchableWithoutFeedback>
        </Modal>
      )}
    </View>
  );
};

