import React from 'react';
import { View, Text, StyleSheet, ViewStyle, TouchableOpacity } from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export type TimelineStepStatus = 'completed' | 'active' | 'pending' | 'rejected';
export type TimelineVariant = 'default' | 'stepper-badge' | 'compact-dot' | 'horizontal';

export interface TimelineEventItem {
  id: string;
  stepNumber?: number | string;
  title: string;
  description?: string;
  date?: string;
  status?: TimelineStepStatus;
  note?: string;
  badge?: string;
  onPress?: () => void;
}

export interface AppTimelineProps {
  /**
   * Presentation variant:
   * - 'stepper-badge': Circular numeric badge with "STEP N" (Screenshot Credit Card Issuance Guide style)
   * - 'default': Status-colored circles with checks, active dots, and failure marks
   * - 'compact-dot': Minimalist small dots for activity logs and history
   * - 'horizontal': Step journey bar across the horizontal axis
   */
  variant?: TimelineVariant;
  events: TimelineEventItem[];
  title?: string;
  accentColor?: string;
  style?: ViewStyle;
  testID?: string;
}

/**
 * Universal enterprise Timeline component supporting multiple visual variants:
 * 1. Stepper Badge: Numbered step circles (STEP 1, STEP 2...) matching Lotte Card Issuance Guide.
 * 2. Default: Status-based icon/colored circles (completed ✓, active dot, pending, rejected ✕).
 * 3. Compact Dot: Clean timestamp activity feed for audit logs and event tracking.
 * 4. Horizontal: Step-by-step progress bar across horizontal layout.
 */
export const AppTimeline: React.FC<AppTimelineProps> = ({
  variant = 'default',
  events,
  title,
  accentColor,
  style,
  testID = 'app-timeline',
}) => {
  const { theme } = useTheme();
  const primaryColor = accentColor || theme.colors.primary || '#E7252B';

  const getStatusColor = (status: TimelineStepStatus = 'pending') => {
    switch (status) {
      case 'completed':
        return theme.colors.success || '#117A4D';
      case 'active':
        return primaryColor;
      case 'rejected':
        return theme.colors.error || '#DC2626';
      default:
        return '#E5E7EB';
    }
  };

  // ----------------------------------------------------
  // VARIANT 1: STEPPER BADGE (Screenshot Style)
  // ----------------------------------------------------
  if (variant === 'stepper-badge') {
    return (
      <View testID={testID} style={[styles.container, style]}>
        {title ? (
          <View style={styles.headerWrap}>
            <Text style={[styles.headerTitle, { color: theme.colors.text }]}>
              {title}
            </Text>
            <View style={[styles.redAccentLine, { backgroundColor: primaryColor }]} />
          </View>
        ) : null}

        {events.map((event, index) => {
          const isLast = index === events.length - 1;
          const stepNum = event.stepNumber ?? index + 1;
          const isCurrentActive = event.status === 'active';

          return (
            <TouchableOpacity
              key={event.id}
              testID={`${testID}-step-${event.id}`}
              activeOpacity={event.onPress ? 0.7 : 1}
              onPress={event.onPress}
              disabled={!event.onPress}
              style={styles.stepBadgeRow}
            >
              {/* Left Column: STEP Circle & Line */}
              <View style={styles.badgeLeftCol}>
                <View
                  style={[
                    styles.stepperBadgeCircle,
                    isCurrentActive
                      ? { backgroundColor: '#F3F4F6', borderColor: primaryColor, borderWidth: 2 }
                      : { backgroundColor: '#E5E7EB' },
                  ]}
                  testID={`${testID}-badge-${event.id}`}
                >
                  <Text style={styles.badgeStepLabel}>STEP</Text>
                  <Text
                    style={[
                      styles.badgeStepNumber,
                      isCurrentActive && { color: primaryColor, fontWeight: '800' },
                    ]}
                  >
                    {stepNum}
                  </Text>
                </View>

                {!isLast && <View style={styles.badgeConnectorLine} />}
              </View>

              {/* Right Column: Title & Description */}
              <View style={[styles.badgeRightContent, !isLast && styles.contentSpacing]}>
                <Text
                  testID={`${testID}-title-${event.id}`}
                  style={[
                    styles.badgeEventTitle,
                    { color: theme.colors.text },
                    isCurrentActive && { color: primaryColor },
                  ]}
                >
                  {event.title}
                </Text>

                {event.description ? (
                  <Text style={[styles.badgeEventDesc, { color: theme.colors.textMuted }]}>
                    {event.description}
                  </Text>
                ) : null}

                {event.date ? (
                  <Text style={styles.eventDateText}>{event.date}</Text>
                ) : null}
              </View>
            </TouchableOpacity>
          );
        })}
      </View>
    );
  }

  // ----------------------------------------------------
  // VARIANT 2: COMPACT DOT (Activity & Audit Log Style)
  // ----------------------------------------------------
  if (variant === 'compact-dot') {
    return (
      <View testID={testID} style={[styles.container, style]}>
        {events.map((event, index) => {
          const isLast = index === events.length - 1;
          const status = event.status || 'pending';
          const color = getStatusColor(status);

          return (
            <View
              key={event.id}
              testID={`${testID}-step-${event.id}`}
              style={styles.compactRow}
            >
              <View style={styles.compactLeftCol}>
                <View style={[styles.compactDot, { backgroundColor: color }]} />
                {!isLast && <View style={styles.compactConnector} />}
              </View>

              <View style={[styles.compactRightContent, !isLast && { paddingBottom: 16 }]}>
                <View style={styles.compactTitleRow}>
                  <Text style={[styles.compactTitle, { color: theme.colors.text }]}>
                    {event.title}
                  </Text>
                  {event.date ? (
                    <Text style={styles.compactDate}>{event.date}</Text>
                  ) : null}
                </View>
                {event.description ? (
                  <Text style={[styles.compactDesc, { color: theme.colors.textMuted }]}>
                    {event.description}
                  </Text>
                ) : null}
              </View>
            </View>
          );
        })}
      </View>
    );
  }

  // ----------------------------------------------------
  // VARIANT 3: HORIZONTAL STEP PROGRESS (Process Bar Style)
  // ----------------------------------------------------
  if (variant === 'horizontal') {
    return (
      <View testID={testID} style={[styles.horizontalContainer, style]}>
        <View style={styles.horizontalTrack}>
          {events.map((event, index) => {
            const isLast = index === events.length - 1;
            const status = event.status || 'pending';
            const color = getStatusColor(status);
            const isCompleted = status === 'completed';
            const isActive = status === 'active';

            return (
              <React.Fragment key={event.id}>
                {/* Step Node */}
                <View style={styles.horizontalNodeWrap}>
                  <View
                    style={[
                      styles.horizontalNode,
                      {
                        borderColor: color,
                        backgroundColor: isCompleted ? color : '#FFFFFF',
                      },
                    ]}
                  >
                    {isCompleted ? (
                      <Text style={styles.whiteCheckMark}>✓</Text>
                    ) : (
                      <Text
                        style={[
                          styles.horizontalStepNum,
                          { color: isActive ? primaryColor : '#9CA3AF' },
                        ]}
                      >
                        {index + 1}
                      </Text>
                    )}
                  </View>
                  <Text
                    numberOfLines={1}
                    style={[
                      styles.horizontalLabel,
                      { color: isActive ? primaryColor : '#4B5563' },
                      isActive && { fontWeight: '700' },
                    ]}
                  >
                    {event.title}
                  </Text>
                </View>

                {/* Connecting Line */}
                {!isLast && (
                  <View
                    style={[
                      styles.horizontalLine,
                      { backgroundColor: isCompleted ? color : '#E5E7EB' },
                    ]}
                  />
                )}
              </React.Fragment>
            );
          })}
        </View>
      </View>
    );
  }

  // ----------------------------------------------------
  // VARIANT 4: DEFAULT (Loan Origination Journey)
  // ----------------------------------------------------
  return (
    <View testID={testID} style={[styles.container, style]}>
      {events.map((event, index) => {
        const isLast = index === events.length - 1;
        const status = event.status || 'pending';
        const color = getStatusColor(status);

        return (
          <View
            key={event.id}
            testID={`${testID}-step-${event.id}`}
            style={styles.defaultRow}
          >
            {/* Left Node & Connector */}
            <View style={styles.defaultLeftCol}>
              <View
                style={[
                  styles.defaultCircle,
                  {
                    borderColor: color,
                    backgroundColor:
                      status === 'completed' || status === 'rejected'
                        ? color
                        : '#FFFFFF',
                  },
                ]}
              >
                {status === 'completed' && <Text style={styles.defaultCheck}>✓</Text>}
                {status === 'active' && (
                  <View style={[styles.defaultActiveDot, { backgroundColor: primaryColor }]} />
                )}
                {status === 'rejected' && <Text style={styles.defaultCheck}>✕</Text>}
              </View>

              {!isLast && (
                <View
                  style={[
                    styles.defaultConnector,
                    { backgroundColor: status === 'completed' ? color : '#E5E7EB' },
                  ]}
                />
              )}
            </View>

            {/* Right Content */}
            <View style={[styles.defaultRightContent, !isLast && styles.contentSpacing]}>
              <View style={styles.titleRow}>
                <Text
                  testID={`${testID}-title-${event.id}`}
                  style={[
                    styles.eventTitle,
                    status === 'active' && {
                      color: primaryColor,
                      fontWeight: '700',
                    },
                  ]}
                >
                  {event.title}
                </Text>
                {event.date ? (
                  <Text style={styles.eventDate}>{event.date}</Text>
                ) : null}
              </View>

              {event.description ? (
                <Text style={styles.eventDesc}>{event.description}</Text>
              ) : null}

              {event.note ? (
                <View style={styles.noteBox}>
                  <Text style={styles.noteText}>{event.note}</Text>
                </View>
              ) : null}
            </View>
          </View>
        );
      })}
    </View>
  );
};

