import React from 'react';
import { TouchableOpacity, View, Text, StyleSheet } from 'react-native';

export interface RadioOption<T = string | number> {
  label: string;
  value: T;
  subtitle?: string;
}

export interface RadioGroupProps<T = string | number> {
  label?: string;
  options: RadioOption<T>[];
  selectedValue: T;
  onSelect: (value: T) => void;
  layout?: 'row' | 'column';
  testID?: string;
}

export const RadioGroup = <T extends string | number>({
  label,
  options,
  selectedValue,
  onSelect,
  layout = 'column',
  testID = 'radio-group',
}: RadioGroupProps<T>) => {
  return (
    <View testID={testID} style={styles.container}>
      {label ? <Text style={styles.groupLabel}>{label}</Text> : null}
      <View
        style={[
          styles.optionsContainer,
          layout === 'row' ? styles.rowLayout : styles.columnLayout,
        ]}
      >
        {options.map((option, index) => {
          const isSelected = option.value === selectedValue;
          return (
            <TouchableOpacity
              key={`radio-${index}`}
              testID={`${testID}-option-${index}`}
              style={[
                styles.optionItem,
                isSelected ? styles.optionItemSelected : null,
              ]}
              onPress={() => onSelect(option.value)}
              activeOpacity={0.7}
            >
              <View
                style={[
                  styles.outerCircle,
                  isSelected ? styles.outerCircleSelected : null,
                ]}
              >
                {isSelected ? <View style={styles.innerDot} /> : null}
              </View>
              <View style={styles.textContainer}>
                <Text
                  style={[
                    styles.optionLabel,
                    isSelected ? styles.optionLabelSelected : null,
                  ]}
                >
                  {option.label}
                </Text>
                {option.subtitle ? (
                  <Text style={styles.optionSubtitle}>{option.subtitle}</Text>
                ) : null}
              </View>
            </TouchableOpacity>
          );
        })}
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    marginVertical: 8,
  },
  groupLabel: {
    fontSize: 13,
    fontWeight: '600',
    color: '#4D5563',
    marginBottom: 8,
  },
  optionsContainer: {
    gap: 8,
  },
  rowLayout: {
    flexDirection: 'row',
    flexWrap: 'wrap',
  },
  columnLayout: {
    flexDirection: 'column',
  },
  optionItem: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 10,
    paddingHorizontal: 12,
    borderWidth: 1,
    borderColor: '#E2E5EB',
    borderRadius: 8,
    backgroundColor: '#FFFFFF',
  },
  optionItemSelected: {
    borderColor: '#E7252B',
    backgroundColor: '#FDECEB',
  },
  outerCircle: {
    width: 20,
    height: 20,
    borderRadius: 10,
    borderWidth: 2,
    borderColor: '#7B8494',
    justifyContent: 'center',
    alignItems: 'center',
    marginRight: 10,
  },
  outerCircleSelected: {
    borderColor: '#E7252B',
  },
  innerDot: {
    width: 10,
    height: 10,
    borderRadius: 5,
    backgroundColor: '#E7252B',
  },
  textContainer: {
    flex: 1,
  },
  optionLabel: {
    fontSize: 14,
    fontWeight: '500',
    color: '#16181D',
  },
  optionLabelSelected: {
    fontWeight: '700',
    color: '#E7252B',
  },
  optionSubtitle: {
    fontSize: 12,
    color: '#7B8494',
    marginTop: 2,
  },
});

