import { LoanCalculator } from '@mfe/core/utils/loanCalculator';
import {
  LoanApplicationDTO,
  CreateLoanApplicationRequest,
} from '../models/LoanApplicationDTO';
import { loanJourneyTracker, LoanJourneyStage } from '@mfe/core/analytics/LoanJourneyTracker';
import {
  defaultNetworkService,
  INetworkService,
  TR_CODES,
} from '@mfe/core';

export interface ILoanOriginationService {
  createApplication(
    req: CreateLoanApplicationRequest,
    useMock?: boolean
  ): Promise<LoanApplicationDTO>;
  getApplicationById(id: string, useMock?: boolean): Promise<LoanApplicationDTO | null>;
  listApplications(useMock?: boolean): Promise<LoanApplicationDTO[]>;
  updateApplicationStatus(
    id: string,
    status: 'APPROVED' | 'REJECTED' | 'DISBURSED',
    useMock?: boolean
  ): Promise<LoanApplicationDTO | null>;
}

export class LoanOriginationService implements ILoanOriginationService {
  private static instance: LoanOriginationService;
  private mockStore: Map<string, LoanApplicationDTO> = new Map();
  private networkService: INetworkService;
  private useMock: boolean;

  constructor(
    networkService: INetworkService = defaultNetworkService,
    useMock: boolean = true
  ) {
    this.networkService = networkService;
    this.useMock = useMock;
    // Seed an initial demo loan
    this.createApplication({
      schemeCode: 'CASH',
      requestedAmount: 5000,
      tenureMonths: 12,
      customerNric: '012345678901',
      customerName: 'Sokha Chan',
      currency: 'USD',
    });
  }

  public static getInstance(): LoanOriginationService {
    if (!LoanOriginationService.instance) {
      LoanOriginationService.instance = new LoanOriginationService();
    }
    return LoanOriginationService.instance;
  }

  async createApplication(
    req: CreateLoanApplicationRequest,
    useMock: boolean = this.useMock
  ): Promise<LoanApplicationDTO> {
    await this.networkService.request({
      trCode: TR_CODES.LOAN_APPLICATION_CREATE,
      payload: req,
      useMock,
    });

    const appId = `APL-${Date.now().toString().slice(-6)}`;
    const interestRate = req.schemeCode === 'CASH' ? 12 : 9.5;
    const monthly = LoanCalculator.calculatePMT(
      req.requestedAmount,
      interestRate,
      req.tenureMonths
    );

    const record: LoanApplicationDTO = {
      applicationId: appId,
      schemeCode: req.schemeCode,
      productName:
        req.schemeCode === 'CASH'
          ? 'Fast Cash Loan'
          : req.schemeCode === 'CAR'
          ? 'Auto Finance Loan'
          : 'Durable Retail Loan',
      requestedAmount: req.requestedAmount,
      tenureMonths: req.tenureMonths,
      interestRate,
      monthlyPayment: monthly,
      currency: req.currency,
      status: 'SUBMITTED',
      customerNric: req.customerNric,
      customerName: req.customerName,
      createdAt: new Date().toISOString(),
    };

    this.mockStore.set(appId, record);

    // Track full loan submission parity across AppsFlyer & CMP
    await loanJourneyTracker.trackApplicationSubmitted({
      applicationId: appId,
      schemeCode: req.schemeCode,
      productName: record.productName,
      amount: req.requestedAmount,
      tenureMonths: req.tenureMonths,
      currency: req.currency,
      customerNric: req.customerNric,
    });

    return record;
  }

  async updateApplicationStatus(
    id: string,
    status: 'APPROVED' | 'REJECTED' | 'DISBURSED',
    useMock: boolean = this.useMock
  ): Promise<LoanApplicationDTO | null> {
    const existing = this.mockStore.get(id);
    if (!existing) return null;

    await this.networkService.request({
      trCode: TR_CODES.LOAN_APPLICATION_STATUS_UPDATE,
      payload: { id, status },
      useMock,
    });

    const updated: LoanApplicationDTO = {
      ...existing,
      status,
    };
    this.mockStore.set(id, updated);

    if (status === 'APPROVED') {
      await loanJourneyTracker.trackJourneyStage(LoanJourneyStage.UNDERWRITING_APPROVED, {
        applicationId: id,
        schemeCode: updated.schemeCode,
        amount: updated.requestedAmount,
        tenureMonths: updated.tenureMonths,
        currency: updated.currency,
      });
    } else if (status === 'REJECTED') {
      await loanJourneyTracker.trackJourneyStage(LoanJourneyStage.UNDERWRITING_REJECTED, {
        applicationId: id,
        schemeCode: updated.schemeCode,
        amount: updated.requestedAmount,
        tenureMonths: updated.tenureMonths,
        currency: updated.currency,
      });
    } else if (status === 'DISBURSED') {
      await loanJourneyTracker.trackDisbursement({
        applicationId: id,
        schemeCode: updated.schemeCode,
        amount: updated.requestedAmount,
        tenureMonths: updated.tenureMonths,
        currency: updated.currency,
      });
    }

    return updated;
  }

  async getApplicationById(
    id: string,
    useMock: boolean = this.useMock
  ): Promise<LoanApplicationDTO | null> {
    if (this.mockStore.has(id)) {
      return this.mockStore.get(id) || null;
    }

    const res = await this.networkService.request<{ items?: LoanApplicationDTO[] }>({
      trCode: TR_CODES.LOAN_APPLICATION_LIST,
      payload: { id },
      useMock,
    });

    const items = res.body?.items || [];
    return items.find((a) => a.applicationId === id) || null;
  }

  async listApplications(useMock: boolean = this.useMock): Promise<LoanApplicationDTO[]> {
    const res = await this.networkService.request<{ items?: LoanApplicationDTO[] }>({
      trCode: TR_CODES.LOAN_APPLICATION_LIST,
      useMock,
    });

    if (this.mockStore.size > 0) {
      return Array.from(this.mockStore.values());
    }

    return res.body?.items || [];
  }
}
