import React, { useRef, useEffect } from 'react';
import {
  Modal,
  View,
  Text,
  TouchableOpacity,
  TouchableWithoutFeedback,
  StyleSheet,
  Animated,
  Dimensions,
  ScrollView,
  Platform,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { CircleProfileAvatar } from '../avatar/CircleProfileAvatar';

export interface DrawerMenuItem {
  key: string;
  label: string;
  icon?: (color: string) => React.ReactNode;
  badge?: string;
  onPress: () => void;
  dividerAfter?: boolean;
}

export interface MenuDrawerProps {
  visible: boolean;
  onClose: () => void;
  userName?: string;
  userRole?: string;
  userAvatar?: string;
  menuItems: DrawerMenuItem[];
  appVersion?: string;
  onProfilePress?: () => void;
  testID?: string;
}

export const MenuDrawer: React.FC<MenuDrawerProps> = ({
  visible,
  onClose,
  userName = 'Nguyễn Văn An',
  userRole = 'Verified Borrower',
  userAvatar,
  menuItems,
  appVersion = 'v1.4.0 (Build 2026)',
  onProfilePress,
  testID = 'menu-drawer',
}) => {
  const { theme } = useTheme();
  const screenWidth = Dimensions.get('window').width;
  const drawerWidth = Math.min(320, screenWidth * 0.82);

  const translateX = useRef(new Animated.Value(-drawerWidth)).current;

  useEffect(() => {
    if (visible) {
      Animated.spring(translateX, {
        toValue: 0,
        useNativeDriver: true,
        bounciness: 2,
        speed: 14,
      }).start();
    } else {
      translateX.setValue(-drawerWidth);
    }
  }, [visible, drawerWidth, translateX]);

  const dismissDrawer = () => {
    Animated.timing(translateX, {
      toValue: -drawerWidth,
      duration: 180,
      useNativeDriver: true,
    }).start(() => {
      onClose();
    });

    if (typeof process !== 'undefined' && process.env?.NODE_ENV === 'test') {
      onClose();
    }
  };

  return (
    <Modal
      transparent
      animationType="none"
      visible={visible}
      onRequestClose={dismissDrawer}
    >
      <TouchableWithoutFeedback onPress={dismissDrawer} testID={`${testID}-backdrop`}>
        <View style={styles.backdrop}>
          <TouchableWithoutFeedback onPress={(e) => e.stopPropagation()}>
            <Animated.View
              testID={`${testID}-content`}
              style={[
                styles.drawerCard,
                {
                  width: drawerWidth,
                  backgroundColor: theme.colors.card,
                  transform: [{ translateX }],
                },
              ]}
            >
              {/* Drawer User Header */}
              <TouchableOpacity
                testID={`${testID}-profile-header`}
                style={[
                  styles.profileHeader,
                  { backgroundColor: theme.colors.primaryLight },
                ]}
                activeOpacity={0.8}
                onPress={onProfilePress || dismissDrawer}
              >
                <CircleProfileAvatar
                  name={userName}
                  source={userAvatar}
                  size={54}
                />
                <View style={styles.userInfo}>
                  <Text
                    testID={`${testID}-user-name`}
                    style={[
                      styles.userName,
                      { color: theme.colors.text, fontFamily: theme.typography.fontFamilyBold },
                    ]}
                    numberOfLines={1}
                  >
                    {userName}
                  </Text>
                  <Text style={styles.userRole} numberOfLines={1}>
                    {userRole}
                  </Text>
                </View>
              </TouchableOpacity>

              {/* Menu Items List */}
              <ScrollView style={styles.menuList} showsVerticalScrollIndicator={false}>
                {menuItems.map((item) => (
                  <React.Fragment key={item.key}>
                    <TouchableOpacity
                      testID={`${testID}-item-${item.key}`}
                      style={styles.menuRow}
                      activeOpacity={0.7}
                      onPress={() => {
                        dismissDrawer();
                        item.onPress();
                      }}
                    >
                      {item.icon ? (
                        <View style={styles.itemIconWrap}>
                          {item.icon(theme.colors.primary)}
                        </View>
                      ) : null}

                      <Text
                        style={[
                          styles.itemLabel,
                          { color: theme.colors.text },
                        ]}
                      >
                        {item.label}
                      </Text>

                      {item.badge ? (
                        <View
                          style={[
                            styles.badge,
                            { backgroundColor: theme.colors.primary },
                          ]}
                        >
                          <Text style={styles.badgeText}>{item.badge}</Text>
                        </View>
                      ) : null}
                    </TouchableOpacity>

                    {item.dividerAfter ? <View style={styles.divider} /> : null}
                  </React.Fragment>
                ))}
              </ScrollView>

              {/* Footer */}
              <View style={styles.footer}>
                <Text style={styles.versionText}>{appVersion}</Text>
              </View>
            </Animated.View>
          </TouchableWithoutFeedback>
        </View>
      </TouchableWithoutFeedback>
    </Modal>
  );
};

const styles = StyleSheet.create({
  backdrop: {
    flex: 1,
    backgroundColor: 'rgba(15, 23, 42, 0.5)',
  },
  drawerCard: {
    height: '100%',
    shadowColor: '#000',
    shadowOffset: { width: 4, height: 0 },
    shadowOpacity: 0.18,
    shadowRadius: 16,
    elevation: 16,
  },
  profileHeader: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 16,
    paddingTop: Platform.OS === 'ios' ? 48 : 28,
    paddingBottom: 20,
  },
  userInfo: {
    marginLeft: 14,
    flex: 1,
  },
  userName: {
    fontSize: 16,
    fontWeight: '700',
  },
  userRole: {
    fontSize: 12,
    color: '#6B7280',
    marginTop: 2,
  },
  menuList: {
    flex: 1,
    paddingVertical: 10,
  },
  menuRow: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 14,
    paddingHorizontal: 18,
  },
  itemIconWrap: {
    marginRight: 14,
    width: 24,
    alignItems: 'center',
  },
  itemLabel: {
    fontSize: 14,
    fontWeight: '500',
    flex: 1,
  },
  badge: {
    paddingHorizontal: 8,
    paddingVertical: 2,
    borderRadius: 10,
  },
  badgeText: {
    color: '#FFFFFF',
    fontSize: 10,
    fontWeight: '700',
  },
  divider: {
    height: 1,
    backgroundColor: '#F3F4F6',
    marginVertical: 6,
    marginHorizontal: 18,
  },
  footer: {
    padding: 16,
    borderTopWidth: 1,
    borderTopColor: '#F3F4F6',
    alignItems: 'center',
  },
  versionText: {
    fontSize: 12,
    color: '#9CA3AF',
  },
});

