import React from 'react';
import { View, Text, StyleSheet } from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export type BadgeVariant = 'success' | 'warning' | 'error' | 'info' | 'default';

export interface StatusBadgeProps {
  label: string;
  variant?: BadgeVariant;
  testID?: string;
}

export const StatusBadge: React.FC<StatusBadgeProps> = ({
  label,
  variant = 'default',
  testID = 'status-badge',
}) => {
  const { theme } = useTheme();

  const getColors = () => {
    switch (variant) {
      case 'success':
        return { bg: theme.colors.successBg, text: theme.colors.success };
      case 'warning':
        return { bg: theme.colors.warningBg, text: theme.colors.warning };
      case 'error':
        return { bg: theme.colors.errorBg, text: theme.colors.error };
      case 'info':
        return { bg: theme.colors.infoBg, text: theme.colors.info };
      default:
        return { bg: theme.colors.background, text: theme.colors.textMuted };
    }
  };

  const { bg, text } = getColors();

  return (
    <View
      testID={testID}
      style={[
        styles.badge,
        {
          backgroundColor: bg,
          borderRadius: theme.radius.sm,
          paddingHorizontal: theme.spacing.sm,
        },
      ]}
    >
      <Text style={[styles.badgeText, { color: text }]}>{label}</Text>
    </View>
  );
};

const styles = StyleSheet.create({
  badge: {
    paddingVertical: 3,
    alignSelf: 'flex-start',
  },
  badgeText: {
    fontSize: 12,
    fontWeight: '600',
  },
});
