import React from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  ViewStyle,
} from 'react-native';

export interface HorizontalStepItem {
  id: string;
  stepNumber?: number | string;
  label: string; // e.g. "Chọn sản phẩm", "Điền thông tin", "Xác nhận hồ sơ", "Phê duyệt chính thức", "Giải ngân"
  status?: 'active' | 'completed' | 'pending';
  onPress?: () => void;
}

export interface HorizontalStepTimelineProps {
  steps: HorizontalStepItem[];
  currentStepIndex?: number; // 0-indexed, default is determined by step status or index
  activeColor?: string; // Default Lotte Red #E5252A
  completedColor?: string; // Color for completed steps
  inactiveColor?: string; // Default #D1D5DB / #9CA3AF
  inactiveNodeBg?: string; // Default #B0B5BD / #D1D5DB
  containerStyle?: ViewStyle;
  testID?: string;
}

/**
 * Horizontal Step Process Timeline component matching Lotte LOS screenshot:
 * - Circular numbered badges (1, 2, 3, 4, 5)
 * - Connecting horizontal line between nodes
 * - Active step in vivid red (#E5252A) for both the badge and the label
 * - Subtle multi-line step titles centered below each badge
 * - Inactive/pending steps with gray background circle (#B0B5BD) and muted gray labels (#8B93A0)
 */
export const HorizontalStepTimeline: React.FC<HorizontalStepTimelineProps> = ({
  steps,
  currentStepIndex = 0,
  activeColor = '#E5252A',
  completedColor = '#E5252A',
  inactiveColor = '#D1D5DB',
  inactiveNodeBg = '#B0B5BD',
  containerStyle,
  testID = 'horizontal-step-timeline',
}) => {
  return (
    <View style={[styles.container, containerStyle]} testID={testID}>
      <View style={styles.stepsRow}>
        {steps.map((step, index) => {
          const isCurrent =
            step.status === 'active' ||
            (step.status === undefined && index === currentStepIndex);
          const isCompleted =
            step.status === 'completed' ||
            (step.status === undefined && index < currentStepIndex);
          const isLast = index === steps.length - 1;

          const badgeBg = isCurrent
            ? activeColor
            : isCompleted
            ? completedColor
            : inactiveNodeBg;
          const labelColor = isCurrent ? activeColor : '#8B93A0';
          const lineBg = isCompleted || (isCurrent && index === 0) ? activeColor : inactiveColor;

          const stepNumber = step.stepNumber !== undefined ? step.stepNumber : index + 1;

          return (
            <React.Fragment key={step.id || `step-${index}`}>
              {/* Step Node & Label Container */}
              <TouchableOpacity
                activeOpacity={step.onPress ? 0.7 : 1}
                onPress={step.onPress}
                style={styles.stepColumn}
                testID={`${testID}-step-${index}`}
              >
                {/* Node Circle */}
                <View
                  style={[styles.nodeCircle, { backgroundColor: badgeBg }]}
                  testID={`${testID}-node-${index}`}
                >
                  <Text style={styles.nodeText}>{stepNumber}</Text>
                </View>

                {/* Step Label */}
                <Text
                  style={[
                    styles.stepLabel,
                    { color: labelColor },
                    isCurrent && styles.stepLabelActive,
                  ]}
                  numberOfLines={2}
                  testID={`${testID}-label-${index}`}
                >
                  {step.label}
                </Text>
              </TouchableOpacity>

              {/* Connecting Line between steps */}
              {!isLast && (
                <View style={styles.lineContainer}>
                  <View
                    style={[
                      styles.connectingLine,
                      {
                        backgroundColor:
                          index < currentStepIndex ? activeColor : inactiveColor,
                      },
                    ]}
                    testID={`${testID}-line-${index}`}
                  />
                </View>
              )}
            </React.Fragment>
          );
        })}
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    paddingVertical: 12,
    paddingHorizontal: 8,
    backgroundColor: 'transparent',
  },
  stepsRow: {
    flexDirection: 'row',
    alignItems: 'flex-start',
    justifyContent: 'space-between',
    position: 'relative',
  },
  stepColumn: {
    alignItems: 'center',
    width: 64,
    zIndex: 2,
  },
  nodeCircle: {
    width: 28,
    height: 28,
    borderRadius: 14,
    alignItems: 'center',
    justifyContent: 'center',
    marginBottom: 8,
  },
  nodeText: {
    color: '#FFFFFF',
    fontSize: 13,
    fontWeight: '700',
  },
  stepLabel: {
    fontSize: 11,
    lineHeight: 15,
    textAlign: 'center',
    fontWeight: '400',
  },
  stepLabelActive: {
    fontWeight: '600',
  },
  lineContainer: {
    flex: 1,
    height: 28, // Matches nodeCircle height so line aligns exactly to center of circle
    justifyContent: 'center',
    paddingHorizontal: 2,
    zIndex: 1,
  },
  connectingLine: {
    height: 1.5,
    width: '100%',
  },
});
