import React, { useRef, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  PanResponder,
  ViewStyle,
  StyleProp,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';

export interface AppRangeSliderProps {
  label?: string;
  min?: number;
  max?: number;
  step?: number;
  value: number;
  onChange: (val: number) => void;
  unit?: string;
  disabled?: boolean;
  style?: StyleProp<ViewStyle>;
  testID?: string;
}

/**
 * Clean enterprise Range Slider with interactive touch dragging,
 * value tooltip, track fill, and boundary indicators.
 * Matches DBCS LOS bm-range-slider.vue.
 */
export const AppRangeSlider: React.FC<AppRangeSliderProps> = ({
  label,
  min = 0,
  max = 100,
  step = 1,
  value,
  onChange,
  unit = '',
  disabled = false,
  style,
  testID = 'app-range-slider',
}) => {
  const { theme } = useTheme();
  const trackRef = useRef<View>(null);
  const trackWidthRef = useRef(300);
  const trackPageXRef = useRef(0);
  const startRatioRef = useRef(0);

  // Keep latest props in refs to avoid stale closures in PanResponder
  const propsRef = useRef({ min, max, step, value, onChange, disabled });
  useEffect(() => {
    propsRef.current = { min, max, step, value, onChange, disabled };
  });

  // Percentage value between 0 and 1
  const clampedVal = Math.max(min, Math.min(max, value));
  const range = Math.max(1, max - min);
  const ratio = (clampedVal - min) / range;

  const measureTrackPosition = () => {
    if (trackRef.current && trackRef.current.measure) {
      trackRef.current.measure((_x, _y, width, _height, pageX) => {
        if (width > 0) {
          trackWidthRef.current = width;
        }
        if (typeof pageX === 'number') {
          trackPageXRef.current = pageX;
        }
      });
    }
  };

  const calculateSteppedValue = (rawRatio: number) => {
    const { min: currentMin, max: currentMax, step: currentStep } = propsRef.current;
    const currentRange = Math.max(1, currentMax - currentMin);
    const clampedRatio = Math.max(0, Math.min(1, rawRatio));
    const rawVal = currentMin + clampedRatio * currentRange;
    const steppedVal = Math.round((rawVal - currentMin) / currentStep) * currentStep + currentMin;
    return Math.max(currentMin, Math.min(currentMax, steppedVal));
  };

  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => !propsRef.current.disabled,
      onStartShouldSetPanResponderCapture: () => !propsRef.current.disabled,
      onMoveShouldSetPanResponder: () => !propsRef.current.disabled,
      onMoveShouldSetPanResponderCapture: () => !propsRef.current.disabled,
      onPanResponderTerminationRequest: () => false,
      onPanResponderGrant: (evt) => {
        measureTrackPosition();
        const { min: currentMin, max: currentMax, value: currentValue } = propsRef.current;
        const currentRange = Math.max(1, currentMax - currentMin);
        const currentRatio = (Math.max(currentMin, Math.min(currentMax, currentValue)) - currentMin) / currentRange;

        // Use absolute pageX coordinates if available; fall back to locationX
        const width = trackWidthRef.current;
        const pageX = evt.nativeEvent.pageX;
        let touchX = evt.nativeEvent.locationX;

        if (typeof pageX === 'number' && trackPageXRef.current > 0) {
          touchX = pageX - trackPageXRef.current;
        }

        const touchRatio = width > 0 ? Math.max(0, Math.min(1, touchX / width)) : currentRatio;
        startRatioRef.current = touchRatio;

        const newVal = calculateSteppedValue(touchRatio);
        propsRef.current.onChange(newVal);
      },
      onPanResponderMove: (evt, gestureState) => {
        const width = trackWidthRef.current;
        if (width <= 0) return;

        let newRatio: number;
        const pageX = evt.nativeEvent.pageX;

        if (typeof pageX === 'number' && trackPageXRef.current > 0) {
          newRatio = (pageX - trackPageXRef.current) / width;
        } else {
          // Continuous relative movement via gestureState.dx prevents jumps
          newRatio = startRatioRef.current + gestureState.dx / width;
        }

        const newVal = calculateSteppedValue(newRatio);
        propsRef.current.onChange(newVal);
      },
    })
  ).current;

  return (
    <View testID={testID} style={[styles.container, style]}>
      {/* Label and Value Header */}
      <View style={styles.headerRow}>
        {label ? <Text style={styles.label}>{label}</Text> : <View />}
        <Text style={[styles.valueText, { color: theme.colors.primary }]}>
          {clampedVal.toLocaleString()} {unit}
        </Text>
      </View>

      {/* Interactive Slider Track */}
      <View
        ref={trackRef}
        testID={`${testID}-touch-area`}
        style={styles.touchArea}
        onLayout={(e) => {
          trackWidthRef.current = e.nativeEvent.layout.width;
          measureTrackPosition();
        }}
        {...panResponder.panHandlers}
      >
        {/* Inactive Track */}
        <View style={styles.trackBackground} pointerEvents="none">
          {/* Active Filled Track */}
          <View
            style={[
              styles.trackActive,
              {
                width: `${ratio * 100}%`,
                backgroundColor: disabled ? '#9CA3AF' : theme.colors.primary,
              },
            ]}
          />
        </View>

        {/* Circular Slider Knob */}
        <View
          pointerEvents="none"
          style={[
            styles.knob,
            {
              left: `${ratio * 100}%`,
              borderColor: theme.colors.primary,
            },
          ]}
        />
      </View>

      {/* Min & Max Range Boundary Display */}
      <View style={styles.boundRow}>
        <Text style={styles.boundText}>{min.toLocaleString()} {unit}</Text>
        <Text style={styles.boundText}>{max.toLocaleString()} {unit}</Text>
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    width: '100%',
    paddingVertical: 6,
  },
  headerRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 8,
  },
  label: {
    fontSize: 14,
    fontWeight: '600',
    color: '#374151',
  },
  valueText: {
    fontSize: 15,
    fontWeight: '800',
  },
  touchArea: {
    height: 36,
    justifyContent: 'center',
    position: 'relative',
  },
  trackBackground: {
    height: 6,
    borderRadius: 3,
    backgroundColor: '#E5E7EB',
    overflow: 'hidden',
    width: '100%',
  },
  trackActive: {
    height: '100%',
    borderRadius: 3,
  },
  knob: {
    position: 'absolute',
    top: 6,
    width: 24,
    height: 24,
    borderRadius: 12,
    backgroundColor: '#FFFFFF',
    borderWidth: 3,
    marginLeft: -12,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.15,
    shadowRadius: 3,
    elevation: 3,
  },
  boundRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginTop: 4,
  },
  boundText: {
    fontSize: 11,
    color: '#9CA3AF',
  },
});

