import { Linking, Platform } from 'react-native';

export interface HotlineContact {
  type: 'DOMESTIC' | 'INTERNATIONAL' | 'TOLL_FREE' | 'VIP';
  label: string;
  phoneNumber: string;
  operatingHours: string;
  isAvailable247?: boolean;
}

export interface BankBranchOffice {
  id: string;
  branchName: string;
  address: string;
  phoneNumber: string;
  email?: string;
  workingHours: string;
  isHeadOffice?: boolean;
  coordinates?: {
    latitude: number;
    longitude: number;
  };
}

/**
 * ContactSupportUtil: Utility for initiating direct phone dials, email inquiries,
 * checking 24/7 hotline operational availability, and branch contact directory.
 * Matches ML-002, GL-18, and SV-02 specifications from Lotte Finance Digital Channels.
 */
export class ContactSupportUtil {
  public static readonly DEFAULT_HOTLINES: HotlineContact[] = [
    {
      type: 'DOMESTIC',
      label: 'Khách hàng trong nước (Domestic Hotline)',
      phoneNumber: '1900 6866',
      operatingHours: '24/7 Daily including Holidays',
      isAvailable247: true,
    },
    {
      type: 'INTERNATIONAL',
      label: 'Khách hàng quốc tế (International Hotline)',
      phoneNumber: '+84 247 302 0202',
      operatingHours: '24/7 Daily',
      isAvailable247: true,
    },
  ];

  public static readonly HEAD_OFFICE: BankBranchOffice = {
    id: 'HEAD_OFFICE_LOTTE',
    branchName: 'LOTTE Finance Head Office (Trụ sở chính)',
    address: 'Tầng 12A, Tháp Tây, Tòa nhà LOTTE Center Hà Nội, 54 Liễu Giai, Ba Đình, Hà Nội',
    phoneNumber: '1900 6866',
    email: 'cskh@lottefinance.vn',
    workingHours: '08:30 - 17:30 (Thứ 2 - Thứ 6)',
    isHeadOffice: true,
    coordinates: {
      latitude: 21.0319,
      longitude: 105.8132,
    },
  };

  /**
   * Sanitizes phone number to tel: URL scheme.
   * e.g. "1900 6866" -> "tel:19006866", "+84 247 302 0202" -> "tel:+842473020202"
   */
  public static sanitizePhoneDialUrl(phoneNumber: string): string {
    if (!phoneNumber) return '';
    const clean = phoneNumber.replace(/[^0-9+]/g, '');
    return `tel:${clean}`;
  }

  /**
   * Initiates direct native phone dialer with provided telephone number.
   */
  public static async makePhoneCall(phoneNumber: string): Promise<boolean> {
    const url = this.sanitizePhoneDialUrl(phoneNumber);
    if (!url) return false;

    try {
      const supported = await Linking.canOpenURL(url);
      if (supported) {
        await Linking.openURL(url);
        return true;
      }
      return false;
    } catch {
      return false;
    }
  }

  /**
   * Opens default email client with support recipient and subject line.
   */
  public static async sendSupportEmail(
    email: string = 'cskh@lottefinance.vn',
    subject: string = 'Hỗ trợ dịch vụ vay LOTTE Finance'
  ): Promise<boolean> {
    const encodedSubject = encodeURIComponent(subject);
    const url = `mailto:${email}?subject=${encodedSubject}`;

    try {
      const supported = await Linking.canOpenURL(url);
      if (supported) {
        await Linking.openURL(url);
        return true;
      }
      return false;
    } catch {
      return false;
    }
  }

  /**
   * Checks if an inquiry or branch is currently open based on operating hours.
   */
  public static isHotlineOperating(hotline: HotlineContact, now: Date = new Date()): boolean {
    if (hotline.isAvailable247) return true;
    const hour = now.getHours();
    // Standard business hours: 8:00 to 18:00
    return hour >= 8 && hour < 18;
  }
}

