import React, { useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ScrollView,
  Platform,
} from 'react-native';
import { useTheme } from '@mfe/core/theme/ThemeContext';
import { ClockIcon } from '@mfe/assets/icons/PickerIcons';
import { PresentationMode } from './DatePickerField';
import { AppAlertModal } from '../../modals/AppAlertModal';
import { AppBottomSheet } from '../../modals/AppBottomSheet';

export interface TimePickerFieldProps {
  label: string;
  value: string; // HH:mm AM/PM
  onChangeTime: (timeString: string) => void;
  presentation?: PresentationMode; // 'alert' | 'bottomsheet'
  error?: string;
  testID?: string;
}

export const TimePickerField: React.FC<TimePickerFieldProps> = ({
  label,
  value,
  onChangeTime,
  presentation = 'alert',
  error,
  testID = 'time-picker-field',
}) => {
  const { theme } = useTheme();
  const [modalVisible, setModalVisible] = useState(false);

  const [selectedHour, setSelectedHour] = useState(9);
  const [selectedMinute, setSelectedMinute] = useState(0);
  const [period, setPeriod] = useState<'AM' | 'PM'>('AM');

  const hours = Array.from({ length: 12 }, (_, i) => i + 1);
  const minutes = [0, 5, 10, 15, 20, 25, 30, 35, 40, 45, 50, 55];

  const handleConfirm = () => {
    const h = String(selectedHour).padStart(2, '0');
    const m = String(selectedMinute).padStart(2, '0');
    onChangeTime(`${h}:${m} ${period}`);
    setModalVisible(false);
  };

  const isBlur = theme.modal?.alertBackdropBlur || theme.modal?.bottomSheetBackdropBlur;

  const timePickerContent = (
    <View testID={`${testID}-modal-content`}>
      <Text style={styles.modalTitle}>Choose Time</Text>

      {/* AM / PM Segment */}
      <View style={styles.periodRow}>
        {(['AM', 'PM'] as const).map((p) => (
          <TouchableOpacity
            key={p}
            testID={`${testID}-period-${p}`}
            style={[
              styles.periodBtn,
              period === p && {
                backgroundColor: theme.colors.primary,
                borderRadius: theme.radius.sm,
              },
            ]}
            onPress={() => setPeriod(p)}
          >
            <Text
              style={[
                styles.periodText,
                period === p && { color: '#FFFFFF', fontWeight: '700' },
              ]}
            >
              {p}
            </Text>
          </TouchableOpacity>
        ))}
      </View>

      {/* Hours and Minutes Grid */}
      <View style={styles.selectorsRow}>
        {/* Hours Column */}
        <View style={styles.column}>
          <Text style={styles.columnHeader}>Hour</Text>
          <ScrollView style={styles.pickerScroll} nestedScrollEnabled>
            {hours.map((h) => {
              const isSelected = selectedHour === h;
              return (
                <TouchableOpacity
                  key={`hour-${h}`}
                  testID={`${testID}-hour-${h}`}
                  style={[
                    styles.timeOption,
                    isSelected && {
                      backgroundColor: theme.colors.primaryLight,
                      borderColor: theme.colors.primary,
                      borderRadius: theme.radius.sm,
                    },
                  ]}
                  onPress={() => setSelectedHour(h)}
                >
                  <Text
                    style={[
                      styles.timeOptionText,
                      isSelected && {
                        color: theme.colors.primary,
                        fontWeight: '700',
                      },
                    ]}
                  >
                    {String(h).padStart(2, '0')}
                  </Text>
                </TouchableOpacity>
              );
            })}
          </ScrollView>
        </View>

        {/* Minutes Column */}
        <View style={styles.column}>
          <Text style={styles.columnHeader}>Minute</Text>
          <ScrollView style={styles.pickerScroll} nestedScrollEnabled>
            {minutes.map((m) => {
              const isSelected = selectedMinute === m;
              return (
                <TouchableOpacity
                  key={`min-${m}`}
                  testID={`${testID}-min-${m}`}
                  style={[
                    styles.timeOption,
                    isSelected && {
                      backgroundColor: theme.colors.primaryLight,
                      borderColor: theme.colors.primary,
                      borderRadius: theme.radius.sm,
                    },
                  ]}
                  onPress={() => setSelectedMinute(m)}
                >
                  <Text
                    style={[
                      styles.timeOptionText,
                      isSelected && {
                        color: theme.colors.primary,
                        fontWeight: '700',
                      },
                    ]}
                  >
                    {String(m).padStart(2, '0')}
                  </Text>
                </TouchableOpacity>
              );
            })}
          </ScrollView>
        </View>
      </View>

      {/* Actions */}
      <View style={styles.actionRow}>
        <TouchableOpacity
          style={[styles.btn, styles.cancelBtn]}
          onPress={() => setModalVisible(false)}
        >
          <Text style={styles.cancelBtnText}>Cancel</Text>
        </TouchableOpacity>
        <TouchableOpacity
          testID={`${testID}-confirm-btn`}
          style={[
            styles.btn,
            { backgroundColor: theme.colors.primary, borderRadius: theme.radius.sm },
          ]}
          onPress={handleConfirm}
        >
          <Text style={styles.confirmBtnText}>Set Time</Text>
        </TouchableOpacity>
      </View>
    </View>
  );

  return (
    <View testID={testID} style={styles.container}>
      <Text style={styles.label}>{label}</Text>

      <View style={[styles.inputGroup, error ? styles.inputError : null]}>
        <Text style={[styles.valueText, !value && styles.placeholderText]}>
          {value || 'Select Time (HH:mm AM/PM)'}
        </Text>

        <TouchableOpacity
          testID={`${testID}-trigger`}
          style={styles.timeBtn}
          onPress={() => setModalVisible(true)}
          activeOpacity={0.7}
        >
          <ClockIcon size={20} color={theme.colors.primary} />
        </TouchableOpacity>
      </View>

      {error ? <Text style={styles.errorText}>{error}</Text> : null}

      {/* Presentation wrapped in either AppBottomSheet or AppAlertModal */}
      {presentation === 'bottomsheet' ? (
        <AppBottomSheet
          visible={modalVisible}
          showHeader={false}
          onClose={() => setModalVisible(false)}
          testID={`${testID}-bottom-sheet`}
        >
          {timePickerContent}
        </AppBottomSheet>
      ) : (
        <AppAlertModal
          visible={modalVisible}
          showHeader={false}
          maxWidth={340}
          onClose={() => setModalVisible(false)}
          testID={`${testID}-alert-modal`}
        >
          {timePickerContent}
        </AppAlertModal>
      )}
    </View>
  );
};

