import React from 'react';
import {
  View,
  Text,
  StyleSheet,
  ViewStyle,
  TouchableOpacity,
} from 'react-native';

export type CheckItemStatus = 'pass' | 'checking' | 'waiting' | 'failed' | 'pending';

export interface VerificationCheckItem {
  id: string;
  title: string;
  status: CheckItemStatus;
  statusText?: string;
  note?: string;
  onPress?: () => void;
}

export interface VerificationChecklistGroup {
  id: string;
  headerTitle: string;
  headerIcon?: React.ReactNode;
  items: VerificationCheckItem[];
}

export interface VerificationTimelineProps {
  groups: VerificationChecklistGroup[];
  headerTitle?: string;
  onBackPress?: () => void;
  style?: ViewStyle;
  testID?: string;
}

/**
 * Verification Timeline component matching the screenshot:
 * "Kiểm tra thông tin khách hàng"
 * Displays multi-section verification audits (e.g. Thông tin khách hàng, Thông tin người đồng vay)
 * with a blue person icon header, continuous thin vertical connecting lines,
 * green filled check circle for 'pass', light-blue dots for 'waiting' / 'checking',
 * and localized status labels (Pass, Đang chờ, Đang kiểm tra...).
 */
export const VerificationTimeline: React.FC<VerificationTimelineProps> = ({
  groups,
  headerTitle,
  onBackPress,
  style,
  testID = 'verification-timeline',
}) => {
  const renderStatusNode = (status: CheckItemStatus) => {
    switch (status) {
      case 'pass':
        return (
          <View testID="status-node-pass" style={styles.passNodeCircle}>
            <Text style={styles.passCheckmark}>✓</Text>
          </View>
        );
      case 'failed':
        return (
          <View testID="status-node-failed" style={styles.failedNodeCircle}>
            <Text style={styles.failedCrossmark}>✕</Text>
          </View>
        );
      case 'checking':
        return (
          <View testID="status-node-checking" style={styles.checkingNodeCircle}>
            <View style={styles.checkingInnerDot} />
          </View>
        );
      case 'waiting':
      case 'pending':
      default:
        return (
          <View testID="status-node-waiting" style={styles.waitingNodeCircle} />
        );
    }
  };

  const renderStatusText = (item: VerificationCheckItem) => {
    if (item.statusText) {
      return (
        <Text
          style={[
            styles.statusLabelText,
            item.status === 'pass' && styles.statusPassText,
            item.status === 'checking' && styles.statusCheckingText,
            item.status === 'failed' && styles.statusFailedText,
            (item.status === 'waiting' || item.status === 'pending') && styles.statusWaitingText,
          ]}
        >
          {item.statusText}
        </Text>
      );
    }

    switch (item.status) {
      case 'pass':
        return <Text style={[styles.statusLabelText, styles.statusPassText]}>Pass</Text>;
      case 'checking':
        return <Text style={[styles.statusLabelText, styles.statusCheckingText]}>Đang kiểm tra...</Text>;
      case 'failed':
        return <Text style={[styles.statusLabelText, styles.statusFailedText]}>Không đạt</Text>;
      case 'waiting':
      default:
        return <Text style={[styles.statusLabelText, styles.statusWaitingText]}>Đang chờ</Text>;
    }
  };

  return (
    <View testID={testID} style={[styles.container, style]}>
      {/* Optional Top Screen Header */}
      {headerTitle ? (
        <View style={styles.topHeader}>
          {onBackPress ? (
            <TouchableOpacity
              testID={`${testID}-back-btn`}
              style={styles.backBtn}
              onPress={onBackPress}
              hitSlop={{ top: 12, bottom: 12, left: 12, right: 12 }}
            >
              <Text style={styles.backChevron}>‹</Text>
            </TouchableOpacity>
          ) : null}
          <Text testID={`${testID}-header-title`} style={styles.topHeaderTitle}>
            {headerTitle}
          </Text>
        </View>
      ) : null}

      {/* Checklist Groups */}
      {groups.map((group, groupIndex) => {
        const isLastGroup = groupIndex === groups.length - 1;

        return (
          <View
            key={group.id}
            testID={`${testID}-group-${group.id}`}
            style={[styles.groupCard, !isLastGroup && styles.groupCardBorder]}
          >
            {/* Group Header with Circle Person Icon */}
            <View style={styles.groupHeaderRow}>
              {group.headerIcon ? (
                group.headerIcon
              ) : (
                <View style={styles.personIconCircle}>
                  <Text style={styles.personGlyph}>👤</Text>
                </View>
              )}
              <Text style={styles.groupHeaderTitle}>{group.headerTitle}</Text>
            </View>

            {/* Checklist Items */}
            <View style={styles.itemsList}>
              {group.items.map((item, itemIndex) => {
                const isLastItem = itemIndex === group.items.length - 1;

                return (
                  <TouchableOpacity
                    key={item.id}
                    testID={`${testID}-item-${item.id}`}
                    style={styles.itemRow}
                    activeOpacity={item.onPress ? 0.7 : 1}
                    onPress={item.onPress}
                    disabled={!item.onPress}
                  >
                    {/* Left Node & Connector Column */}
                    <View style={styles.nodeColumn}>
                      {renderStatusNode(item.status)}
                      {!isLastItem ? <View style={styles.connectorLine} /> : null}
                    </View>

                    {/* Right Content Column */}
                    <View style={[styles.contentColumn, !isLastItem && styles.contentSpacing]}>
                      <Text style={styles.itemTitle}>{item.title}</Text>
                      {renderStatusText(item)}
                      {item.note ? <Text style={styles.itemNote}>{item.note}</Text> : null}
                    </View>
                  </TouchableOpacity>
                );
              })}
            </View>
          </View>
        );
      })}
    </View>
  );
};

