import React, { useEffect } from 'react';
import { View, StyleSheet, Alert } from 'react-native';
import { NavigationContainer } from '@react-navigation/native';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import { ThemeProvider } from '@mfe/theme';
import { I18nProvider } from '@mfe/core/i18n';
import { GlobalModalHost } from '@mfe/ui-components/modals';
import { NotificationNavigator } from './navigation/NotificationNavigator';

export const NotificationStandaloneApp: React.FC = () => {
  useEffect(() => {
    console.log('🚀 [DevMode] remote-notification running in Isolated Standalone Mode');
  }, []);

  return (
    <SafeAreaProvider>
      <ThemeProvider>
        <I18nProvider initialLanguage="en">
          <View style={styles.container}>
            <NavigationContainer>
              <NotificationNavigator
                onBackToDashboard={() => {
                  Alert.alert(
                    'Isolated Dev Mode',
                    'Back to Dashboard pressed. In full application mode, this navigates back to Dashboard.'
                  );
                }}
              />
            </NavigationContainer>
          </View>
          <GlobalModalHost />
        </I18nProvider>
      </ThemeProvider>
    </SafeAreaProvider>
  );
};

export default NotificationStandaloneApp;

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#FFFFFF',
    height: '100%',
    width: '100%',
  },
});
