import React from 'react';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { NotificationStackParamList } from './NotificationNavigationTypes';
import { NotificationListScreen } from '../views/NotificationListScreen';
import { NotificationDetailScreen } from '../views/NotificationDetailScreen';

const Stack = createNativeStackNavigator<NotificationStackParamList>();

export interface NotificationNavigatorProps {
  onBackToDashboard: () => void;
}

export const NotificationNavigator: React.FC<NotificationNavigatorProps> = ({
  onBackToDashboard,
}) => {
  return (
    <Stack.Navigator
      initialRouteName="NotificationList"
      screenOptions={{
        headerShown: false,
        animation: 'default',
        gestureEnabled: true,
        fullScreenGestureEnabled: false,
      }}
    >
      <Stack.Screen name="NotificationList">
        {({ navigation }) => (
          <NotificationListScreen
            onBack={onBackToDashboard}
            onSelectNotification={(item) =>
              navigation.navigate('NotificationDetail', { notification: item })
            }
          />
        )}
      </Stack.Screen>

      <Stack.Screen name="NotificationDetail">
        {({ navigation, route }) => (
          <NotificationDetailScreen
            notification={route.params.notification}
            onBack={() => navigation.goBack()}
          />
        )}
      </Stack.Screen>
    </Stack.Navigator>
  );
};

