export interface LoanSimulationParams {
  principal: number;
  annualInterestRate: number; // e.g. 12 for 12%
  tenureMonths: number;
  monthlyFeePercent?: number; // e.g. 0.5 for 0.5%
}

export interface LoanSimulationResult {
  monthlyPayment: number;
  totalInterest: number;
  totalPayment: number;
  principal: number;
  tenureMonths: number;
}

export interface AmortizationScheduleRow {
  month: number;
  openingBalance: number;
  payment: number;
  principalPaid: number;
  interestPaid: number;
  closingBalance: number;
}

export class LoanCalculator {
  /**
   * Round to specified decimal digits (default 2).
   */
  public static round(num: number | string, decimal: number = 2): number {
    const value = Number(num);
    if (!Number.isFinite(value)) {
      return 0;
    }
    const factor = Math.pow(10, decimal);
    return Math.round(value * factor) / factor;
  }

  /**
   * Calculates PMT (Periodic Monthly Payment) using banking formula:
   * PMT = [P * r * (1 + r)^n] / [(1 + r)^n - 1]
   */
  public static calculatePMT(
    principal: number,
    annualInterestRate: number,
    tenureMonths: number,
    monthlyFeePercent: number = 0
  ): number {
    if (principal <= 0 || tenureMonths <= 0) {
      return 0;
    }

    let monthlyRate = annualInterestRate / 100 / 12;

    if (monthlyFeePercent > 0) {
      monthlyRate += monthlyFeePercent / 100;
    }

    if (monthlyRate === 0) {
      return this.round(principal / tenureMonths);
    }

    const pmtFactor = Math.pow(1 + monthlyRate, tenureMonths);
    if (pmtFactor - 1 <= 0) {
      return 0;
    }

    const monthlyPayment = (principal * monthlyRate * pmtFactor) / (pmtFactor - 1);
    return this.round(monthlyPayment);
  }

  /**
   * Calculates monthly interest rate amount for a given principal.
   */
  public static calculateMonthlyInterest(amount: number, annualInterestRate: number): number {
    const monthlyRate = annualInterestRate / 100 / 12;
    return this.round(amount * monthlyRate);
  }

  /**
   * Full loan simulation calculation.
   */
  public static simulateLoan(params: LoanSimulationParams): LoanSimulationResult {
    const monthlyPayment = this.calculatePMT(
      params.principal,
      params.annualInterestRate,
      params.tenureMonths,
      params.monthlyFeePercent || 0
    );

    const totalPayment = this.round(monthlyPayment * params.tenureMonths);
    const totalInterest = this.round(Math.max(0, totalPayment - params.principal));

    return {
      monthlyPayment,
      totalInterest,
      totalPayment,
      principal: params.principal,
      tenureMonths: params.tenureMonths,
    };
  }

  /**
   * Generates complete monthly amortization breakdown.
   */
  public static generateAmortizationSchedule(
    principal: number,
    annualInterestRate: number,
    tenureMonths: number
  ): AmortizationScheduleRow[] {
    const schedule: AmortizationScheduleRow[] = [];
    const monthlyRate = annualInterestRate / 100 / 12;
    const monthlyPayment = this.calculatePMT(principal, annualInterestRate, tenureMonths);

    let remainingBalance = principal;

    for (let month = 1; month <= tenureMonths; month++) {
      const openingBalance = remainingBalance;
      const interestPaid = this.round(openingBalance * monthlyRate);
      let principalPaid = this.round(monthlyPayment - interestPaid);

      if (month === tenureMonths || principalPaid > remainingBalance) {
        principalPaid = openingBalance;
      }

      const closingBalance = Math.max(0, this.round(openingBalance - principalPaid));
      remainingBalance = closingBalance;

      schedule.push({
        month,
        openingBalance,
        payment: monthlyPayment,
        principalPaid,
        interestPaid,
        closingBalance,
      });

      if (remainingBalance <= 0) {
        break;
      }
    }

    return schedule;
  }

  /**
   * Calculates Debt Service Coverage Ratio (DSCR):
   * DSCR = Net Operating Income (or Net Income) / Total Debt Service
   */
  public static calculateDSCR(netIncome: number, totalMonthlyDebtObligations: number): number {
    if (totalMonthlyDebtObligations <= 0) {
      return netIncome > 0 ? 999.99 : 0;
    }
    return this.round(netIncome / totalMonthlyDebtObligations);
  }

  /**
   * Calculates Debt-to-Income (DTI) percentage:
   * DTI = (Total Monthly Debt / Gross Monthly Income) * 100
   */
  public static calculateDTI(totalMonthlyDebt: number, grossMonthlyIncome: number): number {
    if (grossMonthlyIncome <= 0) {
      return 100;
    }
    return this.round((totalMonthlyDebt / grossMonthlyIncome) * 100);
  }

  /**
   * Calculates Loan-to-Value (LTV) percentage:
   * LTV = (Loan Amount / Collateral Appraisal Value) * 100
   */
  public static calculateLTV(loanAmount: number, collateralValue: number): number {
    if (collateralValue <= 0) {
      return 100;
    }
    return this.round((loanAmount / collateralValue) * 100);
  }
}

