import { useState, useEffect, useCallback, useMemo } from 'react';
import {
  ApprovalItemDTO,
  ApprovalStatus,
  ApprovalMenuType,
  ApprovalTabType,
} from '../models/ApprovalModel';
import { IApprovalService, ApprovalService } from '../services/ApprovalService';

export interface UseApprovalViewModelProps {
  approvalService?: IApprovalService;
  useMock?: boolean;
}

export function useApprovalViewModel({
  approvalService = ApprovalService.getInstance(),
  useMock = true,
}: UseApprovalViewModelProps = {}) {
  // Tabs & Filters
  const [tabType, setTabType] = useState<ApprovalTabType>('loan');
  const [menuType, setMenuType] = useState<ApprovalMenuType>('My Request');
  const [statusFilter, setStatusFilter] = useState<ApprovalStatus | undefined>(undefined);
  const [dateRangeStr, setDateRangeStr] = useState<string>('15 តុលា, 2026 ~ 14 វិច្ឆិកា, 2026');
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [isInquiryOpen, setIsInquiryOpen] = useState<boolean>(true);

  // Modal Sheet Visibility
  const [isMenuModalVisible, setIsMenuModalVisible] = useState<boolean>(false);
  const [isStatusModalVisible, setIsStatusModalVisible] = useState<boolean>(false);
  const [isDateModalVisible, setIsDateModalVisible] = useState<boolean>(false);

  // Selected Detail Item (Screen navigation between List and Detail view)
  const [selectedItem, setSelectedItem] = useState<ApprovalItemDTO | null>(null);
  const [detailSubTab, setDetailSubTab] = useState<'info' | 'line'>('info');

  // List Data & Loading States
  const [items, setItems] = useState<ApprovalItemDTO[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);

  // Fetch items based on active criteria
  const loadApprovals = useCallback(async () => {
    setIsLoading(true);
    try {
      const data = await approvalService.getApprovalList(
        {
          tabType,
          menuType,
          status: statusFilter,
          dateRangeStr,
          searchQuery,
        },
        useMock
      );
      setItems(data);
    } finally {
      setIsLoading(false);
    }
  }, [approvalService, tabType, menuType, statusFilter, dateRangeStr, searchQuery, useMock]);

  useEffect(() => {
    loadApprovals();
  }, [loadApprovals]);

  const handleSearch = useCallback(() => {
    loadApprovals();
  }, [loadApprovals]);

  const handleClearDateRange = useCallback(() => {
    setDateRangeStr('');
  }, []);

  const handleSelectMenuOption = useCallback((option: ApprovalMenuType) => {
    setMenuType(option);
    setIsMenuModalVisible(false);
  }, []);

  const handleSelectStatusOption = useCallback((status: ApprovalStatus | 'All') => {
    if (status === 'All') {
      setStatusFilter(undefined);
    } else {
      setStatusFilter(status);
    }
    setIsStatusModalVisible(false);
  }, []);

  const handleApplyDateRange = useCallback((formattedRange: string) => {
    setDateRangeStr(formattedRange);
    setIsDateModalVisible(false);
  }, []);

  const handleOpenDetail = useCallback((item: ApprovalItemDTO) => {
    setSelectedItem(item);
    setDetailSubTab('info');
  }, []);

  const handleCloseDetail = useCallback(() => {
    setSelectedItem(null);
  }, []);

  const handleCancelModify = useCallback(
    async (stepId: string, remark?: string) => {
      if (!selectedItem) return;
      const success = await approvalService.cancelModify(selectedItem.id, stepId, remark, useMock);
      if (success) {
        // Refresh detail item
        const updated = await approvalService.getApprovalDetail(selectedItem.id, useMock);
        if (updated) {
          setSelectedItem(updated);
        }
        loadApprovals();
      }
    },
    [approvalService, selectedItem, loadApprovals, useMock]
  );

  return {
    tabType,
    setTabType,
    menuType,
    statusFilter,
    dateRangeStr,
    searchQuery,
    setSearchQuery,
    isInquiryOpen,
    setIsInquiryOpen,
    isMenuModalVisible,
    setIsMenuModalVisible,
    isStatusModalVisible,
    setIsStatusModalVisible,
    isDateModalVisible,
    setIsDateModalVisible,
    items,
    isLoading,
    selectedItem,
    detailSubTab,
    setDetailSubTab,
    handleSearch,
    handleClearDateRange,
    handleSelectMenuOption,
    handleSelectStatusOption,
    handleApplyDateRange,
    handleOpenDetail,
    handleCloseDetail,
    handleCancelModify,
  };
}
